window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":38000,"as":"一项研究指出，过去三十年中，快速发展经济体的混凝土需求推动了资源使用的增加。尽管在生产工艺上有所改进，但这些改进仅能略微减少资源负担，难以在维持人类发展的同时显著降低因混凝土消耗带来的行星边界压力。","scd":null,"kp":["[混凝土资源脱钩现状]: 生产工艺改进仅能边缘性地减轻环境资源负担，需求增长持续推高资源消耗"]},{"i":38001,"as":"研究揭示了溶剂化离子的溶剂交换动力学与界面电化学反应动力学存在内在耦合关系。基于此发现设计的电解质，通过快速的溶剂化重构加速了界面电荷转移，成功实现了锂离子电池的快速充电和低温环境下的稳定运行。","scd":null,"kp":["[电解液设计机制]: 溶剂化离子的溶剂交换动力学与界面电化学反应动力学存在内在耦合","[快溶剂化重构电解液]: 实现锂离子电池的快速充电和低温运行"]},{"i":38002,"as":"小型高山湖泊正迅速成为全球高山地区冰冻圈风险的关键组成部分。这些在退化和不稳定地形中加速形成的小型湖泊，尽管体积不大，但已引发破坏性的溃决洪水，对适应能力有限的偏远社区造成了严重且不成比例的影响。目前监测和政策框架中仍存在盲点。","scd":null,"kp":["[高山湖区冰冻圈风险]: 不稳定冰消地形中加速形成的小型高山湖泊引发破坏性溃决洪水，存在监测盲点"]},{"i":38003,"as":"研究利用冷冻电镜技术，解析了构巢曲霉高亲和力嘌呤转运蛋白UapA的无底物和结合底物构象的高分辨率结构。结构揭示了水分子和脂质在底物结合、特异性、转运蛋白二聚化和活性中的作用。研究发现UapA的N端尾部具有变构调节功能，调控转运过程。","scd":null,"kp":[]},{"i":38004,"as":"研究发现乳糜泻（CeD）中HLA-DQ2.5基因的致病风险部分源于对初始CD4+ T细胞受体（TCR）库的塑造。通过对103名CeD受试者和103名对照者进行测序分析，证实HLA和TR位点的遗传变异通过改变初始CD4+ TCR库的基因使用频率，赋予了对该疾病的易感性。","scd":null,"kp":[]},{"i":38005,"as":"针对法医武器鉴定近期报告的高达20%的误报率，研究批判性地审查了法医熟练度测试的设计与结果。研究指出现有测试在测试项目设计、评分规则以及其对真实世界推断的有效性上存在多重局限，强调需重新评估此类测试在证明模式比对方法可靠性方面的科学价值。","scd":null,"kp":[]},{"i":38006,"as":"论文研究了接触流形中的实心环面，给出了明确计算结型接触宽度的标准，并证明了多种结型中存在大量不可增厚环面。这些环面对勒让德和横截结理论至关重要。此前不可增厚环面仅在S3的迭代环面结中被观察到，而本研究证实它们在其他流形中普遍存在。","scd":null,"kp":[]},{"i":38007,"as":"本文提出了一种多尺度框架，将线性化学-孔隙弹性理论扩展至描述纳米多孔固体与受限流体对机械波激发的耦合响应。该框架从原子模拟中提取出有效孔隙力学参数（如弹性、应力化学耦合张量、化学模量及流体迁移率张量），并将这些参数嵌入到机械波传播的连续介质模型中，解决了经典连续介质假设在分子尺度上失效的难题。","scd":null,"kp":["[流体饱和纳米多孔介质波传播]: 建立将分子力学升级为连续介质描述的多尺度框架","弹性与应力-化学耦合参数[纳米受限流体与固体耦合]: 基于线性化学-多孔弹性理论推导"]},{"i":38008,"as":"本文引入了适应度景观设计（FLD）的基础原理，旨在以定量精度定制生物物理适应度景观的结构峰谷，从而实现对长期进化结果的稳健控制。FLD算法利用化学衍生的生物物理适应度模型的随机优化，能够持续发现最优抗体集合，迫使目标蛋白向特定方向进化。","scd":null,"kp":[]},{"i":38009,"as":"本文利用Col1a1-YFP报告小鼠在两种疾病模型（视网膜损伤修复模型和视网膜下纤维化疾病模型）中实时无创地体内成像胶原蛋白的产生。研究构建了产生胶原蛋白的细胞图谱，揭示了早期损伤与纤维化视网膜下疾病中成纤维细胞截然不同的命运，明确了导致视网膜下纤维化的细胞来源与异质性。","scd":null,"kp":[]},{"i":38010,"as":"石墨负极的快充性能常受界面极化导致的SEI生长和锂沉积限制。虽然硼酸盐添加剂能提升倍率性能，但常产生高阻抗界面。本文通过一步非水合法成成了无水双（儿茶酚）硼酸锂（LiBCB）添加剂，消除了结晶水的影响。该添加剂能改善锂离子电池的界面化学，克服了传统LiBOB产气和界面阻抗大的问题。","scd":null,"kp":["[石墨负极快充限制]: 界面极化导致SEI生长和析锂","硼酸盐添加剂(如LiBOB)[商用锂电池]: 提升倍率性能但会生成厚且高阻抗的界面层并产气"]},{"i":38011,"as":"本文设计了一种Au24Cd/CZ9-700双位点催化剂用于电化学耦合CO2和NO3-合成尿素。传统催化剂存在反应物非选择性吸附的问题，阻碍了C-N键的形成。该双位点催化剂能够实现关键C和N中间体的空间对齐相互作用，其尿素峰值产率达到668.60 µg h-1，有效提升了合成效率并同步解决了废水脱氮问题。","scd":null,"kp":["[CO2与硝酸根电化学共还原]: 缓解废水脱氮并实现可持续尿素合成","传统催化剂[电合成尿素效率阻碍]: 反应物非选择性吸附阻碍关键中间体的空间定向相互作用"]},{"i":38012,"as":"水系锌离子电池中锌金属负极的析氢等水致副反应和缓慢的离子迁移动力学严重降低了库仑效率和寿命。本文在锌负极与电解液之间引入了由三聚氰胺（MA）和间苯二甲酸（IPA）自组装而成的有机共晶体。该超分子结构通过广泛的氢键网络捕获并隔离活性水分子，其含有的氨基、羧基等亲锌位点增强了离子传输，从而稳定了锌负极。","scd":null,"kp":["[水系锌离子电池锌负极]: 水引发副反应及离子迁移动力学缓慢降低库仑效率与寿命","有机共晶界面层[三聚氰胺与间苯二甲酸自组装]: 形成具有广泛氢键网络的超分子结构以稳定锌负极"]},{"i":38013,"as":"本文建立了一种自下而上、按组件解析的方法论，结合差示扫描量热法/热重分析（DSC/TGA）、逸出气体分析（EGA）和原位XRD，评估NMC811-石墨微型电池的热安全性和稳定性。该方法直接关联了不同配置下的材料分解路径、能量释放和气体逸出，克服了部分配置差异和微型电池架构限制带来的解释困难。","scd":null,"kp":["[NMC811-石墨微型电池热安全与气体析出]: 建立自下而上且按组件解析的热化学表征方法"]},{"i":38014,"as":"LHAASO合作组的研究表明，袭击地球的太阳风暴（行星际日冕物质抛射）减少了入射的高能宇宙射线数量。观测到了由行星际日冕物质抛射引起的万亿电子伏特（TeV）宇宙射线的瞬态大尺度各向异性，这提供了一种测量太阳活动的新方法。","scd":null,"kp":["[高能宇宙射线探测]: 行星际日冕物质抛射等太阳风暴可减少入射宇宙射线并作为测量太阳活动的新方法"]},{"i":38015,"as":"本文提出了一种针对开放量子系统的统一多体微扰理论，将耗散、电子关联和外部驱动置于同等重要的位置进行处理。利用Keldysh-Lindblad形式主义，引入了图解化方法处理代表准粒子流和涨落的耗散相互作用线，为研究驱动的耗散系统提供了新理论框架。","scd":null,"kp":["[开放量子系统耗散与涨落]: 提出基于Keldysh-Lindblad形式论统一处理耗散、关联与外部驱动的多体微扰理论"]},{"i":38016,"as":"本文研究了一维波导中由弱相干场共振驱动的N个全同两能级原子的散射场。当原子间距等于驱动波长时，增加原子数量会抑制光的透射，同时显著增强光子聚束效应（光子群聚）。透射率的下降表明原子系统能够产生强烈的非线性光学响应。","scd":null,"kp":["[一维波导中的原子共振散射]: 随着与驱动波长等间距分布的原子数量增加，透射率受抑制而光子聚束效应增强"]},{"i":38017,"as":"本文研究了层状共晶固相在熔化过程中出现的丰富多样的图样形成。研究发现，在两相共晶合金熔化时，其微观结构会自发演化出独特的物理形态和图案，这对理解材料相变过程中的微观动力学具有重要意义。","scd":null,"kp":["[层状共晶固相熔解过程]: 涌现出丰富多样的图案形成机制"]},{"i":38018,"as":"窄带系统中的磁性源于电子关联、量子几何与能带色散之间的相互作用。铁磁和反铁磁态均可作为窄带模型系统的基态出现。本文研究了量子几何与能带色散之间的竞争机制，揭示了决定窄带系统中铁磁性与反铁磁性究竟哪种基态更受青睐的物理条件。","scd":null,"kp":["[窄带系统磁性基态竞争]: 铁磁与反铁磁态的基态优势取决于电子关联、量子几何与能带色散之间的相互博弈"]},{"i":38019,"as":"本文利用部分子-强子-量子分子动力学（PHQMD）方法，研究了吉电子伏特能级下重离子碰撞中核物质状态方程（EOS）对集体观测量（即核子与轻核的定向流v1和椭圆流v2）的影响。研究揭示了动量相关势如何影响中高能重离子碰撞中质子和轻核的集体流特征。","scd":null,"kp":[]},{"i":38020,"as":"本文研究了在自旋极化电流产生的自旋轨道力矩作用下，反铁磁体中畴壁的轮廓和动力学特征。研究发现，其动力学表现出铁磁体中没有的特性，并且可以通过电流极化方向进行调控：面内极化电流驱动畴壁传播，而垂直极化电流则引发进动动力学。","scd":null,"kp":["[反铁磁体畴壁在自旋极化电流下的动力学特性]: 表现出铁磁体中没有的动力学行为，且可通过电流极化进行调控","动力学行为[面内极化电流]: 传播畴壁","动力学行为[垂直极化电流]: 进动动力学"]},{"i":38021,"as":"本文在芯片上引入了一类新型“时空等离激元涡旋”，这类多色模式在空间和时间上交织了轨道角动量，并携带非平凡的拓扑自旋结构。这些涡旋是通过时间分辨结构光的时序干涉产生的。该成果为片上光通信和纳米级光操控提供了新途径。","scd":null,"kp":["时空等离激元涡旋[核心特征]: 携带非平庸拓扑自旋纹理，通过时间相干全息图的时空聚焦产生的时序干涉生成"]},{"i":38022,"as":"本文研究了具有不对称空间结构的主动和被动随机系统。研究结果挑战了传统的“棘轮原理”（该原理认为打破宇称和时间反演对称性是产生非平衡定向电流的必要条件），发现在某些存在隐藏守恒定律的随机系统中，即使打破了这些对称性，依然会阻止定向电流的产生。","scd":null,"kp":[]},{"i":38023,"as":"本文利用基于FAZIA实验装置对50 MeV/核子下的Ne-20+C-12反应数据的贝叶斯分析，约束了重离子碰撞输运模型中的关键参数：介质内核子-核子碰撞截面和团簇产生机制。通过比较反对称化分子动力学（AMD）模型的预测与实验数据，有效限制和优化了模型参数。","scd":null,"kp":["[重离子碰撞输运模型关键参数约束]: 基于贝叶斯分析对FAZIA数据集的比较，限制了介质内核子-核子碰撞截面和团簇产生的关键参数"]},{"i":38024,"as":"本文研究了具有极强本征值排斥的幺正量子系统中谱形状因子的类晶体行为。使用低温库仑气体模型模拟本征值排斥现象，推导出了德拜-沃勒因子（Debye-Waller factor），该因子会抑制谱形状因子的周期性振荡，揭示了强关联量子系统的能谱统计特性。","scd":null,"kp":["[具有极强本征值排斥的幺正量子系统中的晶体状谱形式因子行为]: 使用低温库仑气体模型推导出抑制谱形式因子周期振荡的德拜-沃勒因子"]},{"i":38025,"as":"过渡金属硫族化物（TMDs）结合了拓扑电子态和由长寿命激子产生的强光学响应。本文研究了由激子与分数陈绝缘体中的任意子耦合形成的相互作用费米子-玻色子系统，揭示了激子-任意子结合现象的光谱特征，为拓扑量子计算和光电性质研究提供了新视角。","scd":null,"kp":["[过渡金属硫族化物分数量子霍尔绝缘体中的激子-任意子束缚态]: 通过耦合激子与拓扑态形成相互作用的费米子-玻色子系统，具有可探测的光谱指纹特征"]},{"i":38026,"as":"本文指出，在Lindbladian开放量子系统中，连续时间晶体涌现的条件可以通过其作为PT对称态的出现来理解。研究表明，连续时间平移对称性的自发破缺伴随着临界奇异点（Critical Exceptional Points）的出现，从而完全阐明了连续时间晶体的出现条件和物理机制。","scd":null,"kp":["[开放量子系统中的连续时间晶体]: 表现为PT对称状态，并伴随临界例外点的出现"]},{"i":38027,"as":"研究测量了铍中交换关联空穴的动态行为。发现该关联空穴大小约为2埃，但在等离激元激发能下可延伸至约5埃。这一现象表明，电子关联性受到电子动力学的显著影响。","scd":null,"kp":["交换关联空穴尺寸[铍]: 约2 Å","交换关联空穴最大延伸范围[等离激元激发能下]: 最高达约5 Å"]},{"i":38028,"as":"研究使用精确数值模拟，探讨了受到非互易增益和损耗作用的相互作用费米子链。结果揭示了非互易耦合在量子多体临界性和纠缠中的影响，展示了非互易性与粒子相互作用交织产生的耗散相变现象。","scd":null,"kp":["[具有非互易增益和损耗的相互作用费米子链的耗散相变]: 非互易耦合的相互作用破坏了时间平移对称性，引发了耗散相变并影响了多体量子临界性和纠缠"]},{"i":38029,"as":"研究提出一种笼导向组装策略，通过预合成的Rh(II)金属有机多面体作为持续空腔模板，在HKUST-1型金属有机框架中编程引入拓扑相关缺陷。使用缺失一个羧酸基团的羧酸酯连接体，成功形成九种独立的局部缺陷构型，实现了缺陷分布控制和框架非周期性。","scd":null,"kp":["缺陷工程策略[金属有机框架HKUST-1]: 笼导向组装策略，可程序化引入拓扑相关缺陷并诱导非周期性"]},{"i":38030,"as":"为实现深层组织高分辨率生物成像，研究引入了由能量陷阱调节的镧系纳米颗粒概念。该技术旨在克服传统Er³⁺纳米探针在1530纳米发射时的高分辨率但组织穿透深度受限，与980/1060纳米探针穿透深但分辨率低的权衡矛盾。","scd":null,"kp":["成像技术权衡[Er³⁺掺杂稀土纳米颗粒近红外活体成像]: 约1530 nm发射具有高光学分辨率，但因水吸收导致组织穿透深度受限","[深度学习增强的生物成像]: 利用能量陷阱调控的稀土纳米颗粒结合深度学习解决深部组织高分辨率成像的权衡限制"]},{"i":38031,"as":"研究开发了一种以丰富可再生原料合成环丙烷的催化路线。呋喃氧杂环丁烷在路易斯酸催化下发生分子内SN型重排，生成具有理想原子经济性的环丙烷。该策略避免了传统方法对危险重氮前体或预功能化底物的依赖，并能够合成内消旋环丙烷二甲缩醛。","scd":null,"kp":["[环丙烷化合成]: 采用光生成氧杂环丁烷作为中间体，实现无重氮前体的整体吸热催化路线"]},{"i":38032,"as":"光动力治疗是一种高精度的肿瘤治疗方法，但传统光敏剂的瓶颈限制了其效率。花菁染料已成为克服这些挑战的首选分子框架。研究团队总结了过去8年在基于现代花菁染料的光敏剂领域的开创性工作，促进了光敏剂的合理设计并激发了跨学科的持续兴趣。","scd":null,"kp":["光敏剂[光动力治疗]: 花菁染料分子框架"]},{"i":38033,"as":"为解决CO₂转化为醇类过程中醇类导致离子导电聚合物离子通道不稳定的问题，研究开发了一种非极性交联聚合物结构。将离子导电聚芳基亚哌啶共价整合到非极性聚苯乙烯网络中，形成限制离子通道的疏水支架，有效防止了醇引起的溶胀，使机械性能保留率超过97%。","scd":null,"kp":["聚合物结构[CO2电还原富醇环境]: 非极性交联网络架构"]},{"i":38034,"as":"工业点源捕获CO₂的水溶液单乙醇胺(MEA)需通过高能耗热溶剂再生工艺释放CO₂。为降低此碳移除过程中的主要能源成本，研究探索了生物催化加速溶剂再生的方法。通过基于氨基酶特征超家族的序列挖掘，鉴定出可用于加速溶剂再生步骤的酶。","scd":null,"kp":["脱附机制[MEA溶液捕集CO2]: 酰胺酶催化脱附替代传统高耗能热溶剂再生"]},{"i":38035,"as":"针对锂氧气电池中电解液挥发、阳极退化及放电产物不可逆等挑战，研究设计了一种新型氟化醚共溶剂(FTE)。FTE具有高沸点，能有效抑制电解液蒸发，并调控界面和溶剂化动力学，从而显著提升锂氧气电池的循环耐久性。","scd":null,"kp":["共溶剂[锂氧电池]: 氟醚类共溶剂","[锂氧电池挑战]: 电解液挥发与分解、锂负极退化及Li2O2放电产物不完全可逆"]},{"i":38036,"as":"针对传统纳米滤膜固定孔道尺寸难以应对盐湖提锂中剧烈波动的Mg²⁺/Li⁺比，研究制备了自适应Mg²⁺门控聚合物膜。通过将4'-氨基苯并15-冠-5-醚大环接枝到聚酰胺膜表面，实现了纳米通道在空间位阻下的响应性尺寸切换，满足了多级分离的需求。","scd":null,"kp":["膜改性剂[纳米滤膜提锂]: 4'-氨基苯并15-冠-5-醚(AB-15C5)大环分子接枝","分离机制[适应镁锂比剧变]: Mg2+门控自适应纳米通道"]},{"i":38037,"as":"研究利用一系列弯曲程度系统控制的苝二酰亚胺衍生物，揭示了结构扭曲增强非辐射弛豫的起源。观察到单重态系统内从近乎一的发射向强烈非辐射衰变的显著转变。时间分辨光谱排除了三重态途径，确立内部转变为主要衰变通道，并证明弯曲诱导的振动重组主导了能量耗散。","scd":null,"kp":["非辐射弛豫[苝二酰亚胺弯曲畸变]: 结构扭曲导致非辐射衰减显著增强"]},{"i":38038,"as":"单壁碳纳米管因严重自聚集导致热电性能劣化。研究首创了自由基介导的分散策略，利用合理设计的带有供体-受体共轭骨架和游离自由基末端的小分子OTN。该策略通过双重相互作用增强π相互作用，打破聚集限制，显著提升了碳基柔性热电材料的性能。","scd":null,"kp":["分散策略[单壁碳纳米管热电材料]: 自由基介导的分散打破自聚集限制"]},{"i":38039,"as":"研究探讨了通过催化氧化将聚乙烯转化为二元羧酸的工艺。发现在无催化剂条件下，通过选择适宜反应参数，二元羅酸产率可达约29 mol%，且极少过度氧化为一氧化碳和二氧化碳。在高三氧化二氮分压下，气态产物生成受抑制，多种产物获得优异的碳回收率。","scd":null,"kp":["[聚乙烯催化氧化增值]: 催化氧化为二元羧酸"]},{"i":38040,"as":"为可持续回收聚氨酯和尼龙等含碳-杂键塑料，研究利用荧光塑料模拟物结合荧光激活细胞分选技术，对历史遗留塑料废弃物进行生物勘探。鉴定出12种塑料降解酶，与现有酶相比，这些酶针对不同高分子量聚氨酯聚合物和尼龙纺织品展现出更高的热稳定性和水解活性。","scd":null,"kp":["[塑料降解酶发掘]: 利用荧光塑料类似物结合荧光激活细胞分选(FACS)进行环境生物勘探","[新酶鉴定数量]: 29种塑料降解酶"]},{"i":38041,"as":"多孔有机笼凭借精确可调的孔结构和出色的溶液可加工性，成为离子分离膜的优质平台。其将结构限域与可调的离子-通道相互作用相结合，能够实现对尺寸和物理化学性质高度相似的离子进行选择性分离。本综述系统总结了多孔有机笼基离子分离膜的分子设计、制造、界面工程及分离机制。","scd":null,"kp":["[离子分离膜材料]: 多孔有机笼(POC)，具有精确可调的孔结构和优异的溶液可加工性","[离子分离机制]: 结构限域与可调的离子-通道相互作用协同，实现对尺寸和理化性质高度相似离子的选择性分离"]},{"i":38042,"as":"研究提出“配位饱和异构”作为分子设计范式，系统调控碘化亚铜簇的发光和闪烁性能。通过调节N-甲基哌嗪A位阳离子的质子化状态，实现了离子型一维链、有机型和结构型三种结构模式。该策略优化了分子发光效率、稳定性和器件兼容性，推动了计算机断层扫描成像的应用。","scd":null,"kp":["[碘化铜簇闪烁体分子设计]: 提出“配位饱和异构”范式系统调控发光与闪烁性能","[设计目标]: 在计算机断层扫描成像中协同优化发光效率、稳定性及器件兼容性"]},{"i":38043,"as":"为提升高性能电容去离子技术中氯离子捕获的容量与选择性，研究基于选择性轨道耦合理论设计了Fe₂CoSe₄/Ti₃C₂异质结构。该材料具有共存的四面体铁和八面体钴位点，独特的双中心几何结构触发了显著的电荷转移和电子调制，实现了高效的氯离子捕获。","scd":null,"kp":["[电容去离子(CDI)电极设计]: 基于选择性轨道耦合(SOC)理论的配位工程策略","[异质结构电极]: Fe2CoSe4/Ti3C2异质结构，用于高效氯离子捕获"]},{"i":38044,"as":"研究采用靶标导向策略开发了人类15-脂氧合酶-1的光开关抑制剂。15-脂氧合酶-1是炎症信号传导、铁死亡和癌症的关键酶。研究开发了可逆偶氮苯、偶氮杂环芳烃和共价偶氮双炔烃三类光开关化合物。这些化合物表现出高效的E/Z光异构化和高双稳态性，实现了对肠道炎症信号的光控调节。","scd":null,"kp":[]},{"i":38045,"as":"生物分子凝聚物形成的开放区室能够调节包括蛋白质聚集在内的生化过程。本综述探讨了相分离与淀粉样原纤维形成之间的分子机制。与直觉相反，即使在局部蛋白质浓度升高的情况下，凝聚物内部也能抑制而非促进蛋白质聚集；然而在特定条件下，界面处的原纤维形成却可能被加速。","scd":null,"kp":[]},{"i":38046,"as":"研究披露了一种受自然启发的钯催化碳-氮键形成新方法。通过向水中添加一定量氢氧化钾产生“脏水”强碱性环境，胺化反应可快速进行。30%氢氧化钾/水溶液的粘度阻止了有机偶联反应物的溶解，使得酯类、腈类等对碱敏感的基团得以保留，简化了反应过程。","scd":null,"kp":["[钯催化C-N键形成]: 利用“水上”现象在加入KOH产生的高碱性条件（“脏水”）下快速实现胺化"]},{"i":38047,"as":"无负极水系锌金属电池具有高能量密度，但其性能受界面副反应和正负极交叉污染的严重限制。通过数据驱动筛选分子描述符，构建了不对称双界面隔膜。该隔膜在负极侧采用Zn2+供应界面（ZSI），系统性解决了单一界面策略的不足，从而提升电池的能量密度和循环寿命。","scd":null,"kp":["[无负极锌金属电池]: 采用数据科学指导的双界面隔膜工程以抑制界面副反应和正负极交叉干扰"]},{"i":38048,"as":"针对共价有机框架因快速结晶难以实现有效手性诱导的问题，提出预交联网络介导的双交换策略。该策略通过在无定形亚胺网络中固定单体，发生并发胺和醛交换，延缓反应动力学并延长手性诱导窗口，成功在β-酮烯胺链接的COFs中实现了放大的手性光学活性和解耦的多级手性。","scd":null,"kp":["[手性共价有机框架合成]: 预交联网络介导的双交换策略","[机制与效果]: 克服快速结晶限制，实现增强的光学活性并解耦多级手性"]},{"i":38049,"as":"为解决锂金属阳极人工固体电解质界面（ASEI）因体积波动破裂脱落而降解的问题，开发了动态交联氟聚合物（DCF）人工界面。该聚合物由脲基嘧啶酮交联，其可逆四重氢键能实现聚合物裂纹快速自愈合。同时，该动态界面还能持续补充富氟无机SEI成分，显著稳定锂金属阳极。","scd":null,"kp":["[锂金属负极人工固体电解质界面]: 动态交联含氟聚合物(DCF)","[界面保护机制]: 赋予聚合物涂层自主裂缝愈合能力，并持续补充无机SEI成分以维持稳定"]},{"i":38050,"as":"报道了一种由B(C6F5)3催化硅氢加成脱氧聚合合成聚硅氧烷的新策略。该反应过程能够同步将聚醚和聚酯等含氧聚合物降解升级为烷烃。聚合物中C-O/C=O键周围的位阻、溶解度及反应条件直接影响Si-O键的构建效率和C-O/C=O键的断裂程度，实现了可持续塑料升级回收与新材料制备的结合。","scd":null,"kp":["[聚硅氧烷合成与聚合物升级回收]: B(C6F5)3催化的氢化硅烷化脱氧聚合策略，将聚合物升级回收为烷烃"]},{"i":38051,"as":"为解决钙钛矿光催化溴化氢（HBr）分解制氢中溴积累阻碍反应动力学的问题，在HBr系统中引入乙醛作为还原剂。采用具有暴露（100）和（111）晶面的铂单原子修饰FAPbBr3钙钛矿，实现了高性能氢气析出，同时将乙醛氧化升级为高附加值的乙酸，有效突破了1.09 V的氧化能垒。","scd":null,"kp":["[溴化氢裂解氧化反应能垒]: 1.09 V (vs NHE)","[钙钛矿光催化体系]: 引入乙醛作为稳定且强还原剂，在FAPbBr3体系中同步实现产氢与乙酸合成"]},{"i":38052,"as":"提出一种基于聚合动力学介导的策略，通过空间调制拓扑缠结和链间相互作用，在 hydrogels（水凝胶）中实现高对比度的三维自变形。该策略利用聚合过程中的链增长与质量传输竞争，慢速聚合使单体向内扩散形成互穿聚合物网络，产生具有截然不同溶胀比的局部结构域，大幅提升了形态复杂性。","scd":null,"kp":["[水凝胶三维自变形机制]: 聚合动力学介导空间拓扑纠缠与链间相互作用，产生具有显著溶胀差异的局部结构域以实现高对比度三维形变"]},{"i":38053,"as":"针对有机太阳能电池中背靠背二聚体受体分子间相互作用弱的问题，采用不对称端基策略开发了新型不对称二聚体受体DQx-FCl。打破结构对称性改变了静电表面电位，增强了分子间π-π相互作用。同时，该设计减少了单线激发态中电子和空穴的重叠，促进了电荷分离，从而有效提升了器件效率与拉伸性能。","scd":null,"kp":["受体分子结构[有机太阳能电池]: 不对称端基封端的背靠背二聚体 DQx-FCl"]},{"i":38054,"as":"利用结构与位点明确的分子模型催化剂，揭示了电子自旋态是主导氧还原反应（ORR）选择性生成过氧化氢（H2O2）的决定性因素。实验合成了一系列酞菁钴衍生物，发现钴的自旋态与ORR选择性之间存在明确相关性，阐明了自旋状态对电化学能量技术中ORR机制的底层调控作用。","scd":null,"kp":["调控机制[氧还原选择性产过氧化氢]: 电子自旋状态"]},{"i":38055,"as":"针对MOF光催化剂体相电荷复合严重和表面活性位点不足的挑战，提出界面供体-受体（D-A）系统。通过纳米限域、光解、重捕获和再分布的自优化过程，将三种不同配位环境的PtL受体像天线一样锚定在NH2-MIL-125上。该受体不仅能自身光致激发，还能捕获并汇聚MOF主体提供的电子，实现高效光催化析氢。","scd":null,"kp":["界面工程[MOF光催化析氢]: 界面供体-受体(D-A)系统","催化剂合成[MOF光催化析氢]: 纳米限域、光解、重捕获及重排的自优化过程","受体[MOF光催化析氢]: 具有不同配位环境的PtL受体通过酰胺键锚定于NH2-MIL-125"]},{"i":38056,"as":"","scd":null,"kp":[]},{"i":38057,"as":"","scd":null,"kp":[]},{"i":38058,"as":"为解决无细胞系统中mRNA表达量低而无法进行RNA测序的问题，结合贝叶斯优化与高通量实验开发了主动学习工作流。在探索160万种缓冲液组合后，筛选出使mRNA产量提升20倍的优化缓冲液。利用直接RNA测序对T7噬菌体转录组进行了分析，揭示了无细胞基因表达与纯化转录系统及细菌感染状态的渐进式调控差异。","scd":null,"kp":["探索空间[无细胞系统缓冲液优化]: 160万种缓冲液组合","实验测试[无细胞系统缓冲液优化]: 653种","mRNA表达优化[无细胞系统]: “mRNA优化”缓冲液体系（提升20倍）"]},{"i":38059,"as":"","scd":null,"kp":[]},{"i":38060,"as":"","scd":null,"kp":[]},{"i":38061,"as":"电催化原电池重新定义了电化学能量转换模式。该技术能够利用可再生原料和废弃原料，在实现电能自发产生的同时，完成高附加值化学品的合成。这种将发电与化工合成耦合的新型范式，为能源转化与资源利用提供了创新途径。","scd":null,"kp":["电化学反应器[自发化学合成与发电]: 电催化原电池"]},{"i":38062,"as":"","scd":null,"kp":[]},{"i":38063,"as":"针对多重耐药（MDR）铜绿假单胞菌引起的非手术假体周围感染，在抗生素及多次手术治疗失败后，采用了间歇性噬菌体疗法进行为期两年的单独治疗。该个性化噬菌体治疗实现了感染的临床消退（尽管未达到微生物学根除）。噬菌体通过改变细菌毒力特性，成功长期抑制了多重耐药细菌在植入物感染中的蔓延。","scd":null,"kp":[]},{"i":38064,"as":"脑型疟疾（CM）的发病机制涉及一个以脾脏为中心的体液自身免疫回路。感染的红细胞富含宿主来源的CD36抗原，诱导患者产生抗CD36自身抗体。这些抗体虽然有助于清除受感染红细胞，但也会攻击其他表达CD36的细胞，导致血小板减少、内皮损伤和巨噬细胞活化。机制上，疟原虫感染通过CCL2-CCR2轴招募特定巨噬细胞至脾脏，加剧了系统性炎症。","scd":null,"kp":[]},{"i":38065,"as":"纹状体多巴胺能神经元的许多响应（如高成本、厌恶刺激）无法用传统的奖励预测误差（RPE）解释。基于信息论，研究发现这种表观上的RPE相关性在数学上实际上源于动作策略的信息增益。策略信息增益量化了新到达的信息改变选择的程度，将不确定性和奖励预期统一在同一个数学框架内，解释了纹状体-多巴胺回路的决策与学习机制。","scd":null,"kp":[]},{"i":38066,"as":"线粒体功能障碍是引发视网膜色素变性（RP）视网膜脆弱的关键因素。在RP大鼠模型中，光感受器细胞和视网膜色素上皮（RPE）细胞的线粒体出现明显异常，且烟酰胺腺嘌呤二核苷酸（NAD+）代谢水平显著下降。补充NAD+能够有效调节MERTK相关模型中线粒体的脆弱性，为预防和治疗致盲性RP提供了潜在新靶点。","scd":null,"kp":[]},{"i":38067,"as":"铁蛋白由重链(FTH1)和轻链(FTL)组成。研究表明，急性呼吸窘迫综合征(ARDS)患者血清、单核细胞和肺泡巨噬细胞中的FTH1与FTL显著富集。在髓系细胞中特异性敲除FTH1可减轻肺损伤，减少巨噬细胞铁死亡，改变气道炎症反应，并降低细胞外铁水平及FTL的补偿性分泌。","scd":null,"kp":[]},{"i":38068,"as":"硬膜外纤维化是脊柱手术后的严重并发症。研究发现患者术后手术部位存在FAP⁺成纤维细胞富集。通过研发双特异性抗体修饰的细胞外囊泡，可重定向内源性T细胞以原位清除FAP⁺成纤维细胞。在临床前模型中，该囊泡能选择性清除致病性成纤维细胞，减少纤维化胶原积累并预防术后硬膜外纤维化，且在测试条件下未检测到全身毒性。","scd":null,"kp":[]},{"i":38069,"as":"人类钠依赖性多维生素转运蛋白(SMVT)介导生物素、泛酸和硫辛酸等关键代谢辅助因子的细胞摄取，其功能障碍与神经和代谢疾病及癌症相关。研究利用冷冻电子显微镜解析了SMVT在封闭、向外开放和向内开放三种构象下的结构，揭示了靠近弯折跨膜螺旋(TM1)的保守底物结合口袋，明确了其底物羧基被静电锚定的多底物转运分子机制。","scd":null,"kp":[]},{"i":38070,"as":"光系统II(PSII)天线中的过量激发能会对光合器造成不可逆损伤。非光化学猝灭(NPQ)作为反馈机制，可将多余能量以热能形式安全耗散。研究通过对缺乏LHCII三聚体和外周天线的拟南芥突变体进行时间分辨荧光测量，结合稳态荧光实验结果，定量分析了PSII超复合物不同区室对NPQ发生的具体贡献程度。","scd":null,"kp":[]},{"i":38071,"as":"研究发布了具有极高耐逆性的同源六倍体河八王的高质量单倍型参考基因组。基因组分析表明，河八王约在131万年前起源于二倍体祖先，多倍化后经历了两轮长末端重复逆转录转座子的近期爆发。系统发育分析证实甘蔗与高粱亲缘关系更近，表明两者多倍化过程独立发生。","scd":null,"kp":[]},{"i":38072,"as":"细胞在应激反应中会通过可塑性形成突出物进行迁移。利用新型遗传筛选方法，研究证实Cbx3是突出物形成的关键决定因素。除了其核内功能，CBX3还具有调控特定mRNA在表皮祖细胞极化突出物及鳞状癌细胞侵袭足中的亚细胞定位的“兼职”功能。这种CBX3依赖性的mRNA运输促进了局部微型细胞质的建立，从而驱动应激状态下的细胞激活。","scd":null,"kp":[]},{"i":38073,"as":"SARS-CoV-2的免疫逃逸变异株需要能激发变异株特异性抗体的疫苗。在经武汉刺突蛋白mRNA或腺病毒载体疫苗免疫的小鼠中，使用Omicron匹配疫苗进行加强。改变肌肉注射部位对血清特异性抗体反应无实质性影响，但增加加强针抗原剂量、多次接种以及通过鼻内接种加强疫苗，能够有效增强针对变异株的特异性免疫反应。","scd":null,"kp":[]},{"i":38074,"as":"研究利用包含全球846个森林流域的地面调查、径流数据及遥感数据，分析了森林树种丰富度对流域碳固存、碳储存、供水、水文调节和土壤保持等多重生态功能的影响。结果显示，树木物种丰富度与流域生态多功能性之间呈现出一致的正相关关系。","scd":null,"kp":[]},{"i":38075,"as":"针对低维材料局部原子结构难以确定的问题，研究提出了一种对称性引导的筛选策略。结合扫描透射电子显微镜、反应力场分子动力学和密度泛函理论，将稀土氯化物封装在单壁碳纳米管中，形成了包含有序一维原子纳米线的稳定LnCl3@SWCNTs杂化物。该策略成功解析了受限在一维原子纳米线内的离子排列结构。","scd":null,"kp":["结构解析方法[低维稀土氯化物]: 对称性引导的筛选策略结合扫描透射电子显微镜"]},{"i":38076,"as":"植被在受到外部扰动后的恢复速度是预测生态系统稳定性的关键。研究评估了岩性和构造对全球山脉植被韧性的调节作用。植被类型和温度主导了全球空间格局，其中树木的韧性最高。在排除气候和人为影响后，岩石圈路径对各植被类型的韧性具有强烈调节作用，树木韧性在特定 lithospheric pathways 中达到峰值。","scd":null,"kp":[]},{"i":38077,"as":"在Quantinuum的H1量子计算机上，研究利用Renyi关联子和量子纠错码的变分解码性能，探测了混合态物质的相变。通过阴影层析技术提取了处于不同退相干噪声通道下的横场伊辛模型低能态的Renyi关联子，观察到不同相下的衰减差异，并研究了相关量子误差纠正码的解码保真度。","scd":null,"kp":["量子计算验证[混合态物相]: 在Quantinuum H1量子计算机上利用Renyi关联子和变分解码表征"]},{"i":38078,"as":"气候变暖加速了青藏高原冻土的骤然融化并引发严重的碳释放。综合分析显示，受降水变化驱动，到2100年热融滑塌易发区面积将比2022年扩大17-19%。与未坍塌区域相比，坍塌区生态系统呼吸率下降14.4%，但甲烷释放率增加20.0%。2016至2022年间，由RTS扩张导致的二氧化碳和甲烷总释放量增加了1.1倍。","scd":null,"kp":[]},{"i":38079,"as":"针对二维共轭金属有机框架电致变色颜色单调且机制不清的问题，研究提出金属中心电子亲和力是决定电致变色性能的关键机制。通过无监督机器学习筛选出锌、镍、铜等二价金属邻苯二酚体系。这三种体系均表现出从绿到蓝再到紫的多色转变，其中Zn-CAT-1和Ni-CAT-1的切换速度比Cu-CAT-1快三倍，表现出更优异的性能。","scd":null,"kp":["电致变色机制[二维共轭金属有机框架]: 金属中心电子亲和力调控机制","材料筛选[二维共轭金属有机框架电致变色]: 无监督机器学习方法筛选二价金属-儿茶酚配合物"]},{"i":38080,"as":"准确的分子属性预测对化学和药物研发至关重要。研究提出了双图变换器(DGT)架构，通过自注意力机制联合建模原子图和化学键图，有效融合了原子与化学键特征、拓扑结构及立体几何信息。在多组分子属性预测数据集的基准测试中，DGT的表现显著优于当前最先进的方法。","scd":null,"kp":["大模型架构[分子性质预测]: 融合原子图与化学键图特征的自注意力架构(DGT)"]},{"i":38081,"as":"序列明确的低聚物在数据存储和防伪领域具有应用潜力。研究提出了一种基于非生物序列明确低聚酰胺的分子标记策略。这些低聚酰胺能够在超低浓度下掺入塑料材料中，作为高鲁棒性的分子信息载体，突破传统低聚物在规模化应用、热稳定性和专用分析方法上的限制，实现了塑料材料的可追溯性。","scd":null,"kp":["分子标签[塑料材料溯源]: 序列明确的非生物低聚酰胺(超低浓度掺入)"]},{"i":38082,"as":"研究从信息论角度揭示了量子系综克隆的基本定律，证明了即使假设拥有系综纯化的多个副本，任意系综的通用不可克隆定理依然成立。这一发现解决并澄清了在量子多体物理和量子热力学中，依赖测量单体量子态非线性特性的量子系综控制系统所面临的精细克隆挑战。","scd":null,"kp":[]},{"i":38083,"as":"研究开发了一种利用蒸汽辅助结晶法合成的沸石(SA-HZSM-5)，可在260℃下将高密度聚乙烯高效转化为芳烃，转化率高达85.4%，选择性达49.2%。该无贵金属催化剂的性能超越了同条件下的Ru-HZSM-5，产物中约85%为高价值的单环芳烃。其机制归因于SA-HZSM-5内部特定的路易斯酸和布朗斯台德酸位点分布，实现了单烯烃的双位点吸附。","scd":null,"kp":[]},{"i":38084,"as":"宏观相干性是量子多体系统的重要特征。研究实验探究了从排斥相互作用骤冷至调制不稳定的吸引相互作用状态下的简准一维玻色气体。通过原位密度和物质波干涉成像监测发现，动力学演化过程表现出长程多体相干的密度波演化现象，这与此前在吸引玻色气体中观测到的经典孤子列车形成明显区别。","scd":null,"kp":[]},{"i":38085,"as":"双光子聚合技术广泛用于聚合物三维微纳加工，但金属纳米打印由于能量驱动反应难以空间局域化而极具挑战。研究通过纳米晶体内的多电子激发产生时空受限的热电子，成功突破了聚合物的限制，实现了具有极高深度和横向分辨率的金属三维纳米打印。","scd":null,"kp":[]},{"i":38086,"as":"可拉伸射频天线在自然形变下易发生共振失谐。研究提出了针对谐振平面天线的系统性方向机械-电磁分析框架，并开发了双端口多向应变不敏感天线(DP-MSiA)。该天线在2.45 GHz工作频率下，能够承受高达45%的多种面内应变，且共振频率偏移保持在40 MHz以内，解决了传统设计受限于特定负载方向和辐射性能妥协的问题。","scd":null,"kp":[]},{"i":38087,"as":"提出一种利用介电超表面对宽带辐射传热进行抑制的新策略。该技术通过随机梯度下降（SGD）优化算法，协同设计了非周期性分布布拉格反射镜（DBR）对。设计使反射镜的通带在较宽的热波段内发生错位，在较小的厚度和制造成本内实现了有效的宽带热解耦，突破了传统非金属热光子方法受Bode-Fano极限约束的性能与带宽权衡瓶颈。","scd":null,"kp":[]},{"i":38088,"as":"建立了通过调节镧系元素组成和壳层沉积速率，在核-壳-壳纳米晶格中控制界面晶格应变的模型系统。研究发现，在六方相NaErF4@NaYF4@NaLnF4纳米结构中，界面处的晶格失配主导了镧系元素跨异质界面的迁移，从而决定了晶体的生长和光学性质。当晶格失配率超过5.1%时，镧系离子可发生长达13纳米的迁移。","scd":null,"kp":[]},{"i":38089,"as":"提出一种仿生策略，利用等离子体纳米复合螺旋结构解决激光雷达保护盖上的多尺度水滴干扰问题。该结构通过掠角共沉积技术将铜纳米颗粒嵌入三维二氧化硅纳米螺旋中。铜纳米颗粒在保持905纳米波段超过85%透射率的同时提供可见光等离子体光热效应以实现被动防雾，螺旋结构则赋予材料分层粗糙度，使其达到143°的接触角，具备抗压的疏水防雨能力。","scd":null,"kp":[]},{"i":38090,"as":"提出了一种界面吡啶盐-炔点击聚合策略，原位制备均匀、无缺陷的大面积自支撑有机聚合物薄膜。该技术在空气-DMSO界面形成厚度可调（几十至几百纳米）的HDPP-TFB-BF4薄膜。在连续紫外光照射下，该薄膜表现出显著的100纳米蓝移和5倍荧光增强的光致变色特性，并生成基于自由基的薄膜，可作为视觉传感、自由基生成等应用平台。","scd":null,"kp":[]},{"i":38091,"as":"提出一种用于具身智能体的仿生空间认知导航框架（BSC-Nav）。针对多模态大语言模型（MLLMs）缺乏结构化空间记忆且仅能反应式运行的问题，该框架模拟生物系统，将空间认知知识整合为地标、路径和地图测量三种互联形式，构建并利用以自我为中心的结构化空间记忆，提升了智能体在复杂真实环境中的泛化能力和适应性。","scd":null,"kp":[]},{"i":38092,"as":"结合古气候代用指标、多重气候模型和古气候数据同化技术，揭示了工业革命前过去千年间大西洋经向翻转环流（AMOC）的演化历史及驱动机制。结果显示，公元850至1850年间AMOC缓慢减弱，流量减少约0.7 Sv（约4%）。这一长期减弱趋势主要由爆炸性火山喷发驱动。火山喷发后的最初十年AMOC会快速增强，随后因海洋储存的冷却效应在百年尺度上呈现缓慢减弱。","scd":null,"kp":[]},{"i":38093,"as":"提出了一种“动态糊状模型”以解释高硅流纹岩岩浆的成因。结合结构和热力学建模分析表明，高硅熔体通过上地壳分馏形成，正长岩和暗色正长岩是其硅酸-基性堆晶岩。正长岩在较低的结晶度（约16-33体积%）下形成，期间提取了大量（47-80液体体积%）的间隙熔体。该动态提取机制克服了静态模型中无法在上地壳找到互补堆晶体的难题，并与火山口崩塌式喷发相关联。","scd":null,"kp":[]},{"i":38094,"as":"报道了一种超支化介电聚合物网络，解决了高温下电荷转移导致的电容储能受限问题。超支化拓扑结构不仅将线性聚合物链转化为坚固的网络以承受热应力，还扩大了链间距，有效抑制了高电热场下的电荷转移。该聚合物网络在250℃的严苛高温环境下表现出卓越的储能密度，满足了恶劣环境电子系统对先进介电材料的需求。","scd":null,"kp":[]},{"i":38095,"as":"提出一种智能声电超构材料（IAM）用于水下声源探测。该架构由独特的三维微结构压电水听器组成，通过物理几何结构而非化学成分来动态编程压电特性。这种结构多样性产生了独特的机电响应，使单一器件能够对海洋生物、水下潜航器等多种水下目标进行实时、自动的声源定位，推动了下一代声学传感技术的发展。","scd":null,"kp":[]},{"i":38096,"as":"探讨了材料挤出增材制造中存在的分辨率与吞吐量（制造速度）之间的根本矛盾。研究强调了材料行为、传输和打印架构之间的相互作用，并指出了新兴的系统级方法。这些方法旨在解耦制造精度与速度，从而在广泛的材料和尺寸规模上实现稳健的多尺度制造，从微尺度结构特征延伸到大型结构打印。","scd":null,"kp":[]},{"i":38097,"as":"提出利用离子束沉积（IBD）技术在商业铜集流体和锂箔上制备具有非晶-纳米晶复合微观结构的ZnMgSn薄膜涂层。该人工界面层具有强亲锂性和快速动力学特性，不仅增强了锂原子的吸附能，还显著降低了锂原子的扩散势垒，从而协同实现均匀的锂沉积。该微结构工程有效解决了锂金属负极中不可控的枝晶生长和不稳定的固体电解质界面（SEI）问题，适用于长循环锂金属电池。","scd":null,"kp":[]},{"i":38098,"as":"","scd":null,"kp":[]},{"i":38099,"as":"利用M3D-K代码研究了中性束注入（NBI）与离子回旋频率范围（ICRF）波协同加热产生的快离子对鱼骨不稳定性的影响。忽略平衡改变时，协同快离子对鱼骨模式起稳定作用，且该效应随垂直温度和Beta值增加而增强；当其超过阈值时会驱动高频鱼骨分支。若考虑协同快离子对平衡的改变，其净效应在较大尺寸下表现为稳定，在较小尺寸下表现为失稳。","scd":null,"kp":[]},{"i":38100,"as":"利用回转动力学模拟研究了HL-2A托卡马克中离子内部输运势垒（ITB）的动力学过程，重点分析了漂移波湍流与带状流（ZF）的相互作用。模拟揭示了维持ITB的自调节循环，其中离子温度梯度湍流驱动带状流，进而抑制湍流。核心发现是带状流主要由湍流离子能通量驱动，而非经典捕食者-猎物模型中认为的极向雷诺应力，为实验中观察到的极向雷诺应力微弱效应提供了自洽解释。","scd":null,"kp":[]},{"i":38101,"as":"基于HL-2A托卡马克边缘等离子体湍流实验，利用双点法和双谱分析研究了多尺度涨落之间的非线性能量传递过程。研究观察并描绘了逆能量级联、能量级联和双级联现象。实验发现，在边缘等离子体中，能量典型地从高频区的小尺度结构向低频区的大尺度结构传递。这种逆能量转移能够触发或加强大尺度流结构，为理解湍流系统中的等离子体输运行为提供了完整图像。","scd":null,"kp":[]},{"i":38102,"as":"提出一种通过定制气泡动力学实现节能高效电合成H2O2的方法，将阴极H2O2合成与阳极升级耦合以实现无外部供电运行。高速成像微观实验表明，电解液中的有机底物作为界面气泡成核调节剂，降低了气液表面张力，大幅降低了产物气泡的成核壁垒。这导致微气泡生成频率升高并产生驻留粘附现象。基于该机理指导，有效克服了工业级电流密度下的界面动力学瓶颈。","scd":null,"kp":[]},{"i":38103,"as":"提出一种基于商业氯化聚烯烃（PP-Cl）的无合成增韧策略，用于本征可拉伸有机光伏器件（IS-OPVs）。该材料成本低、可溶液加工，与多种高性能给受体共混物具有广泛兼容性。在不牺牲光伏性能的前提下，赋予了器件优异的机械韧性。在最佳负载下，基于PM6:BTP-eC9的刚性器件不仅保持了机械回弹性，其光电转换效率（PCE）也实现了可重复的提升，解决了高效率与高机械变形难以兼顾的难题。","scd":null,"kp":[]},{"i":38104,"as":"介绍了大型螺旋装置（LHD）在等离子体控制与物理研究方面的进展。通过数据同化技术实现了电子温度的实时控制；虚拟LHD环境可视化了逃逸的高能氚离子并证实其撞击偏滤器板背面。此外，利用锂颗粒下降进行实时壁处理，改善了体离子能量和粒子输运并增强了重杂质输运。研究还在湍流驱动的等离子体输运动力学方面取得突破。","scd":null,"kp":[]},{"i":38105,"as":"以斑马鱼幼体为模型，研究发现抑制性突触后支架蛋白Gephyrin（Gphn）在介导特定轴突类别的选择性髓鞘化中起关键作用。Gphn在GABA能和甘氨酸能轴突的髓鞘中富集。在Gphnb缺陷的少突胶质细胞中，GABA能轴突的髓鞘形成受损，且髓鞘鞘生长受限被解除。这表明少突胶质细胞谱系利用该突触后蛋白对抑制性轴突进行特异性髓鞘化并限制其生长。","scd":null,"kp":[]},{"i":38106,"as":"展示了一种基于碲纳米线和纳米片互补集成的智能非线性光学计算范式。该体系利用碲材料固有的光学各向异性以及偏压调制的相反二次谐波产生行为。在信息安全领域，利用光学各向异性作为物理不可克隆函数的熵源构建了加密单元；在偏振图像处理领域，利用各向异性实现了对干扰背景的光学滤波，打破了传统偏振系统感知与处理分离导致的延迟和冗余。","scd":null,"kp":[]},{"i":38107,"as":"提出一种由反向特斯拉阀调制的体效应蒸发系统（BEES），以打破液-气界面的边界层阻力限制。该系统将特斯拉流体二极管反向应用，利用结构诱导的涡流气流破坏热质传递边界层，解锁了内部液-气界面前所未有的蒸发动力学。该技术实现了21.29 kg m−2 h−1的极高蒸发速率，并显著提升了太阳能和总能量利用效率，适用于太阳能蒸汽生成和蒸发冷却等工业场景。","scd":null,"kp":[]},{"i":38108,"as":"针对柔性电子中大面积、厚度可控且低成本的独立氧化物薄膜需求，提出一种水辅助离子解锁策略。该方法通过水诱导钾离子从云母基板中浸出，削弱Pt/云母界面结合能，成功实现厘米级独立铁电Pb(Zr,Ti)O3薄膜的快速剥离。","scd":null,"kp":[]},{"i":38109,"as":"研究了富锂锰基氧化物正极在硫化物全固态电池中的界面演变。发现高电位下不可逆的晶格氧氧化还原会导致严重的硫化物电解质分解，生成多孔含氧副产物，增加界面阻抗并阻碍阴离子氧化还原。在2.6-2.0V放电时，副产物还原结合锂离子重构界面层，显著增强了性能。","scd":null,"kp":[]},{"i":38110,"as":"报告了一电子和二电子三钍原子簇，它们均表现出增强的抗磁性，展示了开壳层和闭壳层的Jellium芳香性。研究证实，这些全金属Jellium芳香体表现出非线性的磁响应，打破了环电流计算的基础假设，解释了先前实验与计算结果之间的冲突。","scd":null,"kp":[]},{"i":38111,"as":"设计了一种有机三体异质结适应型光晶体管（OTAT），在单一器件中集成了运动分析与运动目标提取功能。该器件采用相邻栅极的半导体-绝缘体异质结作为光敏渗透通道，在跨越六个数量级的光照下实现精细调节。成像实验中，该器件实现了45.3%的高光比目标提取，逼近人类视觉能力。","scd":null,"kp":[]},{"i":38112,"as":"以金属钨为模型系统，揭示了氢杂质对材料辐照缺陷演化的影响。研究表明，氢原子在空位团簇内表面的吸附会显著抑制空位与自间隙原子的复合，阻碍缺陷湮灭。其核心机制是氢的吸附通过应力介导作用改变了空位团簇的局部应力场，削弱了其与间隙原子的相互作用。","scd":null,"kp":[]},{"i":38113,"as":"开发了一种快速、灵敏的碰撞诱导去折叠（CIU）分析技术，用于预测工程化单克隆抗体（hIgG2变体）的激动剂活性。研究发现气相条件下的蛋白质去折叠状态与其药理激动作用存在预测关联，突出了铰链区工程在调节单克隆抗体结构与功能关系以及开发生物治疗药物中的重要作用。","scd":null,"kp":[]},{"i":38114,"as":"阐明了石榴石型Li7La3Zr2O12固态电解质晶界处的元素偏析对锂离子传输和枝晶形成的关键影响。常规烧结中Al、Ta和La在晶界偏析，导致局部锂耗尽并形成空间电荷层，降低总离子电导率；同时提高了晶界处的电子电导率，促进锂晶核形成并增加枝晶风险。该偏析机制由烧结晶界的双峰结构主导。","scd":null,"kp":[]},{"i":38115,"as":"为解决多色中子束聚焦时产生的严重色差问题，研发出一种用于全场中子显微镜的消色差中子透镜。该透镜克服了传统复合折射透镜和菲涅尔波带片在多色光束下的成像缺陷，为推进真正的高分辨率中子显微镜技术提供了关键的光学器件支持。","scd":null,"kp":[]},{"i":38116,"as":"提出一种统计过滤器，通过将节点级别的二分网络聚类与保留度分布的随机化网络进行基准对比，将节点分类为几何信号或度约束噪声。在四个实际系统（代谢、在线群组、植物-授粉者、语言）应用中，该过滤器成功剥离了普遍存在或弱共现实体，提取出紧凑且具复现性的几何传输主干网络。","scd":null,"kp":[]},{"i":38117,"as":"通过在La0.4Sr0.6FeO3-δ钙钛矿上电化学选择性浸出Sr离子，构建了富含羟基的纳米空腔，实现了硝酸盐高效电还原为氨。羟基间的分子内氢键开辟了无势垒的氢转移路径，促进了活性氢的生成与跳跃以实现硝酸根加氢，克服了传统表面氢迁移缓慢的瓶颈。","scd":null,"kp":[]},{"i":38118,"as":"揭示了平移对称晶格中的波动力学天然等同于卷积操作，其色散关系可唯一确定复值卷积核。基于此原理，在可编程光子合成晶格中实现了极低复杂度的卷积架构，在图像处理上达到13.5 TOPS的高吞吐量。复值核的物理特性还支持了对不可逆扩散的光子模拟与数据加密处理。","scd":null,"kp":[]},{"i":38119,"as":"提出由超亲钠离子/电子混合导体界面驱动的“顶部”钠沉积机制，用于提升准固态钠金属电池寿命。该界面内嵌具有高电子电导率和强Na+吸附能的Na3Sb合金相，加速了界面离子扩散与成核动力学，确保了快速且无枝晶的钠负极运行，最终形成平滑致密的钠沉积层。","scd":null,"kp":[]},{"i":38120,"as":"提出一种单体诱导的原位界面工程策略，通过丙烯酰胺单体在锌阳极表面的优先吸附，构建了含有动态负电荷微区的稳定水化网络界面（HNI）。该界面通过三重协同机制（Lewis酸碱配位提供成核位点、动态锚定作用、水化网络调控）精准调控锌沉积，实现了超稳定的水系锌离子电池。","scd":null,"kp":[]},{"i":38121,"as":"通过单细胞RNA测序发现，肺纤维化过程中存在一种正常肺部没有的成纤维相关周细胞亚群，它们具有向纤维化状态转变的独特转录特征。转录因子FOXF1在成纤维周细胞中表达下调，特异性敲除Foxf1会加重小鼠肺纤维化，揭示了FOXF1在调控周细胞促纤维化转变中的关键作用。","scd":null,"kp":[]},{"i":38122,"as":"在阿曼萨迈尔蛇绿岩的强碱性（pH>11）环境中，发现了甲烷氧化的直接证据。同位素与宏基因组测序数据表明，δ13CH4的富集无法仅用非生物过程解释，其伴随有甲烷氧化菌16S rRNA基因序列。宏基因组组装基因组证实了超嗜碱甲烷营养菌在甲烷富集且还原性流体中的活跃代谢作用。","scd":null,"kp":[]},{"i":38123,"as":"采用液态金属辅助策略直接合成并转移了单晶、4英寸晶圆级、厚度仅7.5纳米的超薄β-Ga2O3薄膜。基于此制造的日盲探测器实现了16.3 A/W的高响应度和快速响应。此外，还开发出受日晷启发的高维度超系统，能利用该薄膜同时检测入射光方向，突破了传统单一探测器的功能限制。","scd":null,"kp":[]},{"i":38124,"as":"利用单分子技术发现，大肠杆菌复制解旋酶DnaB在正确装载后，是极快的单链DNA易位子，移动速度高达3 knt/s，是复制体速度的三倍。其易位过程具有高度的持续合成能力，能抵抗拉力和高盐环境并排解短链DNA双链。研究证实，该解旋酶由灵活燃料马达驱动，不局限于单一ATP的水解。","scd":null,"kp":[]},{"i":38125,"as":"开发出具有组织粘附性的水凝胶光纤（TAHOFs），由折射率1.429的导光芯和折射率1.343的生物粘附包层组成。0.086的折射率差实现了0.534 dB/cm的低传播损耗和高效光限制。该器件在30%拉伸应变下仍保持稳定的空间定位，成功在自由活动的小鼠胰腺中实现了外周光遗传学神经调控。","scd":null,"kp":[]},{"i":38126,"as":"利用分子动力学模拟与生化实验揭示了辅酶Q（CoQ）合成代谢体的形成机制。COQ代谢体在相变临界点形成，其聚集程度和代谢通量随蛋白间相互作用强度的变化呈现协同的S型响应。完整的代谢体实现了连续酶促反应间的底物通道效应，极大提升了辅酶Q的生产效率。","scd":null,"kp":[]},{"i":38127,"as":"通过融合血凝素（HA）特异性中和抗体与唾液酸受体结合域（SiaB），工程化出唾液酸锚定的串联药物M-SiaB。与母体抗体相比，M-SiaB对多种流感病毒的中和效力提高了4至20倍，抑制病毒的附着、进入和释放。鼻内给药可对高致病性H1N1和H5N1/Texas/2024毒株感染提供显著增强的保护。","scd":null,"kp":[]},{"i":38128,"as":"为研究太空飞行对人体代谢的影响，研究人员利用液相色谱-质谱联用技术，对52名宇航员在国际空间站执行任务前、中、后的血浆代谢组进行了纵向分析。结果显示，太空飞行影响了约40种循环化合物。这些代谢变化在发射后不久即出现，并在着陆后几天内消退。飞行引起的代谢物变化反映了肠道微生物蛋白质发酵的增加。","scd":null,"kp":[]},{"i":38129,"as":"本文提出了一种基于扫描光场显微镜的实时鲁棒自动对焦方法。该方法无需修改硬件，通过利用光场角度测量的内在视差，能在500微米的深度范围内以小于2微米的误差估算焦平面。整个对焦过程在0.1秒内完成，速度提升300倍，成功实现对多种样本长达数天的高速三维持续成像。","scd":null,"kp":[]},{"i":38130,"as":"细菌性败血症是导致新生儿死亡的主要原因，MR1T细胞通过识别细菌病原体发挥保护作用。通过单细胞RNA测序和TCR库分析发现，与成年人相比，新生儿脐带血中的MR1T细胞具有更高的TCR多样性，但细胞毒性、促炎基因表达以及细菌识别能力均有所降低。结构分析显示，新生儿MAIT TCR的β链结合力下降。","scd":null,"kp":[]},{"i":38131,"as":"研究发现拟南芥干种子胚胎中积累了组蛋白变体H2B.8，其通过形成空间簇结构参与染色质高级组织。H2B.8主要组装成异型核小体，富集在常染色质转座子中。种子吸胀期间，水分吸收触发H2B.8转录减少。该变体以不依赖复制的方式从染色质中排出，从而调节部分靶基因的转录激活，完成染色质重塑。","scd":null,"kp":[]},{"i":38132,"as":"HSV-1起源结合蛋白UL9在病毒双链DNA基因组复制起始中的作用机制一直备受关注。通过单分子技术直接测试发现，UL9并不能有效地使起源序列oriS成环，否定了先前的假设。然而，数据证明UL9能在非起源序列处极其高效地形成分子间DNA系链和大型分子内DNA环，这为理解疱疹病毒复制机制提供了新见解。","scd":null,"kp":[]},{"i":38133,"as":"为开发利用粘细菌的生物合成基因簇，研究人员开发了高效的基因编辑工具包并构建了异源表达底盘。在黄色粘球菌中，重组酶MxRecET与核酸酶TnpB协同作用，实现了两周内无缝删除高达200kb的大片段DNA、双位点串联编辑以及灵活的单核苷酸替换。该技术极大促进了粘细菌天然产物的挖掘与改造。","scd":null,"kp":[]},{"i":38134,"as":"在复制偶联的DNA双链断裂（DSB）修复中，53BP1-Shieldin复合物的作用尚不明确。研究发现，在BRCA1 BRCT结构域缺陷的细胞中，Shld2或Shld3的缺失（而非53bp1）能赋予PARP抑制剂抗性。Shld2/3的删除以不依赖53BP1的方式，通过CST复合物部分恢复同源重组，减少插入/缺失特征，并促进RAD51的加载。","scd":null,"kp":[]},{"i":38135,"as":"研究发现雄性小鼠下丘脑室旁核中表达一氧化氮合酶1（Nos1）的神经元是控制全身脂肪消耗的关键节点。这些神经元通过交感神经系统向骨骼肌和脂肪组织传递信号。激活PVH中的Nos1神经元可诱导白色脂肪脂解和脂肪氧化，增加全身脂肪消耗；而抑制这些神经元则会消除脂肪消耗的增加。","scd":null,"kp":[]},{"i":38136,"as":"现有时间序列空间转录omics（ST）轨迹推断方法难以维持相邻生物结构单元（如卵泡、肾小管）的完整性。为此，研究人员提出了一种基于最优传输的时空连续结构轨迹推断方法（SOCS）。该方法有效解决了传统分析产生的生物学轨迹不连贯问题，能够准确推断并保留连续生物结构在发育过程中的完整性。","scd":null,"kp":[]},{"i":38137,"as":"一项包含超过360万确诊SARS-CoV-2感染成年人的智利全国回顾性队列研究表明，发展为重症COVID-19并住院的患者，在一年内发生结核病的风险是非重症患者的八倍以上。SARS-CoV-2疫苗接种改变了这一关联，未接种新冠疫苗的人群面临更高的结核病发病风险。","scd":null,"kp":[]},{"i":38138,"as":"基于对1513株临床分离株的10年监测和全球60724个基因组的精细分析，鉴定出一种广泛传播的耐碳青霉烯类肺炎克雷伯菌（CRKP）ST11-KL64亚系。该亚系携带编码高毒力因子的质粒，表现出增强的侵袭能力。尽管其引发的侵袭性感染病例增多，但并未增加患者死亡率。","scd":null,"kp":[]},{"i":38139,"as":"研究表明全球板块构造历史塑造了深海热液喷口化能自养微生物的生物地理分布。这些微生物（尤其是厌氧菌）在起源较早的太平洋、北冰洋和地中海中丰度显著较高，而在晚形成的太西洋和印度洋中极为罕见。其原因在于后两个海洋形成时的显生代充分氧化环境对厌氧菌造成了氧气毒性和能源耗竭的双重扩散屏障。","scd":null,"kp":[]},{"i":38140,"as":"人类APOBEC3（A3）蛋白通过诱导病毒cDNA过度突变来限制逆转录病毒感染，而HIV-2通过病毒感染因子（Vif）拮抗A3蛋白。研究展示了HIV-2 Vif与人A3H及CBFβ复合物的冷冻电镜结构。A3H通过dsRNA介导形成二聚体，Vif-A3H和CBFβ-A3H界面对A3H降解至关重要，且HIV-2 Vif-A3H的结合界面完全不同于HIV-1。","scd":null,"kp":[]},{"i":38141,"as":"为扩展半机械昆虫的活动范围，研究人员研发了一款供陆地昆虫穿戴的微型潜水服。该装备集成了微型氧气生成模块和柔性防水外壳，能持续供氧并隔绝水分。穿戴该装备的蟑螂在水下缺氧环境中成功存活并行动长达3小时，被转化为能在水陆两栖环境中跨介质操作的半机械蟑螂。","scd":null,"kp":[]},{"i":38142,"as":"为阐明人类内分泌胰腺的早期发育，研究人员收集了123例出生至十岁期间的儿童胰腺样本。利用共聚焦显微镜和多重成像技术，构建了内分泌细胞形成和胰岛结构的综合模型。该模型详尽绘制了内分泌细胞的异质性、丰度、增殖以及胰岛血管化与神经支配的组织学和功能成熟过程。","scd":null,"kp":[]},{"i":38143,"as":"为从心脏MRI中高效提取表型，研究开发了3D扩散自编码器模型，从71017名参与者的数据中提取了潜在表型。这些表型具有可重复性和遗传性（遗传度4-18%），且与心脏代谢特征显著相关。全基因组关联分析识别出42个基因座的89个显著常见变异（含7个新基因座），证实了这些心脏MRI性状具有共同的遗传基础。","scd":null,"kp":[]},{"i":38144,"as":"多组分自由基途径直接对映选择性构建多取代无环烯烃是有机化学中的一大挑战。本文报道了一种钴催化的末端炔烃、酮亚胺和非活化烷基碘化物的不对称三组分自由基加成反应。该反应高效生成了具有四取代立体中心的多元取代烯丙基胺衍生物，为复杂分子的快速组装提供了有效策略。","scd":null,"kp":[]},{"i":38145,"as":"研究通过实验证实，大气等离子体诱导的化学还原反应能够产生与光化学过程截然不同的汞同位素非质量分馏（MIF）。等离子体反应产生的奇数汞同位素MIF（Δ199Hg跨度从-78‰到+28‰）远大于光还原过程。此外，MIF的符号会随溶液pH值的改变发生逆转，这源于等离子体生成物质间的竞争作用。","scd":null,"kp":[]},{"i":38146,"as":"","scd":null,"kp":[]},{"i":38147,"as":"该研究提出了一种将生物质衍生的2,3-丁二醇转化为高附加值化学品和航空燃料的优化工艺。针对2,3-丁二醇与水分离难的问题，采用反应萃取法形成二氧戊环，并通过原位生成异丁醛免除对外源醛的需求。技术经济与生命周期评估显示，该燃料和化学品生产方案可使二氧化碳排放量减少58%。","scd":null,"kp":[]},{"i":38148,"as":"传统电池健康状态多依赖于容量跟踪，但实际应用中能量是更关键的指标。本研究建立并验证了一个理论框架，阐明了电池能量与容量差异之间的机制联系。该框架证实，这种指标偏离与特定的电池退化模式直接相关，并受到电极化学性质、操作机制、动力学和放电深度的综合影响。","scd":null,"kp":[]},{"i":38149,"as":"卡宾锰(II)配合物能够在溶液（141 K）和固态（112.5 K）下通过光诱导激发态自旋捕获实现低自旋到高自旋的定量转变。实验数据表明，在77 K温度下，其亚稳态高自旋状态的寿命超过100万年。这种超长寿命主要归因于高金属-配体键共价性带来的高重组能。","scd":null,"kp":[]},{"i":38150,"as":"研究提出了一种无需金属的逆向主动模板合成轮烷的方法。柔性聚乙二醇轴可通过氢键促进大环化反应中的酰胺键形成，从而围绕自身构建大环，以最高70%的产率合成[2]轮烷。更长的分子轴能够实现多环组装，X射线晶体结构证实了由芳香堆叠和氢键稳定的拥挤螺旋堆叠结构。","scd":null,"kp":[]},{"i":38151,"as":"研究人员通过拓扑合成子方法（即过度纽结的延伸与大环化），成功合成了具有窄多分散性和可调拓扑参数的闭环三叶状聚合物。利用相同的结构单元制备了线性、环状和三叶状拓扑异构体，以直接研究拓扑与性质的关系。扫描隧道显微镜成功解析了三叶状聚苯乙烯的三种构象。","scd":null,"kp":[]},{"i":38152,"as":"基于半硫靛蓝的分子电机由可见光驱动旋转。通过对其结构进行细微改变，分子电机在运行过程中意外产生了一种“超级充电”中间体。这种结构上的偶然变化使得分子电机能够有效储存太阳光的能量，突破了该类电机十年来未能利用此储能特性的局限。","scd":null,"kp":[]},{"i":38153,"as":"《科学进展》发表的研究报道了一种完全可生物吸收的电子绷带。该设备采用基于MXene的电极，能够从糖尿病组织中收集葡萄糖生化能量，并利用该能量恢复伤口边缘的电场，从而有效加速糖尿病伤口的修复过程。","scd":null,"kp":[]},{"i":38154,"as":"随着极右翼政党德国选择党在全国和各州选举的民调中领先，德国科研机构正面临应对该党提出限制学术自由计划的挑战。科学家们正在发起反击，抵制极右翼限制学术自由的计划，维护科研领域的学术独立性。","scd":null,"kp":[]},{"i":38155,"as":"一部新上映的纪录片探讨了美国科研经费削减和拨款延迟所带来的人力成本。科学研究是一项涉及艰苦努力且高度互联的人类事业，资金短缺和项目延期对美国众多科研人员造成了沉重打击，严重影响了科研生态的运转。","scd":null,"kp":[]},{"i":38156,"as":"Marisa Chrysochoou和Keivan Stassun提出，人工智能工具能够有效帮助神经多样性学生应对学术界不成文的规则（即“隐性课程”）。他们认为，AI可以作为重要的辅助手段，引导这些学生顺利度过学术生涯中的各种隐性挑战。","scd":null,"kp":[]},{"i":38157,"as":"由于受到美国DOGE（政府效率部门）削减经费的影响，科学家Sarah Weisberg与许多其他科研人员一样，为了寻求更稳定的职业保障，选择离开美国前往欧洲工作和生活，反映出当前科研人才因资金问题向海外流失的趋势。","scd":null,"kp":[]},{"i":38158,"as":"面对研究人员对美国大规模人工智能研发计划的质疑，Darío Gil承担着将特朗普政府宏大的AI和量子计算 ambition 转化为现实的重任。他呼吁科研界保持开放态度，共同审视并推进这些重大科技发展目标。","scd":null,"kp":[]},{"i":38159,"as":"多肽目前是健康保健领域最热门的趋势之一，且无监管的多肽市场规模庞大。本期《自然》长篇音频探讨了这种多肽热潮背后的科学依据，客观分析了相关的科学承诺与当前市场炒作之间的真实差距。","scd":null,"kp":[]},{"i":38160,"as":"在菱形多层石墨烯中发现了磁场增强的超导现象。输运测量表明，四层和五层石墨烯表现出多种纯净极限超导性，其中五层石墨烯中存在三种不同的磁场增强和磁场诱导的超导态。这些超导态在高达8特斯拉的面内磁场下依然保持稳定。","scd":null,"kp":[]},{"i":38161,"as":"康涅狄格大学校长Radenka Maric分享了该校向可持续校园转型的历程。这一转型主要依赖于治理结构的完善、基础设施项目的建设，以及旨在培养学生可持续发展素养的教育倡议，全面展示了高校在可持续发展方面的实践。","scd":null,"kp":[]},{"i":38162,"as":"研究表明，异化碘酸盐还原微生物活跃于海洋最低含氧区（OMZs）。通过分析代表性菌株发现，IO3−的还原滞后于NO3−的还原。研究证实了功能基因idrABP1P2在OMZs中的广泛分布与表达，表明这些微生物栖息于该区域并促进了碘离子的生产与积累。","scd":null,"kp":[]},{"i":38163,"as":"基于2013至2022年的家庭面板数据和高分辨率气候数据，对吉尔吉斯斯坦的研究表明，极端天气事件显著影响人类流动性。区域内外的极端天气与国际移民和不移民（受困）状态的关联度，高于国内流动及国内外结合的流动性。不同家庭和地点的响应存在显著差异。","scd":null,"kp":[]},{"i":38164,"as":"研究提出在镜像增强的等离激元纳米颗粒阵列中实现超高Q值（品质因数）的非局域共振。这种高Q值共振对于增强纳米尺度上的光与物质相互作用至关重要，在无标记生物传感、低阈值激光器和量子信息处理等光谱选择性应用中具有关键作用。","scd":null,"kp":[]},{"i":38165,"as":"基于扫描隧道显微镜在Fe(Te,Se)薄片中发现的对密度调制（PDM）现象，研究人员开发了一种朗道理论来阐明其物理起源。该理论通过螺旋转动和滑移对称性对PDM进行了深入分析，为理解该材料的复杂超导机制提供了理论框架。","scd":null,"kp":[]},{"i":38166,"as":"核子动量分布揭示了关于费米运动和短程关联的关键信息。研究提出了一种从包容性电子散射数据中提取复杂原子核NMDs的方法，改进了传统的标度分析等理论手段，实现了对复杂原子核内部核子动量分布的一致性处理。","scd":null,"kp":[]},{"i":38167,"as":"通过详细比较48Ca、90Zr、132Sn和208Pb等中重质量双闭壳母核中Gamow-Teller强度分布的实验与理论数据，推导出了猝灭因子Q以及对应的朗道-米格达尔参数g′的具体数值，深化了对原子核内自旋相关相互作用的理解。","scd":null,"kp":[]},{"i":38168,"as":"超相对论性重离子碰撞的早期阶段可描述为高密度胶子体系（即胶子玻璃态）。研究探讨了与该系统角动量相关的物理特性，特别是垂直于反应平面的全局角动量，为理解早期宇宙或高能碰撞中夸克胶子等离子体的演化提供了理论见解。","scd":null,"kp":[]},{"i":38169,"as":"本文提出一种数据驱动的深度学习框架，用于预测美国布鲁克海文国家实验室RHIC对撞机能量下金核-金核（Au+Au）碰撞中的多个集体观测量。该框架仅使用带电粒子横向动量等参数的实验测量数据对单一神经网络进行训练，实现了高效、准确的预测，展示了深度学习在重离子碰撞物理中的应用潜力。","scd":null,"kp":[]},{"i":38170,"as":"本文在准粒子模型和多反射展开法的基础上，研究了强磁场环境下矢量相互作用对夸克物质表面张力与稳定性的影响。研究采用了自洽的热力学方法处理化学势相关的夸克质量，深入分析了矢量相互作用在强磁场下对夸克物质特性的具体作用机制。","scd":null,"kp":[]},{"i":38171,"as":"BESIII合作组利用北京正负电子对撞机BEPCII上的BESIII探测器在2009、2012、2018和2019年收集的约100.87亿个J/ψ事件，对Ξ⁰核子散射中的Ξ⁰n→ΛΛX反应进行了实验搜索研究，其中X代表任意额外的末态粒子。该实验为探索超子-核子相互作用提供了重要数据。","scd":null,"kp":[]},{"i":38172,"as":"BESIII合作组利用在BEPCII对撞机上收集的27亿个ψ(3686)事件数据样本，在ψ(3686)→Ξ(1530)⁰Ξ(1530)⁰衰变中首次观测到了Ξ(1530)⁰的极化现象，其统计显著度极高。基于该极化现象，研究团队进一步确定了Ξ(1530)⁰重子的电偶极矩和磁偶极矩。","scd":null,"kp":[]},{"i":38173,"as":"本文研究了过渡金属硫族化物家族中2H-NbSe2和2H-TaS2在超薄极限下的超导性质。尽管此前的隧穿测量表明其仅存在单一超导能隙，但本文通过实验深入揭示了少层NbSe2和TaS2中存在的双能隙超导特性，进一步加深了对该类材料超导微观机制的理解。","scd":null,"kp":[]},{"i":38174,"as":"本文在欧洲核子研究中心（CERN）的ISOLDE设施上，研究了质子滴线附近的铯-116（¹¹⁶Cs）的多重衰变性质。实验成功识别出氙-116（¹¹⁶Xe）的六种以上新非束缚态，并首次观测到低能量同标量八极共振现象。此外，研究还分析了质子衰变后的后续退激过程及特征。","scd":null,"kp":[]},{"i":38175,"as":"研究团队在全连通、可调耦合的超导量子处理器上，成功实现了量子姆佩巴效应（Quantum Mpemba Effect）的观测与调控。该研究展示了在量子系统中，远离平衡态的系统比更接近平衡态的系统可以更快地恢复到平衡状态，证实了这种反常弛豫现象的存在。","scd":null,"kp":[]},{"i":38176,"as":"本文证明在量子处理器中引入中途测量和基于测量结果的反馈操作，不仅对于实现量子纠错至关重要，而且将其整合到量子多体动力学中时，能够引发出新型非平衡相变。研究展示了这种测量与反馈驱动的动力学在单个实例层面和物理观测层面均会引发这种相变现象。","scd":null,"kp":[]},{"i":38177,"as":"本文研究了群体运动混合物中的分离机制，指出非互易性是导致解混的普遍机制。通过结合二元Vicsek模型的数值模拟和粗粒化连续介质方程分析，研究证明，即使是微弱的非互易对齐作用，也会破坏由互易对齐形成的有序相，从而在群体混合物中引发大规模的斑图结构形成。","scd":null,"kp":[]},{"i":38178,"as":"本文在马氏体合金中观察到了一种前所未有的现象：通过纳米级位移相变，马氏体状态能够表现出几乎与温度无关的弹性模量（即恒弹性效应）。这不同于铁弹性合金在马氏体相变前发生模量软化并在相变完成后呈现正常冷硬化效应的传统规律，为新弹性材料设计提供了思路。","scd":null,"kp":[]},{"i":38179,"as":"本文提出了一种用于异质有限尺寸自组装体系通用逆向设计的框架。该框架利用基于梯度的优化方法，对解析产率计算进行求逆，从而将系统调节至目标平衡产率。研究成功设计了从简单二聚体到复杂异质组装体等多种自组装系统，有效解决了软物质与生物领域的系统设计难题。","scd":null,"kp":[]},{"i":38180,"as":"为解决水系锌离子电池中锌负极固体电解质界面（SEI）不稳定的问题，本文通过引入Na₂TeO₃电解液添加剂，在锌负极上原位形成了一种仿生细胞壁结构的SEI。其中，基于碲的无定形基质能够适应锌离子传输过程中的体积变化，镶嵌的功能性纳米晶（Na₂Zn₂(TeO₃)₃和ZnTe）则显著增强了SEI的硬度并提供离子通道，从而实现高性能水系电池。","scd":null,"kp":[]},{"i":38181,"as":"针对水系锌离子电池中凝胶电解质与电极界面接触不良和电荷分布不均的问题，本文提出了一种面对面的电子通道调控策略。通过热压工艺将聚丙烯酰胺凝胶电解质与商用导电碳布集成，该工程化凝胶电解质促进了电极表面电荷的快速转移，有效均匀化了界面电场并降低了局部电流密度，从而构建出高度可逆的锌电池。","scd":null,"kp":[]},{"i":38182,"as":"受海洋褐藻碘调节能力的启发，本文开发了一种多功能水凝胶电解质，用于解决水系锌碘电池中的锌枝晶和聚碘化物穿梭问题。该电解质将岩藻多糖（一种硫酸化多糖）引入聚合物网络中。与传统的吸附策略不同，岩藻多糖中的硫酸基团通过静电排斥将聚碘化物限制在正极界面，从源头上抑制穿梭效应，结合酰胺基团的捕获作用，实现了协同稳定机制。","scd":null,"kp":[]},{"i":38183,"as":"本期简报重点介绍了CRISPR技术的下一个突破性应用阶段：利用表观基因组编辑来治疗相关疾病。此外，简报还涉及了全新“世界最快超级计算机”的诞生，并探讨了如何在人生的逆境中取得成功。","scd":null,"kp":[]},{"i":38184,"as":"本文研究了Hedgehog（Hh）信号通路中关键致癌蛋白Smoothened（SMO）G蛋白偶联受体的配体激活机制。研究明确了G蛋白和胆固醇（CHL）配体结合到SMO上的序列。结果表明，SMO遵循“G蛋白优先”的激活路径：胆固醇首先结合到SMO的富含半胱氨酸结构域，随后G蛋白自发结合形成预偶联复合物；当PTCH脱离后，SMO被最终激活。","scd":null,"kp":[]},{"i":38185,"as":"本文结合大规模生物信息学分析和病毒学实验，评估了SARS-CoV-2多碱基弗林蛋白酶切割位点（FCS）与小鼠适应型MERS-CoV MA30毒株之间的遗传联系假说。对超过1700万个SARS-CoV-2基因组的分析表明，对应RRVR序列的S:684V替换仅零星出现且未成为系统发育基底。反向遗传学实验证实，S:684V变体持续降低了病毒的进入效率和竞争力，否定了两者间的直接关联。","scd":null,"kp":[]},{"i":38186,"as":"受自然形态发生的启发，本文提出了一种名为RDGenCAD的形态发生设计框架，突破了传统基于晶胞的架构材料设计限制。该框架将可编程生长规则转化为反应-扩散动力学，生成自组织的CAD模型。基于12万个结构的数据表明，尽管几何形状高度不规则，其弹性性能在拉胀和常规区间内具有统计学确定性和连续可调性，且通过应力区隔化表现出对缺陷的极度不敏感和裂纹偏转能力。","scd":null,"kp":[]},{"i":38187,"as":"本文针对人类脑内呈薄片状的屏状核，构建了三维组织学“黄金标准”模型，并以此系统评估了三个7特斯拉超高场MRI数据集。研究表明，以往基于MRI的屏状核形态学研究中出现的巨大差异，主要源于分辨率依赖效应而非对比度限制。高分辨率成像揭示了该结构在个体间的变异性以及双侧的细微不对称性。","scd":null,"kp":[]},{"i":38188,"as":"本文探讨了进化上保守的WIP转录因子家族在苔藓（小立碗藓）生活史两个阶段中的功能。研究解析了PpWIP1和PpWIP2基因在配子体阶段的作用，证明了这些调节因子不仅控制着被子植物的根和花发育，还能调控苔藓配子体的发育进程，表明WIP转录因子在陆地植物不同生活史阶段的形态演化中均发挥着关键的调节作用。","scd":null,"kp":[]},{"i":38189,"as":"研究团队引入了一种双人觅食范式，用于探究共同决策中的妥协行为和责任归因。该实验要求两名参与者在存在风险的环境下共同选择能带来奖励的地点，并互相评估对共享结果的责任。这项研究通过设计特定的实验模型，解析了人们在联合决策时何时妥协、如何评估同伴责任，并深入揭示了这些过程背后的计算与心理机制。","scd":null,"kp":[]},{"i":38190,"as":"针对AI生成的人脸深度伪造技术威胁，研究团队提出了一种全新的人类训练方法。不同于以往依靠特定视觉伪影识别的方法，该研究利用了人类对人脸的整体感知差异。通过训练参与者关注AI与人脸产生的系统性不同感知印象，有效提升了人类识别未经训练的AI生成人脸的能力，克服了算法检测的不透明性和脆弱性问题。","scd":null,"kp":[]},{"i":38191,"as":"蕨类植物通常具有庞大的基因组和极高的染色体数量。研究团队对具有最小基因组的槐叶苹和被认为是异源五倍体的入侵种细叶满江红进行了染色体水平的基因组组装。研究结果出乎意料地发现，细叶满江红实际上是二倍体杂种。这一发现揭示了槐叶苹属在基因组大小和染色体数量上的巨大差异，重塑了当前对蕨类植物染色体进化的理解。","scd":null,"kp":[]},{"i":38192,"as":"RNA聚合酶III（Pol III）负责高通量合成短链RNA。 Rpc34亚基的带翼螺旋结构域（WH2）在转录延伸过程中的作用一直是个谜。研究团队利用单分子荧光共振能量转移和纳米定位三角测量技术，在具有转录活性但不进行移位的Pol III延伸复合物中，成功解析了Rpc34-WH2结构域的动态变化和具体空间位置，阐明了该结构域在稳定延伸复合物以及促进转录重新启动中的关键作用。","scd":null,"kp":[]},{"i":38193,"as":"近期研究通过生物记录、声学监测和分子分析证实了大型夜蝠会捕食夜间迁徙的雀形目鸟类。这一发现建立在过去二十年对蝙蝠粪便中鸟类羽毛残留物的分析之上，其捕食高峰期与鸟类迁徙期完全吻合。研究还指出，著名画家布鲁盖尔在其画作中早已描绘了夜蝠捕食鸟类的场景，这表明人类对蝙蝠食鸟行为的自然史认知比现代科学记录要早得多。","scd":null,"kp":[]},{"i":38194,"as":"为了深入理解紫色细菌极高的太阳能收集量子效率，研究团队利用二维电子光谱（2DES）技术解析了完整细胞内光合作用复合体之间的能量传递过程。由于活体系统高度复杂，室温下的光谱往往严重重叠，而2DES技术通过在光谱的第二维度解析激发能量，成功区分了不同子系统并理清了它们在完整细胞内的相互作用响应。","scd":null,"kp":[]},{"i":38195,"as":"为解决公共大语言模型在预测蛋白质功能方面的不足，研究团队开发了BetaDescribe模型。该模型直接将蛋白质序列作为输入，生成包含功能、催化活性、参与的特定代谢途径、亚细胞定位以及特定结构域存在情况的详细丰富文本描述。该技术有效克服了传统实验表征资源密集型的问题，为生物信息学中的蛋白质功能解析提供了高效的计算工具。","scd":null,"kp":[]},{"i":38196,"as":"整合素连接激酶（ILK）和Kindlin-2（K2）是调节细胞基质黏附的关键焦点黏附组分。研究结合生物化学、细胞生物学和超分辨率显微镜建立了一套高灵敏度工作流，成功区分了细胞内的直接与间接分子相互作用。研究证实，ILK与β1整合素的结合并非直接发生，而是由Kindlin-2介导的间接相互作用。破坏ILK-K2相互作用会减少ILK在焦点黏附处的定位并损害整合素功能，但不影响K2的募集。","scd":null,"kp":[]},{"i":38197,"as":"传统观点常使用分子遗传多样性（如核苷酸多样性）来推断种群的短期适应潜力。然而研究证实，分子遗传多样性与反映可加性遗传变异的遗传力之间仅存在微弱联系。即便测序技术进步使得研究重点转向功能区域的核苷酸多样性，其作为短期适应潜力预测指标的表现依然不佳。这一结论表明，仅凭核苷酸多样性无法准确预测种群在变化环境下的适应与生存能力。","scd":null,"kp":[]},{"i":38198,"as":"拟肽作为宿主防御肽的类似物具有广谱抗菌活性。研究团队利用单细菌细胞时间分辨荧光显微镜和单颗粒追踪技术，探究了12聚体拟肽TM1及其类似物的作用机制。研究发现，这些拟肽能够迅速穿透细菌细胞膜，并引发细胞质内大分子阴离子（包括核糖体和DNA）的絮凝与硬化，从而实现对细菌的快速杀灭，揭示了拟肽动态杀菌的物理化学机制。","scd":null,"kp":[]},{"i":38199,"as":"研究团队利用结构预测方法评估了由5至60个氨基酸随机重复序列组成的约120个氨基酸长度序列的可折叠性。结果显示，在少于30个氨基酸的重复序列中，有1%至12%的序列能够以高置信度稳定折叠。当重复序列少于60个氨基酸时，常观察到与天然蛋白质相似的β-螺旋结构。这些螺旋结构不仅可以通过非极性堆积稳定，还能通过核心区域与钙离子（Ca2+）的极性相互作用来维持稳定。","scd":null,"kp":[]},{"i":38200,"as":"气候变化加剧了干旱对温带森林的胁迫，但研究团队通过分析欧洲221个欧洲水青冈种子生产的时间序列发现，干旱并未降低树木的繁殖能力。研究将繁殖过程划分为开花、授粉和种子成熟阶段，结果表明夏季干旱不会削弱种子产量，而干燥的春季条件反而通过促进花粉扩散增加了种子产量。一旦繁殖启动，即使遭遇极端干旱（如2003、2018和2022年），当年的 reproduction 乃至次年的繁殖均不会受到抑制。","scd":null,"kp":[]},{"i":38201,"as":"研究团队开发了一种名为RUNA（可逆尿苷腈鎓介导加成）的可逆共价化学反应。该技术通过N3去质子化以及由醛和异腈生成的腈鎓离子中间体，选择性地修饰尿苷和胸苷残基，形成的稳定N3加合物可通过水解完全逆转。借助膜通透和非通透性试剂，该技术成功揭示并证实了外泌体表面存在DNA分子，为核酸结构、定位及功能研究提供了新的标记工具。","scd":null,"kp":[]},{"i":38202,"as":"研究团队对1075项研究中超过1200种海洋范围扩展物种的种群效应进行了全球综合分析，旨在建立预测物种扩张生态效应的框架。分析表明，类似生物入侵理论，扩展物种对接收种群产生的生态影响可以通过其历史生态角色和营养级来进行可靠预测。这些物种在扩张前历史分布区内的作用能够准确预示其在全新分布区内的生态影响。","scd":null,"kp":[]},{"i":38203,"as":"长期以来，旧石器时代晚期的北美洲克洛维斯文化一直被假定使用投矛器狩猎大型动物。研究团队对全新世保存的投矛器进行了放射性碳年龄的模型分析，结果否定了克洛维斯人使用投矛器的假设。如果克洛维斯人不使用该技术，那么其在美洲早全新世的出现属于技术趋同演化。这要求学界重新评估当时猎人使用长矛或弓箭等武器的狩猎效率、风险及战术模型。","scd":null,"kp":[]},{"i":38204,"as":"","scd":null,"kp":[]},{"i":38205,"as":"","scd":null,"kp":[]},{"i":38206,"as":"肥厚型心肌病（HCM）的致病基因变异会导致心脏异常肥大、收缩和舒张功能障碍及能耗异常。研究团队通过绘制233个变异（包括MYH7、MYBPC3、MYL2和MYL3基因的错义变异），定义了这些致病变异和良性变异在结构上的具体后果。研究证实，肌球蛋白重链等相关蛋白质形成的粗丝分子界面在肥厚型心肌病的发病机制中起着核心关键作用。","scd":null,"kp":[]},{"i":38207,"as":"","scd":null,"kp":[]},{"i":38208,"as":"","scd":null,"kp":[]},{"i":38209,"as":"","scd":null,"kp":[]},{"i":38210,"as":"","scd":null,"kp":[]},{"i":38211,"as":"","scd":null,"kp":[]},{"i":38212,"as":"","scd":null,"kp":[]},{"i":38213,"as":"","scd":null,"kp":[]},{"i":38214,"as":"研究团队通过思想实验重建了自1950年以来的平流层臭氧观测模型，以探究人为臭氧损耗最早在何时可被检测到。结果显示，人类活动导致的臭氧损耗最早在1957年就可以在热带上平流层被识别出来。该区域较低的自然变率使得早期人为氯氟烃排放造成的微小臭氧损失足以被检测到。这比1985年南极臭氧空洞的正式报告提前了近三十年。","scd":null,"kp":[]},{"i":38215,"as":"","scd":null,"kp":[]},{"i":38216,"as":"","scd":null,"kp":[]},{"i":38217,"as":"","scd":null,"kp":[]},{"i":38218,"as":"","scd":null,"kp":[]},{"i":38219,"as":"","scd":null,"kp":[]},{"i":38220,"as":"计划烧除是维护森林韧性的重要手段，并有助于减少后续野火的排放，但其本身也会产生烟雾。研究团队开发的数学模型表明，在当前全球大多数环境条件下，计划烧除产生的细颗粒物（PM2.5）排放量很少能被后续减少的野火排放所抵消，因此总体上反而增加了PM2.5总排放。对73个研究站点的分析证实，以往研究中所报告的净排放减少往往具有局限性。","scd":null,"kp":[]},{"i":38221,"as":"研究团队利用经过验证的模型，量化了洛杉矶帕利塞兹地区露天空间植被管理与家庭点燃区（HIZ）缓解措施的空间分布对遏制城市大火的有效性。露天空间的燃料管理涉及特定比例的植被疏伐，而HIZ缓解则包括加固建筑特征和清除可燃物。研究通过对比随机和针对性干预策略，证实了结合空间分布特征的联合管理能够显著改变火灾蔓延边界并减少建筑环境的破坏。","scd":null,"kp":[]},{"i":38222,"as":"","scd":null,"kp":[]},{"i":38223,"as":"辐鳍鱼占现存脊椎动物一半以上，但其早期演化史仍未完全理清。研究团队利用X射线微型计算机断层扫描技术，对石炭纪早期的辐鳍鱼进行了分析。结果显示了出人意料的神经颅骨和神经软组织形态特征：该物种拥有一个能够紧密贴合脑颅腔的大型大脑。这一发现颠覆了早期鱼类脑化石极小而使得颅腔铸型无法准确反映神经解剖粗略形态的传统观点。","scd":null,"kp":[]},{"i":38224,"as":"","scd":null,"kp":[]},{"i":38225,"as":"布鲁顿酪氨酸激酶（BTK）是一种对B细胞激活至关重要的非受体酪氨酸激酶。研究提出了一种原生质谱平台，通过定制靶向脂质双分子层，直接探究和理解脂质介导的外周膜蛋白（PMP）的募集机制。该技术成功捕获并揭示了PMP与细胞膜之间微弱且动态的低亲和力相互作用，为研究PMP的膜招募及激活机制提供了技术支撑。","scd":null,"kp":[]},{"i":38226,"as":"","scd":null,"kp":[]},{"i":38227,"as":"JP2蛋白在产热棕色脂肪组织（BAT）中富集，但在营养过剩条件下表达下调。在脂肪细胞尤其是BAT中条件性敲除JP2会加剧寒冷不耐受和饮食诱导的肥胖易感性。机制上，缺失JP2的棕色脂肪细胞表现出钙离子处理功能障碍：基线胞质钙水平升高，而去甲肾上腺素诱导的钙瞬变减弱，导致钙库操纵性钙内流减少。研究揭示了JP2通过调节钙信号体维持棕色脂肪细胞产热和能量代谢。","scd":null,"kp":[]},{"i":38228,"as":"当前全球昆虫物种数量约600万的共识被严重低估。研究基于哥斯达黎加ACG保护区的15个“核心”马氏陷阱，采集了代表53,945个物种的160多万份DNA条形码昆虫样本。为估算ACG昆虫总丰富度，研究利用寄生蜂亚科的“欠采样比例”对观察到的物种数量进行了校准。这种基于海量经验数据的下限估算方法，为推断全球昆虫物种总数提供了新的可靠依据。","scd":null,"kp":[]},{"i":38229,"as":"泛北极（北纬60至90度）自然甲烷排放对气候变暖的敏感性长期缺乏直接观测约束。长期大气测量表明，泛北极秋冬甲烷积累的“秋季零交叉日期”呈现提前趋势。这一趋势是由7月至9月气候变暖导致北极自然甲烷排放增加所致。在1998年至2020年期间，甲烷排放的增长率为0.14 ± 0.04 Tg CH4/年。","scd":null,"kp":[]},{"i":38230,"as":"研究发现，与居住在共和党聚集区的共和党人相比，居住在民主党人聚集区的共和党人报告了更高水平的焦虑、抑郁和孤独感。民主党人总体心理健康状况差于共和党人，但对党派居住环境不敏感。通过对居住在同一邮编区的党员进行大规模调查并控制其他个体特征后，上述模式依然成立。这种相关性在党派立场最坚定的人群中最强，政治环境是影响心理健康关系的重要因素。","scd":null,"kp":[]},{"i":38231,"as":"蛋白质稳态（Proteostasis）对维持蛋白折叠、运输和降解至关重要，神经元因其有丝分裂后和长寿特性极易发生稳态崩溃。研究构建了人兴奋性神经元和小鼠胶质细胞的双物种共培养模型，利用DIA LC-MS/MS蛋白质组学技术，研究了发育和成熟过程中蛋白质稳态网络的细胞特异性变化。通过监测ATF6、IRE1/XBP1下游效应蛋白，量化了未折叠蛋白反应（UPR）的分支特异性激活，揭示了细胞类型特异性的成熟反应。","scd":null,"kp":[]},{"i":38232,"as":"食欲素神经元调节能量稳态、觉醒和动机行为等生理功能。在转基因大鼠中利用化学遗传学、光纤光度法和光遗传学技术进行实验发现，激活食欲素神经元会增加对奖励的动机。在动机行为中，神经元活动动态变化：在奖励预测期间活动增加，在获得奖励后活动降低。当发生未获得预期奖励的意外事件时，神经元活动增加。研究表明食欲素神经元在动机行为中负责编码奖励预测。","scd":null,"kp":[]},{"i":38233,"as":"研究在苔原天鹅中鉴定出三个几乎全长的SARS-CoV-2变异株病毒基因组序列，分别命名为IMCAS_M1、IMCAS_M2和IMCAS_M3。其中，IMCAS_M1和IMCAS_M3在病毒刺突蛋白受体结合域（RBD）上具有与Beta变异株相同的突变（K417N、E484K和N501Y）；IMCAS_M2的RBD突变与Gamma变异株相同（K417T、E484K和N501Y）。这三种序列在基因组中均显示出独特的突变，提供了候鸟携带SARS-CoV-2的基因组证据。","scd":null,"kp":[]},{"i":38234,"as":"二维材料因其尺寸效应，传统的马氏体相变因高能量屏障而难以实现。研究调查了单层二维二碲化钼（MoTe2）的相变过程，发现了一种一维多米诺骨牌式的相变机制。该机制有效克服了二维过渡金属二硫族化物（TMDCs）中存在的高能垒挑战，实现了对材料物相的精准调控，为二维材料的微观相变机理实验研究和物理属性调控提供了新途径。","scd":null,"kp":[]},{"i":38235,"as":"量子自旋霍尔（QSH）效应因其无磁场操作、自旋动量锁定和拓扑电场可调等特性，被视为超低功耗、超快电子学、自旋电子学和拓扑量子计算的理想平台。然而，QSH状态在实验上的实现仍局限于少数材料和器件几何形状中，且通常需在低温和有限长度尺度下运行。文章重新评估了2D拓扑绝缘体在实验实现中面临的挑战，并对其未来在自旋电子学等领域的应用前景进行了展望。","scd":null,"kp":[]},{"i":38236,"as":"高熵过渡金属硫化物（HESs）因熵稳定、晶格畸变和鸡尾酒效应成为钠离子电池负极的重要材料，但多组分不相容导致的相分离限制了其性能。研究提出低混合焓策略，通过调节元素化学相容性，成功合成了单相Co-Fe-Ni-Mn-Cr高熵硫化物固溶体（HES-Cr）。其中电子离域增强了导电性，而相分离的Co-Fe-Ni-Mn-Mo高熵硫化物（HES-Mo）则性能较差。HES-Cr实现了超高容量和超快动力学稳定储钠。","scd":null,"kp":[]},{"i":38237,"as":"水系锌离子电池受限于锌负极的枝晶生长和水引起的寄生反应，导致可逆性差。基于布拉菲定律的晶面调控可指导锌沉积/剥离，但未受保护的晶面易发生副反应。研究提出一种解耦电解液设计，使用甲酰胺（FA）共溶剂，实现了晶面选择性织构控制和全局水活度抑制。这种设计将寄生反应与电化学氧化还原解耦，在安时级电池中实现了高度可逆的(101)织构锌负极。","scd":null,"kp":[]},{"i":38238,"as":"深海极端环境和传统传感器分离的信号处理导致系统庞大、能耗高且延迟大，限制了水下实时感知系统发展。研究开发了一种神经形态浮栅晶体管（NFT），将电学和光学记忆功能结合，在单个器件内同时模拟视觉和听觉突触行为，实现视觉-听觉信号的存内双模处理。该器件实现约14微秒的快速开关，开关比高达10^6，为海洋视觉-听觉感知提供了低能耗解决方案。","scd":null,"kp":[]},{"i":38239,"as":"热固性聚氨酯废料体积大且难以降解，现有回收策略所得产品机械性能固定，适应性受限。研究提出一种化学回收策略，在聚氨酯中插入热触发网络拓扑转变开关，将其转化为机械性能可编程的智能材料。该网络开关赋予再生材料按需机械可编程性，实现了高达54倍的模量增强。这种策略使废弃聚氨酯转变为适应多样化应用的终端按需可编程智能材料。","scd":null,"kp":[]},{"i":38240,"as":"针对缺乏实时凝血病检测技术的问题，研究提出了一种无试剂、可穿戴的电化学传感平台。该平台集成了片上普鲁士蓝（PB）氧化还原换能器、信号关闭型分子印迹聚合物（MIP）层以及用于组织间液（ISF）采样的生物相容性水凝胶微针阵列。该系统能够直接对血栓炎症生物标志物进行电化学检测，实现体内微创监测，比传统血液测试能更早评估风险并有效监测治疗。","scd":null,"kp":[]},{"i":38241,"as":"倒钙钛矿太阳能电池中钙钛矿与电子传输层（ETL）的界面缺陷是实现高效率和稳定性的关键瓶颈。研究开发了一种新型多功能集成聚合物半导体材料P4N-Cl，作为钙钛矿与PCBM之间的界面中间层。聚合物骨架中的羰基、Cl原子和sp2-N原子通过协同配位机制有效钝化界面缺陷，显著抑制非辐射复合，为实现高性能工业化倒钙钛矿太阳能电池提供了界面工程新方案。","scd":null,"kp":[]},{"i":38242,"as":"皮肌炎需要定量评估肌肉无力程度，但缺乏与病理性干燥皮肤兼容的稳定电极接口。研究通过分子工程开发了一种顺应性神经运动电极接口，其超软模量约2.13 kPa，1kHz下阻抗约0.9 kΩ，且7天内电学性能稳定。该接口能从干燥皮肤获取高保真表面肌电图，基线噪声极低，通道间信号相关性高，实现了非侵入性肌无力评估中神经运动信息的稳健分解。","scd":null,"kp":[]},{"i":38243,"as":"全无机钙钛矿的软晶格特性导致卤素空位缺陷和离子迁移，严重损害光伏性能和稳定性。研究引入磺化硫醇分子2,3-二巯基-1-丙磺酸钠（DPS）作为多功能螯合钳。不同于传统单齿钝化剂，DPS通过双齿螯合使其两个巯基与未配位的Pb2+结合，形成稳定的五元环。柔性碳链使其能适应异质晶界，有效解决缺陷和离子迁移问题，实现高效稳定的无机钙钛矿太阳能电池。","scd":null,"kp":[]},{"i":38244,"as":"研究系统分析了在TbScO3(110)衬底上外延生长的BiFeO3薄膜厚度对自旋摆线稳定性的影响。当薄膜厚度大于5nm时保持菱方结构，晶格失配通过71°铁弹闭合畴释放，随后形成109°畴。当厚度小于等于5nm时，极性菱方相与类四方相共存。研究揭示了外延薄膜厚度与晶体结构、铁电畴及磁序（如自旋摆线）演化之间的复杂关联机制。","scd":null,"kp":[]},{"i":38245,"as":"电化学硝酸盐还原产氨的效率受限于水分解与硝酸盐加氢之间的动力学不匹配。研究设计了Ag/CoNiS异质结构，通过调控Ag的负载密度来对界面限域进行编程，调节氢溢流效应。该机制将CoNiS上的水分解活化区产生的活性氢，溢流至Ag相关的硝酸盐/氮氧化物中间体上，实现产氢、传递与深度加氢的耦合。优化的Ag/CoNiS电催化剂显著提升了环境条件下硝酸盐电还原产氨的效率。","scd":null,"kp":[]},{"i":38246,"as":"Ag2Se（硒化银）因具备窄带隙、本征低晶格热导率及罕见的室温塑性，被认为是柔性可穿戴领域极具潜力的n型热电材料。本综述系统总结了Ag2Se基热电材料的最新进展，涵盖决定其半导体与超离子传输行为的基础晶体结构、缺陷化学及电子能带特征，并深入探讨了包括纳米结构化、化学计量比调整、掺杂以及引入无机或有机第二相在内的先进性能提升策略。","scd":null,"kp":[]},{"i":38247,"as":"本研究开发了一种无负极锂离子电池，采用3D打印的超厚正极（面载量120 mg cm⁻²）和双盐/双溶剂电解液。该电解液形成富含阴离子的溶剂化结构，构建了弹塑性固态电解质界面层（SEI），在裸铜箔上实现了高度可逆的锂沉积/剥离，并在低温下保持稳定循环。该电池配置实现了1308 Wh L⁻¹的体积能量密度和424 Wh kg⁻¹的质量能量密度。","scd":null,"kp":[]},{"i":38248,"as":"针对传统均相与非均相催化体系在活性、选择性及回收性上存在壁垒的问题，均相-非均相集成催化作为一种新兴策略，旨在构建兼具高活性、优异选择性、稳定性和易回收性的新型催化系统。本综述系统总结了有机合成领域均相-非均相集成催化系统的前沿进展，打破了这两种催化模式独立发展的界限，为催化科学开辟了新途径。","scd":null,"kp":[]},{"i":38249,"as":"卤化物固态电解质（Li-M-X超离子导体）因具备高锂离子电导率、优异正极兼容性及机械可延展性，成为全固态锂电池的理想材料。然而，当其与还原性负极接触时表现出化学和电化学不稳定性，阻碍了高比容量锂金属负极的直接应用，并限制了电池的整体能量密度。因此，提升卤化物固态电解质的负极兼容性已成为当前全固态电池研发的关键任务。","scd":null,"kp":[]},{"i":38250,"as":"由超分子（如氢键、静电相互作用）和动态共价键（如Diels-Alder反应、二硫键）驱动的自修复聚合物正在重塑柔性电子材料的结构设计。可逆的超分子基元能实现快速界面重建与损伤容忍，而动态共价键则提供坚固且可重构回收的网络架构。两者的协同作用赋予材料可重复愈合、强韧力学及多模态响应特性，极大推动了柔性电容传感等电子器件的多层架构与 printed 导体的发展。","scd":null,"kp":[]},{"i":38251,"as":"在机器学习的指导下，本研究在钛酸钡基陶瓷中实现了高效且热稳定的介电储能。通过协同局部结构工程和优化的制造工艺，该材料展现出增强的极化、降低的磁滞损耗以及提高的击穿强度。所设计的介电电容材料实现了10.69 J cm⁻³的超高能量密度，且效率接近理想的97%，成功在简单环保的化学组分中突破了介电储能的技术瓶颈。","scd":null,"kp":[]},{"i":38252,"as":"氧化还原酶（OR）纳米模拟酶是目前应用最广泛的纳米酶，但其复杂的催化机制限制了进一步发展。本综述打破了按材料类型分类的传统模式，沿着反应路径深入分析了OR纳米模拟酶的催化机制。文章详细考察并比较了催化过程中的电子转移序列、底物吸附、活性中间体的生成与转化以及产物脱附步骤，将其与天然对应物进行对比，为理解其活性、特异性和可持续性提供了深刻见解。","scd":null,"kp":[]},{"i":38253,"as":"针对分子半导体室温自旋传输效率低（约5%）的局限，本研究开发了基于相分离形成垂直不对称纳米柱通道的分子自旋电子器件。该通道不仅限制了自旋扩散，还产生了内建电场，将室温自旋传输效率提升至20%，创历史新高，是不结构化薄膜的五倍以上。同时，纳米柱通道还诱导了明显的偏压依赖不对称性，极大促进了高效不对称自旋传输。","scd":null,"kp":[]},{"i":38254,"as":"有机半导体本体异质结纳米颗粒因具有强可见光吸收和丰富的空间电荷分离界面，成为极具前景的光催化剂。然而结晶度差和易受分子振动影响会导致电荷严重复合。为此，研究人员开发出甲氧基功能化的电子受体ITIC-OMe，显著提高了材料的结晶度和分子堆积紧密度。该策略通过抑制电荷复合和降低电子-声子耦合，有效提升了光催化析氢反应的效率。","scd":null,"kp":[]},{"i":38255,"as":"基于光动力疗法（PDT）的光免疫疗法结合了PDT的精准性与免疫疗法的持久性。研究者通过合理的供体-受体工程，开发了一系列A-D-A结构的有机光敏剂。该分子策略通过微调分子内电荷转移强度精确控制光动力路径，建立了一个系统比较平台，以探究I型和II型PDT是否引发同样强烈的免疫反应，进而利用有机光敏剂诱导免疫原性细胞焦亡来驱动光免疫治疗。","scd":null,"kp":[]},{"i":38256,"as":"本研究在SnTe合金中引入熵驱动缺陷架构，实现了热电性能与力学性能的双重提升。该架构引导从0D置换团簇、1D位错到3D共格纳米析出物的分级缺陷演化，实现了对声子传输和强化机制的多尺度调控。宽带声子散射将873 K时的晶格热导率大幅降至0.26 W·m⁻¹·K⁻¹，同时共格结构有效保障了材料的机械完整性，解决了传统异价键合硫族化合物力学强度受损的问题。","scd":null,"kp":[]},{"i":38257,"as":"自下而上的微纳制造在多层、3D及低成本制造中极具潜力，但缺乏具有光刻胶级可重复性的图形化技术。本研究提出表面选择性成核（SSN）效应，通过在预图案化基底上进行双端丙烯酸酯单体的溶液聚合，并利用吸附抑制剂和链终止剂产生成核势垒，协同调节表面和体相自由能。该技术成功实现了纳米级分辨率、低缺陷密度、干净剥离且适用于多种制造平台的高分子光刻胶图案。","scd":null,"kp":[]},{"i":38258,"as":"基因组的有丝分裂后重塑主要由含STAG1或STAG2亚基的黏连蛋白复合物主导，其中STAG2是这一过程的主要编排者。研究发现，STAG2以阶段和染色质环境依赖的方式调控基因组重塑：在G1早期促进真染色质结构环和转录重启；在G1晚期则限制STAG1的进程性以抑制大环形成。STAG2的进程性受CTCF阻滞限制。该研究揭示了STAG1和STAG2在有丝分裂后基因组折叠中的不同且互补的作用。","scd":null,"kp":[]},{"i":38259,"as":"靶向DNA复制修复机制（如调控ADP核糖基化的PARP1/2和PARG）是癌症治疗的有效手段。研究发现，PARG抑制会导致FET蛋白家族以PAR依赖性方式被招募至复制叉，形成冷凝物从而减缓复制叉进程并促进复制叉反转。FET蛋白控制特定应激下的复制叉动态，而FUS失活会通过RECQ1和PRIMPOL导致复制叉进程失控，进而危及基因组稳定性。","scd":null,"kp":[]},{"i":38260,"as":"衰老引起的认知衰退可能源于神经反应变异性的增加。本研究记录了年轻和年老小鼠在执行视觉决策任务时16个脑区的超1.8万个神经元。结果显示，老年小鼠的反应时间变异性更大。衰老全局性地增加了神经元的放电率和刺激后神经变异性（通过Fano因子量化），并降低了刺激呈现时的变异性淬灭。在视觉皮层、运动皮层和纹状体等区域，老年动物表现出更高的整体放电率。","scd":null,"kp":[]},{"i":38261,"as":"本研究鉴定出SPOP突变和CHD1缺失是前列腺癌对铁死亡易感性的关键遗传决定因素。SPOP突变增强了对靶向GPX4的铁死亡诱导剂的敏感性，而CHD1缺失则削弱了该疗效。机制上，SPOP和CHD1通过拮抗调控MYC-ACSL4轴对铁死亡产生相反作用。这一发现揭示了靶向铁死亡的情境依赖性脆弱点，为基于遗传亚型的精准抗癌治疗提供了依据。","scd":null,"kp":[]},{"i":38262,"as":"本研究利用配体控制的商业镍催化剂，实现了可再生生物质醇向高附加值三取代烯烃和1,3-二烯的高效转化。通过两种不同醇的顺序交叉偶联/异构化和交叉偶联/脱氢反应，实现了三取代烯烃（27个实例，E/Z高达98:2）及1,3-二烯（23个实例，E/Z > 20:1）的立体选择性合成。该催化系统具有精准抑制副产物的能力，并成功应用于DL-半乳糖和α-生育酚的后期官能化。","scd":null,"kp":[]},{"i":38263,"as":"NUDT5已被全基因组CRISPR筛选鉴定为介导抗癌药物6-硫鸟嘌呤（6-TG）毒性的关键因子。本研究开发并验证了一种具有选择性和细胞活性的NUDT5降解剂工具箱。通过正交表征靶点结合、三元复合物形成、降解动力学及全蛋白质组选择性，研究发现NUDT5的靶向蛋白降解能够将其催化抑制作用与6-TG响应中的蛋白损失现象分离开来，为深入解析其作用机制提供了新工具。","scd":null,"kp":[]},{"i":38264,"as":"本研究开发了一种稳健的光催化方案，利用可见光诱导苯并噻吩/吲哚衍生物与N-芳基环丙胺的分子间脱芳构化反应，直接构建角并稠合的四环骨架。该转化通过光催化脱芳构化[3+2]环加成及随后的串联环化机制实现。角并稠合多环系统具有独特的结构刚性和可调理化性质，是生物活性天然产物和药物中的优势骨架。该研究成功展示了从简单芳烃前体合成复杂多环框架的可行性。","scd":null,"kp":[]},{"i":38265,"as":"本研究提出了一种基于全脱氧烷基化的多醇外围编辑新概念，用于合成复杂手性烷烃。通过简单引入烯烃并将所有醇转化为酯，利用级联SN2'反应对所有羟基进行催化和立体选择性的顺序编辑，成功合成了含有高达六个连续手性中心的手性烷烃。该方法使用易得的生物基多元醇为原料，极大缩短了传统的冗长合成路线，使得能够探索科学领域中未被充分开发的复杂手性分子空间。","scd":null,"kp":[]},{"i":38266,"as":"尽管金红石型IrO2-TiO2和IrO2-SnO2体系完全符合Hume-Rothery固溶度判据，但其实际固溶度极低。研究揭示，这是由于d0和d10阳离子（如Ti4+和Sn4+）形成离子键，而IrO2中的Ir-O键具有强共价键特性。在共边金红石结构中，共享氧位点上的这两种不同键合类型会导致电子密度局域化的几何阻挫。","scd":null,"kp":[]},{"i":38267,"as":"针对航运业减碳挑战，研究表明将溶剂再生过程从船舶转移至岸上可显著提升船载碳捕集系统的实用性与经济性。通过在16条航线和4种捕集溶剂的对比测试，研究指出采用实际负载限制（约20%）比固定捕集率更具合理性。船上再生倾向选择低再生能耗溶剂，而高CO2吸收容量溶剂更适用于其他特定模式。","scd":null,"kp":[]},{"i":38268,"as":"针对自然杀伤（NK）细胞在实体瘤微环境中穿透性差且受免疫抑制的挑战，研究利用空间与单细胞转录组学揭示了Nur77在NK细胞介导的肝细胞癌（HCC）免疫中的关键作用。NR4A1（编码Nur77）的表达与NK细胞增殖、免疫刺激基因调节网络激活及HCC患者良好的无病生存期密切相关。在小鼠模型中，条件性敲除NK细胞中的Nr4a1会破坏其稳态并加速肿瘤进展，而激活Nur77可增强其抗癌能力。","scd":null,"kp":[]},{"i":38269,"as":"研究提出经典确定性电路可作为研究多体系统中流体动力学涌现的极简、精确且高效的平台。通过开发新技术并以一维电路为概念验证，研究证明该平台能够为确定性但混沌的系统提供非平凡的流体动力学行为，成功捕捉到包括弛豫至吉布斯态在内的特征动力学过程。该发现解决了微观确定性动力学如何涌现出宏观流体力学方程的百年难题。","scd":null,"kp":[]},{"i":38270,"as":"Polo-like kinase 1 (Plk1)的活性依赖于多种辅因子，研究揭示了这些辅因子在人类细胞周期中的特异性调控作用。在S期，Cep192和Aurora A控制Plk1以促进复制起点激活；Bora是驱动G2期有丝分裂进入、DNA损伤恢复和中心体成熟的主要激活因子；而中心体解耦则由另一独立机制控制。这表明不同的Plk1辅因子精确控制着细胞与中心体周期的不同转换阶段。","scd":null,"kp":[]},{"i":38271,"as":"在拟南芥中，异染色质的形成机制研究表明，相互排斥的组蛋白H2A变体（H2A.W和H2A.Z）作为引导因子启动异染色质的形成。H2A.W促进异染色质的建立，而H2A.Z则起抑制作用，这一机制在含有分散转座子（TEs）的染色体臂区域尤为显著。相反，近着丝粒TEs表现出自主的异染色质形成过程。该发现阐明了植物中不依赖RdDM途径的区域特异性异染色质建立机制。","scd":null,"kp":[]},{"i":38272,"as":"研究揭示了肺单核吞噬细胞亚群在慢性结核分枝杆菌（Mtb）感染期间限制细菌能力差异的机制。最允许Mtb存活的CD11clo单核衍生细胞表达更低水平的干扰素-γ（IFNγ）信号蛋白，导致其对IFNγ的反应弱于肺泡巨噬细胞。此外，I型IFN信号会抑制IFNγ介导的MHC II类分子表达，损害抗原特异性CD4 T细胞的激活。已控制的Mtb感染所赋予的先期免疫力能显著增强单核衍生细胞对IFNγ的响应能力。","scd":null,"kp":[]},{"i":38273,"as":"为解析癌症在治疗压力下的进化与耐药机制，研究开发了一种分层动态谱系追踪技术——FLARE。利用该技术在体内外追踪了急性髓系白血病（AML）细胞系在接受阿糖胞苷（AraC）治疗时的演变过程，成功绘制了小鼠和人类AML细胞系中易产生AraC耐药的不同细胞谱系。通过FLARE，研究准确识别出在治疗干预前即负责引发耐药的细胞群体。","scd":null,"kp":[]},{"i":38274,"as":"研究探讨了酵母中Swi-Snf染色质重塑复合物与Tup1-Cyc8全局共抑制物对基因转录的拮抗调节作用。在葡萄糖培养的细胞中，Swi-Snf和Tup1-Cyc8共同存在于活性和非活性基因的启动子上，且SNF2对Tup1-Cyc8的充分占据是必需的。这两种复合物对核小体定位的影响具有基因特异性，取决于各共调节基因的具体环境。研究明确了这两种复合物在转录激活与抑制中的全局拮抗网络。","scd":null,"kp":[]},{"i":38275,"as":"通过组装拟南芥两个亲本基因组并分析合成与天然四倍体的表观基因组，研究探究了异源多倍体化和环境对DNA甲基化的综合影响。异源多倍体化瞬间引发了最显著的DNA甲基化变化，随后的世代中变化较小。在不同环境条件下生长的后代表现出表观遗传修饰的趋同与趋异模式。该研究揭示了多倍体化初期短期基因组与表观遗传响应机制对植物物种形成的关键作用。","scd":null,"kp":[]},{"i":38276,"as":"针对金属蛋白结合位点识别的难题，研究提出了一种混合深度学习框架PRIME。该框架结合了蛋白质语言模型和预训练结构模型，从蛋白质的序列与结构中提取进化及结构信号，并引入探针生成算法来连接序列和结构预测。PRIME能够克服数据稀缺和金属离子杂乱结合的干扰，实现高效且精确的金属结合位点预测，为细胞过程的机理研究提供计算支持。","scd":null,"kp":[]},{"i":38277,"as":"昆虫复眼的广角视觉依赖于微米级的曲面变化，研究以黑腹果蝇为模型揭示了这种精细曲率的发育编码机制。研究发现发育中视网膜的基底表面被组织成超细胞三角形网格，且三角形大小呈现物种特异性的二维分布模式。通过遗传干扰和计算建模证实，这种自然可编程的超材料模式决定了成年果蝇眼睛的局部曲率，并在果蝇近缘物种中展现出演化上的保守性。","scd":null,"kp":[]},{"i":38278,"as":"研究采用可扩展的时间复用方法，构建了一个完全可重构的光子处理器架构，成功展示了量子受控非（C-NOT）门。该平台结合单量子比特旋转，能够实现任意量子电路。实验中以(93.8 ± 1.4)%的保真度实现了后选择C-NOT门操作。此外，研究还验证了利用该时间复用平台将C-NOT门与单量子比特门结合，成功生成了四个贝尔态。","scd":null,"kp":[]},{"i":38279,"as":"受珍珠母矿物桥结构启发，研究提出了一种主动引入纳米孔的反向界面设计，用于克服陶瓷基复合材料强度与韧性之间的权衡问题。多尺度表征与模拟显示，纳米孔能够降低界面脱粘强度并诱发裂纹偏转，从而保护纤维免受脆性断裂。同时，粗糙的断裂路径增加了界面摩擦应力与载荷传递，提升了基体承载能力和能量耗散。这种不对称调制机制有效保持了纤维完整性并实现了能量耗散的最大化。","scd":null,"kp":[]},{"i":38280,"as":"大模场（LMA）技术被引入芯片级集成光子学，以克服传统集成器件因储能容量受限导致的低光功率问题。研究展示了一种零偏振相关增益（Zero-PDG）的硅光子放大器，该放大器能够在芯片上直接实现瓦级的光功率放大。结合高增益和低噪声特性，该器件在高功率光传感、测距、医疗手术及长距离光通信等对低偏振依赖性要求严格的领域中具有重要应用潜力。","scd":null,"kp":[]},{"i":38281,"as":"研究提出了一种名为HARPA的地震相位关联框架，旨在解决高频率地震波到达序列难以关联的问题。该框架将观测和预测的到达序列表示为概率分布，并使用最优传输度量进行比较。HARPA能够联合估算地震位置、发震时刻以及波速场的低维表征，从而有效应对局部波速高度非均匀或未知的复杂地质条件，大幅提升了对微小地震事件的关联和定位精度。","scd":null,"kp":[]},{"i":38282,"as":"研究比较了范德华铁电材料NbOBr2和NbOI2中的自发参量下转换（SPDC）过程，证明了NbOI2在近红外SPDC应用中具有突出优势。实验成功实现了近红外偏振纠缠光子的产生，并获得了纠缠度为0.90 ± 0.05的偏振纠缠态。该研究不仅扩展了基于NbOX2的量子光源波长范围，还为超紧凑纠缠光源和片上集成量子光子器件提供了新的候选材料。","scd":null,"kp":[]},{"i":38283,"as":"针对引导骨再生双层膜界面结合差和适应性弱的问题，研究通过同构原位制造策略开发了一种具有双交联增强界面的统一双层膜。该膜在干态和湿态下抗拉强度分别达到约156 MPa和8.6 MPa，保证了长期的体内降解稳定性和生物活性。结合顺序释放的生物活性成分，该双层膜能够有效调节抗菌、免疫调节、神经血管化和成骨作用，在大鼠模型中成功实现了阶段适应性骨再生。","scd":null,"kp":[]},{"i":38284,"as":"针对单糖结构中多羟基难以区分和修饰的挑战，研究开发了一种有机催化方法，实现了对极低保护度单糖的位点选择性磺酰化。该方法利用N-杂环卡宾（NHC）衍生的磺酰鎓中间体，通过不同的NHC骨架精确控制区域选择性。结合经典的SN2取代反应，该技术能够高效实现糖类分子中羟基的立体反转与官能团交换，为复杂碳水化合物分子的模块化编辑提供了强有力的工具。","scd":null,"kp":[]},{"i":38285,"as":"受骨骼肌运作机制启发，研究开发了一种具有低压氧化触发和自发收缩特性的电化学人工肌肉。通过在低于0.4V的电压下电化学充电触发I3⁻注入并氧化为I2，随后通过I2 + I⁻ → I3⁻的反应实现自发收缩。这一化学供能机制类似于骨骼肌中三磷酸腺苷（ATP）的水解作用，突破了传统电化学人工肌肉的工作机理。基于此机制，原始碳纳米管纱线人工肌肉展示了优异的驱动性能。","scd":null,"kp":[]},{"i":38286,"as":"残余学习力场是一种混合机器学习力场，结合基于物理的键合相互作用描述与对剩余能量效应的学习校正，以减少现有力场在物理可靠性、计算效率和跨分子准确性之间的权衡。两部分通过三步策略共同训练，提供互补信息。在类药分子、分子二聚体、扭转能谱、能量最小结构和生物分子模拟测试中，该方法表现出有效性能。","scd":null,"kp":[]},{"i":38287,"as":"研究人员制备了负载量达66.5 wt%的Ni-Ce-Al三元催化剂。Ni纳米颗粒由Al2O3框架连接，被富含Ce单原子和团簇的原子级分散Ce物种包围。该设计克服了CeO2载体上Ni烧结导致的活性-稳定性权衡，在600°C下实现了324.0 mmol gcat⁻¹ min⁻¹的高产氢率。其促进作用源于CeO2缓解了氢中毒，具有高亲氢性的原子级分散Ce物种在其中发挥关键作用。","scd":null,"kp":[]},{"i":38288,"as":"该研究展示了一种视频率的无透镜叠层衍射成像技术。通过协同设计光学、传感方案和计算，利用编码表面对动态物体进行编码，结合时序传感和时空神经场框架提取相关性，突破了空间带宽积（SBP）的限制。该技术实现了厘米级覆盖和308纳米线宽分辨率的视频率千兆像素成像，SBP吞吐量达到每秒20.8千兆像素，并验证了其在介观尺度动态监测中的应用。","scd":null,"kp":[]},{"i":38289,"as":"研究通过描述符指导的氧亲和力工程，合成了锚定在铜上的不饱和MgO1-x催化剂。在流动池中，该催化剂在300 mA cm⁻²的电流密度下，将二氧化碳电还原为乙烯的法拉第效率达到78.2%。机理表明，MgO1-x的双功能特性通过化学相互作用稳定了Cu⁺并形成不对称的Cu⁺···Cu⁰对，从而促进了C-C偶联和C-O断裂过程，实现了安培级的高效乙烯生产。","scd":null,"kp":[]},{"i":38290,"as":"研究证明TRPC4和TRPC5通道是经颅聚焦超声诱导大脑神经元调节的关键介质。对雄性小鼠的压后皮质（RSC）施加tFUS会使其对机械和热刺激脱敏，并引发早期生长反应1（Egr1）的强烈表达。抑制tFUS诱导的Egr1 ensemble会阻断躯体感觉效应。转录组学分析显示Trpc4富集，药理抑制和基因敲低TRPC4均会消除tFUS介导的感觉调节。","scd":null,"kp":[]},{"i":38291,"as":"Runx2通过调节Ctsk转录直接驱动破骨细胞分化，但其在成骨细胞中的双重作用限制了治疗潜力。研究确认Ip6k2是一种Runx2相互作用蛋白，能特异性增强破骨细胞中依赖于Runx2的Ctsk转录。敲除Ip6k2可抑制破骨细胞生成并增加骨量，同时不影响成骨细胞功能。同时敲除Runx2和Ip6k2无叠加效应，表明二者共享调节途径，靶向Ip6k2-Runx2轴可用于治疗骨质疏松症。","scd":null,"kp":[]},{"i":38292,"as":"Richardson-Lucy反卷积算法在恢复模糊图像时容易过拟合噪声并产生高频伪影。为此，研究人员提出了DeBayes，这是一种基于物理精确成像模型的严格贝叶斯反卷积框架。DeBayes在空间域进行反卷积，精确联合建模噪声源，推断完整后验分布。该方法避免了对稀疏性或连续性的假设，产生严格的正重建，且在无需用户调优正则化参数或迭代截断的情况下稳定收敛。","scd":null,"kp":[]},{"i":38293,"as":"研究表明线粒体利用重力激活细胞器内的蛋白质合成。全基因组核糖体分析显示，哺乳动物细胞和秀丽隐杆线虫在微重力下的线粒体翻译会减少。这一表型是由层粘连蛋白-整合素相互作用引起的细胞粘附减弱所致。线粒体翻译的激活依赖于FAK、RAC1、PAK1、BAD和Bcl-2家族蛋白传递的信号，以及基质中的线粒体脂肪酸合成（mtFAS）途径。mtFAS消耗丙二酰辅酶A以调节该过程。","scd":null,"kp":[]},{"i":38294,"as":"利用不同尺寸的胶体量子点进行相分离自组装，能够生成Janus微环。这种微环结构有效抑制了能量转移，并使其在单个微腔内实现稳定的双波长激光发射。这种可扩展的一步法策略支持高密度光学编码和用于集成光子学应用的大面积全彩激光阵列。","scd":null,"kp":[]},{"i":38295,"as":"该研究阐明了一种全固态锂硫电池的设计原则：微小孔隙塑造硫的反应路径，而较大的碳颗粒引导离子流动。将这两种尺度统一在单一主体中，赋予了阴极所需的反应性和传输能力，从而实现了高硫利用率和持久的循环性能。该方法为推进下一代全固态锂硫电池提供了实用途径。","scd":null,"kp":[]},{"i":38296,"as":"一项深入的分析挑战了仅靠追求经济增长就能为卢旺达带来长期繁荣的观点。该分析探讨了卢旺达在科技领域崛起的可持续性，并提出了有助于其实现长期科技进步与发展的关键支持因素。","scd":null,"kp":[]},{"i":38297,"as":"《自然》杂志档案记录了对早期“电视机”的演示以及英国政府为此提供的慷慨资助。该记录展示了早期电视技术的面貌及其引发的关注，探讨了该项新兴技术未来的发展潜力与普及前景。","scd":null,"kp":[]},{"i":38298,"as":"研究描述了一种新型靶向种系HIV-1包膜蛋白（CAP256.OPT4），其诱导V2顶点广谱中和抗体（bNAbs）前体的效率是野生型的30至400倍，在超过90%的猕猴中诱导了包含N130病毒的广谱中和作用。通过三种不同平台（猿人免疫缺陷病毒、蛋白质纳米颗粒和mRNA）进行递送，均在感染或免疫后4周内实现bNAb启动，12周时血浆中出现广谱中和作用，部分猕猴中和广度最高达90%。","scd":null,"kp":[]},{"i":38299,"as":"","scd":null,"kp":[]},{"i":38300,"as":"HIV极高的抗原多样性是开发广谱保护性疫苗的主要障碍。通过采用靶向种系疫苗设计，旨在激活具有预定人类遗传特征的稀有广谱中和抗体前体B细胞。研究报告了该设计思路通过异源加强引导B细胞亲和力成熟，克服了免疫学挑战，首次成功在非转基因动物体内生成了广谱中和抗体，为HIV疫苗研发提供了实质性突破。","scd":null,"kp":[]},{"i":38301,"as":"研究利用具有动量选择的扫描透射电子显微镜振动光谱，直接探测了LaAlO3/SrTiO3界面在整个超导相图中的晶格振动和原子结构。研究发现，超导性与反演对称性破缺和高频局部声子的出现密切相关。这些可调谐的极性振动被限制在界面附近，为电声子耦合提供了直接证据，揭示了其与铁电量子临界点附近的对称性破缺之间的内在联系。","scd":null,"kp":[]},{"i":38302,"as":"研究发现了一种由边界几何形状驱动且独立于材料参数的电荷守恒的三维拓扑缺陷构型转变。在小鼠胚胎中，三维极性缺陷是充满液体的腔隙形成的位置，而这些腔隙对后续发育至关重要。通过实验扰乱胚胎形状验证了这些发现，表明边界几何结构通过控制三维拓扑缺陷来决定胚胎发育中的腔隙成核。","scd":null,"kp":[]},{"i":38303,"as":"研究证明边界几何形状决定了三维拓扑缺陷的构型。在发育的胚胎中，这些由表面几何形状控制的体积拓扑缺陷，决定了腔隙形成的位置，从而主导了胚胎早期关键结构的发育。这一发现阐明了三维缺陷在活体组织结构形成中的物理和生物学机制。","scd":null,"kp":[]},{"i":38304,"as":"深入理解忆阻器的固有特性，并在器件、阵列和系统三个层级上进行协同设计，是实现基于忆阻器的高精度计算的关键。这种多层次的综合设计策略有助于突破现有技术瓶颈，提升计算系统的整体可靠性与准确性。","scd":null,"kp":[]},{"i":38305,"as":"研究开发了一种以非常规产油酵母红酵母为底盘的从头微生物合成平台，无需添加醇或脂质前体即可高水平合成结构多样的脂肪酸酯。通过筛选特定的途径酶并进行模块化途径工程，成功重新编程了该酵母的原生脂质代谢，为替代依赖石油化工催化和植物提取的传统生产方式提供了可持续的解决方案。","scd":null,"kp":[]},{"i":38306,"as":"","scd":null,"kp":[]},{"i":38307,"as":"气候变化正导致咖啡植物面临严重的灭绝威胁。研究人员正积极寻找解决方案以应对这一危机，不仅旨在保护咖啡植物的生物多样性，也致力于确保科学家及相关产业能够持续获得这一重要资源。","scd":null,"kp":[]},{"i":38308,"as":"AI智能体通过协同合作，能够生成生物医学假设并进行数据分析。这一技术进展推动实验室发现周期向新模式发展，在该模式中，AI深入参与到实验发现流程的每一个步骤中。","scd":null,"kp":[]},{"i":38309,"as":"肠道微生物组是神经退行性疾病的风险调节因素。研究利用htau.P301S小鼠模型发现，进行性tau病会引发肠道微生物组组成和功能的改变，且这种变化与基于淀粉样蛋白的阿尔茨海默病模型不同。通过慢性抗生素治疗破坏肠道微生物组，会加剧小鼠的认知缺陷和tau病理，证实了微生物组对tau驱动疾病进展具有因果影响。这种病理变化伴随着血清和大脑中微生物组依赖性代谢物的广泛改变。","scd":null,"kp":[]},{"i":38310,"as":"中心体生物发生依赖于无模板的物理转化过程，其中软骨轮支架引导中心体生长随后发生解体。研究证实，内在无序蛋白ALMS1作为外部辅助因子，能在不并入种子结构的情况下促使软骨轮种子形成。间期形成的CS以纳米级环状复合物存在；进入有丝分裂后，CS在ALMS1参与下解体。ALMS1突变会导致软骨轮异常扩增并从自身中心体脱落，形成异位结构。","scd":null,"kp":[]},{"i":38311,"as":"研究利用Cxcr3报告小鼠发现，典型的1型炎症趋化因子受体CXCR3在甲型流感病毒(IAV)反应性B细胞中高度表达。在IAV感染期间，诱导型支气管相关淋巴组织(iBALT)中异位肺生发中心B细胞的CXCR3表达量显著高于次级淋巴器官。B细胞特异性CXCR3的缺失会直接影响iBALT中生发中心反应的生成效率，揭示了其在肺部异位生发中心形成过程中的驱动作用。","scd":null,"kp":[]},{"i":38312,"as":"磷酸肌醇(PIPs)在细胞内划分作用位点，引导ESCRT转运机器进行膜结合。早期ESCRT-I和ESCRT-II复合物结合PIPs和泛素化修饰，而晚期ESCRT-III复合物与VPS4 ATP酶结合介导膜的重塑、收缩和分裂。研究描述了两类不同的螺旋状ESCRT-III细丝，这些细丝能够包围并重塑特定的细胞膜结构，揭示了其介导膜断裂的具体机制。","scd":null,"kp":[]},{"i":38313,"as":"Tau蛋白在神经退行性疾病中发挥作用，而磷酸化状态影响其生理功能。实验发现，在果蝇中泛神经元表达人Tau蛋白并结合物理损伤，会触发雄性果蝇攻击行为显著增加，而非磷酸化Tau蛋白则无此现象。这种行为源于多巴胺能神经环路的激活，且不伴随神经退行性病变。体外实验证实，磷酸化的人Tau蛋白保持与微管结合，但丧失抑制微管解体的能力，从而促进了微管的动态性。相反，非磷酸化Tau和果蝇Tau能稳定微管。","scd":null,"kp":[]},{"i":38314,"as":"人类朊病毒在分裂细胞中增殖的限制一直阻碍了朊病毒病理学研究和治疗手段开发。研究成功构建了名为EKV的人源化细胞模型，该模型能够强健且无限期地传播散发性克雅氏病(sCJD)朊病毒。实验证实，EKV细胞的裂解物能在人源化小鼠体内复制出真实的朊病毒感染，其引发的临床致死性神经退行性病变与直接接种天然朊病毒的症状无法区分。","scd":null,"kp":[]},{"i":38315,"as":"在拟南芥脱落酸(ABA)诱导的气孔关闭过程中，不依赖钙离的激酶OST1和依赖钙离的蛋白激酶CPKs均发挥重要作用。研究确认，OST1通过介导磷酸化激活主要由CNGC5/6/9/12构成的钙离子通道。此外，研究新鉴定出CPK3、CPK8和CPK10这三种钙依赖性蛋白激酶，它们通过增强OST1启动的钙离子内流，直接参与并调控ABA信号通路中的钙离子编码过程。","scd":null,"kp":[]},{"i":38316,"as":"对于固体粘合剂，材料越软意味着粘性越强，因为高柔顺性有助于在非共形表面间形成紧密接触。研究通过测量柔性硅胶凝胶微球与平坦刚性基底间完整的粘合接触几何形状，探究了连续体弹性、流体表面力学与内部孔隙弹性流之间复杂的相互作用。实验观察到粘合力学的连续弹性毛细管转变。这一发现揭示了软凝胶微球在跨越多个数量级弹性刚度下的弹性毛细粘附物理机制。","scd":null,"kp":[]},{"i":38317,"as":"研究探讨了大脑对诗歌进行美学评估的神经机制。实验让受试者阅读自然主题的俳句和情感主题的川柳，并从美学吸引力、意象等五个维度进行评分，同步记录脑电(EEG)数据。采用多类梯度提升树模型与SHAP解释法，从神经振荡特征中预测评估得分。结果显示，模型预测表现优于线性基线，且跨主题泛化能力有限，证明神经编码具有高度的内容特异性。不同主题的诗歌评估对应着截然不同的神经振荡特征。","scd":null,"kp":[]},{"i":38318,"as":"液晶作为拓扑软物质，能自发形成特定组装体以最小化自由能。针对传统分子液晶由于尺度极小导致三维结构难以观测的问题，研究利用掺铕（Eu3+）磷酸镧纳米棒构成的胶体液晶，实现了一种从传统向列态液滴到独特花形形态的形态发生过程。研究全面展示了在几何限制条件下，受挫液晶的形态发生学及其三维拓扑缺陷的动态演化机制。","scd":null,"kp":[]},{"i":38319,"as":"肢体优势（利手现象）广泛存在于人类行为中。研究通过几何学分析量化运动轨迹，测试了内在半球优势与长期练习对利手的影响。结果显示，在使用工具或面对复杂轨迹要求时，非优势手臂的控制能力明显处于劣势。这种劣势源于非优势手臂在执行复杂工具操作或物体交互所需轨迹时缺乏足够的练习。结论证实，手臂优势是后天练习执行工具所需复杂轨迹形状的涌现效应。","scd":null,"kp":[]},{"i":38320,"as":"线粒体损伤是大脑老化和神经退行性疾病的共同特征。利用缺乏PTL-1（线虫Tau同源物）的秀丽隐杆线虫和缺乏Tau蛋白的小鼠模型，研究发现野生型Tau蛋白的缺乏会促使线粒体向促融合状态转变，并增强线粒体功能和抗逆性。在两种动物模型中，Tau缺失均导致线粒体活性增加、氧化还原平衡改变，并显著提升了线虫对热应激和线粒体应激的抵抗力。","scd":null,"kp":[]},{"i":38321,"as":"智力障碍是一种严重影响认知功能的疾病。动力蛋白激活蛋白复合物对神经元内运输和突触稳态至关重要。研究在智力障碍家系中识别出动力蛋白激活蛋白亚基4（DCTN4）的有害变异。小鼠模型中DCTN4的消融会导致神经前体细胞凋亡和神经元位置改变。携带该变异的小鼠表现出认知缺陷和树突发育受损。缺乏或变异的DCTN4皮质神经元中多种复合物亚基水平显著下降，证实了DCTN4功能破坏是导致智力障碍的机制。","scd":null,"kp":[]},{"i":38322,"as":"决策科学家致力于理解风险下人类选择的动机，但传统行为数据方法受限。研究引入大型语言模型（LLMs）构建了可扩展的分析框架，用于分析口头报告并提取参与者在金钱彩票选择中的明确动机。经验证的LLM能在95%的实验测试中，从自由文本中准确识别出预定义的决策动机并与实际选择一致。分析证实，人类决策动机主要由选择问题的结构驱动，而非个体差异。","scd":null,"kp":[]},{"i":38323,"as":"气孔通过保守的生理途径形成图案。研究确认了一种依赖最终对称细胞分裂(SCD)调控的气孔 patterning 机制。在亚细胞和超细胞尺度上，SCD由组织生长主轴上的拉伸应力进行方向对齐，从而形成全局极化的气孔场。研究证实 KATANIN 1 是对称分裂方向的关键调节因子。相邻细胞的扩张以非自主方式控制对称分裂方向，证实基于机械应力的分裂定向是气孔形态预置和孔隙生成的必要条件。","scd":null,"kp":[]},{"i":38324,"as":"大脑具备抑制自身动作产生的不良信号以确保准确感知的能力，例如快速眼动期间的眼跳抑制。研究采用瞳孔测量法和脑磁图(MEG)评估了不同注意力状态下的视觉敏感度。结果显示，在通过注意力振荡范式引发的注意力转移期间，受试者的视觉灵敏度出现明显降低或抑制。这种抑制现象并非由微眼跳引起，且在节律性注意中不存在，证实了大脑在注意力转移时存在特异性的视觉处理抑制机制。","scd":null,"kp":[]},{"i":38325,"as":"情绪调节的动机和策略在不同文化中存在差异。通过三项大规模跨国研究证实，个人主义文化背景下的人群具有更强的动机去改善他人的情绪状态，这对其心理健康和社交关系至关重要。相反，集体主义文化人群在动机和策略上表现出不同特征。跨文化差异直接影响情绪调节方式，个人主义文化在促使他人感觉更好方面表现出更为显著的主动性。","scd":null,"kp":[]},{"i":38326,"as":"睡眠期间慢振荡、纺锤波和涟漪波的跨区域相互作用支持记忆巩固。研究利用19名癫痫患者的颅内神经记录，分析运动记忆巩固及癫痫棘波的作用。结果显示，眶额皮层慢振荡强健地调节跨区域的纺锤波和涟漪波。大多数睡眠振荡组合频率正向预测了运动任务的表现提升，但海马体涟漪波频率及其耦合的癫痫棘波会破坏这一过程。这表明癫痫活动会干扰正常睡眠节律对运动记忆的巩固机制。","scd":null,"kp":[]},{"i":38327,"as":"光合生物通过非光化学猝灭(NPQ)平衡高效捕光与过剩激发能防护。在海洋硅藻中，光收集复合体(LHC)蛋白Lhcf2被证实是能量依赖性猝灭的关键必需物质。通过基因敲除Lhcf2发现，qE效应完全丧失。机制表明，Lhcf2的缺失阻止了NPQ核心效应物Lhcx1的稳定积累。这证实Lhcf2在组装能量猝灭位点中发挥核心作用，对硅藻的光保护机制至关重要。","scd":null,"kp":[]},{"i":38328,"as":"布氏锥虫通过侧附着的鞭毛驱动细胞体快速变形。高速散焦成像显示，其表面点在横截面上描绘出花朵状图案。花瓣图案源于顺时针鞭毛跳动产生的右手螺旋波，使细胞如开瓶器般前进；中心波瓣则由平衡主动扭矩的较慢逆时针细胞旋转引起。鞭毛下方的弯曲细胞形状将这两种手性运动叠加，并通过三维流体动力学模拟验证了该机制。","scd":null,"kp":[]},{"i":38329,"as":"A2AR是抑制CD8+ T细胞活化的关键免疫调节受体。利用A2AR-eGFP报告小鼠发现，A2AR表达在TCR刺激下被诱导，并在慢性抗原暴露和缺氧环境中持续存在，其持续表达通过经典的Gαs-cAMP-PKA途径强烈促进CD8+ T细胞终末耗竭。出人意料的是，A2AR缺失并未缓解耗竭，反而加速了向耗竭方向的分化。","scd":null,"kp":[]},{"i":38330,"as":"研究通过构建模型对“负利率-增长率缺口(r<g)为政府债务融资提供免费午餐”的观点提出质疑。模型将利率r和增长率g内生化，表明它们是由财政政策通过对均衡多重性和资本筛选的效应所塑造的变量。这打破了政府可以无成本进行债务融资的假设，揭示了债务在资本机制中的实际作用。","scd":null,"kp":[]},{"i":38331,"as":"NLRP3炎症小体在微管组织中心（中心体）形成凝聚物。研究表明，微管依赖性运输是NEK7依赖的NLRP3激活的必要条件，并将NEK7促进至中心体周物质（PCM）。微管、引发和NEK7协同增加PCM丰度，为NLRP3凝聚和组装创造许可环境。NLRP3表达升高可补偿有限的PCM丰度，从而在K+流失等条件下维持炎症小体激活。","scd":null,"kp":[]},{"i":38332,"as":"针对难熔高熵合金（RHEAs）强塑性的权衡问题，提出“高熵+稀释”设计策略。该策略将高熵基体与微量合金化结合，并引入相反特征应变溶质配对规则。具体而言，在基体中添加1.5 at.%的替代铼（局部收缩）和0.3 at.%的间隙硼（局部膨胀），协同放大了局部晶格畸变，成功制备出在77 K至1373 K极端温度范围内兼具高强度和优异延展性的合金。","scd":null,"kp":[]},{"i":38333,"as":"多亚基RNA聚合酶（RNAPs）的核苷酸添加循环（NAC）涉及包括触发环（TL）在内的活性位点构象变化。抗生素先导化合物CBR9379和AAP-SO2分别抑制大肠杆菌和结核分枝杆菌的RNAP，通过结合口袋发挥作用。这些抑制剂揭示了活性位点的运动，特别是触发环（TL）和Rim螺旋/F环（RH-FL）的关闭对催化和核苷酸添加循环至关重要。","scd":null,"kp":[]},{"i":38334,"as":"NASA啮齿动物研究-20任务评估了42天太空飞行对雌性生殖的影响。返回地球5天后交配的雌鼠成功怀孕，繁殖力仅略有下降。然而，太空飞行母鼠所产的F1后代在生长、功能和行为上与对照母鼠的后代存在显著差异。此外，F1代还表现出跨代的生殖功能及代谢等后果，表明长期太空飞行对女性生殖系统及后代存在负面影响。","scd":null,"kp":[]},{"i":38335,"as":"在桌面实验中利用2+1时空维度的宏观活性颗粒圆盘，首次直接观察了经典连续时空晶体的“三阶段熔化”过程。该时空晶体通过自发形成相干的刚体旋转二维三角晶格来表征，持续近一天且对噪声具有极强的鲁棒性。通过调节耗散参数，研究人员成功观察并解析了该时空晶体熔化过程的底层物理机制。","scd":null,"kp":[]},{"i":38336,"as":"处于战区的乍得湖是非洲最大的湿地和生物多样性热点。研究团队克服安全限制，于2022年采用航空距离采样法对该区域野生动物进行了调查。该方法提高了调查的安全性、可重复性并减少了探测偏差。结合密度表面模型，研究估算物种丰度并预测时间趋势，证实乍得湖仍然是非洲对水鸟最重要的湿地。","scd":null,"kp":[]},{"i":38337,"as":"提出一种具备单次成像能力的宽场红外显微光谱技术，用于实现1 kHz帧速率的单次宽场生化成像。该技术利用每对仅持续约一皮秒的激光脉冲捕获单张图像，有效减少了运动模糊，能够观察活体生物的快速动态过程。其原理基于红外共振的三阶和频过程，将红外光转化为可见光信号，成功实现了活体单次成像。","scd":null,"kp":[]},{"i":38338,"as":"构建了一个正式模型来探究人类食人行为的出现及其被禁忌压制的原因。该模型将食人视为受能量收益和多种成本约束的潜在食物来源，其中营养收益由卡路里摄入的饱和函数计算，成本来源于获取、消化和感染。感染成本被模拟为随机过程，其均值随营养级传递链长度增加而增加。研究揭示了食人在何时具有适应性以及禁忌抑制它的机制。","scd":null,"kp":[]},{"i":38339,"as":"发育中器官的感觉神经支配受周围组织分泌的分子信号影响。研究以牙齿根发育过程中的神经支配为模型，发现组蛋白去甲基化酶KDM6B在牙间充质中表达，是牙齿感觉神经支配的关键外在调节因子。间充质中Kdm6b的缺失严重损害三叉神经轴突进入并在牙髓中的分支，导致牙根发育缺陷。该过程由间充质骨形态发生蛋白(BMP)信号传导的表观遗传调控介导。","scd":null,"kp":[]},{"i":38340,"as":"极端电解质限制下的空间电荷积累主导了界面动力学。研究引入了一种固定电荷选择性界面，利用不动的阴离子电荷替代移动的电解质阴离子作为主要的电荷补偿物质，建立了化学编码的静电边界条件。以葡萄糖衍生网络为模型系统，证明局部固定电荷能够实现阳离子选择性运输，有效抑制空间电荷驱动的低效性，同步极端纳米级限制下的离子传输。","scd":null,"kp":[]},{"i":38341,"as":"受生物系统瞬态激活态启发，开发了一种时间门控分子平台。该系统集成了质子响应型电荷转移复合物（CTC）敏化剂和二芳基乙烯光开关。CTC的可逆质子化实现了对三线态敏化光致变色的化学门控，并与耗散pH调节网络耦合产生瞬态激活窗口。这使得相同的光学刺激在化学演变过程中的不同时间施加会产生截然不同的结果，有效促进了化学门控的自适应光化学响应。","scd":null,"kp":[]},{"i":38342,"as":"报道了一种基于[3]索烃架构的多组分分子机器的合成与表征。该系统由两个冠醚大环和一根带有三个识别位点（铵、联吡啶和三唑鎓）的轴组成。通过一系列化学和电化学输入，两个大环的位置可被精确控制，实现两环处于相邻位点、同一位点或分离在轴两端的运动。该复杂耦合运动机制得到了清晰的阐明。","scd":null,"kp":[]},{"i":38343,"as":"开发了一种脂肪族伯胺的直接脱氨基炔基化反应。该方法利用炔基溴作为偶联伴侣，在无金属条件下，使用N-端基异构酰胺作为氮删除试剂，成功断裂强C(sp3)─N键并构建C(sp3)─C(sp)键。这克服了从常见胺前体制备烷基取代内部炔烃的挑战，无需预先对胺进行活化，为有机合成和药物化学提供了一种有效路径。","scd":null,"kp":[]},{"i":38344,"as":"提出了一种离子驱动聚合物链缠结的通用策略，以指导可重构的层级结构并实现高度可调的有机磷光。具体而言，钾离子以可编程方式桥接κ-角叉菜胶(κCG)内的醚基和磺酸基，引发聚合物缠结和发色团聚集。这种离子驱动的缠结实现了对凝聚态结构的精确可逆控制，成功制备出动态有机磷光聚合物。","scd":null,"kp":[]},{"i":38345,"as":"为解决水系锌离子电池中锌离子有效去溶剂化和快速质量传输之间的矛盾，设计了一种基于C3对称三角羧酸配体的氢键有机框架（HOF）作为离子筛分界面。该设计将精确的孔径控制与定制的化学环境相结合，有效调节Zn2+的去溶剂化行为。含有缺电子三嗪核心的柔性HOF成功解耦了去溶剂化和质量传输之间的权衡，显著稳定了锌负极。","scd":null,"kp":[]},{"i":38346,"as":"开发了一种利用廉价非均相Pd/C催化剂，对含有CF3、CF2H和CF2CO2Et基团的吡啶进行加氢的稳健方法。该反应条件耐受空气和水分，以良好至极高的非对映选择性合成了多种高度功能化的氟化哌啶（37个实例，产率高达98%）。通过全面的核磁共振研究实现了结构表征，并在克级规模制备中验证了该方法的实用性。","scd":null,"kp":[]},{"i":38347,"as":"针对电化学合成过氧化氢（H2O2）反应动力学迟缓及选择性低的问题，采用液体纳秒脉冲激光烧蚀技术设计合成了一系列高熵合金气凝胶。在包含CrMnFeCoNi在内的多种体系中，CrMnFeCoNi高熵合金气凝胶表现出最佳的电催化性能，实现了高达95%的H2O2选择性，在环境可持续的H2O2生产和水脱色应用中展现出巨大潜力。","scd":null,"kp":[]},{"i":38348,"as":"研究开发了一种蛋黄-壳结构的MoO3/Co3O4@C纳米反应器，用于锂硫电池。该结构利用氧桥诱导的轨道振荡打破溶剂化屏障，加速界面转化。Mo-O-Co氧桥的动态振动通过4d轨道促进定向电子流，解决了多硫化物的穿梭效应和迟缓的氧化还原动力学问题。","scd":null,"kp":[]},{"i":38349,"as":"报道了一种由镍催化、未活化烯醇与烯基硼酸酯和芳基碘化物发生的1,2-芳基烯基化反应。该方法直接利用固有的羟基作为导向基团，无需预装辅助基团。反应条件温和，具有广泛的官能团耐受性和极佳的区域选择性。机理研究与DFT计算揭示了该反应基于Ni(0)/Ni(I)/Ni(II)的催化循环。","scd":null,"kp":[]},{"i":38350,"as":"提出一种金属有机框架（MOF）门控生物催化方法，通过将酶封装在ZIF-8中，使其在180°C下处理2分钟后仍能保留85%以上的活性。该方法日产量可达约50公斤，并通过双螺杆挤塑技术以每天一吨的规模混入PCL、PBAT和PLA等聚酯中。生产的酶@ZIF-8生物复合材料颗粒与标准热成型工艺兼容，实现了熔融加工聚合物的按需解聚。","scd":null,"kp":[]},{"i":38351,"as":"开发了一种一锅法串联催化系统，将二氧化碳加氢生成CH3O*中间体，并利用二元羧酸进行原位酯化，以大于99%的选择性直接生成二甲酯（如PET制造的单体）。该系统采用由金属有机框架衍生的催化剂，其特点为碳纳米限制的原子级Cuδ+位点锚定在约1.8 nm的四方相ZrO2纳米颗粒上。","scd":null,"kp":[]},{"i":38352,"as":"针对室温钠硫电池后期Na2S4转化为Na2S2和Na2S的动力学限制，提出了一种阶梯式靶向串联催化策略。该策略在导电碳载体中整合了原子级分散的Fe-N4位点和极性ZrO2纳米域，以克服迟缓的硫氧化还原动力学，提升电池的实际性能。","scd":null,"kp":[]},{"i":38353,"as":"引入了一款名为cgx的无偏结构预测软件工作流，通过探索算法和低成本最小模型预测复杂笼状结构。该方法仅依赖实验输入（构建块类型、特征及其化学计量比）即可预测笼状结构。这项技术可以在投入昂贵的实验之前提供高效的自动化结构设计。","scd":null,"kp":[]},{"i":38354,"as":"研究展示了在质量数160附近钬（Z=67）和铒（Z=68）同位素的高自旋结构。在这一区域，原子核在实验可达到的最高自旋下，集体激发模式与单粒子激发模式相互竞争以产生角动量。研究详细阐述了这些同位素的能级图及多种价空间和核心激发带终止现象。","scd":null,"kp":[]},{"i":38355,"as":"针对此前发表于《物理学评论C》第112卷关于高能中子发射与短程核子-核子关联的研究（Phys. Rev. C 112, 034614 (2025)）发布的勘误声明。","scd":null,"kp":[]},{"i":38356,"as":"提出了一种嵌入物理知识的贝叶斯神经网络（PE-BNN）框架，用于预测具有精细结构的能量依赖型裂变产物产额（FPY）。该框架将FPY与先验核物理知识相结合，通过引入与壳相关的现象学输入特征和激发能，实现了对FPY数据精细结构的准确预测。","scd":null,"kp":[]},{"i":38357,"as":"探讨在D-Wave量子退火机上解决运动方程声子方法中的大规模特征值问题。在核多体理论中，哈密顿矩阵的维度通常极大。尽管量子相位估计算法在原则上提供了解决方案，但该研究展示了量子计算在处理此类大规模且高要求特征值问题中的新视角和实际应用。","scd":null,"kp":[]},{"i":38358,"as":"传统上，原子核的八极形变被认为是由宇称相反的单粒子轨道之间的强Δl=3耦合引起的。本工作证明了常被忽视的Δl=1模式也发挥着重要作用。以八极幻数附近的轨道为例，研究详细阐述了单粒子轨道的Δl=1耦合对八极形变原子核结构的具体影响。","scd":null,"kp":[]},{"i":38359,"as":"利用Skyrme粒子-振动耦合模型，研究了Pb-208中矮偶极共振（PDR）态向低能2_1^+态的γ衰变。研究旨在解决核结构中长期存在的同位旋性质和集体性问题。通过分析PDR的γ衰变特征，深入探究了矮偶极共振的内部结构特性。","scd":null,"kp":[]},{"i":38360,"as":"研究表明，自1980年以来，全球强热带气旋季节正在变长，所有盆地的显著增长趋势为每十年9.9至13.8天，相当于每十年增加7.4%至21.9%。这主要是由于淡季热带气旋经历快速增强的概率提高所致。气候变暖是延长全球强热带气旋季节的根本原因。","scd":null,"kp":[]},{"i":38361,"as":"对全球地下水硝酸盐动态的模型显示，截至2020年，浅层含水层积累了162 ± 6 Tg的硝酸盐氮，全球10%的陆地面积地下水硝酸盐超过世界卫生组织饮用水限值。包气带中庞大的硝酸盐储量为4037 ± 214 Tg，将长期造成新的地下水污染。研究根据污染特征将全球农田划分为四种管理原型，以指导水污染治理。","scd":null,"kp":[]},{"i":38362,"as":"通过伊比利亚西南边缘高分辨率花粉记录与气候模型，研究发现中更新世过渡期的三阶段气候演化与北半球夏季日照幅度密切相关。早期强日照极值推动西风带北移；中期西风带南移引发大旱；晚期西风再次北移并与长周期气候响应一致，最终促成向10万年冰期旋回的转变。","scd":null,"kp":[]},{"i":38363,"as":"针对C(sp3)金属络合物固有的不稳定性，设计了一种手性螺环单膦配体((R)-SciPhos)。该配体集成了吸电子基团、季碳部分和刚性螺环骨架，有效克服了稳定性难题。该设计成功实现了β,β-二取代丙烯酸盐的不对称氢化反应，合成出高附加值的手性产物。","scd":null,"kp":[]},{"i":38364,"as":"提出了一种基于乙烯基连接共价有机框架（TFP-COF）的多孔复合聚合物电解质策略。TFP-COF中极性极强的–C≡N和–F部分与Li+形成多重强离子-偶极相互作用，降低了锂盐解离能，引导Li+定向传输，并诱导形成稳定的固体电解质界面（SEI），从而显著提升了固态锂金属电池的离子传导率和循环稳定性。","scd":null,"kp":[]},{"i":38365,"as":"报道了一种催化剂控制的立体选择性开环聚合方法，合成了带有乙烯基、烯丙基和炔丙基的高间规聚羟基脂肪酸酯（PHA）。其间规度（Pr）高达0.95，并具有宽广的玻璃化转变温度（低至-31°C）和熔融转变窗口。此外，通过定制化的后转化反应，成功制备了具有特定功能的网络结构PHA材料。","scd":null,"kp":[]},{"i":38366,"as":"短波红外有机光电探测器（SWIR-OPDs）在偏压下通常面临暗电流密度过高的挑战。本研究通过开发一种窄带隙p型聚合物作为短波红外吸收剂，构建了新型材料平台，使器件在高偏压条件下实现了超低暗电流密度，显著提高了探测率。","scd":null,"kp":[]},{"i":38367,"as":"报道了一种基于3,3'-亚甲基二苯二铵（3,3-MDPDA2+）的二铵基非Dion-Jacobson（DJ）相二维钙钛ite。打破传统认为有机二铵必然与两层无机[PbI6]板形成双侧氢键生成DJ相的认知。该新型二维钙skite材料被用于构建高效且高耐久性的2D/3D钙钛矿太阳能组件。","scd":null,"kp":[]},{"i":38368,"as":"报道了一种用于对映体纯二硫内酯进行立体选择性开环聚合的共价硼烷-硫脲有机催化剂。传统开环聚合催化剂常面临α-氢酸性导致单体消旋化的挑战，阻碍高结晶度材料的合成。该催化剂通过结合强路易斯酸性位点，有效解决了这一立体化学难题，用于合成化学可回收的高性能聚硫酯。","scd":null,"kp":[]},{"i":38369,"as":"报道了一种利用差分光电二极管的差分图像传感器（DIS），具有解耦的差分和隧穿模式。该传感器在感官层级实现了静态（亮度）和动态（振幅与极性）输出的完整采集与解耦。这些模式可通过传统的读出集成电路读取，支持高达640×512的规模化集成，为按需激活的视觉功能优化了能耗与性能的平衡。","scd":null,"kp":[]},{"i":38370,"as":"提出了一种在非晶态氧化物-金属界面上进行的交叉界面准串联催化策略，用于二氧化碳电还原生成正丙醇（C3产物）。该策略利用富含缺陷的非晶ZrO2促进*CO的生成与含氧C2中间体（*OCCOH）的稳定，并推动随后的C-C偶联反应，有效克服了C1-C2偶联迟缓和中间体不稳定的基本限制。","scd":null,"kp":[]},{"i":38371,"as":"将基于串联动态键的单体（ADM）引入钙钛矿薄膜中，通过原位交联控制结晶过程，实现了多模式钝化。ADM与钙钛矿晶格间的路易斯碱配位和氢键作用，以及交联网络内部的动态键赋予了柔性钙钛矿薄膜在温和条件下的瞬时自修复能力，解决了制备均匀、高结晶度且机械性能坚固的钙钛矿薄膜的挑战。","scd":null,"kp":[]},{"i":38372,"as":"提出了一种可持续的电催化策略，在环境条件下直接将工业废水中的亚硫酸盐（SO3 2-）升级转化为高附加值的磺酸盐分子。利用商业镍催化剂并以甲醇为代表性原料，该系统成功实现了废水中亚硫酸盐的电化学增值，克服了传统处理方法效率低、存在二次排放和硫资源流失的问题。","scd":null,"kp":[]},{"i":38373,"as":"提出了一种通过化学气相沉积（CVD）的选择性非均匀成核策略，实现了对室温铁磁性CrTe纳米片的非均匀生长控制。通过利用厚度分布与磁化反转之间的强相关性，自下而上控制磁畴演变，多厚度纳米片中的阶梯式磁化反转赋予了材料多种磁态。基于这种多厚度纳米片成功实现了可调的多态磁阻。","scd":null,"kp":[]},{"i":38374,"as":"报道了一种基于手性连接体交换构建的金属有机框架（MOFs）的发光传感策略，用于对映选择性识别。该方法在框架中同时引入了手性和缺陷位点，形成手性缺陷MOFs。其受限的纳米孔环境对对映体表现出截然不同的发光响应。构建的一对对映体MOFs对R-和S-型底物表现出相反的选择性识别性能。","scd":null,"kp":[]},{"i":38375,"as":"提出了一种单片三维集成的全固态离子门控碳纳米管（CNT）晶体管（sIGT）。通过薄膜中的离子含量工程和缩减至亚微米级的厚度，实现了对离子动力学的宽范围调控和可调离子电导率，离子时间常数达到微秒至毫秒级。该器件与晶圆级薄膜工艺完全兼容，在低离子含量下实现了稳健的直流操作。","scd":null,"kp":[]},{"i":38376,"as":"通过环丁烷、氧杂环丁烷、氮杂环丁烷取代的锍盐与氮杂环丙烯之间的Johnson-Corey-Chaykovsky反应，合成了一类新型“超应变”螺环化合物——螺环1-氮杂双环[1.1.0]丁烷。这类超应变螺环是制备高度功能化的1-氮杂螺[3.3]庚烷衍生物的合适前体，解决了后者合成方法稀缺的问题。","scd":null,"kp":[]},{"i":38377,"as":"报道了两种具有不同空腔结构（三棱柱形和碗形）的咪唑鎓功能化阳离子共价有机笼，作为受限平台用于无氧化剂的Hofmann-Löffner-Freytag（HLF）/环化级联催化。这两种有机笼均能在温和条件下高效介导N-氯代酰胺一锅法转化为吡咯烷衍生物，解决了高位点选择性调控自由基级联过程的挑战。","scd":null,"kp":[]},{"i":38378,"as":"通过拓扑转化策略在掺硫且带有碳空位的空心碳基质上合成了铁单原子催化剂（Fe SAs/NSCV）。通过配位与电荷调制工程调节轨道杂化，FeN4位点第二配位壳层中的S杂原子与相邻的碳空位协同加速了氧还原反应（ORR），使催化剂表现出优异的ORR性能，并实现了高功率密度的水系锌空气电池。","scd":null,"kp":[]},{"i":38379,"as":"报道了一种化学可编程的视网膜形态p-n二极管，在超紧凑器件平台上集成了尖峰响应、光适应和化学可调谐性。其功能由p-n结处的光电载流子分离和半导体/电解质界面处的电化学载流子消耗的相互作用所控制，克服了传统视觉传感器主要依赖外部物理刺激而缺乏化学可编程性的局限。","scd":null,"kp":[]},{"i":38380,"as":"利用原位发光测温法（LT）测量了甲烷氧化偶联（OCM）反应期间的局部催化剂温度。分析表明，在惰性条件下，局部催化剂温度比反应炉温度高出近250°C。该技术揭示了局部催化剂温度与反应生成热量之间的依赖关系，为解决OCM工艺因高放热性和高温导致的工业化难题提供了关键参数。","scd":null,"kp":[]},{"i":38381,"as":"提出了一种用于硫化物固态电解质（Li6PS5Cl, LPSCl）的癸酸（DA）脂肪酸涂层策略。该涂层使LPSCl在39%的相对湿度下暴露长达2小时后，仍能保持其结构、离子电导率并提高阳极稳定性。使用2wt% DA涂层的LPSCl作为正极电解质，搭配裸NCM85正极和Li-In负极的电池展现出175 mAh/g的容量。","scd":null,"kp":[]},{"i":38382,"as":"提出了一种协同控制逆向系间窜越（rISC）和激子循环的策略，突破了持久热激活延迟荧光（p-TADF）的动力学限制。该策略在保持krISC远大于磷光与非辐射衰减速率之和的前提下，同时减缓了rISC速率，从而克服了传统p-TADF材料由于动力学权衡导致的寿命限制，实现了长达1.0秒的热激活延迟荧光。","scd":null,"kp":[]},{"i":38383,"as":"引入了偏压触发的电导弛豫（BCR）技术，作为同时研究混合离子-电子导体（MIEC）薄膜中氧反应热力学、动力学和静电效应的新工具。BCR技术克服了传统方法无法在同一样品和单次测量中全面揭示复杂多步反应动力学过程、离子与电子缺陷浓度以及静电表面效应的局限性。","scd":null,"kp":[]},{"i":38384,"as":"开发了一种分步组装方案，通过六价阳离子笼（TPBCage6+）与葫芦[8]脲（CB[8]）的非共价结合，构建了一种用于溶酶体成像的深红发射型“笼中环”复合物生物探针。该复合物在热力学上具有优势，具有生物相容性、长波长发射和内在选择性，满足了生物成像技术对高性能生物探针的需求。","scd":null,"kp":[]},{"i":38385,"as":"首次利用胶体合成技术成功制备了UOS、UOSe和β-US2等含铀-硫族元素纳米材料。研究克服了铀强亲氧性导致极易生成二氧化铀的难题，系统研究了金属、硫族元素源和溶剂对溶液中物相形成的影响。并通过消化后修饰技术成功实现了对β-US2纳米颗粒的尺寸控制，产物物相经粉末X射线衍射证实。","scd":null,"kp":[]},{"i":38386,"as":"通过在新型及现有中性镍催化剂结构中引入Ni···O吸引力相互作用，实现了乙烯与一氧化碳的非交替共聚。该方法成功合成了在主链中带有低密度光降解酮基的酮-聚乙烯材料，有效解决了传统催化剂对一氧化碳耐受性有限的问题，降低了聚乙烯废物的环境影响并增强了可回收性。","scd":null,"kp":[]},{"i":38387,"as":"提出了一种电子结构导向的孔道工程策略，用于金属有机框架分离六氟丙烯（C3F6）和八氟丙烷（C3F8）。利用具有Jahn-Teller活性的Cu2+引导框架重构，实现了对MOF孔径的精确调控，成功克服了因C3F6和C3F8分子尺寸极其相似而导致的分离挑战，满足了生产高纯度含氟电子气体的需求。","scd":null,"kp":[]},{"i":38388,"as":"该研究介绍了一种机械互锁的靛蓝光开关。针对现有光开关在稀薄或复杂环境中因双分子策略受限的问题，研究人员利用拓扑受限的超分子相互作用，改善了靛蓝光开关的切换性能。该方法有助于红移激活波长并提升热半衰期，实现纳米尺度上对物质的精准控制。","scd":null,"kp":[]},{"i":38389,"as":"针对钠离子电池硬碳负极的初始库仑效率低和不可逆容量损失问题，研究人员提出了一种软接触预钠化（SCP）方法。该方法能够移除并回收钠源，大幅提升钠源的利用率和电池安全性。经SCP处理的硬碳负极在与NaNi1/3Fe等材料匹配时，初始库仑效率提升了约30.0%。","scd":null,"kp":[]},{"i":38390,"as":"研究首次在多金属氧酸盐基发色团中实现了二阶非线性光学响应的电化学开启。在硝基官能化芳基亚氨基多金属氧酸盐衍生物中，多金属氧酸盐的还原使得倍频散射光强度增加了15倍，达到目前氧化还原循环多金属氧酸盐的最高开启状态。计算和光谱研究表明，氧化态中方向相反的电荷转移导致低净响应。","scd":null,"kp":[]},{"i":38391,"as":"研究构建了一种可编程的活体电子界面，实现了两种活体微生物之间直接的光驱动种间电子转移。集成在蓝藻外膜的聚(3,4-乙烯二氧噻吩)网络拦截并传递光合电子流，同时通过超分子葫芦[7]脲主客体相互作用编程特定的细胞间组装，克服了非生物材料的限制。","scd":null,"kp":[]},{"i":38392,"as":"研究人员构建了一个耦合光热蒸发与淡水电解的创新平台，用于海水制氢。基于氢键交联机制和阴离子诱导的霍夫迈斯特效应，设计了涂有改性针状焦凝胶的轻质球形蒸发器，在3.5 wt%浓度下实现了2.32 kg m⁻² h⁻¹的连续脱盐性能，并具备耐盐自清洁能力，有效避免了设备腐蚀和催化剂失活。","scd":null,"kp":[]},{"i":38393,"as":"詹姆斯·韦伯空间望远镜（JWST）在z≈10-14的高红移处发现了明亮星系，并在更高红移（z≈15-30）发现了各种星系候选体。研究人员利用这些观测数据，提出了多种天体物理学和超越标准模型的物理学方案，旨在阐明暗物质与重子之间的相互作用。","scd":null,"kp":[]},{"i":38394,"as":"暗物质与质子之间的散射会导致小尺度涨落受到抑制，进而影响多种宇宙学可观测量。本研究利用第一代星系的紫外光度函数，搜寻了暗物质与质子散射的证据，分析了相互作用截面在不同速度指数（n=0, 2, 4）下的表现情况。","scd":null,"kp":[]},{"i":38395,"as":"本文是对先前发表的论文《金属中非互易等离子体拖曳引起的横向热光伏效应 [Phys. Rev. Lett. 136, 176901 (2026)]》的勘误声明。","scd":null,"kp":[]},{"i":38396,"as":"为了提高实际或未来核反应堆设计的中子学模拟精度，必须深入了解堆芯中子群。中子群部分受(n,xn)反应影响，这类反应会改变中子数量并降低能量。本研究结合伽马射线符合光谱学，对铀-238进行了非弹性中子散射实验，以获取相关核反应数据。","scd":null,"kp":[]},{"i":38397,"as":"研究发现转录因子NANOG在高浓度下会组装成具有自限制老化特征的胶束。NANOG是维持胚胎干细胞多能性的关键蛋白质，其组装而成的胶束能够驱动溶胶-凝胶转变，并调节DNA动力学，表现出复杂的流变学特性。","scd":null,"kp":[]},{"i":38398,"as":"研究提出了轨道交变磁性的概念，这是一种纯轨道自由度的对称性保护磁序。其特征是在实空间中具有有序的反平行轨道磁矩，但在动量空间中表现出动量依赖的轨道能带分裂，这与自旋交变磁性类似。","scd":null,"kp":[]},{"i":38399,"as":"交变磁性材料具有动量依赖的自旋分裂能带结构和净磁化为零的特性，在自旋电子学领域极具前景。本研究利用Andreev反射技术，探测了交变磁候选材料CrSb中动量依赖的自旋极化特性。","scd":null,"kp":[]},{"i":38400,"as":"研究利用微聚焦角分辨光电子能谱技术，直接可视化了扭曲双层双层石墨烯中平带在不同载流子密度和位移场下的演变。该技术直观地展示了莫尔微带的演化过程。","scd":null,"kp":[]},{"i":38401,"as":"在动能被淬灭的平带系统中，与能带色散相关的大多数常规长度尺度失去效用。尽管可以定义量子度量长度等几何长度尺度，但它们依赖于系统的嵌入方式。本研究深入探讨了平带系统中独立长度尺度的嵌入特性。","scd":null,"kp":[]},{"i":38402,"as":"手性在自然科学中具有深远影响。研究在中心对称的2M-WS2中发现了量子几何诱导的反常手性输运现象。这种手性输运伴随隐藏的对称性破缺，并通过电子磁手性各向异性等非线性响应被探测到。","scd":null,"kp":[]},{"i":38403,"as":"通常耗散对波传输不利，但本研究在声子晶体中通过实验证明了一个反直觉的现象：通过故意引入耗散可以增强拓扑谷输运。这表明在特定系统中，精心设计的耗散反而能够促进波的传输。","scd":null,"kp":[]},{"i":38404,"as":"在可扩展的原子量子处理器中，中性原子阵列依赖荧光读取，但极易受到加热和原子损失的影响。本研究开发了一种神经网络辅助的贝叶斯量子比特读取方法，能够在单光子水平下实现短曝光方案的量子态读取。","scd":null,"kp":[]},{"i":38405,"as":"研究提出了一种扩展的平均场理论，用于描述真实生物神经元网络。结果表明，这种扩展版本的平均场理论能够准确捕捉生物神经元网络中观察到的复杂活动模式。","scd":null,"kp":[]},{"i":38406,"as":"研究通过缺陷工程策略合成了富含硫空位的Cu4SnS4-x纳米片，并负载了小分子抑制剂NLG919。该纳米片具备64.7%的超高光热转换效率，实现了协同铜死亡、光热电催化和免疫疗法的联合治疗，克服了传统光热电催化疗法热电活性受限和肿瘤复发的挑战。","scd":null,"kp":[]},{"i":38407,"as":"在CO2加氢制甲醇反应中，混合金属氧化物表现出优异的性能。本研究引入了一种新型ZnHfOx催化剂，在锌含量为20 mol%时，其本征甲醇生成速率超越了参考催化剂ZnZrOx。研究强调了Zn-Hf位点邻近性和氧空位在促进甲醇生成中的关键作用。","scd":null,"kp":[]},{"i":38408,"as":"受天然铁硫簇启发，研究团队设计了S桥接的Fe-Fe双原子催化剂（Fe2N6-S/SNC）以打破限制单原子催化剂氧还原反应（ORR）活性的线性比例关系。硫桥作为内在的电荷转移通道，使两个Fe中心之间产生强烈的电子耦合。该设计克服了过渡金属3d轨道局域化导致的轨道重叠困难，实现了相干的电子调控，从而提升了ORR的催化效率。","scd":null,"kp":[]},{"i":38409,"as":"为满足生物医学研究减少动物使用的需求，研究团队开发了一种毫米级刚性多孔胶囊（RPC）用于三维细胞培养。该平台利用复合液体弹珠（由可熔的聚丙烯酸十八酯微粒和不可熔的疏水颗粒混合而成）经热处理制备而成。RPC具备高机械稳定性和渗透性，通过施加外部几何限制，能够促进细胞间的聚集与毫米级三维增殖，解决了大规模制备大尺寸细胞球体的技术挑战。","scd":null,"kp":[]},{"i":38410,"as":"受DNA碱基配对结构启发，研究人员通过多氢键策略成功开发了首个基于核苷酸的氢键有机框架（N-HOF-1）。该框架完全在水中合成，仅需将2-氨基-2'-氟-2'-脱氧腺苷（2FA）与三聚氰酸（CA）混合即可实现规模化生产。该技术克服了传统HOF严重依赖有机溶剂且在水相中易被破坏的缺陷，具备无金属、高生物相容性特点，可应用于治疗性细菌混合系统。","scd":null,"kp":[]},{"i":38411,"as":"高能锂金属电池（LMBs）对下一代储能和电动汽车技术至关重要，但传统电解液化学性质和不良的界面动力学导致锂枝晶生长、正极结构退化及界面持续恶化，阻碍了能量密度突破500 Wh/kg。本综述总结了限制LMB发展的基础挑战，并系统概述了理想电解质材料的基本特征与设计策略，旨在提升电池的电化学可逆性、稳定性与安全性。","scd":null,"kp":[]},{"i":38412,"as":"针对固态电卡制冷材料在宽温域内难以实现大绝热温差（ΔTad）的挑战，研究团队通过在弛豫铁电多层陶瓷电容器（MLCC）中引入B位中熵工程成功突破限制。所设计的Pb(Sc0.25Ta0.25In0.25Nb0.25)O3 MLCC在不需要过高电场的情况下，展现出巨大的直接测量电卡效应与极宽的稳定温度范围，为固态制冷技术的实用化提供了关键的材料解决方案。","scd":null,"kp":[]},{"i":38413,"as":"水系锌电池（AZBs）因电解液引起的锌腐蚀导致日历寿命严重衰减。研究团队提出一种悬浮电解液策略，仅在常规ZnSO4电解液中分散3 wt.%的Al2O3纳米颗粒。在日历老化测试方案下，添加Al2O3的Zn||Cu电池有效抑制了自发腐蚀现象，显著提升了电网储能场景下电池闲置期间的日历寿命和整体性能。","scd":null,"kp":[]},{"i":38414,"as":"采用硫族化物正极的全固态电池理论能量密度极高，但受限于迟缓的固态反应动力学。研究提出一种d-p能级匹配策略，通过将高熵合金（HEA）催化剂的d带与硫族化物正极的p带对齐来加速反应动力学。HEA具备丰富的活性位点、多样的原子环境与强烈的电子协同效应，有效提升了催化活性，克服了固态电池正极的动力学障碍。","scd":null,"kp":[]},{"i":38415,"as":"针对全无机钙钛矿CsPbI3在溶液沉积中因碘化二甲基铵（DMAI）残留导致高缺陷密度和易降解的问题，研究人员提出一种基于2,2,2-三氟乙基三氟乙酸酯（TFTF）的反应引导结晶策略。在退火过程中，TFTF与DMAI发生快速的酯-胺酰胺化反应，将DMAI转化为高挥发性物质并去除。该方法有效加速了CsPbI3的结晶形成，降低了材料缺陷。","scd":null,"kp":[]},{"i":38416,"as":"细胞能量代谢失衡是引发多种人类疾病的核心因素。基于线粒体和类囊体工程改造的生物能细胞器提供了一种革命性的治疗手段，旨在恢复细胞能量稳态。这些人工细胞器作为自主的代谢模块，能够在原位生成ATP、还原当量和氧气，同时调节氧化还原平衡、氧张力与免疫代谢信号传导，从而从根本上修复导致疾病进展的能量失调问题。","scd":null,"kp":[]},{"i":38417,"as":"研究揭示了发光分子晶体中由竞争性分子间相互作用引起的多晶型结构-性质切换行为。研究人员设计了带有溴和甲氧基侧链的氰基-β-取代二苯乙烯基苯衍生物，引入具有不同特性的同型与异型非共价竞争作用。单晶分析表明，分子间相互作用层级顺序的微小差异能够转化为宏观的发光功能响应，为通过分子设计精准控制固态相变和功能材料开发提供了平台。","scd":null,"kp":[]},{"i":38418,"as":"研究发现热力学稳定的构建单元在耦合其热力学活化前驱体的放热降解反应时，能够发生相分离。单独的热力学稳定产物无法形成液滴，而这一违背热力学的逆向转化过程由能量转导驱动，作为催化剂促进了放热化学反应。这种化学转化是实现路径控制的相分离的关键，该机制类似于生物大分子利用亚稳态驱动相分离，为构建非平衡态材料系统提供了全新策略。","scd":null,"kp":[]},{"i":38419,"as":"非均相光催化CO2还原制备合成气面临反应能垒高和电荷分离效率低的问题。研究在共价有机框架（COF）催化剂中引入N原子提高光电子转移效率，并利用两个负一价双齿配体提高Co(II)位点的电子密度。最优催化剂Triazine-COF-Co-SA实现了创纪录的合成气产率以及极高的H2/CO摩尔比，成功突破了光催化还原过程中的电子传输和活性限制。","scd":null,"kp":[]},{"i":38420,"as":"自充电水系锌离子电池（SC-AZIBs）是一种整合了能量收集与存储的前沿技术，能够利用光和机械振动等环境能量实现自主运行。该综述系统分析了空气、光照、热能和机械等多种自充电机制及其特定应用场景优势，深入探讨了正极材料与集成器件的设计策略。文章还全面总结了SC-AZIBs在材料本征限制、系统耦合效率及极端环境下面临的核心挑战。","scd":null,"kp":[]},{"i":38421,"as":"在JET-ILW的氘-氚（D-T）等离子体实验中，束-靶反应对聚变功率贡献巨大。模拟显示，在富氚等离子体中注入能量约120 keV的氘（D）束离子比在50:50的氘氚等离子体中产生更大的14 MeV聚变产额。此外，利用离子回旋共振加热（ICRH）对氘离子进行加热，可将体氘离子和快氘束离子加速至D-T反应的最佳能量范围，从而显著提升净聚变反应性。","scd":null,"kp":[]},{"i":38422,"as":"实现氚自持是未来聚变电站面临的关键挑战。MIT LIBRA项目下的BABY 1L实验旨在在氘-氚（DT）中子辐照下验证熔盐增殖剂系统中的氚增殖与释放。相比初始100毫升实验，该系统将增殖剂体积扩大十倍，并升级了热力、气体处理及中子诊断系统。四轮辐照实验测得的氚增殖比（TBR）与OpenMC中子学模拟结果高度一致，为聚变堆氚增殖技术提供了关键数据。","scd":null,"kp":[]},{"i":38423,"as":"使用ORB5粒子模拟程序进行了包含碰撞效应的全局电磁回旋动理学模拟，研究ADITYA-U托卡马克装置中的离子温度梯度（ITG）和捕获电子模式（TEM）湍流。线性模拟表明，有限碰撞效应使ITG模式增长率降低约10%。在真实的MHD平衡和特定磁几何形态下，ADITYA-U等离子体由于低电子温度导致的高碰撞率，对等离子体从磁轴到分离面的湍流输运特性产生了显著影响。","scd":null,"kp":[]},{"i":38424,"as":"在JET L-mode条件下的氘-氚匹配脉冲对实验表明，氚脉冲的能量约束时间提升了13%至16%。这种同位素效应主要源于电子热传输通道和等离子体边缘区域。喷气调制实验结果证明，核心等离子体粒子传输通道不存在大尺度的同位素效应。EDGE2D-EIRENE模拟也证实了氘和氚脉冲之间的径向电离分布非常相似，明确了热传输是改善约束的主导因素。","scd":null,"kp":[]},{"i":38425,"as":"研究对比了EUROFER97材料在氘气与氘等离子体暴露下的滞留行为差异。核反应分析和热脱附光谱表明，等离子体暴露导致单一的低温脱附主峰，而气体暴露则产生额外的高温脱附峰。在低于7微米的深度范围内，两种加载方式产生了截然不同的氘深度分布。这些实验结果结合模拟分析，揭示了未来聚变堆结构材料中氚滞留机制的差异，对保障聚变堆安全性和氚自持至关重要。","scd":null,"kp":[]},{"i":38426,"as":"可转座元件（TEs）能够在基因组中复制并常被用作顺式调控元件。基于国际人类表观基因组联盟4867个ChIP-seq实验数据，研究分析了47种细胞类型中6种组蛋白标记与TEs的关联。结果显示TEs在组蛋白标记中通常呈现整体贫化，但在特定情境下显著富集。研究精确识别出456个细胞类型特异性的组蛋白-TE三元组，揭示了TEs通过细胞类型特异的表观遗传关联深刻影响人类调控网络。","scd":null,"kp":[]},{"i":38427,"as":"甲病毒M1在骨肉瘤（OS）中展现出强效的溶瘤活性。蛋白质组学和ChIP-seq分析证实，DNA导向RNA聚合酶II亚基RPB1在致癌超级增强子活性中起关键作用，是M1病毒调控的直接靶点。M1病毒的抗肿瘤效果与超级增强子区域的RPB1转录依赖性呈正相关。机制上，M1病毒的非结构蛋白NSP2能够直接破坏超级增强子的激活，从而阻断致癌转录，实现对骨肉瘤的靶向杀伤。","scd":null,"kp":[]},{"i":38428,"as":"硫化氢（H2S）在抗菌肽（AMP）的抗感染功能中发挥关键作用。人源抗菌肽LL-37及其小鼠同源物CRAMP通过3-巯基丙酮酸硫转移酶（3MST）在大肠杆菌和产气荚膜梭菌中诱导产生H2S。生成的H2S进一步促进活性氧（ROS）积累，从而导致细菌死亡。研究揭示了H2S在介导多种动物物种AMP抗感染功能中的核心机制。","scd":null,"kp":[]},{"i":38429,"as":"人体真菌病原体球孢子菌的不同发育阶段会引发宿主差异性的免疫反应。其关节孢子激活TLR2并诱导巨噬细胞中的NLRP3-pyrin炎症小体，铁死亡信号促进对关节孢子的杀灭。当转化为内孢囊时，仅有破裂的内孢囊能通过NLRP3-pyrin和GSDMD-GSDME孔触发IL-1β产生。此外，巨噬细胞中的TLR2-NLRP3-pyrin-IL-18轴会促进内孢囊生长，而Caspase-1缺陷小鼠表现出对该疾病更强的耐受性。","scd":null,"kp":[]},{"i":38430,"as":"针对空间多组学数据整合与降维问题，研究者开发了SpaMV（Spatial Multi-View）表示学习算法。现有方法通常将不同组学数据投影到统一的潜在空间，掩盖了各组学的独特信息。SpaMV算法打破了这一局限，能够明确捕获不同组学间的共享信息以及特定组学的独立信息，从而为空间多组学数据提供更全面、更具可解释性的表征。","scd":null,"kp":[]},{"i":38431,"as":"细胞核内存在直接调控基因表达的代谢途径。研究发现，线粒体酶乌头酸酶（ACO2）和异柠檬酸脱氢酶（IDH2）可定位于细胞核内，催化α-酮戊二酸的还原羧化反应，快速合成柠檬酸以扩大核内乙酰辅酶A池。核内的IDH2和ACO2与KAT2A/GCN5形成复合物，促进组蛋白乙酰化，从而增加染色质可及性并激活细胞增殖相关基因。","scd":null,"kp":[]},{"i":38432,"as":"干扰素调节的CD34+肺成纤维细胞在肺癌转移前微环境的形成中起关键作用。多组学测序表明，这些成纤维细胞通过VLDLR介导的脂蛋白代谢激活，增加胞内脂质积累并表达CD155。CD155+成纤维细胞会强烈诱导细胞毒性CD8+ T细胞和NK细胞耗竭，进而形成免疫抑制性的转移前微环境。通过遗传学手段阻断干扰素-VLDLR-CD155轴可显著恢复免疫监视功能并抑制多种肿瘤模型的肺转移。","scd":null,"kp":[]},{"i":38433,"as":"研究者在钢中原位共晶凝固制备的微米级二硼化钛（TiB2）陶瓷中，实现了接近理论值的强度和高弹性。微观力学实验及有限元分析表明，这种定向微米级晶体在拉伸侧可承受数吉帕的应力，弹性应变高达9%。直接微拉伸测试证实，超过4立方微米的体积能够承受约13 GPa的均匀拉伸应力而不发生断裂，展现了微米尺度结晶固体极其优异的力学性能。","scd":null,"kp":[]},{"i":38434,"as":"呼吸链复合物I通过长距离质子耦合电子转移（PCET）驱动细胞能量代谢。结合冷冻电镜、生物物理实验和多重模拟，研究者在复合物I功能核心的E通道中鉴定出一个保守的羧酸开关点（D79NuoA）。该开关点通过建立动力学门控来介导质子转移，并将氧化还原化学反应与质子泵送相耦合。该位点的突变直接关联于人类患者中严重的神经退行性疾病。","scd":null,"kp":[]},{"i":38435,"as":"癌基因突变引发的后果高度依赖于组织所处的发育阶段。研究提出一个统一模型：早期生活中的致癌事件主要通过“保留”机制，稳定短暂的胚胎-胎儿转录与表观遗传程序；而晚期生活中的突变更多依赖“重塑”机制，通过逐步的转录和染色质重塑来重新激活被抑制的致瘤胎儿状态。将发育时间线纳入癌症建模和风险分层，有助于解释具有相同基因病变的儿童与成人癌症在轨迹、行为和治疗反应上的差异。","scd":null,"kp":[]},{"i":38436,"as":"多梳抑制复合物1的核心催化亚基Ring finger protein 2（RNF2）在结肠炎期间调控单核细胞向巨噬细胞的转化。该蛋白在溃疡性结肠炎患者的未成熟结肠和循环单核细胞中高表达。髓系特异性敲除RNF2的小鼠表现出实验性结肠炎减轻、单核/巨噬细胞平衡恢复。机制上，RNF2通过组蛋白H2A第119位赖氨酸的单泛素化抑制Runx3转录因子的表达，从而介导炎症过程。","scd":null,"kp":[]},{"i":38437,"as":"为解决数字病理学图像分析中计算效率低下的问题，研究者开发了深度学习框架EAGLE。该框架模拟病理医生的行为，结合任务无关的切片选择与详细的特征提取，仅选择性地分析信息量高的图像区域。在涵盖9种癌症类型、43项任务的基准测试中（包括形态学、生物标志物预测、治疗反应和预后），EAGLE的性能比传统的图像块聚合方法高出23%，实现了极高的计算效率。","scd":null,"kp":[]},{"i":38438,"as":"植物通过激活丝裂原活化蛋白激酶级联反应响应机械刺激。研究发现，机械刺激可在60秒内激活MAPKKK3/4/5-MKK4/5-MPK3/6级联，诱导约800个基因表达。这些基因大部分与CAMTA1/2/3转录因子调控的触觉响应基因重叠，揭示了MAPK与CAMTA之间的相互作用。MKK4/5的缺失会导致触觉调控的蛋白质磷酸化发生全面障碍，证实其为机械信号传导的关键调节因子。","scd":null,"kp":[]},{"i":38439,"as":"EHMT2基因编码的G9a甲基转移酶功能丧失会导致常染色体显性遗传的Kleefstra综合征。研究在患者中鉴定出7个全新的EHMT2新发变异，这些患者表现出与EHMT1单倍剂量不足引起的Kleefstra综合征1型相似的临床特征和表观遗传特征。体外研究表明，这些变异产生的G9a蛋白结构稳定，但由于与组蛋白H3尾部或S-腺苷甲硫氨酸的异常相互作用，导致其完全丧失催化能力。","scd":null,"kp":[]},{"i":38440,"as":"溶酶体双孔通道2（TPC2）能够控制钙调蛋白依赖性的STIM1失活。TPC2的激活会通过加强STIM-Orai激活区域（SOAR）快速且持久的钙调蛋白依赖性失活，从而抑制钙库操纵性钙内流（SOCE）。实验证实，TPC2激活剂NAADP和TPC2-A1-N在多种细胞系中消除了SOCE，增强了STIM1控制的Orai1通道的缓慢钙依赖性失活，并阻止了RFP-STIM1向TIRF平面的募集。","scd":null,"kp":[]},{"i":38441,"as":"针对锂硫电池中多硫化物转化不平衡和严重的穿梭效应问题，研究者以铁、氮、硫共掺杂的多孔石墨烯为模型催化剂，阐明并验证了硫还原的完整级联催化路径。密度泛函理论表明，铁位点优先结合并活化长链多硫化物，而氮、硫位点则负责后续短链中间体的转化。这种精准设计的级联催化路径实现了多硫化物的平衡转化，为提升锂硫电池性能提供了有效策略。","scd":null,"kp":[]},{"i":38442,"as":"通过2.2埃分辨率的单颗粒冷冻电镜技术，研究解析了苏云金芽孢杆菌Vpb4Aa2蛋白的成孔结构。与其他已知双组分毒素家族成员不同，作为单组分的Vpb4Aa2结构中缺失了分子瓶颈，且具有电中性的β-桶状结构。电生理学初步研究证实，与典型的PA蛋白相比，Vpb4Aa2孔隙结构展现出更大的离子通量，揭示了其独立发挥成孔功能的结构基础。","scd":null,"kp":[]},{"i":38443,"as":"研究开发了一款名为3D PURE的便携式三维实时超声系统，专为克服乳腺体积成像的限制而设计。该系统采用包含角间隙偏移几何形状的盒式阵列设计，将峰值串扰抑制了3.73 dB，支持高达24 V的发射电压。定制的可流式背衬层（声阻抗6.12 MRayl）有效保护了脆弱的引线键合。该技术提供了不依赖操作者的便携式乳腺筛查及纵向监测方案。","scd":null,"kp":[]},{"i":38444,"as":"研究在假单胞菌中鉴定了缩肽类HDAC抑制剂FR-901375的生物合成基因簇，揭示了其组合生物合成的分子基础。这类聚酮-非核糖体肽杂合化合物（如罗米地辛）的组装过程，涉及保守的锌离子结合药效团与可变肽基帽的融合。通过比较不同PKS-NRPS装配线的同源基因，研究者阐明了细菌如何利用模块化酶逻辑构建靶向HDAC的复杂杂合天然产物。","scd":null,"kp":[]},{"i":38445,"as":"2010至2023年间，中国二氯甲烷（CH2Cl2）和氯仿（CHCl3）等未受蒙特利尔议定书管制的短寿命氯化物的排放量呈上升趋势，其中CH2Cl2排放量已翻倍。预计到2035年，在按常规情景下这些物质排放量将持续增长。在破坏臭氧层的CFC-11当量排放中，氯代短寿命物质的占比已超过氢氯氟碳化物。研究指出，实施最佳可行技术有望大幅减少这两种物质的累计排放量。","scd":null,"kp":[]},{"i":38446,"as":"研究发现，不同排放情景下北半球大气CO2季节性周期变化的主导驱动因素将发生根本性转变。在高排放情景（SSP5-8.5）下，陆地碳汇的增强主导并放大了CO2的季节性变化，基于地面的观测依然是可靠的陆地碳汇代理指标。相反，在低排放情景（SSP1-2.6）下，化石燃料排放的季节性波动将取代陆地生态系统，成为主导CO2季节周期变化的核心因素。","scd":null,"kp":[]},{"i":38447,"as":"中亚是早期人类扩散的关键迁徙走廊。研究针对塔吉克斯坦黄土-古土壤地层中富含石器组合的旧石器时代卡拉套文化，首次提供了全面描述及绝对年代学框架。此前，该地区早期人类活动的确切年代长期缺乏绝对年龄约束。通过建立可靠的年代标尺，该研究为理解跨多个冰期-间冰期循环的环境变化及早期人类在 Central Asia 的占领历史提供了关键证据。","scd":null,"kp":[]},{"i":38448,"as":"铁作为海洋生物限制性营养盐，对碳等营养物质的沉积埋藏起关键控制作用。针对斯瓦尔巴-巴伦支冰盖邻近的耶马克高原沉积物记录的研究表明，在过去13.5万年期间，冰盖进退期间至少发生了5次脉冲式活性铁输出。这些富铁地层保存了大量活性铁相，其中部分在沉积时具有生物可利用性。这揭示了敏感的冰川系统在冰退或冰进期间对海洋活性铁传输的重要机制与历史影响。","scd":null,"kp":[]},{"i":38449,"as":"研究利用碎屑透长石示踪颗粒和鱼类系统发育学，揭示了美国科罗拉多河大陆尺度河流系统在800万至480万年前的发展过程。源自从北方的沙粒依次出现在犹他州、亚利桑那州和科罗拉多河下游地层中，表明古河段自北向南实现连通。这一时间线与鱼类谱系分化的分子钟估计相吻合。河流的整合是对黄石热点轨迹和落基山脉源头隆升的响应，同时40Ar/39Ar年代测定精确了导致沉降的地幔滴落的时间。","scd":null,"kp":[]},{"i":38450,"as":"厄尔尼诺-南方涛动（ENSO）的周期决定了气候变异与极端事件频率。基于多模式大集合模拟表明，在未来变暖情境下，ENSO周期倾向于缩短。这种周期变化通过遥相关扩展至热带气候模式并全球传播，产生全球性的ENSO频率同步牵引效应。该现象在末千年模拟和非平稳、非单调的二氧化碳强迫响应中均普遍存在。","scd":null,"kp":[]},{"i":38451,"as":"异戊二烯是全球最丰富的生物源挥发性有机化合物，其大气氧化影响二次有机气溶胶的形成。研究建立了一种自由基组学方法，用于特异性识别和检测挥发性有机物氧化过程中产生的数百种自由基异构体。应用于羟基自由基引发的异戊二烯氧化体系时，该方法成功量化了四种添加了羟基的烯丙基自由基，并确定了它们的分支比，填补了分子机制上的关键实验空白。","scd":null,"kp":[]},{"i":38452,"as":"全球路网扩张引发的野生动物死亡率分布存在不平等现象。结合实地调查、全球公民科学记录和中国高分辨率数据集分析表明，中低收入国家在标准化物种库和采样努力后，比高收入国家承受更重的路杀负担。在受威胁的脊椎动物中，碰撞率的差异最为显著，高达2至4倍，这反映了受威胁动物碰撞率升高，而非受影响物种名单的扩大。","scd":null,"kp":[]},{"i":38453,"as":"北方永久冻土区植被褐化对生态系统功能具有重要影响。研究通过综合多种遥感数据集（包括NDVI、SIF、叶片叶绿素浓度）和CMIP6模型中的总初级生产力模拟，对低矮灌木和草本植被在土壤与大气水分双重亏缺下的褐化模式进行了表征。研究结果确认了由复合干燥条件引发的显著植被褐化模式，揭示了植被对极端水分缺乏的直接生理响应。","scd":null,"kp":[]},{"i":38454,"as":"","scd":null,"kp":[]},{"i":38455,"as":"线粒体短链烯酰辅酶A水合酶1（Echs1）缺失会导致严重的脑病。研究发现，神经干细胞中Echs1缺失会导致脂肪酸积累，抑制增殖并促进凋亡。机制上，Echs1缺乏增加了巴豆酰辅酶A水平，导致全局组蛋白巴豆酰化富集于H3K9cr，进而上调内质网应激调节因子Atf4。Atf4随后上调脂肪酸合酶，形成加剧脂质积累的正反馈回路，最终阻碍神经发生。","scd":null,"kp":[]},{"i":38456,"as":"","scd":null,"kp":[]},{"i":38457,"as":"研究利用电压成像技术，对小鼠虚拟导航过程中海马体CA1区锥体神经元和生长抑素阳性中间神经元的亚阈值和峰值活动进行了纵向记录。部分两类细胞均表现出空间调谐特征，许多SST神经元表现出速度调谐或跨空间均匀放电。胞内记录揭示了增加的theta功率和不对称的斜坡样去极化，为位置细胞在空间编码过程中保持稳定性与表征漂移之间的独特平衡提供了机制见解。","scd":null,"kp":[]},{"i":38458,"as":"番茄果实的酯类代谢物合成受DNA低甲基化介导的转录抑制控制。SlSPL-CNR转录因子表现出对甲基化敏感的DNA结合特性，专一结合未甲基化的GTACGG基序。在果实成熟期间，SlDML2介导的SlAAT1启动子去甲基化允许了SlSPL-CNR的结合，从而抑制SlAAT1表达并调节酯类物质（果实风味的关键成分）的生物合成。结构分析显示，胞嘧啶甲基化引起空间位阻冲突，解释了其对甲基化的敏感性。","scd":null,"kp":[]},{"i":38459,"as":"生物质衍生碳由于缺乏足够的芳香族缩合，通常无法进行液相石墨化。研究提出一种化学引导策略，通过脱氧-芳构化和受控低聚反应，将松香树脂来源的萜烯转化为真正的可石墨化沥青。该沥青具有内在的低杂原子含量。热分析和偏光显微镜证实，其在加热过程中表现出热塑性行为并形成了中间相。这成功实现了从生物质萜烯大批量制备石墨材料。","scd":null,"kp":[]},{"i":38460,"as":"富锂层状氧化物正极材料能提供超过280 mAh g⁻¹的容量和1000 Wh kg⁻¹的比能量，但其单晶版本的高体积能量密度制备和倍率性能面临挑战。研究开发出具有快速充电能力的单晶富锂层状氧化物，在5C快充下0.2C放电容量为248 mAh g⁻¹，5C快放容量达179 mAh g⁻¹。其快充性能的突破源于共同表面相阳离子有序排布的复杂结构设计。","scd":null,"kp":[]},{"i":38461,"as":"研究在两个互补的工程量子多体系统中，建立了黎曼ζ函数非平凡零点与动态量子相变之间的直接对应关系。这些系统分别通过平均累积相位因子和Loschmidt振幅来表征。这一对应关系将黎曼假设转化为在特定温度下发生相变的现象，并将其识别为一种新的跃迁机制。原理验证实验在量子处理器上证明了该理论，为黎曼假设的验证提供了全新物理视角。","scd":null,"kp":[]},{"i":38462,"as":"研究提出一种用于可穿戴传感的偏振增强技术，通过开发自旋光子纤维纺织品实现多变量干扰之间的高效解耦。该技术采用离散螺旋锚固策略，在挤出过程中将圆偏振材料自主嵌入纤维中，制备出连续长度超过1300米的超长自旋光子纤维。所得核-鞘珠状纤维的发光不对称因子达0.41。编织成织物后，能够对动态多维环境中的信号进行实时采集。","scd":null,"kp":[]},{"i":38463,"as":"研究通过在介观状态下调控电子能带结构增强光学非线性，证明了结晶银薄膜的二阶谐波产生（SHG）随着厚度减少到几个单原子层而显著增强。这些处于体块和二维系统边界的超薄膜，展现了随厚度减薄而带来的SHG大幅增强效应。该策略通过调控纳米结构尺寸与形貌来操纵光学近场，突破了传统体材料固有非线性光学响应较弱的限制，为光子技术提供了新思路。","scd":null,"kp":[]},{"i":38464,"as":"质子交换膜水电解槽中铱基阳极催化剂的电化学非活性“死区”限制了其利用率。研究证实，离聚物破坏IrO2纳米催化剂导电网络导致的极低面内电子电导率是主导因素。通过开发顺序喷涂策略，将原始导电催化剂层与离聚物沉积解耦，保留了连续的电子传输路径。该方法成功激活了面内死区，显著提高了质子交换膜的性能表现。","scd":null,"kp":[]},{"i":38465,"as":"针对6G可重构智能表面（RIS）技术响应慢、损耗高、集成成本大的问题，研究首次利用标准半导体工艺直接实现了RIS系统。提出的STARE架构将定制的选择性重叠二极管集成到高阻硅中，实现了可调谐的开启电阻和关闭电容，同时保持低功耗。采用磁耦合的无通孔透射单元消除了硅通孔需求，简化了制造并降低了衬底损耗。实验验证了该方案的有效性。","scd":null,"kp":[]},{"i":38466,"as":"研究利用持久性硝酰自由基TEMPO作为模型系统，在超音速分子喷射中对其自由基对的旋转进行了表征。实验采用同位素敏感的高分辨率微波光谱，揭示了两种避免电子转移的独特中性配对模式。同位素标记实验证实，自由基对内分子的N···O距离分别为3.38和4.93 Å，建立了非共价范德华相互作用，未观察到电子自旋超精细效应。","scd":null,"kp":[]},{"i":38467,"as":"导电二维共价有机框架薄膜的电荷传输常受限于晶界和无定形区。研究提出通过分子分散的共轭聚合物（CPs）桥接多晶COF域的简便策略。在电子排列、几何兼容性和链长标准的指导下，组装成异质结构的COF-CP组合展现出大幅增强的导电性。研究证实，这种增强仅在低于CP结晶阈值时发生，证明桥接CP需要短程有序或非晶特性才能有效实现分子级连接。","scd":null,"kp":[]},{"i":38468,"as":"为提升弹性体的韧性，研究提出一种顺序激活多路径能量耗散策略，在单一聚合物中集成了机械互锁网络、可断裂力色团和编织网络。聚氨酯中的轮烷交联剂作为初级耗能途径，当轮烷滑动达到极限后，大环中的三苯二甲酸酯力色团发生牺牲性断裂作为二级途径。该非协同的结构演变机制克服了传统多重耗能途径在结构演化后失效的缺陷。","scd":null,"kp":[]},{"i":38469,"as":"Cas9蛋白衍生自人类病原体，在基因编辑中引发安全性担忧。研究比较了SaCas9、AsCas12a和CasΦ（源自细菌噬菌体）在未免疫个体中的免疫原性风险。体内外分析表明，这三种Cas蛋白被抗体和T细胞识别的水平相似。质谱鉴定证实，源自这三种Cas蛋白的肽段在9种MHC-I蛋白上均存在递呈，表明即使是非人类致病源来源的Cas蛋白依然具有交叉免疫识别特性。","scd":null,"kp":[]},{"i":38470,"as":"T细胞转染传统上具有挑战性。研究发现，将纳米颗粒靶向具有快速受体介导内吞作用的T细胞表面受体，可改善治疗效果。实验表明，CD2和CD7的内化作用显著高于CD3或CD4。靶向CD2和CD7能提升非激活态原代CD4+ T细胞对纳米颗粒的内化，并增强其结合特异性。使用抗CD2或CD7抗体修饰的mRNA-脂质纳米颗粒，在体外成功增强了向CD4+ T细胞的mRNA递送效率。","scd":null,"kp":[]},{"i":38471,"as":"倒置钙钛矿太阳能电池中广泛使用的聚三芳基胺(PTAA)因在氧化铟锡(ITO)上的结晶和聚集，导致薄膜连续性受损并降低组件稳定性。研究表明，4-氟苄基膦酸(4FBPA)能够修饰ITO表面，诱导PTAA发生纳米级无定形化，形成均匀的亚10纳米空穴选择层。4FBPA通过脱水反应与ITO结合，调谐光阳极的功函数和表面自由能，改善与PTAA的能级对齐，从而提升光伏性能与稳定性。","scd":null,"kp":[]},{"i":38472,"as":"大脑皮层沿感觉运动到联合(S-A)轴组织。研究提出了多模态诱导-排斥网络发展(MIND)模型，结合多物种证据说明S-A模式的形成机制。该轴线由两种在转录组学上对立的程序驱动，通过相互竞争的诱导与排斥过程塑造。其中“中央旁”程序在额颞极周围被诱导，并逐渐向未分化中枢区域推进，从而共同塑造皮层感觉运动-联合轴的发展。","scd":null,"kp":[]},{"i":38473,"as":"肌肉烟碱型乙酰胆碱受体突变会导致通道开启受损（快通道）或延长（慢通道），引发以严重肌无力为特征的先天性肌无力综合征(CMS)。研究人员利用冷冻电子显微镜、化学生物学和电生理学技术，确定了这些致病性受体缺陷的结构机制。通过揭示相关的微观结构基础，该研究阐明了如何通过药理学手段纠正这些与先天性肌无力相关的乙酰胆碱受体缺陷。","scd":null,"kp":[]},{"i":38474,"as":"锂金属固态电池由于锂枝晶的引发和增殖，在低于1 mA cm−2的低充电速率下也会因短路而失效。研究开发了一种面内双轴压缩方法，提供了直接证据表明，当表面引发机制失效时，石榴石型Li6.6La3Zr1.6Ta0.4O12固态电解质在长期循环过程中，其枝晶会从电解质内部引发。该发现证实了固态电解质内部是枝晶引发的区域之一。","scd":null,"kp":[]},{"i":38475,"as":"螯肢动物螯肢和书鳃的早期演化机制一直存在争议。有假说认为螯肢由寒武纪大附肢类的短大附肢演化而来，书鳃则起源于其躯干附肢。研究人员利用X射线微计算机断层扫描技术，揭示了早寒武世真节肢动物Urokodia aequalis的三维解剖结构。该化石的解剖特征为阐明大附肢类附肢向真正螯肢及书鳃的形态转变过程提供了关键化石证据。","scd":null,"kp":[]},{"i":38476,"as":"透明细胞肾细胞癌(ccRCC)主要受转录因子HIF-2α驱动。在ARC-20研究中，口服选择性HIF-2α抑制剂Casdatifan在难治性转移性ccRCC患者中表现出具有临床意义的持久抗肿瘤活性和可控的安全性。在每日一次100毫克队列（32人）和总体队列（127人）中，确认的客观缓解率(ORR)分别为35%和31%。因不良事件停药率极低（3%），主要类效应毒性包括贫血和缺氧。","scd":null,"kp":[]},{"i":38477,"as":"公众对科学的信任无法仅依靠意识形态光谱一端的狭隘选民群体的支持来维系。科学家应当正视并认识到自身的政治偏见，这对于建立和维持广泛的公众对科学的信任至关重要。","scd":null,"kp":[]},{"i":38478,"as":"FAIR（可查找、可访问、可互操作、可重用）指导原则为确保科学数据的可访问性和可重复性奠定了坚实基础。在实施十年后，研究人员正在思考如何超越这些原则，进一步提升科学数据的开放与信任。","scd":null,"kp":[]},{"i":38479,"as":"研究人员已经鉴定出进化上高度保守的靶点。这些靶点不仅在不同疟原虫物种及其各个生命周期阶段中普遍存在，同时也能被人体免疫系统有效识别，为开发通用型疟疾疫苗提供了关键靶标。","scd":null,"kp":[]},{"i":38480,"as":"通过结合单神经元记录与人工智能技术，研究人员识别出了使人类具备语言生成能力的特定脑细胞。这些细胞广泛分布于人类大脑中，能够编码特定的含义和语法特征，反映词汇如何组装成短语和句子。单神经元活动专门负责编码词汇含义、语法结构或更高阶的句子结构。","scd":null,"kp":[]},{"i":38481,"as":"一家生物学期刊实施了向同行评审专家支付报酬的政策。实践结果表明，这一做法不仅保持了高质量的评审水准，还将作出首次编辑决定的时间大幅缩短了85%，有效提升了出版效率。","scd":null,"kp":[]},{"i":38482,"as":"生物多样性对单一营养级生态系统功能有积极影响，但在多营养级食物网中的变化机制尚不明确。研究通过量化来自海洋、湖泊、溪流和土壤生态系统的318个高分辨率复杂食物网中的能量流动（代表初级消费和捕食两项主要功能），发现食物网的复杂性调节着生物多样性与生态系统功能间的关系，且在所有营养级中生态系统功能均随分类群丰富度的增加而持续提升。","scd":null,"kp":[]},{"i":38483,"as":"结直肠癌经常转移至肝脏，且转移灶在肝组织中的生长能力决定了患者的预后。最新研究表明，肝脏脂肪会促进预后不良的特定肝转移模式。患有脂肪肝疾病的个体在结直肠癌中发展为侵袭性继发性肿瘤的风险更高，这表明患者个体特定的生理特征可用于风险分层和治疗指导。","scd":null,"kp":[]},{"i":38484,"as":"这篇文章探讨了RS-232通信协议及其相关技术，将其描述为一种与另一种生活或过去时代的联系，反映了技术更迭带来的情感共鸣。","scd":null,"kp":[]},{"i":38485,"as":"高温环境会导致植物细胞膜变弱并发生渗漏。水稻能够通过快速调整细胞膜上的脂质成分来应对这一不利影响，从而抵消高温造成的损害。这种对膜脂质含量的重排机制，使水稻植株能够在热浪等热应激条件下保持细胞膜的稳固并维持机能。","scd":null,"kp":[]},{"i":38486,"as":"论文工厂生成的潜在欺诈性论文往往在彼此之间进行相互引用。这种相互引用行为不仅虚增了这些伪造成果的引用次数，还人为地推高了发表这些论文的期刊的影响因子。","scd":null,"kp":[]},{"i":38487,"as":"公众对科学的信心并未全面崩溃，但科学界依然面临着亟待解决的信任难题和挑战，科学家需要正视这些问题并采取相应措施以巩固公众信任。","scd":null,"kp":[]},{"i":38488,"as":"全球范围内公众对精英机构的信任度正在下降。将公众参与纳入科学研究过程和政府政策建议中，有助于扭转信任下滑的趋势，从而将公众置于科学和政策的核心位置。","scd":null,"kp":[]},{"i":38489,"as":"直接成像技术证实，电流流入原子级薄层晶体管的接触电极能够被按比例缩小至仅几纳米长。这表明随着晶体管尺寸的不断缩小，电极尺寸也能实现相应的微缩突破。","scd":null,"kp":[]},{"i":38490,"as":"数据研究揭示了全球科学信任危机的真实情况与具体问题所在。数据表明，所谓的全球信任危机并非全面存在，研究明确了信任缺失的具体领域和根本问题，为理解和解决科学与公众之间的信任问题提供了事实依据。","scd":null,"kp":[]},{"i":38491,"as":"研究开发了一种单步工艺，利用边缘带有氢原子的平面碳“纳米石墨烯”分子，成功制备出尺寸仅为3至4纳米的分子纳米金刚石。该方法可在毫克级别生产尺寸分布极窄的纳米金刚石，并可进一步改造以生成荧光纳米金刚石。该技术突破了制备小尺寸、高结晶度和均匀性纳米金刚石的难题，为量子传感和成像领域的原子级发光体提供了新材料。","scd":null,"kp":[]},{"i":38492,"as":"研究通过对三种不同粒径和结晶度的层状锰氧化物在相同溶液条件下进行孵育，观察到结晶度对锰氧化物矿物相变的决定性影响。实验表明，空位密度和表面能等纳米级矿物性质会调节锰离子的吸附几何结构，进而影响电子转移和结构重组，最终生成不同的隧道状锰氧化物。这一结论证明，与结晶度相关的矿物结构特性是导致自然界中锰氧化物多样性的关键且被此前忽视的因素。","scd":null,"kp":[]},{"i":38493,"as":"中村荣一教授分享了他在化学研究领域的丰富经历、重要成就以及未来愿景。此外，他还深刻阐述了自己的生活哲学，并提及他在中国开启的科研新篇章，展示了其在科学研究与个人生活理念上的双重探索。","scd":null,"kp":[]},{"i":38494,"as":"研究发现，生活在蚜虫细胞内的布赫纳氏菌会分泌一种名为SyeA的关键蛋白质，这种蛋白质对于细菌在宿主体内的定植至关重要。SyeA在结构上与致病菌分泌的蛋白质具有相似性，这表明布赫纳氏菌与蚜虫之间有益的共生关系最初起源于致病性。共生细菌正是通过分泌这种与病原体类似的蛋白质来成功定植于蚜虫宿主。","scd":null,"kp":[]},{"i":38495,"as":"合成信使RNA(mRNA)在癌症和传染病治疗中广泛应用，目前业界普遍使用N1-甲基假尿苷(m1Ψ)作为修饰核苷以降低免疫原性并促进翻译。然而，最新研究发现m1Ψ会损害翻译保真度，导致提前终止和核糖体移码等错误。研究揭示了N4-乙酰胞苷(ac4C)可作为m1Ψ的全新替代方案。在培养细胞系和原代人单核细胞实验中，ac4C不仅有效提升了合成mRNA的翻译产量，还显著增强了翻译过程的保真度。","scd":null,"kp":[]},{"i":38496,"as":"平流层水汽(SWV)作为一种关键的温室气体，对全球气候和臭氧化学具有重要影响。结合卫星观测和气候模型模拟，研究证实自2005年以来，中等强度的火山喷发和极端野火系统性地增加了平流层水汽含量（增幅约0.1）。火山喷发通过气溶胶诱导的对流层顶变暖增加水汽，而极端野火则在此基础上揭示了额外的自举效应途径，直接将水汽输送至平流层。","scd":null,"kp":[]},{"i":38497,"as":"利用詹姆斯·韦伯太空望远镜近红外光谱仪，研究在0.5至5.0微米波段对白矮星行星WD 1856 b的大气成分进行了透射光谱探测。观测数据明确证实了该行星大气中存在碳氢化合物（甲烷被确认为最优选模型）以及气溶胶。这一发现标志着首次在白矮星行星上探测到大气层特征，揭示了主序后恒星阶段行星的大气化学组成。","scd":null,"kp":[]},{"i":38498,"as":"针对气相沉积钙钛矿发光二极管因动力学驱动导致的结晶相混乱和器件效率受限问题，研究提出了一种热力学引导的X型准二维钙钛金属气相合成方法。通过引入卤素位点取代的有机间隔分子，使其在沉积过程中与Pb2+发生共价结合，成功实现了具有可控纳米级相分布和界面相干的准二维相的选择性结晶。该技术克服了相无序和纳米级异质性难题，为高效器件制造提供了规模化且与工业兼容的路径。","scd":null,"kp":[]},{"i":38499,"as":"阿马尔·卡斯里探讨了量子科学向量子技术转变的发展趋势。他警示了在这一转变过程中出现结构性鸿沟的风险，并强调当前必须立即采取行动，以确保量子技术的各项成果能够转化为实际应用，从而为全社会带来共享的繁荣。","scd":null,"kp":[]},{"i":38500,"as":"研究开发出一种无缝湿组织粘附生物电子器件。该器件通过将应变不敏感的弹性体电子器件与水凝胶粘合剂相结合，实现了与生物组织的无缝集成。这种无缝生物接口技术能够成功实现闭环治疗调制，为医疗干预和神经调控提供了新平台。","scd":null,"kp":[]},{"i":38501,"as":"研究深入分析了二维材料中的量子隧穿和漏电流物理现象，对比了不同厚度的六方氮化硼、二硫化钼、二硫化钨与工业级二氧化硅样本。结合纳米尺度与器件级实验分析，并辅以密度泛函理论和计算机辅助设计建模，研究证实表面褶皱等结构特征对超微缩电子器件和异质结的漏电流及器件可靠性具有关键影响，为理解二维材料的漏电流机制提供了准确量化模型。","scd":null,"kp":[]},{"i":38502,"as":"针对感音神经性耳聋，研究开发了一种能够与哺乳动物传入神经混合的神经形态接口以重建听觉通路。该系统采用自供电声学器件作为听觉感受器，结合利用WO3纳米线实现动态可逆质子插拔的突触单元，具备动态信息和宽范围序列声音处理能力。通过8×8突触晶体管阵列，该系统实现了三维声源定位和空间映射，利用侧抑制逻辑集中注意力，成功重建了人工听觉神经形态界面。","scd":null,"kp":[]},{"i":38503,"as":"针对呼吸道合胞病毒(RSV)，研究开发了一系列尺寸和维度可控的DNA纳米载体鼻内疫苗。通过精确控制几何特性以优化鼻腔内的滞留效率，并精确组织表面pre-F单体抗原图案以最大化激活B细胞。在动物实验中，优化后的DNA纳米载体疫苗成功在小鼠体内诱导了体液免疫，其免疫效果与临床批准的肌肉注射疫苗相当，填补了有效鼻内替代疫苗的空白。","scd":null,"kp":[]},{"i":38504,"as":"科学记者罗恩·胡珀深入探讨了生物共生现象以及生物体之间合作的重要性。他基于其著作《相聚》，详细阐述了自然界不同物种间的协同合作机制是如何塑造和构建当今世界的，强调了互助在生物演化与生态平衡中的核心作用。","scd":null,"kp":[]},{"i":38505,"as":"霍金辐射是黑洞视界发射量子粒子的现象，连接了引力、量子力学和热力学。由于天文观测的困难，这一现象仅在实验室模拟中被观察到。研究在光纤光学事件视界类似物中获得了理论与实验证据，揭示了产生霍金辐射的具体物理机制。研究纠正了此前认为霍金辐射来源于复杂级联过程的错误认知，从理论上成功识别出了一个简单的生成机制，证实了辐射能量直接来源于引力场或类似场。","scd":null,"kp":[]},{"i":38506,"as":"实现精准医疗的前提是基因组测序和分析具备极高的准确性。研究从基因组数据质量的角度分析了该领域面临的挑战和机遇，并在胚系测序、肿瘤测序、无细胞DNA检测以及基因治疗质量控制等具体应用领域提出了标准化建议。研究呼吁在具有相似技术挑战（如精确检测低频遗传变异）的各个独立标准社区之间加强同步与协作，以建立新的医学基因组标准，增强数据准确性与临床应用信心。","scd":null,"kp":[]},{"i":38507,"as":"为推进细胞生命的计算模拟，研究提出构建“虚拟酵母”系统。该系统以酿酒酵母为模型，利用多模态生物数据、机制推理和主动实验，构建出由大语言模型协调的八个特定领域AI工具组成的功能模块（涵盖遗传、代谢和结构系统）。该AI智能体建立在机制知识、亚细胞架构和动态状态三大数据支柱之上，通过闭环学习管道整合表征学习与生成建模，实现了对真核细胞行为的精准模拟。","scd":null,"kp":[]},{"i":38508,"as":"针对蓝色钙钛矿发光二极管因宽禁带导致高工作电压及八面体结构不稳定造成的性能瓶颈，研究通过引入同分异构分子构建分子内及界面氢键网络，成功实现了高效且稳定的饱和蓝光发射。在空穴传输层与钙钛矿发光层之间使用O-苄基羟胺盐酸盐(OBCl)作为氢键供体，使其与钙钛矿无机框架紧密结合，有效抑制了离子型钙钛矿在高电压下的八面体不稳定性，显著提升了器件性能。","scd":null,"kp":[]},{"i":38509,"as":"研究揭示了胞内共生细菌进入宿主细胞并抑制免疫反应的具体机制。在蚜虫的专性内共生菌布赫纳氏菌中发现了一种名为SyeA的关键分泌蛋白，该蛋白存在于布赫纳氏菌祖先中，可被分泌至宿主细胞质中。SyeA与细菌病原体的分泌效应物同源，对于布赫纳氏菌从特化母细胞排出并被胚胎摄取的过程至关重要，是细菌成功定植和向子代传播不可或缺的决定性因素。","scd":null,"kp":[]},{"i":38510,"as":"研究发现复制压力会诱导形成包裹停滞复制叉的瞬时染色质环。压力下的复制叉在趋同的CTCF基序处停滞，引发CTCF聚集以限制环挤出并稳定结构。这种稳定依赖于CTCF锚定和G9a依赖性异染色质在环内新合成DNA上的沉积。这些染色质环作为保护性支架，保护停滞和逆转的复制叉免受多种核酸酶的降解。","scd":null,"kp":[]},{"i":38511,"as":"研究利用免疫肽组学技术，在感染网织红细胞的疟原虫中鉴定出由HLA-I类分子呈递的疟原虫抗原衍生肽。针对恶性疟原虫和间日疟原虫这两种主要的人类疟疾寄生虫，研究共鉴定出453种独特的多肽，并映射到166个蛋白。这些发现为开发跨物种、跨阶段的靶向T细胞的疟疾疫苗提供了关键的抗原表位靶点。","scd":null,"kp":[]},{"i":38512,"as":"基于二维材料的晶体管因其超薄厚度和无缺陷表面，被视为1纳米以下逻辑技术节点的重要发展方向。研究提出了一种直接探测二维材料晶体管中载流子转移长度的方法。该技术能够确定接触缩放限制，物理沟道长度有望降至2纳米以下，为未来超大规模电子器件的开发提供了关键的设计信息与参数指导。","scd":null,"kp":[]},{"i":38513,"as":"研究利用纵向活体双光子钙成像技术，观察了R6/2亨廷顿病小鼠模型运动皮层中特定神经元亚型的活动。结果发现，小鼠的运动缺陷伴随着神经元亚型特异性的运动相关活动异常，特别是在皮层抑制性神经元和皮层纹状体投射神经元中。恢复皮层去抑制能够有效改善亨廷顿病的疾病表型，揭示了特定皮层神经元在病理机制中的作用。","scd":null,"kp":[]},{"i":38514,"as":"锡基卤化物钙钛矿因其可调带隙和优异的电荷传输特性成为极具潜力的无铅半导体，但其在欠配位Sn2+位点处的内在氧化还原不稳定性严重限制了其实际应用。研究提出了一种挥发性辅助配位策略，通过瞬态醋酸配位和挥发化重构钙钛矿表面，将高活性的SnI2终止表面转化为化学平衡且缺陷减少的界面。该方法有效抑制了陷阱态并稳定了局部化学计量比。","scd":null,"kp":[]},{"i":38515,"as":"研究通过对当今洋岛火山岩进行高精度钕（Nd）同位素测量，发现了可追溯至地球最早期历史的化学非均质性。在科摩罗群岛海底Fani Maoré火山的熔岩中，报告了显著的正142Nd异常。这一地球化学发现为理解地幔深部的复杂动力学过程、地幔柱的演化以及地球早期物质的起源和年代提供了关键的地球化学证据。","scd":null,"kp":[]},{"i":38516,"as":"结直肠癌肝转移瘤的组织病理学异质性显著影响患者预后。研究发现，伴有肝脂肪变性的未接受治疗的结直肠癌患者更易发生“替代型”肝转移。机制上，脂肪变性促进的脂肪酸氧化通过乙酰化作用增加MYC蛋白的稳定性，进而加剧了“替代型”肝转移瘤的形成。具有替代型转移瘤的患者5年总生存率不足44.2%，明显低于包裹型患者的73.4%。","scd":null,"kp":[]},{"i":38517,"as":"研究通过整合小鼠视觉皮层的单细胞RNA测序数据与长距离轴突投射形态，解决了将转录组身份与投射组联系起来的难题。研究收集了包含局部形态、电生理和转录组数据的1,528个兴奋性Patch-seq神经元数据集，以及341个全神经元形态数据。基于这些数据，研究成功定义了17种不同的细胞类型，为理解大脑神经元多样性提供了多维度视角。","scd":null,"kp":[]},{"i":38518,"as":"针对胶质母细胞瘤中抗原表达不均一及免疫抑制微环境的限制，研究利用多组学靶点发现平台鉴定出GPNMB作为一个双靶点。通过开发靶向GPNMB的CAR-T细胞疗法，能够同时识别并攻击肿瘤细胞以及微环境中主导免疫抑制的肿瘤相关巨噬细胞。这种将疾病视为肿瘤-免疫耦合系统的双重靶向策略，有效克服了单一靶向设计的局限性。","scd":null,"kp":[]},{"i":38519,"as":"细胞必须迅速抵消热应激引起的细胞膜过度流动化以防止损伤。研究表明，水稻中的P4-ATPase OsALA5及其β亚基OsALIS2介导了饱和磷脂酰胆碱的热响应翻转。热暴露会引发OsALA5转运活性在分钟级时间尺度上发生转变，导致饱和磷脂酰胆碱在细胞质膜小叶中选择性富集。这种翻转作用有效防止了热应激条件下的细胞膜过度流动化，从而稳定了膜的流动性。","scd":null,"kp":[]},{"i":38520,"as":"研究确定跨膜糖蛋白TROP2是预后不良结直肠癌的标志物，与WNTlow、胎儿样肿瘤细胞状态及转移和治疗抗性相关。TROP2阳性细胞表现出上下文依赖的干细胞样能力，能够启动转移性生长。时间分辨分析揭示了使用临床相关的TROP2导向抗体-药物偶联物进行靶向治疗时，肿瘤细胞状态表现出由治疗驱动的动态变化特征。","scd":null,"kp":[]},{"i":38521,"as":"该研究开发了一种氧化还原介导的水性流控系统，利用固体质子-电子载体（SPEC）生成用于直接空气捕集（DAC）的碱性溶液，同时保持SPEC与空气隔离。该设计有效克服了氧化还原活性物质对氧气的敏感性，实现了99.9%的库仑效率。其模块化架构为低能耗的电化学直接空气捕集技术提供了一条可扩展且可合理调控的新路径。","scd":null,"kp":[]},{"i":38522,"as":"研究聚焦中国五个最大的工业排放源，分析了重工业脱碳的时机对成本和碳锁定风险的影响。结果表明，加速清洁技术的发展而非等待，能触发更快的“干中学”效应，从而降低成本，最终节省约8%的累计系统成本。研究指出，2035至2040年间是一个关键窗口期，若延迟行动将导致高成本路径被锁定，对全球工业气候政策具有直接指导意义。","scd":null,"kp":[]},{"i":38523,"as":"黏附G蛋白偶联受体（GPCR）BAI3在控制轴突、树突生长及促进突触形成中发挥重要作用，且其G蛋白信号传导必不可少。实验表明，组成性暴露BAI3的系留激动剂可使其GPCR活性增加约5倍。然而，研究证实即使缺失GAIN结构域及暴露的系留激动剂，BAI3依然能够进行信号传导，说明其生理功能并不完全依赖于传统的系留激动剂机制。","scd":null,"kp":[]},{"i":38524,"as":"硼烯因具有本征金属性、最轻元素单层结构和高频声子等特性而备受关注，但制造困难和弱的电子关联性阻碍了新兴量子现象的实现。研究证实，在三元硼化物表面的蜂窝状硼晶格中衍生出了一种强关联的二维电子态。这一发现成功打破了原有s和p电子系统弱关联的限制，为在二维硼材料平台上研究各种量子现象提供了新途径。","scd":null,"kp":[]},{"i":38525,"as":"针对物联网设备对安全柔性电池的需求，研究开发了一种无毒的薄膜电池。该电池利用先进集水技术，收集环境中的水分作为电解质。其开路电压约为1.6伏，比容量约为52毫安时/克，比能量约为81毫瓦时/克。该电池模仿穿山甲皮肤的独特设计赋予了其极高的柔性和可拉伸性，兼具能量收集器的特点与传统电池稳定的高功率输出优势。","scd":null,"kp":[]},{"i":38526,"as":"研究通过将厘米级单层WS2和WSe2与偶氮苯分子覆层相结合，构建了一种大面积、光可编程的二维半导体平台。波长选择性的偶氮苯反式-顺式光致异构化，能够产生可逆的掺杂态切换。这一突破克服了以往微观单器件规模的限制，实现了原子级厚度沟道对分子构型变化的高度敏感性，为可重构电子器件和新型计算范式提供了技术途径。","scd":null,"kp":[]},{"i":38527,"as":"研究基于恶臭假单胞菌的短蓝光-氧-电压（LOV）蛋白设计了二聚体感光组氨酸激酶，并解析了其晶体结构。尽管在有无光照下，结构均呈现类似光状态的对称激酶模块，但小角X射线散射与功能实验揭示了在溶液中存在明显的光依赖性重排现象。研究成功界定了激酶激活状态下的二聚体不对称性，阐明了光遗传学中潜在的结构信号传导机制。","scd":null,"kp":[]},{"i":38528,"as":"通过暗能量光谱仪获取的约40万个星系光谱的叠加分析，研究在Mg II吸收线中发现了由恒星形成驱动的冷外流。计算表明，在仅受重力作用下，低质量星系（恒星质量小于10的10次方太阳质量）产生的气体外流能够逃离暗物质晕。这一观测证据证实了恒星反馈是驱动低质量星系重子物质缺失的关键物理过程。","scd":null,"kp":[]},{"i":38529,"as":"研究应用多变量机器学习技术，基于大规模数据集探究了全脑不对称性变异与认知、衰老及相关疾病的关联。研究揭示了大脑两半球之间显著且未知的结构差异，并建立了结构不对称与偏侧化功能之间的关键联系。在群体层面，识别出了半球差异的独特衰老轨迹，并在阿尔茨海默病和帕金森病患者中发现了具有诊断特异性的大脑不对称性变异。","scd":null,"kp":[]},{"i":38530,"as":"研究提出一种结合尿液表面增强拉曼散射（SERS）光谱与颈动脉B超的双模态分析方法。该方法利用机器学习技术，将患者全身微观分子指纹与局部宏观器官病理事件进行跨维度数据整合。通过此概念验证模型，能够有效克服单一模态检测的局限性，成功将确诊缺血性脑卒中患者与健康对照组进行区分，提升临床风险评估效能。","scd":null,"kp":[]},{"i":38531,"as":"研究利用果蝇腿部肌肉模型揭示了骨骼肌多样性的发育机制。原始中胚层前体细胞在上皮形态发生素的引导下经历逐步特化：Wg/Wnt1和Dpp/BMP首先将多能前体细胞限制为近端和远端谱系。在远端谱系中，连续的命运分支产生不同肌肉亚型及非肌肉神经薄层细胞。Wg和Dpp再次作用控制转录因子的时空部署，确保融合形成特定肌肉的成肌细胞群具有协调的转录状态。","scd":null,"kp":[]},{"i":38532,"as":"研究开发了名为“μBots”的生物集成微型机器人，配备了超宽带磁电天线（OUWB-ME）。该天线利用抛光硅基板中的高阶声学模式，在3至4GHz频段实现倍频能力，达到22.6GHz的-10dB带宽。异质结构采用银纳米颗粒墨水键合，在生物负载下保持稳定运行。体外实验证实了氮化铝的生物相容性，且聚对二甲苯封装有效保护了铁镓材料，离体大鼠和人体组织能够重塑其透射和反射光谱。","scd":null,"kp":[]},{"i":38533,"as":"研究分析了复发大肠杆菌菌血症患者的系列分离株，发现O-抗原合成的频繁破坏源于wbbL基因突变，导致脂多糖（LPS）呈现粗糙表型。粗糙LPS分离株的血清敏感性更高，在小鼠模型中的致病力降低。尽管表现出毒力衰减的迹象，但在队列的61个大肠杆菌序列型131血流感染分离株中，有18%（11株）携带破坏性的wbbL突变。","scd":null,"kp":[]},{"i":38534,"as":"研究利用新型超快光谱仪，对比了半导体碳纳米管薄膜与器件中的激子动力学。结果发现，传统的光吸收检测极大地高估了长寿命激子在光伏器件性能中的重要性。激子虽能跨越纳米管扩散数皮秒，但超快光电流检测表明，光电流主要由特定激子产生，激子扩散对碳纳米管器件效率的贡献微乎其微。这一结论推翻了以往基于光学检测得出的错误推论。","scd":null,"kp":[]},{"i":38535,"as":"研究提出了一种统一的配体维度设计策略，以解决钙钛矿太阳能电池中有机阳离子（尤其是FA+）迁移导致的长期稳定性问题。通过开发一系列吡啶基配体，在相同加工条件下构建了涵盖2D、1D、1D插层和0D金属卤化物结构的低维/三维（LD/3D）异质结。研究表明，2D/3D结构能够独特结合几何限制与多向氢键作用，有效固定并阻止FA+阳离子的迁移。","scd":null,"kp":[]},{"i":38536,"as":"地震学研究揭示了俯冲带地震规模与断层倾角之间简单但常被忽视的关联。全球地震统计表明，断层倾角与地震大小存在显著依赖关系，超大地震在超低角度断层上发生的概率最高。案例研究表明，当断层几何形态与区域应力场对齐时，地震规模趋于扩大。研究强调了监测俯冲带应力随时间演化对预测未来巨型地震的关键重要性。","scd":null,"kp":[]},{"i":38537,"as":"基于美国提顿山脉近60年（1967-2024）的数据，研究发现高山冰冻圈地形的响应存在显著差异。受夏季气温升高影响，2014至2022年间冰川和雪原变薄速率分别达-0.84和-0.59米/年，相比1967-2014年期间增加了约7倍。与之形成对比的是，石冰川几乎处于平衡状态（-0.05米/年），速率未发生变化。自2015年起，雪原补给的溪流水温正迅速上升。","scd":null,"kp":[]},{"i":38538,"as":"研究构建了一种由同种金属元素组成的Nb4CuC3/Nb4C3Tx高度耐用异质结构。该异质结具备固有晶格匹配和低界面电阻，在锂离子电池中表现出卓越的循环稳定性：在5.0 A/g的大电流密度下循环10,000次后，容量几乎无衰减。此外，研究利用同步辐射衍射反常精细结构技术，精确揭示了稳健异质结中与电化学活性位点相关的化学信息。","scd":null,"kp":[]},{"i":38539,"as":"研究评估了X平台的社区笔记在多样化极化环境中的运作机制。通过分析截至2025年3月的190万条审核记录及13个国家的数据，发现该算法能有效捕捉各国的主要极化维度，并呈现获得跨党派支持的笔记。然而，这种机制在系统设计上导致对高度极化内容的审核力度不足。在针对近期选举相关笔记的分析中，证实了该特征在选举过程中易引发特定风险。","scd":null,"kp":[]},{"i":38540,"as":"研究提出利用可移动脂质产生的机械运动来打破内体屏障的新概念，以提升mRNA疗法的效力。尽管优化脂质pKa、空间构旋及LNP成分已被广泛应用，但内体困限仍是限制疫苗效能的瓶颈。新型脂质纳米颗粒（LNPs）被设计为在特定输入信号下执行机械运动，通过物理方式破坏内体膜稳定性，从而实现高效的mRNA递送，突破了传统化学参数优化的收益递减问题。","scd":null,"kp":[]},{"i":38541,"as":"研究鉴定出内质网Mg2+ ATP酶（ERMA）是驱动Mg2+进入内质网腔的转运蛋白，确立了内质网作为双离子细胞内储存库的地位。靶向内质网的MagFRET生物传感器表明，ERMA介导动态的Mg2+储存，其依赖ATP的Mg2+摄取浓度可达到15至30毫摩尔。冷冻电镜结构分析揭示了人和小鼠ERMA的高分辨率结构及其功能机制。","scd":null,"kp":[]},{"i":38542,"as":"研究开发了一种针对免疫检查点B7-H4的放射性诊疗抗体。该抗体在实体瘤中广泛过度表达而在正常组织中极少表达。抗体分别标记[89Zr]用于PET成像，以及标记[177Lu]或[225Ac]用于β或α粒子靶向治疗。[89Zr]-免疫PET成像实现了对B7-H4表达的定量全身可视化，能准确区分高、中及阴性表达的肿瘤；而[177Lu]或[225Ac]标记的放射治疗在实体瘤模型中展现出强效的抗肿瘤能力。","scd":null,"kp":[]},{"i":38543,"as":"研究综合评估了东白令陆桥（约14000至13300年前）、北美洲克洛维斯（约13400至12800年前）和南美洲鱼尾投射尖器复合体（约12900至11600年前）的动物考古学记录。通过对这些美洲早期古印第安人遗址的分析，总结了其适应策略。研究证据揭示了早期古印第安人在整个半球范围内针对巨型草食动物的专业化狩猎特征，而非作为饮食泛化者。","scd":null,"kp":[]},{"i":38544,"as":"研究结合远缘同源检测、AlphaFold结构建模以及斑马鱼和秀丽隐杆线虫的功能遗传学，鉴定出后生动物中此前未知的Scm3/HJURP直系同源物。这些同源蛋白定位于着丝粒，其缺失会导致严重的有丝分裂失败。此外，研究证实，长期被视为功能类似物的果蝇CAL1蛋白，实际上是高度保守的Scm3/HJURP直系同源物，推翻了以往认为这些谱系中发生伴侣蛋白彻底替换的推论。","scd":null,"kp":[]},{"i":38545,"as":"研究发现水稻在遭受毁灭性害虫褐飞虱侵袭时，会释放一种特定的挥发性警报物质——水杨酸的二甲基化代谢物（DMSA）。DMSA的生物合成依赖于O-甲基转移酶级联反应（BSMT1-MSOMT），该过程由茉莉酮酸信号途径直接激活。与介导广谱植物与昆虫互作且无特异性的水杨酸甲酯不同，DMSA的发现表明植物能够合成特定的挥发性化合物来精准调控复杂的生态相互作用。","scd":null,"kp":[]},{"i":38546,"as":"研究在完全明确且经基因验证的系统中，通过单分子计数技术探究了SNARE蛋白如何实现同步神经递质释放。实验重构了快速释放过程（少于7毫秒），并在每个准备释放的囊泡中精确发现了12±0.3个SNAREpin复合物，表明其具有规则的结构。研究指出，包括基因点突变在内的多种遗传条件会减少囊泡上的SNAREpin数量，直接证明需要12个SNAREpins的协同才能实现囊泡的快速释放。","scd":null,"kp":[]},{"i":38547,"as":"针对倒置钙钛矿太阳能电池（PSCs）中镍离子诱发的界面氧化还原及隐藏缺陷导致的非辐射损耗问题，研究开发了一种界面锁定的双分子接触策略。通过共组装Me-4PACz和CzOTf分子，利用π-π稳定的共面堆积刚性化分子取向，增强界面电子耦合以实现高效空穴提取。同时，磺酸酯末端基团提供了更广的铅缺陷配位能力，有效缓解了界面应力，使器件光电转换效率达到27.3%。","scd":null,"kp":[]},{"i":38548,"as":"文章探讨了自主机器人辅助手术（RAS）的最新进展，并展望了向微型机器人辅助手术（μ-RAS）缩放微化的趋势。这种微型化技术有望实现微创、部分或完全自动化的手术程序，从而缩短患者恢复时间、降低医疗成本并解锁全新的手术方案。文章分析了RAS在血管内、腔内、腹腔镜、眼科和骨科五个外科领域的临床需求与关键技术突破，并明确指出了推动这些领域进展所需的核心创新。","scd":null,"kp":[]},{"i":38549,"as":"衰老与协调能量产生、生物合成及分子周转的代谢途径重编程紧密相关。代谢成像技术能够在分子、细胞及生物体水平上实现空间分辨的代谢动态可视化。本综述总结了代谢成像在探索衰老生物学领域的最新进展与应用，重点强调了多模态非线性光学成像技术及其在不同衰老模型中的实际应用。光学代谢成像通过捕捉代谢动态，为深入理解衰老机制提供了独特的见解。","scd":null,"kp":[]},{"i":38550,"as":"昆虫腿部肌肉发育研究表明，腿部通过多样化的肌肉完成运动。在肌肉形成之前，环境因素会指导并决定细胞的多样性。这一发现揭示了环境信号在肌肉细胞身份确立过程中的关键指导作用。","scd":null,"kp":[]},{"i":38551,"as":"研究开发了一种基于四磷酸化酞菁的自组装单分子层（SAM）来稳定钙钛矿太阳能电池。该单分子层具有坚固的框架和稳定的化学键，显著提高了光电稳定性；四磷酸化使酞菁牢固锁定在界面处，改善了热稳定性、电荷提取和组装均匀性。该技术使钙钛矿太阳能组件（20.3平方厘米）获得了23.1%的认证效率，并通过了ISOS-O-1标准的户外稳定性测试。","scd":null,"kp":[]},{"i":38552,"as":"为修复超长周围神经缺损，研究人员开发了一种全合成的神经导管。该导管采用分级微拓扑工程和特定的分子递送，通过同步结构线索与修复级联反应创造促再生微环境。其受神经解剖学启发的核心模拟了神经内膜和神经束膜，为轴突排列提供接触引导；双层鞘结构确保了机械完整性和代谢渗透性。","scd":null,"kp":[]},{"i":38553,"as":"研究提出在低温下制备锆酸铅（PbZrO3）薄膜的策略，通过在反铁电材料中引入稳定的亚铁电相，在大电场下实现了三重磁滞回线。这种结合了铁电体单磁滞回线与反铁电体双磁滞回线的多重磁滞回线材料，解决了稳定连接铁电非易失性与反铁电场诱导相变中间态的挑战，将极大推进储能、电卡冷却和非易失性多态存储技术的发展。","scd":null,"kp":[]},{"i":38554,"as":"新进化的长链非编码RNA（lncRNA）主要源于灵长类动物，其致癌作用通过逐步过程产生。当转录活性增加并超过阈值后，这些lncRNA会发生序列扩张，其中73.3%整合了外部或局部基因组片段，从而融入高度保守的癌症相关通路中。研究以MIR497HG验证了这一进化模型。","scd":null,"kp":[]},{"i":38555,"as":"在析氧反应（OER）中，基于离聚物电极的气泡动态变化十分复杂。气泡生长时，三相接触线表现出钉扎-脱钉行为。当气泡超过临界尺寸（约420微米）时，离聚物中的自由水分子进入气泡与电极的接触区，形成不断演变的微液滴（小于20微米）和纳米气泡。这一发现打破了附着气泡仅作为活性位点阻碍的传统观念。","scd":null,"kp":[]},{"i":38556,"as":"研究测试了独立及联合使用珊瑚选择性育种和共生藻（虫黄藻）实验进化来生成耐热珊瑚种群。在32°C环境下，使用快速测定法进行的 selective breeding 提高了Davies珊瑚幼体的存活率和生长速度，但未改善摩尔礁珊瑚幼体的表现。此外，用耐热共生藻接种珊瑚后代也是干预手段之一。研究证明了辅助进化能增强珊瑚的耐热性，但效果复杂。","scd":null,"kp":[]},{"i":38557,"as":"研究构建了泛基因组范围的基因-蛋白质-反应关联，并将其应用于2377个大肠杆菌基因组，重建了泛基因组尺度代谢模型（panGEM）。该模型在生长预测中达到了约0.99的精确度。研究发现了超过11000个稀有代谢基因，但仅有35个稀有代谢反应，发现大多数稀有基因是通过水平基因转移获得的假基因或趋异直系同源物。","scd":null,"kp":[]},{"i":38558,"as":"对绿僵菌的早期和新近分化品系进行的比较分析揭示了不同的生活史策略。早期菌株表现出有限的植物根系关联、较慢的杀虫速度和高产孢量；而新近分化菌株则显示出在昆虫角质层和植物根系上快速发芽、加速杀死宿主的能力，且多数具有破坏素活性。对95种底物的碳利用分析表明，代谢广度的扩大是该真菌致病性与植物关联之间强有力的预测指标。","scd":null,"kp":[]},{"i":38559,"as":"保持飞机、自主机器人到生物系统等反馈系统的稳定性依赖于行为监控和输入调整。渐进式损伤会使控制变得脆弱，传统的工程方法依赖准确的系统模型，在受损系统偏离模型时往往会失效。研究表明，反馈系统接近不稳定状态时可以通过动力学的弹性指标进行监控。这种全局系统安全监控器不依赖系统模型，能监测增量损坏引发的不稳定。","scd":null,"kp":[]},{"i":38560,"as":"为促进各类溶酶体贮积症（LSD）的分子表型分析，研究开发了一个缺乏23个LSD基因之一的人类胚胎干细胞文库工具包。这些基因与鞘脂沉积症和神经元蜡样脂褐质沉积症相关。利用该工具包，研究人员成功生成了皮层样和中脑多巴胺能样诱导神经元的蛋白质组学资源，并进行了深入的丰度与相关性分析。","scd":null,"kp":[]},{"i":38561,"as":"研究以重晶石（BaSO4）为模型，实验测量了晶体成核过程中的同位素分馏。通过在有机膜上沉淀晶体，利用阳离子富集创造高度过饱和的微环境，使成核主导晶体生长。实验在单批次中分离出纳米晶体（约1.5纳米）和微米晶体，成功分离并测量了成核效应。这对现有的同位素分馏理论进行了补充，并为生物结晶研究提供了重要意义。","scd":null,"kp":[]},{"i":38562,"as":"一种能分化出专门固氮细胞（异形胞）的丝状蓝细菌中，细胞分化与图灵样图案紧密相关。通过系统遗传学分析和转录系统重建，研究确立HetZ是异形胞分化基因调控网络的核心激活子。生化和冷冻电镜分析证实HetZ是一种σ因子（σ-HetZ），其独特的结构域插入对细胞分化特化和图灵样图案形成至关重要。","scd":null,"kp":[]},{"i":38563,"as":"研究利用贝叶斯分子钟分析和系统发育调和，确定了钴胺素生物合成基因和生产者的出现时间框架。结果显示，四吡咯前体和咕啉环的部分生产者早于最古老的钴胺素生产者，表明钴胺素样化合物在从头生产者出现之前就已经存在。该研究填补了这一广泛存在的共同辅因子起源的进化信息空白。","scd":null,"kp":[]},{"i":38564,"as":"类鼻疽伯克霍尔德菌的双功能血红素过氧化物酶（BpKatG）利用血红素和三个色氨酸作为氧化还原辅因子。研究利用连接的硝基氧化物自旋探针，探明了Trp153与高价血红素中间体之间的长程多步电子隧穿路径，证实其由Trp94和Trp95介导。研究还展示了高价铁中间体与色氨酸自由基之间反应平衡的非微扰监测。","scd":null,"kp":[]},{"i":38565,"as":"对湍流环流波动的最新研究揭示了湍流间歇性的几何特征。研究发现，环流概率分布函数允许超统计表示，即基于玻尔兹曼-吉布斯系综的描述。该方法的基本要素在于耗散场与携带环流的小尺度涡旋空间分布之间的强相关性。在超统计语言中，这对应于对环流的特定特征描述。","scd":null,"kp":[]},{"i":38566,"as":"蚂蚁是除人类之外少数会进行社会性伤口护理的动物。通过结合受控损伤实验与自动化行为跟踪，研究发现提供护理的蚂蚁是处于护理和觅食角色之间过渡状态的工蚁，它们具有活跃度高和网络连接广泛的特点。社会和空间亲和力是驱动蚂蚁进行伤口护理的关键因素。","scd":null,"kp":[]},{"i":38567,"as":"皮埃尔·尚邦是法国分子生物学先驱和真核生物基因调控领域的远见卓识者，于2026年5月5日逝世，享年95岁。他在基因表达和激素调控基本机制方面做出了重大贡献，开发了开创性的小鼠遗传学技术，并将斯特拉斯堡打造为欧洲领先的生命科学研究中心。他的精神遗产将继续影响全球的研究人员。","scd":null,"kp":[]},{"i":38568,"as":"尽管斑马蝴蝶在加勒比海和美洲分布广泛且形态和基因高度同质，但基因组分析揭示了三个地理受限的染色体倒位。这些古老的倒位多态性在最近的范围扩张中幸存下来，解释了基因组其余部分的同质性。这些倒位携带局部适应性等位基因，证明了不同范围内的分歧选择在没有形态差异的情况下仍能产生局部适应。","scd":null,"kp":[]},{"i":38569,"as":"研究展示了一种免扫描的方法来表征时频域中的高维纠缠态。该方法成功重建了记录的5.70±0.07 ebits纠缠熵，与1021维度的最大纠缠态保真度达65.4%，直接认证了668维的纠缠态。这项技术克服了全态层析成像成本高昂且难以实现的挑战，释放了高维光子纠缠在增强噪声弹性和信息容量的大字母量子通信协议中的潜力。","scd":null,"kp":[]},{"i":38570,"as":"研究揭示了普通壁虎具有紫外线反射颜色形态的分子基础。该特征与转录因子PAX7上游的非编码区变异有关。该位点的变异通过改变细胞组成来改变真皮结构，从而暴露出产生紫外线结构色的细胞内部结构。此外，PAX7位点对其他颜色基因具有上位效应，能够抑制色素沉积。","scd":null,"kp":[]},{"i":38571,"as":"血红素-铜氧化酶利用氧气还原为水的能量跨膜泵送质子以合成ATP。研究利用位点选择性光谱法，克服了其他氧化还原中心的光谱重叠干扰，探测了该酶活性位点中铜及其交联的酪氨酸残基。研究阐明了这种电子离域的铜-酪氨酸状态在质子泵送机制中的直接作用。","scd":null,"kp":[]},{"i":38572,"as":"研究报道了角豆胶(LBG)水凝胶在高压处理下发生反常软化而非硬化的现象。在高达1.2 GPa的反复压缩-解压循环下，LBG水凝胶的弹性模量(G′)逐渐降至初始值的31%左右。相反，反复的冻融循环则能使其模量提升约2.3倍。扫描电镜揭示了这种反常软化背后的结构转变特征。","scd":null,"kp":[]},{"i":38573,"as":"普鲁士蓝不仅是经典颜料，还因其电致变色和储能特性在现代科技中具重要价值。研究利用超快二维红外光谱技术，测量了沉积在电极上的普鲁士蓝薄膜内部的电子转移速率。随着材料从普鲁士白逐渐氧化为普鲁士蓝，研究利用CN伸缩振动模式作为探针，揭示了局部铁氧化态和溶剂化动力学变化。","scd":null,"kp":[]},{"i":38574,"as":"鸟类适应飞行的骨骼形态演变中，从长骨尾向短小尾综骨的转变一直是进化谜题。研究人员在中国东南部上侏罗统发现了一种新的早期鸟类化石——郑氏鸟。该化石表明，在早期鸟类演化中，脊椎骨的减少和缩短发生在尾综骨融合之前。这一发现为鸟类尾部的阶段性演化提供了关键证据。","scd":null,"kp":[]},{"i":38575,"as":"全球地貌演变主要由沉积物侵蚀、搬运和沉积塑造。研究发现，地球上约75%的陆地面积由以扩散性土壤蠕动为主的土壤覆盖斜坡和平原组成，约0.5%为基岩河道走廊。尽管冰川、湖泊、风成沙漠等其他地貌过程区域仅占陆地面积的约24%，但它们承担了大部分从大陆向海洋输送的沉积物。","scd":null,"kp":[]},{"i":38576,"as":"GBA1基因突变会耗尽溶酶体中GCase酶的活性，导致底物积累，是引起戈谢病和帕金森病的重要风险因素。通过开展全基因组筛选，研究人员发现磷脂酶Cγ2（PLCG2）能够限制溶酶体中GCase的活性。这一发现为通过提升溶酶体GCase活性来改善底物积累及相关神经毒性提供了重要靶点。","scd":null,"kp":[]},{"i":38577,"as":"研究发现强烈的压力会使果蝇产生持久的幽闭恐惧症样行为（CLB），该行为的形成不依赖于多巴胺受体。神经筛选表明，神经肽Allatostatin-A通过其受体AstA-R1使下游神经元失活，从而直接诱导CLB。此外，基因表达分析揭示，果蝇头部的血脑屏障中发生了先天性免疫反应的激活。","scd":null,"kp":[]},{"i":38578,"as":"黄体形成初期的血管生成滞后于孕酮的快速升高，形成无血管期。研究揭示了一种名为“颗粒细胞能量存储（GCES）”的细胞适应机制。在黄体化开始时，颗粒细胞进入代谢静止状态，但通过增强葡萄糖摄取并将其转化为糖原储存。随后，这些糖原储备的分解为无血管期的黄体细胞提供了类固醇生成所需的能量。","scd":null,"kp":[]},{"i":38579,"as":"","scd":null,"kp":[]},{"i":38580,"as":"研究发现小麦中的TaSnRK1α1激酶在赋予耐热性和增加粒重方面发挥关键调节作用。转录因子TaMYB55直接结合TaSnRK1α1启动子并激活其表达，从而正向提高小麦的耐热性。TaSnRK1α1启动子上的A到G碱基替换增强了TaMYB55的结合亲和力，且该变异与小麦耐热表型共分离。此外，TaSnRK1α1会与下游蛋白互作并发生磷酸化。","scd":null,"kp":[]},{"i":38581,"as":"在逆转录病毒（如HIV-1）感染早期，宿主组蛋白H1被沉积到未整合的病毒DNA上，导致其转录沉默。这种沉默伴随着高水平的H3K9三甲基化和低水平的H3乙酰化。研究证实，组蛋白H1与染色质压缩及翻译后修饰密切相关，核心组蛋白和H1的同时缺失或敲除会直接影响未整合病毒DNA的命运。","scd":null,"kp":[]},{"i":38582,"as":"BsYetJ是一种细菌跨膜蛋白，其Ca²⁺渗透机制由局部静电转化控制。结合平面双层电生理、纳米盘双电子-电子共振光谱及原子建模等技术，研究解析了其跨膜和活细胞中的电化学门控机制。研究发现，该门控机制受控于两个具有不同物理作用的双盐桥结构，共同调节质子门控和钙离子泄漏。","scd":null,"kp":[]},{"i":38583,"as":"透明细胞肾细胞癌的发生与VHL基因缺失及HIF2α的激活密切相关。研究发现，TRAIL在ccRCC细胞中受VHL-HIF2α轴调控而上调，并表现出特异性合成致死效应。TRAIL通过激活p38 MAPK通路和促进G1/S期转换来促进癌细胞增殖。消耗或抑制TRAIL可有效控制VHL缺陷型ccRCC的发展。","scd":null,"kp":[]},{"i":38584,"as":"研究构建了包含881种条件的大肠杆菌转录组库，包含在43种特定碳源上生长的346个RNA测序数据。通过独立成分分析，定量测定了137个独立基因表达模块的活性。研究鉴定出25个碳代谢模块，并将这些模块在43种底物上的活性模式总结为四个底物组。这些活性模式与测量的细菌生长速率直接相关。","scd":null,"kp":[]},{"i":38585,"as":"EARLY BOLTING IN SHORT DAYS (EBS)是一种能识别H3K27me3和H3K4me3的双价染色质读取蛋白，通过改变结合偏好控制开花转变。研究表明，氮营养和TOR信号通路通过直接互作来调节EBS蛋白丰度。TOR激酶在S195和S196残基位点磷酸化EBS，促进其稳定性，从而抑制下游转录，调节植物在缺氮条件下的营养向生殖生长转换。","scd":null,"kp":[]},{"i":38586,"as":"生物分子通过相分离在细胞表面形成凝聚体，用于信息处理和决策。研究展示了多组分流体可被设计用于招募不同组成的凝聚体至表面，执行基于凝聚的表面分类。类似于机器学习中的多维分类，研究探索了隐藏节点（隐藏物种）如何扩展这些相互作用集合的表达能力和容量，从而在拥挤环境中促进复杂的组合决策。","scd":null,"kp":[]},{"i":38587,"as":"研究采用有效场论方法，并结合量子蒙特卡洛计算得到的核矩阵元，计算了¹⁰C超允许β衰变的辐射校正（δ_NS）。这些辐射校正参数是提取卡比博-小林-益川（CKM）夸克混合矩阵元的关键物理输入量。该成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":38588,"as":"研究利用充气反冲分离器SHANS2，通过熔合蒸发反应¹⁶⁹Tm(⁵⁴Cr, 3-4n)重新研究了缺中子镎同位素²¹⁹Np和²²⁰Np。实验重点分析了这两种放射性同位素的α衰变特性，该结果对于理解超铀元素区原子核的衰变性质和核结构演变具有重要意义。成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":38589,"as":"研究聚焦于天体物理γ过程中与⁸⁵Rb相关的核反应，该反应流由(γ,n)和(γ,p)两个通道的竞争决定。在前期对⁸⁴Kr测量以约束(γ,p)通道的基础上，本研究进一步测量和约束了⁸⁵Rb的分支点。这些数据有助于精确理解恒星内部重核的光致裂变合成路径。成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":38590,"as":"研究提出了一种完全高斯且实验可行的方案，用于同时估算双通道光学网络中的四个实参数。该方案利用双模压缩探针和两个输出端口的平衡零差检测技术，实现了海森堡标度极限下的高精度量子测量。研究推导出了该参数估计方案的完整理论框架。成果发表于《Physical Review Letters》。","scd":null,"kp":[]},{"i":38591,"as":"研究人员使用双振荡器红外自由电子激光的两色操作，成功控制并表征了超流氦纳米液滴内离子的同分异构体布居数。两束激光的时间实现高度同步，且频率可以独立调节。该技术为分子结构的精准操控提供了新手段。","scd":null,"kp":[]},{"i":38592,"as":"结合远红外振动光谱技术与计算模拟，科研人员能够更精确地测定小尺寸铁阳离子团簇的几何结构和自旋磁矩。该技术解决了关于小型阳离子铁团簇自旋状态的长期争议，为团簇物理研究提供了精确的分析工具。","scd":null,"kp":[]},{"i":38593,"as":"提出利用光镊技术对微观里德堡原子的电子轨道进行局域操纵和时空雕刻。结合激光冷却、原子捕获与里德堡激发技术，该方法能够诱导长程相互作用，实现对里德堡电子运动的精确时空控制，推进了量子科学的发展。","scd":null,"kp":[]},{"i":38594,"as":"在变形密度泛函理论和自洽Hartree-Fock-Bogoliubov计算框架下，研究了质子数在82到126之间的超重核的α衰变性质。研究采用了SkM*和SLy4 Skyrme相互作用参数，致力于开发一种专用于超重核α衰变研究的Skyrme相互作用模型。","scd":null,"kp":[]},{"i":38595,"as":"通过在双层光子晶体中设计各向同性带间耦合，构建了拓扑保护的连续环状单向导引共振。该结构能够将涡旋激光发射锁定在单一方向，在光子器件方向控制和激光发射研究领域具有重要意义。","scd":null,"kp":[]},{"i":38596,"as":"针对自洽多电子理论中迭代多体方案出现的误导性收敛问题，研究将其与Luttinger-Ward泛函的分叉问题进行形式上的解耦。该方法提供了一个严谨、不依赖模型的程序，确保多体计算能够准确收敛到物理解。","scd":null,"kp":[]},{"i":38597,"as":"开发了一种物理一致的计算方法，通过约束从头算分子动力学轨迹，计算出有限温度下离子与电子耦合转移的自由能表面。该形式化理论提供了一条基于第一性原理的途径，用于确定电化学反应中的电流-过电位关系。","scd":null,"kp":[]},{"i":38598,"as":"通过比较理论计算与实验测得的质子和反质子横向动量谱及产额比，限制了介质内质量修改的范围。基于受限范围和具有径向流的高斯源模型，对布鲁克海文国家实验室相对论重离子对撞机能量下的挤压谱和背对背关联进行了分析。","scd":null,"kp":[]},{"i":38599,"as":"结合原位偏压加热透射电子显微镜与第一性原理计算，对钛酸钡晶体在临界点附近的结构无序进行了直接观察。该研究揭示了铁电体中与巨型介电和机电响应相关的结构起源，特别是在非弛豫系统中的物理机制。","scd":null,"kp":[]},{"i":38600,"as":"电解合成技术能够利用丰富的小分子（如水、二氧化碳、氮气等）形成碳-杂原子（氮、硫、磷）键，为清洁化学技术提供了平台。然而，在传统的静态电解下，碳-杂原子偶联反应面临产品范围狭窄（主要以尿素为主）和电流效率适中等局限性。","scd":null,"kp":[]},{"i":38601,"as":"","scd":null,"kp":[]},{"i":38602,"as":"介绍了一种由双(亚氨基)苝支撑的氮杂环卡宾衍生的有机氧化还原体系。该系统表现出两个可逆且分离良好的氧化还原过程，不同氧化态可被分离并通过X射线衍射进行表征。其自由基阳离子在可见光区域具有强吸收，在连续可见光光催化等领域具有应用潜力。","scd":null,"kp":[]},{"i":38603,"as":"提出了一种基于大面积触觉物理耦合的连续人机交互范式，用于行走辅助。通过在人腰部和腋下等机械敏感区域建立安全的触觉交互，机器人可以直接参与调节人机耦合动力学，从而有效提升步行支撑过程中的运动稳定性和意图对齐。","scd":null,"kp":[]},{"i":38604,"as":"最新证据表明，公众对科学的信任度依然保持在高水平。此外，维拉·鲁宾天文台正在进行史上最广泛的巡天观测，同时向同行评审专家支付报酬的机制有助于加快科学论文的评审过程。","scd":null,"kp":[]},{"i":38605,"as":"英国癌症研究中心向曼彻斯特研究所投资600万英镑，旨在使其成为新兴肿瘤治疗领域的全球领导者。这项投资将专注于在曼彻斯特建立世界级的肿瘤学研究与治疗中心，推动新兴抗癌疗法的发展。","scd":null,"kp":[]},{"i":38606,"as":"通过季铵盐调节聚合物网络，开发出一种抗冲击水凝胶。该方法无需复杂的后处理或高能耗，能够控制含有极性基团的聚合物的结构组织，将大块且密集堆积的刚性域转化为动态结构，从而克服了传统水凝胶机械性能不足和环境不稳定的缺陷。","scd":null,"kp":[]},{"i":38607,"as":"进行了一项高精度实验，寻找碳-12中预测位于7.458 MeV激发能处的Efimov态。利用先进的探测器系统和新型分析技术，研究人员成功在3α阈值以上的预测能级处分离出潜在的Efimov态事件。","scd":null,"kp":[]},{"i":38608,"as":"报道了在含有稀土元素的半哈斯勒化合物中，通过亚晶格软化实现极低本征晶格热导率和优异热电性能的机制。与传统的非稀土半哈斯勒不同，基于稀土的晶格框架在4c亚晶格内引发了剧烈的原子振动，增强了晶格非谐性和声子阻尼，有效抑制了热传导。","scd":null,"kp":[]},{"i":38609,"as":"固态锂电池因其固态电解质能够防止泄漏、提高热稳定性，并支持使用高电压正极和锂金属负极，成为储能系统的理想选择。文章从以界面为中心的视角探讨了结合高镍层状氧化物正极材料的实用化固态锂电池的发展策略与挑战。","scd":null,"kp":[]},{"i":38610,"as":"提出了一种平面度-位阻共平衡策略，开发了具有极小吸收蓝移的反平行堆积H-聚集体，用于I型光动力疗法。通过π桥平面化驱动H-型堆积，以及供体位点空间位阻调节滑移，克服了传统H-聚集体需要短波长激光激发、组织穿透性差的问题。","scd":null,"kp":[]},{"i":38611,"as":"通过将4-氨基苯甲酸盐酸盐与二苯并-18-冠醚-6结合，在倒置钙钛矿太阳能电池的电子传输层界面构建了共组装混合中间层。该结构提高了单层覆盖率和界面偶极矩，通过双重钝化效应（利用─NH3+和─COOH基团中和离子缺陷）显著增强了上界面的稳定性。","scd":null,"kp":[]},{"i":38612,"as":"研究人员开发出一种醇溶蛋白-氧化铈（Zein-Ceria）混合微粒，用于工程化骨微组织的再生。该微粒能够持续进行长达40天以上的活性氧中和与供氧，并提供骨诱导因子。其核心设计利用疏水性醇溶蛋白核心稳定氧气来源并抑制初期氧气的爆发性释放，结合氧化铈纳米酶解决传统生物材料释放氧气时伴随的高水平氧化应激问题。","scd":null,"kp":[]},{"i":38613,"as":"本文为无阳极电池的中间层设计建立了一套设计过滤指南。分析指出，中间层的可行性取决于表面形貌、化学特性和沉积物理学的交叉条件：涂层必须在实际电池基底上保持连续，同时兼容有限的阴极金属储量。低吸收率的合金中间层在中等厚度下依然能保持储量效率，而转化型氧化物和氮化物通常需要采用超薄设计，除非其具备高回收效率或发生部分转化。","scd":null,"kp":[]},{"i":38614,"as":"本文介绍了在DIII-D托卡马克装置上部署的PACMAN（基于机器学习的预测与控制）通用算法的设计与应用。该架构实现了从诊断数据处理到最终执行指令的端到端部署。利用该机器学习算法，DIII-D成功实现了无撕裂模式（TM）、无边缘局域模（ELM）等传统控制器难以实现的场景控制，包括强化学习协同控制实验，展示了先进等离子体控制技术的应用潜力。","scd":null,"kp":[]},{"i":38615,"as":"研究利用皮秒激光诱导击穿光谱（ps-LIBS）技术，在约10^-7毫巴的高真空条件下，对Wendelstein 7-X（W7-X）仿星器偏滤器石墨瓦表面的材料成分进行了非原位定量分析。成功获取了碳、硼、氢、氧元素的极向二维分布图和深度剖面。这些空间分布数据对于解析等离子体与壁面相互作用（PWI）驱动的杂质源、评估器壁处理性能以及约束杂质迁移模型具有重要的关键作用。","scd":null,"kp":[]},{"i":38616,"as":"在2023至2025年间，WEST装置实现了超过1000秒（最高记录1337秒）的稳态长脉冲放电。该装置配备了全主动冷却的ITER级偏滤器，承受了高达12 MW/m²的热通量和超过10^27 D/m²的粒子注量。实验观察到单块顶部表面裂纹，但目前未影响偏滤器功率排散能力。此外，偏滤器高场侧沉积层易剥落引发等离子体杂质问题，研究提出了激光清洗技术予以解决。","scd":null,"kp":[]},{"i":38617,"as":"通过密集阵列远震层析成像、三维波形模拟以及地震波速度与地幔过渡带厚度的联合反演，研究者在东北亚地幔过渡带绘制出一个长约1000公里的连续弧形板片空窗（slab gap）。精细几何与热结构分析显示，该空窗温度接近正常上地幔值，比地幔柱温度低200°C以上，无异常热证据。其边界特征符合停滞板片内的机械张开，走向与三联交界迁移路径一致。","scd":null,"kp":[]},{"i":38618,"as":"研究团队开发了温度介导引物交换反应（TEMPER）平台，实现了一锅法、可编程的聚合酶介导DNA合成。该技术无需进行溶液交换，仅通过温度控制即可完成任意DNA序列的合成。其核心机制是利用发夹DNA作为温度响应性构建模块，通过设计发夹长度来设定特定的温度响应范围。这种基于热力学相互作用的机制，允许在同一反应体系中选择性且顺序性地合成DNA。","scd":null,"kp":[]},{"i":38619,"as":"研究结合碳-13固态核磁共振（ssNMR）、多变量统计分析和分子建模，对13种在富碳-13大气中生长的毛果杨基因型的次生细胞壁进行了纳米尺度表征。结果揭示了不同基因型间高度保守的大分子架构，组成、结构和聚合物邻近度的微小变化被组织成主要结构轴和次要迁移率轴。原子级模型与分子动力学模拟进一步表明，这种保守的细胞壁架构由一种弱但协调的相互作用网络支撑。","scd":null,"kp":[]},{"i":38620,"as":"在全球变暖背景下，极超快寒潮事件（温度在数小时内骤降并冻结能源基础设施）的命运呈现地域分化：在欧亚大陆逐渐减弱，而在北美地区显著加剧。这种差异由特定的大气环流机制驱动，特别是北美地区阿拉斯加-北极反气旋的频率增加。2021年造成超200亿美元损失的北美寒潮即是典型案例，打破了变暖必然导致冬季变暖和极端寒冷减少的普遍假设。","scd":null,"kp":[]},{"i":38621,"as":"研究发现一类与CRISPR相关的Schlafen蛋白（Cash）在原核生物免疫中的机制。Cash蛋白包含Schlafen结构域和Csx15传感器，其在III型CRISPR干扰期间被产生的环四腺苷酸（cA₄）激活。冷冻电镜结构表明，Cash在结合cA₄前为无活性十二聚体，结合后形成细丝以排列催化界面。激活的Cash通过切割tRNA（主要在T环）诱发细胞毒性，从而抵御噬菌体感染。","scd":null,"kp":[]},{"i":38622,"as":"研究首次提供了涵盖过去12000年的中国贵州地区古人类基因组数据，包括5名距今超过10000年的个体。结合广西和云南的已发表样本，揭示了从旧石器时代到新石器早期东亚西南部人群复杂的遗传史。旧石器时代人群表现出基底东亚兴义_EN血统与北方血统的异质混合分布模式，为了解东亚南方、东南亚与青藏高原交汇处早期人类迁移历史提供了重要基因组学证据。","scd":null,"kp":[]},{"i":38623,"as":"研究者开发了一种无电池、柔性的水凝胶生物电子贴片，用于牙周炎症的无线监测与局部微RNA（miRNA）免疫调节。该水凝胶由结合生物活性多肽的明胶合成，多肽序列可被基质金属蛋白酶特异性裂解。当感知到牙周病相关的蛋白酶活性时，水凝胶的酶促降解信号被无线转化为定量读数，实现了早期诊断；同时释放miRNA进行免疫干预，解决了电子器件与口腔组织间生物学不匹配的难题。","scd":null,"kp":[]},{"i":38624,"as":"","scd":null,"kp":[]},{"i":38625,"as":"研究以马里亚纳海沟为典型案例，利用三维数值模型揭示了地幔环形流动对大洋内海沟弯曲及热化学传输的调制作用。模型表明，当俯冲板块沿走向具有急剧的密度变化并伴随大型浮力块体（如加罗林板块）时，会引发海沟的剧烈后退与弯曲。此过程在地幔楔中产生显著的动态压力波动，在非线性地幔流变下形成延伸超1000公里的强烈环形流，进而驱动深部热化学物质的沿走向迁移。","scd":null,"kp":[]},{"i":38626,"as":"研究对长翅型和短翅型两种半翅目昆虫的翅芽进行了单细胞RNA测序，鉴定出六种保守细胞类型。通过RNA干扰沉默51个标记基因，发现翅型模式基因En（上皮样细胞）和bs（气管细胞），以及细胞周期基因Anln、CycB3和cdk1（神经元细胞）对长翅发育至关重要，其中En具有特定的时间需求。流式细胞术证实，长翅型的形成主要依赖于发育过程中细胞周期的显著延长。","scd":null,"kp":[]},{"i":38627,"as":"2021年美国《两党基础设施法案》（BIL）为安全饮用水项目拨款307亿美元，创历史新高，并规定49%的资金须以拨款或可免除贷款形式提供给“弱势社区”。各州对弱势社区的定义拥有自主权。研究分析了2019至2023年各州对弱势社区定义的重塑及空间分布。结果显示，尽管各州广泛更新了定义标准，但在饮用水资金分配上，种族和民族之间的系统性差异依然存在。","scd":null,"kp":[]},{"i":38628,"as":"研究发现L型绿脓杆菌素能够通过抑制细菌表面的β-桶组装机器（BAM）复合体来杀灭革兰氏阴性病原体铜绿假单胞菌。单颗粒冷冻电镜结构显示，L型绿脓杆菌素结合BamA的表面暴露区域，并通过其C端多肽竞争性抑制BAM复合体，从而阻断外膜蛋白组装。这一机制证实，L型绿脓杆菌素及类似环肽抗生素的杀菌作用无需进入细胞内部，克服了外膜渗透性防线。","scd":null,"kp":[]},{"i":38629,"as":"《能源研究与社会科学》上发表的一篇文章指出，在制定氢能管道相关决策时，公众参与意愿与现行法律框架之间存在着明显的脱节与鸿沟。","scd":null,"kp":[]},{"i":38630,"as":"先天性红细胞生成异常性贫血I型（CDA-I）患者的红细胞呈现特征性的“海绵状”异染色质。研究者证实，由CDAN1基因编码的Codanin-1蛋白与CDIN1编码的CDIN1蛋白在内源性状态下相互作用，形成稳定的复合物。结构与功能分析表明，该CDIN1-Codanin-1复合物本质上是一种RNA核酸酶。这一发现揭示了引发该罕见遗传性红细胞生成障碍疾病的蛋白质核心分子机制。","scd":null,"kp":[]},{"i":38631,"as":"基于中国亚热带地区调控树种丰富度（1至24种）的大型生物多样性实验，研究整合了11种对抗性和互利性物种相互作用网络及34种生态系统功能。分析表明，多营养级物种相互作用网络是解释生物多样性丧失生态后果的关键。刻画物种相互作用网络的结构特征，对于全面评估和量化生物多样性对生态系统多功能性的驱动作用具有不可替代的价值。","scd":null,"kp":[]},{"i":38632,"as":"研究证实，桥连脂质转运蛋白VPS13C/PARK23是细胞响应溶酶体损伤早期全局反应的关键组件。在机械或渗透压张力下，VPS13C会预先结合溶酶体。损伤引发的脂质堆积缺陷被其C末端的ATG2C结构域感知，触发蛋白构象变化。VPS13C形成的内质网-溶酶体接触平台为OSBP/ORPs蛋白提供了关键结合位点，从而实现内质网对受损溶酶体的高效包裹，启动有效的膜修复。","scd":null,"kp":[]},{"i":38633,"as":"一项历时28年、涉及9063名患者的德国前瞻性研究探讨了原发性黑色素瘤假阴性诊断带来的影响。结果显示，共有206例（2.3%）患者出现假阴性诊断，从假阴性到确诊的中位时间为24.0个月。在生存率方面，假阴性诊断患者的10年无复发生存率为32.9%，而初次即确诊的患者为76.2%。数据证实假阴性诊断导致的治疗延迟会显著恶化患者预后。","scd":null,"kp":[]},{"i":38634,"as":"Michelle Francl将早期在化学领域做出贡献却被忽视的女性科学家重新拉回公众视野，重点关注了这些早期女性化学家的历史成就与地位。","scd":null,"kp":[]},{"i":38635,"as":"重点阐述了异戊二烯在连接生物圈与大气层之间的关键作用。异戊二烯将植物与全球气候联系在一起，并在植物、人类、材料以及气候系统中发挥着多种关键作用。","scd":null,"kp":[]},{"i":38636,"as":"能够围绕中心轴进行360度旋转的分子具有驱动纳米级机器运动与功能的潜力。本专题汇编了多篇文章，集中展示了旋转分子马达领域的最新技术进展，并探讨了该领域未来面临的挑战。","scd":null,"kp":[]},{"i":38637,"as":"真核生物主要通过泛素-蛋白酶体系统（UPS）进行蛋白质降解，但细胞器内的膜蛋白难以直接被 UPS 降解。细胞利用保守的 AAA+ ATP酶 Cdc48 将细胞器蛋白提取到细胞质中，从而促进其被蛋白酶体降解。研究重点比较了内质网、线粒体和叶绿体中依赖 Cdc48 的蛋白水解系统，分析了它们在维持各自细胞器蛋白质稳态方面的异同及其在人类健康领域的意义。","scd":null,"kp":[]},{"i":38638,"as":"值此Ben Feringa获得诺贝尔化学奖（表彰其设计分子机器）十周年之际，他在专访中分享了自己的职业生涯、在分子马达和光开关领域的最新研究进展，并为年轻研究人员提出了宝贵的建议。","scd":null,"kp":[]},{"i":38639,"as":"《自然》读者分享了他们在攻读博士学位期间进行时间管理的困境与烦恼，集中反映了博士生群体面临的科研时间分配问题。","scd":null,"kp":[]},{"i":38640,"as":"在南极探测到的一种高能粒子起源于一个特定的星系。研究指出，该粒子诞生于宇宙早期一个正在大量孕育新生的恒星的星系（被称为“影子爆破手”），由此确认了这种中微子的诞生地。","scd":null,"kp":[]},{"i":38641,"as":"","scd":null,"kp":[]},{"i":38642,"as":"防止自组装单分子脱离并增强其对钙钛矿的钝化效应是提升钙钛矿太阳能电池性能和稳定性的关键。研究采用电沉积法取代传统溶液工艺，通过电位循环电沉积促进了分子的重排和重新锚定，在氧化铟锡（ITO）基底上形成了均匀致密且锚固性更强的SAMs层。通过电化学氧化偶联生长的功能单元，构建了定制的咔唑膦酸类SAMs，显著提高了电池的光电转换效率。","scd":null,"kp":[]},{"i":38643,"as":"地衣是真菌与光合生物的共生体，能在贫营养环境中繁衍。研究阐明了地衣型真菌黄色石衣适应铁限制环境的机制。该真菌共生体能够产生铁载体铬素，并拥有完整的基因系统，用于铁载体生物合成、还原性铁同化、铁解毒及调节。合成铁载体的非核糖体肽合成酶具有地衣特有的紧凑结构，在异源表达中依然保持功能，从而为其微藻共生体提供支持。","scd":null,"kp":[]},{"i":38644,"as":"快速制备的Ru-NiMn/NF-IH催化剂通过改善底物吸附、促进去质子化以及调控反应路径，显著提升了析氢反应（HER）和生物质衍生分子电氧化（HMFOR）的活性。该研究将双功能反应机制与催化剂设计直接关联，为提高电氧化催化剂的活性和耐久性提供了重要见解。","scd":null,"kp":[]},{"i":38645,"as":"交通基础设施的扩张对热带环境传染病传播的影响尚不明确。研究采用准实验方法，以秘鲁亚马逊地区跨洋公路2009年的铺设为自然实验，评估了公路铺设对登革热病毒传播的影响。通过控制各项混杂变量并对比公路附近与远处的医疗设施数据，量化分析了公路铺设前后登革热发病率的差异。","scd":null,"kp":[]},{"i":38646,"as":"利用晶格失配调控表面应变可以增强外延过渡金属薄膜的电催化活性。研究证实，在使用外延铂薄膜进行电化学氧还原反应时存在厚度依赖的临界应变。在临界应变之下，薄膜可避免不可逆的应变松弛。第一性原理计算表明，临界应变范围为-8.2%（压缩）至2.7%（拉伸），且在厚度不超过约3纳米的铂薄膜中能保持-2.5%的最优应变，从而实现催化剂稳定性与活性的最优化。","scd":null,"kp":[]},{"i":38647,"as":"美国国家科学院新任院长Neil Shubin承诺将加倍投入科学研究。他同时警告称，一个失去科学的群体必将失去未来，强调了科学发展对社会的重要性。","scd":null,"kp":[]},{"i":38648,"as":"银屑病是一种自身免疫性皮肤病。生物信息学分析显示，银屑病皮损中INSIG1（一种胆固醇合成调节因子）的表达与促炎细胞因子（IL-23、IL-17A）水平呈显著负相关。单细胞RNA测序和免疫荧光证实，银屑病皮肤巨噬细胞中的INSIG1表达显著降低。在髓系细胞中特异性敲除Insig1基因会通过SREBP2-STAT1轴加剧咪喹莫特诱发的银屑病样皮炎，表现为表皮增厚加剧等现象。","scd":null,"kp":[]},{"i":38649,"as":"基因相同的细胞在代谢活性上存在差异，进而影响耐药性、细胞分化和免疫激活。研究利用基于成像的单细胞空间蛋白质组学，揭示了人类酶蛋白组的非遗传变异性。近五分之二的酶表现出细胞间的表达差异，且一半定位于多个细胞区室。这种代谢异质性在很大程度上独立于细胞周期自主产生，并且单个细胞能在几代繁衍过程中重建这些多种代谢表型。","scd":null,"kp":[]},{"i":38650,"as":"在蛋白质支架中引入非生物催化辅因子构建的人工酶，在催化非天然反应中展现出潜力。研究提出一种高效的细胞内人工酶组装策略，通过将表达目标蛋白的细胞与合成催化辅因子共孵育，利用细胞内的天然机制进行共价锚定。该人工酶在细胞内通过位点特异性形成二硫键高效组装，成功在细胞质中催化了不对称曼尼希反应，表现出优异的对映选择性。","scd":null,"kp":[]},{"i":38651,"as":"甾体药物活性成分主要源于天然甾体，其生物合成的关键步骤是由酮类固醇异构酶（KSI）催化的异构化反应。研究发现KSI具有出人意料的催化混杂性，能将环烯酮高效转化为同型和杂型加成产物。晶体结构和诱变表明同源二聚体界面是另一个活性中心。分子动力学和量子力学计算揭示了一种单酶级联催化机制：异构化发生在单体口袋中，而加成反应则优先发生在此特定界面处。","scd":null,"kp":[]},{"i":38652,"as":"文章重点介绍了仿生协同限域催化，通过统一化学环境和空间结构来突破传统催化剂设计的局限。研究通过解构限域机制并提出由瓶颈驱动的部署策略，为材料科学家设计能够媲美天然酶的高效、高选择性的多尺度催化系统提供了系统的设计框架。","scd":null,"kp":[]},{"i":38653,"as":"纳米限域工程能够同时调控单原子催化剂的配位数和位点间距，从而改变催化反应路径。这种双重调控机制迫使反应向高选择性地生成高价铁氧（FeIV=O）物种的方向进行，实现了对特定催化反应的高效控制。","scd":null,"kp":[]},{"i":38654,"as":"由内部化学振荡器驱动的空心水凝胶胶囊可在轻微的形状波动和大规模屈曲之间自主切换。这种模式选择由化学和机械时间尺度之间的单一无量纲比率控制。该框架将多种材料和反应条件归纳为一个预测相图，为在活性软材料中编程自主变形确立了设计原则。","scd":null,"kp":[]},{"i":38655,"as":"药物释放动力学可通过内部细丝结构进行编程。多材料3D打印将载药、无药和屏障细丝组织成特定的传输路径。同时，可解释的机器学习与PBPK模型将结构设计与可调释放及疾病相关的暴露控制联系起来，从而避免了反复改变配方。","scd":null,"kp":[]},{"i":38656,"as":"被动冷却技术能减少建筑物和公共空间的热量与太阳辐射增益并散发多余热量，从而降低机械空调对环境的影响、电力消耗及电网压力。该综述探讨了智能太阳控制、通风以及辐射、蒸发和混合散热系统的进展。这些技术从技术成熟阶段到新兴材料应用各有不同，且通风、辐射和蒸发冷却均具有低能耗的特点。","scd":null,"kp":[]},{"i":38657,"as":"高角环形暗场高分辨率扫描透射电子显微镜（HAADF-HRSTEM）被用于观察和理解催化剂的活性位点。","scd":null,"kp":[]},{"i":38658,"as":"结合单细胞RNA测序、空间转录组学和基因组学技术，对28名同时患有导管原位癌（DCIS）和浸润性乳腺癌（IBC）的患者进行分析。浸润主要由预先存在的DCIS亚克隆扩增驱动，强调转录重编程和肿瘤微环境（TME）重塑的作用。IBC细胞表现出明显的上皮-间充质转化和代谢重编程。研究明确了侵袭前沿的动态TME重塑及关键的配体-受体相互作用（如PPIA-BSG）。","scd":null,"kp":[]},{"i":38659,"as":"20世纪60年代的“绿色革命”半矮化品种以积累DELLA蛋白为特征，虽提高了抗倒伏性和收获指数，但降低了单株生物量和生产力，且需要高氮肥投入。研究阐明了赤霉酸（GA）结合GID1受体诱导DELLA蛋白发生多层次构象变化，影响其特定的N端结构，为改善水稻氮利用效率和实现可持续农业提供了机制。","scd":null,"kp":[]},{"i":38660,"as":"染色质重塑因子BRG1通过抑制铁死亡，介导了套细胞淋巴瘤（MCL）对BTK抑制剂（BTKi）的耐药性。依赖BRG1的异常转录程序通过限制活性氧（ROS）和不稳定铁来保护细胞免于铁死亡。BRG1诱导MEF2B表达，上调非典型线粒体复合物I亚基NDUFA4L2。增加的NDUFA4L2限制细胞呼吸，从而预先减少线粒体ROS，导致耐药性。","scd":null,"kp":[]},{"i":38661,"as":"一种触觉编码的脑机接口（BCI）利用触觉诱发的P300范式，实现了对额外运动意图的可靠解码，且该解码与自主行为叠加时依然有效。在多日双任务实验中，该接口在评估自然运动潜在影响的同时，实现了对四个额外自由度运动意图的实时可靠解码，解决了增强指令与自然运动集成的挑战。","scd":null,"kp":[]},{"i":38662,"as":"植物碱喜树碱是合成多种抗癌药物的高价值前体，其生物合成途径的关键是从6/5/6四氢-β-咔啉环系统重组为6/6/5吡咯并喹啉骨架。研究发现，黄素单核苷酸等黄素辅因子可在光氧化过程中高效催化这一骨架转变。研究验证了先前假设的大环酮内酰胺中间体的存在，并证明在有氧、光照和黄素的温和条件下，这种转化也可以在叶片中发生。","scd":null,"kp":[]},{"i":38663,"as":"在利用H2和O2直接环氧化烯烃的过程中，原位生成的H2O2在扩散期间迅速分解，导致大部分Ti活性位点无法被利用。研究通过将疏水性聚合物与双功能Au/TS-1催化剂进行物理结合，构建了疏水性传输通道。这种微环境加速了H2O2的传输，成功克服了中间体传输限制对串联催化效率的影响。","scd":null,"kp":[]},{"i":38664,"as":"固体电解质界面（SEI）的形成受双电层（EDL）控制。研究设计了一种不对称室温鏻离子液体PMEP，旨在促进阴离子增强的EDL。分子的不对称性降低了PMEP的熔点，并促进了PF6−参与以Li+为中心的溶剂化结构。分子动力学模拟和密度泛函理论计算证实了该设计在引导电解质还原和SEI演化方面的机制。","scd":null,"kp":[]},{"i":38665,"as":"为使水凝胶人工组织具备可编程的复杂运动，研究通过两种方法在生物相容性水凝胶中生成了非单向各向异性：对静态样品施加非稳态磁场，以及将稳态磁场与剪切流叠加。这两种方法均使磁性颗粒在聚合物基质中进行定向自组装，随后基质凝胶化以固定形成的层状结构。研究分析了组装动力学，表征了层状图案，并为每种方法构建了相图。","scd":null,"kp":[]},{"i":38666,"as":"为高效可持续地生产过氧化氢（H2O2），研究人员合成了一种由界面酸位点介导的ZnSe/ZnO异质结电催化剂，用于高选择性的两电子氧还原反应（ORR）。实验和理论结果表明，表面硒化诱导了结构重构，形成了具有内建电场的协同界面，从而优化了催化性能。","scd":null,"kp":[]},{"i":38667,"as":"挪威斯瓦尔巴群岛已成为北极科学研究的关键前哨。然而，地缘政治的紧张局势正使该地区的科学研究工作变得复杂化。","scd":null,"kp":[]},{"i":38668,"as":"","scd":null,"kp":[]},{"i":38669,"as":"一种内置在计算机存储芯片中的人工神经网络实现了高精度的实时人类大脑皮层重建。","scd":null,"kp":[]},{"i":38670,"as":"一种机械敏感性离子通道在肝脏受损后能够调节肝细胞的增殖，进而调控肝脏的再生过程。","scd":null,"kp":[]},{"i":38671,"as":"果蝇会主动寻找黑暗环境，以此来重新启动其内部的生物钟。","scd":null,"kp":[]},{"i":38672,"as":"","scd":null,"kp":[]},{"i":38673,"as":"","scd":null,"kp":[]},{"i":38674,"as":"极高的树木高度被认为会损害其水力系统，使其更易受干旱破坏。对世界上最高的热带树木——龙脑香科树种的研究表明，树木能够通过调整导管解剖结构和叶片水力特征，完全补偿由高度引起的木质部压力降低。在严重干旱期间，这些高大树木的生长并未因高度而受损。因此，高度不会使热带最高树种的水力系统更容易受到干旱的负面影响。","scd":null,"kp":[]},{"i":38675,"as":"纤锌矿结构的Al1-xScxN铁电体具有出色的极化和热稳定性。研究利用球差校正透射电子显微镜发现，阳离子和阴离子间距沿极化方向存在周期性调制，形成了交替的原子偶极子层。这种调制源于铝和钪原子在相邻层之间能量有利的化学排序，有效降低了切换能垒并减小了矫顽场。","scd":null,"kp":[]},{"i":38676,"as":"在癌症恶病质模型中，肝激酶B1（Lkb1）的缺失促进了恶病质的发展。高脂饮食不仅未能改善热量摄入，反而加重了恶病质症状。机制上，肿瘤局部产生的前列腺素E2（PGE2）驱动了这一病理过程。通过基因、饮食或药理学手段抑制肿瘤衍生的PGE2，能够有效抑制疾病行为和恶病质的发生。","scd":null,"kp":[]},{"i":38677,"as":"研究揭示了植物表面免疫信号通过mRNA剪接解锁核苷酸结合富亮氨酸重复（NLR）免疫受体激活的调节机制。马铃薯晚疫病抗性蛋白Rpi-vnt1.1中存在一个抑制抗病小体形成的N端结构域，可阻止NLR自激活。病原体识别后，PTI信号诱导该蛋白mRNA发生可变剪接，去除该抑制元件，从而促使Rpi-vnt1.1被致病疫霉激活。","scd":null,"kp":[]},{"i":38678,"as":"研究通过使用由轨道角动量（OAM）主导的磁性材料，展示了轨道霍尔磁电阻效应的显著增强。在氧化钴/铜（CoO/Cu*）结构中，表面氧化的铜产生的动态OAM与反铁磁绝缘体CoO中的静态OAM发生相互作用，使得其轨道霍尔磁电阻比氧化钴/铂（CoO/Pt）中的自旋霍尔磁电阻高出70倍，证明利用OAM主导材料能有效利用巨轨道电流。","scd":null,"kp":[]},{"i":38679,"as":"研究团队在量子处理器上利用（2+1）D格子规范理论观察了无序局域化现象。通过使用初始化为所有无序构型叠加态的量子电路来降低采样成本，在实验时间尺度内成功观察到一维和二维中无序条件下的局域化（微扰未能扩散）。然而，熵测量表明，这种叠加态与直接无序采样得到的态存在本质区别。","scd":null,"kp":[]},{"i":38680,"as":"","scd":null,"kp":[]},{"i":38681,"as":"研究开发了一种基于相变忆阻器的神经动力学系统（NDS）硬件，利用忆阻器的电导漂移和存内计算能力，将计算延迟降低至10毫秒以下。该团队制造了40纳米制程的NDS芯片用于表面重建任务。与现有硬件相比，该单次迭代NDS计算的延迟仅为2.12毫秒，误差容限为10，有效解决了物理建模中实时密集可微分变形场的计算延迟问题。","scd":null,"kp":[]},{"i":38682,"as":"","scd":null,"kp":[]},{"i":38683,"as":"研究表明，高脂饮食会影响小鼠体内的肿瘤到神经的信号传导，从而促进恶病质（系统性衰退）的发展。","scd":null,"kp":[]},{"i":38684,"as":"创新架构的演变反映了围绕科学发展的各类机构的不断成熟。","scd":null,"kp":[]},{"i":38685,"as":"","scd":null,"kp":[]},{"i":38686,"as":"美国的研究型大学在美国历史进程中留下了不可磨灭的印记。","scd":null,"kp":[]},{"i":38687,"as":"宿主与微生物的共同进化对人类健康具有重要影响。","scd":null,"kp":[]},{"i":38688,"as":"微生物间的竞争机制可用于预防和治疗致命疾病。","scd":null,"kp":[]},{"i":38689,"as":"微生物群落在蚊媒疾病中隐藏着重要作用。","scd":null,"kp":[]},{"i":38690,"as":"许多至今仍以某种形式存在的美国基础创新政策，是在第二次世界大战期间发展起来的。","scd":null,"kp":[]},{"i":38691,"as":"","scd":null,"kp":[]},{"i":38692,"as":"美国建国之初便高度重视科学知识。本杰明·富兰克林等建国者深刻认识到新知识的重要性。独立战争前新英格兰已建立私立大学，南方各州在建国同期也创建了佐治亚、北卡罗来纳等公立大学，托马斯·杰斐逊卸任后也在夏洛茨维尔创办了新机构。","scd":null,"kp":[]},{"i":38693,"as":"果蝇通过主动选择环境来维持其昼夜节律。光照会导致核心节律蛋白Timeless降解，使节律停止。在持续光照环境中，果蝇通过在明暗区域间移动，成功维持或恢复了规律的行为模式。这种自我维持的节律伴随着驱动行为节律的神经元的分子节律，且规律行为的果蝇相比节律紊乱的果蝇睡眠质量显著提高。","scd":null,"kp":[]},{"i":38694,"as":"美国国立卫生研究院（NIH）针对基因组数据集出台的安全规则导致研究进程放缓。数据安全专家认为加强监管是必要的，但研究人员在遵守这些规定方面面临困难。","scd":null,"kp":[]},{"i":38695,"as":"实验室成功研发出一种名为“SpudCells”的新型合成细胞。这种合成细胞具备生长和分裂的能力，但在功能和应用上仍存在重大局限性。","scd":null,"kp":[]},{"i":38696,"as":"施普林格·自然出版集团撤回了量子力学先驱马克斯·普朗克的两篇研究论文。撤稿原因可能与自动程序机器人（bot）的操作有关。","scd":null,"kp":[]},{"i":38697,"as":"尽管面临审批延误和人员短缺问题，美国国立卫生研究院（NIH）预计仍能全额支出2026年预算。然而，新增资助项目的数量可能将继续保持在历史平均水平之下。","scd":null,"kp":[]},{"i":38698,"as":"古老的冈瓦纳大陆分裂引发的 mantle waves（地幔波）和构造拉伸作用，将极地山脉抬升至极寒地带，这一地质过程最终促使了广阔的南极冰盖的形成。","scd":null,"kp":[]},{"i":38699,"as":"霍华德·休斯医学研究所将启动一项耗资10亿美元的宏大神经科学项目，透明鱼类Danionella将成为该研究的核心模式生物。","scd":null,"kp":[]},{"i":38700,"as":"鲁宾天文台的大型相机将开始执行为期10年的宇宙观测任务。该望远镜将对天空进行反复扫描，旨在发现暂现源的同时，构建包含数十亿个星系的深度宇宙图谱。","scd":null,"kp":[]},{"i":38701,"as":"研究分析了47个人类组织中1400万个单细胞的379个激素及受体基因表达数据，成功构建了人类内分泌系统细胞分辨率图谱。利用hormone2cell工具，识别了产生和接收激素的细胞类型，定义了组织特异性和跨组织内分泌特征。研究预测了激素表达的非经典位点（如浆细胞样树突状细胞中的促胰液素），推断了激素反馈环路，并揭示了脂肪细胞中动态的内分泌程序。","scd":null,"kp":[]},{"i":38702,"as":"研究确定了第2组固有淋巴细胞（ILC2s）是胰腺成纤维细胞稳态的关键调节因子。ILC2s在外分泌胰腺的间隙微环境中，与表达Pi16+、Dpp4+、Ly6c+基因的成纤维细胞共定位，该微环境包绕胰腺实质。ILC2s能够特异性调节这些成纤维细胞的扩增，从而在原位控制组织成纤维细胞的分布拓扑结构和发育。","scd":null,"kp":[]},{"i":38703,"as":"","scd":null,"kp":[]},{"i":38704,"as":"人类肾脏类器官缺乏可靠的空间 patterning。通过人类肾脏发育的空间转录组学分析，研究发现新生肾单位在WNT11-WNT9B信号边界建立极性。将工程化分泌WNT的细胞组织者引入肾脏类器官，能够恢复其组织几何结构，从而指导后续的肾脏形态发生，成功在体外重建了发育组织者介导的空间模式。","scd":null,"kp":[]},{"i":38705,"as":"研究开发了TranscriptFormer生成式基础模型家族，基于跨越12个物种、15.3亿年进化史的1.12亿个细胞数据进行训练。该模型在细胞类型分类上表现出色，能识别相隔6.85亿年物种间的细胞类型，并在人类细胞中实现零样本疾病状态识别。发育轨迹、系统发育关系和细胞层级等特征在模型表征中自然涌现，为单细胞转录分析提供了量化框架。","scd":null,"kp":[]},{"i":38706,"as":"针对跨膜蛋白疏水表面导致生产和结构分析困难的问题，研究提出基于深度学习的全新蛋白设计方法。设计了基因编码的水溶性WRAPs蛋白，包裹膜蛋白的疏水表面，使其无需去垢剂即可具备热稳定性和水溶性，同时保留天然序列、折叠和配体结合特性。该策略成功应用于单聚体和寡聚体跨膜蛋白，并解析了2.95埃分辨率的冷冻电镜结构。","scd":null,"kp":[]},{"i":38707,"as":"研究探讨了南极洲在约3400万年前形成冰川的原因。结合地球动力-地形模型与冰盖能量平衡模型，研究发现由侏罗纪大陆裂解和地幔-地表反馈驱动的区域地形隆起起到了关键作用。渐进式的南极高原生长（始新世甘布尔采夫山脉隆起）在约4500万年前将地貌推升至冰盖成核临界点以上，从而促成了东南极冰盖的形成。","scd":null,"kp":[]},{"i":38708,"as":"研究揭示了小鼠肝脏再生过程中区域特异性机械感应的关键机制。中叶肝细胞（特征为表达DPP4）是主要的增殖细胞群，其表面富集的机械感受器PIEZO1能够整合生物力学信号，通过胰岛素样生长因子结合蛋白2（IGFBP2）驱动肝脏重新生长。遗传破坏PIEZO1会抑制肝细胞增殖并损害肝脏再生，确认了PIEZO1在驱动肝小叶第2区细胞增殖中的核心作用。","scd":null,"kp":[]},{"i":38709,"as":"","scd":null,"kp":[]},{"i":38710,"as":"针对纤维状锌金属电池（FZBs）中复杂的锌沉积动力学导致枝晶生长的问题，研究开发了一种基于含氧官能化碳纳米管纤维（OCNTF）的纤维状锌电极。通过定制的连续化工艺，成功制备出米级长度的FZBs。高度结晶且排列整齐的OCNTF与锌具有极低的晶格错配度，显著缓解了枝晶的形成，同时致密的结构有效提升了柔性电池的性能与稳定性。","scd":null,"kp":[]},{"i":38711,"as":"在JT-60SA托卡马克装置中进行了ITER相关的低感应电场等离子体启动实验。研究发现，欧姆零场位形（FNC）启动受限于高杂质含量；而电子回旋（EC）辅助FNC启动则受制于装置模型不确定性引发的剩余极向磁场和等离子体外移。相比之下，捕获粒子位形（TPC）通过施加有限的垂直磁场，有效克服了上述限制，实现了更可靠的等离子体启动与击穿。","scd":null,"kp":[]},{"i":38712,"as":"研究提出在无需阻抗匹配的条件下，利用非线性谐振器实现耗散传感器近单位信号读出的方法。通过驱动谐振器进入非线性工作区域，对双量子点电荷状态进行读出。实验和数值计算表明，传感器耗散改变了非线性谐振器响应的起始点，从而突破了线性体系中阻抗匹配对读出带宽和信号强度的上限限制，实现了接近1的读取信号。","scd":null,"kp":[]},{"i":38713,"as":"研究调查了金属间化合物Ru2Sn3的热电输运行为，发现尽管其具有晶体有序性，但在8-14 K的热容中表现出类似玻璃化转变的玻色峰反常。结合第一性原理计算和分子动力学模拟，该反常源于其烟囱阶梯结构产生的低能光学声子。这些模式与声学声子强烈耦合，重塑了振动光谱，使混合声学支直接贡献于反常现象。热电测量证实了其本征低热导率的物理机制。","scd":null,"kp":[]},{"i":38714,"as":"研究通过流体动力学方法提升了宏观碳纳米管（CNT）纤维的拉伸强度。该方法利用高速喷射乙醇冲刷和收缩预制CNT纤维，显著改善了CNT的排列和堆积密度，从而大幅增加了管间的范德华力。在最优条件下，新型CNT纤维的比拉伸强度达到7.5×10^6 N·m·kg⁻1，绝对拉伸强度高达12.5 GPa，逼近单根CNT的强度下限，且具有370 GPa的高杨氏模量和优异的导电性。","scd":null,"kp":[]},{"i":38715,"as":"研究开发了一种用于高灵敏检测气体的同轴嵌套不对称光纤谐振腔（FRC）系统。基于建立的腔内拉曼信号产生理论框架，提出不对称FRC设计，有效平衡了激光功率增强与高反射镜引入的腔内损耗。相比单空心光纤和单几何谐振腔，该设计分别将拉曼信号强度提升了170倍和36倍。结合分离膜，该系统能够在极小体积内实现多组分气相及溶解气体的动态、高灵敏同步检测。","scd":null,"kp":[]},{"i":38716,"as":"研究通过微波冲击法合成了二维六方YMnO3体系，成功实现了航空航天天蓝可见光伪装与中红外透明在高温环境下的兼容。传统材料中蓝色电子跃迁往往与晶格极化耦合，破坏中红外透明窗口。二维YMnO3具有非易失性的高热稳定性，克服了这一长期制约。其具备优异的热稳定性、天蓝色外观和中红外透明性，展现出巨大的应用潜力。","scd":null,"kp":[]},{"i":38717,"as":"研究在全范德华异质结中实现了创纪录的室温103%磁阻率。该器件采用范德华铁磁材料Fe3GaTe2作为电极，单元素黑磷或紫磷作为间隔层。器件的磁阻表现出对磁场角度不依赖的特性，同时保持了各向异性的矫顽力。这种独特的性能源于由畴壁运动驱动的磁化反转机制以及材料本身强大的垂直磁各向异性，为室温自旋阀器件提供了新思路。","scd":null,"kp":[]},{"i":38718,"as":"研究证明了通用机器学习原子间势能在规模化训练中能够自发获得关于化学键解离能的化学直觉。研究开发了边级涌现能量分解框架，并应用于在SPICE2分子数据集上训练的E(3)等变神经网络势能。在无直接监督的情况下，该模型成功提取了局部化学键信息。研究通过分析边级能量贡献、数据集大小及信息熵，阐明了模型容量的增加使其具备了可解释的化学概念能力。","scd":null,"kp":[]},{"i":38719,"as":"研究通过高温煅烧策略合成了引入非晶态Ti物种的钛铁矿催化剂FeTiOx，用于二氧化碳加氢合成高级醇。调节铜物种的分散性使高级醇选择性提升至30.2%，同时保持42.5%的CO2转化率。原位X射线衍射和红外光谱实时监测表明，催化剂相结构经历了Fe2O3向Fe3O4再到Fe5C2的动态演化，并捕捉到了CO*、CHx*和CH3CH2O*等关键化学中间物种。","scd":null,"kp":[]},{"i":38720,"as":"针对铂基催化剂在逆水气变换（RWGS）反应中CO选择性和耐久性不足的问题，研究提出了一种硫（S）介导的靶向钝化策略。通过将S引入二氧化铈载体，精确工程设计了Pt-CeO2催化剂的原子级活性位点。硫的掺入诱导了优化的电子调制，有效钝化了低配位Pt边缘位点对CO的过度吸附，解决了催化活性、稳定性和选择性之间的权衡问题，实现了CO2到CO的高效稳定转化。","scd":null,"kp":[]},{"i":38721,"as":"研究提出了一种“含液聚合策略”，通过在催化剂颗粒上周期性润湿和干燥惰性正己烷液体，精准调控非均相Ziegler-Natta催化剂的活性位点核数。原位光谱证实，这种独特的流体环境促进了双核钛物种的形成，而非常规体系中占主导地位的单核物种。这些双核位点大幅提高了共聚单体的结合效率，使得生成的聚乙烯具有更加均匀的短链支化分布。","scd":null,"kp":[]},{"i":38722,"as":"研究开发了一种基于二维二硫化铼（ReS2）与铁电氧化铪锆（HZO）的场效应晶体管光偏振电光存储器。异质结界面的晶格失配引发压缩应力，缩短了Re-Re键，使其各向异性提升了3倍。光生载流子在界面处的重分布建立了静电场，调制HZO铁电畴以编码非易失性状态。该器件通过电场驱动的电荷分离实现了偏振分辨的存储能力，为多维信息处理提供了新通道。","scd":null,"kp":[]},{"i":38723,"as":"该研究提出了一种低温、无水的制造策略，用于构建基于Mg基材料的微型热电冷却器（μ-TEC），以替代有毒且稀缺的Bi2Te3基材料。研究通过磁控溅射冷键合方法，成功制造了由n型Mg3(Bi,Sb)2和p型MgAgSb组成的紧凑型12对微型器件。该器件尺寸为2.95 × 4.35 × 1.4立方毫米，热电腿长度约为3毫米。此方法解决了Mg基热电材料在微尺度器件中集成的挑战，为高性能且环保的电子热管理提供了新方案。","scd":null,"kp":[]},{"i":38724,"as":"科研人员通过3D打印“外衣”技术将蟑螂改造为“半机械”生物。这些经过改造的昆虫具备了水下呼吸的能力，能够在水下环境中进行长达三小时的探索任务。此外，相关报道还提及了虚假的癌症研究论文获取了大量引用的现象，并探讨了科学家如何通过认识自身偏见来建立公众信任。","scd":null,"kp":[]},{"i":38725,"as":"非小细胞肺癌（NSCLC）具有高侵袭性和死亡率。研究发现，TMED9在NSCLC中高度表达，且其表达水平与患者预后不良显著相关。功能实验表明，TMED9能促进NSCLC细胞的增殖、侵袭和迁移，并在体内加速肿瘤生长和转移。在机制上，TMED9与ATG9A相互作用，并招募USP5使ATG99去泛素化从而保持其稳定，最终激活自噬过程。这揭示了TMED9在NSCLC病程中的关键驱动作用。","scd":null,"kp":[]},{"i":38726,"as":"探测非常规对称性超导相的序参量对称性和拓扑结构是超导研究的重大挑战。研究团队利用扫描隧道显微镜（STM）技术，通过分析由一对杂质作为分束器产生的杨氏准粒子干涉图样，成功提取了超导能隙的相位缠绕信息。这项被称为超导序参量断层扫描（SOPT）的技术，突破了以往STM无法探测相位信息的限制，实现了对超导序参量的实空间成像。","scd":null,"kp":[]},{"i":38727,"as":"在传染病暴发期间，准确区分病原体是由患病旅行者感染当地健康居民，还是由患病居民感染外来旅行者后带回，对理解疫情动态至关重要。研究引入了一种结合流行病学 compartment 模型稳态特性的系统发育地理学模型。该模型通过包含访客动态（宿主短暂访问其他群体后返回）来追踪病原体的传播，构建了一种统计准确且计算高效的近似方法，用于在访客动态下推断流行病学参数。","scd":null,"kp":[]},{"i":38728,"as":"通过针对学龄前至小学二年级儿童的大规模纵向功能性磁共振成像研究，揭示了大脑数学响应网络的发展机制。数据显示，儿童在入学前倾听数学陈述时，已能调动类似成人的皮层网络，并对几何具有部分特化性。在头两年的正规教育中，大脑与数学相关的激活整体增加，额外神经区域的参与度小幅提升，且对已知事实的激活反应降低。这些发现为数学认知发育理论提供了纵向评估数据。","scd":null,"kp":[]},{"i":38729,"as":"实现HIV-1治愈需防止治疗中断后的病毒反弹，但目前缺乏定义反弹能力病毒库的定量标准。研究发现，在13名参与者中，有9人的反弹病毒与循环静息CD4+ T细胞中的前病毒遗传相同或相似，且反弹序列无重组现象。自体中和抗体对病毒反弹起决定性作用：血浆中IgG对病毒生长的抑制增强与反弹时间延长直接相关。这表明自体中和抗体的抑制潜力为反弹型HIV-1病毒库设定了定量限制。","scd":null,"kp":[]},{"i":38730,"as":"在合成生物学中，将能量保存机制与其他生物功能自下而上整合以创建类生命复杂系统是一项挑战。研究开发了一种人工呼吸链，专门用于维持固定CO2的16酶催化循环中的快速电子转移。该系统同时利用伴随的电子流进行能量保存（如合成ATP）。这一人工呼吸链的直接整合成功克服了无细胞代谢网络中心氧化反应与能量保存不耦合的动力学和热力学限制，显著提升了无细胞代谢效率。","scd":null,"kp":[]},{"i":38731,"as":"","scd":null,"kp":[]},{"i":38732,"as":"皮肤界面可穿戴生物医学设备需要与皮肤保持稳定、亲密的接触，同时要求易于拆卸以减少刺激。吸盘式安装因其能提供强力、无粘合剂且可逆的附着而成为极具前景的替代方案。为解决其底层力学机制尚不完全清楚的问题，该研究建立了一个完全显式的解析模型，用于描述吸盘在变形和受力过程中的力学行为，为吸盘设计提供了理论指导。","scd":null,"kp":[]},{"i":38733,"as":"许多膜蛋白通过弱非共价相互作用自组装成空间模式，进而形成高阶瞬态结构（HOTS）。这些10到100纳米大小的HOTS在膜信号传导中充当瞬态枢纽。研究阐述了HOTS组装的必要条件、其与生物分子凝聚相形成的 thermodynamic 关系，以及由其独特物理性质衍生出的潜在生物学功能。目前对HOTS的定量理解仅限于膜蛋白，但多项观察表明，HOTS在三维细胞区室中同样广泛存在。","scd":null,"kp":[]},{"i":38734,"as":"","scd":null,"kp":[]},{"i":38735,"as":"","scd":null,"kp":[]},{"i":38736,"as":"","scd":null,"kp":[]},{"i":38737,"as":"戊型肝炎病毒（HEV）是引发病毒性肝炎的主要原因，孕妇感染后预后不良。研究揭示了一条促进HEV复制的脂质介导途径。脂质组学分析显示，HEV感染的人肝细胞及感染 HEV-3ra 的孕兔中油酸显著上调。实验表明，油酸通过与HEV ORF1多聚蛋白中的预测脂肪酸结合域（FABD）相互作用，大幅增强HEV复制。这解释了孕期HEV复制增强的潜在机制。","scd":null,"kp":[]},{"i":38738,"as":"哺乳动物胚胎皮肤毛囊前体的空间模式通常被描述为一种扩散-诱导过程。然而，最新发育数据表明，鳞片、羽毛和毛囊基板是通过表皮和真皮信号的反应-扩散-趋化细胞相互作用进行自组织的。研究提出，该框架中的趋化成分足以解释胎盘插入在差异极大的两种哺乳动物物种中的动态变化。这表明趋化自组织是驱动哺乳动物毛囊模式形成的核心机制。","scd":null,"kp":[]},{"i":38739,"as":"配子间的功能不对称性对性别进化至关重要，但最初同等的配子间差异如何产生尚缺乏经验证据。结合理论与实验对裂殖酵母的研究表明，虽然P型和M型配子形态完全相同，但它们在减数分裂凝聚蛋白（如Rec8）的贡献上存在不对称性。P型配子在合子发育中投入不同量的保守减数分裂凝聚蛋白，这种不对称投入使配子产生适应性代价，从而推动了基因表达中亲本偏向性的进化。","scd":null,"kp":[]},{"i":38740,"as":"空间上下文通过增强新特征并抑制空间冗余特征来修饰视觉感知，这发生在初级视觉皮层（V1）中。为了探究前馈、反馈和侧向皮层内通路的具体贡献，研究利用7T超高分辨率fMRI（0.6毫米各向同性分辨率），分析了参与者在观看嵌入背景中的正弦光栅盘时跨越皮层深度的BOLD信号。研究通过分析皮层层面的信号变化，揭示了不同神经通路在方向调谐的侧向抑制中的相对贡献。","scd":null,"kp":[]},{"i":38741,"as":"球形托卡马克（ST）是一种低环径比装置，能够在高归一化环向β和高自举电流分数下运行。由于紧凑型ST反应堆无法配备全尺寸螺线管，必须通过非电感驱动来实现持续运行所需的电流爬升。利用自由边界 TRANSP 代码进行模拟，研究开发了一种电流爬升方案。在该方案中，大部分电流由中性束电流和自举电流非电感组合驱动，为实现MA级别的非电感电流爬升场景提供了理论支持。","scd":null,"kp":[]},{"i":38742,"as":"研究首次在优化的螺旋对称实验（HSX）仿星器准螺旋构型中，基于漂移约化Braginskii方程进行了全三维双流体等离子体湍流模拟。该模拟采用经过改造的GBS代码以适应具有大扭转率和椭圆率的三维磁场。模拟得到的时间平均密度、电子温度和静电势剖面与使用Langmuir探针和Thomson散射测量的边缘实验数据高度吻合。同时，涨落频率谱和空间相关性测量等湍流特性也展现出良好的匹配度。","scd":null,"kp":[]},{"i":38743,"as":"EPED模型通过结合动力学气球模（KBM）和剥离-气球（PB）约束来描述托卡马克的台基结构。在该模型中，KBM约束常通过计算理想气球模（IBM）阈值来近似。研究指出，在低环径比下，局部理想MHD与回旋动力学气球稳定性之间的定量差异更大。该工作应用简化模型计算了动力学气球稳定性，证明了KBM临界台基与常规及球形托卡马克的实验观测结果保持一致。","scd":null,"kp":[]},{"i":38744,"as":"开发高效、稳定且适用温宽的氨选择性催化还原（NH3-SCR）催化剂是工业NOx排放控制的重大挑战。研究提出了一种氧化物-沸石（OXZEO）混合设计策略，利用孤立的沸石Brønsted（B）酸位点在空间上分离氨的储存和氧化还原功能。机制研究表明，沸石B酸位点作为高度受控的氨存储库，储存的NH3解吸并以NH3和NH4+的形式迁移至氧化物活性位点。这种独特的脱硝机制实现了高效的NOx去除。","scd":null,"kp":[]},{"i":38745,"as":"地球内辐射带的高能电子对航天器系统构成重大威胁，其中低地球轨道（LEO）最强的辐射主要集中在南大西洋异常区（SAA）。基于澳门科学卫星一号任务的数据，研究报道了SAA辐射环境的瞬态畸变现象，表现为在传统SAA辐射区域外出现增强的高能电子通量。这些畸变是由改变电子镜像高度的大尺度电场扰动引起的，这种由电场驱动的绝热改变进一步调制了辐射带的动态变化。","scd":null,"kp":[]},{"i":38746,"as":"高质量二维纳米片的可扩展制备常受限于材料质量、产量和成本之间的权衡。研究通过多环芳烃自由基阴离子（PAH•-）介导的有机碱金属插层技术，实现了高品质二维晶体的秒级（约12秒）剥离。PAH•-可调的还原电位和电子转移能力使得碱金属离子能够在几秒钟内完成插层。以石墨为例，萘化钠在1秒内形成一阶石墨插层化合物，随后11秒内的水解剥离可产出单层比例大于50%、产率超88%且缺陷极低的石墨烯。","scd":null,"kp":[]},{"i":38747,"as":"","scd":null,"kp":[]},{"i":38748,"as":"本文回顾了范德华磁性材料中激子的研究进展。二维磁性半导体为长程磁序与强束缚激子的共存提供了独特平台，由于激子态和磁矩源自相同电子轨道，光激发对磁序表现出高度敏感性。实验观测到了异常强的磁光响应和激子-磁振子直接耦合现象，为利用自旋自由度控制光与物质相互作用开辟了新途径。文章重点总结了代表性材料体系、实验特征及描述这些现象的理论框架。","scd":null,"kp":[]},{"i":38749,"as":"本文利用网状化学在结晶框架中实现了局部限制的可编程调控。在三唑酸金属有机框架（由Kuratowski型Zn5Cl4节点构建）中，通过连接体几何结构引导形成ith-d拓扑，向内指的末端Zn结合基团生成了具有化学可寻址性的受限孔隙。该策略合成了两种具有不同笼尺寸和孔径的同网状框架（NU-6000和NU-6001），且合成后的氯化物向氢氧化物交换能在不损失结晶度的情况下向孔隙内引入密集的Zn-OH基团。","scd":null,"kp":[]},{"i":38750,"as":"本文回顾了摩尔分数陈绝缘体中分数量子反常霍尔效应的理论基础与实验进展。分数陈绝缘体将朗道能级的分数量子霍尔效应推广至无外加磁场的晶格系统中，源于电子间强相互作用与非平凡拓扑。尽管长期面临能带平整度等苛刻要求，二维摩尔超晶attice的发展克服了这些障碍，成功在摩尔材料中实现了分数量子反常霍尔效应的观测。","scd":null,"kp":[]},{"i":38751,"as":"本文提出了一种自模板梯度组装策略，以可控地调节聚合物的多尺度有序性和排列，从而大幅提高载流子迁移率。该策略基于溶解度参数和蒸汽压耦合框架确立了溶剂体系选择标准，以触发超分子有序组装。利用新设计的聚合物（PFIDTO-BT），研究优化了溶液态聚集体，实现了多尺度结构排序并可视化，有效克服了无法控制的聚集组装带来的限制，为下一代有机电子器件制造提供了高性能聚合物半导体。","scd":null,"kp":[]},{"i":38752,"as":"本文在扭转单层-多层菱面体石墨烯中发现了高陈数的轨道磁性。输运测量表明，当极化偏离摩尔界面时，在每摩尔晶胞一个和三个电子处出现明显的反常霍尔效应。通过Středa轨迹和量子化霍尔电阻，观察到C=n（n=3,4,5）的清晰拓扑等级，并得到自洽平均场计算的支持。此外，研究还实现了这些拓扑相的电学和磁学切换。该平台为多通道无耗散手性输运及超越C=1范式的关联相研究提供了新途径。","scd":null,"kp":[]},{"i":38753,"as":"中国国家自然科学基金委员会宣布，从今年起将额外资助12,000个项目。这一举措旨在增加对青年科学家的科研资助，以期缓解当前激烈的科研基金竞争压力。","scd":null,"kp":[]},{"i":38754,"as":"本文提出了一种界面渗流策略，成功在低锂含量下实现了高离子电导率，打破了固态电解质对高锂含量的传统依赖。以嵌入非晶基质中的Ta2O5纳米晶复合渗流固态电解质为例，研究证明绝缘分散体可以降低锂浓度并同时提高离子电导率。该策略不仅解决了全固态电池中无机固态电解质过度消耗锂的问题，还允许对电解质的高压稳定性等性能进行调控，提升了材料的电化学稳定性。","scd":null,"kp":[]},{"i":38755,"as":"本文通过定制具有笼状Mg2+溶剂化环境的电解质，开发出一种可充电的非水系镁氧（Mg-O2）电池。研究发现，通过改变醚溶剂链长并配合三齿螯合剂，可形成动态溶剂化微反应器。这种溶剂化环境不仅与阴极上纳米晶过氧化镁的可逆形成相一致，还能与镁阳极的可逆剥离和沉积保持兼容，有效克服了由于缺乏合适电解质和阴极不可逆反应导致的充放电性能障碍。","scd":null,"kp":[]},{"i":38756,"as":"本文展示了一种单片制造的、可电学寻址的准悬浮纳米光子孔径架构，克服了电学注入所需导电通道对强光物质相互作用光学环境产生干扰的物理限制。该结构采用由亚波长纳米柱阵列支撑的准悬浮光子晶体孔径，纳米柱精确位于连续域束缚态的电磁场节点处。这一配置在保持完整的半导体-空气折射率对比和光学腔对称性的同时，实现了跨越数百个晶胞的均匀载流子注入。","scd":null,"kp":[]},{"i":38757,"as":"本文利用玻色-爱因斯坦凝聚体中的量子物质波，从理论和实验上模拟并演示了非绝热非阿贝尔编织操作。在此框架下，有效的编织链由动量态编码，模拟的编织变换源自非绝热非阿贝尔和积。实验通过展示作用于物质波的不同序列和积操作，验证了非阿贝尔代数。这一成果克服了传统经典波模拟依赖绝热过程导致操作速度本质上较慢的缺陷，为实现拓扑量子门操作提供了新机制。","scd":null,"kp":[]},{"i":38758,"as":"本文提出了一种微环境解耦策略，通过将单原子Sn锚定在氨基功能化碳纳米管上，有效缓解了污染物聚合过程中的自抑制效应。氨基将锡稳定为Sn(II)-N4结构，通过形成双齿Sn-PDS复合物选择性地活化过硫酸盐（PDS），维持以电子转移为主导的路径。同时，碳纳米管表面富集酚类底物并促进其para-C-O聚合转移。结合光谱和密度泛函理论证实了Sn 5p与O 2p的相互作用是维持氧化还原平衡的关键。","scd":null,"kp":[]},{"i":38759,"as":"本文开发了一种柔性三维共价有机框架（FCOF-XJ），实现了热响应和氙气触发的开门效应，用于选择性捕集氙气。该材料由柔性和刚性四面体构建基块组装而成，其特有的-O-C-C-C-O-单键赋予其随温度变化的构象切换能力。其自适应孔隙结构在吸收氙气时发生开门效应，使氙气吸附量增加4倍，且在298K和1bar下表现出极高的氙氪选择性（36.9）。这一分离性能超越了绝大多数金属有机框架等多孔有机材料。","scd":null,"kp":[]},{"i":38760,"as":"本文展示了一种在强光物质耦合状态下运行的全溶液处理的有机微腔激光器。有机半导体因其激子结合能大和非线性强，是极化激元学的理想材料。针对以往有机极化激元激光器的光学腔通常依赖真空沉积、限制其低成本和规模化制造的问题，本研究采用全介电有机微腔结构。结合溶液处理的有机薄膜工艺，该器件成功在室温下实现了低阈值极化激元激光，为可扩展的有机光电子器件制造提供了新途径。","scd":null,"kp":[]},{"i":38761,"as":"本文通过固态电化学泵浦精确调控氧的非化学计量比，揭示了钛酸锶（SrFeO3-δ）薄膜拓扑相变中稳定中间态的存在。利用电压控制的离子插入技术，研究对材料的完全氧化和完全还原状态之间的中间氧化态进行了精细调节与量化。这种精细调控不仅揭示了多种中间相的共存，也为开发神经形态晶体管和智能显示器等自适应器件提供了一种强大的模拟调节材料特性的策略。","scd":null,"kp":[]},{"i":38762,"as":"本文在硅光子晶体平台中，利用热光非线性与非厄米简并度（即近奇异点简并）之间的相互作用，成功实现了三态光学存储器。这一机制为多级光存储器件的开发提供了新途径。","scd":null,"kp":[]},{"i":38763,"as":"本文深入研究了双极性膜中水分子解离的机制，发现表面羟基结构决定了水解离活性。以氧化锡量子线作为模型催化剂，实验表明，与桥接氧空位相关的羟基基团能促进质子转移，加速膜界面的碱性水解离过程。通过受控合成增加这类羟基结构的丰度，双极性膜实现了优异的跨膜水解离催化性能。该发现为提升电解水和燃料电池等可持续能源转换技术中的催化效率提供了理论指导。","scd":null,"kp":[]},{"i":38764,"as":"本文报道了一种熔融涂覆策略，利用金属有机框架玻璃对硬碳颗粒进行包覆，显著提升了钠离子电池的存储性能。该玻璃涂层内部含有的亚纳米通道降低了去溶剂化活化能，加速了钠离子输运，并在循环过程中诱导生成富含NaF的薄层阴离子衍生固态电解质界面。优化后的界面促进了准金属钠簇在硬碳闭合孔隙内的形成，激活了高容量储钠机制，从而有效解决了硬碳负极去溶剂化动力学迟缓及界面不稳定的问题。","scd":null,"kp":[]},{"i":38765,"as":"本文开发了一种由电解驱动的苯乙烯富集工艺，实现了从海水中直接高效提取溴。针对海水溴化物浓度极低（约60ppm）导致传统电化学方法无法直接提取的难题，研究筛选了一系列碳纳米管负载的金属酞菁作为电催化剂。实验表明，碳纳米管负载的镍酞菁通过加速溴演化反应并抑制副反应，展现出最高的催化活性。该技术结合苯乙烯富集过程，为保障地球溴资源的可持续供应提供了切实可行的新方法。","scd":null,"kp":[]},{"i":38766,"as":"本文开发了一种连续多相场模型，结合内部耗散和驱动细胞形状各向异性的主动偶极力，揭示了内部耗散在细胞单层自发形成孔隙中的关键作用。模拟表明，在软基底低摩擦状态下，细胞间的速度相关性增强。此时，拓扑缺陷会产生螺旋流模式并导致局部应力集中，从而自发触发细胞单层中孔隙的形成。这一发现克服了以往对单层细胞融合状态的固有认知，阐明了集体细胞运动引发组织形态变化的物理机制。","scd":null,"kp":[]},{"i":38767,"as":"本文开发了一种用于安全通信的多层加密DNA设备，成功将多种加密算法集成在单个DNA折纸工作流中。该编码系统利用矩形DNA纳米结构的空间可寻址性，将其转化为纳摩尔电码以构建空间图案。在基于密码本的对称加密框架内，通过共享密钥传输由纳摩尔电码加密的密文。此外，该系统还利用矩形与管状DNA纳米结构之间的形态转换，进一步拓展了加密层级，充分利用了DNA分子的大容量存储和纳米结构多样性优势。","scd":null,"kp":[]},{"i":38768,"as":"无阳极钠金属电池（AFSBs）因可逆钠损失导致容量快速衰减，限制了其实际应用。研究将集流体表面的d带中心（εd）确定为控制钠相关行为的统一电子结构描述符。测试和计算表明，εd与钠成核过电位之间存在火山型关系，处于中等εd值的材料展现出最佳性能。该发现为优化无阳极钠电池的钠沉积与稳定性提供了核心理论依据。","scd":null,"kp":[]},{"i":38769,"as":"血小板表面的Ero1α-蛋白质二硫键异构酶（PDI）系统对整合素激活和血小板聚集至关重要。研究通过高通量筛选，确定了Luminespib和AZ5104两种临床期化合物为该通路的特异性抑制剂。这两种化合物结合在PDI b'结构域的疏水口袋上，不影响其他PDI家族成员。在巨核细胞特异性Pdi或Ero1a敲除小鼠中，这两种药物的抗血小板作用完全消失，证实了它们通过靶向Ero1α-PDI互作发挥抗血栓作用。","scd":null,"kp":[]},{"i":38770,"as":"产生白细胞介素-17（IL-17）的γδT17细胞是引发自身免疫性炎症的关键。研究发现，芳香烃受体（AhR）在γδT17细胞激活时显著减少。AhR缺失会增强HSPA9与NICD的RAM结构域竞争结合，从而阻碍FBXW11依赖的NICD泛素化。这增加了NICD在Rorc增强子上的占有率，从而驱动γδT17细胞激活。而药理学激活AhR则可以抑制这一过程，缓解炎症。","scd":null,"kp":[]},{"i":38771,"as":"β-Zn4Sb3热电材料在电场下易发生严重的锌离子迁移导致相分解。研究采用粉末原子层沉积（pALD）技术，构建了氧化锌界面以同时抑制锌离子迁移和增强声子散射。100次循环的优化涂层成功固定了间隙锌离子，消除了锌运动并抑制了相分解，同时使晶格热导率降低了20%以上，有效稳定了材料的热电性能。","scd":null,"kp":[]},{"i":38772,"as":"为解决传统无电辐射制冷技术在冬季产生负面效应的问题，研究提出了一种动态蒸发与辐射制冷（DERC）装置。该装置能根据环境温度变化实现全年动态热管理，最大化炎热夏季的制冷功率。DERC设备具备动态调节水分蒸发的能力，并能对太阳光和热辐射进行显著调制，从而在四季地区实现高效的全年节能目标。","scd":null,"kp":[]},{"i":38773,"as":"研究通过综合分析122项研究中的2052个营养级传递效率（TTE）估算值，挑战了能量传递效率约为10%的传统生态学假设。结果显示，全球平均能量传递效率仅为5.92%，而平均营养物质传递效率为11.13%。在各类生态系统中，海洋生态系统的平均能量传递效率最高（8.13%），其次为淡水（5.53%）和陆地生态系统（1.52%）。","scd":null,"kp":[]},{"i":38774,"as":"针对印尼弗洛雷斯岛的弗洛里斯人，埋藏学分析表明其并未具备猎杀大型猎物和使用火的先进行为。对梁布亚遗址长鼻目动物骨骼化石的研究显示，科莫多巨蜥最先获取了这些猎物，仅留下低利用率的残骸供弗洛里斯人食用。此外，与弗洛里斯人相关的地层单元中并未发现故意用火的痕迹，澄清了对其行为和技术能力的认知。","scd":null,"kp":[]},{"i":38775,"as":"为揭示脊索动物大脑的基本蓝图，研究结合单核RNA测序和空间转录组学，构建了文昌鱼中枢神经系统三维细胞图谱。该图谱揭示了一个由喙侧视网膜/下丘脑区、间中脑区及尾侧后脑/脊髓组成的三元结构。研究还识别出类似于脊椎带状限界和后脑边界细胞的细胞簇，这为理解脊椎动物特异性大脑结构的演化提供了新视角。","scd":null,"kp":[]},{"i":38776,"as":"植物在胁迫下会产生损伤相关分子模式（DAMPs）激活防御。研究发现，植物激发肽前体PROPEP1会经历S-酰化修饰，这对于其定位至液泡膜及介导细胞壁损伤反应至关重要。S-酰化位点的突变会改变PROPEP1的运输途径，将其送入液泡腔降解。当细胞壁受损时，蛋白质S-酰转移酶的表达会精确调控这一过程，揭示了S-酰化控制植物多肽命运及防御机制的分子基础。","scd":null,"kp":[]},{"i":38777,"as":"研究发现Cyclin K是多种癌症的关键易感靶点。在肝细胞癌中，Cyclin K与CDK12形成复合物，通过结合转录共激活因子YAP形成调节性凝聚物，促使CDK12对YAP的第398位苏氨酸进行磷酸化。这种磷酸化阻碍了LATS激酶对YAP的抑制作用，稳定了YAP并促进其与TEAD4进一步凝聚，从而激活致癌基因程序，驱动肿瘤进展。","scd":null,"kp":[]},{"i":38778,"as":"通过综合分析146项研究，研究量化了热带湿润森林（TMF）在部分干扰后的地上碳（AGC）变化。部分人为干扰导致的即时碳损失中，森林火灾最严重（49%），其次为选择性砍伐（34%）和边缘效应（31%）。经过20年的恢复，退化森林的AGC储量恢复率达41%至117%，显著高于完全砍伐后次生林的1%至74%。干扰频率和强度的增加会显著加剧碳损失。","scd":null,"kp":[]},{"i":38779,"as":"为解决小麦淀粉颗粒尺寸的遗传调控机制不明问题，研究证实空间和底物限制是制约颗粒大小的关键。通过对小麦进行基因突变，即敲除质体分裂组分PARC6（增大淀粉质体尺寸和空间）并突变BGC1（减少颗粒启动数量从而降低竞争），成功减少了小颗粒的生成，为大幅增加A型大淀粉颗粒的尺寸提供了一种有效的基因工程方法。","scd":null,"kp":[]},{"i":38780,"as":"研究开发了一种基于深共晶溶剂（DES）电解质的新型级联电池。该电池协同整合了气相（Cl2 ↔ Cl−）、液相（Cu2+ ↔ Cu+）和固相（S ↔ CuS ↔ Cu2S）三相氧化还原反应，成功解锁了七电子转移过程。富氯DES电解质从根本上改变了铜的氧化还原热力学，实现了可逆的液相反应，突破了传统双电子电池的能量密度限制。","scd":null,"kp":[]},{"i":38781,"as":"针对星系团中长期存在的冷却流问题，研究运用MACER框架进行了理想化的流体动力学模拟。该模拟结合了射流和风，其物理属性受广义相对论磁流体动力学黑洞吸积模拟的严格约束。结果表明，这种联合反馈机制成功重现了冷气体质量、恒星形成率、热力学径向分布等关键观测数据，而单一射流或风模型均无法做到，证明了联合活动星系核反馈的有效性。","scd":null,"kp":[]},{"i":38782,"as":"研究揭示了一条植物中不依赖于ATR的DNA复制应激响应新通路。在复制应激期间，GSK3样激酶BIN2的活性被未知机制激活。随后，BIN2在T244和T249位点磷酸化SOG1蛋白，从而增强SOG1的稳定性和转录活性，激活DNA损伤反应（DDR）。这一分子模块的发现阐明了植物在应对基因组稳定性威胁时的动态调控机制。","scd":null,"kp":[]},{"i":38783,"as":"研究开发了一种依赖流速的多功能毛细管棘轮机制，用于精确控制手性微结构的单向旋转。在高流速条件下，界面流动与毛细管力相互作用可产生稳定的单向旋转。模拟显示，界面流依赖于驱动方向并产生迟滞效应。利用该物理原理，研究团队成功实现了扭矩的产生与微组装应用，克服了精确控制微观物体旋转的方法局限。","scd":null,"kp":[]},{"i":38784,"as":"研究发现陆地哺乳动物的嗅觉并非完全依赖节律性嗅闻。实验观察到，小鼠在觅食和进食时，能够以毫秒级的精准度将单次吸气与快速的头部和肢体动作同步。这种单一食物嗅闻与呼吸节律的突然重置有关，且会根据食物特性的不同而产生行为上的调整。嗅觉和运动回路操控实验证明，这种非节律性嗅闻依赖于运动皮层，而非反射性神经控制。","scd":null,"kp":[]},{"i":38785,"as":"研究揭示了丘脑底核（STN）中两种神经元亚群在调节左旋多巴诱发的运动障碍（LID）中的不同功能。投射至脚内核（EP）的STN神经元表现出U型激活模式，激活该群体可缓解运动障碍但会加重运动减少；而投射至被盖网状核的神经元主要表现为抑制反应，单独激活不会诱发多动症。这一发现阐明了STN脑深部刺激治疗帕金森病并发症的特定神经回路机制。","scd":null,"kp":[]},{"i":38786,"as":"通过果蝇肿瘤模型研究发现，脂肪体衍生的储存蛋白hexamerins通过选择性摄取过程在肿瘤中积累，并作为营养源支持肿瘤生长，其摄取受阻会显著减缓肿瘤增殖。此外，hexamerin的摄取还促进了肿瘤表达Dilp8蛋白，从而抑制蜕皮激素的产生并延长肿瘤的生长期，表明该蛋白同时促进了肿瘤的生长速度和持续时间。","scd":null,"kp":[]},{"i":38787,"as":"胰岛α细胞在代谢稳态中发挥关键作用。在小鼠模型中消融α细胞后，虽然在纯葡萄糖耐量测试中差异甚微，但在加入模拟膳食的氨基酸后，其葡萄糖耐受性显著下降。高密度微电极阵列分析表明，α细胞缺失导致大型细胞簇激活减少，削弱了胰岛内动态β细胞网络的功能。这证明了α细胞是维持氨基酸刺激下营养稳态不可或缺的调节者。","scd":null,"kp":[]},{"i":38788,"as":"无义介导的mRNA降解（NMD）是由提前终止密码子（PTC）触发的翻译偶联mRNA降解途径。针对PTC在转录位点（TS）的检测机制，研究人员采用实时成像技术，在同一细胞内检测表达野生型或NMD靶向β-珠蛋白报告基因的TS。数据表明，含PTC的β-珠蛋白mRNA转录过程发生动态变化，且该变化依赖于翻译、NMD以及核蛋白输入过程。","scd":null,"kp":[]},{"i":38789,"as":"为探究甲状腺癌淋巴结（LN）转移的决定因素，研究人员对原发甲状腺肿瘤和匹配的转移性淋巴结中的肿瘤浸润白细胞进行了单细胞RNA测序。对比发现，在淋巴结定植后，甲状腺细胞和肿瘤相关巨噬细胞会下调多种炎性细胞因子受体（如TNFRSF12A和CX3CR1）的表达。此外，淋巴结中观察到调节性T细胞的诱导现象，揭示了肿瘤免疫相关的微环境改变。","scd":null,"kp":[]},{"i":38790,"as":"在发育过程中，自发声带活动通过皮层内通路激活发育中的听觉皮层（ACtx）。在新生小鼠幼崽中进行的活体成像显示，在耳道打开前，小鼠已存在与自发声带相关的ACtx活动，且该活动强于纯音诱发活动。在耳聋幼鼠中同样存在该活动，表明其源自自上而下的活动机制。前扣带皮层（ACC）和次级运动皮层（M2）向ACtx发出投射，且ACC/M2的失活会减少自发声和ACtx活动。","scd":null,"kp":[]},{"i":38791,"as":"西北太平洋（NWP）海洋热浪的跨季度持续时间主要受5波数的准静止环行星波（CGW）模式驱动，且该过程独立于厄尔尼诺-南方涛动现象。CGW通过调节夏季表面热通量，触发自强化反馈循环，使NWP变暖加剧CGW模式，从而延长热浪。此外，北北大西洋的夏季变暖通过海洋热惯性持续至冬季，激发大圆波传播路径，进一步延长海洋热浪。","scd":null,"kp":[]},{"i":38792,"as":"表达P物质（SP）受体和神经元一氧化氮合酶的Tacr1神经元对脑血流量（CBF）起着显著的调节作用。双光子成像显示，Tacr1神经元通过释放一氧化氮（NO）和SP受体信号通路调节CBF，星形胶质细胞的钙离子瞬变是血管舒张的次级反应。病毒映射表明，体感皮层中的局部Tac1阳性神经元是SP的潜在来源，并投射至Tacr1神经元，证实该机制是皮层神经血管耦合的关键组成部分。","scd":null,"kp":[]},{"i":38793,"as":"高熵合金设计能有效降低热导率，但往往会降低载流子迁移率。研究证明，在半赫斯勒合金中系统增加构型熵会导致晶格热导率的渐近降低。由原子级化学无序引起的声子群速度降低和声子散射增强，使室温下晶格热导率降至2 W/(m·K)，随着时间推移可达到约1.48 W/(m·K)的最低值。该发现为提升热电性能提供了关键依据。","scd":null,"kp":[]},{"i":38794,"as":"创伤性脑损伤（TBI）后血脑屏障（BBB）被破坏，而星形胶质细胞中的肌营养不良蛋白71（Dp71）在患者和小鼠模型中表达下降。小鼠实验表明，下调星形胶质细胞Dp71可减轻继发性BBB破坏，并减少星形胶质细胞活化、炎症细胞浸润及基质金属蛋白酶-2（MMP2）释放。机制上，核内Dp71与WTAP蛋白相互作用并影响其泛素化，进而通过WTAP相关的m6A修饰调控MMP2表达。","scd":null,"kp":[]},{"i":38795,"as":"与多数哺乳动物快速反复嗅闻不同，人类通常通过单次长嗅来采样气味。针对缺乏快速嗅闻节奏下人类气味反应的组织方式，研究利用高精度神经记录发现，嗅闻的启动会引发并时间对齐人类嗅球中的西塔（theta）频段振荡。这表明人类嗅球利用西塔范围的神经振荡来设定气味编码的节奏，西塔振荡构成了人类嗅觉处理的基本组织单位。","scd":null,"kp":[]},{"i":38796,"as":"利用X射线微型计算机断层扫描技术发现，温带低地森林中山毛榉的晚材密度测量值表现出强烈的夏温信号（1833-2022年间相关系数r=0.73）。基于深度学习分割的木材解剖分析显示，导管和纤维解剖结构是晚材密度温度敏感性的关键驱动因素。结合这些解剖学响应，基于X射线micro-CT的晚材密度可作为一种可靠的夏季温度代用指标。","scd":null,"kp":[]},{"i":38797,"as":"蜱传脑炎病毒（TBEV）的许多颗粒呈非对称结构，且缺乏部分表面杂二聚体。未成熟TBEV颗粒含有不完整的刺突，证明其包膜蛋白直接由膜前体和包膜蛋白的杂二聚体组装而成。在戈尔基体中暴露于酸性pH值后，TBEV成熟中间体中的刺突和人字纹区域呈现随机取向，而非符合常见的二十面体对称性。成熟的人字纹晶格围绕随机取向的成核中心形成并扩展。","scd":null,"kp":[]},{"i":38798,"as":"高分辨率实时触觉传感对于执行复杂任务的机器人至关重要。现有触觉传感技术在空间分辨率和响应速度之间存在固有权衡：基于触点的传感器分辨率受限于尺寸和串扰，难以突破1毫米；而基于视觉的传感器虽能达到更精细的分辨率，但将原始图像转换为三维接触信息所需的庞大计算量严重限制了响应速度。该研究指出了打破这一技术瓶颈的迫切需求。","scd":null,"kp":[]},{"i":38799,"as":"甲状腺嗜酸细胞癌（OCT）表现为广泛的杂合性缺失（LOH）和复发性线粒体DNA突变。新建立的OCT细胞系UT946表现出严重的线粒体电子传递链功能障碍和瓦伯格代谢表型。研究证实，UT946中复合物I的缺陷源于复合物I亚基NDUFS1的核编码功能丧失突变。NDUFS1突变作为一种隐性胚系等位基因被遗传，并在肿瘤中通过LOH暴露出来。对91例OCT肿瘤基因组的重新分析证实了LOH在其中的驱动作用。","scd":null,"kp":[]},{"i":38800,"as":"RNA去甲基化酶FTO是驱动非小细胞肺癌（NSCLC）细胞胱氨酸代谢的治疗靶点。抑制FTO可减少胱氨酸摄取和转硫化作用，导致细胞内谷胱甘肽耗竭、活性氧（ROS）升高，并引发DNA损伤和细胞凋亡。机制上，FTO通过促进胱氨酸摄取转运蛋白SLC7A11及转硫酶CBS和CTH的表达，维持NSCLC的生存。该FTO/SLC7A11/CBS/CTH轴为NSCLC提供了新的治疗策略。","scd":null,"kp":[]},{"i":38801,"as":"通过对铁器时代欧亚草原游牧民族（包括塞西安“黄金人”）的85个个体（38个精英和47个非精英）进行古DNA全基因组分析，揭示了社会地位对生物血缘和 ancestry 模式的影响。研究发现精英群体中存在近亲结合、有效种群规模减小以及共同祖先认同。跨墓地的祖孙关系证实了精英阶层的王朝统治，表明尽管血统来源具有异质性，但精英阶层的遗传连续性更强。","scd":null,"kp":[]},{"i":38802,"as":"基于机械剥离的二硒化钨场效应晶体管，研究提出了一种坚固的光电突触器件。该器件无需复杂异质结构，利用本征缺陷介导的电荷捕获机制实现神经形态功能。通过光刺激产生持久光电导实现电导增强，结合电刺激实现了突触权重的可逆调控。该器件成功模拟了巴甫洛夫条件反射，为下一代神经形态计算和人工视觉系统提供了高效解决方案。","scd":null,"kp":[]},{"i":38803,"as":"利用表面活性剂模板法合成了负载于介孔二氧化硅中的镁稳定钴单原子催化剂（600CoMg/MS）。该策略实现了5.97 wt%的高钴负载量和457.359 m²/g的高比表面积，硅酸镁在稳定Co-O键方面发挥关键作用。在活化过硫酸盐（PMS）降解5-氟尿嘧啶的实验中，600CoMg/MS在30分钟内去除率超过97%，并在多次循环后仍保持95%的高去除率，表现出优异的催化性能。","scd":null,"kp":[]},{"i":38804,"as":"将DNAzyme与CRISPR/Cas系统结合易导致操作繁琐。本研究开发了一种由RNA触发的DNAzyme电路，并将其与CRISPR/Cas12a整合，作为通用的核酸预放大器，实现了均相单管检测。目标分析物的识别能恢复最初被抑制的DNAzyme催化活性，进而切割发夹状底物，释放出多个激活子。该级联放大系统为简单、特异性且高灵敏度的等温RNA诊断提供了创新平台。","scd":null,"kp":[]},{"i":38805,"as":"研究设计了一种受创可贴启发、免缝合的压电神经修复膜，用于修复复杂周围神经缺损。该Janus膜通过静电纺丝制备，内层为甲基丙烯酰明胶和单宁酸制成的定向黏合水凝胶纤维，可适应不同神经直径；外层为压电丝素蛋白纤维，提供物理屏障和支撑。体内实验证实，该压电薄膜能够有效促进复杂神经结构的形态恢复与功能重建。","scd":null,"kp":[]},{"i":38806,"as":"将金属有机框架与高内相乳液聚合物泡沫结合，制备了用于反应过滤的复合材料。研究以UiO-66-NH2为填料，通过一锅法合成了polyHIPE复合物。实验探究了不同MOF负载量对聚合物基体的影响，揭示了该复合大孔结构在有毒化学气体和蒸汽吸附及反应消除中的协同机制，为MOF粉末成型及在有毒化学物质过滤中的实际应用提供了有效途径。","scd":null,"kp":[]},{"i":38807,"as":"针对水凝胶智能窗户耐候性和加工性差的局限，研究开发了一种由丙烯酸丁酯（BA）和双离子液体（ILs）组成的 thermochromic（热致变色）离子凝胶墨水。该前驱体可紫外快速固化，适配3D打印、涂层及卷对卷工艺，支持定制化图案和大规模生产。聚合物基体内富IL微区的温度驱动动态分布，赋予材料卓越的太阳光调节能力和可调的低临界溶解温度，有效提升了智能窗户的综合性能。","scd":null,"kp":[]},{"i":38808,"as":"该研究开发了一种由丙烯酸丁酯（BA）和二元离子液体组成的变色离子凝胶油墨，专门用于解决智能窗户薄膜的耐候性和加工性瓶颈。该前驱体可通过紫外光快速固化，适用于3D打印和卷对卷固化等大规模工业生产。聚合物基质中富离子微区的动态分布赋予了材料卓越的太阳光调节能力和可调谐的低临界溶液温度。","scd":null,"kp":[]},{"i":38809,"as":"该研究提出了一种基于核磁共振（NMR）的19F凝集素标记方法，用于探测复杂的聚糖介导结合过程。细胞表面的聚糖-凝集素相互作用在分子水平上难以表征，且不同凝集素对广泛分布的聚糖表位具有重叠的选择性和亲和力。通过引入19F探针，该方法能够探究凝集素在纯化糖蛋白和细胞表面聚糖水平的竞争与选择性识别机制。","scd":null,"kp":[]},{"i":38810,"as":"该研究提出了一种弛豫匹配框架，结合中间散射函数和退相关时间分辨范霍夫分析，用于探究石榴石固态电解质中的锂离子动力学。离子电导率受迁移势垒、跃迁频率和扩散长度尺度的共同影响。该框架揭示了空间和时间相关性如何调控离子输运，为理解原态和镓掺杂的Li7La3Zr2O12等材料中的超离子传导机制提供了新视角。","scd":null,"kp":[]},{"i":38811,"as":"该研究报道了一种基于可转化金属有机框架（MOF）纳米平台的双功能光催化策略。通过微波辅助原子级工程制备了Pt1/In2O3/UiO-66-NH2纳米复合材料，其具有原子级分散的铂位点。该结构在可见光下实现了高效的产氢反应，速率达2749.6 μmol g–1 h–1，析氢吸附能为-0.39 eV，并能可控实现包括二氧化碳还原在内的两条不同太阳能燃料生产路径。","scd":null,"kp":[]},{"i":38812,"as":"研究通过引入Azulyne（薁块）中间体，成功实现了Azulene（薁）的选择性官能化。 computations表明5,6-和4,5-Azulyne具有适度的环张力和显著的亲电性。基于这些中间体，研究人员开发了一个模块化平台，能够将多种官能团直接、高效且具位点选择性地引入到Azulene缺电子的七元环上，突破了以往缺乏通用合成方法的局限。","scd":null,"kp":[]},{"i":38813,"as":"该研究首次实现了简单未活化芳烃的分子间脱芳1,4-加成反应。通过使用易变的碘占位基团阻断内球还原消除，并结合铬/钼的η6-配位，成功克服了传统的1,2-区域选择性偏好。该反应利用双亲核试剂，实现了脱芳1,4-双烷基化和1,4-氢烷基化，具有极广的芳烃底物适用范围和优异的官能团耐受性，可直接合成1,4-环己二烯衍生物。","scd":null,"kp":[]},{"i":38814,"as":"该研究开发了一种具有限制性钌（Ru）物种的层状MEL沸石催化剂，用于将聚乙烯定量转化为液态烯烃。在270°C下反应4小时，优化的Ru@MEL催化剂实现了大于99%的聚乙烯转化率，以及对C5-C9烯烃高达92%的选择性。Ru的引入促进了骨架铝在结晶过程中向MEL沸石直通道的迁移，有效解决了底物转化率与产品选择性之间的平衡难题。","scd":null,"kp":[]},{"i":38815,"as":"利用原位拉曼光谱结合X射线和SEM表征，该研究揭示了锂介导的氮还原反应中固态电解质界面（SEI）的动态演化过程。反应过程中，SEI的成分由溶剂衍生的有机物逐渐转变为含锂盐的无机物。研究发现，乙醇通过调节LiF和LiBO2化合物的含量，关键性地控制着SEI的化学组成和物理形态。这阐明了质子供体在Li-NRR过程中的具体作用。","scd":null,"kp":[]},{"i":38816,"as":"研究利用高压拉曼光谱、光吸收测量和第一性原理计算，在范德华层状铁电体CuInP2S6中发现了压力诱导的级联相变。电学输运测量表明，在超过58 GPa时该材料出现超导性。随着压力增加，超导转变温度（Tc）在215 GPa时达到15 K，创下MPX3家族中最高Tc纪录。其高Tc源于动态载流子耦合的独特配对机制。","scd":null,"kp":[]},{"i":38817,"as":"该研究通过结合连续的Pinner反应和席夫碱反应这一不可逆级联反应，成功构建了恶嗪锁定的二维共价有机框架。该设计将框架结晶与永久性连接键的形成相结合，赋予了COFs在酸碱条件下的高化学稳定性。这些框架被证明可作为高效的光催化剂用于生成过氧化氢（H2O2），为人工光合作用提供了稳定COF基光催化剂的通用合成路线。","scd":null,"kp":[]},{"i":38818,"as":"该研究报道了一种由镍介导的（杂）芳烃18F,D2-单氟甲基化反应。与传统基于SN2反应的放射化学不同，新方法具有前体稳定性高、无需定制前体合成、官能团耐受性广等优势。它能够在单步反应中实现氘和氟-18的晚期引入。该协议已成功应用于30多种底物（包括复杂生物活性分子），并可通过半自动化平台进行放大生产，分离出了18F,D2标记的PARP放射性示踪剂。","scd":null,"kp":[]},{"i":38819,"as":"研究揭示了反温度结晶（ITC）过程中甲脒铅碘（FAPbI3）发生溶剂依赖性重新溶解的机制。虽然γ-丁内酯（GBL）和2-甲氧基乙醇（2ME）混合溶剂有利于α-FAPbI3在环境条件下生长，但FAPbI3会促进这两种溶剂发生酯化反应，改变配位环境并破坏钙钛矿的稳定性。研究发现，碘化铅（PbI2）的缺乏可以有效延迟重溶过程，减少δ-FAPbI3的形成并提高稳定性。","scd":null,"kp":[]},{"i":38820,"as":"该研究提出了一种通过空间位阻受限的表面配位策略，来增强钙钛矿量子点（PQD）固体的手性诱导和晶格不对称性。采用基板上直接合成法构建了具有专属手性配体覆盖的CsPbBr3手性PQD薄膜。密度泛函理论计算表明，决定PQD表面不对称相互作用强度的是配体几何构型而非配体密度。这使得CPQD薄膜展现出显著增强的手性光学特性。","scd":null,"kp":[]},{"i":38821,"as":"该研究通过将氨基功能化金属有机框架与亚稳态光酸共组装，实现了光驱动的高效二氧化碳捕获与可逆释放。在3分钟的光照下，优化系统每个循环可从烟气中按每毫摩尔光酸释放12毫升CO2，并在5分钟暗场期间恢复其CO2捕获能力。这种利用光子能量在温和条件下调节酸度的系统，通过U型连续流原型机进一步验证了其实用性，大幅降低了吸附剂再生的能耗。","scd":null,"kp":[]},{"i":38822,"as":"该研究报道了三种基于茚并芴的氯代紫凝盐阳离子的合成。它们与Et3SiH反应展现出不同路径，生成了中性的砷二氢化物、阳离子的锑氢化物以及三核铋双阳离子。阳离子4与三甲基铟、镓及二苯基二硫属化物反应，生成含有Sb-E双键的产物。铋双阳离子7表现出显著的2电子-3中心键特征。阳离子4表现出类似质子化锑烯的性质。","scd":null,"kp":[]},{"i":38823,"as":"该研究报道了一种由手性配体调节的镍催化立体选择性自由基迁移交叉偶联反应，实现了碳水化合物非异头碳位置的C2芳基化。研究采用一类未被充分探索的手性2-(氨甲基)吡啶配体，在镍催化中实现催化剂调制的立体控制。该反应广泛兼容各种芳基硼酸和碳水化合物底物，耐受多种复杂分子结构，适用于克级规模合成，突破了糖类非异头碳位置碳-碳键形成的难题。","scd":null,"kp":[]},{"i":38824,"as":"硫化物基全固态锂金属电池因具有媲美液态电解质的高离子电导率和高容量，成为下一代高能量密度储能（目标400 Wh/kg）的首选。然而，其实际应用受到界面不稳定性、机械脆性等因素的限制。实现高能量密度不仅需要先进的活性材料，还需要从材料界面到电极制造和电池集成整个链条的多尺度协同设计和精密制造，以解决其失效机制。","scd":null,"kp":[]},{"i":38825,"as":"该研究通过在共价有机框架的连接体中引入乙炔基和二乙炔基，合成了TpEDD-COF和TpBDD-COF两种β-酮烯胺COFs。实验和密度泛函理论计算表明，炔基的引入提高了骨架的平面性，显著放大了COFs内的π电子离域。这使得材料的光电性能得到提升（顺序为TpBDD-COF > TpEDD-COF > TpBD-COF），从而显著增强了可见光光催化中氧气的活化能力，实现了高选择性光催化。","scd":null,"kp":[]},{"i":38826,"as":"该研究通过化学共沉淀法合成了从二元到四元的等摩尔多组分稀土磷酸盐（REPO4），并在1500°C下进行放电等离子烧结。表征结果显示，所有REPO4的热膨胀系数均接近碳化硅陶瓷基复合材料。热导率依赖于阳离子尺寸无序度和成分复杂性，在成分元素数量恒定时，阳离子尺寸无序度的增加会降低热导率。研究系统评估了其作为环境障碍涂层抗钙镁铝硅酸盐腐蚀的性能。","scd":null,"kp":[]},{"i":38827,"as":"基于构建的荷斯坦牛泛基因组，研究对1571头牛的93,059个结构变异进行了基因分型，并开发了名为HolPIP的变异插补参考面板。利用HolPIP，对50,299头公牛进行了结构变异插补。结合43种复杂表型进行全基因组关联分析（GWAS），识别出1225个变异-性状关联，并通过精细定位筛选出32个高置信度候选结构变异，实现了大规模基因型-表型研究。","scd":null,"kp":[]},{"i":38828,"as":"为解决3D医学图像中血管分割耗时且精度低的问题，该研究组织了一场全球机器学习竞赛，旨在促进Hierarchical Phase-Contrast Tomography (HiP-CT)数据集中3D血管分割的深度学习方法。对顶尖方案的荟萃分析揭示了趋同的方法创新，包括利用数据分布的伪标记方法，以及针对连通性和拓扑结构设计的新型度量指标和损失函数。","scd":null,"kp":[]},{"i":38829,"as":"研究揭示了内质网到高尔基体的COPII囊泡运输受脂质代谢的转录调控。这一过程依赖于磷脂酸相关的Opi1-Ino2/Ino4调控回路。其中，靶基因YIP3对COPII囊泡运输起负调控作用。具体机制表明，Ino2/Ino4调节COPII囊泡形成初始步骤的Sar1激活，而Yip3则阻碍该过程。","scd":null,"kp":[]},{"i":38830,"as":"研究利用冷冻电镜技术解析了大肠杆菌中Wza-Wzc复合物的两种功能状态（野生型自磷酸化与K540M非磷酸化突变体）结构。结构显示，Wza和Wzc组装成跨越整个细菌被膜的连续通道，为理解革兰氏阴性菌中通过Wzx/Wzy依赖途径组装和转运colanic acid的分子基础及调控机制提供了关键架构信息。","scd":null,"kp":[]},{"i":38831,"as":"通过对侵袭性骨肉瘤进行空间转录组学分析，研究在高度肿瘤异质性中确定了一个包含9个基因的细胞表面特征签名，该签名具有诊疗潜力并分布于不同肿瘤区域。肿瘤免疫微环境分析揭示了系统性淋巴排斥、差异化髓系浸润模式以及I型干扰素反应特征，这些机制解释了干扰素治疗的失败原因。","scd":null,"kp":[]},{"i":38832,"as":"研究利用源自硫化叶菌的pRN1质粒DNA引物酶探究引物合成起始机制。核磁共振和建模结果显示，辅助结构域同时结合DNA模板与两个起始核苷酸。起始过程中仅有第二个核苷酸与模板配对，第一个核苷酸保持未配对状态，引发模板碱基翻转和连接体相互作用，促使第二个核苷酸发生位移，从而完成二核苷酸的形成。","scd":null,"kp":[]},{"i":38833,"as":"对D. catenulata酵母的基因组分析揭示了其显著的染色体不稳定性，这与两种DNA转座子（Dici1和Dici2）广泛存在密切相关。实验证实这两种转座子在实验室条件下仍具活性并发生转移。其中标准菌株含有高达96个Dici1拷贝。高序列保守性表明，近期且持续的转座爆发正在重塑该物种的基因组。","scd":null,"kp":[]},{"i":38834,"as":"在青藏高原冰川退缩区130年序列的多组学研究中，发现冰川退缩重塑了病毒和微生物群落。编码氧化型异化亚硫酸盐还原酶操纵子的硫氧化细菌在退缩后前1-5年内特异性富集。相关病毒主要采用“搭便车”策略促进这些细菌增殖，这种病毒介导的机制驱动了早期演替过程中的有机碳汇形成。","scd":null,"kp":[]},{"i":38835,"as":"高温高压实验表明，在俯冲板片约2 wt%水含量条件下，含水矿物在地幔过渡带逐渐脱水并将水转移至瓦兹利石和尖晶橄榄石等名义无水矿物中，而冷板片核心保持干燥。下地幔顶部附近的快速脱水产生流体，与最深层地震相关。中源地震主要由干燥橄榄石相变引起，而非脱水脆化。","scd":null,"kp":[]},{"i":38836,"as":"卫星植被指标分析显示，2001至2024年间全球半干旱地区56.6%植被区的滞后一阶时间自相关呈上升趋势，表明植被恢复力正在下降。47.5%的植被区在绿化的同时表现出恢复力减弱。加剧的热浪进一步放大了这种临界减慢效应，凸显了极端气候对半干旱生态系统恢复力的显著负面影响。","scd":null,"kp":[]},{"i":38837,"as":"受自然界结构材料启发，综述探讨了通过界面调节驱动聚合物纳米复合材料增韧的机制。在纳米界面上，聚合物链展现出与体相截然不同的断裂力学特性，这是抵抗弯曲变形并实现增韧的核心决定因素。文章评估了将界面调节作为激活多尺度增韧关键机制的策略，以此打破合成材料强度与韧性难以兼得的瓶颈，推进规模化制造。","scd":null,"kp":[]},{"i":38838,"as":"研究提出一种利用g-C3N4/SrTiO3双异质结的挠电催化技术，通过氧还原路径高效生产过氧化氢（H2O2）。该纳米复合材料通过水热合成结合机械混合与煅烧制备。优化的异质结克服了机械化学能量转化率低和活性位点不足的局限，将H2O2的生成率显著提升至645.1 μmol·g⁻¹·h⁻¹。","scd":null,"kp":[]},{"i":38839,"as":"为解决紫外纳米压印光刻（UV-NIL）传统光刻胶体积收缩大、耐热性差和氧抑制严重等缺陷，研究设计了具有可调分支结构的Vi-T系列硅氧烷基硫醇-烯光刻胶。研究阐明了化学计量比和拓扑结构调控光聚合动力学、流变行为和图案保真度的双重机制。通过精确优化非化学计量比，有效提升了光刻胶的图案精度与整体性能。","scd":null,"kp":[]},{"i":38840,"as":"研究探讨了在准单组分混合物中利用有机自由基作为敏化剂及其闭环氢化类似物作为湮灭剂实现光化学上转换的机制。在单一分子（TTM-1Cz-DPA）中结合了三苯基甲基自由基光学跃迁和蒽基成分的三重态。闭环对应物中仅一个氢原子的差异使其切换为湮灭剂，有效介导上转换过程，规避了传统闭环敏化剂中单重态-三重态系间窜越造成的能量损失。","scd":null,"kp":[]},{"i":38841,"as":"藻胆蛋白PC645是隐藻光合膜腔内的闭壳聚光复合物。光合作用引发腔内pH值大幅下降，研究使用高效密度泛函紧束缚框架进行多尺度模拟，发现pH依赖的振动动力学会引发PC645复合物的激发态猝灭。这一机制解释了类囊体腔内质子浓度变化如何调节外围天线复合物的激发能传递与光捕获效率。","scd":null,"kp":[]},{"i":38842,"as":"研究开发了一种基于氢键介导的原位聚合方法，通过LiTFSI与磷酸锆层间结晶水形成氢键促进质子转移提升酸性，实现了聚1,3-二氧戊环（PDOL）的可控聚合。PDOL-ZP固态电解质因具备均匀长链大分子结构，电压窗口高达5.0V，有效解决了传统路易斯酸催化法难以适应高压正极的瓶颈，大幅提升了固态锂电池的性能。","scd":null,"kp":[]},{"i":38843,"as":"针对碘化物钙钛矿胶体量子 dots合成过程中的尺寸分布宽化问题，研究提出了一种前驱体扩散控制的克级规模合成策略。通过配体介导调节延缓单体形成并抑制连续成核，成功分离结晶阶段，无需合成后尺寸筛选即可获得高单分散性的CsPbI3量子点。该策略已扩展至甲脒的掺入，可直接应用于光伏材料制备。","scd":null,"kp":[]},{"i":38844,"as":"超材料通常依赖规则结构以保持可控性，而该研究提出结合几何与物理学的网络理论是建模和设计具有可控不规则性的超材料网络的理想框架。通过机器学习与自组装技术支持，引入工程化不规则网络结构能够为超材料带来增强或全新的物理特性，同时也推动了广义物理网络领域的研究方向拓展。","scd":null,"kp":[]},{"i":38845,"as":"研究发现，ATM激酶缺乏细胞中BRCA1-A复合物会限制依赖复制叉反转的DNA修复。ATM抑制会触发SUMO和泛素介导的BRCA1-A识别受损复制叉，限制末端切除并导致拓扑异构酶I抑制剂高度敏感。当BRCA1-A缺乏时，受损复制叉处的染色质可及性和核酸酶活性升高，末端切除恢复并产生耐药性。","scd":null,"kp":[]},{"i":38846,"as":"研究解析了黏液性结直肠腺癌（MUC CRC）的顶底极性调控机制。单细胞分析表明，肿瘤-基质间的胶原蛋白与α2β1整合素相互作用激活Src并上调内体分拣受体SorLA。SorLA通过促进整合素回收和HER2/HER3表达来维持向顶极性。临床样本显示HER2、HER3与SorLA表达呈正相关，阐明了影响MUC CRC转移的极性调节网络。","scd":null,"kp":[]},{"i":38847,"as":"准确评估抗菌药耐药性（AMR）感染的负担对于制定公共卫生政策至关重要。文章指出传统估算高度依赖模型假设，存在多重分析挑战。为此，作者建议引入明确的因果推断视角来优化评估方法，改进从单项研究整合至区域及国家层面AMR负担估算的过程，从而提供更具政策参考价值的流行病学数据。","scd":null,"kp":[]},{"i":38848,"as":"针对传统差异甲基化区域（DMR）检测方法依赖预定义样本条件且难以跨多条件比较的局限，研究开发了metilene3算法。该方法支持在监督和无监督模式下快速进行多条件DMR检测。通过根据多重成对甲基化差异信号对基因组进行分割，metilene3能够在临床样本标签未知或不确定的情况下自主聚类，有效发现全新表观遗传模式。","scd":null,"kp":[]},{"i":38849,"as":"该研究提出了一种量化脑维持的通用指标，通过潜在生长曲线模型联合建模衰老相关脑萎缩（通过内侧颞叶与脑室比率MTLV-ratio）、白质高信号（WMH）和总体认知（通过PACC5评估）的纵向演变。在543名认知未受损的老年队列中验证，结果显示MTLV-ratio和WMH的变化可加性地预测认知变化。此外，较高的神经质、抑郁症状、较低的开放性以及较快的特征变化与该指标相关。","scd":null,"kp":[]},{"i":38850,"as":"为解决传统测序技术难以全面表征遗传性肌病复杂基因变异的问题，研究人员开发了一种靶向长读长测序测定法及生物信息学分析框架。该技术能够捕获目前已知与遗传性肌病相关的所有基因、变异（涵盖小序列变异、结构变异、重复扩增等）和表观遗传特征。在患者队列中的应用证实了该方法的分析有效性，并在准确率上取得了显著提升。","scd":null,"kp":[]},{"i":38851,"as":"针对结直肠癌微环境中的免疫抑制，研究人员将谷氨酰胺拮抗剂DON与青蒿素靶向部分偶联，开发了新化合物WGF-T17（T17）。T17能够阻断巨噬细胞中的谷氨酰胺代谢，促使其代谢转向糖酵解，诱导乳酸积累和组蛋白乳酸化，增强线粒体分裂和吞噬活性，从而将巨噬细胞重编程为炎症状态。体内实验表明，T17通过巨噬细胞靶向作用，在控制肿瘤生长方面优于前药JHU-083。","scd":null,"kp":[]},{"i":38852,"as":"研究解析了非洲马瘟病毒（AHSV）4型全长VP2蛋白的3.11埃分辨率冷冻电镜结构，揭示了其天然三柱结构及其他环状病毒缺乏的α螺旋结构域。基于结构指导的图谱分析，鉴定出VP2的一个亚基是中和抗体的关键靶点。利用SpyCatcher/SpyTag技术将该结构域展示在纳米颗粒上作为疫苗，能够为机体提供完全的保护。","scd":null,"kp":[]},{"i":38853,"as":"单核细胞和巨噬细胞表达CSF1R受体，调节细胞的分化和代谢。研究发现，急性阻断CSF1R或其基因缺失会干扰单核细胞的细胞内代谢，并通过抑制经典单核细胞向非经典单核细胞的分化，导致血液中非经典单核细胞数量减少。这揭示了CSF1R在单核细胞亚群分化和细胞内谷氨酰胺-果糖-6-磷酸氨基转移酶代谢途径中的重要调节作用。","scd":null,"kp":[]},{"i":38854,"as":"研究在拟南芥中鉴定出BEL1-LIKE HOMEODOMAIN转录因子BLH1是植物热形态建成的关键负调节因子。BLH1调节BZR1-PIF4热形态建成模块，其过表达可使植物对高温不敏感，而突变体则表现出高度敏感。BLH1的表达受到BZR1的直接抑制，并会被高温下调。BLH1直接结合特定靶点，揭示了BZR1-BLH1-PIF4反馈模块作为分子放大器在精确热形态建成中的作用。","scd":null,"kp":[]},{"i":38855,"as":"研究揭示了锌指蛋白689（ZNF689）在三阴性乳腺癌（TNBC）中调节同源重组（HR）修复的关键作用。响应DNA损伤时，ZNF689被ATM磷酸化，并通过E3连接酶SKP2促进NBS1泛素化，稳定MRN复合物并激活ATM，从而促进HR修复。ZNF689缺失会显著增强TNBC对PARP抑制剂的敏感性，特别是与PD-L1抑制剂联合使用时效果更佳。","scd":null,"kp":[]},{"i":38856,"as":"研究调查了小分子剪接调节剂（如Risdiplam和Branaplam）的分子特异性基础。Risdiplam优先诱导3'端具有N-3G-2A-1序列的外显子，而Branaplam偏向A-3G-2A-1结尾的外显子。利用生化实验、转录组分析和遗传扰动，研究人员鉴定出依赖于序列的特异性决定因素，阐明了剪接调节剂发挥作用的特定外显子靶标空间及分子机制。","scd":null,"kp":[]},{"i":38857,"as":"利用谱系追踪、单细胞转录组和表观基因组分析发现，小鼠毛囊间表皮很大程度上由间充质谱系细胞组成。小鼠胚胎的谱系追踪和活体成像表明，这些间充质谱系表皮祖细胞源自外胚间充质，通过间充质向上皮的转化过程（MET）参与表面外胚层的形成。研究证实了间充质细胞在生理正常状态下对角质形成细胞形成的贡献。","scd":null,"kp":[]},{"i":38858,"as":"研究采用实验与理论相结合的方法，通过记录两只猕猴在熟悉度学习过程中的下颞叶（IT）皮层活动，发现了跨越数分钟至数天的两种不同时间尺度的学习相关变化。在跨阶段学习中，平均反应随着熟悉度增加而逐渐降低，这与突触可塑性一致；而快速学习则表现出不同的细胞机制。这表明灵长类下颞叶皮层中快慢时间尺度的视觉学习由截然不同的可塑性规则驱动。","scd":null,"kp":[]},{"i":38859,"as":"研究引入了基于序列归因的成对影响（PISA）方法，能够组合解码特定基因组坐标下的碱基对读数的贡献。PISA可以可视化转录因子基序的影响，发现具有复杂贡献模式的新基序，并揭示实验偏差。通过学习MNase-seq的偏差，PISA实现了前所未有的核小体预测模型，从而深入解释了顺式调控密码和核小体组织。","scd":null,"kp":[]},{"i":38860,"as":"通过分析全球845种动植物物种的分布边缘位移记录，研究探讨了海拔变化如何依赖于地理区域、气候生态位、全球普遍性和进化史。结果发现，这些驱动因素对上下分布极限有不同影响。热带物种下边缘向上移动的速度比温带物种更快；具有温暖潮湿气候生态位的物种表现出更快的上边缘位移。研究揭示了物种分布对气候变化的生态与进化响应机制。","scd":null,"kp":[]},{"i":38861,"as":"海马体重放与记忆功能相关，但传统分析方法依赖空间调整并排除非位置细胞。为克服这些限制，研究人员开发了一种基于活动行为中观察到的成对放电顺序概率来估计尖峰序列似然的分析方法。该方法不依赖于行为相关性，并在模拟数据、大鼠单细胞记录和小鼠钙成像中得到了验证。结果显示其与传统的重放指标高度一致，且具有广泛的适用性。","scd":null,"kp":[]},{"i":38862,"as":"研究调查了神经递质系统与儿童数学和阅读能力相关的脑结构组织之间的联系。对991名儿童的影像学分析表明，脑学术能力结构表型与包含19种神经递质受体和转运体的PET图谱存在关联。在两个独立队列中，NMDA谷氨酸受体分布与支持学术能力的脑结构组织显示出最一致的相关性。NMDA受体密度对应于支撑数学能力的多种功能网络，揭示了谷氨酸能信号的关键作用。","scd":null,"kp":[]},{"i":38863,"as":"研究人员开发了一种闭环颅内脑机接口，能够检测前岛叶宽频伽马活动（70-150 Hz）的瞬态波动，并据此触发刺激呈现。研究发现，前岛叶的自发高BGA活动会影响个体对包含愉悦与不悦属性的多属性提议的接受或拒绝决策。这一发现揭示了自发神经活动对人类决策行为的影响。","scd":null,"kp":[]},{"i":38864,"as":"基于百万退伍军人计划（MVP）中超60万名参与者的数据，研究对欧洲、非洲、美洲混血和东亚人群进行了mtDNA变异与心脏代谢表型的多血统分析。验证了248个mtDNA基因位点后，鉴定出10个血统分层单变异关联，并在性别和2型糖尿病分层分析中发现了23个额外信号。其中四个变异标记了单倍群J，并在MT-ND3、MT-ND5和MT-CYB等基因上存在特定突变，影响疾病特征。","scd":null,"kp":[]},{"i":38865,"as":"为研究灵长类前额叶-杏仁核网络在社交凝视中的因果动态，研究开发了一种算法，将独立记录的雄性猕猴数据整合为“超级阶段”。该方法利用合成真值数据验证，能够重建与匹配凝视序列对齐的同时多区域记录。通过动态贝叶斯网络分析，揭示了杏仁核、眶额皮层、背内侧前额叶皮层之间具有时间结构化且依赖于行为的因果相互作用。","scd":null,"kp":[]},{"i":38866,"as":"研究报道了使用氯化钠作为绿色氯源，在无需化学氧化剂的条件下进行对映选择性氯化的方法。通过电化学原位氧化，实现了首例电驱动的对映选择性半频哪醇重排。该方法的核心是一个双有机催化剂相转移系统，可协同管理相转移和对映体诱导。交替电流（AC）的应用被证明在防止催化剂沉积在电极上方面发挥了关键作用。","scd":null,"kp":[]},{"i":38867,"as":"通过淡水填充实验研究表明，在 Heinrich 寒冷期的开端，东北太平洋发生的冰山排放事件（即 Siku 事件）可以通过将淡水输送到北大西洋深层水形成区，引发大西洋经向翻转环流（AMOC）的减弱。这种初始减弱随后可能被不列颠和劳伦泰德冰盖释放的进一步融水放大，揭示了北太平洋融水在引发和预先调节 AMOC 减弱中的机制。","scd":null,"kp":[]},{"i":38868,"as":"研究报道了在金表面上通过丙烯氧化偶联电化学合成C6化学物质的路径，成功生产出2,5-己二酮和3-己烯-2,5-二酮两种C6化合物。在温和条件下，C6产物的总法拉第效率达到36%。结合原位红外光谱、压力相关实验和密度泛函理论计算表明，该氧化偶联过程是通过丙烯和丙烯羟基中间体之间的不对称偶联实现的。","scd":null,"kp":[]},{"i":38869,"as":"提出了一种溢流-存储-弛豫加氢机制，以克服电催化加氢反应中活性与选择性之间的制约关系。以乙炔加氢转化为乙烯为例，采用负载在铜上的原子级分散WOx（WOx/Cu）作为催化剂。该催化剂界面具有生成*H的Cu位点和作为*H储层的WOx位点，有效避免了高电流密度下析氢和过度加氢问题。实验表明，该催化剂实现了约1.43 A的乙烯偏电流密度。","scd":null,"kp":[]},{"i":38870,"as":"为解决可充镁电池中卤化物阴离子对反应动力学影响机制不明确的问题，研究团队以氟苯基硼酸镁络合物（MPFBC）电解质为基础，系统合成了MPFBC-Cl和MPFBC-Br等电解质。研究表明，Br-具有与Cl-相当的溶解度和质量效率，是解耦卤化物特性对 Mg2+溶剂化和去溶剂化动力学影响的理想平台。该工作填补了电解质设计中卤素化学理论的空白。","scd":null,"kp":[]},{"i":38871,"as":"利用原位原子级环境扫描透射电子显微镜（ESTEM），研究了α-Fe(001)表面的氧化过程，揭示了一条从Fe到Fe3O4的全新氧化途径。研究发现，亚稳态的FeO在两个中间态中发挥了动态维持作用，填补了气固反应与固态相变之间原子级结构动力学耦合机制的认知空白。该成果对腐蚀科学、多相催化及氧化物异质结构设计具有重要意义。","scd":null,"kp":[]},{"i":38872,"as":"报告了一种由界面驱动内在稳定高阶范霍夫奇点（HOVHS）的机制。通过在Si(111)上外延生长原子级薄铅单层，结合角分辨光电子能谱、扫描隧道光谱和第一性原理计算，证明了在布里渊区非正规点出现了II型HOVHS。这一发现证明了HOVHS无需外部调谐即可在实际晶体材料中内在涌现，为二维系统中增强电子关联效应提供了新认识。","scd":null,"kp":[]},{"i":38873,"as":"引入了统计描述符φ，用于量化给定元素组合中高活性构型的比例，从而缩小材料计算模型与实验性能之间的偏差。结合自主开发的Seq-Equiformer图神经网络模型，对3d过渡金属掺杂CoOOH的2.5亿种析氧反应结构进行了过电位预测。通过考虑多结构活性分布，相比单一模型，该方法能更准确地量化并筛选宏观催化活性。","scd":null,"kp":[]},{"i":38874,"as":"报道了一种基于N'-烷基腙酰胺（NAHA）试剂的新型还原和环化羰基去除方法。该方法通过顺序断裂双碳-碳键，将多种环酮高效转化为对应的开环和缩环类似物。此策略具有广泛的官能团耐受性和高化学选择性，不仅能实现复杂生物活性化合物的后期修饰，还可用于合成缺乏极性官能团的全碳季碳中心。","scd":null,"kp":[]},{"i":38875,"as":"建立了一种布朗斯特与路易斯双酸协同催化策略，成功实现了三维共价有机框架（COFs）单晶的受控轴向生长和形貌演变。通过调节三氟甲磺酸镧（Dy(OTf)3）路易斯酸的浓度，大幅抑制了晶体双晶化现象。该策略成功制备出尺寸≥50 μm、具有dia拓扑结构的大型3D COFs单晶，并实现了其形貌的持续定向调控。","scd":null,"kp":[]},{"i":38876,"as":"提出利用锆（Zr 4+）掺杂调节LiYMo2O8（LYMO）单晶载流子传输以提高X射线检测灵敏度的策略。原始LYMO晶体沿a轴和c轴的电阻率分别为9.96 × 10^13和1.44 × 10^14 Ω·cm。通过顶部籽晶溶液法成功生长了Zr掺杂的LYMO晶体，有效克服了氧化物单晶因超高本征电阻率导致的光电流受限问题，提升了电导率和检测性能。","scd":null,"kp":[]},{"i":38877,"as":"综述了超晶格材料在热电领域的最新研究进展。超晶格凭借独特的周期性结构，通过结构设计和界面改性实现了对材料性质的精细调控。界面的额外声子散射、电荷转移和能量过滤效应，成功解耦了热传输与电传输，使其同时具备极低的热导率和优异的电导率，成为替代传统热电材料的重要候选者。","scd":null,"kp":[]},{"i":38878,"as":"开发了一种用于同时检测乳酸脱氢酶（LDH）和白细胞介素-6（IL-6）的无标记电容式传感电极。该传感器利用蛋白质钝化的石墨烯界面进行功能化，克服了传统比色法依赖复杂仪器设备的局限。此方法能够从细胞代谢和免疫调节的角度提供全面的病理学见解，适用于资源受限环境下的疾病进展评估和细胞模型状态监测。","scd":null,"kp":[]},{"i":38879,"as":"证明了单层Ca2Nb3O10纳米片模板中的纳米级间隙可作为可调节元件来控制薄膜性质。针对二维纳米片组装中因不规则几何形状产生的固有间隙，研究发现这些暴露衬底的区域创造了第二生长环境。通过控制间隙，能够有效调控晶格匹配的SrRuO3薄膜的晶体取向、输运和磁各向异性，解决了任意衬底上氧化物薄膜集成的难题。","scd":null,"kp":[]},{"i":38880,"as":"开发了一种基于上转换纳米粒子（CSS-UCNPs）和偶氮苯交联液晶弹性体的808 nm近红外（NIR）光驱动执行器。Nd3+敏化的纳米粒子将NIR光转换为紫外/蓝光发射，驱动偶氮苯单元发生反式至顺式的光致异构化，引发LCE薄膜宏观弯曲。该微槽执行器避免了紫外光的光毒性，成功应用于心肌细胞的定向排列培养。","scd":null,"kp":[]},{"i":38881,"as":"通过大地电磁成像技术揭示了古代地幔柱残留物对岩石圈结构的改造及其对地壳流体迁移的影响。在四川华蓥山断裂带下方发现的高电阻率、高地震波速和高密度结构，被解释为峨眉山大火成岩省地幔柱玄武岩熔体的结晶产物。结合地幔尺度的地球动力学模拟，阐明了柱缘区域古老柱体衍生材料如何影响地壳流体迁移与构造变形。","scd":null,"kp":[]},{"i":38882,"as":"揭示了FeMn基聚阴离子磷酸盐（如Na4FeMn(PO4)3）钠离子电池正极材料存在异常电化学惰性的物理根源。研究发现其内在的电子“时空限制效应”：空间上PO4多面体阻隔了MO6氧化还原单元，时间上自旋配对阻碍了d电子构型内的电荷传输。通过引入具有空3d轨道的V和Ti作为电子桥梁进行异金属连接，成功激活了材料的高能量密度和超宽温钠存储性能。","scd":null,"kp":[]},{"i":38883,"as":"提出利用强酸修饰水凝胶以提升渗透能转换性能的策略。通过引入具有高度解离和水化特性的强酸基团，水凝胶展现出高电导率、低内部电阻和强保水能力。在50倍氯化钠盐度梯度下，修饰后的水凝胶显著改善了离子传输和发电性能，有效解决了膜基逆电渗析技术中功率输出密度受限的难题。","scd":null,"kp":[]},{"i":38884,"as":"","scd":null,"kp":[]},{"i":38885,"as":"","scd":null,"kp":[]},{"i":38886,"as":"报道了一种利用镍催化脱氰和钌催化乙烯复分解串联反应降解含腈塑料和橡胶的通用策略。该催化升级回收过程能够去除氰基并将其转化为高附加值腈类化合物，且不释放剧毒氰化物。该工艺可使用乙烯作为氰基受体和复分解 partner 实现一锅法反应，极大简化了降解流程，提高了降解效率并具备工业应用潜力。","scd":null,"kp":[]},{"i":38887,"as":"开发了一种双金属铬催化剂，用于提高环氧丙烷聚合的活性和立构选择性。通过基于计算的有理设计，引入柔性系链并增大水杨亚胺邻位的空间位阻，该催化剂实现了近100的对映选择性和高达50,000 h-1的 unprecedented 周转频率。该工作成功合成了作为高强度、海洋可光降解材料的全同立构聚环氧丙烷。","scd":null,"kp":[]},{"i":38888,"as":"开发了一种离子液体负载的金属有机框架（MOF/IL）复合材料，用于高效捕获NH3。该材料结合了高亲和力离子液体和具有促扩散通道的蒽基MOF。由于空间限制的离子液体-NH3体系发生有序相变，复合材料在298 K和1 bar下表现出S型吸附等温线和高达455.81 cm³/cm³的高体积NH3吸附量，实现了高容量、优异选择性和快速吸附动力学的结合。","scd":null,"kp":[]},{"i":38889,"as":"","scd":null,"kp":[]},{"i":38890,"as":"发现了海水微滴界面的自由基级联反应机制，能显著放大其氧化能力。在海水微滴界面自发产生的羟基自由基（·OH）与海水中丰富的溴离子和碳酸氢根离子迅速发生协同反应，生成包括活性溴（·Br）和碳酸根（·CO3-）在内的二次自由基网络。这一自持的界面循环机制驱动了大气中汞的氧化过程。","scd":null,"kp":[]},{"i":38891,"as":"报道了一种结合静电纺丝和同步光交联的单步制造工艺，用于制造液晶弹性体（LCE）纤维执行器。通过设计合成支化低聚物并优化光引发剂系统，实现了介晶单元的长程定向排列，成功解决了静电可纺性与交联密度之间的权衡问题。制得的纤维材料展现出优异的无应力热致和光致形变能力，适用于软机器人和人造肌肉领域。","scd":null,"kp":[]},{"i":38892,"as":"","scd":null,"kp":[]},{"i":38893,"as":"","scd":null,"kp":[]},{"i":38894,"as":"研究人员提出一种多功能电解液添加剂三(二甲基硅氧基)苯基硅烷(TDSPS)，以改善4.8V富锂氧化物(LRO)/锂电池的电化学循环性能。实验表明，在25℃下添加1 vol%的TDSPS，电池在200次循环后(0.5 C)容量保持率达到81.6%，而基准电解液仅为34.3%。TDSPS通过在正极表面优先氧化等三种主要机制发挥作用。","scd":null,"kp":[]},{"i":38895,"as":"本研究设计并制备了基于二维薄膜/氧化物量子点的多维界面结构，用于高效全光控半导体器件。该架构显著增加了有效界面面积，极大增强了光生载流子的分离和界面电荷注入效率。器件在紫外光照射下实现了全光驱动的可逆操作，无需电刺激，并在运行中表现出高效率与稳定性。","scd":null,"kp":[]},{"i":38896,"as":"为解决二氧化锡负极因不可逆转化反应导致的首效偏低问题，研究通过金属有机框架(MOF)衍生策略构建了SnO2-NiO/Ni-碳复合材料。富界面结构实现了转化/合金化反应的协同调节与界面锂离子存储，减少了首圈锂的不可逆消耗。优化后的电极初始放电比容量达1102 mAh g-1，初始充电比容量为1035.1 mAh g-1。","scd":null,"kp":[]},{"i":38897,"as":"针对固态导体中离子电导率与机械强度难以兼顾的问题，研究提出利用三种基于柱芳烃的自组装有机纳米片(SONs)的超分子策略。复合薄膜的性能与氢键位点数量及亲水性相关：增加氢键位点与亲水性实现了最高韧性(66328±424 kJ/m3)，而提高疏水性并减少氢键位点则有助于优化杨氏模量(659.1±22 MPa)。","scd":null,"kp":[]},{"i":38898,"as":"","scd":null,"kp":[]},{"i":38899,"as":"研究提出一种超快且可扩展的反应激光烧结(RLS)策略，用于制备石榴石型Li6.4La3Zr1.4Ta0.6O12(LLZTO)固态电解质。RLS实现了反应与致密化的同步进行，相对密度达到约95%，同时减少了锂损耗并抑制了二次相的形成。与传统烧结相比，该方法提高了离子电导率(0.36±0.08 mS cm-1)并改善了致密度。","scd":null,"kp":[]},{"i":38900,"as":"针对宽带隙金属卤化物钙钛矿因富含溴导致的结晶加速、缺陷态多及光致卤化物相分离引起的电压损失和不稳定问题，研究提出基于甲酸铯(CsFa)和甲脒甲酸盐(FAFa)的双添加剂策略。其中引入的甲酸根离子(HCOO-)发挥主导的双功能作用，有效改善材料的性能并抑制非辐射复合与离子迁移。","scd":null,"kp":[]},{"i":38901,"as":"受生物构象多重性启发，研究使用单一荧光两性离子单体实现了在结晶态、凝胶态或无定形态的选择性自组装，突破了传统二元单体系统难以控制聚集体形貌的局限。这种极简设计实现了凝胶化的实时可视化，并制备出高性能水系锌离子电池负极保护材料，为功能超分子材料提供了新路径。","scd":null,"kp":[]},{"i":38902,"as":"人类颅骨形态演化呈现出脑容量增加和面部健壮度下降的特征。为验证这是否为大脑增大认知需求及食物加工降低咀嚼能耗的自然选择结果，研究测试了六种进化过程对人类颅骨形态变异的拟合度。分析基于从早期人类开始的八个分类单元的神经颅骨和面部3D地标坐标数据集。","scd":null,"kp":[]},{"i":38903,"as":"为克服血脑屏障(BBB)对阿尔茨海默病(AD)治疗的限制，研究对碳硅烷树枝状聚合物(G3Si PEG6000)及其siRNA复合物进行了分阶段评估。结果表明，该聚合物能增强细胞内siRNA的胞质定位信号，且复合后的siRNA降低了载体的基因毒性。在BBB三培养模型中，屏障功能得以保持且未受破坏。","scd":null,"kp":[]},{"i":38904,"as":"","scd":null,"kp":[]},{"i":38905,"as":"","scd":null,"kp":[]},{"i":38906,"as":"为解决可拉伸电子系统中的热量积聚问题，研究提出了一种具有局部导热复合岛的地桥架构。通过在软衬底特定区域掺入立方氮化硼(c-BN)，构建了面内和面间热导率分别为2.327和2.596 Wm-1-K-1的复合岛。与不含复合岛的基底相比，峰值温度降低了12.8℃，使得可拉伸计算平台在实际运行中保持40℃以下的工作温度。","scd":null,"kp":[]},{"i":38907,"as":"研究利用单细胞基因表达分析探究了爬行动物色素细胞的分化机制。在玉米蛇和鬃狮蜥胚胎皮肤中发现了经典色素细胞，并在鬃狮蜥中发现了此前未知的色素细胞亚型。这些亚群共表达祖细胞和成熟细胞标记物，可能参与胚胎皮肤花纹的形成。比较分析揭示了成熟色素细胞分化既有保守机制，也存在谱系特异性机制。","scd":null,"kp":[]},{"i":38908,"as":"为寻找银屑病外用小分子替代疗法，研究在原代人角质形成细胞中进行了全基因组CRISPR敲除筛选，以寻找IL17RA的调节因子。结合实验和AI语言模型VirtualCRISPR，验证了5-脂氧合酶(ALOX5)和催产素受体(OXTR)这两个此前与IL17RA关联极小的调节因子，它们通过特定机制发挥作用。","scd":null,"kp":[]},{"i":38909,"as":"非整倍体是人类胚胎着床前失败的常见原因，但极少在出生时观察到。利用重演上胚层、内脏内胚层和外胚外外胚层的三谱系干细胞胚胎模型，研究发现非整倍体细胞的命运具有谱系特异性：它们会从上胚层和内脏内胚液中被选择性清除（通过凋亡或物理挤压），但在外胚外外胚层中持续存在。p53激活和Myc抑制介导了这一清除过程。","scd":null,"kp":[]},{"i":38910,"as":"在骨髓骨内膜中发现了一类表达整合素α8的独特间充质干细胞亚群。这类细胞表现出比其他亚群更强的造血支持活性。耗竭Itga8+ MSCs会导致造血干细胞(HSC)数量减少和静息期缩短，削弱骨髓重建能力。机制上，它们通过细胞粘附维持造血，并分泌Mfap4因子支持骨髓重建。","scd":null,"kp":[]},{"i":38911,"as":"核酸酶FAN1与错配修复蛋白MLH1的相互作用能调节亨廷顿病的CAG重复扩增。研究解析了MLH1 C端结构域与FAN1 MIP/MIM基序结合的晶体结构，揭示了一个保守的识别机制，并发现了MLH1上此前未知的结合位点S3。免疫共沉淀证实，突变MLH1关键残基会破坏细胞内的FAN1结合，阐明了二者互作的分子基础。","scd":null,"kp":[]},{"i":38912,"as":"研究操纵了小鼠学习运动计时任务中的关键可塑性介质CaMKII，以探究新皮层细胞可塑性对学习的影响。前运动皮层中瞬时失活CaMKII会损害学习但不影响已习得动作的执行。细胞特异性操作表明，两个锥体束(PT)神经元亚型（而非IT神经元）中的CaMKII依赖性可塑性是学习所必需的，并参与动态塑造过程。","scd":null,"kp":[]},{"i":38913,"as":"CMG2/ANTXR2是维持细胞外基质稳态的受体，也是炭疽毒素的入口。研究揭示其功能受有序的S-酰化和去酰化循环控制。ZDHHC7对近膜半胱氨酸的S-酰化通过稳定折叠中间体防止内质网降解，使具备内质网输出能力的受体增加约5倍。随后在戈尔基体中由ZDHHC3介导第三个位点的酰化。","scd":null,"kp":[]},{"i":38914,"as":"研究确定二肽基肽酶3(Dpp3)是细菌感染期间免疫激活阈值的调节因子。Dpp3−/−小鼠对肺炎克雷伯菌表现出更强的抵抗力，伴有早期细菌负荷下降、存活率提高、组织结构保留和全身炎症减轻。机制上，Dpp3缺乏会阻碍Nrf2稳定，导致ROS积累增加和NF-κB相关反应增强，从而提升免疫细胞的内在保护作用。","scd":null,"kp":[]},{"i":38915,"as":"研究结合计算与化学库靶向设计，发现了一种具有高亲和力和长效镇痛效果的苯并噻吩取代的TRPV1激动剂MSP20。体外实验表明，长时间或重复暴露于该化合物会诱导TRPV1发生钙依赖性脱敏，使其对伤害性刺激不敏感。研究解析了人源TRPV1与MSP20复合物的冷冻电镜结构，揭示了其作用的结构机制。","scd":null,"kp":[]},{"i":38916,"as":"H3K4甲基转移酶KMT2D被鉴定为红细胞生成中转录因子GATA1的辅助因子。在人类红系前体细胞中丧失KMT2D会导致发育停滞及多种红系基因表达受损。机制上，KMT2D与GATA1在超过一千个红系增强子上共定位，显著增强转录活性。急性消耗KMT2D会导致H3K4甲基化迅速减少，证实其在红细胞分化中的关键作用。","scd":null,"kp":[]},{"i":38917,"as":"研究发现了一种与结直肠癌术后复发密切相关的独特肠道细菌特征。高达30%的非转移性结直肠癌患者在接受手术切除后会发生复发，但此前缺乏预测生物标志物。研究证实，患者在手术当天的肠道微生物群中富含产胶原酶细菌，这一围手术期特有的肠道细菌特征能够强烈预示术后肿瘤的发生。","scd":null,"kp":[]},{"i":38918,"as":"研究揭示了阿尔及利亚西尼罗病毒（WNV）的传播模式。WNV主要由受感染的库蚊叮咬传播。通过对人类进行横断面血清阳性率调查并对严重病例进行分析，发现该地的血清阳性率为16.7%，并确定年龄、地区和居住类型为感染的风险因素。此外，南部两个省份的传播模式表现为持续的低水平地方性流行风险。","scd":null,"kp":[]},{"i":38919,"as":"研究通过两种基于家庭的设计，控制了遗传混杂因素，探讨了父母养育行为与儿童攻击行为之间的双向影响。挪威队列研究利用家庭成员间的遗传相关性分离遗传与环境成分；美国收养样本则排除了遗传混杂。两项研究一致证实，父母行为与儿童攻击性之间的关联同时受到遗传和环境因素的共同影响。","scd":null,"kp":[]},{"i":38920,"as":"人类特异性microRNA（miR-1229-3p）在控制兴奋性突触形成的时机中起关键调节作用。抑制该microRNA会改变人类诱导多能干细胞衍生神经元的成熟轨迹并增强兴奋性突触传递。转录组分析表明，敲低miR-1229会导致线粒体DNA编码基因下调。该分子通过调节线粒体形态、mtDNA丰度及线粒体自噬来控制突触生成的进程。","scd":null,"kp":[]},{"i":38921,"as":"鼠伤寒沙门氏菌通过向宿主细胞质转移效应分子SopB来抑制早期黏膜组织炎症，从而延缓疾病进展并延长宿主存活期。在机制上，SopB能阻止ADAM17的激活、质膜易位及膜结合型TNFα的释放，并通过mTOR控制的分泌自噬减少IL-18的上皮分泌。这彻底消除了早期上皮转录反应，减少了免疫细胞募集及程序性细胞死亡介导的黏膜屏障损伤。","scd":null,"kp":[]},{"i":38922,"as":"研究鉴定出了小麦串联激酶蛋白WTK4识别的病原体效应子AvrWTK4。小麦白粉病RNase-like效应子AvrWTK4被WTK4识别。AvrWTK4基因突变或表达量降低会导致对含有WTK4植株的感染。转染实验表明，无毒力的AvrWTK4变体比毒力变体与WTK4的N端结构域具有更强的相互作用，从而引发特异性细胞死亡以介导抗病性。","scd":null,"kp":[]},{"i":38923,"as":"慢性伤口因持续炎症、蛋白水解失衡、微生物定植和组织再生受损而成为临床难题。现有2D和3D体外模型缺乏重现非愈合表型所需的生化复杂性。基于定量的临床伤口渗出液数据，文章提出了一个特征驱动、病因分层的模块化设计框架，用于指导构建体外模型和慢性伤口模拟培养基，以更准确地复现各类慢性伤口的复杂性。","scd":null,"kp":[]},{"i":38924,"as":"精准营养学通过利用多模态数据为个体量身定制干预措施。人工智能（AI）和机器学习（ML）在处理多组学和营养数据（具有组合性、偶发性、依赖上下文和易错性特点）时展现出巨大潜力，但仍面临数据质量、可解释性、验证和因果推断的挑战。文章明确了实现稳健、可解释且具临床可操作性的AI/ML营养学应用的最佳实践。","scd":null,"kp":[]},{"i":38925,"as":"FLOWR.ROOT是一个基于流匹配的SE(3)等变基础模型，将口袋感知的3D配体生成与多终点结合亲和力预测及置信度估计集成于单一主干网络中。该模型支持全新结构生成、骨架跃迁和片段替换等操作。其训练分为三个阶段：数十亿配体构象预训练、高质量共晶数据微调，以及通过LoRA进行的参数高效微调，实现了结构与亲和力的联合预测。","scd":null,"kp":[]},{"i":38926,"as":"研究开发了一种基于聚甲基丙烯酸甲酯（PMMA）和EuIII配合物的多功能透明薄膜，专用于智能窗户。该薄膜集成了发光太阳能聚光器（LSC）和光学温度探头的双重功能。其配体能有效吸收近紫外光并敏化EuIII发光，发光量子产率高达50%，敏化效率超过90%，且薄膜保持90-100%的高透明度。","scd":null,"kp":[]},{"i":38927,"as":"间充质干细胞体外扩增易引发衰老，而线粒体转移是改善这一现象的有效策略。为克服传统共培养和微注射法的定量控制差、通量低等缺陷，研究开发了一种惯性聚焦辅助的液滴微流控平台。该平台能在单细胞水平上实现高通量、高效率的线粒体转移，成功生成了29.2%的单细胞液滴，为缓解细胞衰老提供了新技术。","scd":null,"kp":[]},{"i":38928,"as":"研究利用远程等离子体辅助方法合成了氮掺杂无定形碳（NDAC）原子级薄膜。该膜的厚度可在亚纳米至数纳米之间连续可调。实验展示了这种超薄、连续且各向同性的无定形碳膜在电子透射和铜扩散阻挡层领域的广阔应用前景，是下一代极端厚度电子器件和阻挡涂层的重要候选材料。","scd":null,"kp":[]},{"i":38929,"as":"研究利用高速原子力显微镜（HS-AFM）首次实现了对N6-甲基腺苷催化核心METTL3-METTL14（M3/M14）异二聚体动态构象的单分子可视化。底物RNA结合会诱导M3/M14从开放刚性状态转变为紧密催化状态。基于此，研究筛选出两种强效DNA适体抑制剂M3B和M3L，它们通过竞争性结合将M3/M14锁定在构象陷阱中，从而抑制其催化活性。","scd":null,"kp":[]},{"i":38930,"as":"","scd":null,"kp":[]},{"i":38931,"as":"细胞取向对组织工程与再生至关重要。研究在聚二甲基硅氧烷基底上制备了由高度有序金纳米球组成的各向异性纳米线，用于引导细胞排列。这种金纳米球线性组装体提供的纳米形貌线索能够诱导RSC96施万细胞沿着组装体发生显著的定向拉伸和排列，覆盖了底层褶皱形貌的引导作用。该过程与黏着斑的定向组织和肌球蛋白II介导的机械转导密切相关。","scd":null,"kp":[]},{"i":38932,"as":"为解决被动辐射冷却（PRC）材料易受环境污染老化及夜间过度冷却的问题，研究设计制造了一种具有抗紫外线和储热能力的新型无机核壳散射体（ICSS）。通过硅烷化改性和蒸发驱动组装技术，开发出集抗紫外线、储热和超疏水特性于一体的涂层，有效提升了辐射冷却材料的耐用性，并实现了全天候稳定的冷却效果。","scd":null,"kp":[]},{"i":38933,"as":"CuInS2/ZnS胶体量子点因具有吸收广和斯托克斯位移大等优点，是理想的发光太阳能聚光器材料。然而，使用传统原料生长ZnS壳层会产生共分散残留杂质，严重降低胶体稳定性并限制墨水配制。研究引入了极性可调的沉淀法，在纯化量子点的同时将杂质保留在上清液中，不仅保持了光致发光量子产率，还大幅提升了胶体稳定性。","scd":null,"kp":[]},{"i":38934,"as":"文章提出了一种基于杯芳烃的反硫化方法，用于构建天然橡胶/炭黑复合材料的机械互锁多硫化物交联剂。缺乏聚合基团的宏观主体在橡胶与填料界面形成聚轮烷结构，增强结合胶的形成并允许界面滑动；而带有烯丙基官能团的系统则与橡胶网络发生共价交联，从而实现网络与界面的协同增强，全面提升材料的撕裂抗性、加工稳定性和抗老化性能。","scd":null,"kp":[]},{"i":38935,"as":"糠醛的电催化加氢裂解生成2-甲基呋喃涉及复杂的四电子转移过程，易出现无序电子流动。研究开发了一种由碳基基质包裹的混合价态铜簇催化剂，通过中间体覆盖策略加速电子转移。碳基质创造了对H+吸附较弱的有利环境，Cu+位点易于活化C-O键生成2-甲基呋喃，Cu0位点则加速加氢过程，从而在动力学和热力学上共同克服了活性与选择性之间的矛盾。","scd":null,"kp":[]},{"i":38936,"as":"光致环状有机分子开环是光化学的基础过程。由于直接成像超快原子核运动极具挑战，现有的反应机制存在争议。研究利用时间分辨库仑爆炸成像技术结合分子动力学模拟，直接对气相呋喃在紫外光激发后的瞬态碳骨架结构进行成像。该技术成功识别并映射了开环反应的路径，为直接观察和确认超快光化学反应机制提供了新方法。","scd":null,"kp":[]},{"i":38937,"as":"受锂-空气化学启发，研究开发了一种新型电渗析技术，可直接从海水中提取碳酸锂。该方法使用环境中的二氧化碳作为碳源，将固态锂离子传导膜与锂-空气化学相结合。热力学驱动的置换反应赋予了该系统固有的离子选择性，使其无需添加沉淀剂即可在单一步骤内同时实现锂的富集和碳酸盐的形成，为可持续获取锂资源提供了新途径。","scd":null,"kp":[]},{"i":38938,"as":"受墨鱼骨壁隔结构启发，研究人员采用逐层冷冻技术开发出轻质环氧树脂蜂窝材料。该材料密度为0.55 g/cm³时，比能量吸收高达34.5 J/g。其多孔壁层间的致密隔板增强了抗屈曲结构稳定性，并在压缩时提供横向约束。该结构显著提升了高应变率抗冲击强度，实现了190%和66%的增长。","scd":null,"kp":[]},{"i":38939,"as":"研究提出具身智能驱动的轨迹预测框架，整合场景注意力机制、社会影响理论图与物理社会力模型，解决传统黑盒模型缺乏可解释性的问题。在ETH和UCY数据集上实验表明，该模型平均位移误差降低42%，最终位移误差降低40%，推理速度达0.003秒，并具备强大的可解释性。","scd":null,"kp":[]},{"i":38940,"as":"浓缩乳液的生产涉及高剪切流动及液滴的聚合与破碎，这些复杂相互作用决定了液滴形态和流变特性。研究发现，当达到临界体积分数时，乳液会失去稳定性，发生流质组分角色互换的极快过程，即灾难性相变。该过程对食品、化妆品及化学工业至关重要。","scd":null,"kp":[]},{"i":38941,"as":"研究证明三油酸甘油酯可作为动力学控制超分子聚合的有效介质，揭示了脂滴在调节超分子组装途径中的作用。以丙氨酸为基础的二酰胺功能化荧光团在三油酸甘油酯中通过“成核-生长”机制形成超分子聚合物。其热力学稳定性与常规溶剂相当。","scd":null,"kp":[]},{"i":38942,"as":"研究人员开发出室温下运行的抗磁悬浮毫米级转子，耗散率低至3.85 μHz，自由旋转时间超10小时。该转子在轴对称永磁体阱中稳定悬浮，可在高真空中通过非接触式静电驱动达到930 RPM。利用其低阻尼和高角动量特性，实现了精度为6.5×10⁻³°/s的精密陀螺仪。","scd":null,"kp":[]},{"i":38943,"as":"","scd":null,"kp":[]},{"i":38944,"as":"通过打破Ruddlesden-Popper铁电材料的对称性，可制备出具有高可调谐性和低损耗的面外介电材料。","scd":null,"kp":[]},{"i":38945,"as":"为解决大功能基团带来的空间位阻问题，研究提出空位约束策略，通过压缩金属键实现催化剂深层轨道离域。以负载在缺陷CeO₂上的铋原子为例，构建了O4-Bi-Bi-O4集合体。离域深层轨道通过增强活性位点间的电荷转移，展现出强穿透力，有效克服了空间位阻效应。","scd":null,"kp":[]},{"i":38946,"as":"研究发现儿茶酚胺神经元活动能增强与意识感知相关的皮层点火过程。化学遗传学显示，激活或抑制腹侧被盖区多巴胺神经元分别增强或减弱视觉皮层刺激引发的扣带回皮层兴奋。常用麻醉剂氯胺酮和异氟醚会显著抑制V1到ACA的活动传播，从而干扰意识感知。","scd":null,"kp":[]},{"i":38947,"as":"研究将波长选择性染料QC7CN用作3D打印的“染料墨水”，解决了光控智能材料在骨组织工程中的分子设计难题。该染料在紫外光聚合过程中保持高透明度，同时具备强大的第二近红外（NIR-II）吸收能力。利用其深层光热响应特性，实现了近红外光热驱动甲状旁腺激素脉冲释放，用于骨质疏松骨修复。","scd":null,"kp":[]},{"i":38948,"as":"体育比赛中不当使用降温休息正削弱人们对热健康研究的信任。","scd":null,"kp":[]},{"i":38949,"as":"相关分析阐述了除软件和加州企业家之外的计算机芯片发展历史及其控制权竞争。","scd":null,"kp":[]},{"i":38950,"as":"科技公司声称其服务能检测出AI生成的文本，但不同检测程序在技术和质量上存在差异。","scd":null,"kp":[]},{"i":38951,"as":"绵羊多莉的成名经历为当前关于生殖技术的讨论提供了重要启示。","scd":null,"kp":[]},{"i":38952,"as":"研究证实，通过将锗与氧化还原活性配体配对，主族化合物可发生通常与过渡金属相关的多电子转移化学反应。该分子能够精准引导双电子或四电子转移路径，并在单一位置表现出电子供体和受体双重特性，为在主族化学中构建更通用的氧气激活系统提供新思路。","scd":null,"kp":[]},{"i":38953,"as":"基于自旋缺陷的量子显微镜凭借高灵敏度和高空间分辨率，在凝聚态物理研究中展现出前沿优势。文章综述了扫描探针氮-空位量子传感技术在纳米尺度研究新兴量子材料物理特性方面的进展，并探讨了基于该技术的量子传感平台。","scd":null,"kp":[]},{"i":38954,"as":"研究发现，在氮化硼封装的双层石墨烯范德华异质结构中，两层BN之间的角度对齐（约15°至45°）是控制异常门控效应的关键参数。这种异常效应（如无效静电控制和强电阻滞后）并非源于石墨烯与BN的莫尔超晶格，且在室温下未表现出预期的60°周期性。","scd":null,"kp":[]},{"i":38955,"as":"学者指出，欧盟现行法律需进行改革，以解决活体复合材料的市场准入瓶颈问题。","scd":null,"kp":[]},{"i":38956,"as":"研究表明，锂镧锆氧化物固态电解质的晶界带有离子内置电荷，锂空位聚集在界面产生局部电势（20°C时为-0.15 V）。这阻碍了离子传输，使晶界处的电子传导率比块体高30倍。这种不平衡导致电池运行期间内部锂金属成核，加速短路，限制了固态电池的耐久性。","scd":null,"kp":[]},{"i":38957,"as":"研究成功研发出名为Tumbleweed（TW）的人工蛋白分子马达。该马达采用模块化设计，包含三条“腿”，每条腿具有配体门控DNA结合域，能与DNA轨道特定部位选择性结合。在化学燃料驱动下，TW能在DNA轨道上实现类似前翻滚的外部受控定向步进运动。","scd":null,"kp":[]},{"i":38958,"as":"研究利用扫描隧道光谱技术，在激子绝缘体Ta₂Pd₃Te₅中观测到杂质诱导的电子-空穴对破裂现象。单个碲空位在激子能隙内生成一对光谱峰，其能量可由针尖电场连续调节。光谱映射揭示了亚能隙态在空间上的各向异性，证实了电子-空穴成分间的电子耦合特性。","scd":null,"kp":[]},{"i":38959,"as":"名为“风滚草”的人工蛋白步行器在DNA轨道上展示了配体驱动的步进运动。这一成果标志着向模块化、定制化设计自主运动蛋白迈出了关键一步，是实现人工分子机器可控运动的重要技术进展。","scd":null,"kp":[]},{"i":38960,"as":"研究解决了四个关键的体内递送瓶颈，使脂质纳米颗粒能够成功在小鼠体内实现治愈性的先导编辑。这为非病毒载体基因编辑提供了一条高效且安全的递送路径。","scd":null,"kp":[]},{"i":38961,"as":"","scd":null,"kp":[]},{"i":38962,"as":"","scd":null,"kp":[]},{"i":38963,"as":"马凡综合征的胸主动脉瘤等致命并发症缺乏治愈手段。研究发现，蛋白聚糖驱动的纤连蛋白（FN）积累会激活αVβ3-PI3K-PIP3-PDK1-ILK信号级联反应，导致主动脉疾病。抑制该通路中的FN组装或关键节点，可恢复血管收缩力并限制小鼠主动脉扩张。","scd":null,"kp":[]},{"i":38964,"as":"针对相变材料热能存储系统充放电温度难以动态调节的挑战，研究人员开发出基于呼吸热量金属有机框架（MOF-508b）的气体响应型热能存储方案。通过调节环境二氧化碳压力（5至25巴），其转变温度可在零下30摄氏度至120摄氏度间实现宽范围调节。","scd":null,"kp":[]},{"i":38965,"as":"研究人员提出了一种用于大型碱性水电解槽的“时间电位诱导调节”技术。在不改变催化剂和电解槽结构的条件下，仅通过优化电源供电方案即可延长设备在功率波动下的耐久性。该技术打通了电气工程与电化学的壁垒，推进了可再生能源制氢基础设施的融合。","scd":null,"kp":[]},{"i":38966,"as":"","scd":null,"kp":[]},{"i":38967,"as":"研究发现，在保持纳米颗粒尺寸和电子状态相似的前提下，优化铂纳米颗粒密度能够有效提升内在催化活性。在环己烷催化脱氢反应中，调节铂纳米颗粒密度使铂效率提高了9.6倍，苯生成速率达每摩尔铂每小时24217摩尔。该优化催化剂在连续800小时测试中保持稳定。","scd":null,"kp":[]},{"i":38968,"as":"二维范德华极性金属因结合长程极性有序和金属导电性而备受关注，但极难实现。研究首次发现了由极性原子层堆叠而成的二维范德华极性金属MoOBr2。单晶X射线衍射表明其结晶于非中心对称空间群C2，极性源于不对称的八面体结构，为相关非互易传输及非线性光学研究提供了新材料。","scd":null,"kp":[]},{"i":38969,"as":"为解决活细胞内亚细胞水平酶活性成像工具缺乏的问题，研究人员开发了一类荧光生成报告器。该报告器通过罗多尔荧光团结合酶特异性底物和生物正交笼蔽基团，能够对线粒体、溶溶酶体、内质网和高尔基体等特定细胞器内的酶活性进行高时空分辨率的荧光成像。","scd":null,"kp":[]},{"i":38970,"as":"高熵金属有机框架中长程晶体有序与化学无序共存。研究证明，金属异质性会在三核次级结构单元中诱导出明确的组分依赖性畸变，并相干传递产生晶格级别的结构变化。通过单金属到五金属组合的单啉啉TCPP框架模型，定量确立了金属种类、局部配位几何与晶格响应间的关系。","scd":null,"kp":[]},{"i":38971,"as":"氧化还原液流电池等长时储能技术需要精确的状态诊断。本文综述了原位和工况光谱及电化学工具的进展，包括紫外可见近红外、核磁共振、X射线技术等。这些工具能够有效解析电解质形态、传输性质及反应机制，为新兴氧化还原靶向液流电池和电化学二氧化碳捕获系统提供机理研究工具箱。","scd":null,"kp":[]},{"i":38972,"as":"由于熵效应通常倾向于紧凑排列，制造开放式低密度超晶格极具挑战。研究人员采用形状伪装策略，在纳米颗粒上外延生长牺牲壳层，利用壳层定义的有效几何形状引导组装。选择性地刻蚀去除壳层后，留下了由直接颗粒间接触稳定的自支撑三维框架结构，成功避免了传统方法中常见的结构坍塌。","scd":null,"kp":[]},{"i":38973,"as":"研究利用α螺旋肽骨架构建仿生支架，将罗丹明染料接枝到骨架上形成Pep-Rh结构。该结构具有与质子耦合电子转移（PCET）路径对齐的内在偶极子场。光谱和电化学分析表明，α螺旋偶极场显著加速了分子内PCET过程，其性能优于非螺旋小分子及聚合物类似物。","scd":null,"kp":[]},{"i":38974,"as":"自旋光学接口可实现材料自旋态的主动控制。本研究利用硫化钙（CaS）具有高对称、低磁噪声和红移发光光谱的优势，在铈掺杂的硫化钙（CaS:Ce3+）纳米晶体中实现了基于圆偏振光激发的态分辨自旋极化与读出。研究解析了该系统自旋选择性的物理机制，证实了化学体系在直接自旋-光学接口中的巨大潜力。","scd":null,"kp":[]},{"i":38975,"as":"研究合成了两种包含六[7]环烯核心的负曲率手性双层纳米石墨烯。在晶体状态下，两者分别采取交错和位移构象形成双层结构，由层间π-π和C-H···π相互作用驱动。核磁共振证实了其在溶液中明确的双层结构，循环伏安法测量证实了双层结构间存在分子间耦合作用。","scd":null,"kp":[]},{"i":38976,"as":"","scd":null,"kp":[]},{"i":38977,"as":"研究人员以苯酚和苯乙酮为溶剂，成功生长出具有多种多晶型、尺寸达毫米级的Y6非富勒烯受体晶体。该晶体结构密度高于以往所有报道。实验表明，这种致密单晶的激子扩散长度提升至70±15纳米，展现出了优于半晶薄膜的卓越光电特性，为高性能光电器件开发奠定了基础。","scd":null,"kp":[]},{"i":38978,"as":"金在晶体中通常以正一价或正三价存在。针对新合成的二价金化合物，第一性原理计算表明，二价金离子通过形成极化子晶体得以稳定。其键合网络由多个平面方形结构基元组成，缺乏使二价金发生歧化反应的平滑路径。金的电子态被限制在特定基元内，确保了二价金状态的局部稳定存在。","scd":null,"kp":[]},{"i":38979,"as":"研究人员开发了一种光诱导钯催化的烯丙基Heck反应，能够将烯丙基亲电试剂与烯烃直接偶联，合成高官能度化的间隔双烯和共轭双烯。该反应通过混合型钯-烯丙基自由基中间体进行，不仅具有高效的区域选择性C-C键形成能力，还展现出广泛的底物适用范围和优异的官能团耐受性。","scd":null,"kp":[]},{"i":38980,"as":"电化学氢同位素交换技术用于脂肪胺药物标记时易发生过度氧化。研究开发了首个针对无环和环状烷基胺的高效氘标记电化学方案。其核心创新是使用1,3-丙二硫醇作为氢原子转移催化剂，原位生成强效的巯基自由基转移试剂，成功克服了α-氨基自由基不稳定的难题，实现了脂肪族胺的高效同位素标记。","scd":null,"kp":[]},{"i":38981,"as":"在两个前手性自由基之间构建立体发散的碳碳键极具挑战。研究通过改造依赖于硫胺素二磷酸的自由基酶，实现了两个亲电前体的氧化还原中性立体发散交叉偶联。该反应利用光加速单电子转移生成自由基，经过系统蛋白质工程改造的四种酶变体，能够高效提供所有四种立体异构体，产率高达82%，具有极高的对应选择性和非对映选择性。","scd":null,"kp":[]},{"i":38982,"as":"理论预测光激发会导致黄素分子发生质子化位点切换，但一直缺乏实验直接证实。研究结合低温离子阱红外光谱与水分子可控微溶剂化技术，以质子化光黄素为模型，直接证明了S1至S0的光激发确实会将其优先质子化位点改变至三环芳香环的相反一侧，从实验上确证了这一光化学反应机制。","scd":null,"kp":[]},{"i":38983,"as":"美国联邦政府通过货币支付提供公共产品和服务，支付准确性对财政健康至关重要。文章评估了利用社会和行为科学 insights 开发的低成本干预措施，如修改表格、优化信息请求方式和沟通方式，以改善联邦项目的支付完整性。评估由美国联邦政府主导。","scd":null,"kp":[]},{"i":38984,"as":"数字平台快速发展带来消费者保护新挑战。美国联邦贸易委员会经济局利用行为学和实证方法防止数字市场不公平商业行为。研究填补了消费者保护领域的认知空白，重点探究消费者对广告披露的感知与反应，以及数字设计选择如何影响消费者报告工具的可访问性和有效性，展示了行为研究在评估潜在补救措施和评估过往政策效果中的作用。","scd":null,"kp":[]},{"i":38985,"as":"行为与决策科学长期支持美国食品药品监督管理局（FDA）的药品监管与公共卫生使命。文章通过四个案例阐述合作：创建指导新药审批的收益-风险框架；启动内部决策支持服务；实施以患者为中心的药物开发计划以加强监管；开发动态系统FDA SOURCE。这些合作协同临床与药学专家，直接影响公众健康选择。","scd":null,"kp":[]},{"i":38986,"as":"文章阐述了行为科学如何支持金融市场政策制定。总结了政策形成过程，并提出科学家与政策制定者互惠互利的框架。以美国证券交易委员会（SEC）的四个研究项目为例：建立针对美国投资者行为的全国代表性调查小组，以及考察共同基金基准、指数挂钩年金和共同基金费用图表等投资者沟通项目。文章最后总结协助科学家将政策影响转化为现实的实践方法。","scd":null,"kp":[]},{"i":38987,"as":"","scd":null,"kp":[]},{"i":38988,"as":"针对逻辑推理与语言的关系，研究采用两种方法系统调查。首先利用功能性磁共振成像观察健康成年人进行逻辑推理任务时的神经活动；其次采用其他互补方法。研究直接探索了复杂思想和语言之间是否紧密相关，验证逻辑推理（包括归纳和演绎推理）是否依赖于自然语言的表征这一假设。","scd":null,"kp":[]},{"i":38989,"as":"研究利用加拿大东部北方森林300公里纵断面204年的火灾历史重建数据，探讨火灾与植被的空间配置如何影响火灾复发间隔。结果表明，大火内部区域（距边缘>8公里）短间隔内复燃的可能性远低于边缘区域（距边缘<2公里）。这表明在大火区域内部，负向火灾-燃料反馈机制得到显著增强，限制了早期植被恢复期间的复燃概率。","scd":null,"kp":[]},{"i":38990,"as":"研究结合鸡胚模型操作、全肠三维成像和短间隔单核转录组学，时间分辨地分析了神经元亚型轨迹。成像显示轴突网络生长高度动态，密度迅速增加且空间取向多样化。转录组学将这些变化与特定轴突导向基因集的细胞状态转变相关联。跨物种分析揭示，人类、小鼠和鸡的肠道谱系轨迹及特定亚型轴突导向程序在整体上具有保守性。","scd":null,"kp":[]},{"i":38991,"as":"在热浪频发的背景下，研究利用遥感地表温度和物种分布图，探究热带树种阻碍光合作用的关键温度阈值。重点分析了热安全裕度（TSM），即临界光合作用温度与最高冠层温度之间的差值在时空上的变化，揭示了热带森林目前面临的温度风险状况。","scd":null,"kp":[]},{"i":38992,"as":"真核生物基因调控依赖于基因在转录活跃与非活跃状态间的随机切换。近期研究在多种基因和生物体中观察到“切换相关时间”（T_C，启动子活动波动自相关函数的特征衰减时间）在不同基因表达水平下具有惊人的不变性。研究指出，这种经验约束对现实的极简转录调控模型提出了严格要求，重现T_C的不变性是模型的关键。","scd":null,"kp":[]},{"i":38993,"as":"","scd":null,"kp":[]},{"i":38994,"as":"动态力学模式化能精确控制血管生成的时空过程。研究开发了一种磁驱动的人体血管芯片平台，在胶原基质内集成可灌注的内皮微通道，能跨越三个空间维度和时间（4D）施加无创且可调的机械刺激。利用自动化3轴驱动器，系统研究了应变幅度等力学因素如何实现对血管发芽的精确时空控制，克服了生化方法不能持续时空递送生长因子的局限。","scd":null,"kp":[]},{"i":38995,"as":"研究提出一种碱热处理（ATT）策略，在低温和常压下将包含PET、PE和PP的混合塑料废物直接转化为清洁氢能，无需预分选。与传统气化不同，NaOH辅助的ATT能显著降低塑料分解温度，同时产出高纯度氢气并最大程度减少碳排放。该技术结合了固碳特性，为混合塑料的高效化学回收提供了直接且高选择性的方案。","scd":null,"kp":[]},{"i":38996,"as":"南极冰架能阻挡冰盖流动，但裂缝形成会降低冰粘度并加速冰排入海洋，削弱其稳定性。研究将物理一致的损伤力学引入冰盖模型，应用于目前南极质量流失最大的阿蒙森海海湾。模拟重现了当前卫星观测到的损伤模式。预测显示，至2300年，允许损伤演变的模型使未来冰损失大幅增加，海平面贡献量最高增加约4.5倍。","scd":null,"kp":[]},{"i":38997,"as":"研究结合高分辨率原位转录组学、组织学、蛋白质组学和功能实验，绘制了出生后第3天至21天小鼠子宫的空间转录组图谱。研究定义了所有主要子宫细胞类型的瞬时出现和空间排列，证实子宫内膜腺体是通过管腔上皮的渐进式转录重编程产生，而非预定的祖细胞群。空间分析进一步揭示了子宫发育过程中复杂的转录网络整合。","scd":null,"kp":[]},{"i":38998,"as":"链霉菌利用小分子控制形态发育和次级代谢，但目前已知的信号分子多为来源于γ-丁内酯（GBL）合成酶的诱导剂。研究鉴定出一种名为烷基恶唑（AOX）的新型信号分子。该分子具有由烷基尾部侧链连接的恶唑头部结构，在链霉菌中对孢子形成和抗生素生产起到下调作用。这为生物合成不同且具负调控功能的信号分子研究提供了新见解。","scd":null,"kp":[]},{"i":38999,"as":"基于2010至2022年具有全国代表性的面板数据，研究考察了外卖平台对中国健康不平等的影响。平台普及增加了低收入群体的超重率，却降低了高收入群体的超重率。这种差异在于低收入者增加油炸食品摄入并将做饭时间转为久坐休闲，而高收入者减少了高热量食物摄入并增加体育锻炼。这些行为改变直接导致了与体重相关的慢性疾病不平等加剧。","scd":null,"kp":[]},{"i":39000,"as":"研究鉴定出组蛋白伴侣HIRA是脂肪组织功能的表观基因组调控因子。在小鼠中敲除脂肪组织特异性Hira基因会损害胰岛素敏感性，并抑制高脂饮食诱导的肥胖过程中的脂肪扩张。机制上，HIRA是脂肪组织中编码脂联素的Adipoq基因及脂质代谢基因表达所必需的。基因组图谱显示，HIRA通过结合这些基因的启动子和增强子促进RNA聚合酶II（Pol II）停顿释放。","scd":null,"kp":[]},{"i":39001,"as":"研究利用挪威近58万名男性的义务兵役认知测试与行政记录，分析了1967至1991年出生队列的弗林效应逆转现象。结果表明，认知测试分数下降的趋势首先出现在高收入父亲的儿子中，而低收入和中等收入群体的峰值出现较晚，且峰后下降幅度较小。这些社会经济地位差异与教育扩张带来的教育水平趋同现象一致，表明教育变化在其中起到了关键作用。","scd":null,"kp":[]},{"i":39002,"as":"针对生物膜感染的治疗难题，研究开发出MZ-8微机器人系统。该系统结合实时人工导航与微环境自主响应治疗，采用仿脊柱结构进行机械破膜，并通过pH响应性ZIF-8涂层释放具有免疫调节功能的Zn²⁺，在近红外二区荧光引导下进行闭环驱动。在假体周围关节感染大鼠模型中，MZ-8有效清除生物膜，通过诱导巨噬细胞向M2型极化实现组织修复。","scd":null,"kp":[]},{"i":39003,"as":"研究发现了癌细胞在氧化应激下协调细胞外囊泡（EV）分泌的应激适应机制。通过生物发光报告系统筛选发现，化合物YM155能广泛抑制肿瘤细胞释放CD63⁺ EV。机制上，YM155使抗氧化转录因子FOXO3a快速失活，降低解毒酶表达，导致应激颗粒（SGs）延迟但持续积累。这些SGs作为RNA分检中心，特异性地抑制了CD63⁺ EV的释放。","scd":null,"kp":[]},{"i":39004,"as":"约2.519亿年前的二叠纪末期快速气候变化引发了地球历史上最大的动物群演替。随着海洋变暖、缺氧和酸化，古生代生物群（如腕足动物）大规模灭绝，现代生物群（如双壳类）崛起。研究利用基于物种代谢氧气平衡的性状模型证实，依赖温度的缺氧症能完全解释不同生物群灭绝强度的差异，证明生理耐受性差异是导致此次生物群更替的核心机制。","scd":null,"kp":[]},{"i":39005,"as":"EIF2AK4（编码GCN2）的双等位基因突变会导致致命的肺静脉闭塞病（PVOD）。为研究GCN2缺陷引发肺血管病理的机制，研究人员构建了两种小鼠模型：一是模拟基因突变PVOD的Gcn2基因敲除模型，二是使用丝裂霉素C构建的药理学模型。通过对野生型和Gcn2缺陷小鼠的肺部进行单细胞RNA测序分析，研究揭示了白介素-6（IL-6）在Gcn2缺陷小鼠肺血管疾病发展中起关键作用。","scd":null,"kp":[]},{"i":39006,"as":"波形蛋白中间丝在维持细胞完整性和调节细胞功能中起关键作用，并与微丝骨架协同参与细胞迁移、分裂和机械感知等依赖于微丝动态的过程。关于两者是否发生直接的蛋白质相互作用一直存在争议。本研究结合体外重构、理论建模和全内反射荧光技术，证实波形蛋白能够通过稳定倒刺端（正端）的ATP-肌动蛋白亚基来促进肌动蛋白的组装，阐明了两者直接相互作用的分子机制。","scd":null,"kp":[]},{"i":39007,"as":"研究通过联合反演近断层强震动、大地测量和远震数据，确定了2025年缅甸MW 7.7级地震的详细破裂过程。破裂在震中附近引发约5米的显著滑移。局部的断层几何复杂性和应力非均匀性导致了小尺度滑动分段和间歇性超剪切破裂。向北的破裂总体处于亚剪切速度，延伸约80公里后迅速停止；向南的破裂则传播约380公里，完全穿透了自1839年以来未破裂的地震空区。","scd":null,"kp":[]},{"i":39008,"as":"面部表情是识别动物内部情感状态的重要窗口。在哺乳动物中，摄入后的口面部反应（如对甜味吐舌头）是公认的积极享乐标志。研究发现，熊蜂同样表现出与哺乳动物在功能上类似的离散口面部反应：面对奖励性溶液时，熊蜂会吐出舌头（舌突起）；面对厌恶性味道时，则会摇头并擦拭口部。这证实了昆虫具备情感评价的能力，并提供了明确的行为标记。","scd":null,"kp":[]},{"i":39009,"as":"","scd":null,"kp":[]},{"i":39010,"as":"研究在土耳其北部黎凡特的Üçağızlı II洞穴发现了尼安德特人（约7.7-5.9万年前）和现代人类（约5.9-4.7万年前）连续居住的证据。人类化石、动植物遗骸、石器和搬运物等综合证据表明，在这两种人类的分类过渡中存在显著的行为和技术连续性。这体现在一致的生存策略，以及对特定非食用贝壳的持续选择和运输。其石制品组合很大程度上符合晚旧石器时代中期的莫斯特传统。","scd":null,"kp":[]},{"i":39011,"as":"公元前218年，汉尼拔率领含有37头战象的大军穿越阿尔卑斯山。学者们经常基于后勤和地形考量对历史路线进行辩论。在阿尔卑斯山口的可能性中，Col du Clapier曾被认为是最佳候选路线。但最新的文献学和地貌学分析指向了Col de la Traversette路线。本研究通过重点关注战象的穿越能量成本进行了分析，结果同样支持Traversette路线，并为了解汉尼拔在后勤和大象战争心理学上的考量提供了见解。","scd":null,"kp":[]},{"i":39012,"as":"","scd":null,"kp":[]},{"i":39013,"as":"","scd":null,"kp":[]},{"i":39014,"as":"","scd":null,"kp":[]},{"i":39015,"as":"","scd":null,"kp":[]},{"i":39016,"as":"","scd":null,"kp":[]},{"i":39017,"as":"基于基因驱动的种群修饰策略正被开发用于控制按蚊传播人类疟疾。该方法旨在通过在媒介种群中传播显性的抗寄生虫效应基因来降低疾病发病率。为产生流行病学影响，这些品系必须长期维持驱动和寄生虫抑制特性。研究表明，在按蚊中构建的携带自主Cas9/向导RNA驱动系统并连接多个抗寄生虫效应基因的三个基因驱动品系（AcTP13、AcTP43和AgTP13），在所有测试中均表现出显著的长期稳定性。","scd":null,"kp":[]},{"i":39018,"as":"人类JC多瘤病毒（JCPyV）会导致免疫缺陷患者患上致命的进行性多灶性白质脑病（PML）。该病毒在PML患者体内常发生突变，在病毒聚糖受体结合位点形成“抗体识别漏洞”，从而逃避抗体反应。研究利用X射线晶体学，研究了从健康捐赠者和PML康复者中分离出的、能够识别一系列PML相关JCPyV变异株的VP1特异性人源单克隆抗体的结合模式。结构分析显示，四种单抗中有三种结合在病毒的特定表位上。","scd":null,"kp":[]},{"i":39019,"as":"本研究提出了一种电可调的宇称-时间（PT）对称磁子激光与反激光机制。该机制基于一个由磁有序平面波导中电流偏置区域组成的器件。在偏置区域内，存在多条携带直流电荷电流的重金属线。该研究为通过电流偏置实现磁性系统中激光与反激光效应的动态调控提供了新方案。","scd":null,"kp":[]},{"i":39020,"as":"在弓激波脉冲星风云附近观测到的丝状X射线结构（如吉他星云、灯塔星云等），以及脉冲星周围存在的慢扩散区域，对标准的宇宙射线传播图像提出了挑战。研究指出，相对论性正负电子对束在磁化星际等离子体中能够实现自约束。该机制成功解释了脉冲星X射线细丝的成因。","scd":null,"kp":[]},{"i":39021,"as":"研究提出了一种精确测量轻过渡元素（原子序数23≤Z≤30）绝对电四极矩的新方法。该方法基于对2s-2p流形（也称为兰姆移位）进行的精密介子X射线光谱学测量。通过测量介子原子中的兰姆移位，研究实现了对过渡元素参考四极矩的高精度确定。","scd":null,"kp":[]},{"i":39022,"as":"研究基于手征有效场理论推导的真实核力，调查了rp-过程等待点核素（氪-72、硒-68和锗-64）的β衰变性质。研究采用了从头算的价空间介质相似重正化群方法。该工作详细计算并分析了这些N=Z原子核的β衰变特性及核子配对相互作用，为理解核天体物理过程中的核合成提供了数据。","scd":null,"kp":[]},{"i":39023,"as":"本研究探讨了致密不对称核物质的状态方程（EoS）对核物质不可压缩性K的敏感性，并评估了其对中子星结构特性的影响。为了单独分离K的效应，研究采用了六种相对论平均场模型。通过对比不同不可压缩性参数下的计算结果，揭示了不对称系统中物质状态方程与中子星宏观结构之间的紧密联系。","scd":null,"kp":[]},{"i":39024,"as":"确定中子星内壳层的超流中子比例对于理解其能否提供足够角动量以驱动脉冲星自转突变至关重要。研究首次采用完全自洽的Hartree-Fock-Bogoliubov理论，计算了超流中子穿过核团簇周期性晶格的流动。计算结果表明，超流比例可高达90%，能够提供充足的超流体角动量储备来驱动脉冲星的自转突变现象。","scd":null,"kp":[]},{"i":39025,"as":"本研究详细评估了使用杰斐逊实验室提出的SoLID装置，通过氦-3靶进行半单举深度非弹性散射（SIDIS）非极化截面测量的潜在影响力。此类测量数据主要在较大Bjorken-x值、中等Q²值和较小动量转移值下收集。研究结果为理解核子内部结构和部分子分布函数提供了关键信息。","scd":null,"kp":[]},{"i":39026,"as":"研究利用有限温度下获得的介子产生率和传播子，探讨了温度如何影响介子-介子散射（即ππ散射和D-D*散射）中的阈值尖峰效应。通过分析不同温度下ππ产生率的线形，揭示了相对论重离子碰撞中强子物质的有限温度环境对强子相互作用阈行为的具体影响。","scd":null,"kp":[]},{"i":39027,"as":"光子对的 femtoscopy（ femtoscopy，全息干涉技术）是研究高能核碰撞的有效工具。由于统计数据的限制，该技术此前很少在实验中得到应用。随着探测器技术的进步，本研究详细探讨了一维、二维和三维光子 femtoscopy 的理论与应用，为未来在重离子碰撞实验中提取时空参数提供了方法指导。","scd":null,"kp":[]},{"i":39028,"as":"研究利用具有动态势能表面的双核系统模型（DNS-DyPES模型），探讨了导致生成超重核鿫-297的重离子聚变反应中的中子-质子比（N/Z）平衡和核子转移动力学。通过研究一系列初始反应体系，揭示了在中能重离子碰撞中，复合系统向N/Z动力学平衡演化的时间尺度及核子转移的详细路径。","scd":null,"kp":[]},{"i":39029,"as":"重离子碰撞中的核子转移反应为探索核结构和反应动力学提供了宝贵见解。这些反应对壳层结构、配对关联和集体激发高度敏感。本研究详细调查了氟-19与钼-100相互作用中的质子剥离转移通道。实验和理论分析的结合为解释此类重离子转移反应的发生机制提供了精确的参数约束。","scd":null,"kp":[]},{"i":39030,"as":"研究利用相互作用玻色子模型（IBM），结合基于微观核密度泛函理论计算的哈密顿顿量参数，分析了八极关联对镭和钍同位素的低能激发态0+态及双中子转移强度的影响。研究表明，八极形变在这些原子核的低能激发和转移反应中扮演着重要角色。","scd":null,"kp":[]},{"i":39031,"as":"基于现代Brueckner-Hartree-Fock（BHF）理论，研究人员开发了用于核子-核子散射的微观光学势（MOP）。该理论在描述对称和非对称核物质的性质方面非常成功。研究对核物质中能量与密度的依赖关系进行了参数化，以构建该微观光学势模型。","scd":null,"kp":[]},{"i":39032,"as":"研究探讨了重离子融合激发函数的新表示方法。在适当的缩放条件下，所有重离子融合激发函数的σE实验谱均表现为水平曲线。这些曲线位于Y轴上，其数值对应于Rg²Wg，其中Rg和Wg是通过单高斯势垒拟合得到的参数。","scd":null,"kp":[]},{"i":39033,"as":"研究利用¹²C(n,n)和⁹Be(n,n)中子散射参考测量，测定了²⁵²Cf自发裂变的瞬发裂变中子能谱（PFNS）。这种裂变释放的中子能量分布几十年来一直被视为中子数据标准，对中子发射反应等核物理测量具有基础性的重要意义。","scd":null,"kp":[]},{"i":39034,"as":"研究人员通过共振吸收法重新测定了¹⁴N中9.17 MeV能级的宽度。光核反应在基础物理和应用物理中具有关键作用，其中¹³C(p,γ)¹⁴N反应提供了一个能量为9.17 MeV的准单能γ射线源，为研究光核反应中的数据差异提供了有效途径。","scd":null,"kp":[]},{"i":39035,"as":"利用连续介质中形变相对论Hartree-Bogoliubov理论（DRHBc），研究系统探讨了钬同位素（中子数N=74–186）的基态性质。研究发现该同位素链存在显著的形变现象，且相较于球形相对论连续Hartree-Bogoliubov理论，DRHBc理论在描述这些性质时表现更佳。","scd":null,"kp":[]},{"i":39036,"as":"基于同位旋相关的Boltzmann-Uehling-Uhlenbeck输运模型，研究系统考察了重离子碰撞中核子-核子（NN）散射截面的介质内效应对核子和π介子观测量的影响。研究采用了由Brueckner-Hartree-Fock理论推导出的微观散射截面进行分析。","scd":null,"kp":[]},{"i":39037,"as":"针对金属修饰硅基光电阴极导致强光反射并限制底层硅光吸收的问题，研究人员通过空间限域策略设计了一种高性能硅基光电阴极。该设计将Pt助催化剂限制在金字塔顶部的Ti保护层，其余区域覆盖SiO2层。这使得光线能穿透并被底层硅吸收，有效抑制了寄生光吸收，从而显著提升了光电阴极的析氢反应性能。","scd":null,"kp":[]},{"i":39038,"as":"为解决核酸提取和缓慢热循环的限制，研究开发了一种用于即时检测的等离激元纳米腔热循环仪（PNT）。该器件集成了金、二氧化硅和金薄膜组成的纳米腔，在白光LED照射下实现了20.4°C/s的快速加热和7.5°C/s的冷却，在269秒内完成40个热循环。PNT与微透镜阵列荧光相机集成，实现了直接实时逆转录PCR。","scd":null,"kp":[]},{"i":39039,"as":"研究阐明了等离激元诱导界面电荷转移在增强拉曼光谱（SERS）和化学反应中的选择性路由机制。研究指出，直接电子转移是控制化学增强机制的核心过程，转移电子的数量和寿命是关键描述符。此外，SERS的化学增强与等离激元介导化学反应的化学界面阻尼之间存在竞争关系，这决定了电子转移的路径。","scd":null,"kp":[]},{"i":39040,"as":"","scd":null,"kp":[]},{"i":39041,"as":"对不稳定原子核⁵⁹Cu的单核子转移反应的研究，探究了天体物理X射线暴中的镍铜循环。快速质子俘获过程模型指出，⁵⁹Cu(p,γ)⁶⁰Zn与⁵⁹Cu(p,α)⁵⁶Ni反应之间的竞争可能导致NiCu循环的形成，从而将物质流限制在特定区域。","scd":null,"kp":[]},{"i":39042,"as":"研究计算了伴随轻子喷注产生的顶夸克对产生过程的高阶QCD（量子色动力学）修正。顶夸克是目前已知最重的基元粒子，该产生过程对研究粒子物理标准模型的性质至关重要，并且对顶夸克质量具有极高的敏感度。","scd":null,"kp":[]},{"i":39043,"as":"通过对GWTC-4引力波数据集的观测分析，多项独立分析结果均证实了引力波信号中存在一个独特的黑洞双星子群。证据表明，这些大质量双星是通过反复并合（即层级并合）形成的，具有明显的重复并合特征。","scd":null,"kp":[]},{"i":39044,"as":"针对引力波观测数据的多项独立分析均证实，并合双星黑洞群中存在由反复并合产生的独特大质量黑洞双星子群。研究进一步指出，在具有不同主质量的双星黑洞系统中，存在三个不同的子群分类。","scd":null,"kp":[]},{"i":39045,"as":"研究计算了广义相对论下两个非自旋体的保守径向作用和散射角，精确度达到牛顿常数的五阶（O(G⁵)），并包含二阶自力效应。该计算在散射振幅框架内完成，且没有采用自力截断，完整包含了引力子对势能的贡献。","scd":null,"kp":[]},{"i":39046,"as":"研究通过比较固定能量和不同碰撞参数下的四组数值相对论模拟，分析了两个孤子玻色子星的引力散射行为。分析采用了有效单体解析描述，综合考虑了引力效应（质点和潮汐）以及短程标量场相互作用的影响。","scd":null,"kp":[]},{"i":39047,"as":"研究探讨了自由概率理论在复杂量子系统中的鲁棒性。该理论用于描述希尔伯特空间遵循最大熵分布的非对易观测量间的相关性。研究重点考察了当系统通过耦合单个量子比特而最小程度地偏离“自由”状态时，该理论框架的适用性和表现。","scd":null,"kp":[]},{"i":39048,"as":"ATLAS合作组利用质心能量为13 TeV的140 fb⁻¹质子-质子碰撞数据，结合多项测量结果，分析了希格斯玻色子与电弱规范玻色子相互作用的CP性质。研究结果基于矢量玻色子衰变通道的观测量，对理解希格斯玻色子的基本物理性质具有重要意义。","scd":null,"kp":[]},{"i":39049,"as":"研究探讨了晶格模型中高阶对称性在何种条件下可实现为“在位对称”。如果通过引入辅助量子比特并进行有限深度电路共轭变换，可将对称性解耦为在位操作，则称其具有此性质。传统观点认为这等价于反常自由，但研究揭示了其在高阶对称性下的新特性。","scd":null,"kp":[]},{"i":39050,"as":"研究提出一种利用液晶乳液滴 quantifying 细菌适应性的新方法。通过将单个细菌细胞捕获在微尺度液晶乳液滴的拓扑缺陷上，细菌的主动运动会导致液滴陷阱发生倾斜和方位旋转，而液滴自身的重力会反向抵抗这种运动，从而形成一场“拔河比赛”，以此实现对细菌动态的快速可靠量化。","scd":null,"kp":[]},{"i":39051,"as":"研究发现室温生长的富铜非晶YBa2Cu3Ox（YBCO）薄膜器件具有新颖的电阻开关行为。通过改变靶材及薄膜中的铜含量，电阻开关机制可以在界面大面积机制和单点细丝机制之间进行调控。此外，改变铜含量还可用于调节器件的其他性能，在神经形态计算领域展现出应用潜力。","scd":null,"kp":[]},{"i":39052,"as":"研究提出一种表面修饰叶酸的交联二硒化物纳米囊泡（FA@cSeLAV），用于治疗急性肝损伤。该纳米囊泡能够有效靶向肝巨噬细胞，将症状层面的活性氧（ROS）消除与内源性ROS产生的抑制无缝结合，解决了现有疗法仅注重清除ROS而忽视抑制其生成的局限性，从而大幅提升治疗效果。","scd":null,"kp":[]},{"i":39053,"as":"研究开发了一种由DNA纳米桥修饰的石墨烯场效应晶体管（g-FET），用于全面评估呼吸道感染。该DNA纳米桥由两个DNA四面体通过链节连接构成。靶标病毒核酸识别会触发链节解离并释放探针，进而检测炎症因子IL-6。这种级联逻辑运算实现了病原体与炎症反应的同时检测，病毒核酸检测限低至3.9 × 10-16 M。","scd":null,"kp":[]},{"i":39054,"as":"研究采用分子/原子层沉积（MLD/ALD）技术调控纳米压印光刻（NIL）模具与光刻胶界面。针对模具断裂和脱模效率低等挑战，基于分子动力学模拟，系统研究了在NIL模具上生长的石墨烯、Al2O3和聚脲模型界面层。该策略主动调节了压印过程中的粘附、摩擦和应力演化，解决了界面力学控制的难题。","scd":null,"kp":[]},{"i":39055,"as":"研究利用脉冲激光沉积技术在SrTiO3基板上制备了250纳米厚的无铅BiFeO3/BaTiO3（BFO/BTO）超晶格。结合高分辨X射线衍射、原子力显微镜和扫描透射电子显微镜分析，揭示了该超晶格薄膜具有高纯度、良好的外延质量及特定的纳米级化学调制。通过调制周期调控，实现了由巨大界面应变梯度驱动的自极化和零偏压压电特性。","scd":null,"kp":[]},{"i":39056,"as":"研究利用角分辨表面增强拉曼散射（SERS）技术，探究了胶体超表面中等离子体-光子杂化模式。通过独立扫描极角和方位角，获取了固定超高数值孔径激发下的色散与简并特性。结合模板辅助自组装技术制备的胶体超表面，研究揭示了纳米颗粒浓度、结构有序度与模式鲁棒性之间的直接相关性，确定了在缺陷下仍具容忍度的低损耗模式。","scd":null,"kp":[]},{"i":39057,"as":"研究通过先驱体转化陶瓷（PDC）工艺制备了一种多孔层状碳化铪陶瓷。HfC熔点接近3900℃，但阻抗匹配差限制了其电磁波吸收应用。该工艺通过破碎并冷冻干燥凝胶先驱体构建多孔微观结构，有效改善了材料的阻抗匹配。这种新型层状HfC陶瓷集成了优异的耐高温性能和高效的电磁波吸收能力，适用于极端环境下的隐身部件。","scd":null,"kp":[]},{"i":39058,"as":"研究制备了一种具有仿珍珠层分级工程界面结构的柔性压电复合薄膜，以解决高压电载荷下响应易饱和的难题。氧化石墨烯片层在准互连压电陶瓷框架与热塑性聚氨酯基体界面处优先排列，形成可承受兆帕级高压缩载荷的机械坚固结构。该结构促进了应力传递和界面极化，使优化的压电薄膜实现了宽范围的压力传感性能。","scd":null,"kp":[]},{"i":39059,"as":"","scd":null,"kp":[]},{"i":39060,"as":"研究提出将二维聚吡咯包覆的二硒化钒（VSe2@PPy）片状纳米复合材料作为锂硫电池正极的高性能硫载体。该设计结合了金属VSe2的高导电性和多硫化物转化催化活性，以及PPy涂层的优异导电网络、吸附能力和机械柔韧性。两者间的界面电子耦合效应构建了功能界面，有效克服了锂硫电池多硫化物穿梭效应及导电性差的限制，实现了稳定的高倍率性能。","scd":null,"kp":[]},{"i":39061,"as":"研究设计了二氧化钛表面修饰的碳纳米颗粒（CNPs@TiO2），以解耦电流变液中极化效率与导电渗流之间的矛盾。富含sp2的类石墨烯碳纳米颗粒提供强本征极化率，而无定形TiO2界面层则限制了长程电荷传输并促进界面极化。结构与化学分析证实了表面无定形TiO2及Ti-O-C界面键的形成。阻抗谱与漏电流测试表明该设计在高电场下实现了高阻抗与低漏电流，维持了电气稳定性。","scd":null,"kp":[]},{"i":39062,"as":"研究将高价态钼掺杂至具有三重传导性能的层状双钙钛矿阴极材料（PBSCF）中，用于质子陶瓷燃料电池（PCFC）。钼掺杂有效促进了氧空位的形成，加速了整体阴极反应。电化学分析显示，氧还原反应（ORR）相关动力学得到显著改善，具体表现为改性材料PBSCFM01的极化电阻大幅降低，在600℃时仅为0.052 Ω·cm2，提升了PCFC的低温运行性能。","scd":null,"kp":[]},{"i":39063,"as":"研究开发了一种集成止血、抗氧化和抗菌特性的多功能水凝胶（CBOS），用于感染和糖尿病溃疡的伤口再生。该水凝胶通过甜菜碱修饰的壳聚糖与氧化海藻酸钠的席夫碱反应制备，并掺入聚乙烯醇和硼酸钠以增强网络稳定性。CBOS水凝胶具有均匀多孔结构、强粘弹性、高溶胀能力和适宜的水蒸气透过率。生物相容性评估证实其细胞毒性极低且血液相容性好，并展现出广谱抗菌能力。","scd":null,"kp":[]},{"i":39064,"as":"研究报道了一种仿生菱形图案二氧化钒（VO2）超表面智能热辐射器件，用于自适应全天候建筑热管理。通过协同调控VO2的金属-绝缘体相变与法布里-珀罗腔及亚波长阵列的共振，该器件在大气窗口（8-14 μm）内实现了0.65的动态发射率调制（0.27至0.92）。仿生结构维持了稳定且极低的太阳能吸收率（0.23），有效抑制了太阳过度加热，解决了冬季被动辐射冷却的过度制冷问题。","scd":null,"kp":[]},{"i":39065,"as":"","scd":null,"kp":[]},{"i":39066,"as":"研究利用脑磁图追踪人类在学习噪声中时间依赖性的神经动态，揭示了两种时间上可分离的学习机制。神经预测活动迅速出现，在刺激呈现前产生特定模式，且早于可测量的行为改善。随后是缓慢的表征变化，表现为非相邻但具有统计依赖性的元素间神经模式相似度增加。这两个过程由分布式的神经协同网络支持。","scd":null,"kp":[]},{"i":39067,"as":"研究沿降水梯度并结合全球数据集，分析了土壤放射性碳、有机质理化组成及微生物碳利用效率。结果表明，随着土壤有机碳（SOC）含量增加，其由放射性碳反映的持久性在区域和全球尺度上均出现下降。高SOC土壤逐渐由年轻、快速循环的碳主导，而非老的稳定碳库。植物碳输入强烈预测SOM持久性，且与更年轻、更短暂的SOC相关。","scd":null,"kp":[]},{"i":39068,"as":"研究通过虚拟导航任务直接测试了环境几何（梯形和正方形）与路线导航顺序对空间记忆的交互影响。结果验证了内嗅网格细胞模型预测的环境几何效应以及路径积分模型预测的顺序效应。关键发现表明，这两种效应以相加方式结合，位置记忆在几何不规则且处于序列特定位置的路线中表现最差，揭示了环境几何对序列路线学习及认知地图整合的影响。","scd":null,"kp":[]},{"i":39069,"as":"研究结合临床分析与小鼠模型，揭示了非小细胞肺癌脑转移对anti-PD-1单药耐药的机制。分析表明，脑转移灶含有较少的细胞毒性T淋巴细胞和三级淋巴结构，呈现免疫排斥表型。与单药治疗相比，纳武利尤单抗联合伊匹木单抗（anti-CTLA-4）显著增强了CD8+ T细胞反应并促进了三级淋巴结构的形成，有效克服了免疫排斥，抑制了脑转移肿瘤的生长并改善了颅内病情控制。","scd":null,"kp":[]},{"i":39070,"as":"研究通过模型模拟和微宇宙实验，量化了生物多样性对生态系统稳定性的净效应。实验将不同浮游植物物种及其组合暴露于温度升高和波动的环境中。结果显示，稳定性作为群落的涌现特性，经常超过组合共存物种的预期稳定性。这表明增加的生物多样性通过各物种间的相互作用，为生态系统提供了显著的额外稳定性净效益。","scd":null,"kp":[]},{"i":39071,"as":"研究确定慢性肿瘤坏死因子-α（TNF-α）信号传导是导致成人海马神经发生障碍的关键驱动因素。利用人类体外神经发生模型、单细胞RNA测序和T细胞迁移实验，证实TNF-α在海马祖细胞中诱导强烈的I型干扰素反应，形成自分泌/旁分泌环。这一过程促进了趋化因子介导的T细胞募集，从而抑制神经发生，揭示了炎症导致神经发生受损的具体机制。","scd":null,"kp":[]},{"i":39072,"as":"研究利用18个欧洲国家的1353个每年采集的河流无脊椎动物时间序列，测试时间分辨率对生物多样性趋势评估准确性的影响。结果表明，将采样频率从每年一次降至每2至6年一次，仅有87%至73%的位点趋势方向一致，且幅度匹配度大幅下降。缩短采样年数同样导致方向与幅度的严重偏差。结论强调高分辨率长期时间序列数据对于准确评估生物多样性变化至关重要。","scd":null,"kp":[]},{"i":39073,"as":"研究证明了星形胶质细胞锚蛋白-2（Ank2）对小鼠海马记忆的持久性至关重要。特异性敲除星形胶质细胞中的Ank2会破坏长期增强作用的维持，导致远期记忆受损而不影响近期记忆。机制上，Ank2的缺失减少了星形胶质细胞与印记神经元的接触，并削弱了由BDNF通过TrkB.T1和IP3R2受体信号传导驱动的星形胶质细胞形态发生。这确立了星形胶质细胞在长期记忆维持中的分子机制。","scd":null,"kp":[]},{"i":39074,"as":"本文提出了一种名为EmulatRx的智能体框架，旨在利用真实世界数据（RWD，如电子健康记录）辅助临床试验设计（CTD）。传统机器学习方法提取真实世界证据（RWE）后，需与领域专家进行大量迭代沟通。EmulatRx通过不同角色智能体间的迭代对话与分析，能够自主完善临床试验方案，并最终生成包含关键信息的稳健报告。","scd":null,"kp":[]},{"i":39075,"as":"研究者开发了一种基于大语言模型的机器学习框架，用于从600家大型欧洲公司（2014-2023年）的企业报告中系统性提取环境、社会和治理（ESG）指标，构建了包含290万条ESG观测值的数据集。该框架依据欧洲可持续发展报告标准（ESRS）评估ESG透明度，并利用提取的数值指标评估ESG表现，揭示了不同ESG评级企业间存在的显著透明度差距。","scd":null,"kp":[]},{"i":39076,"as":"针对使用零价铅（Pb0）合成钙钛矿太阳能电池（PSCs）时难以转化为Pb2+并易产生深能级缺陷的挑战，研究者提出一种自下而上的气相辅助胶体策略。首先使Pb0在特定溶剂中与I2反应，生成高度分散的碘化铅胶体前驱体，随后通过气固反应完全转化为钙钛矿。基于该Pb0前驱体制备的器件在效率和稳定性上均优于商业碘化铅，实现了22.65%的光电转换效率。","scd":null,"kp":[]},{"i":39077,"as":"为解决富镍层状氧化物锂离子电池正极材料在循环过程中的结构不稳定问题，研究者设计了Ti/Sr梯度掺杂与SrTiO3包覆的NCM90正极材料（NCM90-2TS）。Ti/Sr梯度掺杂有效降低了锂离子扩散势垒，缓解了应力应变积累与层间滑移，并抑制了锂镍混排；SrTiO3包覆层则成功抑制了氧负离子外迁，稳定了电极-电解质界面并减轻了副反应。","scd":null,"kp":[]},{"i":39078,"as":"化疗药物紫杉醇通过稳定细胞微管发挥抗癌作用，但会导致患者严重脱发。研究发现，在紫杉醇给药前后特定时间点，短暂暴露于低强度和低频超声波能够瞬间破坏细胞微管和纺锤体，从而消除紫杉醇引起的毛囊损伤和毛发生长抑制。这一发现提供了一种在癌症化疗期间预防脱发、提升患者生活质量的可行物理干预方法。","scd":null,"kp":[]},{"i":39079,"as":"本文将预训练的组织病理学基础模型（hFM）专门应用于侵袭性肿瘤组织，进行扩展预训练以将其转化为富含语义信息的肿瘤专用模型。研究系统评估了模型编码的生物学概念，成功发现了在不同患者间具有一致形态和分子特征的复发性肿瘤原型，并识别出肿瘤内部共存且反复出现的具有异常基因表达程序的显性肿瘤原型，为乳腺癌预后提供了新信息。","scd":null,"kp":[]},{"i":39080,"as":"","scd":null,"kp":[]},{"i":39081,"as":"为解决酶物理吸附固定化易导致酶泄漏和催化寿命短的问题，研究者提出一种基于光响应共价有机框架（COFs）的动态孔径机械锁定策略。通过可见光介导的异构化实现孔径精确可逆变化，从而适应不同酶的限域。该方法使辣根过氧化物酶等酶的截留率提升1.8至9.7倍；机械锁定的甲酸脱氢酶在5次循环后仍保留99.2%的活性。","scd":null,"kp":[]},{"i":39082,"as":"为解决电解海水制氢过程中的盐分渗透和产水量不足的问题，研究者将渗透膜蒸馏（OMD）与碱性水电解（AWE）热共生集成。在双重热梯度和渗透梯度的驱动下，该系统能促进无盐水蒸气传输，连续运行500小时保持稳定，产氢速率达60 kg m–2 day–1。系统利用AWE废热作为OMD的热驱动力，同时OMD为AWE提供冷却，消除了外部加热能耗。","scd":null,"kp":[]},{"i":39083,"as":"本研究利用分子束外延生长的磁性拓扑绝缘体异质结构，展示了非线性输运（包括二次谐波霍尔和非互易纵向响应）中的边界-体态相互作用。研究发现，当样品稍微偏离量子反常霍尔态和轴子绝缘体态时，非线性输运达到最大化。非线性响应的符号和幅度取决于电极配置、磁性有序和载流子类型。该工作揭示了边界模式在非线性输运中的重要作用。","scd":null,"kp":[]},{"i":39084,"as":"为突破析氧反应（OER）分子演化路径的调控难题，研究者提出在全有机电催化剂中构建不对称非金属双活性位点，通过工程化羟基基团触发罕见的非对称氧化物路径机制。该路径降低了传统机制对双活性位点吸附能严格平衡的要求，并打破了吸附物演化机制的线性比例关系限制。所制备的无金属电催化剂表现出优异的OER性能，过电位为364.3 mV。","scd":null,"kp":[]},{"i":39085,"as":"针对商用双轴取向聚丙烯介电薄膜在高温下能量密度低、效率差的问题，本研究通过在聚醚亚胺（PEI）骨架中引入一系列萘四甲酸二酐，协同调控了电荷陷阱与二面角，有效提升了PEI的击穿强度。优化后的介电薄膜在200°C高温下，充放电效率达到一定标准的同时，实现了6.00 J cm−3的放电能量密度，展现出在恶劣环境中的应用潜力。","scd":null,"kp":[]},{"i":39086,"as":"散射奇异点（EP）将波控制应用于输入输出响应中，但其拓扑在稳态下难以展现。本研究将散射视为时空演化的过程，建立了从动量-频率域到空间-时间域的跨域映射，将静态EP与动态散射奇点联系起来。通过将酉散射矩阵投影到低维子空间，成功将EP拓扑结构以时空波包的形式印刻到波包中，从而解析了散射奇异点的时空动力学特征。","scd":null,"kp":[]},{"i":39087,"as":"针对工业烟道气中CO2浓度低且富含O2导致电化学还原效率受限于寄生氧还原的问题，研究者提出一种直接反应捕获（DRC）策略。通过在中等压力下使用二元溶剂有机电解质，将近似定量的法拉第效率转化CO2为CO。研究指出氢键供体能力（HBD）是控制竞争反应的关键参数，使用低HBD电解质可破坏氢键网络，有效抑制竞争反应，实现选择性转化。","scd":null,"kp":[]},{"i":39088,"as":"为开发在远红光激发下产生高效蓝光发射的无金属三重态-三重态湮灭上转换系统，研究者在五次甲基花青骨架的中位引入吸电子基团。该设计缩窄了单三重态能隙，抑制了光异构化并促进了系间窜越，使该分子获得了比未取代物更高的三重态能级。其中，基于中位半花青的敏化剂在与苝配对后，有效延长了激发波长，实现了巨大的反斯托克斯位移和高效蓝光发射。","scd":null,"kp":[]},{"i":39089,"as":"针对红色簇发光器件（CLED）因非辐射弛豫导致效率低的问题，研究者精准优化了双锥体[PXZDPPQ]2Cu4I4的激发态。其配体结合了共轭延伸的膦醌和强给电子的吩恶嗪，形成了具备核外配体电荷转移（nLCT）特征的第一单线态和三线态，以及高能位的内核金属配体电荷转移态。这种高度辐射的nLCT状态在载流子捕获和激子利用上具备空间和能量优势，使器件外量子效率突破40%。","scd":null,"kp":[]},{"i":39090,"as":"本文提出了一种利用接触起电（CE）在固液界面生成自由基的无金属催化途径。通过在盐水中超声驱动氟化乙烯丙烯（FEP）颗粒的接触分离，生成了羟基和氯自由基，进而产生次氯酸和次氯酸根等活性氯物质，且不产生可检测的氯气。使用天然海水时，该策略实现了208.8 μmol g−1 h−1的活性氯产率，利用环境机械能即可实现卤水到含氯消毒剂的转化。","scd":null,"kp":[]},{"i":39091,"as":"针对酸性CO2还原反应（CO2RR）中析氢反应（HER）严重、盐易沉淀的问题，本研究将阳离子碳纳米管（CCNTs）作为通用添加剂引入强酸电解液中。使用铋、银和氧化铜催化剂，在pH≤1的环境下，分别实现了生成甲酸、CO和乙烯的95%、100%和67%的法拉第效率。CCNT添加剂克服了有机阳离子质子屏蔽差的缺陷，实现了选择性酸性CO2RR。","scd":null,"kp":[]},{"i":39092,"as":"本研究基于相变材料集成的超表面，提出了一种可扩展的二维架构，实现了首个透射式中红外幅度型空间光调制器。该器件采用标准硅光子铸造工艺结合后端集成（BEOL）制造，利用多层后端金属互连实现交叉寻址方案。每个像素集成了硅二极管选择器以抑制潜行路径电流，这对于大规模阵列扩展至关重要，成功实现了动态光控制。","scd":null,"kp":[]},{"i":39093,"as":"为解决二维（2D）晶体管中介电材料集成的挑战，研究者成功生长出毫米级、厚度均匀的大面积单晶三氧化钼（α-MoO3），并将其作为范德华（vdW）介电材料应用于2D场效应晶体管。测试表明，单晶MoO3具有约18.5的高介电常数，在3.0 MV cm−1电场下栅极漏电流极低（约10−2 A cm−2），且具备约26.75 MV cm−1的高击穿场强。","scd":null,"kp":[]},{"i":39094,"as":"针对一锅法CRISPR诊断中等温扩增与CRISPR激活消耗底物之间的动力学不兼容问题，本研究通过DNA引物的热力学设计实现了反应顺序编程。利用引物结合强度的差异创建两个连续扩增阶段，在不需物理分离的条件下延缓CRISPR激活，直到积累足够的扩增子。该设计还通过引物引入PAM序列，在保持单核苷酸分辨率的同时扩大了靶标可及性。","scd":null,"kp":[]},{"i":39095,"as":"本研究报告了一种通过参数泵浦产生磁子自激振荡的新机制。通过在钇铁石榴石延迟线中施加泵浦信号激励传播自旋波，四波混频将泵浦模式转换为两个相位自治的传播磁子模式：波数约为泵浦模式两倍的自发模式和波数趋近于零的闲置模式。该机制能够可靠地产生具有宽泛频率可调性的超尖锐自旋波动态。自发模式可以像自振荡器一样与探测信号实现锁相。","scd":null,"kp":[]},{"i":39096,"as":"本研究提出了一种利用具有高消光比和超窄带宽的双折射诱导相位延迟滤波器的方法，用于测量覆盖0.1至3500 cm−1的完整振动光谱。该滤波器能有效抑制激光频率附近的强弹性散射。这种多模态、无标记的分析方法能够同时获取布里渊散射、超低频拉曼和拉曼光谱，从而通过分析不同频率范围的完整振动光谱，同步提取样品的力学、结构和化学特性。","scd":null,"kp":[]},{"i":39097,"as":"研究在水稻中发现了GC偏向性基因转换的经验证据。非编码区的GC含量与重组频率高度相关，而编码区的GC含量则同时受到重组和对翻译效率有利的富GC密码子的选择作用影响。水稻及其部分异交野生祖先的GC含量均出现下降，没有证据表明完全异交会导致GC含量净增加。这表明相关突变对基因组的影响不同于传统的gBGC随异交增强的模式。","scd":null,"kp":[]},{"i":39098,"as":"研究鉴定了一种在水稻胚乳中特异表达的MYB转录因子OsMYB4，它对调控水稻的产量和品质至关重要。功能丧失会导致谷物垩白增加，直链淀粉和蛋白质含量减少，并降低产量。OsMYB4直接结合在淀粉和贮藏蛋白合成相关的多个基因启动子上激活转录，并与其他转录因子形成蛋白复合物，协同调控胚乳中淀粉和贮藏蛋白的合成。","scd":null,"kp":[]},{"i":39099,"as":"研究利用冷冻电镜技术解析了人源质子偶联氨基酸转运蛋白1（hPAT1）的apo状态及其与D-丝氨酸、哌啶酸和D-环丝氨酸三种底物复合物的结构（分辨率为3.4至3.5 Å）。尽管这些配体具有化学多样性，但它们均采用空间上趋同的结合模式。这些结构阐明了hPAT1的底物识别机制以及其介导氨基酸肠吸收和溶酶体 export 的转运机制。","scd":null,"kp":[]},{"i":39100,"as":"研究揭示了拟南芥中仅含富亮氨酸重复序列蛋白的基因（LRIP1）的等位基因变异在抵御不同病原体中的双重作用。常见于干旱地区的等位基因通过水杨酸信号通路赋予对丁香假单胞菌的抗性；而富集于高降水地区的等位基因则通过camalexin生物合成保护植物免受灰葡萄孢菌侵害。两个等位基因在启动子和编码序列上的差异共同调控了这种基因表达和病原体抗性分化。","scd":null,"kp":[]},{"i":39101,"as":"研究开发了一种智能DNA纳米器件（DND），将多价识别、逻辑门计算和精确给药整合在单一纳米结构中。该器件由携带阿霉素的DNA四面体框架（tFNA@Dox）通过三个变构适配体臂连接到胆固醇修饰的膜锚定物组成。当三个适配体同时结合目标细胞表面受体时，触发“与”逻辑门，在靶细胞膜上精确释放tFNA@Dox。这种局部的传感与作用机制最大化了治疗的特异性。","scd":null,"kp":[]},{"i":39102,"as":"研究确定白细胞介素-6（IL-6）是调控小鼠滤泡调节性T细胞生成的关键调节因子。IL-6信号通过诱导C/EBPα结合Tfr细胞中的Bcl6和Cxcr5启动子，促进调节性T细胞分化为Tfr细胞。在小鼠中特异性敲除C/EBPα会损害Tfr分化，导致生发中心反应过度活跃，并加剧系统性红斑狼疮（SLE）和过敏模型的病理表现。体外计算扰动实验证实了该机制在人类中具有一致性。","scd":null,"kp":[]},{"i":39103,"as":"研究结合单细胞mRNA测序、抗原受体测序、16S rRNA基因分析和空间转录组学，分析了原发性硬化性胆管炎合并溃疡性结肠炎（PSC-UC）与普通溃疡性结肠炎（UC）患者结肠活检样本的差异。结果显示，与健康对照组和普通UC相比，PSC-UC患者的结肠具有明显独特的区域特异性黏膜拓扑结构。此外，研究揭示了这两种疾病之间共享的一种肥大细胞状态。","scd":null,"kp":[]},{"i":39104,"as":"研究利用大规模森林生物多样性实验数据，探讨了植物-草食动物系统中时间稳定性从种群到群落和集合群落的跨营养级缩放机制。研究发现，生物多样性在营养级内部和营养级之间通常具有稳定作用。草食动物的物种多样性对其自身群落产生稳定作用，而自下而上的营养级相互作用同样对维持整个系统的生态稳定性起着关键作用。","scd":null,"kp":[]},{"i":39105,"as":"研究开发了一种无需饲养层的确定培养体系，能在12天内将启动态人类多能干细胞高效转化为初始态。多组学分析表明，转化过程伴随着染色质重塑（OCT/KLF基序开放，ZIC/RFX/NFκB位点关闭）及特定miRNA的表达改变。功能实验证实，炎症转录因子NFκB/RELA通过激活IKBKE和VEGFR1等基因阻碍了初始态的诱导，而精准抑制该通路可有效促进向初始态多能性的转化。","scd":null,"kp":[]},{"i":39106,"as":"为了解决神经网络中的权重对称性约束与局部计算之间的“权重传输问题”，研究提出了一种基于脉冲的对齐学习规则（SAL）。这是一种利用噪声进行权重对齐的突触局部学习规则。SAL可以与其他功能性学习规则同时运行，在学习过程中维持必要的连接对称性，从而确保梯度的正确局部表示。该规则有效缓解了模拟物理神经网络的神经元和突触变异性引起的差异。","scd":null,"kp":[]},{"i":39107,"as":"研究提出了一种机制驱动策略，通过简单的热处理调控局部化学秩序来增强高熵陶瓷的电磁波吸收能力。应用于高熵碳化物时，该策略实现了创纪录的11.2 GHz有效吸收带宽。原子级化学图谱与理论模拟表明，是局部化学秩序而非原子空位主导了电磁波吸收机制。该策略在高熵氮化物等其他材料体系中同样适用。","scd":null,"kp":[]},{"i":39108,"as":"为了实现高比能锂金属电池，研究提出了一种介质增强的电解液设计策略。通过定量分析不同溶剂类别的极性指数，发现溶剂介导方法能够在纳米尺度上通过分离溶剂表面电荷产生分子间静电场。这种静电场增强了分子间相互作用，从而更好地容纳溶剂化锂离子，并降低了还原反应能垒，有效促进了界面的形成。","scd":null,"kp":[]},{"i":39109,"as":"研究通过合理设计可电离脂质的结构，开发了一种针对肿瘤酸性的可激活溶瘤脂质纳米颗粒。通过系统改变烷基尾部长度和数量的脂质体库筛选，发现总尾碳数与其pH依赖性细胞毒性呈明显相关。这种纳米颗粒将离子化脂质的膜破坏活性选择性地限制在酸性肿瘤微环境中，利用其pH响应特性实现肿瘤选择性的溶瘤治疗。","scd":null,"kp":[]},{"i":39110,"as":"针对癌症纳米药物中组织深度穿透与长期保留难以平衡的瓶颈，本研究开发了一种不依赖特定刺激的可变形纳米光敏剂（SITNPS）。该光敏剂以纳米球的形态穿透肿瘤，随后逐渐转化为纳米棒，从而延长在肿瘤内的滞留时间。SITNPS可通过双光子激光或智能手机闪光灯激发，且单次给药后即可进行多次光照治疗，为更实用的癌症光动力治疗开辟了途径。","scd":null,"kp":[]},{"i":39111,"as":"多金属增材制造能够将不同金属整合为具有特定位置性能的单体构件。本文综述了控制异质界面形成的热力学互溶规则，阐明了金属间化合物、气孔和元素偏析等缺陷的起源，并揭示了界面-微观结构-性能之间的关联。文章建立了一个包含兼容性评估、工艺决策和缺陷控制的系统框架，为多金属3D打印结构的工业化奠定了材料科学基础。","scd":null,"kp":[]},{"i":39112,"as":"《能源与环境科学》发表的一篇文章提出了一种亚纳米级钌团簇催化剂，旨在提高阴离子交换膜水电解槽中绿氢的生产效率。","scd":null,"kp":[]},{"i":39113,"as":"《环境科学与技术》发表的一篇文章对肯尼亚的绿氢生产进行了建模研究。","scd":null,"kp":[]},{"i":39114,"as":"研究提出了一种利用接触生电（CE）产生的电场引发的静电极化策略，以提升接触电催化中单原子催化剂的性能。以Ru1/SiO2为例，通过对SiO2基底进行氟化处理增强其接触生电能力，使析氢产率提升了7.62倍。性能提升主要归因于氟化处理加速了水分解过程，并建立了强电场以改善随后的还原反应动力学。","scd":null,"kp":[]},{"i":39115,"as":"研究人员开发了一种小分子添加剂，解决了在普通空气中制造高性能钙钛矿太阳能电池的难题。该添加剂在初期引导晶体生长，并在退火过程中稳定材料结构，使得器件能够在手套箱外高效制备。这种添加剂设计同时控制了加工过程和材料稳定性，为实现低成本、可扩展的钙钛矿太阳能电池制造提供了实用路径，最终实现了接近27%的光电转换效率。","scd":null,"kp":[]},{"i":39116,"as":"本文综述了原位光学表征技术在钙钛矿结晶过程中的发展与实际应用。原位光学技术作为一种强大的工具，能够实时探测成核、相演变以及中间态的形成。该综述系统性地概述了如何利用原位光学方法研究钙钛矿结晶机制，旨在为研究人员提供一份全面的技术指南，以深入了解并优化钙钛矿材料的结晶过程。","scd":null,"kp":[]},{"i":39117,"as":"研究人员通过结构导向设计，开发出一种富含环己基的有机结构导向剂，成功稳定了末端BEA构建单元，合成了新型二维大孔高硅前体JU-67。通过煅烧处理，JU-67发生了拓扑转变，转化为名为JU-68的新型三维大孔高硅沸石。这一2D到3D的拓扑缩合反应突破了传统合成的局限，为催化和分离大分子提供了具有稳定三维互连大孔通道的新型工业级沸石材料。","scd":null,"kp":[]},{"i":39118,"as":"研究开发了首个结合光化学卤原子转移（XAT）和镍介导的类氮烯转移的直接催化平台，实现了从简单氟化原料直接制备α-三氟甲基酰胺。在温和条件下，易得的α-溴代三氟甲基烷烃与二氧唑酮偶联，成功在α-CF3中心构建C(sp3)-N键，具有广泛的官能团兼容性。该催化体系还进一步实现了三组分烯烃的三氟烷基酰胺化反应，机理研究证实其涉及光化学产生的α-CF3烷基自由基。","scd":null,"kp":[]},{"i":39119,"as":"","scd":null,"kp":[]},{"i":39120,"as":"为提升从稀废水中光催化提取铀的效率，研究人员利用三种同分异构共价有机框架模型，探究了吸附基团与光催化位点的空间关系。结果表明，位点解耦的TpBpy6架构有效抑制了UO22+捕获与氧还原反应之间的相互干扰，维持了原位光催化生成H2O2的过程，并成功将捕获的UO22+连续转化为不溶性的studite相，证实了空间解耦设计在捕获-转化体系中的协同优势。","scd":null,"kp":[]},{"i":39121,"as":"连续体机器人能够通过连续变形实现弯曲和扭转，具备适应复杂环境的能力，未来有望广泛应用于现代社会基础设施的检查与维护。然而，在实际应用落地之前，仍需解决多项关键工程技术挑战，包括力的施加、形状估算、系统鲁棒性以及具备接触感知的控制能力，以确保机器人在复杂基础设施中发挥实质性作用。","scd":null,"kp":[]},{"i":39122,"as":"为克服常温电化学固氮的动力学惰性及析氢副反应，研究构建了集成等离子体-电解的膜电极组件，将微结构非热表面放电直接耦合至气体扩散阴极，原位生成并向催化界面输送振动激发态氮气。在筛选的14种金属催化剂中，银（Ag）表现出最佳的活性与选择性平衡。在室温和大气压下，该系统实现了7.7 ± 0.8 nmol s-1 cm-2的氨产率和86 ± 14%的法拉第效率。","scd":null,"kp":[]},{"i":39123,"as":"I型光引发剂在光照下发生裂解产生活性物种，被广泛应用于光聚合和光驱动3D打印。然而，复杂的环境因素导致不同研究间的结果难以重复，且缺乏标准化协议来直接比较光引发剂的性能。该研究讨论了光引发剂性能评估的最新进展，并提出了一种适用于光裂解、光聚合和3D打印的可比性反应性框架。","scd":null,"kp":[]},{"i":39124,"as":"利用高分辨率旋转光谱和量子化学计算，研究解码了N,N-二乙酰氧基胺（DEAcA）在多官能团分子早期溶剂化过程中的位点选择性机制。孤立单体偏好由偶极矩最小化驱动的syn构型。而在微溶剂化（结合1-3个水分子）时，体系表现出对高碱性sp3氮位点的绝对偏好。14N核四极矩耦合（NQC）常数提供了直接的实验证据，证明水分子溶剂网络的构建主导了水合位点的选择。","scd":null,"kp":[]},{"i":39125,"as":"利用同步辐射原位掠入射广角X射线散射（GIWAXS）技术结合分子模拟，研究揭示了氟芬那酸溶液在气液界面处的成核机制及其对晶型选择的控制作用。研究观察到显著的浓度依赖性多晶型现象：低浓度有利于晶型I成核，高浓度产生晶型III，中间浓度则选择性生成亚稳态晶型IV。原位GIWAXS直接解析了界面前驱体组件的形成与演化，揭示了与特定晶型出现密切相关的三种截然不同的界面分子演化路径。","scd":null,"kp":[]},{"i":39126,"as":"在名为USTB-35-Cu的二维单晶共价有机框架（COF）中，研究人员发现了异常的多步电荷转移机制。通过连续旋转电子衍射与理论模拟解析，该晶体包含交错堆积的铜卟啉与苝二酰亚胺（TFPDI）层。在形成光致供体-受体电荷分离态后，激发态的TFPDI阴离子自由基将光生电子依次转移给周围的卟啉基团。该发现成功在人工光催化体系中复现了类似自然光合作用的多光子与多电子氧化还原化学过程。","scd":null,"kp":[]},{"i":39127,"as":"为打破钌催化氨分解反应中面临的Sabatier限制（难以同时满足NH3强吸附与*H、*N弱吸附），研究通过动态调控催化剂的自旋状态提供了新方案。实验表明，在交变磁场（AMF）下运行的自热铁磁Ru/Fe3O4催化剂，能够通过催化剂的低自旋和高自旋态转换缓解反应中间体的吸附矛盾。该机制有效克服了传统单一吸附能的限制，显著提升了氨裂解制氢的催化效率。","scd":null,"kp":[]},{"i":39128,"as":"","scd":null,"kp":[]},{"i":39129,"as":"研究首次在成分为Au-Cu-Al-In-R（R = Gd, Tb, Dy）的多组分合金体系中，成功制备出块体、可退火的铁磁性二十面体准晶体。摒弃了以往依赖快速淬火的亚稳态制备方法，研究人员通过化学组分设计和常规电弧熔炼结合控制退火，获得了具有锐利准周期衍射和优异热稳定性的单相准晶。这一突破为定量研究准周期系统的铁磁性临界行为及结构精化提供了切实可行的材料基础。","scd":null,"kp":[]},{"i":39130,"as":"","scd":null,"kp":[]},{"i":39131,"as":"","scd":null,"kp":[]},{"i":39132,"as":"一款名为“Humanizer”的工具引发了科学界的担忧。该工具能够引导文本生成系统自动删除研究论文和基金申请书中常见的人工智能生成文本特征。这种擦除AI写作痕迹的功能使得AI生成内容更难被检测出来，给学术界的原创性和学术诚信审查带来了新的隐患与挑战。","scd":null,"kp":[]},{"i":39133,"as":"为扩大全球关键矿物的获取渠道，文章提出建立专利池和授权架构机制。该架构能够通过技术共享和专利授权，促进核心矿物技术在全球范围内更广泛、快速的应用，其实际推广效果和普及速度将优于仅依靠数十年采矿业和冶炼业的传统基础设施投资，从而有效缓解关键矿物资源短缺与供应链瓶颈问题。","scd":null,"kp":[]},{"i":39134,"as":"在进化特征迥异的不同动物群体中进行的移植实验，揭示了动物发育过程中组织组织机制的高度保守性。以栉水母（comb jellies）为研究对象，实验发现了其体内存在控制身体发育模式的组织者。这一发现为理解动物躯体规划机制的演化起源及共同祖先的发育特征提供了重要的生物学证据与线索。","scd":null,"kp":[]},{"i":39135,"as":"哈勃太空望远镜凭借其独特的观测视野和广泛的公众支持，在人类探索宇宙的进程中持续发挥着关键作用。为了防止该轨道天文台设备老化导致退役，一场旨在提升或修复哈勃望远镜的“拯救行动”已正式启动，以确保其能继续为天文学研究提供不可替代的观测数据。","scd":null,"kp":[]},{"i":39136,"as":"文章强调维持哈勃和詹姆斯·韦伯太空望远镜继续运行的科学价值远超其维护成本。作为两项里程碑式的太空观测合作项目，它们目前正在产出超乎大多数天文学家预期的科学发现。持续的资金投入和技术支持对于保障这些望远镜的生存及其未来的深空科学产出至关重要。","scd":null,"kp":[]},{"i":39137,"as":"大规模科学研究深入探讨了预防痴呆症的有效干预手段，重点分析了饮食、运动和社交活动对大脑健康的潜在保护作用。这些雄心勃勃的研究得出了部分令人意外的结论，为基于科学证据制定痴呆症预防策略和生活方式调整提供了重要且真实的参考依据。","scd":null,"kp":[]},{"i":39138,"as":"导电二维金属有机框架Cu3(HHTATP)2通过实现电压分离的Zn2+和H+顺序存储，有效解决了酸性水系锌离子电池中H+诱发的副反应问题。该材料具有多位点氧化还原化学特性，其悬挂胺基上可逆的H+介导胺/亚胺转化，不仅抑制了层状双氢氧化物相关的干扰，还赋予了电池高容量、快速离子扩散速率和卓越的倍率性能。","scd":null,"kp":[]},{"i":39139,"as":"本研究展示了一种用于水系电池的转化型钒氧化还原反应。OH−介导的化学活化促使V-O键断裂，推动单电子嵌入反应向四电子转化反应转变。通过量身定制的介孔结构富集局部OH−，实现了V2O3与Na3VO4之间的可逆转化。该转化负极具有高达700 mAh g−1的比容量，容量保持率为98%。","scd":null,"kp":[]},{"i":39140,"as":"","scd":null,"kp":[]},{"i":39141,"as":"","scd":null,"kp":[]},{"i":39142,"as":"","scd":null,"kp":[]},{"i":39143,"as":"","scd":null,"kp":[]},{"i":39144,"as":"","scd":null,"kp":[]},{"i":39145,"as":"本期Nature档案回顾了科学史上的两个发现：一是第二轻元素（氦）首次被固化为固态的科学记录；二是关于秘鲁存在古老盐湖的证据。","scd":null,"kp":[]},{"i":39146,"as":"脑毛细血管内皮细胞的Kir2.1通道在神经血管耦合中起关键作用，其被神经元活动衍生的细胞外K+激活，启动血管舒张电信号。Kir2.1通道的功能依赖脂质辅因子PIP2的持续产生。在小鼠脑小血管病模型中，该通道功能受损，表明内皮细胞Arf6通过依赖PIP2的机制激活Kir2.1通道，从而维持大脑电信号传导和脑血流。","scd":null,"kp":[]},{"i":39147,"as":"研究提出了一个二元极简模型，以探究超离子导体中亚晶格熔化和快速离子传输的微观机制。该模型包含刚性宿主晶格和软载流子亚晶格。分子动力学模拟证实了结晶、亚晶格熔化和完全熔化三种动力学状态，载流子运动在亚晶格熔点附近表现出强烈的非谐振和动态异质性。","scd":null,"kp":[]},{"i":39148,"as":"研究揭示了非计划性冲动（NPI）与拖延症之间存在共同的神经遗传学基础。基于纵向双胞胎队列及两个横断面队列的数据分析表明，青春期晚期至成年早期的NPI可前瞻性地预测后期的拖延行为。双胞胎模型分析证实，这种关联受到加性遗传因素的显著影响，解释了拖延症适度遗传的生物学特性。","scd":null,"kp":[]},{"i":39149,"as":"通过对全球102个混合森林群落中的281种木本植物的非结构性碳水化合物（NSC）进行跨物种综合分析，研究发现NSC浓度偏差具有系统发育信号。针叶裸子植物和常绿物种在多个器官中始终维持着特定的NSC水平。可溶性糖和淀粉受不同性状控制的发散性，构成了树木碳水化合物储存的全球性策略基础。","scd":null,"kp":[]},{"i":39150,"as":"艰难梭菌的鞭毛蛋白具有独特的Type A糖型结构，由O-连接的N-乙酰-β-d-葡糖胺通过磷酸二酯键与N-甲基-L-苏氨酸结合而成。研究通过识别细胞中间体，鉴定出由四个基因编码的专属酶组合，这些酶负责合成上述糖基化后的修饰结构（PGM），对细菌表面蛋白功能及病原体毒力至关重要。","scd":null,"kp":[]},{"i":39151,"as":"导致慢性中枢神经系统感染的人类麻疹病毒（MeV）和动物麻疹病毒属（包括犬瘟热病毒CDV、海豚麻疹病毒DMV等）毒株，在各自宿主中持续感染数年。研究分析表明，这些能在中枢神经系统长期潜伏并引发类似亚急性硬化性全脑炎（SSPE）慢性疾病的跨物种麻疹病毒毒株，共享着关键的基因型和表型特征。","scd":null,"kp":[]},{"i":39152,"as":"研究发现海马体中存在一种依赖星形胶质细胞的跨区域超可塑性机制。在海马体CA1区多形层（SO）施加启动刺激，不仅能抑制邻近腔隙层的长时程增强（LTP），还能在体内和体外实验中跨过海马裂抑制齿状回中分子层（MML）的LTP诱导。这种效应在缺乏CA3区域时依然存在，证明了一种逆向且长距离的海马交互作用。","scd":null,"kp":[]},{"i":39153,"as":"气候变化正改变动物的繁殖时间，但不同种群对变暖的响应轨迹存在显著差异。以广泛分布的食虫鸟类为研究对象，研究发现，尽管不同种群对温度的敏感性及响应相似，但其种群数量的发展轨迹却出现分化。这表明除了对温度变化的响应之外，其他因素决定了某些种群能否跟上气候变暖的步伐。","scd":null,"kp":[]},{"i":39154,"as":"海洋环境中的细菌通过物理聚集形成群体，以获取难降解底物、增强抗逆性并减少捕食。研究运用基于大小的接触理论发现，细菌群体的大小直接影响其与营养颗粒和裂解噬菌体的接触率。以海洋细菌Vibrio splendidus 12B01进行的实验证实，较大的群体在获取颗粒状资源方面更具优势，物理接触迫使细菌在群体一致性形成与群体规模之间面临权衡。","scd":null,"kp":[]},{"i":39155,"as":"感觉神经元之间的共享变异性在感知能力提升时会降低。研究提出，这种低维度的共享变异性反映了大脑回路结构，并揭示了传递给下游区域的信号信息。通过电路模型和多区域神经群体记录分析证实，当感觉信号与共享变异性对齐时，会在不损害编码保真度的情况下，有效放大与行为相关的信息。","scd":null,"kp":[]},{"i":39156,"as":"使用果蝇脑癌模型研究发现，肿瘤细胞与皮层胶质细胞之间存在双相动态相互作用。在早期阶段，胶质细胞渗入肿瘤，展现出独特的转录特征并抵抗肿瘤生长；随后，肿瘤细胞通过细胞竞争机制克服了宿主组织的阻力，从而加速肿瘤在成体中的恶性增殖。该研究揭示了细胞竞争在突破微环境阻碍并促进肿瘤生长中的关键作用。","scd":null,"kp":[]},{"i":39157,"as":"以自然果蝇种群为模型，研究发现线粒体-细胞核基因组不匹配会加速年龄相关的线粒体衰退，增加活性氧（ROS）的产生，并缩短寿命。然而，通过饮食调节在生命早期诱导的线粒体应激（毒物兴奋效应干预），能够有效抵消上述不良影响，促进线粒体稳态并延长寿命，揭示了基因组间互作对衰老轨迹的塑造作用。","scd":null,"kp":[]},{"i":39158,"as":"前庭神经节神经元（VGN）是维持视觉稳定和姿势平衡的关键初级感觉神经元。利用单细胞和空间转录组学，研究定义了五种在神经节中具有离散空间分布的转录学独立VGN细胞类型。这些细胞类型表现出器官特异性的神经支配模式，靶向每个器官内的特定区域，并形成特征性的突触末梢。研究还开发了选择性标记各类细胞的遗传工具，以探究其具体功能。","scd":null,"kp":[]},{"i":39159,"as":"在拟南芥受精卵极性生长和不对称分裂过程中，丝裂原活化蛋白（MAP）激酶级联通路发挥核心作用。研究证实，三种BSU1-LIKE（BSL1-3）磷酸酶是该信号级联的正向调节因子。BSL1-3功能缺失会导致与YODA MAPK信号通路缺失极度相似的非极性胚胎缺陷。这一功能独立于油菜素内固醇信号通路，且其家族创始成员BSU1在该过程中并非必需。","scd":null,"kp":[]},{"i":39160,"as":"在光胁迫下，莱茵衣藻叶绿素合成的受阻与镁螯合酶H亚基（CHLH1）的降解有关，而GUN4蛋白及其藻蓝胆素（PCB）配体的缺失会加剧这一过程。研究表明，缺乏GUN4或血红素加氧酶HMOX1的细胞会积累镁螯合酶的底物原卟啉IX（PPIX）。GUN4通过与植物胆色素形成共价加合物，在叶绿素生物合成中发挥光保护机制，防止强效单线态氧发生器的积累。","scd":null,"kp":[]},{"i":39161,"as":"为量化人类皮层神经元独特形态和生理特性对认知能力的贡献，研究提出了功能复杂性指数（FCI）。这是一种基于深度学习的通用框架，用于评估神经元的输入输出复杂性。通过比较人类与其他物种（如啮齿动物）皮层锥体神经元的FCI，证实人类神经元复杂的树突形态及其非线性突触特性显著增强了单个神经元的功能复杂度。","scd":null,"kp":[]},{"i":39162,"as":"自身免疫性葡萄膜炎是一种由视网膜血管内皮细胞（ECs）激活和白细胞浸润引起的炎症性疾病。通过定量蛋白质组学筛选337种萜类化合物，研究发现小分子化合物木香烃内酯（COS）能够有效抑制TNF-α诱导的视网膜内皮炎症。COS通过特异性靶向USP15蛋白，下调内皮细胞中的粘附分子表达，从而阻断T细胞的外渗，显著缓解实验性自身免疫性葡萄膜炎（EAU）的疾病进程。","scd":null,"kp":[]},{"i":39163,"as":"HIV-1病毒衣壳在进入细胞核前需穿过核孔复合物（NPC），此过程依赖病毒衣壳（CA）与核孔蛋白（NUPs）内的苯丙氨酸-甘氨酸（FG）重复序列的直接相互作用。研究表明，HIV-1衣壳与NPC不同区域分布的FG基序表现出显著不同的亲和力。位于中央通道的NUP98 GLFG基序对CA的结合亲和力明显高于传统的FxFG基序，支持了病毒通过亲和力梯度进入细胞核的机制。","scd":null,"kp":[]},{"i":39164,"as":"研究揭示了塔城蜱传病毒1型（TcTV1）核蛋白（NP）的结构特征与功能机制。该核蛋白以不依赖序列的方式结合核酸，并结合后组装成基于四聚体的核糖核蛋白复合物，伴随显著构象重排以促进其聚合。除负责RNA包裹外，研究证实该核蛋白还具备内在的核酸内切酶活性。这些核心发现深化了对正内罗病毒核蛋白在病毒基因组复制过程中多重功能的理解。","scd":null,"kp":[]},{"i":39165,"as":"提出将交流驱动的原子约瑟夫森结作为量子流体中三维孤波的纯净可调谐源。激发类型取决于结势垒高度，在低速下表现为涡环，在接近声速时表现为无涡度稀疏脉冲，涵盖完整的Jones-Roberts孤子族。Shapiro阶梯现象使孤波发射具确定性，在第一、二、三阶梯上每个驱动周期分别发射1、2、3个孤波，实现了对单激发和多激发配置的可控生成及动力学研究。","scd":null,"kp":[]},{"i":39166,"as":"细菌肽聚糖（PGN）片段是激活哺乳动物先天免疫（特别是NOD2通路）的病原体相关分子模式。胞内NOD2传感器的激活依赖于配体活性，胞苷酰二肽（MDP）长期被视为最小激动剂。最新研究强调了哺乳动物N-乙酰葡糖胺激酶（NAGK）对MDP的胞内磷酸化是激活NOD2的先决条件。本研究探讨了不同糖类和茎肽结构的细菌PGN片段在宿主细胞内发生结构修饰的具体机制。","scd":null,"kp":[]},{"i":39167,"as":"约50%欧洲血统前列腺癌患者中存在TMPRSS2:ERG基因融合，通过过表达ERG转录因子驱动肿瘤发生。由于缺乏酶活性和可配体口袋，ERG一直被认为是不可成药的。本研究证实转移性前列腺癌高度依赖ERG，并成功在其N端Pointed（PNT）结构域内鉴定出可成药口袋。利用诱导性shRNA系统证实敲低ERG能显著抑制癌细胞生长，为靶向治疗该致癌驱动因子提供了直接干预策略。","scd":null,"kp":[]},{"i":39168,"as":"突触传递通过调节强度、结构和数量实现可塑性。体内测量证实部分突触能存活数月，这与记忆的长期持久性相关，但维持突触和记忆长期稳定性的分子基础尚不明确。蛋白质通常降解较快，但近期发现突触中存在寿命极长的长寿蛋白（LLPs）群体。这些长寿蛋白被认为是维持特定突触长期稳定性及相关分子机制的关键核心要素。","scd":null,"kp":[]},{"i":39169,"as":"时间依赖密度泛函理论（TDDFT）是计算分子和固体光学激发的常规标准方法，而系综密度泛函理论（EDFT）则是极具前景的替代方案。研究引入了系综时间依赖密度泛函理论（ETDDFT），这是一种将TDDFT与EDFT相结合的实用理论。该理论成功实现了对现有方法的泛化，为相关物理化学计算提供了全新框架。","scd":null,"kp":[]},{"i":39170,"as":"连续变量量子系统是量子计算、通信和传感的基础。传统的波函数或密度矩阵表示方法在实际应用中常面临计算困难，而量子力学的层析成像图景通过关联准概率分布提供了一种易于理解的替代方案。本研究提出了一种非参数学习方法，专门用于学习连续变量系统中的非高斯量子态，有效克服了传统表示方法的局限性。","scd":null,"kp":[]},{"i":39171,"as":"首次在实验上展示利用相对论空心拉盖尔-高斯（LG）激光器，在直接激光加速机制下实现定向和准直的电子加速。电子被有效限制在沿反射激光方向分布的空心场内，产生了高度准直的电子束。该成果在激光尾波场加速和先进粒子加速器技术领域具有重大物理意义，验证了特定光场分布对电子加速轨迹的精准控制能力。","scd":null,"kp":[]},{"i":39172,"as":"研究了具有可调贝里曲率的单味金属中由声子介导的配对现象。在无贝里曲率的情况下，研究发现了纯由延迟效应产生的p波超导性，这打破了静态BCS（Bardeen-Cooper-Schrieffer）近似下的传统认知。该结论揭示了声子介导延迟效应在非常规超导机制中的关键作用，为单味金属超导配对提供了新见解。","scd":null,"kp":[]},{"i":39173,"as":"热力学临界场直接决定了超导凝聚能，但其压力依赖性的研究远少于转变温度。通过缪子自旋旋转弛豫测量技术，精确测量了铅在压力下的热力学临界场。热力学证据表明，随着压力升高，铅的超导特性发生演化，逐渐向弱耦合超导态转变。该结果为理解常规超导体在高压下的耦合强度演变提供了直接参数。","scd":null,"kp":[]},{"i":39174,"as":"量子几何（由量子度量和贝里曲率表征）是理解量子材料物理现象的核心框架，但其在非周期系统中的行为特征尚不明确。研究通过重正化群方法，揭示了准晶体中量子几何谱的层次结构。研究发现了导致量子几何发散增强的普适机制，为探索非周期量子材料中的奇异物理性质提供了理论依据。","scd":null,"kp":[]},{"i":39175,"as":"超对称共形场论是量子场论的重要子集，能提供对强耦合临界现象的深刻理解。研究提出了三维超共形伊辛临界点的微观和非微扰实现。通过模糊球体方法，成功展示了三维伊辛模型临界点的超共形特性，为研究强关联量子临界现象提供了一种新颖的非微扰数值验证模型。","scd":null,"kp":[]},{"i":39176,"as":"p波磁体作为一种新型磁性材料，在动量空间中表现出奇宇称和时间反演对称的自旋劈裂，在自旋电子学应用中极具前景。针对其基础机制的理论理解尚不深入，本研究构建了共度p波磁体的量子自旋模型。该模型精确描述了p波磁体的自旋劈裂特性，为理解和设计新型自旋电子学器件提供了核心理论工具。","scd":null,"kp":[]},{"i":39177,"as":"速度环量是研究湍流能量级联的核心物理量，近期的理论和数值研究将其确定为捕捉湍流间歇性的几何观测量。研究在三维牛顿流体和聚合物湍流中，首次在实验上观测到了速度环量的面积法则和双分形特征。该实验结论证实了速度环量在复杂流体湍流能量耗散及间歇性几何表征中的关键观测价值。","scd":null,"kp":[]},{"i":39178,"as":"交变磁和全补偿铁磁态是零净磁化的两类不同有序态。交变磁体的自旋劈裂源于晶体对称性并在动量空间交替，而补偿铁磁态则不同。研究表明，通过化学对称性破缺机制，可以实现交变磁态和补偿铁磁态之间的相互转换。该发现揭示了晶体化学调控对宏观磁学状态演变的直接作用，为新型自旋电子材料的设计提供了调控途径。","scd":null,"kp":[]},{"i":39179,"as":"描述了一种几何现象，即由简并戈德斯通模式组成的行波会使系统留下一个发生变换的基态。在三角海森堡反铁磁体中，圆偏振自旋波脉冲能够使自旋在其平面内发生旋转。通过求解非线性方程，得出该几何自旋旋转的精确解析解，为磁振子动力学及自旋激发的非线性控制提供了精确理论依据。","scd":null,"kp":[]},{"i":39180,"as":"多铁性氧化物因具有共存的铁电和磁有序而成为研究关联量子现象的核心，但当其厚度逼近二维极限时，铁电和磁性通常会因退极化场而受强烈抑制。本研究证实，在六方LuFeO3薄膜达到二维极限时，其铁电序和磁序依然能够稳定共存。该发现打破了传统理论限制，为研发新型二维多铁性材料提供了关键实验证据。","scd":null,"kp":[]},{"i":39181,"as":"提出了一种量子能量截断太赫兹相干断层扫描技术，实现了高空间局域化的分子物种特异性太赫兹响应提取。该方法利用发射太赫兹能量与分子振动量子能量匹配时的共振光子损失效应，通过重构反射的太赫兹辐射获取深层的材料光谱信息。该技术在非破坏性材料检测与生物分子成像领域具有极高的应用潜力。","scd":null,"kp":[]},{"i":39182,"as":"研究探讨了平均场伊辛模型，该模型中的耦合作用通过反馈函数依赖于系统的磁化强度。研究成功识别出一种混合相（MPs），并证明在反馈强度足够大时，该混合相在零温下能够稳定存在。此外，稳定的混合相始终处于超稳定状态，意味着任何扰动都会随时间衰减。这丰富了对复杂自旋网络相变动力学的认知。","scd":null,"kp":[]},{"i":39183,"as":"伊辛模型和液气系统中的二阶相变具有相同的普适类和临界指数，尽管液气哈密顿量缺乏Z2对称性，这突出了临界现象中非对称性的核心影响。研究系统分析了临界点附近的超临界-亚临界对应关系、非对称效应以及反对称修正项。该结论揭示了非对称性对临界涨落的量化作用，为完善非对称系统临界现象理论提供了重要参数。","scd":null,"kp":[]},{"i":39184,"as":"该研究探讨了红外纳米腔中分子键的断裂控制过程。研究人员分析了少量分子在腔量子电动力学（QED）奇特耦合机制下的化学反应行为，旨在揭示电磁真空如何增强分子的红外激光解离效应。这项工作为理解腔QED系统中的分子物理和化学反应提供了理论基础，发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39185,"as":"该研究探讨了具有Dzyaloshinskii-Moriya相互作用的二维磁性材料在周期性振荡磁场下的非平衡响应。通过广泛的蒙特卡洛模拟，研究人员发现了一种动态重入斯格明子相。这一发现解决了驱动拓扑物质领域的一个核心开放问题，揭示了交变磁场对斯格明子相的调控作用。","scd":null,"kp":[]},{"i":39186,"as":"该研究成功实现了光谱均匀的连续变量量子微梳。尽管此前已在芯片上实现了确定性克尔诱导的双模压缩，但实现多纠缠模式的均匀光谱仍具挑战。研究通过高Q值微谐振腔生成连续变量量子微梳，为集成量子信息处理提供了紧凑且频率复用的纠缠模式源。","scd":null,"kp":[]},{"i":39187,"as":"该研究利用光子时间晶体成功实现了携带轨道角动量（OAM）的微波涡旋光束激射。传统激射方法无法产生内嵌OAM的发射，而该研究通过光子时间晶体这一新兴技术突破了这一限制，为高容量通信、精密传感和雷达成像等先进领域提供了重要技术支撑。","scd":null,"kp":[]},{"i":39188,"as":"该研究利用Floquet工程（通过周期性驱动定制系统），在单光子干涉测量中实现了拓扑复能带辫。研究团队从理论和实验上预测并实现了这一非平衡拓扑现象。Floquet工程为操控物质的拓扑态以及创造超越静态场景的奇异非平衡拓扑现象提供了强大的工具。","scd":null,"kp":[]},{"i":39189,"as":"该研究提出在热猝灭诱导的玻色-爱因斯坦凝聚过程中，通过Kibble-Zurek机制（KZM）生成自发量子湍流。KZM预测在有限速率驱动的连续相变中会自发形成拓扑缺陷。研究团队使用数值模拟证实了这一过程，揭示了新生玻色-爱因斯坦凝聚体中量子湍流的形成机制。","scd":null,"kp":[]},{"i":39190,"as":"该研究分析了各种形式的噪声对一维无相互作用费米子系统的影响。研究证明，在强噪声极限和温和假设下，热力学极限中费米子关联矩阵的统计规律遵循一种普适形式，该形式由最近开发的自由费米子非线性西随机动力学描述，揭示了噪声输运中的普适性。","scd":null,"kp":[]},{"i":39191,"as":"该研究从纠缠态出发，探讨了量子多体系统中纠缠增长的动力学。与以往集中于初始乘积态的研究不同，该工作揭示了初始纠缠态在不同系统（从多体局域化到随机量子电路）中的普遍演化模式，为理解量子多体系统中的纠缠生成和输运提供了统一视角。","scd":null,"kp":[]},{"i":39192,"as":"该研究构建了用于探索阿贝尔拓扑序相位的参数化等距张量网络态，称为“骨架”。这些状态可以在量子处理器上高效实现。研究获得了弦网不动点的稳定有限关联长度形变，证实了其与阿贝尔拓扑序固定点的联系，为在量子处理器上研究拓扑相提供了新方法。","scd":null,"kp":[]},{"i":39193,"as":"该研究证明了高温费米子吉布斯态是高斯态的混合。基于量子系统中纠缠突然死亡的研究，团队探讨了有界自旋系统高温吉布斯态的结构特性。这一发现揭示了高温量子态的关键结构特征，为量子系统的高效模拟提供了重要的理论依据，简化了复杂量子系统的处理。","scd":null,"kp":[]},{"i":39194,"as":"该研究提出利用不定因果序量子纠错实现抗噪且达到海森堡极限的量子传感。由于传统量子纠错在传感中受限于严格的噪声和信号正交性要求，研究通过引入不定因果序突破了这些限制，成功在存在噪声的现实设备中实现了海森堡极限的传感，提升了量子传感性能。","scd":null,"kp":[]},{"i":39195,"as":"该研究提出了一种硬件高效的方法，通过结合工程非线性耗散和线性传输，同时实现非高斯态的生成及其向行波的转换。这种方法对于可扩展的容错量子计算至关重要。研究通过环境辅助技术解决了生成非高斯态并转换为行波包的挑战，为量子计算提供了新方案。","scd":null,"kp":[]},{"i":39196,"as":"该研究针对极端质量比旋近（EMRIs）这一低频引力波源，提出了一种天体物理环境自洽性测试方法。传统引力波信号解析基于真空假设，但在EMRIs系统中该假设失效。研究开发了打破真空假设的测试框架，用于区分空间探测器观测信号中的环境效应与纯真空信号。","scd":null,"kp":[]},{"i":39197,"as":"该研究提出了黑洞并合的最大熵猜想。研究指出，黑洞并合后的残骸属性受最大熵边界约束。当两个黑洞足够接近时，其周围区域对于远处观察者而言类似于一个单独的克尔黑洞，从而使得克尔熵的计算得以适用。该猜想为理解黑洞并合过程提供了新视角。","scd":null,"kp":[]},{"i":39198,"as":"该研究通过分析GWTC-4中的双黑洞并合事件，证实了活动星系核（AGN）吸积盘中的分层黑洞并合现象。研究采用了灵活的混合种群模型分析组件质量、自旋幅度和自旋倾角。结果显示，AGN吸积盘是分层黑洞并合的理想场所，为探测此类事件提供了确凿证据。","scd":null,"kp":[]},{"i":39199,"as":"该研究提出了一种世界面作用量，用于重现广义Veneziano振幅。这种作用量基于近期引入的手征复合线性膨胀子构建，能够推广开弦的Veneziano振幅。研究团队还计算了多点扩展和闭弦对应物，为弦理论中对偶共振振幅的研究提供了新的理论框架。","scd":null,"kp":[]},{"i":39200,"as":"该研究通过全息术研究热关联函数，在自旋链中定义了黑洞态。研究聚焦于海森堡模型，通过评估纠缠熵、空虚形成概率和Krylov复杂性，调查了该黑洞态的热性质和复杂性。这一工作将黑洞概念引入量子自旋链系统，为在凝聚态物理中模拟黑洞特性提供了新途径。","scd":null,"kp":[]},{"i":39201,"as":"该研究揭示了洛伦兹变换如何重塑弛豫谱。研究证明，在相对论中弛豫过程通常被假设经历时间膨胀的直觉是错误的。由于同时性的相对性，洛伦兹变换可将单个弛豫模式分裂为连续的激发态，其宽度由最大膨胀设定，这一发现修正了相对论系统中弛豫过程的传统认知。","scd":null,"kp":[]},{"i":39202,"as":"该研究利用激光冷却离子在电磁阱中构建了金字塔形库仑团簇，以测试Kramers-Langer理论。研究人员通过控制对称性实现了热激活切换，探究了陷阱势、非线性库仑相互作用和激光-离子散射之间的相互作用。这一可调谐的介观系统为研究热激活动力学提供了独特平台。","scd":null,"kp":[]},{"i":39203,"as":"该研究提出了超腔量子电动力学，解决了在单腔内同时实现珀塞尔增强和定制波前控制的挑战。传统腔量子电动力学由于谐振器要求冲突难以实现这一目标。该研究通过超腔结构成功融合了光与物质的相互作用以及波前调控，为产生非经典光态提供了全新方法。","scd":null,"kp":[]},{"i":39204,"as":"研究探讨了起皱Mylar薄膜在弹力作用下的老化行为。实验表明，在受控的力和位移条件下，该材料表现出对数弛豫现象。通过循环弛豫实验，研究人员揭示了一组连续演化的力-位移曲线族，这些曲线向平衡态演化，并受到瞬时和完全弛豫极限的约束。","scd":null,"kp":[]},{"i":39205,"as":"本研究实现了在1.2公里光纤上的时间多模态离子-离子纠缠。量子网络和量子中继器是构建大规模量子信息系统的关键基础设施，广泛应用于分布式量子计算、长距离量子通信和网络化量子传感。该实验的成功是实现全功能量子网络的重要步骤。","scd":null,"kp":[]},{"i":39206,"as":"研究提出了一种钾/锶双掺杂策略，合成具有萤石结构的β-Pb0.88Sr0.08K0.04F1.96氟离子导体。KF掺杂引入了丰富的氟空位缺陷以提升空位浓度，而SrF2与PbF2形成连续固溶体从而在地理上分散氟空位。该方法同时提高了全固态氟离子电池电解质的离子电导率和相稳定性。","scd":null,"kp":[]},{"i":39207,"as":"","scd":null,"kp":[]},{"i":39208,"as":"研究评估了巴西野火细颗粒物(PM2.5)对医疗负担的影响。数据显示，野火PM2.5每增加1 µg/m³，全因、呼吸系统和心血管疾病的住院费用分别增加0.36%、1.59%和0.25%，住院时间延长0.63%、1.72%和0.68%。哮喘和心力衰竭的费用增加最显著。","scd":null,"kp":[]},{"i":39209,"as":"利用三氧同位素数据发现，瑞典基律纳铁氧化物-磷灰石(IOA)矿床的磁铁矿中含有高浓度的蒸发硫酸盐衍生氧。研究指出，这种IOA组合是由硅酸盐岩浆大量同化蒸发岩形成的。蒸发岩中的硫酸盐氧化了岩浆中的亚铁，促使不相容的高铁熔体或磁铁矿形成并分离成矿。","scd":null,"kp":[]},{"i":39210,"as":"对澳大利亚皮尔巴拉克拉通31亿年前火山岩的高分辨率地球化学数据进行分析，识别出拉斑玄武质、钙碱性和真正的玻安岩三个原始熔岩系列。地球化学模型显示这种熔体多样性需要至少两个具有不同消耗历史的地幔源。产生这些熔岩所需的地幔水含量接近现代地幔楔的含水固相线。","scd":null,"kp":[]},{"i":39211,"as":"研究设计并合成了两种新型双高价碘试剂（Togni交联试剂TR1和TR2），作为高效的共价蛋白质交联剂。这些试剂的两端均带有高价碘-氟烷基结构，能够实现蛋白质的分子内和分子间交联，为在天然条件下研究蛋白质结构、构象动态及蛋白质相互作用提供了新工具。","scd":null,"kp":[]},{"i":39212,"as":"本期简报回顾了自克隆羊多莉诞生三十年来相关科学领域的进展。此外，还涵盖了关于预防痴呆的科学研究成果，以及呼吁保护哈勃空间望远镜的相关内容。","scd":null,"kp":[]},{"i":39213,"as":"研究测量了镍同位素（67,69,70Ni）中基于νg9/2的同核异能态的g因子。N=40附近的镍同位素区域因68Ni被认为可能是双幻核而备受实验和理论关注，但现有实验证据存在矛盾。本研究结果为该区域的核结构特性提供了新的数据参考。","scd":null,"kp":[]},{"i":39214,"as":"研究首次在162Er中观察到高K带结构。该结构基于Kπ = 7(-)的同核异能态，被发现与对应的Kπ能带具有相同的性质。这一发现对理解原子核中的“相同带”现象具有重要的科学意义。","scd":null,"kp":[]},{"i":39215,"as":"研究计算了锕系元素裂变中钡和氙链的同位素分辨裂变后产额，并使用评估参考数据进行了基准测试。研究重点关注固定裂变碎片电荷Z下的元素分辨同位素链以及轻重碎片关联的一致性，为核裂变机制提供了系统性的数据支持。","scd":null,"kp":[]},{"i":39216,"as":"通过引入中子-质子双壳层和价核子校正作为主要结构效应，研究改进了α衰变的Geiger-Nuttall规则框架。此外，还探讨了通过势垒穿透展开推导出的二阶能量依赖项的作用，从而提高了α衰变半衰期预测的准确性。","scd":null,"kp":[]},{"i":39217,"as":"实验通过用质子轰击天然锑生产了117mSn和119mTe放射性同位素。119mTe可作为发生器生产119Sb，而117mSn和119Sb是利用俄歇疗法靶向治疗骨关节炎和小体积肿瘤的有前景的放射性核素。该研究为带电粒子核反应建模提供了数据支持。","scd":null,"kp":[]},{"i":39218,"as":"研究直接测量了天体物理p过程中102Pd(γ,p)和102Pd(γ,α)反应的截面。一些中子缺乏的稳定“p核”无法通过中子俘获过程产生，而是由γ诱导反应作用于现有的r和s过程种子核生成。该测量数据有助于理解和模拟这些特定原子核的天体物理生成条件。","scd":null,"kp":[]},{"i":39219,"as":"研究结合单细胞RNA测序和多重免疫荧光技术，揭示了日本血吸虫感染小鼠肝脏肉芽肿的细胞异质性。发现虫卵改变了肝脏免疫细胞组成，表现为广泛的中性粒细胞募集和分化。两种中性粒细胞亚群的功能得到验证，其募集与CXCL2的自分泌和旁分泌信号相关。","scd":null,"kp":[]},{"i":39220,"as":"通过在钙钛矿前驱体溶液中引入亚磷酸三苯酯作为添加剂，实现了钙钛矿太阳能电池的全生命周期管理。该添加剂通过防止碘化物氧化和有机阳离子去质子化来稳定前驱体溶液，并提升薄膜的结晶度和长期稳定性。优化的太阳能电池实现了26.6%的认证功率转换效率。","scd":null,"kp":[]},{"i":39221,"as":"研究开发了一种由磷桥接的Fe-Cu双原子催化剂，具有独特的N3Fe-P1-CuN3结构。Fe-P-Cu桥接键引发d-p-d梯度轨道耦合，建立了从Cu位点（电子供体）到Fe位点（电子受体）的定向电子转移通道。该催化剂通过活化过氧单硫酸盐选择性生成高价铁氧物种，实现了超快速的污染物降解和细菌灭活。","scd":null,"kp":[]},{"i":39222,"as":"利用空间转录组学技术对卵巢透明细胞癌(OCCC)进行分析，揭示了其在氧化磷酸化(OXPHOS)和上皮-间充质转化(EMT)梯度上的异质性。研究发现OXPHOS与炎症沿EMT梯度呈负相关。发生部分EMT的肿瘤细胞发生代谢转变并丢失LCN2表达，而LCN2表达与富含OXPHOS的肿瘤特征和更好的预后相关。","scd":null,"kp":[]},{"i":39223,"as":"研究提出了一种名为MORTISE的紧凑型Cas6f平台，用于革兰氏阴性菌中可编程的多重翻译抑制。该系统无需宿主Hfq或核酸酶即可在大肠杆菌和恶臭假单胞菌中稳定运行。通过匹配引导RNA和靶点的转录，该系统能够在两种物种中实现高效的基因抑制。","scd":null,"kp":[]},{"i":39224,"as":"强直性肌营养不良1型(DM1)的标志性症状是肌强直。研究发现，在DM1小鼠模型中，通过基因组缺失ClC-1基因的隐蔽外显子E7a，可以完全恢复ClC-1通道功能并彻底消除肌强直。正常肌肉兴奋性的恢复使得小鼠的肌病症状得到显著改善，证明了肌强直对后续肌无力的发展有直接影响。","scd":null,"kp":[]},{"i":39225,"as":"RAPPORT前瞻性I/II期试验（NCT02855203）评估了立体定向消融放疗（SABR）联合帕博利珠单抗治疗30例寡转移透明细胞肾细胞癌（ccRCC）患者的效果。主要终点是安全性，次要终点包括总生存期和客观控制率等。预设的探索性转化分析表明，在治疗前肿瘤中，治疗响应者的肿瘤内部浸润有更多靠近肿瘤细胞的细胞毒性T细胞，而非响应者则显示出免疫抑制性特征的富集。","scd":null,"kp":[]},{"i":39226,"as":"本研究测量了雄性猕猴在经过物体辨别训练后其下颞叶（IT）皮层的变化。结果表明，经过训练的猕猴IT皮层显示出更强的物体选择性、更高的跨物体线性可分性以及更不变的特征表征。研究人员开发了一种基于腹侧视觉流解剖映射的人工神经网络（ANN）计算框架进行建模。模拟显示，基于梯度的性能优化更新能够准确逼近观察到的IT皮层神经可塑性变化。","scd":null,"kp":[]},{"i":39227,"as":"本研究利用阵列断层扫描技术和冷冻电子断层扫描技术，研究了人类胎盘细胞分化过程中线粒体网络和嵴的重塑。研究发现，在富含祖细胞滋养层的制备物中存在两个不同的线粒体亚群，而分化的合体滋养层中仅含单一同质的线粒体群。通过标准化的“曲率”指标，研究展示了线粒体内单个嵴的三维拓扑结构，揭示了细胞分化伴随的线粒体形态与功能转化机制。","scd":null,"kp":[]},{"i":39228,"as":"研究人员结合稳态连续培养、功能基因组学和计算方法，探究了自产乙醇梭菌（Clostridium autoethanogenum）中与自养相关的全基因组蛋白-RNA相互作用。研究旨在突破气体发酵微生物（产乙酸菌）细胞工厂理性工程化的基因功能与代谢调控限制。分析结果检测到了有限且解耦的转录现象，基于系统层面的分析预测该自养菌中不存在与自养相关的蛋白-RNA相互作用。","scd":null,"kp":[]},{"i":39229,"as":"研究在裂殖酵母中进行遗传筛选，发现RNA甲基转移酶Tgs1和卷曲螺旋相关蛋白能调节含有低效剪接隐性内含子的转录本。这些蛋白组装成TEaM复合物，被剪接体组分招募至逆转录转座子转录本等目标RNA上。Tgs1随之催化三甲基鸟苷（TMG）加帽，促进保守因子Pir2/ARS2的结合，并与DROSHA同源物Pac1等协同作用，调节基因表达并沉默逆转录转座子。","scd":null,"kp":[]},{"i":39230,"as":"利用体内CRISPR敲除筛选技术对肺癌患者来源的异种移植（PDX）模型进行研究，揭示了小细胞肺癌（SCLC）化疗耐药的遗传基础。研究发现，敲除转录共激活因子SAGA复合物中的去泛素化酶USP22会赋予肿瘤顺铂-依托泊苷耐药性。在携带USP22纯合截短突变的模型中恢复其表达，可使肿瘤重新对化疗敏感。USP22缺失会增加基因编码区组蛋白H2AK119的单泛素化水平。","scd":null,"kp":[]},{"i":39231,"as":"研究利用概率聚类框架对26年的状态估计数据进行分析，识别出北极埃克曼抽吸（Ekman pumping）的七种不同物理状态。这些状态反映了风、冰和地转强迫的不同组合，残余分量在季节性海冰过渡期更为显著。空间分析表明，波弗特海具有频繁的状态转换和持续的海冰-地转耦合状态特征。揭示了北极表面动量平衡中持续且可预测的动力学状态及其转换机制。","scd":null,"kp":[]},{"i":39232,"as":"通过汇编1950至2020年间10,522个城市的面板数据，研究证明了极端气温变率（ETV）的轨迹因城市发展水平（HDI）不同而产生差异。高发展水平城市的ETV加剧，而低发展水平城市略有减弱，造成约1.66°C的差距。极端气温变率主要由事件强度而非频率决定。可解释机器学习模型表明，在控制气候和地理因素后，气溶胶是与ETV关联最强的城市因素。","scd":null,"kp":[]},{"i":39233,"as":"研究证明，在巴伦支海的次表层水域中，颗粒结合型固氮微生物发挥了显著的二氮（N2）固定作用。与亚热带地区的研究对比表明，非蓝细菌群的颗粒结合型固氮微生物是北极次表层水域的主要固氮者，这与温暖地区的多样化群落形成对比。揭示随着北极逐渐向寡营养化演变，颗粒结合型固氮作用对于维持该海域初级生产力具有重要氮源供应意义。","scd":null,"kp":[]},{"i":39234,"as":"一项结合了CO2升高、变暖和干旱条件的15N示踪两年期山地草甸实验表明，尽管施用了高量氮肥，气候变化仍增加了植物对土壤氮库的依赖。植物吸收的氮有82-88%来自土壤，其从土壤中获取的氮量是肥料的4.6-7.3倍。升高CO2和变暖仅增加了植物对土壤氮的吸收，导致植物氮输出超过肥料输入，引发生态系统氮赤字和土壤氮储量耗竭。","scd":null,"kp":[]},{"i":39235,"as":"通过分析两只猕猴在执行空间听觉决策任务时的初级听觉皮层（A1）和背外侧前额叶皮层（PFC）的神经元同步记录，研究发现皮层处理存在明显的层级动态：感觉信息从A1单向传递至PFC；而决策相关信息在A1与PFC之间呈现双向流动。这一发现表明，经典的感觉至高级脑区的顺序层级模型未能完全捕获大脑皮层在整合感觉输入和决策计算时的复杂动态。","scd":null,"kp":[]},{"i":39236,"as":"研究解析了人胞质丝氨酸tRNA合成酶（SerRS）与NAD+依赖性去乙酰化酶SIRT2复合物的冷冻电镜结构，揭示了代谢与翻译网络间的直接分子联系。NAD+代谢物ADP核糖（ADPR）作为分子桥连接这两种酶，并进入SIRT2活性位点。该复合物的形成通过阻断底物接触抑制了SIRT2的去乙酰化酶活性，同时SIRT2的结合通过阻止tRNA结合抑制了SerRS的氨基酰化活性，实现相互调节。","scd":null,"kp":[]},{"i":39237,"as":"研究鉴定了一种介导囊性纤维化患者中铜绿假单胞菌（Pseudomonas aeruginosa）慢性感染持续性的机制。临床分离株中丙酮酸脱氢酶复合体的突变导致丙酮酸分泌增加，金黄色葡萄球菌等其他病原体中也存在类似突变。升高的胞外丙酮酸通过清除活性氧（如H2O2）和抑制气道上皮细胞及巨噬细胞的宿主免疫激活，减弱炎症反应，从而促进细菌在炎症和氧化应激环境中的持久存活。","scd":null,"kp":[]},{"i":39238,"as":"研究发现TREM1信号通路在炎症性肠病（IBD）的中性粒细胞介导炎症中形成两个正反馈回路。第一，激活的中性粒细胞释放PGLYRP1，与细菌肽聚糖结合形成配体复合物激活TREM1，进一步增强中性粒细胞脱颗粒、活性氧产生和NETosis；第二，单核细胞上TREM1的激活促进趋化因子分泌，招募并激活更多中性粒细胞。这些机制共同持续放大并加剧了IBD中的慢性炎症反应。","scd":null,"kp":[]},{"i":39239,"as":"针对间充质基质细胞注射治疗勃起功能障碍中细胞留存率和存活率低的问题，研究开发了表面工程化细胞。通过在细胞表面偶联聚多巴胺纳米颗粒和抗血管细胞黏附分子1（VCAM-1）抗体，实现多价抗体引导细胞靶向炎性海绵体内皮，同时聚多巴胺有效清除活性氧，改善炎症微环境。这种双重功能工程化显著提高了细胞在海绵体内的滞留、存活及治疗效果。","scd":null,"kp":[]},{"i":39240,"as":"研究利用冷冻电子显微镜技术，解析了来自蓝细菌的天然二聚体光系统II（PSII）中间体的高分辨率结构（约2.2 Å）。这些中间体包括缺失放氧复合体（OEC）的无活性二聚体以及仅在其中一个单体中带有OEC的半活性二聚体。该结构数据详细揭示了Mn4CaO5簇的组装和解组装过程是如何与PSII亚基的结合与释放相协调的，为理解光合作用的高效修复机制提供了重要依据。","scd":null,"kp":[]},{"i":39241,"as":"研究利用定量成像和组织特异性扰动方法，分析了斑马鱼嗅觉孔（鼻孔）发育过程中上皮皮肤细胞的动态重塑。研究发现，位于基板玫瑰花结中心的感官腔室在决定上皮孔洞边缘扩张的大小和形状中发挥着至关重要的作用。上皮皮肤细胞与感官腔室之间的动态机械相互作用，精塑了不断扩大的嗅觉开口，使感觉神经元能够直接接触外部气味信号。","scd":null,"kp":[]},{"i":39242,"as":"研究开发了一种含有专用于局部高水平表达的可电离脂质的mRNA-脂质纳米颗粒（mRNA-LNP）肺部疫苗。通过气管内给药至雌性小鼠，该疫苗能够迅速将肺部中性粒细胞和巨噬细胞诱导至转录预激活状态，增强其吞噬活性，有效填补了疫苗接种后的免疫脆弱期。该mRNA-LNP疫苗不仅提供针对细菌肺部感染的快速保护，还能建立持久的免疫防线。","scd":null,"kp":[]},{"i":39243,"as":"本研究结合单细胞转录组分析和T、B细胞受体谱分析，构建了涵盖猪胎儿肝脏、骨髓和胸膜的全面造血发育单细胞图谱。研究揭示了从胎儿到成年期不同组织和年龄阶段的特异性特征，鉴定了支持B细胞和T细胞发育的基因模块，并详细描述了骨髓中B细胞以及胸腺αβ和γδ T细胞受体的成熟与多样化过程，为提升猪的健康和推进临床前研究提供了重要数据。","scd":null,"kp":[]},{"i":39244,"as":"研究鉴定并克隆了介导亚洲栽培稻与非洲栽培稻杂交雄性不育的主要基因座S19。S19位点由两个紧密连锁的非洲稻特有基因（S19A1和S19A7）组成，构成杀手-保护者模块。杀手基因S19A1通过可变剪接产生两种转录本，分别编码介导体细胞或配子细胞死亡的线粒体靶向毒性蛋白；而S19A7蛋白则与这两种毒性蛋白相互作用，阻断其毒性。亚洲栽培稻因缺乏该保护基因，最终导致杂种花粉败育。","scd":null,"kp":[]},{"i":39245,"as":"传统固定配置的电动汽车电池组存在电芯差异性和过早失效等结构低效问题。动态电池重构技术通过开关硬件的智能控制提供了替代方案。研究构建了基于详细电芯建模的统计框架，对多种设计和使用条件下的可重构电池组进行评估。结果显示，可重构电池组能将电池寿命延长20%以上，尤其在电动卡车和长续航乘用车等高压应用中表现突出。","scd":null,"kp":[]},{"i":39246,"as":"扭曲双层范德华磁体通过扭转产生空间变化的层间交换相互作用，从而稳定复杂的磁响应。研究在扭转约3°的双层CrSBr中观察到稳健的磁滞回线，这通过场相关光致发光测量中激子能量的滞后演化得到证实。分析模型表明，扭转降低了层间交换作用，在宽泛磁场范围内稳定了平行和反平行自旋态。","scd":null,"kp":[]},{"i":39247,"as":"单细胞生物在没有神经编码的情况下也能协调复杂行为。研究以一种拥有四根极长纤毛且有运动能力的藻类原生生物为对象，利用高速活体定量成像提取了纤毛的跳动模式谱，并推导出耦合纤毛振荡时间频率和空间波长的色散关系。研究重构了行为空间中的流形，揭示了该生物通过紧密成束的纤毛动力学展现出极其丰富的运动库。","scd":null,"kp":[]},{"i":39248,"as":"RNA聚合酶II（RNAPII）通过包含移位、底物结合和催化的核苷酸添加循环（NAC）驱动基因表达。研究提出了31个冷冻电镜结构，捕捉了酿酒酵母RNAPII延伸复合物NAC的不同阶段，包括难以捕获的过渡中间体。NAC结构动力学分为两个阶段：底物诱导的复合物收紧阶段和催化后的复合物松弛阶段，确立了RNAPII延伸复合物结构动力学的连续变化图谱。","scd":null,"kp":[]},{"i":39249,"as":"亚硝酸盐电化学还原为氨可净化废水并产出高附加值化学品。针对中间体活化与氢化动力学不匹配的问题，研究将镍单原子位点和钯分离簇精确引入共价有机框架，构建了复合催化剂。该催化剂在-1.0 V（vs RHE）下的氨产率达20.9 mg h⁻¹ mgcat⁻¹，法拉第效率高达95.5%。在-1.3 V电压下，其氨产率进一步提升至35.3 mg h⁻¹ mgcat⁻¹。","scd":null,"kp":[]},{"i":39250,"as":"缺乏超短栅极长度的p型晶体管限制了宽禁带氧化物半导体在CMOS集成中的应用。受双层β-二氧化碲启发，研究利用第一性原理量子输运模拟，评估了亚5纳米栅长的双层β-二氧化碲场效应晶体管性能。由于该材料的独特各向异性，在y方向上，亚5纳米栅长的n型和p型晶体管均能实现优异性能，成为首个预测具备对称性能的氧化物半导体。","scd":null,"kp":[]},{"i":39251,"as":"研究探索了不同碱、添加剂、Gd³⁺螯合物及还原剂TCEP条件下的基于硫辛酸的聚合水凝胶。使用TCEP将惰性二硫化物转化为硫醇引发剂，以及碱使硫辛酸去质子化以增溶，显著改善了聚合过程。调节组分可使水凝胶粘度在1×10³至1×10⁸ mPa·s范围内变化，满足外用药膏或可注射水凝胶等不同应用需求。此外，研究还通过改变Gd³⁺螯合物内层结构探索了水凝胶的弛豫效应。","scd":null,"kp":[]},{"i":39252,"as":"随着二氧化碳电化学还原向工业化迈进，优化电池组件对长期性能至关重要。研究详细考察了阴极气体扩散电极压缩比对电化学性能的影响，测试了三种不同的碳基阴极支撑材料。通过电化学阻抗谱和微型断层扫描技术，解释了阴极被逐渐压缩至40%以下时电解性能发生变化的机制。研究结果为零间隙二氧化碳电解槽中阴极组件的最佳压缩使用提供了指导。","scd":null,"kp":[]},{"i":39253,"as":"研究提出了一种稳健的晶种生长方案，在α-氧化铝基底上制备了约3微米厚的连续富马酸铝（A520）多晶金属有机框架膜。合成后的活化过程对膜的完整性至关重要。热活化前的甲醇交换预处理，能有效抑制溶剂蒸发期间毛细管应力引起的晶格畸变。实验表明，经过甲醇交换的A520膜展现出优异的分子筛分性能，能够高效分离CO₂/N₂和CO₂/CH₄。","scd":null,"kp":[]},{"i":39254,"as":"研究通过分子动力学模拟探究了金属离子对金属有机框架膜海水淡化性能的影响。在多种驱动压力下测试了NaCl溶液通过Cu-MOF-74、Ni-MOF-74和Zn-MOF-74膜的特性。结果表明，Ni和Zn膜允许离子通过，且流量随驱动压力增加而上升。相反，Cu-MOF-74膜展现出优异的脱盐性能，在驱动压力低于50 MPa时可完全阻挡Na⁺和Cl⁻，实现100%的离子截留率，而三种膜的水通量则保持相似。","scd":null,"kp":[]},{"i":39255,"as":"二维硼烯的独特电子特性源于其多中心键。研究在超高真空条件下，利用分子束外延技术在加热的Ni(111)基底上生长出大孔硼烯模型。通过扫描隧道显微镜、低能电子衍射和密度泛型理论计算等方法分析，发现硼原子最初结合到Ni表面并优先在台阶边缘成核。基底良好的几何匹配性有助于大孔硼烯结构的形成与稳定。","scd":null,"kp":[]},{"i":39256,"as":"GaAsBi线在红外光电器件中极具潜力。研究通过分子束外延技术，系统探究了生长模式、Bi incorporation与载流子动力学的关系。改变基底温度和V/III束等效压力比，生长从平面沉积转变为气-液-固（VLS）和气-固（VS）生长。在稳定的VLS条件下，实现了高达2.4%的均匀轴向Bi incorporation。成分分析证实VLS条件下组分分布均匀，而VS生长模式则出现非均匀性。","scd":null,"kp":[]},{"i":39257,"as":"研究提出了一种名为单细胞PAGE-PISA的超灵敏蛋白质组分析技术。该技术结合了凝胶电泳和3D单分子荧光成像，通过用荧光染料标记单细胞内的所有蛋白质，利用电泳分离并以单分子分辨率进行计数。该技术可从单个哺乳动物细胞中定量超过107个蛋白质拷贝，对低丰度蛋白质的检测灵敏度可达每种10⁵个拷贝，成功基于蛋白质特征将细胞分类为不同细胞类型。","scd":null,"kp":[]},{"i":39258,"as":"针对体积庞大的肿瘤，免疫检查点抑制剂联合常规放疗疗效有限。研究提出iERT技术，对肿瘤大体积施加低剂量放疗，并对其内部子区域进行立体定向放疗（SBRT）。结合免疫检查点抑制剂，该疗法通过协调NK和CD8⁺ T细胞实现显著控制。单细胞测序表明，SBRT诱导I型干扰素激活NK细胞分泌XCL1，招募树突状细胞，并促进携带新抗原的细胞外囊泡释放，增强免疫响应。","scd":null,"kp":[]},{"i":39259,"as":"研究发现，亚油酸（LA）在老年人及骨关节炎（OA）患者的血液、滑液和软骨中大量积累。在雄性大鼠模型中，LA不仅诱导软骨细胞发生铁死亡，还作为一种风险代谢物驱动OA的发生，并加速创伤性OA的恶化。机制上，LA直接结合铁硫簇装配酶（ISCU）引发其自噬降解，抑制铁硫簇合成，进而激活IRP1介导的翻译过程，揭示了OA进展中的代谢致病机制。","scd":null,"kp":[]},{"i":39260,"as":"Kozak mRNA序列（在AUG起始密码子侧翼的-3和+4位为嘌呤）的识别机制一直未明。通过分析具有不同Kozak活性mRNA序列的人源48S前起始复合物的冷冻电镜结构，研究揭示了特定的识别模式。密码子前的三联体呈扇形插入18S核糖体RNA中，而-3位的嘧啶会破坏三元复合物的定位。+4位嘌呤的特异性识别则通过eIF1A、mRNA和rRNA的相互构象适应，以及解码残基A1825的插入堆叠来实现。","scd":null,"kp":[]},{"i":39261,"as":"针对冯·诺依曼瓶颈，研究开发了一种基于混合卤化物钙钛矿的可重构多态光存储器。该技术利用飞秒脉冲激发下的动态离子行为，将光致发光发射波长作为编码激发参数的易失性可重写存储态。这些状态具有长寿命保持特性，并可通过热脉冲快速擦除。通过调节激发功率和重复率，实现了对光致发光波长的精确控制，表现出类模拟突触的行为，实现了空间分辨的写入。","scd":null,"kp":[]},{"i":39262,"as":"多囊蛋白复合物构成的阳离子通道与常染色体显性多囊肾病密切相关。研究揭示了由特定膜脂质调节的PC1-PC2通道的变构门控机制。磷脂酰甘油和磷脂酸结合在孔道中央维持关闭态，其解离使通道转为预开态。而纤毛中富集的氧固醇通过变构机制将通道稳定在非导通的开放构象。脂质介导的调节与通道巨大的构象变化相耦合。","scd":null,"kp":[]},{"i":39263,"as":"研究通过在介质光栅加速器中结合液晶掩膜板和脉冲前沿倾斜方案，实现了对激光脉冲相位和振幅的编程控制。这种可编程光学脉冲技术被用于动态控制激光驱动电子加速器，实现了对加速器束流动力学的实时调节。该技术允许进行基于软件的结构与光学波前缺陷校正，并能够执行电子束的相空间操作，具备无限的实时调谐能力。","scd":null,"kp":[]},{"i":39264,"as":"研究利用扫描隧道光谱研究了4Hb-TaS2中由填充控制驱动的莫特态及其与超导的相互作用。该材料交替包含强关联的1T-TaS2层和超导1H-TaS2层。通过解析由层间电荷转移驱动的不同能级填充下的电子谱函数，研究定量捕获了莫特态的连续演化过程，表现为莫特-哈伯德能带的出现以及电子跃迁参数的系统性抑制。","scd":null,"kp":[]},{"i":39265,"as":"研究团队开发了一种基于硒原子转移的[3+2+1]杂环加成反应，利用芳基胺、烯烃和二硒化物快速合成含硒和氮的杂环化合物，如硒吗啉和多环1,4-硒嗪。该方法无需金属、条件温和、操作简单且具备可扩展性，具有广泛的底物普适性和官能团容忍度，适用于复杂分子的后期骨架衍生化。机理与计算研究揭示了其反应机制。","scd":null,"kp":[]},{"i":39266,"as":"为解决传统聚烯烃抗氧化方法存在的分散不均、迁移和缺乏普适性问题，研究提出了一种催化剂抗氧化策略（CEAS）。该策略采用酚羟基功能化双功能催化剂，在实现聚合催化的同时提供抗氧化能力。通过这种无需聚合后添加抗氧化剂的原位聚合方法，成功制备出具有本质抗氧化特性的多种聚乙烯材料，特别解决了超高分子量聚乙烯（UHMWPE）的长期稳定性难题。","scd":null,"kp":[]},{"i":39267,"as":"为突破阴离子-π+光诊疗剂结构多样性有限且缺乏第二近红外（NIR-II）发射和光热性能的瓶颈，研究提出了一种有机π共轭阴离子交换策略，合成了DTPAP-2B和DTPAP-2P。纳米化后的DTPAP-2P粒子表现出显著的吸收红移、强烈的NIR-II发射、340 nm的大斯托克斯位移、卓越的活性氧生成能力以及高达72%的光热转换效率，远超DTPAP-2B的性能。","scd":null,"kp":[]},{"i":39268,"as":"研究开发了兼容点击化学的七甲川花菁染料CETIF6a，用于泛肿瘤靶向、术中组织病理学检查和全蛋白质组靶点鉴定。该染料在多种癌症类型中实现了肿瘤边缘准确划定（与H&E染色一致性超90%）。定量蛋白质组学显示，其靶向的肿瘤特异性蛋白质数量是癌旁组织的5至15倍，通过491个保守的肿瘤富集蛋白实现协同泛癌靶向。","scd":null,"kp":[]},{"i":39269,"as":"针对锰基普鲁士蓝类似物（PBAs）因姜-泰勒效应畸变和低电导率导致电化学性能不佳的问题，研究通过钾取代和高熵策略构建了K2(FeMnCoNiCu)[Fe(CN)6]（K-HEHCF）阴极。在1.4V电压下，该电极展现出104.92 mg g−1的高吸附容量，并在200次循环后容量保持率接近100%。该电极对模拟循环冷却水样品中的阳离子具有显著的去除效果。","scd":null,"kp":[]},{"i":39270,"as":"针对微结构表面可拉伸导电薄膜的保形制造难题，研究提出了一种通用策略。通过精确控制液桥力与液态金属（LM）颗粒壳层的临界破裂强度，实现LM颗粒的自发融合，无需额外活化过程即可形成高性能导电薄膜。在拉普拉斯压差驱动下，薄膜可保形沉积于复杂的微结构表面。该策略克服了传统方法在拉伸性、导电性和几何兼容性方面的局限。","scd":null,"kp":[]},{"i":39271,"as":"为解决室温红外光电探测中背景热辐射产生的平均光电流偏移淹没微弱信号的问题，研究展示了基于光谱极性反转的传感器内背景偏移消除机制。通过工程化波长依赖的光电流反转，单器件内不同光谱波段的光子产生相反符号的响应，从而抵消背景偏移。这一混合维度范德华异质结构机制有效抑制了背景电流均值，实现了高灵敏度红外探测。","scd":null,"kp":[]},{"i":39272,"as":"研究利用三维粒子动力学模拟，开发了针对颗粒状小行星内部自引力内聚风化层抗拉强度的缩放框架，揭示了颗粒尺寸和形状对宏观力学行为的联合控制作用。研究表明，抗拉强度可通过等效颗粒直径或颗粒球形度进行缩放。利用OSIRIS-REx任务返回的贝努小行星样本数据，该模型推导出的表面内聚强度与既有估算结果一致。","scd":null,"kp":[]},{"i":39273,"as":"为深入理解分子组件中的单电子电荷态，研究通过扫描探针操纵构建了四溴四氮芘分子的分子三聚体和六聚体。利用安德森杂质模型和主方程方法，成功阐明了其中的非平衡多体电子动力学。这种超越了标准单粒子图像的理论处理对于理解该类分子系统至关重要，能够准确定量重现测量中可见的全部特征。","scd":null,"kp":[]},{"i":39274,"as":"为克服传统体表电位映射在电极性能、连线复杂性和可穿戴性等方面的限制，研究开发了一种混合电子纺织电极阵列系统。该系统能够沿皮层-肌肉轴同步映射大脑、心脏和肌肉的电活动，克服了空间分辨率低的问题，增强了皮肤电生理记录的诊断能力，为非侵入式评估电活性器官提供了创新的柔性电子解决方案。","scd":null,"kp":[]},{"i":39275,"as":"海水电解制氢面临阳极氢氧根氧化与氯离子氧化的竞争难题。研究利用旋转环盘电极装置，在碱性盐水中对比了不同催化剂形成次氯酸盐的情况。结果表明，在析氧反应催化剂中添加铬，能将5分钟内次氯酸盐的生成量从2.362 mM降至0.670 mM。研究直接对比了静电斥力和离子选择性策略在抑制氯氧化方面的效果。","scd":null,"kp":[]},{"i":39276,"as":"","scd":null,"kp":[]},{"i":39277,"as":"","scd":null,"kp":[]},{"i":39278,"as":"","scd":null,"kp":[]},{"i":39279,"as":"研究揭示了细胞骨架内在振荡器决定神经元极性的新机制。神经元极化过程并不完全依赖生长锥感知外部信号，而是由胞体作为中央组织者启动。在胞体内，依赖肌动蛋白相关蛋白2/3（ARP2/3）复合体的周期性肌动蛋白分支重塑了全局肌动球蛋白网络，从而产生振荡程序以启动轴突选择。","scd":null,"kp":[]},{"i":39280,"as":"亚马逊地区拥有全球超10%的陆地生物多样性。研究汇编了90,536份报告，发现人类利用了5,796种亚马逊本土植物（占已知维管种子植物的三分之一）。基于8,429个物种分布模型，研究指出在三种未来气候情景下，气候变化将导致本土植物分布范围大幅缩减，同时揭示了气候变化对生物多样性与原住民语言双重遗产的影响。","scd":null,"kp":[]},{"i":39281,"as":"Ryan Rising致力于开发相关教育项目，旨在帮助刑满释放或被监禁的人员获得进入学术领域的机会。该项目提出建立从监狱到博士（PhD）的学术培养通道，以促进这类人群重新融入社会并提升其学术与职业发展上限。","scd":null,"kp":[]},{"i":39282,"as":"为应对气候变化对生物多样性造成的预期破坏，研究提出重建亚马逊原住民与自然之间以互惠关怀为导向的关系。这种重建人与自然联系的方法，被视为解决亚马逊地区生物文化侵蚀、抵抗气候变化负面影响的有效生态与文化保护策略。","scd":null,"kp":[]},{"i":39283,"as":"诺贝尔化学奖得主Omar Yaghi离开美国，前往中国领导一家人工智能材料实验室。这一举动发生在美国削减科研经费的背景下，同时也是中国积极招募顶尖国际人才战略的体现，进一步强化了中方在AI与材料交叉领域的科研布局。","scd":null,"kp":[]},{"i":39284,"as":"卫星观测与气候模型模拟表明，自2005年以来，中等强度的火山喷发与极端野火活动加剧了平流层的湿润化。这些事件产生的气溶胶介导效应解释了约三分之一的平流层水汽上升趋势，其贡献程度与地表变暖的影响相当。","scd":null,"kp":[]},{"i":39285,"as":"文章标题为“遗忘者”，正文简短提及了“清晰的思维”。","scd":null,"kp":[]},{"i":39286,"as":"科学家首次实时观测到大洋中脊分裂张开的物理过程。监测记录到了数米级别的海底构造运动，并伴随有巨量熔岩流出。这一罕见的地质活动为人类直接了解海底扩张与岩浆喷发机制提供了第一手实证资料。","scd":null,"kp":[]},{"i":39287,"as":"小鼠乳腺癌模型实验表明，癌症基因组中全染色体或染色体臂的非整倍性改变包含一至两个主要的癌症驱动基因。这些基因能够绕过非整倍性积累的过程直接驱动癌症，且其致癌作用依赖于完整的微环境。体内CRISPR筛选鉴定的这些驱动基因，在体外实验中改变表达量时并不会引起细胞行为变化。","scd":null,"kp":[]},{"i":39288,"as":"大语言模型（LLMs）具有推进社会科学实验的潜力，能有效加速该领域的研究进程。然而，关于在研究中如何恰当且合理地使用大模型作为辅助工具，目前仍存在根本性的疑问，亟待明确其应用规范与边界。","scd":null,"kp":[]},{"i":39289,"as":"海底监测实验首次原位观测到两个构造板块之间生成新海洋地壳的现象。这是人类首次对此类地质现象进行原位测量。","scd":null,"kp":[]},{"i":39290,"as":"Kathleen Fisher介绍了她为英国先进研究与发明局（UK ARIA）带来的资助创新科学的策略。该策略的核心在于通过高通量、高风险以及允许失败的机制来推动革命性科学的发展。","scd":null,"kp":[]},{"i":39291,"as":"研究团队发布了《欧洲空间分解代际流动性图谱》（EUROPE-IGM-ATLAS），这是一个包含欧洲各次国家级地区代际流动性指标的面板数据库。该研究扩展了关于代际流动性的现有知识，揭示了个体出生背景对未来经济机会的制约，并指出了代际教育流动性缺失是机会不平等的主要决定因素。图谱进一步展示了欧洲各地区代际流动性发展的时空趋势。","scd":null,"kp":[]},{"i":39292,"as":"在地球轨道上运行的核武器会通过与地球空间辐射环境的相互作用而发射中子。研究指出，这些 emitted 的中子信号具备被卫星探测到的潜力，从而提供了一种追踪太空中潜伏核武器的方法。","scd":null,"kp":[]},{"i":39293,"as":"电化学装置（如燃料电池和电解槽）的商业可行性高度依赖于电催化剂的稳定性，这与其催化活性同等关键。本文综述了纳米结构催化剂的稳定性机制与实际应用指南，探讨了化学势如何驱动催化剂的内在稳定性。文章将催化剂稳定性的基础理解与工程应用相结合，阐明了决定催化剂可靠性、使用寿命和成本效益的化学与结构原理。","scd":null,"kp":[]},{"i":39294,"as":"植物-土壤反馈（PSF）是决定植物群落动态和非本土物种入侵的重要机制。研究选取了五对本地的外来物种，并在0、1、3和6个全球变化因素（GCFs）的并发组合下进行了实验。结果显示，随着GCF数量的增加，本地物种的PSF由负向中性或正向转变；而外来物种的PSF始终保持正向且变得更强。外来物种对多种GCFs的正向反馈响应，源于其原产地特定的相互作用机制。","scd":null,"kp":[]},{"i":39295,"as":"研究利用基因靶向技术，将有机光催化染料整合到细胞表面及内部，实现了针对特定细胞类型且在物理空间上受控的催化反应。这种光催化作用可通过温和的绿光至红光可见光刺激被限制在单个细胞内。染料成功催化了交叉脱氢C-H官能化反应，能够将特定活细胞作为独立的微型反应器，按需进行时空可控的非生物有机化合物合成。","scd":null,"kp":[]},{"i":39296,"as":"","scd":null,"kp":[]},{"i":39297,"as":"研究开发了一种钯催化的C-H活化反应，实现了无导向基团的芳烃、杂芳烃与环戊烯衍生物的对映选择性偶联。在易于获取的手性吡啶酮-恶唑啉配体的促进下，该反应体系能够高效进行C(sp2)-H活化，生成的产物包含两个立体中心，并表现出极高的立体选择性控制水平（对映体过量达96%，非对映异构比达40:1）。","scd":null,"kp":[]},{"i":39298,"as":"研究构建了一种中空结构的CdS@聚多巴胺纳米反应器，集成了仿生特性以促进光催化。其聚多巴胺壳层中的动态邻苯二酚/邻苯醌氧化还原对充当“质子继电器”，通过可逆地释放和接受质子加速质子耦合电子转移（PCET）。同时，多孔壳层构成的纳米空腔创造了受限的微环境，有助于质量扩散、反应物富集和光子捕获。这种协同机制有效促进了氧还原和水氧化反应。","scd":null,"kp":[]},{"i":39299,"as":"研究采用掺氮策略构建了TiO2负载的金催化剂（Au/N-TiO2），用于甲烷的选择性氧化。该催化剂在180°C的温和条件下，使用O2作为氧化剂进行水相反应，实现了高达3956 μmol gcat⁻¹ h⁻¹（比活性为177 mol molAu⁻¹ h⁻¹）的甲醇生产率和98%的甲醇选择性。分析表明，氮的引入调节了金的电子态，有效解决了甲烷C-H键极度惰性和甲醇易过度氧化的难题。","scd":null,"kp":[]},{"i":39300,"as":"研究开发了一种氨基功能化的氢键有机框架材料HOF-101-NH2，用于高效大气集水。策略性的氨基（-NH2）整合创造了大量水成核位点并促进协同氢键网络的形成，使其在60%相对湿度下的吸水量约为0.46 g g⁻¹。该材料捕获的水分可在约50°C的低温下于3分钟内释放，实现低能耗再生。凭借快速的吸附-解吸动力学，该材料每天可完成超过30次循环。","scd":null,"kp":[]},{"i":39301,"as":"研究提出了一种利用电动驱动的粘度梯度来调控液滴动力学的方法，实现了从纳升级母液滴中按需释放皮升级子液滴的耦合富集过程。该技术通过在液滴内局部富集带有电荷的粘度调节剂（聚电解质海藻酸盐）和带电荷的目标物质，实现了试剂或分析物的浓缩与夹断分离。此方法有助于提升微流控技术中的反应动力学和检测灵敏度。","scd":null,"kp":[]},{"i":39302,"as":"脂肪酸光脱羧酶（FAP）是一种通过光驱动自由基化学将脂肪酸转化为碳氢化合物的光酶。研究通过多尺度计算模拟探究了其催化终止的分子机制。结果表明，在快速脱羧之后，生成的烷基自由基主要通过由质子化的精氨酸R451和附近水分子介导的质子耦合电子转移机制被淬灭。相比之下，水辅助的碳酸氢盐形成在催化过程中属于罕见的竞争性反应事件。","scd":null,"kp":[]},{"i":39303,"as":"研究开发了一种通过区域选择性和立体选择性环氢甲酰化反应合成饱和杂环化合物的通用策略。该反应体系在温和条件下使用简单的钴催化剂和可见光，能从多种烷基胺底物广泛获取δ-内酰胺或哌啶类化合物，也可用于合成内酯。此外，增加催化剂用量后，钴羰基化合物既可作为预催化剂也可作为原位一氧化碳（CO）源，使反应能够在氩气气氛下进行。反应对钴前催化剂的种类表现出显著的依赖性。","scd":null,"kp":[]},{"i":39304,"as":"研究设计了四种能够预组装两到三个联吡啶-丙氨酸非天然氨基酸的蛋白质骨架，生成单价铜位点。实验表明，这些嵌入蛋白质的配合物表现出独特的电荷转移特性，显著减弱了八面体Cu(II)配合物的姜-泰勒畸变效应，形成了前所未有的八面体Cu(I)几何结构，并导致Cu(II)/Cu(I)氧化还原电位发生明显的阴极偏移。这证明蛋白质骨架能够作为机械活性的配体结构，重塑铜配合物的经典配位倾向。","scd":null,"kp":[]},{"i":39305,"as":"核酸递送材料的研发正在经历从经验性筛选向预测性、人工智能引导设计的转变。为了解决同时优化材料相互竞争的理化性质以及实现肝外靶向递送等更具挑战性的难题，该领域正致力于根据预先设定的属性目标直接生成新的递送材料，而非仅仅依赖传统筛选。","scd":null,"kp":[]},{"i":39306,"as":"研究构建了一种由交替的Pt-I和Pt-Pt-I-I双链构成的一维分子超晶格结构。链间的静电相互作用使电子配对过程从传统的局域化机制转变为离域的多位点路径，成功稳定了首条由碘桥连的Pt(III)电荷密度波（CDW）链。处于这种CDW状态下的离域电子配对过程使材料的体电导率大幅提升了约两倍。","scd":null,"kp":[]},{"i":39307,"as":"研究利用12种反映肥胖生物学特征的小鼠饮食模型，探究了宿主生理因素对抗肿瘤免疫和免疫检查点抑制剂（ICI）疗效的影响。结果表明，肥胖相关的ICI疗效与代谢功能紊乱的关联性较弱，而是高度依赖于饮食-肠道轴。致胖饮食能够促进建立一种强健且持久的肠道微生物生态系统，这种系统在恢复机体对ICI的敏感性方面起到了关键作用。","scd":null,"kp":[]},{"i":39308,"as":"LARES-2（激光相对论卫星2号）凭借其优化的极低面质比和高度均匀的后向反射器分布，结合其前代卫星LAGEOS及GRACE卫星，成功测量了地球周围的参考系拖曳效应。该测量结果的相对不确定度达到了千分之一水平，将广义相对论这一核心预测的测量精度较以往太阳系测定结果提升了一个数量级。","scd":null,"kp":[]},{"i":39309,"as":"跨膜（TM）螺旋是真核生物膜蛋白的基本结构和功能单元。文章探讨了决定TM螺旋在细胞膜中热力学稳定性的因素，并重点介绍了一类特殊的“条件性跨膜肽”。这类肽段（如pHLIP肽）在分离状态下，无论在溶液中还是细胞膜内均能保持稳定。文章综述了该类肽段的发现、决定其插入细胞膜的因素，及其在癌症治疗和膜蛋白变构调节中作为功能调节剂的应用基础。","scd":null,"kp":[]},{"i":39310,"as":"研究人员将局部热力学测量与输运测量相结合，应用于扭曲三层石墨烯器件中。实验结果揭示，超导现象与电子压缩性的特征振荡同步发生，但完全独立于相关的绝缘相。这一发现揭示了不同强相互作用特征之间的明确联系。","scd":null,"kp":[]},{"i":39311,"as":"","scd":null,"kp":[]},{"i":39312,"as":"","scd":null,"kp":[]},{"i":39313,"as":"","scd":null,"kp":[]},{"i":39314,"as":"气候变化加剧了全球水资源压力，迫使公用事业部门投资昂贵的基础设施并提高水费，导致低收入家庭面临水费可负担性危机。研究构建了城市级建模框架进行评估，发现以加州圣克鲁斯为例，仅气候变化一项就可能导致当地水费在世纪中叶翻番，使7-16%的额外家庭无法负担水费。","scd":null,"kp":[]},{"i":39315,"as":"","scd":null,"kp":[]},{"i":39316,"as":"研究成功在预存有钼和硅原子的Cu(111)箔片上，实现了晶圆级p型单层半导体MoSi2N4单晶的生长。Cu(111)表面的台阶引导了单层MoSi2N4结构域的成核和单向排列，使其无缝拼接成连续的单晶薄膜。该材料的本征迁移率达154 cm2 V−1 s−1，制成的场效应晶体管阵列展现出优异的电学性能。","scd":null,"kp":[]},{"i":39317,"as":"研究开发了一种化学回收路线，通过分步一锅法工艺，将基于二氧化碳的非异氰酸酯聚氨酯（NIPU）泡沫解构并重新功能化，转化为环状碳酸酯构件。该过程重复利用所有主要解聚产物，免除了中间纯化步骤并减少了废弃物。利用这些回收物直接发泡，成功制造出含有高达100%回收碳源的第二代泡沫。","scd":null,"kp":[]},{"i":39318,"as":"过渡金属催化在推动高分子化学进步中发挥了核心作用。文章通过具体案例，介绍了最初为小分子底物开发的催化反应如何被应用于聚合物的合成或改性。此外，还详细描述了该催化技术在功能材料制备，以及塑料的降解、回收和升级回收中的具体应用。","scd":null,"kp":[]},{"i":39319,"as":"一种鞋盒大小的探测卫星有望识别隐藏核装置的特征信号。此为科学界新闻播报的一部分，同期的报道内容还涉及了原住民植物学知识正面临的威胁。","scd":null,"kp":[]},{"i":39320,"as":"基于时空调制的系统可通过合成有效运动来控制波，无需机械位移。理论预测波在经历足够大的旋转多普勒频移时，可从旋转介质中提取能量。由于机械旋转系统需要极端转速，实验一直受限。本研究表明，利用纯空间的Floquet感应旋转，能够成功进入这种超快旋转状态并观察到相关现象。","scd":null,"kp":[]},{"i":39321,"as":"研究利用ATAC-seq技术对包含1563名急性髓系白血病（AML）初诊患者的队列进行了分析。结果显示，根据染色质可及性特征，AML可被划分为16个亚组。多组学分析（涵盖基因突变、转录组、DNA甲基化和组蛋白标记）表明，这些基于染色质可及性的亚组具有不同的驱动突变。","scd":null,"kp":[]},{"i":39322,"as":"随着驱动、控制和学习技术的进步，人形机器人正逐步走向实际应用。医疗保健领域面临人员短缺和需求激增的双重压力，人形机器人凭借在灵活性、操作能力和安全交互方面的优势，在手术辅助任务中展现出独特潜力，打破了传统手术机器人专一平台的局限，并进行了相关的体内可行性研究。","scd":null,"kp":[]},{"i":39323,"as":"为避免造血干细胞移植前基因毒性预处理的副作用，研究人员在KIT胞外域鉴定出氨基酸突变。该突变能阻断两种治疗性单克隆抗体的结合，同时不影响KIT的表达和功能。通过腺嘌呤碱基编辑或先导编辑技术高效引入这些突变后，实现了非基因毒性的移植与体内筛选。","scd":null,"kp":[]},{"i":39324,"as":"研究利用冷冻电子显微镜技术，解析了I型产甲烷菌中Hdr–Vhu–Fwd超组装体的结构。该复合物质量达8 MDa，包含252条多肽链和超过600个氧化还原辅因子。其架构由两个六聚体HdrABC–Vhu环通过四聚体FwdF核心连接，形成连续的环状电子链，通过基于黄素的电子分岔机制将氢气氧化与二氧化碳还原相偶联。","scd":null,"kp":[]},{"i":39325,"as":"量子纠错（QEC）是保护量子计算机免受环境干扰的核心策略。由于环境漂移，必须不断调整控制参数以保持极低的错误率。传统方法是终止计算进行重新校准。本研究将校准与计算统一，将QEC过程的错误检测事件重用作强化学习的信号，训练智能体实时适应环境变化并调整参数。","scd":null,"kp":[]},{"i":39326,"as":"研究建立了包含70项预注册全国代表性调查实验（涉及469个实验效应和119,330名参与者）的档案，评估大型语言模型（LLM）预测社会科学实验结果的能力。通过让GPT-4模拟代表性样本对实验刺激的反应，结果证明GPT-4能够准确推断出实验的处理效应，即使这些实验并未包含在其训练数据中。","scd":null,"kp":[]},{"i":39327,"as":"通过对神经肽进行无偏倚药理学筛选，研究发现两种古老的进食调节因子——神经肽F（NPF）和抑咽肽A（AstA）能够调节克隆突袭蚁的育幼行为。功能实验证实，NPF能够增加个体的育幼行为，揭示了古老进食相关神经肽在昆虫社会行为及异亲抚育调控中的关键作用。","scd":null,"kp":[]},{"i":39328,"as":"研究结合水声、直接测距、海底压力测量与重复海底制图技术，首次在原位观测到了大洋中脊（MOR）板块的裂谷事件。该事件于2024年4月26日发生在东南印度洋中脊（37°S附近）。记录显示，事件以沿洋脊轴快速迁移的扩张性震群开始，为海底扩张的年度运作机制提供了直接的观测数据。","scd":null,"kp":[]},{"i":39329,"as":"文章回顾了新数据集和灵活计算方法的兴起如何推动城市犯罪研究在方法和实证上的演变。计算方法不仅在预测任务上表现出色，更为超越传统预测、进行更严谨的因果推断提供了巨大潜力。文章指出未来研究需解决当前挑战，并提出了利用新数据和计算工具的三个关键发展方向。","scd":null,"kp":[]},{"i":39330,"as":"研究展示了一种可编程的毫米波氮化镓单片微波集成电路（MMIC）。该电路集成了由二维氮化硼（hBN）制成的忆阻射频开关。这种新型开关器件易于制造且电学性能优异，有效解决了在MMIC平台中集成高频开关面临的面积、成本和性能瓶颈问题，满足了5G及更高标准的通信需求。","scd":null,"kp":[]},{"i":39331,"as":"针对传统水凝胶在富水环境中气体交换效率低的问题，研究基于粘弹性相分离（VPS）策略，在高含水量水凝胶中构建了不塌陷且富含空气的网络。这种方法克服了透气性与含水量之间的权衡，实现了创纪录的185 barrer的氧气渗透率，极大改善了水凝胶在生物医学接口等应用中的气体交换瓶颈。","scd":null,"kp":[]},{"i":39332,"as":"针对《外层空间条约》（OST）缺乏核武器部署核查机制的问题，研究提出利用宇宙质子进行核查的概念与可行性分析。该方法旨在验证卫星是否遵守条约规定，防止核武器被送入太空并引爆摧毁近地轨道上的卫星，从而为OST的执行提供技术核查手段。","scd":null,"kp":[]},{"i":39333,"as":"研究人员开发了名为CRISPR-KOALA的高通量双向遗传筛选技术，用于免疫健全小鼠癌症模型。针对由染色体不稳定引起的10种最常见的人类基底样乳腺癌（BLBC）染色体臂水平改变，筛选了3752个小鼠同源基因，成功鉴定出90个癌症驱动基因，阐明了非整倍体在获取驱动基因及促癌过程中的作用。","scd":null,"kp":[]},{"i":39334,"as":"本文提出了通用细胞嵌入（UCE）基础模型。该模型基于大规模细胞数据通过自监督方式训练，构建了能够表示跨组织和物种细胞的统一生物潜伏空间，有效捕捉了生物学变异并排除实验噪声。其通用性使新细胞能够在无数据标记和模型微调的情况下进行嵌入，为细胞生物学提供了全新的跨物种细胞表征方法。","scd":null,"kp":[]},{"i":39335,"as":"针对高压锂金属电池醚基电解液在循环中溶剂去溶剂化加剧氧化分解和消耗导致结构恶化的问题，本研究向富阴离子电解液中引入靶向配体抗溶剂（TLAS）。在静态下TLAS几乎不参与Li+的溶剂化，而在高压全电池的强电场下，其取向和分布发生特定变化，从而稳定高锂离子浓度下的电解液结构，提升电池循环稳定性。","scd":null,"kp":[]},{"i":39336,"as":"针对现有可编程光伏系统因单场调制导致架构复杂且效率受限的问题，本研究引入光作为独立且空间可分辨的自由度，解耦了寻址与状态切换，建立光电双场编程范式。该研究利用范德华ZnIn2S4中的反常光伏效应，将光独立用于寻址，电场用于切换，提升了空间选择性、架构简单性与运行效率，实现了可编程的光伏功能。","scd":null,"kp":[]},{"i":39337,"as":"","scd":null,"kp":[]},{"i":39338,"as":"针对免疫抑制性肿瘤微环境（ITME）这一冷肿瘤免疫治疗的主要障碍，本研究开发了具有光免疫性能的光响应纳米光笼，通过精确激活STING信号通路实现协同光免疫治疗。采用光响应BODIPY连接STING激动剂（DMXAA）制备成水溶性纳米颗粒。其中，碘化的纳米光笼表现出最佳的光反应效率和时空可控性，在光照下能有效释放药物并诱导ITME逆转。","scd":null,"kp":[]},{"i":39339,"as":"","scd":null,"kp":[]},{"i":39340,"as":"","scd":null,"kp":[]},{"i":39341,"as":"","scd":null,"kp":[]},{"i":39342,"as":"传统热熔胶存在不可降解且结合强度不足（<4.0 MPa）的问题。本研究利用地球储量丰富的镍催化剂，通过乙烯与α-烯烃的羰基化聚合反应，将低成本烯烃原料转化为高性能且可降解的聚酮热熔胶。研究发现丙烯/CO含量对粘合强度具有显著影响，通过简单的复合策略明确了聚酮组成与粘合性能之间的基础关系，突破了工程应用的性能瓶颈。","scd":null,"kp":[]},{"i":39343,"as":"","scd":null,"kp":[]},{"i":39344,"as":"","scd":null,"kp":[]},{"i":39345,"as":"","scd":null,"kp":[]},{"i":39346,"as":"","scd":null,"kp":[]},{"i":39347,"as":"","scd":null,"kp":[]},{"i":39348,"as":"","scd":null,"kp":[]},{"i":39349,"as":"","scd":null,"kp":[]},{"i":39350,"as":"","scd":null,"kp":[]},{"i":39351,"as":"","scd":null,"kp":[]},{"i":39352,"as":"","scd":null,"kp":[]},{"i":39353,"as":"","scd":null,"kp":[]},{"i":39354,"as":"","scd":null,"kp":[]},{"i":39355,"as":"","scd":null,"kp":[]},{"i":39356,"as":"","scd":null,"kp":[]},{"i":39357,"as":"传统辐射制冷面临制冷功率上限和环境限制。本文综述了蒸发辅助辐射制冷技术，揭示了其打破辐射制冷功率天花板的协同热力学机制。文章总结了相关的材料设计、多样化应用场景及关键挑战，为迈向能源可持续的先进被动冷却技术提供了指南，并为下一代被动制冷研究和实际应用规划了全面的路线图。","scd":null,"kp":[]},{"i":39358,"as":"本文提出通过曲率-配位耦合机制在碳点中编程弯曲原子活性位点。这种协同调控将镍位点置于最优的电子状态，使尿素的内在氧化活性提升了近20倍。该技术不仅实现了高效的尿素氧化反应，还能在处理含尿素废水的同时实现节能制氢，为能源转换与废水修复提供了新途径。","scd":null,"kp":[]},{"i":39359,"as":"","scd":null,"kp":[]},{"i":39360,"as":"","scd":null,"kp":[]},{"i":39361,"as":"自主微流控平台结合了流动化学、实时光谱学和贝叶斯优化，成功发现了具有目标光学性质的高质量CsPbBr3纳米片。该系统能快速识别控制量子限域、发射颜色和光致发光效率的合成条件，并生成关于纳米片生长机制的数据驱动见解。优化后的条件可直接转化为稳态连续制造，加速了先进量子材料的发现与规模化生产。","scd":null,"kp":[]},{"i":39362,"as":"","scd":null,"kp":[]},{"i":39363,"as":"酰胺的合成对医药和材料开发至关重要。本研究报道了一种钯催化的四组分Suzuki-Miyaura偶联反应变体，利用Mo(CO)6提供CO、DPPH提供NH进行顺序插入，将传统用于形成C-C键的卤化物和硼酸转化为酰胺。该反应能广泛合成含芳香族和烯烃基团的二级酰胺，可快速组装类药分子，并支持从相同原料制备“反向酰胺”类似物。","scd":null,"kp":[]},{"i":39364,"as":"残留的碘化铅（PbI2）导致钙钛矿太阳能电池界面能学空间异质性，降低其效率和稳定性。传统单齿配体钝化效果有限且易破坏晶格。本研究提出双铵双齿配体策略，利用新型配体MeXT选择性将残留Pb2重构为共角PbI6八面体，在不破坏体相钙钛ite的前提下，稳定了PbI6单元并建立空间均匀的界面能学，显著提升器件性能。","scd":null,"kp":[]},{"i":39365,"as":"氢-氘交换质谱（HDX-MS）是识别药物结合位点和作用机制的重要生物制药结构分析方法，但其常规空间分辨率较低，仅能提供多氨基酸片段的平均信息。本文展示了一种具有单氨基酸分辨率的位点特异性HDX-MS测量方法。利用五种针对癌症靶点WDR5的候选药物，验证了该方法在深入探究蛋白质与药物动态相互作用方面的卓越分析能力。","scd":null,"kp":[]},{"i":39366,"as":"张力环烷烃的开环反应是构建复杂有机分子的重要方法。计算研究表明，环丙烷的实验反应活性高于仅通过张力释放（BEP关系）预测的值。在考察12种张力环烷烃与甲基自由基和双自由基的反应时发现，除了张力释放外，断裂σ键的双自由基特性（以占据数y0量化）是加速开环反应的关键因素。","scd":null,"kp":[]},{"i":39367,"as":"","scd":null,"kp":[]},{"i":39368,"as":"无保护基团的糖苷合成面临立体控制难和多步保护-脱保护过程的挑战。本研究开发了一种统一简短的策略，在铜/配体/碱介导下，由易得的糖基磺酰肼生成糖基自由基，随后加成到各种自由基或不饱和键上，高立体选择性地合成了多种无保护基的糖苷，包括多立体中心的烯基C-糖苷、烷基C-糖苷、芳基硫糖苷和芳基硒糖苷。","scd":null,"kp":[]},{"i":39369,"as":"报道了具有前所未有的8,14-seco-ent-kaurane骨架的ent-贝壳杉烷二萜化合物Glutinosasains A-E的差异性不对称合成。关键步骤包括：利用Baran还原烯烃偶联构建含C10季碳中心的反式十氢萘框架；利用路易斯酸介导的脱保护/逆Claisen缩合级联反应构建8,14-seco-ent-kaurane骨架。研究开发了构建顺/反式十氢萘框架的立体发散策略。","scd":null,"kp":[]},{"i":39370,"as":"","scd":null,"kp":[]},{"i":39371,"as":"可持续航空燃料（SAF）是替代化石燃料的未来航空关键解决方案。本文比较了26种已报道的SAF合成路径的效率、经济性、环境影响和可扩展性。技术成熟获批的SAF方法仅依赖少量生物质，无法满足全球需求；而新兴SAF生产路径通过液化、发酵或气化将丰富的生物质转化为中间体，进而开发出符合航空标准的燃料。","scd":null,"kp":[]},{"i":39372,"as":"","scd":null,"kp":[]},{"i":39373,"as":"硫氧水复合物（OS···OH2）是星际和大气硫化学的关键中间体。本文通过在3.5 K的氩基质中，利用254 nm光解由叔丁基亚磺酸在600℃闪真空热解原位生成的不稳定亚磺酸（HOSOH），首次实验制备了该复合物。通过基质隔离红外、紫外/可见光谱和同位素标记实验结合计算，证实了三重态硫氧水复合物比三重态自由基反应途径更稳定。","scd":null,"kp":[]},{"i":39374,"as":"","scd":null,"kp":[]},{"i":39375,"as":"","scd":null,"kp":[]},{"i":39376,"as":"","scd":null,"kp":[]},{"i":39377,"as":"","scd":null,"kp":[]},{"i":39378,"as":"","scd":null,"kp":[]},{"i":39379,"as":"","scd":null,"kp":[]},{"i":39380,"as":"","scd":null,"kp":[]},{"i":39381,"as":"","scd":null,"kp":[]},{"i":39382,"as":"","scd":null,"kp":[]},{"i":39383,"as":"","scd":null,"kp":[]},{"i":39384,"as":"青藏高原农业环境恶劣且是生物多样性热点，面临粮食生产与自然保护的冲突。评估显示，1990至2020年间高原粮食产量增加32.33%。但陡坡种植和过度放牧威胁了未来生产力，加之气候变化影响，实现这两大目标面临风险。文章评估了在气候变化情景下，青藏高原同时实现粮食生产与环境保护双重目标的可行性与挑战。","scd":null,"kp":[]},{"i":39385,"as":"骨关节炎中存在细胞外基质降解，本研究发现血清弹性蛋白片段是系统性衰老驱动因子。在患者滑液中检测到弹性蛋白片段上调，其含有的特定基序（VGVAPG）通过神经氨酸酶-1促进巨噬细胞分泌炎症因子。这些炎症因子与该基序共同上调软骨细胞中的血清淀粉样蛋白A3，加速软骨退化。抑制弹性蛋白降解能有效缓解衰老小鼠、狗和人类模型中的关节退化。","scd":null,"kp":[]},{"i":39386,"as":"研究量化了膜成分对界面质子迁移的控制机制。通过嵌入离子载体将质子直接释放到膜片表面，并监测其在膜上的扩散发现，表面扩散系数和释放活化能受膜静电影响较小。相比之下，掺入类囊体膜特有的糖脂（双半乳糖甘油二酯和硫代异鼠李糖甘油二酯）能显著减缓界面质子迁移，同时保持质子的表面保留能力。","scd":null,"kp":[]},{"i":39387,"as":"昼夜节律对免疫调节至关重要。在多发性硬化症小鼠模型中，血液循环中性粒细胞在发病早期显著增加，并在行为活跃期（晚间）呈时间依赖性地大量浸润中枢神经系统。转录组分析揭示了这些浸润性中性粒细胞具有特异性的时间依赖性基因表达谱，并确定甲酰肽受体2（FPR2）作为治疗该疾病的潜在关键靶点。","scd":null,"kp":[]},{"i":39388,"as":"该研究开发了一种基于mRNA的脂质纳米颗粒（LNP）癌症疫苗平台，旨在解决传统疫苗mRNA递送效率低和树突状细胞（DC）激活不足的问题。通过高通量筛选可电离脂质，该平台实现了高效的mRNA递送。此外，该技术通过共递送多种干扰素基因刺激因子（STING）激动剂，有效促进了DC成熟和交叉呈递。克服了STING激动剂细胞内递送差及与肿瘤抗原难以共定位的限制，从而显著增强了细胞毒性T细胞反应，提升了针对免疫“冷”肿瘤的抗肿瘤活性。","scd":null,"kp":[]},{"i":39389,"as":"研究构建了一种受生物学信息启发的大规模人类皮层计算模型，以探究大脑分子、解剖和生理组织的空间异质性如何影响大尺度神经元动态。模型基于经验性结构连接（SC）数据以及源自转录组和PET数据的毒蕈碱受体（CHRM）图谱，将其作为与适应相关的兴奋性调节剂。结果表明，根据CHRM的空间组织结构调节神经兴奋性，能够生成从清醒到睡眠状态等不同的大脑动态特征，揭示了空间异质性对皮层动态的塑造作用。","scd":null,"kp":[]},{"i":39390,"as":"研究揭示了睡眠剥夺（SD）引发活性氧（ROS）产生及肠道-大脑信号传导的具体机制。在果蝇模型中，机械和热遗传学SD方法上调了多巴胺（DA）的生物合成，导致ROS在肠道前胃及其驻留的血细胞中初始积累。多巴胺通过非常规激活线粒体反向电子传递（RET）发挥作用，该过程涉及对呼吸链复合物之间相互作用的修饰。这一发现明确了睡眠剥夺诱导氧化应激和炎症的源头与关键信号通路。","scd":null,"kp":[]},{"i":39391,"as":"研究探讨了复杂网络上的生态-进化公共物品博弈，揭示了扩散速率差异如何促进合作行为的持续。在背叛者占主导的共存体系中，当背叛者扩散速度快于合作者时，会引发对称性破缺转变，形成合作者的局部集群。在异质网络中，具有较高连接度的节点表现出合作主导地位的概率显著增加。基于度的平均场理论还原分析证实了这一结果，解释了自然和社会系统中合作行为能够克服自私行为优势而维持的机制。","scd":null,"kp":[]},{"i":39392,"as":"研究探讨了受限状态下的二维活性向列相流体动力学现象。通常，二维活性向列相通过内部生成的混沌流进行高效搅拌，这主要由运动的+1/2拓扑缺陷（位错）驱动。然而，研究表明，这种倾向于混沌流体搅拌的特性在受限环境下，反而会反直觉地产生特定有序的周期性流动。这些流动以+1/2拓扑缺陷的稳定周期性轨道为特征，揭示了受限条件下活性物质中从混沌产生有序的特殊动力学机制。","scd":null,"kp":[]},{"i":39393,"as":"研究提出理论模型解释了人类社会为何倾向于采用刚性的道德规则。尽管人类具备灵活的道德判断能力，但社会依赖义务和禁令等绝对适用的刚性规则。刚性规则作为一种管理“不合作行为模糊性”的社会技术出现。由于人们未能合作的正当理由往往对旁观者不透明，机会主义者常将自私伪装成合理困难。博弈论模型显示存在两种均衡：允许借口的灵活规范易受剥削，而强制合作的刚性规则则弥补了这一漏洞，体现了效率与稳健性的权衡。","scd":null,"kp":[]},{"i":39394,"as":"为解决重组蛛丝蛋白产量低及纯化成本高的问题，研究设计了一种新型迷你蛛丝蛋白。通过将重复区域的聚丙氨酸基序替换为非天然淀粉样β16肽，显著提高了蛋白的表达产量和溶解度。此外，研究开发了基于NaCl诱导液-液相分离（LLPS）的无色谱纯化方法。这种一步纯化策略使加工成本相比传统亲和色谱降低了99%，在摇瓶培养中纯化蛋白产量达到每升约300毫克，并成功制备出高性能的蛛丝-淀粉样杂化纤维。","scd":null,"kp":[]},{"i":39395,"as":"研究利用高分辨率功能核磁共振成像技术，分析了人类纹外视觉皮层中处理运动、视差和颜色的中尺度功能柱的发育相互作用。对正常视力者和斜视或屈光参差引起的弱视患者的比较显示，在正常对照组中，视差选择性皮层柱占据的区域与运动及颜色选择性区域存在竞争关系。而在弱视患者中，视差选择性柱的尺寸减小，分配给运动和颜色选择性柱的皮层区域则相应扩大，揭示了视觉功能模块间的发育竞争机制。","scd":null,"kp":[]},{"i":39396,"as":"研究开发了一种重组Aβ1-40（淀粉样蛋白β）的表达和纯化方案，解决了由于其多态性导致的原子分辨率结构表征困难的问题。该方案能够在生理条件（pH 7.4）下形成单态原纤维，为结构基线提供了可靠基准。通过魔角自旋核磁共振（NMR）波谱技术，研究获得了这些无引物、单态Aβ1-40原纤维的高分辨率结构。这一成果为深入理解阿尔茨海默病中构成老年斑核心的Aβ纤维结构提供了关键的结构学数据。","scd":null,"kp":[]},{"i":39397,"as":"研究利用光学光热红外显微光谱技术，以亚微米空间分辨率对活细胞内肝细胞中的棕榈酸（PA）代谢过程进行了实时观察，以探究饱和脂肪酸引起脂毒性的机制。结果发现，在加入PA后，内质网（ER）中靠近形态异常脂滴的区域出现了随时间变化的酯羰基拉伸。该特征被归属于甘油-3-磷酸途径中的二酰基甘油中间体。氘代PA的C-D拉伸提供了补充分子细节，支持了PA酰基链在内质网中的排列会降低酶扩散速率的模型。","scd":null,"kp":[]},{"i":39398,"as":"研究展示了在高品质因子（high-Q）微谐振腔中，经典线性光学范式发生偏离的量子罕见现象。在低强度下，长时间的长时间光子约束使得由量子真空介导的罕见量子电动力学（QED）事件能够发生。这些事件将耦合分析物的独特拉曼特征嵌入到谐振腔的线性透射光谱中，而这些特征在材料的线性磁化率中并不存在。研究进一步表明，增加吸附的分析物样本量可以将这些拉曼指纹放大至远超典型噪声水平，使其能够被现有的先进光子架构实验捕获。","scd":null,"kp":[]},{"i":39399,"as":"研究指出接触变质作用释放的间接硫排放是驱动气候持续降温和生物大灭绝的关键因素。传统观点认为硫注入必须到达平流层才能引发长期降温。然而，模型研究表明，含碳和含硫主沉积物的接触变质作用所排放的合理碳硫量，其持续时间足以引起百年尺度的硫酸盐气溶胶降温效应（降温数开尔文），并叠加在二氧化碳温室效应引起的千年尺度升温之上。这一发现填补了对大规模火成岩区灾害性挥发物释放间接气候影响机制的认知空白。","scd":null,"kp":[]},{"i":39400,"as":"研究报道了一种通过能量转移催化策略实现自由基磷酰化的新反应途径。有别于传统的单电子转移机制，该策略利用高效率的能量转移使同源烯丙醇与磷(III)试剂之间发生前所未有的光化学双自由基重排。机理研究与计算化学证实了能量转移介导的双自由基机制。该反应在可见光驱动下条件温和，通过双自由基中间体经历自由基加成、β-断裂和重组，高效构建了具有张力的磷酰化环丙烷化合物，具有广泛的底物适用性。","scd":null,"kp":[]},{"i":39401,"as":"研究将色氨酸分解代谢酶吲哚胺2,3-双加氧酶（IDO）开发为系统性抗炎蛋白疗法。通过将聚乙二醇（PEG）与IDO偶联（PEG化），显著延长了该酶在体内的循环时间。在五种不同的自身免疫和炎症动物模型中，PEG-IDO展现了显著的治疗效果。单次剂量给药即可逆转后肢炎症等疾病症状，且在实现广谱抗炎作用的同时，未观察到明显毒性，也未损害宿主的正常免疫功能，证明了其作为免疫调节剂的安全性和有效性。","scd":null,"kp":[]},{"i":39402,"as":"研究开发了一种可训练的液晶低聚物网络（LCON）软材料，赋予材料从外部数字信息中“学习”的能力。通过在LCON各向异性网络中功能化引入光开关偶氮苯分子，利用二进制系统将基本逻辑和记忆功能直接集成到材料分子配置中，构建出可训练的自驱动门（T-SPG）。利用光子刺激调节T-SPG的记忆状态，使材料能够根据数字数据进行物理响应的动态调整，成功将人工智能领域的“大数据训练”概念转化为软物质中的物理学习行为。","scd":null,"kp":[]},{"i":39403,"as":"研究开发了一种名为植入式生物电子插座（IBO）的柔性组织样电子接口，用于建立植入式电子设备与外部设备之间的长期可靠电气连接。IBO由涂有导电聚合物的低密度聚合物基体组成，外部包裹疏水弹性体，允许外部电接触的反复插入而不会引发裂纹扩展。该接口在植入一年后仍保持功能且组织反应极小。IBO实现了信号和功率的高保真双向传输，包括低压神经生理信号记录和高能传输，满足了慢性诊断和设备维护的需求。","scd":null,"kp":[]},{"i":39404,"as":"针对三维柔性电子器件与皮肤之间长期共形贴合的难题，研究引入了一种连接三维架构电子器件与皮肤的多功能多孔界面。该界面通过工程化微孔网络构建，不仅克服了三维器件几何复杂性导致的机械脆弱性，还显著增强了界面的弹性拉伸能力和电学可靠性。多孔设计同时赋予了系统出色的水分渗透性、热缓冲和冲击缓解功能。这一技术有效提升了表皮集成电子设备在健康监测和皮肤疾病治疗等长期穿戴场景下的舒适度与稳定性。","scd":null,"kp":[]},{"i":39405,"as":"研究利用长期数值模型分离并量化了采砂对湄公河三角洲 destabilization（失稳）的具体影响。结果显示，该地区的采砂量超过自然沉积物供应量的6至15倍，导致约65%的河道发生河床侵蚀，平均下切率为每年约0.10米（占总下切量的25-30%）。河道加深改变了水流并减少了沉积物传输。单独采砂贡献了约16-30%的年度盐度增加量，在旱季使盐水入侵向内陆延伸多达1.5公里。数据证明采砂是导致三角洲地形与生态失稳的关键驱动因素。","scd":null,"kp":[]},{"i":39406,"as":"研究揭示了深层岩浆负压和岩浆系统连通性在驱动大型岩墙侵入中的核心作用。2024年12月，埃塞俄比亚裂谷下方有1.4立方公里的岩浆发生传播并持续约3个月。大地测量和地震数据表明，该岩墙由深度在6至12公里之间的岩浆储层网络供给。储层压力计算显示，系统深部形成的负压为抽取大体积岩浆创造了条件。研究得出结论，构造应力与充足的岩浆不足以引发巨型岩墙侵入，此类事件只有在岩浆系统连通并形成深度负压后才会触发。","scd":null,"kp":[]},{"i":39407,"as":"研究提出了一种名为经皮全方位靶向（TADT）的静态接触界面设计策略，将被动抓握表面转化为主动触觉显示通道。TADT通过将微纹理皮肤耦合界面与相位控制触觉驱动相结合，增强了换能器间距以下的能量传递，在皮肤下方生成可调节的三维触觉焦点。这一设计允许用户在稳定抓取物体（如鼠标、把手）的同时，在指尖接收空间和时间上演变的动态触觉信息。系统能实现超过200赫兹的振动和亚振幅精度的触觉反馈，极大拓宽了人机交互的信息传输维度。","scd":null,"kp":[]},{"i":39408,"as":"植物在面临碳饥饿时需要快速的线粒体重塑。研究发现了一种协调程序，整合了外周分裂介导的损伤隔离和大规模线粒体自噬。碳饥饿触发了从对称的中区分裂到不对称的外周分裂的转变，产生小而去极化的片段和较大的极化线粒体。不依赖损伤的大规模线粒体自噬针对中型线粒体，以减轻负担和调动资源，同时排除小的外周分裂产物。研究确定了内质网-线粒体连接蛋白1（ML1），它是一种碳饥饿诱导因子。","scd":null,"kp":[]},{"i":39409,"as":"气溶胶-云相互作用具有高度非线性，在气溶胶限制状态下气候效应最强。通过结合卫星观测和气候模型模拟，研究发现该状态在过去20年中以每十年4.8%的速度扩张，主要归因于北半球人为排放的减少（每十年增加约14.7%）。在强减排路径下，预计关键海域的频率将增加两到三倍。这种系统性转变正在推动海洋云层状态发生改变。","scd":null,"kp":[]},{"i":39410,"as":"聚乙烯在理论上具有极佳的导热性能，但非晶结构阻碍了热量传输。研究发现，高取向聚乙烯中部分有序的非晶过渡相不仅不是加工的负面副产物，反而是热传导的关键贡献者。基于此，研究开发了一种凝胶态间歇慢拉伸方法，引导聚乙烯纤维成型过程中的非晶演化。该方法促进了通常被认为是非晶和界面区域的链松弛和结构重组，从而显著提升了材料的导热性能。","scd":null,"kp":[]},{"i":39411,"as":"研究提出了一种基于流体的多轴机械软力传感器（ME-SOFS），通过直接将传感信号与流体驱动耦合，消除了对外部计算或能量输入的需求。这种传感器是反应式架构的机械类比，能够轻松重新配置和集成，赋予机器人体感多轴力传感能力。基于流体转导原理，ME-SOFS将施加的力直接转化为机械运动信号，实现传感与驱动的无缝连接。","scd":null,"kp":[]},{"i":39412,"as":"研究开发了一种柔软、可穿戴的近红外光谱（NIRS）系统，用于检测睡眠期间与类淋巴系统活动相关的脑水动态。该设备集成了多波长LED和光电探测器。针对多名受试者的体内研究在自然家庭环境中进行了整夜睡眠监测，揭示了不同睡眠阶段脑水动态的连续变化。研究结果支持了睡眠阶段依赖性脑水动态与类淋巴活动之间的联系，解决了持续实时监测的挑战。","scd":null,"kp":[]},{"i":39413,"as":"通过在上地壳应力条件下对花岗岩样品进行流体注入实验，研究同时追踪了流体压力和无震滑移的传播。实验表明，在低注入速率和低初始应力下，无震滑移滞后于压力锋；但在高注入速率或接近破坏的初始应力条件下，无震滑移会迅速超过压力锋。这种转变由一个整合了注入速率、断层强度和初始剪应力的无量纲加载参数控制。研究为裂缝力学模型提供了直接的实验验证。","scd":null,"kp":[]},{"i":39414,"as":"研究挑战了胶束聚集体（MAs）仅由疏水尾部和带电头基简单组装而成的传统观点，证明它们具有特定的表面活性剂微结构域。利用芘标记的聚酰胺胺树状聚合物进行表征，发现这些微结构域是由同一SDS胶束内带电和部分被氯化钠中和的表面活性剂发生局部相分离形成的。带电表面活性剂构成极性边缘，部分中和的形成非极性中间区域，树状大分子在其中进行空间分配。","scd":null,"kp":[]},{"i":39415,"as":"针对自2009年以来平流层羟基自由基（OH）卫星观测数据的严重缺失，研究开发了一种基于化学信息的深度学习网络DRCAT。该网络利用化学相关物种的同步卫星观测数据来预测平流层OH剖面。仅使用两年的数据进行训练，DRCAT成功重建了从2004年底至今连续且可靠的全球平流层OH数据集。结果表明，DRCAT的性能优于化学传输模型和观测约束的稳态近似方法。","scd":null,"kp":[]},{"i":39416,"as":"全球珊瑚礁正经历前所未有的快速衰退。文章提出，艺术可以作为一种灯塔，在科学与艺术的结合中发挥作用，旨在吸引受众关注珊瑚礁危机，影响相关政策制定，并激发全球范围内的保护行动。","scd":null,"kp":[]},{"i":39417,"as":"三维（3D）拓扑陈绝缘体的标志性特征是拓扑陈向量C=(C1, C2, C3)。然而，目前的拓扑陈向量仅局限于单一非零分量的最简单形式，即C=(0,0,C3)。这种限制导致手性表面态仅出现在四个侧面上，并在陈向量方向上呈现非手性传输。本研究致力于突破这一限制，探索实现任意拓扑陈向量的光子系统。","scd":null,"kp":[]},{"i":39418,"as":"受石蛾幼虫茧结构的启发，研究开发了一种兼具高韧性和增强离子传输的凝胶聚合物电解质（CLC GPE），用于安全的锂金属电池。该电解质将静电纺丝聚偏氟乙烯-六氟丙烯支架与剪切增稠流体相结合。CLC GPE实现了高达2.80×10^-3 S/cm的离子导电率，锂离子迁移数为0.89，韧性达到7.29 MJ/m^3，并具备优异的抗刺穿能力，有效解决了离子导电性与机械强度之间的权衡问题。","scd":null,"kp":[]},{"i":39419,"as":"研究开发了一种通用的“多合一”癌细胞衍生疫苗，通过共递送CIITA、NLRC5、CD80和IL-2，将肿瘤细胞重编程为抗原递呈细胞。这种重编程模拟了专业抗原递呈细胞的表型，能够同时提供HLA-I和HLA-II抗原递呈。UniCVac具备全面的抗原谱覆盖能力，克服了传统癌症疫苗抗原覆盖有限、递呈不足以及微环境免疫抑制等挑战，为引发T细胞免疫反应提供了新策略。","scd":null,"kp":[]},{"i":39420,"as":"通过热激剥离氟化铈镁氧（Gd0.1Ce0.9O1.95），研究成功创建了铈-钆-氧簇。这些无序的、空位分离的团簇在不具备长程有序结构的情况下形成了渗流氧离子通道。测试表明，该材料在400°C下的氧离子电导率高达2.14 ± 0.09 S/cm，比以往大多数导体高出320倍以上，成功克服了传统导体需要高温运行的电导率瓶颈。","scd":null,"kp":[]},{"i":39421,"as":"受微生物无神经处理自主性的启发，研究开发了具备物理智能的胶囊机器人（PI Capbots）。该机器人能够在体积、功耗和生物安全性受限的条件下，紧密集成传感、决策和驱动功能。针对胃肠道稳态失调的临床评估需求，PI Capbots基于压力、温度和pH等阈值生理指标，在体内实现动态监测和事件触发的原位治疗，解决了微型医疗机器人难以在胃肠道内综合执行功能的挑战。","scd":null,"kp":[]},{"i":39422,"as":"研究利用肺泡器官筛选平台调查了肺干细胞与成纤维细胞生态位之间的相互作用。通过评估干细胞中201个候选基因的作用，并结合嵌合RNA测序分析，构建了表型-转录组图谱。该图谱揭示了调节增殖、代谢和免疫信号的细胞状态及通路。研究发现，干细胞能影响成纤维细胞的瘢痕形成和免疫程序，且该损伤反应依赖于干细胞的身份特异性。","scd":null,"kp":[]},{"i":39423,"as":"茧蜂依赖多分体DNA病毒（Bracovirus）来寄生鳞翅目宿主。尽管茧蜂病毒编码了8个口服感染因子（PIF）同源物，但由于其通过寄生蜂直接注射病毒，缺乏口服感染途径，其进入宿主细胞的机制尚不明确。本研究使用中红侧沟茧蜂及其鳞翅目宿主（如粘虫和棉铃虫）作为模型，揭示了PIF复合体在茧蜂病毒感染和寄生蜂寄生过程中的必要性。","scd":null,"kp":[]},{"i":39424,"as":"针对糖尿病治疗中抗氧化药物胃肠转运差和胰腺靶向性不足的问题，研究确定了与铁死亡相关的氧化应激是胰岛β细胞死亡的关键原因。通过将弯曲的油酸嵌入有序的1,2-二硬脂酰-sn-甘油-3-磷脂酰乙醇胺中，研究人员开发了六种具有不同硬度梯度的口服纳米颗粒。具有中等硬度的纳米颗粒能够优化细胞膜包裹，最小化能量消耗，从而有效恢复受损的胰岛β细胞。","scd":null,"kp":[]},{"i":39425,"as":"补体过敏毒素（如C3a和C5a）通过典型GPCR引发炎症反应。EP67是一种源自C5a的十肽免疫刺激候选药物，在抗病毒和抗菌方面展现出潜力，但其分子机制和精确受体靶点尚不明确。研究对EP67在人类和小鼠的C3aR及C5aR1上进行了全面的药理学分析，发现它优先激活人类C3aR，从而在不引发过度炎症的情况下引发免疫反应。","scd":null,"kp":[]},{"i":39426,"as":"纳米科学领域的先驱Louis E. Brus（1943-2026）的讣告。他是一位纯粹的物理化学家，也是探索纳米级材料光谱学的先驱。他的职业生涯是受好奇心驱动的科学的丰碑，在20世纪80年代和90年代的贝尔实验室中孕育了具有影响力的科学成果。他的智慧、指导与善良将被朋友、学生和同事深深怀念。","scd":null,"kp":[]},{"i":39427,"as":"","scd":null,"kp":[]},{"i":39428,"as":"陨石球粒的历史可追溯至太阳系早期，但其在行星形成中的作用一直不明确。研究展示了一条形成含球粒陨石的坚固路径：在类地行星形成的后期，原行星胚胎之间的碰撞导致熔融物质冷却形成球粒，并与胚胎中心圆盘中的喷射物（未熔融物质）混合。这些物质吸积成大量小行星大小的卫星，随后由于与其他胚胎的引力相遇，它们被弹射到日心轨道上，成为如今的陨石母体。","scd":null,"kp":[]},{"i":39429,"as":"海洋云层增亮（MCB）是一种旨在减少长期变暖的太阳地球工程建议。研究利用2019-2020年澳大利亚野火的自然实验，证明了在东南太平洋模拟MCB可以重现云层增亮及随后的拉尼娜现象响应。模拟显示，在厄尔尼诺增长阶段启动MCB会破坏比耶克尼斯反馈机制。研究表明区域性的MCB能够有目的地干预并改变厄尔尼诺-南方涛动（ENSO）现象。","scd":null,"kp":[]},{"i":39430,"as":"联会复合蛋白SYCP1曾被认为仅在减数分裂中起作用，但研究发现其在乳腺癌等多种人类实体瘤中存在异常重新表达。整合分析表明，SYCP1在肿瘤细胞中结合于染色质的调控元件上，直接控制基因组维持相关的转录程序，积极促进DNA损伤修复、细胞周期进程和恶性生长。这揭示了SYCP1在癌症中的关键调控作用。","scd":null,"kp":[]},{"i":39431,"as":"俯冲带是地表硫元素进入地幔的主要途径。研究通过整合海洋钻探沉积物成分与地震数据，建立了全球海沟的俯冲硫清单。结果显示，受沉积物硫含量差异及侵蚀型与增生型边缘构造差异的影响，俯冲板块的硫通量存在显著的空间异质性。全球板片至岛弧的硫循环平均效率约为37%。","scd":null,"kp":[]},{"i":39432,"as":"胃癌转移伴随代谢重编程，研究发现线粒体酶ALDH6A1是一种抗入侵因子。ALDH6A1表达异常降低会阻断缬氨酸分解代谢的最后一步，导致甲基丙二酸（MMA）在细胞内积累。积累的MMA竞争性占据组蛋白去甲基化酶KDM5C的辅助因子口袋，抑制其活性，从而增加侵袭相关基因（如ANGPT2和MMP7）启动子上的H3K4双甲基化，最终促进胃癌的侵袭性转移。","scd":null,"kp":[]},{"i":39433,"as":"前扣带皮层（ACC）在协调社交行为和注意力方面发挥重要作用。研究在ACC中发现了两个功能不同的谷氨酸能神经元亚群，分别投射至丘脑网状核边缘区和未定带。这两个亚群差异性地介导了社交互动和注意力分配。在Shank3b突变的自闭症模型小鼠中，这两种行为均出现缺陷。通过光遗传学激活特定ACC通路可以调控这些功能。","scd":null,"kp":[]},{"i":39434,"as":"罗马混凝土结构因其卓越的耐久性闻名近两千年。除了传统的火山灰与石灰之间的火山灰反应外，研究利用多尺度光谱和断层扫描技术对哈德良别墅的古混凝土进行了分析。结果证实，长期的碳化作用（矿物化碳酸盐的形成）同样显著增强了混凝土的耐久性以及潜在的自愈能力。这一发现为古建筑的长寿命机制提供了新的解释。","scd":null,"kp":[]},{"i":39435,"as":"传统丙烷脱氢高耗能且依赖化石合成气。研究提出并设计了一种由二氧化碳辅助的氧化脱氢-氢甲酰化级联反应（CO2-ODH-HF）。该架构利用CO2替代传统脱氢反应器，并循环利用CO2在系统内部生成一氧化碳和氢气。Aspen Plus模拟显示，这种反应路径的转变成功实现了合成气的自给自足，大幅提升了碳效率，有效实现了丙烷的升级转化。","scd":null,"kp":[]},{"i":39436,"as":"内皮细胞功能障碍是心脏异种移植长期存活的主要障碍。单细胞RNA测序鉴定出VCAM-1+内皮亚群是极易发生急性排斥反应的主要细胞类型。为保护该细胞群，研究开发了靶向VCAM-1的纳米颗粒（VTN）。VTN集成了VCAM-1结合肽和自组装模块，能够形成保护性纳米纤维涂层覆盖血管内皮，从而有效保护血管内皮并延长心脏异种移植的存活时间。","scd":null,"kp":[]},{"i":39437,"as":"浮游植物基因组大小的进化受到营养物质可用性的严格限制。研究基于核苷酸的磷氮成本及细胞营养需求，推导了插入/缺失突变的选择系数。结果表明，在营养需求较低的浮游植物中，自然选择显著大于遗传漂变，促使缩小基因组大小的突变发生固定。比较基因组学和宏基因组学分析证实了这一模型预测，揭示了细胞营养经济对基因组大小进化的决定性影响。","scd":null,"kp":[]},{"i":39438,"as":"非本征铁电体在理论上没有本征厚度限制，但传统实验中薄膜厚度低于6个晶胞时铁电性即消失。研究打破了传统主要集中在面内晶格失配的外延设计范式，引入面外方向的结构相容性考量。通过这种方法，研究在单层厚度极限下成功实现了不减的非本征几何铁电性。这一结果从实验上证实了非本征铁电体不存在临界厚度的理论预测。","scd":null,"kp":[]},{"i":39439,"as":"新生儿支气管肺发育不良（BPD）等肺病的分子机制尚不明确。研究提出了一种多模态成像工作流，结合质谱和非线性光学成像技术，在多个空间尺度上对肺组织的分子和代谢特征进行详细表征。研究还开发了分层多模态配准网络，实现了不同模态数据的精准配准。这种方法能够有效提供多尺度的肺部代谢映射信息，助力肺病诊断与治疗研究。","scd":null,"kp":[]},{"i":39440,"as":"基于卫星热红外观测数据，研究量化了2013至2024年间美国287座大型大坝上下的河流表面温度差异。结果发现，71%的纵向河流剖面存在下游温度改变，其中60%表现为变暖。这些温度变化通常在坝下20公里范围内持续或继续增加。下游温度改变的幅度和频率因大坝类型而异，其中91%的极端温度事件可归因于特定大坝的调节影响。","scd":null,"kp":[]},{"i":39441,"as":"玉米作为主食虽然富含碳水化合物，但缺乏必需的赖氨酸。通过对伯利兹南部39个人类遗骸的氨基酸稳定碳同位素数据进行分析（距今6100至1100年），研究揭示了早期人类如何克服以玉米为主食带来的营养缺陷。混合模型结果表明，人类通过食用以玉米为饲料的动物来获取动物蛋白，这种营养级放大作用为人类饮食补充了玉米来源的赖氨酸，保障了营养均衡。","scd":null,"kp":[]},{"i":39442,"as":"毒牙、毒刺和棘刺等生物穿刺结构在自然界中趋同进化。研究基于机械工程原理分析了140多种生物穿刺工具。结果显示，这些工具的多样性主要受抗屈曲能力与穿刺效率之间的权衡影响。生物在权衡景观中的位置部分取决于其生物学功能，但与工具本身的可替换性几乎无关。这表明简单的几何定律结合机械性能权衡能够充分描述穿刺工具的进化多样性。","scd":null,"kp":[]},{"i":39443,"as":"多参数量子估计面临的核心挑战在于不同参数的最优测量不兼容，导致复杂的精度权衡。研究提出了一种新方法，能够精确量化多参数量子估计中的最小权衡界限。通过确定最优测量策略，该方法有效厘清了精度权衡关系，有助于更深入地理解和探索多参数估计的量子极限。","scd":null,"kp":[]},{"i":39444,"as":"研究提出了一种受量子纠错启发的噪声缓解协议，用于提升量子传感器探测波状暗物质的灵敏度。该协议利用多个传感器来缓解单个传感器受到的噪声影响，从而有效抑制激发噪声。这种方法能够在使用量子传感器进行暗物质探测时，显著滤除背景噪声，提高探测精度。","scd":null,"kp":[]},{"i":39445,"as":"研究重新考察了具有SU(N)对称性的厄米矩阵量子力学在大N极限下的性质。已知其单态部分可以通过自由费米子精确求解。研究发现，当费米能级接近势能最大值时，系统会表现出与弦理论相关的临界行为。通过研究伴随部分的矩阵量子力学，研究成功推导出了相应的雷吉轨迹。","scd":null,"kp":[]},{"i":39446,"as":"LHCb合作组报告了对中性B介子衰变（B0→K*0μ+μ−）的全面测量分析结果。这一罕见的衰变过程测量能够为检验标准模型提供关键数据支持。最新的精确测量结果或将为探索超出标准模型的新物理现象提供重要线索和指示。","scd":null,"kp":[]},{"i":39447,"as":"LHCb合作组利用Run 3探测器收集的质子-质子碰撞数据，首次观测到了双粲重子Ξcc+。该粒子通过衰变至Λc+K−π+末态被探测到，其统计显著性超过了七倍标准偏差。这一新粒子的发现为重子谱学和强相互作用研究提供了重要的实验证据。","scd":null,"kp":[]},{"i":39448,"as":"拉姆齐干涉术是一种用于光谱学、时间频率精确测量和原子钟的高分辨率技术。传统实验通常在光学稀薄的原子样本中进行。研究在光学厚原子系综中实现了拉姆齐干涉术，不仅实现了光谱线宽的指数级缩窄，还显著提升了测量灵敏度。这一突破优化了高精度测量的技术路径。","scd":null,"kp":[]},{"i":39449,"as":"研究建立了一种几何涨落-耗散关系，将直流几何电流涨落与非线性热电响应直接联系起来。传统涨落定理主要描述平衡态噪声与线性响应，而该工作将其拓展至几何驱动的非线性输运领域。该研究填补了统计物理与量子物理在非线性区间的理论空白。成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39450,"as":"研究提出了一种统一的第一性原理公式，用于解释时间分辨角分辨光电子能谱（ARPES）中相干和非相干激子诱导的电子能带结构改变。该微观定量框架突破了低密度极限的限制，弥补了现有实验进展与理论解释之间的空白，能够准确解释高密度激子效应下的光谱特征。成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39451,"as":"研究在WSe2包覆的单层石墨烯中实现了纯谷-塞曼自旋轨道耦合的调控。通过清晰分辨的朗道能级，揭示了由固定谷-塞曼劈裂与磁场依赖的回旋能之间的竞争所驱动的对称性强制朗道能级重排现象。该成果为石墨烯自旋轨道耦合的精确控制提供了实验证据，发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39452,"as":"本文是对关于1T-TiSe2中手性电荷密度波的光致动力学与动量分布研究的评论。C. Xu等多名研究人员参与了此次学术评论，针对此前发表在《物理评论快报》上的相关实验结果或理论解释提出了学术探讨与质疑。该评论发表于2026年7月8日。","scd":null,"kp":[]},{"i":39453,"as":"本文是Qiu等人对上述关于1T-TiSe2手性电荷密度波评论的回复。Qingzheng Qiu等多名研究人员针对评论中提出的学术质疑进行了答辩与补充说明，进一步阐述了其关于光致电荷密度波动力学的研究结论。该回复同发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39454,"as":"研究证明了扩散方程与狭义相对论是兼容的。传统观点认为，扩散方程具有抛物线特征，表现出瞬时空间扩展，在洛伦兹 boosts 下会变得不稳定，因此与狭义相对论存在根本的不兼容性。本研究打破了这一传统解释，证实了该方程在相对论框架下的适用性。成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39455,"as":"研究提出了一种通过M个解耦子空间耦合机制生成跨越整个布里渊区的平带的新机制。在光子超晶格系统中，平带能够实现强光局域和增强的光-物质相互作用，但在整个布里渊区实现平坦色散十分困难。该机制为光子系统中平带的设计与调控提供了实用方案。成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39456,"as":"研究开发了一种基于监督学习的喷注淬灭识别方法，应用于模拟的重离子碰撞。传统方法依赖全局可观测变量，无法全面捕捉部分子与夸克-胶子等离子体介质相互作用的复杂动力学特征。该方法利用机器学习提取复杂信息，为微观探究等离子体性质提供了优于传统手段的分析工具。成果发表于《物理评论C》。","scd":null,"kp":[]},{"i":39457,"as":"研究提出了一种用于加速提取锂的分子离子门控策略，通过界面工程将选择性与容量解耦。该研究构建了由LiMn2O4核心和A15C5功能化氧化石墨烯壳层组成的核壳结构（LMO@CGO）。该架构有效抑制了钠离子的竞争通量，实现了高度选择性的Li+传输。实验结果和动力学模型证实了该策略在电池去离子化系统中复杂盐水提锂的有效性。","scd":null,"kp":[]},{"i":39458,"as":"","scd":null,"kp":[]},{"i":39459,"as":"研究解析了人类干细胞衍生胰岛中α细胞与β细胞的命运分配机制。研究人员生成了ARXCFP/CFP和PAX4mCherry/mCherry敲入的多能干细胞报告系，结合单细胞多组学分析，揭示了人类特异性的调控网络。研究发现小鼠模型中Arx和Pax4转录因子的交叉抑制机制在人类细胞中有所不同，填补了体外工程化胰岛细胞分化机制的知识空白。","scd":null,"kp":[]},{"i":39460,"as":"研究开发了名为FloatForm的自重构模块化机器船平台。这些微型模块化机器船能够通过混合协调框架自主组装成物理连接的结构，进行自重构，并作为大型装配体集体移动。每个机器人单元均配备机载系统，克服了水面复杂非线性水动力学和外部环境干扰，解决了水面二维自主重构的难题，可广泛应用于基础设施建设和环境监测。","scd":null,"kp":[]},{"i":39461,"as":"研究利用木材的分级结构和大比表面积，开发了一种基于木材的离子选择性发电机，用于废水发电。通过浸涂带正电或负电聚合物并经阳光诱导聚合，制备了阴/阳离子选择性木膜（环保材料占比达98%）。在脱硫废水中，单个改性木电池的输出电压和电流分别达55 mV和0.6 µA，比未处理木电池高十倍，实现了废水中总溶解固体的持续电力转化。","scd":null,"kp":[]},{"i":39462,"as":"研究针对索尔顿海地热卤水的大规模提锂项目进行了技术经济分析。评估基于企业披露、工艺专利和卤水资源建模，发现大规模生产成本约为每吨1万美元；若考虑锂和杂质浓度变化、卤水随时间稀释以及碳化或电解等不同工艺配置，生产成本最高可达每吨2.2万美元。该评估为地热卤水提锂的商业化提供了成本依据。","scd":null,"kp":[]},{"i":39463,"as":"研究在300毫米CMOS兼容代工厂工艺制造的硅自旋量子比特器件中实现了八比特运行。研究人员成功调试并相干控制了由八个量子比特组成的线性阵列，将其配置为四个双量子点对。所有量子比特的拉曼退相干时间（T2*）最高达41微秒，Hahn回波相干时间最高达1.31毫秒。该成果成功读取了中央四个量子比特，证明了硅自旋量子比特系统超越双比特规模的可扩展性。","scd":null,"kp":[]},{"i":39464,"as":"研究展示了利用磁交换力显微镜在MgO薄膜上对单个钬原子磁体进行读写操作。单原子比特通过吸附位的强单轴各向异性稳定其自旋取向。读取机制通过测量磁针尖与钬原子之间的交换力来实现；写入操作则是通过进一步缩短针尖与原子的距离来完成。这种基于机械交互的读写方法为低发热、高密度存储设备的研发提供了技术途径。","scd":null,"kp":[]},{"i":39465,"as":"研究开发了用于预测DNA-DNA相互作用的深度学习模型BINND，能够准确预测非正交（不相似）的DNA结合。传统分子生物工程主要关注正交性，该研究结合超高通量实验平台测量的数百万次相互作用数据训练模型，准确率超过80%，能够泛化至不同序列空间。该技术突破了序列空间限制，成功设计并工程化了高度互连的DNA网络。","scd":null,"kp":[]},{"i":39466,"as":"研究在单个CuInP₂S₆忆阻器中实现了Bienenstock-Cooper-Munro（BCM）规则，模拟了大脑的稳态可塑性。研究发现该器件的内在结电容会产生反向尖峰，引发依赖于尖峰频率的电导抑制，并结合二阶离子动力学，自然复现了BCM规则的关键特征。仿真表明，添加类似的电容可实现通用的BCM规则，为类脑计算中的突触器件设计提供了新方法。","scd":null,"kp":[]},{"i":39467,"as":"研究引入了一类分形晶格，将长程周期有序性与自相似层级结构相结合，实现了拓扑边界态的指数级缩放。研究在由Koch曲线构成的准一维晶格链和由Sierpiński垫片构成的二维周期镶嵌晶格中验证了该现象。在特定耦合参数下，系统中的拓扑边界态数量和拓扑微隙数量均实现指数级增长，为拓扑材料设计提供了新的结构基序。","scd":null,"kp":[]},{"i":39468,"as":"研究探讨了掺杂电荷转移绝缘体中的束缚态物理问题，这是理解高温超导的核心难题。研究基于一个局域Zhang-Rice单态和Néel态构建近似基态波函数，发现了电荷转移能隙内存在束缚态。该结论通过对4×4 CuO2晶胞系统进行基于矩阵乘积态的Lanczos计算得到证实，并进一步探讨了这些束缚态向金属态的演化过程。","scd":null,"kp":[]},{"i":39469,"as":"研究演示了一种可逆堆叠的单片三维互补场效应晶体管架构，突破了传统后端工艺低于400°C的热预算限制。该平台采用低温沉积的n型In2O3和p型Te半导体材料，摆脱了传统高温生长或转移条件的固定堆叠顺序约束，实现了高密度、高能效逻辑和存储系统的密集垂直堆叠设计自由度。","scd":null,"kp":[]},{"i":39470,"as":"","scd":null,"kp":[]},{"i":39471,"as":"量子光工程的发展使得红外明亮压缩真空（BSV）飞秒脉冲被应用于强场物理和高次谐波产生等非线性光学领域。先前的理论主要集中于单原子相互作用，忽略了光在介质中传播的宏观效应。为此，研究人员提出一个全量子化框架，用于分析气体介质中产生高次谐波时的传播过程。研究发现，电离及其导致的光子损耗会引发退相干效应，限制了光在介质中的传播长度，降低了辐射的量子特性，并减少了谐波的发射。","scd":null,"kp":[]},{"i":39472,"as":"强磁场中子星的吸积通常使用准稳态模型解释，认为吸积柱结构随质量流入率平滑变化。X射线光谱中的回旋线质心能量可用于示踪磁场强度和区域高度。研究人员在X射线脉冲星1A 0535+262的巨大爆发期间，观察到了准周期的硬X射线通量变化，并伴随回旋线能量的同步振荡，其振荡幅度超出了简单吸积率波动的预期，且回旋线能量与通量之间存在反相关性。","scd":null,"kp":[]},{"i":39473,"as":"原子尺度缺陷对低维材料的性质起着决定性作用。传统上，横向力显微镜（LFM）被认为对最外层原子下方的结构特征不敏感。这项研究打破了这一观念，证明了LFM不仅能检测二硫化钼（MoS2）中的原子空位，还可以根据空位的深度对其进行分类。该技术通过悬臂的侧向扭转测量摩擦力，为探测材料表面和次表面结构提供了有效方法。","scd":null,"kp":[]},{"i":39474,"as":"扭曲双层石墨烯的超导性质一直是物理学界未解之谜。受近期在莫尔石墨烯超导体中观察到Kekulé有序性的启发，研究人员为其构建了微观理论。研究发现，这种超导态是一种谷内有限动量的对密度波（PDW），本征携带Kekulé调制。该状态具有四个显著特征：自发破坏C3旋转对称性产生向列序、三重态配对，以及随着吸引力增加，准粒子态密度从V形演变为具有完整能隙的U形光谱。","scd":null,"kp":[]},{"i":39475,"as":"液态和玻璃态是两种密切相关的无序物质状态。数十年来，关于它们是否存在结构不同但化学成分相同的多晶型现象，以及平衡液体与非平衡玻璃态多晶型之间的关系一直存在争议。研究人员利用金刚石压砧中的原位高温高压同步辐射X射线衍射技术，在两种典型的金属玻璃形成合金中开展研究。通过多个衍射结构描述符的可重现的不连续变化，证实了在熔点之上存在不同的液态，并在不同压力下熔体淬火形成相应的玻璃态。","scd":null,"kp":[]},{"i":39476,"as":"实现可逆的四电子氧气析出反应是非水系氢氧化锂（LiOH）锂氧电池面临的核心挑战。研究人员利用铁钴镍层状双氢氧化物催化剂和环丁砜基电解液，构建了高度可逆的LiOH锂氧电池。研究表明，LiOH分解释放氧气的过程涉及表面结合的羟基和羟基自由基等关键活性氧物质，但不产生单线态氧。这些羟基物质会腐蚀电解液和碳载体，是导致电池副反应的主要原因。","scd":null,"kp":[]},{"i":39477,"as":"","scd":null,"kp":[]},{"i":39478,"as":"β-桶组装机器（BAM）对外膜蛋白（OMP）的正确折叠至关重要。当OMP生物发生受到干扰时，β-桶组装增强蛋白酶A（BepA）会与BAM结合执行质量控制。冷冻电镜结构显示，BepA会诱导BAM复合物发生巨大的构象变化，使其活性位点位于BAM外周质环内。BepA的盖子具有动态特征，与BAM结合时将其两个水溶性螺旋深嵌入膜双层中，从而为错误折叠蛋白的蛋白水解做好准备。","scd":null,"kp":[]},{"i":39479,"as":"基因组病原体监测对公共卫生至关重要，但在低资源环境中成本高昂且难以实现。研究人员开发了“Phylo-Plex”测序平台，通过识别信息丰富的基因组区域，在最大化系统发育信息的同时最小化目标区域数量。该方法针对梅毒螺旋体和淋病奈瑟菌设计了高分辨率多重PCR测序方案。在针对梅毒螺旋体的临床测试中，利用MinION Flongle测序细胞成功对72个临床样本进行了测序，实现了高效谱系追踪。","scd":null,"kp":[]},{"i":39480,"as":"在一项为期24个月、针对21至50岁非肥胖男性和绝经前女性的随机对照试验中，评估了热量限制（CR）对代谢健康的影响。结果显示，热量限制与高分子量脂联素水平升高有关，并降低了与胰岛素抵抗相关的神经酰胺（如C16:0、C18:0和C24:0）水平。中介分析表明，神经酰胺的减少在统计学上可解释热量限制对胰岛素分泌和敏感性改善的部分介导作用。","scd":null,"kp":[]},{"i":39481,"as":"","scd":null,"kp":[]},{"i":39482,"as":"慢性神经炎症会引发大脑中小胶质细胞状态的多样化。研究发现，皮层脑损伤后，小鼠丘脑中吞噬突触的小胶质细胞会导致认知障碍（主要在雌性中研究）。在慢性期对丘脑反应性小胶质细胞的区域特异性操作会损害识别记忆，而海马体中的操作则不会。单细胞RNA测序表明，丘脑中富含吞噬突触的CD9hi小胶质细胞。基于抗体的CD9阻断和小胶质细胞选择性CD9破坏，能够挽救突触丧失、恢复神经元活动并改善识别能力。","scd":null,"kp":[]},{"i":39483,"as":"美国首次对养殖水貂进行SARS-CoV-2主动监测，在2022至2023年间收集的样本中检出约0.9%的RT-PCR阳性率。基因组系统发育分析表明，适应人类的变异株（如Omicron）反复溢出传染给水貂。值得注意的是，在人类中最后一次检测到Delta变异株四个月后，水貂农场内仍检出了Delta谱系病毒（AY.39），表明存在长期的未被采样传播。此外，水貂适应的AY.39病毒已传播至邻近的野生白尾鹿中。","scd":null,"kp":[]},{"i":39484,"as":"尽管成年中性粒细胞的发育和防御功能已被充分了解，但关于胎儿中性粒细胞的研究仍然有限。对小鼠胚胎发育的研究表明，在血液和非造血稳态器官中存在大量未成熟和成熟的组织驻留中性粒细胞。单细胞转录组分析证实，在胎儿和新生小鼠的血液以及非造血组织中存在中性粒细胞祖细胞和前体细胞。此外，胚胎组织驻留的中性粒细胞在转录特征上与胚胎血液中的中性粒细胞存在差异。","scd":null,"kp":[]},{"i":39485,"as":"野生多年生植物的驯化有助于提高农业的多样性，但由于基因组庞大，许多植物难以进行分析。研究人员利用三重分选技术，为两种原产于北美洲的植物组装了分阶段基因组。这些基因组染色体长达1.8 Gb，且在间期保持了43 Mb环周长的螺旋结构。基于基因组信息的低覆盖度靶向测序策略，不仅精炼了该属的系统发育关系，揭示了自然种群的空间分布，还鉴定出81个与环境和驯化性状相关的基因位点。","scd":null,"kp":[]},{"i":39486,"as":"","scd":null,"kp":[]},{"i":39487,"as":"","scd":null,"kp":[]},{"i":39488,"as":"","scd":null,"kp":[]},{"i":39489,"as":"","scd":null,"kp":[]},{"i":39490,"as":"","scd":null,"kp":[]},{"i":39491,"as":"","scd":null,"kp":[]},{"i":39492,"as":"脑转移是癌症转移的关键部位。研究人员设计了一种两性离子聚羧基甜菜碱（PCB）纳米递送系统，用于精准靶向脑转移瘤。该系统能够在血脑肿瘤屏障（BBTB）处选择性结合甜菜碱-γ-氨基丁酸转运蛋白1（BGT1），使纳米颗粒在肿瘤血管内局部富集。PCB固有的机械灵活性可激活内皮细胞中的Piezo1离子通道，引发钙离子内流，从而在无需外部刺激的情况下于肿瘤血管内快速释放治疗药物。","scd":null,"kp":[]},{"i":39493,"as":"在对其研究生态系统进行大规模重组后，印度尼西亚正在其古生物学研究领域中占据主导地位。该国正致力于自主引领人类历史和本土古生物学的科学研究。","scd":null,"kp":[]},{"i":39494,"as":"许多TSC2错义变异被归类为意义不明的变异（VUS），难以进行结节性硬化症（TSC）的精确遗传诊断。为解决传统功能检测无法规模化处理的问题，研究人员利用大规模平行测序测量了近9000种TSC2错义变异的稳态丰度，并结合基因组编辑开发了mTOR途径活性测定法。结果显示，14.17%的被测错义变异改变了TSC2丰度，17.65%的变异改变了mTOR途径的活性。","scd":null,"kp":[]},{"i":39495,"as":"生物分子凝聚物的形成依赖于通常微弱且瞬态的多价相互作用，实验研究极具挑战。研究人员开发了基于mRNA展示的凝聚物分配技术（CPmD），通过测量肽和核酸进入重组凝聚物的分配自由能来量化这些相互作用。CPmD将实验通量提高了几个数量级。研究揭示了内在无序蛋白驱动凝聚物形成的相互作用机制，证明约十万个来源于无序蛋白质组的肽在模型凝聚物中的分配自由能直接反映了它们的多价相互作用。","scd":null,"kp":[]},{"i":39496,"as":"海洋内部的小尺度湍流混合对海洋环流和全球气候至关重要。研究表明，内部湍流混合在多种时间空间尺度上影响气候系统。除了在百年至千年时间尺度上促进深海环流平衡外，它在短至亚年度的时间尺度上也是海洋示踪剂收支的主要决定因素。研究还强调了垂直混合和侧向搅拌的相互依赖性在建立大规模海洋结构中的重要性。","scd":null,"kp":[]},{"i":39497,"as":"","scd":null,"kp":[]},{"i":39498,"as":"随着人为气候强迫加剧，土壤水分干旱频繁发生。研究发现，在土壤水分干旱发生后的次年，土壤水分流失引起的年度变暖效应，大于等量水分增加带来的冷却效应。这种不对称的温度响应仅在包含人为温室气体强迫的影响时才会出现。干旱后植被受到的抑制强于水分增加后的恢复程度，导致蒸腾作用和碳吸收减少，是产生这一不对称响应的主要原因。","scd":null,"kp":[]},{"i":39499,"as":"尽管实施了严格的空气政策，中国的臭氧（O3）污染依然持续，这是与气候行动交织的全球性挑战。研究揭示，臭氧减排策略在实现清洁空气和气候协同目标上具有多十年尺度的路径依赖性。2020至2023年间中国特大城市群中O3浓度和敏感性趋势的同时停滞验证了这一路径依赖。基于该理解，研究定量表明，要实现气候与空气质量目标的协同一致，中国必须在早期实施挥发性有机物（VOC）控制。","scd":null,"kp":[]},{"i":39500,"as":"针对湖泊中氮磷保留率及其在营养循环中的作用，研究利用机器学习和贝叶斯分层方法追踪了2012-2022年美国121个湖泊的营养保留变化。结果发现，磷的优先保留比例从2012年的70.3%发生转变，到2022年有92.6%的湖泊转变为氮优先保留。四个关键湖泊指标表现出类闪烁的动态变化，揭示了水生生态系统内部的营养代谢失调状态。","scd":null,"kp":[]},{"i":39501,"as":"","scd":null,"kp":[]},{"i":39502,"as":"研究绘制了首张包含不同形态区分的全球沙丘完整数字地图。研究发现，在干旱环境中，沙丘的存在主要由沉积物汇聚搬运和靠近物源来解释；而在更湿润的气候条件下，风力强度则是额外的限制因素。该数据集基于全球可用图像和地形数据生成，为推断地球及其他星球的沉积物源分布和气候条件提供了一致的基础数据。","scd":null,"kp":[]},{"i":39503,"as":"","scd":null,"kp":[]},{"i":39504,"as":"研究使用包含自然听觉统计规律的刺激物，结合神经外科患者的颅内脑电图记录，探究了时间向前的预测机制。结果显示，预测信号主要由广泛皮质区域（包括感觉、顶叶和额叶区）的低频活动承载。预测误差信号在低频和高频活动中均有发现，其中高频成分主要集中在感觉区域。这一发现打破了先前的假设，揭示了自然听觉处理中的神经机制。","scd":null,"kp":[]},{"i":39505,"as":"研究提出了一款名为NEVA的多模态基础模型，用于解决神经母细胞瘤的生物学异质性和分子分析受限问题。NEVA采用受病理学家启发的分层工作流进行端到端优化。在跨多个中心的1238名患者队列中开发和评估，NEVA在11项临床任务中的大多数任务上表现优于TITAN、UNI等十个代表性基础模型，展现出卓越的性能。","scd":null,"kp":[]},{"i":39506,"as":"研究发现，数百万篇arXiv预印本提交的元数据和源文件中包含了大量原本不应被公开分享的敏感信息。这些意外泄露的数据包括密码、GPS坐标以及私人对话内容。","scd":null,"kp":[]},{"i":39507,"as":"研究提出了基于Transformer的GeneLLM模型，通过直接处理人类映射的cfRNA读长核苷酸序列来识别癌症指示特征。该模型绕过了基因水平定量，保留了来自转录组暗物质的信号。GeneLLM学习潜在伪生物标志物作为癌症分类的判别特征，克服了依赖基因注释的现有液体活检方法会忽视未注释基因组区域信号的缺陷。","scd":null,"kp":[]},{"i":39508,"as":"天文学家发现了两颗环绕同一恒星运行的气态巨行星。这两颗行星的密度极低，是迄今为止发现的密度最小的行星之一，其密度甚至比棉花糖还要轻。","scd":null,"kp":[]},{"i":39509,"as":"针对单原子催化剂活性位点的调控机制，研究结合X射线吸收精细结构观察、模拟和机器学习，确定了堆叠双层金属-金属耦合（MMC）构型是Fe-N-C催化剂中的重要活性位点基序。这一发现解释了层状Fe-N-C催化剂在氧还原反应（ORR）中理论预测与实验活性之间的巨大差异，为单原子催化剂的理性设计提供了原子级描述符。","scd":null,"kp":[]},{"i":39510,"as":"研究结合热力学筛选与增强采样从头算分子动力学，揭示了硼催化丙烷氧化脱氢（ODHP）的真实活性位点。催化活性并非源于静态结构，而是通过[BO3]和[BO4]持续相互转化产生的瞬时超配位[BO4]介导。这种动态的sp2到sp3杂化过程，解释了不可还原的B(III)中心如何高效激活C-H键并保持高丙烯选择性。","scd":null,"kp":[]},{"i":39511,"as":"研究报道了一种通过氨氧基丝氨酸或氨氧基苏氨酸介导的化学编辑策略，实现了对未保护多肽中丝氨酸和苏氨酸的位点特异性修饰。该方法在水溶液中通过瞬态1,2,4-噁二嗪烷中间体发生有效的氨氧基连接，实现N端位置的化学选择性多肽连接。此外，连接后的氨氧基官能团还能与酮酸发生化学选择性酯连接，恢复为天然丝氨酸残基。","scd":null,"kp":[]},{"i":39512,"as":"研究将大体积的环己基三酰胺配体引入镧系化学，成功分离出具有线性CeNCe核心的镧系氮化物络合物。该化合物不含任何碱金属相互作用，由双核铈(IV)金属环与NaNH2在12-冠-4存在下反应制得，产率为48%。其Ce-N键长接近目前报道的最短值，键角达到严格的180°。","scd":null,"kp":[]},{"i":39513,"as":"研究利用深度学习蛋白质设计方法，开发出包含半胱氨酸连接钴卟啉IX辅因子的高度热稳定从头CO2还原酶。通过体内组装并在钴盐补充下评估，筛选出的设计展现出高催化活性（转换数>1000，速率达25 min-1），同时有效抑制了竞争性析氢反应。2.1 Å的晶体结构证实了其与设计模型高度一致，Co-Cys键按预期构建。","scd":null,"kp":[]},{"i":39514,"as":"研究报道了一种数据驱动的策略，使廉价的硝酸锂能够作为稀释锂离子电池电解液的主要盐类。这种设计的低浓度电解质不仅有效降低了成本，还稳定了电池界面，成功实现了软包电池的全天候运行。","scd":null,"kp":[]},{"i":39515,"as":"研究提出了一种采用氧化石墨烯和自组装单分子层的双层策略，应用于锡铅钙钛矿太阳能电池。基于此方法，研究人员成功制备出高效且稳定的三结全钙钛矿太阳能电池。该电池实现了27.3%的光电转换效率，并展现出优异的运行稳定性，其T90寿命达到770小时。","scd":null,"kp":[]},{"i":39516,"as":"","scd":null,"kp":[]},{"i":39517,"as":"","scd":null,"kp":[]},{"i":39518,"as":"","scd":null,"kp":[]},{"i":39519,"as":"","scd":null,"kp":[]},{"i":39520,"as":"","scd":null,"kp":[]},{"i":39521,"as":"","scd":null,"kp":[]},{"i":39522,"as":"","scd":null,"kp":[]},{"i":39523,"as":"","scd":null,"kp":[]},{"i":39524,"as":"","scd":null,"kp":[]},{"i":39525,"as":"","scd":null,"kp":[]},{"i":39526,"as":"研究通过分析39对夫妇的访谈和394份问卷调查，探讨了家庭内部动态对住宅太阳能采用的影响。结果发现，采用太阳能的家庭伴侣具有共同目标和劳动分工（同步角色），而未采用者则存在分歧（对立角色）。浪漫伴侣和父母在家庭决策中扮演着关键角色，但即使是同步家庭，通常也需要外部催化剂（如税收抵免到期）来促成最终采用。","scd":null,"kp":[]},{"i":39527,"as":"研究表明，包含整个家庭的协调和积极商议能够促进太阳能的安装与采用。因此，针对能源采用制定的干预措施，其设计应侧重于支持家庭集体的决策过程，而不是仅仅针对家庭中的单一成员，这样会更加有效。","scd":null,"kp":[]},{"i":39528,"as":"","scd":null,"kp":[]},{"i":39529,"as":"针对真空沉积钙钛矿太阳能电池的结晶控制难题，研究引入了一种结构导向层置于钙钛矿吸光剂下方，并结合原位光致发光技术监测钙钛矿的成核、应变和缺陷。该方法成功改善了结晶质量，从而制造出具有高效率和改进稳定性的钙钛矿太阳能电池器件。","scd":null,"kp":[]},{"i":39530,"as":"针对人工智能数据中心扩张引发的环境问题，研究探讨了缓解策略。硬件设计方面，使用回收或旧组件可通过减少隐含排放使数据中心整体排放降低10-20%。电网集成方面，通过将AI工作负载管理与电网运行条件保持一致，在可再生能源普及率高的电网中可减少约10%的碳排放。此外，数据中心对淡水资源的压力也需重点关注。","scd":null,"kp":[]},{"i":39531,"as":"研究开发了一种基于刚性的半导体聚合物核心的溶酶体自分选纳米降解剂（SOLID），用于降解血清中的致病免疫介质。SOLID能够实现近乎定量的溶酶体积累，通过表面生物偶联在血液中捕获目标免疫介质形成蛋白冠，随后主要在肝脏积累并被肝溶酶体降解。实验表明，捕获IL-6的SOLID成功降低了血清IL-6水平。","scd":null,"kp":[]},{"i":39532,"as":"研究在Slater-Pauling半导体MRu1.5Sb（M = Ti, Zr, Hf）中观察到了原子占位有序现象。由于Ru原子不足，Ru原子在过量的可用晶格位点上采用调制分布，选择性占据4c和4d Wyckoff位置。这种选择性占据不仅破坏了这些位点的局部对称性，还在部分空位填充的Heusler合金中促成了新型原子有序结构的形成。","scd":null,"kp":[]},{"i":39533,"as":"针对层状热电材料PbSnS2面外电子传输受阻的问题，研究提出SnSe合金化策略协同优化n型PbSnS2的面外热电性能。SnSe的引入提高了载流子浓度，通过改善晶格对称性和优化能带结构，显著提升了面外载流子迁移率。此外，合金化产生的点缺陷加剧了声子散射，实现了电子和声子传输的有效解耦。","scd":null,"kp":[]},{"i":39534,"as":"研究提出一种呋喃/丙烯酰胺机械力响应基团，可在3.0 nN的低作用力下被激活。该分子在溶液中能够实现完全且选择性的激活，仅需使用标准超声浴即可完成，无需特殊设备。这一低阈值激活特性克服了传统机械力响应基团激活力过高的问题，在需要高效率和选择性的功能分子控制释放应用中具有显著优势。","scd":null,"kp":[]},{"i":39535,"as":"","scd":null,"kp":[]},{"i":39536,"as":"科学家已确认一种特定的藻类物种是导致超过一百万只海洋动物死亡的元凶。这一发现直接指明了造成此次海洋生态灾难的具体有毒生物凶手。","scd":null,"kp":[]},{"i":39537,"as":"针对工业水系统中硅酸不可控聚合导致结垢的难题，研究提出一种模块化大分子合成平台。该平台结合可控自由基聚合和聚合后修饰技术，制备出链长、官能团和构象可独立调节的聚合物阻垢剂。通过结合计算与实验，研究确定了抑制性能的关键结构-性质关系，并指出了传统阻垢剂存在的关键局限性。","scd":null,"kp":[]},{"i":39538,"as":"研究将粉煤灰和矿渣等工业固体废物转化为高强度、具离子导电性的地质聚合物电解质，并应用于锌离子砖电池。通过工程设计连通孔隙以高效引导离子传输，该材料实现了机械耐久性与长期电化学性能的结合。该成果为开发兼具承重和储能功能的建筑组件提供了新途径。","scd":null,"kp":[]},{"i":39539,"as":"研究开发了一种基于荧光检测水溶性致癌物NDMA的新策略。该方法利用亲和捕获替代传统的色谱柱分离，通过NDMA的光化学转化及其与生物素化聚合试剂的反应，生成可通过链霉亲和素-链霉生物素相互作用选择性富集的生物素标记荧光产物。该检测方法完全在水相中进行，无需样品预处理、浓缩或溶剂交换，成功将分析信号与背景有效分离。","scd":null,"kp":[]},{"i":39540,"as":"研究证明了苏氨酸磷酸化是胶原蛋白三股螺旋中脯氨酸羟基化的生物可逆替代修饰。在使用合成的类胶原蛋白多肽进行实验时，发现大部分氨基酸替换会破坏结构稳定性，但在中央Pro-Hyp-Gly三联体的Yaa位置引入磷酸化苏氨酸能够保留由羟脯氨酸赋予的三股螺旋稳定性。pThr在三股螺旋内充当特定修饰的替代物。","scd":null,"kp":[]},{"i":39541,"as":"研究利用铁电极化辅助策略，成功制备出厚度仅为3.5纳米的石墨烯表皮膜，用于超快速和选择性的分子分离。该技术克服了制备无缺陷石墨烯膜的挑战，利用石墨烯原子级平滑的表面实现分子滑行，有效降低了固有分子摩擦，从而在质量传输中实现了近乎无摩擦的超快渗透。","scd":null,"kp":[]},{"i":39542,"as":"研究利用机器学习势驱动的巨正则蒙特卡洛模拟探索了约250万种电化学NO还原反应的活性结构。研究发现，铁在反应中表现出优异的电化学性能并非源于其本征活性，而是源于在原位条件下的自适应自单原子化能力。反应中铁表面主要被吸附的N*物种覆盖，进而形成FeNx基序。","scd":null,"kp":[]},{"i":39543,"as":"研究揭示了盐辅助化学气相沉积生长WS2过程中，生长界面残留盐导致的环境稳定性瓶颈。空气暴露下，Na和W的非晶残留物结晶并机械破坏WS2层，同时形成富Na吸湿环境，驱动W-S键氧化断裂。动力学分析表明该热激活降解过程表观活化能约为0.22 eV。研究证实生长后退火（PGA）处理可有效消除残留物并稳定材料结构。","scd":null,"kp":[]},{"i":39544,"as":"中国实施了首批允许博士生以实际产品成果替代学术论文毕业的政策。Nature采访了参与该“实践型”博士学位项目的三名学生，探讨了这一以产品替代论文毕业的新模式。","scd":null,"kp":[]},{"i":39545,"as":"研究开发了基于膦酰胺酯的固化剂，将环氧固化、本征阻燃和动态键交换集成在单一分子设计中，构建了环氧共价适应性网络。该网络通过P-O键处高效的膦酰胺酯交换机制，实现了多次再加工而不损失性能。与其他磷酸化网络相比，该结构促进了更快的动态键交换和网络重排，解决了热固性材料在可持续性和防火安全之间的传统矛盾。","scd":null,"kp":[]},{"i":39546,"as":"研究提出一种基于非对称CuO-Cu2O纳米线薄膜的视觉-味觉神经形态器件，通过物理耦合实现固态光电电子学与液相离子学的内禀结合。该异质结纳米线网络表现出显著的表面光生伏特效应和固液界面的自发电荷重排，实现在水相环境下的无偏压运行。化学响应相关的离子吸附形成双电层，动态调制光电信号，从而模拟生物系统的跨模态联想感知行为。","scd":null,"kp":[]},{"i":39547,"as":"研究提出一种电子给体-受体（EDA）复合物辅助策略，在水相、无添加剂的条件下构建β-酮烯胺类共价有机框架，并同步原位封装酶。富电子的Bpy与缺电子的Tp形成的EDA复合物以特定方向预排列单体，显著降低反应活化能，生成高结晶度的TpBpy COF。此外，COF中的Bpy单元不仅充当保护支架，还作为各种金属离子的锚定位点用于级联生物传感。","scd":null,"kp":[]},{"i":39548,"as":"针对C2H2和CO2分离的挑战，研究报道了由氟桥连七核[Co7F12]2+簇和三齿吡啶配体构建的两种同构金属有机框架LIFM-712和LIFM-713。受限的BF4-反离子与桥连氟配体协同，形成富氟孔环境，为C2H2提供丰富的C-H···F识别位点。其中，LIFM-713在298K和1bar下的C2H2吸附量高达149.8 cm3/g，其C2H2/CO2理想吸附溶液理论选择性高达4.5。","scd":null,"kp":[]},{"i":39549,"as":"研究通过调控Cu2O催化剂表面二氧化硅壳层的厚度，开发出一种调节CO2电还原反应路径的界面工程策略。薄二氧化硅壳层的Cu2O@tn-SiO2在预还原后易形成Cu/Cu2O/SiO2三相界面，有利于不对称中间体的形成，从而促使反应向C2+产物路径进行；而厚壳层则有效引导反应转向生成CH4。该技术实现了选择性切换C2+与CH4的生成途径。","scd":null,"kp":[]},{"i":39550,"as":"为解决固态锂电池复合聚合物电解质室温离子电导率低的问题，研究通过旋涂技术设计出一种非对称高盐聚合物电解质。该电解质采用聚偏氟乙烯框架贯穿全膜，含环丁砜的富LiTFSI聚环氧乙烷（PEO）层面向正极。这种高介电常数微环境将离子聚集体转化为与醚氧配位的游离Li+，显著提升了室温离子导电率和锂离子迁移数，并改善了机械兼容性界面。","scd":null,"kp":[]},{"i":39551,"as":"为应对耐药菌引起的骨缺损修复难题，研究开发了一种名为SPMiL的磺化PEEK支架。该支架负载了人类抗菌肽LL37和富含线粒体的囊泡。这些囊泡提取自敲除了Opa1基因的外胚层间充质干细胞，基因敲除大幅提升了囊泡的产量。在MRSA感染的大鼠颅骨缺损模型实验中，SPMiL支架成功释放 payloads以清除感染并促进成骨。","scd":null,"kp":[]},{"i":39552,"as":"研究设计并制备了由聚(3,4-乙烯二氧噻吩)（PEDOT）包覆碳布上生长的Co3O4纳米线构成的Co3O4@PEDOT-CC阳极，用于提升微生物电化学系统降解四环素的能力。该阳极具有分层结构和优异的导电性及生物相容性，其最小电荷转移电阻仅为6.5 Ω，较裸碳布降低了27.3倍。系统实现了3.33 W/m2的最大功率密度，显著提升了处理效率。","scd":null,"kp":[]},{"i":39553,"as":"研究合成了一系列带有双吖丙啶/炔烃标签的苯并氧硼杂环，通过细胞内光亲和标记实验，发现其中一个子集对真核翻译起始因子4E（eIF4E）具有高选择性。这种结合具有立体选择性，且与mRNA的7-甲基鸟苷帽存在竞争关系。标记位点实验及计算建模表明，苯并氧硼杂环片段直接结合在eIF4E的帽结合口袋内，并通过氢键相互作用稳定结构。","scd":null,"kp":[]},{"i":39554,"as":"研究团队基于VO2(B)纳米片墨水，通过简便且可规模化的滴铸工艺制备出柔性红外热探测器。在室温下，该器件的电阻温度系数高达4.57% K-1，响应度为9.84 A/W，探测率达到3.27 × 10^8 Jones。该成果突破了传统非柔性器件及高成本制造工艺的瓶颈，为可穿戴红外设备提供了技术支持。","scd":null,"kp":[]},{"i":39555,"as":"研究团队开发出一种针对赖氨酸乙酰转移酶KAT2A的高选择性降解剂。通过冷冻电子显微镜证实，CRBN分子胶无需依赖传统的降解标签即可招募KAT2A，而是通过结合表面暴露的酪氨酸，实现类似抗体的分子识别。这种选择性降解能有效消除组蛋白H3K9乙酰化，在急性髓系白血病细胞中表现出显著的抗增殖作用。","scd":null,"kp":[]},{"i":39556,"as":"研究人员提出非平衡态瞬态组装策略，利用周期性热脉冲协议驱动高能瞬态构型演化，超快速合成了具复杂结构的核壳铂皮金属间纳米晶体（如Pt@PtFe-i）。该工艺实现了高有序PtFe金属间核心与原子级精度铂表皮的同步组装。Pt@PtFe-i催化剂的铂皮层具有依赖于配位的压缩应变，产生了高密度的高活性位点，适用于燃料电池。","scd":null,"kp":[]},{"i":39557,"as":"研究利用高分辨率低温光电子能谱结合相对论四分量计算，探测了CBi-分子离子的成键机制。实验直接证实了重元素分子中相对论效应引发的轨道混合，打破了主族元素经典的σ-π独立成键框架。结果显示，自旋-轨道耦合作用使总角动量投影成为唯一的良好量子数，导致CBi-阴离子中传统的三键发生相对论性塌陷。","scd":null,"kp":[]},{"i":39558,"as":"评论文章批判了将人类用户转变为“反向半人马”的人工智能技术。作者认为，如果技术的应用方式导致人类沦为服务于人工智能的系统，这种技术发展将无法激起人们的热情与支持。","scd":null,"kp":[]},{"i":39559,"as":"关于“我们对性了解多少”的问题，答案取决于你询问的对象是谁。","scd":null,"kp":[]},{"i":39560,"as":"研究表明，仅数分钟的冷冻过程即可决定后续数月铁矿物在水相老化过程中的演变命运。单次冻融循环通过物理与化学机制的交汇，使水铁矿发生不可逆聚集。冰冻浓缩效应与冰晶抽吸作用剥离水化层并将纳米颗粒压缩成微米级聚集体，界面羟桥键与氢键共同抵抗了重新分散，从而抑制了其向针铁矿的转变。","scd":null,"kp":[]},{"i":39561,"as":"研究团队通过对比潜水鸟类数据与仿生扑翼机器人实验，揭示了跨介质飞行的机制。结果表明，频率适应、柔性机翼和强力驱动能够实现飞行与水下潜游的无缝切换。大型机翼在提升飞行能力的同时不会大幅降低水下效率，而尾身距离及出水角度则显著影响机器人跃出水面。这为两栖航行器设计提供了关键参数。","scd":null,"kp":[]},{"i":39562,"as":"美国国家科学院新任院长Neil Shubin探讨了该机构的未来发展方向。面对当前美国科学界所处的动荡环境，文章重点讨论了科学院如何在此严峻局势下维持运作，并确保其在美国科学界持续发挥重要影响与相关性。","scd":null,"kp":[]},{"i":39563,"as":"","scd":null,"kp":[]},{"i":39564,"as":"文章指出，历史上城市能够基于灾难带来的证据与压力，在数年内出台并执行有效的适应性政策（如伦敦大火后的建筑法规）。然而，当前这种“破坏产生证据并推动治理改善”的逻辑机制在全球各宜居大陆均已出现退化，导致城市在面对灾害时无法有效学习与制定应对策略。","scd":null,"kp":[]},{"i":39565,"as":"研究人员开发出一种用于量子气体的“相位显微镜”技术，通过分析物质波成像中的高阶塔尔博特复兴，实现了将相位涨落映射为密度涨落的晶格级解析。该技术成功观测了超流体中相位关联的代数衰减及指数随温度的线性增加，为在全空间分辨率下研究强相关量子系统（如超导现象）的相干特性提供了新方法。","scd":null,"kp":[]},{"i":39566,"as":"文章探讨了为支持《全球塑料条约》而填补数据空白的关键策略。提出相关数据报告需要重点关注三个核心方向：推进全球数据标准的统一化、完善供应链衡量指标，以及精确识别塑料污染的热点区域。","scd":null,"kp":[]},{"i":39567,"as":"最新研究显示，当年英国“第一舰队”殖民者将天花病毒引入了澳大利亚。同时，证据表明在欧洲人到达之前，澳大利亚大陆原住民的人口规模远比过去认知的要庞大得多。","scd":null,"kp":[]},{"i":39568,"as":"面对H5N1禽流感病毒在澳大利亚大陆爆发的威胁，新西兰针对濒危鸟类启动了 ambitious（宏大）的疫苗接种计划。这一举措旨在通过提前免疫，防止高致病性禽流感对当地珍稀濒危鸟类种群造成毁灭性打击。","scd":null,"kp":[]},{"i":39569,"as":"美国农业部（USDA）加速了关闭其旗舰科学园区的计划。农业部声称关闭该研究中心旨在提高整体运营效率，但批评人士指出，此举将严重削弱对农民至关重要的一系列农业科学研究项目。","scd":null,"kp":[]},{"i":39570,"as":"北方斑点猫头鹰曾因林业砍伐受到保护而免于灭绝，如今却面临着全新的生存威胁。科学家们正在发起最后的保卫战，试图拯救这一濒危物种免受新威胁的侵害。","scd":null,"kp":[]},{"i":39571,"as":"越来越多的新理论模型对天王星和海王星的“冰巨星”传统分类提出挑战，指出这两颗行星可能并非主要由冰类物质组成，而是实质上属于岩石星球。","scd":null,"kp":[]},{"i":39572,"as":"","scd":null,"kp":[]},{"i":39573,"as":"","scd":null,"kp":[]},{"i":39574,"as":"研究指出，冰冻过程会改变地球冰冻圈内铁元素的演变轨迹。在冰晶生长过程中，多晶冰将矿物纳米颗粒浓缩至液体边界，使得冰在这个物理化学过程中充当了地化反应器的角色，从而重新分配并决定了铁的命运。","scd":null,"kp":[]},{"i":39575,"as":"关于情绪隐藏逻辑的新模型正在跨物种研究中建立起统一的解释框架。该情绪模型整合了不同领域的实证数据，并为治疗焦虑症和心理创伤等精神疾病提供了全新的思路与干预靶点。","scd":null,"kp":[]},{"i":39576,"as":"研究发现，免疫系统抗体在成体大脑神经环路的重塑中发挥“雕塑”作用。特定的免疫细胞能够靶向大脑内过度活跃的神经元，通过清除多余的突触连接，参与成体脑神经网络的精细调节与维护。","scd":null,"kp":[]},{"i":39577,"as":"","scd":null,"kp":[]},{"i":39578,"as":"研究揭示，在高地鼠体内，应对低氧环境的生理反应与处理毒素的反应之间存在竞争关系。这两种截然不同的生存防御机制在分子层面上，竞争结合同一个共享的分子调节因子，从而形成生理权衡。","scd":null,"kp":[]},{"i":39579,"as":"","scd":null,"kp":[]},{"i":39580,"as":"拟南芥中DNA单链断裂（SSB）修复缺陷会触发全基因组范围的转座元件（TE）去抑制和广泛的DNA从头甲基化。ZDP/APE2基因突变会阻碍碱基切除修复中3'端受阻SSB的修复。同时，SSB修复效率低下会激活ATR-SOG1介导的DNA损伤反应，从而增强RNA介导的DNA甲基化途径。","scd":null,"kp":[]},{"i":39581,"as":"溶致液晶在无需微观吸引力的条件下即可发生自发相分离。基于日落黄水混合物的研究表明，相分离仅依赖于局部向列分子密度与取向顺序之间的类昂萨格耦合。当耦合足够强时，向列相缺陷会触发各向同性液滴成核，并在弹性或界面张力作用下聚结。","scd":null,"kp":[]},{"i":39582,"as":"在具有切向锚定边界的环形向列液晶微滴中，磁场会诱导生成稳定的对齐反转壁（Helfrich壁）。环形几何与外场的相互作用产生了复杂的指向场构型。无缺陷时出现splay-bend壁，而存在点缺陷对时则会产生其他特定类型的壁结构。","scd":null,"kp":[]},{"i":39583,"as":"神经元通过组合多种连接蛋白（Innexin）来建立具有选择性的电突触连接。在秀丽隐杆线虫的机械感觉回路中，单个电突触可由INX-1、UNC-7和UNC-9三种不同蛋白组成的异质通道聚集形成。这种被称为“异通道突触”的组合构型赋予了突触特定的分子和生理功能。","scd":null,"kp":[]},{"i":39584,"as":"化脓性链球菌分泌的蛋白酶SpyCEP通过重塑趋化因子来破坏中性粒细胞免疫。SpyCEP的切割自催化成熟环（CAML）含有一个无序的芳香族酸性区域，该区域能模拟受体N端并结合CXCL8的变构位点，形成动态模糊复合物并促进CXCL8二聚体解离，从而增强酶的切割可及性。","scd":null,"kp":[]},{"i":39585,"as":"","scd":null,"kp":[]},{"i":39586,"as":"白细胞介素-13（IL-13）信号在皮肤过敏引发全身过敏性休克中发挥关键作用。在小鼠模型中，IL-13受体α1亚基的细胞特异性敲除实验表明，传统树突状细胞（而非T或B细胞）是IL-13作用的核心靶点，负责产生高亲和力IgE抗体并驱动系统性过敏反应。","scd":null,"kp":[]},{"i":39587,"as":"植物根尖能够通过感知局部pH梯度来避开土壤中的腐败区域，这种生长反应被称为“腐生性”。真菌分解有机物释放有机酸并形成稳定的pH梯度，根尖表皮细胞通过RMG肽-受体模块感知外部酸性梯度，引发脱落酸（ABA）的不对称分布，进而驱动微管重组，最终使根尖弯曲生长。","scd":null,"kp":[]},{"i":39588,"as":"补体C1q与抗体共同介导成人大脑中依赖于神经元活动的突触丢失。体内化学遗传学证明，神经元过度活跃会诱导海马体中依赖于C1q的突触丢失。在阿尔茨海默病模型中抑制过度活跃可减少淀粉样蛋白-β和C1q沉积。成人海马体中的抗体分泌B细胞谱系也参与了这一过程。","scd":null,"kp":[]},{"i":39589,"as":"基因分析表明，非洲入侵性疟疾媒介斯氏按蚊起源于南亚，在吉布提建立过渡种群后扩散至苏丹、埃塞俄比亚/肯尼亚和也门。其传播速率受地形影响。该蚊虫对杀虫剂的抗药性主要由代谢解毒基因介导，并且伴随着特定的抗性单倍型和基因拷贝数变异。","scd":null,"kp":[]},{"i":39590,"as":"社会记忆效价的更新依赖于海马腹侧CA1（vCA1）-基底外侧杏仁核（BLA）-伏隔核（NAc）组成的神经回路。当原本中性的同伴转变为具有攻击性时，vCA1中的社会记忆印记神经元会加强与BLA中携带负性效价神经元的突触连接。这一回路的突触和生理变化灵活调节着适应性社会行为。","scd":null,"kp":[]},{"i":39591,"as":"表观遗传酶CARM1是癌症免疫中交叉递呈树突状细胞功能的负向调节因子。抑制CARM1可特异性增强cDC1的抗原交叉递呈和激活能力。CARM1失活增加了BATF3-Jun和RelA位点的染色质可及性，从而促进肿瘤内cDC1积累；CARM1抑制剂还能协同癌症新抗原疫苗增强T细胞应答。","scd":null,"kp":[]},{"i":39592,"as":"提出了一种统计假设检验方法，用于评估个性化干预策略的性能是否优于使用单一的最佳干预措施。该检验方法严格控制第一类错误，并在特定条件下实现了具有最小可能方差的渐近正态性。在求职培训、抑郁症治疗、教育和推荐系统等多个真实数据集上，该方法展现出了优于其他替代方案的普遍性和性能。","scd":null,"kp":[]},{"i":39593,"as":"安第斯山脉的食叶鼠适应了极端的海拔梯度（从海平面至6700米以上）。与低地同类相比，高地种群在缺氧环境中进化出了更强的产热能力，这与骨骼肌线粒体呼吸能力的增强密切相关。群体基因组学分析揭示了其低氧适应机制，并且表明该物种进化出了代谢植物源性食物毒素的能力。","scd":null,"kp":[]},{"i":39594,"as":"丝状真菌在共享细胞质的多核网络中存在严格的核密度（单位体积细胞核数量）控制。通过构建相振荡器模型，将细胞核建模为分裂群体，揭示了在局部非同步细胞周期中维持整体核密度的机制。这种机制解释了多核细胞如何平衡各个细胞核的异步分裂与整体的核质比控制。","scd":null,"kp":[]},{"i":39595,"as":"","scd":null,"kp":[]},{"i":39596,"as":"","scd":null,"kp":[]},{"i":39597,"as":"将自旋-轨道耦合的结构光投射到人类视网膜上，可将经典的二叶状Boehm刷转变为多叶状结构。与黄斑二色性吸收产生的Haidinger刷不同，这一现象是由视网膜中依赖于偏振的散射所驱动的。散射中心的偏振趋同会产生方位调制的内视模式，使多叶结构更加明亮和清晰。","scd":null,"kp":[]},{"i":39598,"as":"本项研究报道了远离稳定线的奇奇核、轻质量稀土同位素（$^{162}\\mathrm{Lu}$）的低能级结构。由于核反应截面产额低、半衰期短且缺乏专门研究，这类形变奇奇核的能级结构一直鲜有表征。研究详细分析了该同位素的特定低能级特性。","scd":null,"kp":[]},{"i":39599,"as":"对使用Ca、Ti、V和Cr等作为弹核合成$Z=119$号超重核进行了理论估算。超重核合成涉及复杂的反应机制，研究重点评估了反应Q值的影响以及不同质量模型的依赖性，为周期表中新元素的合成与机制理解提供了理论依据。","scd":null,"kp":[]},{"i":39600,"as":"在杰斐逊国家加速器实验室的FROST实验中，测量了圆偏振光子轰击横向极化质子的$\\gamma p \\rightarrow \\pi^0 p$反应（光子能量最高至3.082 GeV）。研究报道了该介子光生过程中的极化观测量$T$和$F$，为理解核子共振态和强相互作用提供了实验数据。","scd":null,"kp":[]},{"i":39601,"as":"在Marchenko理论框架下进一步研究了多通道情况下的逆散射问题（固定$l$反演）。研究将第一通道动量$q$函数下的$n$通道$S$矩阵，近似为有理项与截断sinc级数之和。该方法有效解决了具有不同阈值的通道情况下的$S$矩阵近似与Marchenko方程求解。","scd":null,"kp":[]},{"i":39602,"as":"提出利用月球表面的引力波天文台进行月球引力波断层扫描，以约束月球内部结构。研究指出，得益于月球独特的地质条件，月球引力波观测台在探测引力波的同时，能够收集到比以往预期更为丰富的地质与内部结构信息。","scd":null,"kp":[]},{"i":39603,"as":"发表在《物理评论快报》上的研究指出，月球地质特性（较厚的月壳）能够放大分赫兹引力波信号。基于这一地质学发现，拟建中的月球引力波天文台将能够收集到比此前预期更多的引力波观测信息。","scd":null,"kp":[]},{"i":39604,"as":"研究提出了一种光氧化还原中性平台，可将亚甲基吡啶鎓连接基团直接转移至未活化的芳烃中，将惰性C-H位点转化为通用的合成活性位点。生成的苄基吡啶鎓产物作为关键中间体，可广泛用于构建C-C和C-杂原子键，从而高效获取药物化学中极具价值的取代甲基分子结构。","scd":null,"kp":[]},{"i":39605,"as":"研究收集了48个撒哈拉以南非洲国家的住宅电价数据，利用多层级框架(MTF)和模拟收入分布评估了电网电力的可负担性。结果显示，在当前电价下，约6.08亿人（50%）无法负担第4层级电力，该数字在第5层级下升至10.5亿人（85%，基于10%能源贫困阈值）。5%和15%阈值的敏感性分析证实了该结论的稳健性。","scd":null,"kp":[]},{"i":39606,"as":"研究分析了20,389家机构中65,768位当代艺术家的展览史和拍卖数据，揭示了视觉艺术领域的性别不平等。通过区分“性别中立”（获得展览机会与性别无关）和“性别平衡”（代表性数量均等）两项标准，研究发现58%的机构实现了性别中立，但仅有24%达到性别平衡。此外，男性代表性过高的机构比例随着机构声望的增加而上升。","scd":null,"kp":[]},{"i":39607,"as":"每日简报指出，章鱼的蛋白质合成机制发生突变，从而显著提升了其合成蛋白质的精确度。此外，简报还涵盖了一位诺贝尔奖获得者从美国前往中国，以及微重力环境对人体大脑影响的研究进展。","scd":null,"kp":[]},{"i":39608,"as":"该观点文章指出，无人机(UAVs)在接收到开放性指令后，不应直接执行，而必须在选择安全动作前，将指令转化为可在飞行中验证的测量数据。这种机制旨在确保无人机空中具身智能的安全性和可靠性。","scd":null,"kp":[]},{"i":39609,"as":"","scd":null,"kp":[]},{"i":39610,"as":"Tokamak Energy开发了ST-E1聚变发电站的预概念设计。有效的反应堆维护方案能够确保安全运行并缩短停机时间，从而实现高可用性，这对商业聚变电站至关重要。文章阐述了托卡马克装置架构和选定的维护机制，以及该维护方案如何支持分两阶段（先导电站和商业电站）演示商业运营的发展策略，同时说明了该方案对发电站空间设计和周边基础设施的影响。","scd":null,"kp":[]},{"i":39611,"as":"研究探讨了ST-E1聚变发电站（大半径5米、低环径比）的功率和粒子排出挑战。利用一维边缘等离子体模型和SOLPS-ITER代码进行模拟分析，评估了在双零和单零配置下使用短/长外偏滤器腿的脱靶分离状态。结果表明，以氩作为主要杂质种子，配合钨等离子体面对部件，可实现耗散偏滤器运行。但在磁体工程和不确定的等离子体参数范围之间仍需进行权衡。","scd":null,"kp":[]},{"i":39612,"as":"针对ST-E1聚变发电站，研究开发了一套集成的氚燃料循环架构。该架构将氦冷液态锂增殖包层与专用循环回路耦合，在统一的系统边界内实现氚提取、排热和存量控制。氚处理系统包含提取、纯化、同位素分离和存储等子系统，以适应电站动态产氚和耗氚率。通过建模评估提取方案和氚滞留量，综合评估证明了该闭环架构的有效性。","scd":null,"kp":[]},{"i":39613,"as":"ST-E1是Tokamak Energy设计的低环径比聚变电站，目标聚变功率为1.5吉瓦。针对其等离子体从击穿到平顶态的爬升过程，由于ST-E1的低环径比限制了可用螺线管磁通，研究利用METIS进行时间依赖性建模。结果表明，通过外部垂直场线圈提供感应磁通，并在相对较高的等离子体密度下进行爬升，可以实现这一等离子体演化方案。","scd":null,"kp":[]},{"i":39614,"as":"ST-E1低环径比托卡马克反应堆的预概念设计中，辐射屏蔽的有效性是决定装置尺寸、寿命和系统平衡的关键。研究利用基于Geant4工具包的自研G4Tokamak程序，开发了电站级中子学模拟工作流，将中子学和材料考量纳入系统工程框架。该工作流加快了设计迭代，并通过基准测试验证了结果，确保高温超导磁体得到有效保护。","scd":null,"kp":[]},{"i":39615,"as":"研究阐述了ST-E1聚变电站辅助加热和电流驱动系统的物理基础。其平顶态等离子体是完全非感应的，自举电流份额为0.9，其余电流由电子回旋(EC)波驱动。利用物理优化方法，证明了通过从真空容器低场侧上半部分(LFS顶部)发射频率为160-200 GHz的基模O波(O1)，可实现净效率达52 kA/MW的目标平顶态ECCD，且在等离子体运行早期同样有效。","scd":null,"kp":[]},{"i":39616,"as":"作为美国能源部聚变能源发展里程碑计划的一部分，Tokamak Energy完成了ST-E1聚变电站的预概念设计。该电站计划分两阶段运行：先导电站阶段（目标持续净功率生产）和商业电站阶段（目标稳态运行及特定的隔夜建设成本）。设计过程高度迭代，集成了所有主要工厂系统，侧重于探索设计空间、识别系统级权衡，并定义整体电站概念的关键决策。","scd":null,"kp":[]},{"i":39617,"as":"为支持ST-E1聚变电站的预概念设计，研究开发了全新的系统代码PyTok。该代码在纯Python面向对象框架中编入了等离子体物理和工程约束，支持快速迭代和外部物理代码耦合。基于经济性分析，PyTok确定了ST-E1的初始参考设计点：大半径5.0米、特定环径比和特定环向磁场。该设计点可同时作为先导电站和商业电站的基础。","scd":null,"kp":[]},{"i":39618,"as":"研究对ST-E1低环径比聚变电站的热管理和净功率性能进行了综合分析。研究量化了冷却回路设计、压降、泵送功率和储热对电站效率的具体影响，并深入探讨了冷却剂系统设计、功率循环集成与电力负载之间的相互作用。研究结果明确了实现先导阶段300至500兆瓦电(MWe)净功率目标所需的系统级权衡条件及提升净功率性能的路径。","scd":null,"kp":[]},{"i":39619,"as":"面对气候变化和AI数据中心带来的低碳能源需求，Tokamak Energy提出了ST-E1低环径比托卡马克聚变电站预概念设计，旨在解决先导电站脱险与高昂成本的融资悖论。ST-E1从一开始就设计为分阶段运行（包含先导阶段、升级阶段和商业阶段），重点强调商业可行性，提供了一种专门的应对长期聚变商业化的工程方案。","scd":null,"kp":[]},{"i":39620,"as":"ST-E1聚变电站设计包含全寿命周期高温超导(HTS)磁体笼，现已完成预概念设计。为了打破串联设计循环并避免发现不可行运行场景过晚的问题，研究开发了一种新型集成工作流。该工作流能够快速、早期地迭代整合磁体笼、核心等离子体物理和功率排出系统，特别是准确表征了紧密耦合这些系统的感应电流驱动，确保设计的一致性。","scd":null,"kp":[]},{"i":39621,"as":"研究使用3D牵引力显微镜耦合胶原来量化青光眼小梁网(TM)细胞对细胞-胶原蛋白力学的细胞骨架调节。对高流速和低流速区域的配对培养物测试发现，在对照组中，高流速区域的平均牵引力从4小时的36.2 kPa增至12小时的44.8 kPa。加入Latrunculin B等药物后，牵引力早期下降并伴随部分恢复，揭示了不同流速区域中细胞骨架控制机制的差异。","scd":null,"kp":[]},{"i":39622,"as":"","scd":null,"kp":[]},{"i":39623,"as":"随着电池护照在储能领域的可追溯性、安全性和循环性方面变得不可或缺，学术界电池研究依然难以整合到数字生态系统中。该评论提出了一种学术界电池护照框架，旨在使电池科学具备互操作性和机器可读性，从而服务于监管合规、人工智能应用和全生命周期智能管理。","scd":null,"kp":[]},{"i":39624,"as":"研究提出了一种适用于钠全固态电池的锡电极界面-相间工程策略，该策略与卷对卷电极制造兼容。通过将渗入的钠closo-硼酸盐负极电解质与碳纳米管(CNT)支架集成，工程化的锡负极实现了可逆合金化学和低压运行能力。结合阴极和固体电解质薄膜的干法制造工艺，首次成功演示了软包型钠全固态电池(NaSSB)。","scd":null,"kp":[]},{"i":39625,"as":"研究人员利用四维扫描透射电子显微镜首次在原子尺度上直接观测了极性InGaN/GaN异质界面的极化电场。观测结果表明，界面处的负电荷呈空间离域状态且偏向GaN势垒层，打破了经典物理中电荷呈突变面分布的理想近似。结合电子能量损失光谱与密度泛函理论计算证实，该不对称性微观机制源于铟的引入削弱了局部的金属-氮键。","scd":null,"kp":[]},{"i":39626,"as":"为解决蛋白治疗药物在递送过程中细胞渗透性差和易被水解的问题，研究人员开发了一种氧化还原响应型蛋白前药RP-ss-PK。该药物通过线性双功能PEG支架（RGD-PEG-ss-NPC）将具有细胞毒性的蛋白酶K（PK）共价结合。支架α端的环状RGD肽用于整合素介导的肿瘤靶向，ω端用于结合蛋白酶K。其内部的二硫键连接体使前药在特定条件下具备可裂解特性。","scd":null,"kp":[]},{"i":39627,"as":"针对黑色素瘤术后复发和愈合困难的问题，研究人员开发了一种共载HMnO2和阿霉素（DOX）的微针（MN）贴片。该微针贴片能够穿透角质层实现透皮递送并靶向手术部位。在近红外光照射下，HMnO2介导的光热消融能有效清除残余肿瘤细胞，DOX则抑制潜在微转移灶的增殖。此外，该系统还能调节局部炎症微环境，促进术后伤口修复。","scd":null,"kp":[]},{"i":39628,"as":"","scd":null,"kp":[]},{"i":39629,"as":"受海参可逆机械切换行为启发，研究人员开发出一种由明胶、水和离子液体组成的温度响应型离子生物凝胶（IBG），用于皮肤可穿戴生物电子设备。明胶形成具有可逆溶胶-凝胶转变特性的物理网络，而离子液体通过氢键和静电相互作用调节网络结构并提供可移动离子。该凝胶解决了传统预制导电凝胶无法完全适应复杂动态变形皮肤表面的问题，提升了界面的粘附性和信号传输性能。","scd":null,"kp":[]},{"i":39630,"as":"为解决氮化铝（AlN）在潮湿环境中易水解导致性能下降的问题，研究人员提出一种新型表面改性策略。通过将巯基接枝到AlN颗粒上，随后用液态金属（LM）层进行封装，制备出LM@AlN填料。将该填料掺入聚二甲基硅氧烷（PDMS）基体固化后，制成了热界面材料。该策略克服了现有表面改性方法难以兼顾高加工效率和材料增强性能的缺陷，显著提升了材料的热导率和稳定性。","scd":null,"kp":[]},{"i":39631,"as":"为修复大段骨缺损，研究人员开发了一种结合脱细胞鱼鳞（DC-FS）支架与干细胞片来源细胞外囊泡（CS-EVs）的无细胞策略。该复合支架利用鱼鳞固有的微槽形貌进行细胞定向引导，并加载CS-EVs提供持续的促成骨信号。实验表明，该支架保留了生物支架的微纳结构和矿化成分，允许囊泡可控释放，有效促进了骨髓间充质干细胞在体外的定向迁移、粘附和成骨分化。","scd":null,"kp":[]},{"i":39632,"as":"研究人员开发出一种非对称结构的MXene/WPU复合涂层（AMWC），实现了全天候防冰/除冰与吸收主导型电磁干扰（EMI）屏蔽的协同优化。该涂层顶层为光热西兰花状贫MXene层，底层为电热富MXene层。AMWC表现出优异的超疏水性（水接触角约162°，滑动角约5°）及机械化学稳健性。该结构借助可调的光电热效应，克服了传统涂层无法同时防止冰积累和缓解EMI的局限性。","scd":null,"kp":[]},{"i":39633,"as":"针对分子电化学发光（ECL）探针细胞摄取和靶向性差的问题，研究人员设计了一种胶体磁性纳米探针。该纳米颗粒以6-7纳米的氧化铁为核心，表面修饰同时具有荧光和ECL特性的钌联吡啶络合物作为双重信号探针，并通过靶向配体进行功能化。将分子发光体转化为胶体纳米颗粒显著提高了细胞的摄取率，有效拓展了其在荧光与ECL双模式生物成像及检测中的应用潜力。","scd":null,"kp":[]},{"i":39634,"as":"研究人员利用X射线自由电子激光驱动的激光冲击压缩技术，在177-440 GPa的地球外核压力下，对铁及氧化铁熔体进行了原位X射线衍射测量。结果显示，这些熔体的Fe-O配位数在4.0至4.5之间，主要表现为四配位环境，明显小于下地幔含铁相的配位数。压缩态氧化铁熔体中较短的Fe-Fe原子间距促使原子堆积比常压熔体更紧密。","scd":null,"kp":[]},{"i":39635,"as":"研究人员在包含多达105,000个收缩型自旋霍尔纳米振荡器（SHNO）的晶格阵列中实现了纳秒级相位排序。实验表明该阵列实现了完全的相互同步，其微波光谱品质因子超过10^6。阵列的微波功率与阵列规模（N）成正比，线宽与N成反比。同步时间随阵列规模呈弱对数增长，验证了大规模SHNO网络在物理计算和集体动力学研究中的可扩展性。","scd":null,"kp":[]},{"i":39636,"as":"为提升锂金属电池性能，研究人员提出基于刚性聚阴离子架构与含锂离子液体相互作用的复合聚合物电解质设计策略。该设计使锂离子的传导与聚合物链段动力学解耦，实现了快速界面电荷转移。该复合电解质同时具备高离子传导率、高机械模量和低电极界面电阻，有效稳定了与锂金属电极接触的界面区域，显著提升了固态电池的综合电化学性能。","scd":null,"kp":[]},{"i":39637,"as":"为解决厚电极中离子传输迟缓、反应不均及力学降解等问题，研究人员通过调控晶体生长过程，将连贯孪晶界（CTBs）引入富锂层状氧化物正极材料中。该结构构建了准三维离子扩散通道，有效克服了富锂材料在厚电极应用中面临的纳米结构应力、氧氧化还原不可逆性及电极级传输限制，显著提升了厚电极电池的储能密度和循环稳定性。","scd":null,"kp":[]},{"i":39638,"as":"该综述探讨了聚烯烃加氢裂化用于塑料废弃物升级回收的双功能纳米催化剂设计。传统碳氢化合物加氢裂化的纳米级构效关系为该领域提供了基础，但塑料的大分子特性、传质限制及催化剂-聚合物界面特性阻碍了直接应用。文章指出，这些差异为重新设计催化剂以优化聚合物解聚效率创造了新机遇，并探讨了相关催化剂工程的未来发展路径。","scd":null,"kp":[]},{"i":39639,"as":"欧盟对进口纯电动汽车征收关税的政策整体上不会大幅阻碍电气化进程，但在脆弱市场中会导致电动汽车的普及率显著下降。这表明广泛的贸易干预带来了不平衡的影响，突出了制定互补性政策以支持弹性且包容性电动汽车产业转型的重要性。","scd":null,"kp":[]},{"i":39640,"as":"研究量化了2024年7月欧盟对中国纯电动汽车加征额外关税对20个欧洲国家及10类车型的影响。根据车企应对策略的不同，2035年欧盟电动汽车的市场份额预计在56.4%（市场撤出）至68.9%（低成本本土化生产）之间，而基准预期为64.4%。关税带来的成本冲击导致对价格敏感的低收入国家和车型类别的电动汽车普及率出现显著下降。","scd":null,"kp":[]},{"i":39641,"as":"","scd":null,"kp":[]},{"i":39642,"as":"注入血液中的机械发光纳米材料能够在超声波的控制下发光。这一技术实现了对深层组织中神经元的精准光遗传学刺激，解决了传统光学方法穿透深度受限的问题。","scd":null,"kp":[]},{"i":39643,"as":"力学信号在调节肿瘤转移扩散和抗肿瘤免疫反应中发挥关键作用。将力学转移与免疫学过程相整合的“力-免疫学”框架，为深入理解肿瘤转移的进展机制及开发新型干预手段提供了重要途径。","scd":null,"kp":[]},{"i":39644,"as":"一种原位散射光学显微技术能够在几分钟内同时监测数千个单个纳米晶体的尺寸和发光特性。该技术具备单颗粒精度，能够有效揭示半导体纳米晶体生命周期中依赖于尺寸的物理现象。","scd":null,"kp":[]},{"i":39645,"as":"氟离子作为阴离子电荷载体，以其高理论能量密度、低成本和有效规避轻金属电极沉积难题的优势，成为超越锂离子电池的新型电化学储能替代方案。文章概述了氟离子电池转换型和插入型电极的设计原则，探讨了其与液态及固态电解质的配合应用，并深入解析了“硬”氟离子在各类储能器件组件中的跨界传导机制及材料跨尺度设计策略。","scd":null,"kp":[]},{"i":39646,"as":"通过分析1970至2021年间15个经合组织国家的数据，发现将能源密集型产业转移至海外（离岸外包）是导致国家能源强度持续下降的重要因素。国家产出的结构变化未能与国内消费模式的改变相匹配。这一发现表明，传统的基于生产的气候指标存在去碳化“错觉”，有必要采用纳入消费端数据的气候核算指标。","scd":null,"kp":[]},{"i":39647,"as":"本文综述了π共轭水凝胶半导体的设计、制造、表征和基准测试标准。通过π共轭聚合物的网络设计，水凝胶在具备生物相容性等类组织特性的基础上，拓展至晶体管等先进电子应用。研究详细阐述了如何理解和调控热力学层面的离子与电子传输及其相互作用。","scd":null,"kp":[]},{"i":39648,"as":"","scd":null,"kp":[]},{"i":39649,"as":"在穿越阿尔卑斯山的过程中，由于山地恶劣环境与长途跋涉的消耗，汉尼拔军队的重型巨兽（如大象）以及随行的马匹和士兵都流失了大量的体重，遭受了沉重的生理负荷与损失。","scd":null,"kp":[]},{"i":39650,"as":"本期科学简报探讨了科学史上的重要里程碑事件：首次利用成年细胞克隆哺乳动物（多利羊）的三十周年回顾。此外，简报还讨论了首次直接观测到洋壳生成的过程，盘点科学界的重大事件。","scd":null,"kp":[]},{"i":39651,"as":"科学通用人工智能工具（如Claude Science）旨在加速科学研究进程。本指南旨在帮助科研人员评估并选择最适合其实验室具体需求的AI科学工具，解答在众多通用AI工具中做出选择的困惑。","scd":null,"kp":[]},{"i":39652,"as":"针对预印本可靠性的分析表明，当生物医学领域的预印本后续在正规学术期刊上发表时，其核心结论极少发生改变。该结果基于对7万项研究的分析，证明了预印本在学术交流中的结论稳定性。","scd":null,"kp":[]},{"i":39653,"as":"科学家在实验室生育技术方面取得新进展，通过干细胞培养出未成熟的人类精子。该过程将干细胞诱导生成的精子细胞置于小鼠肾脏上进行培育，标志着向生育突破迈出了关键一步。","scd":null,"kp":[]},{"i":39654,"as":"美国国家科学基金会（NSF）计划削减核心科学项目资金，以支持白宫的倡议。目前NSF面临预算紧缺，正艰难清理积压的资助申请。在此背景下，该机构还提出了一项回收已分发研究资金的提议。","scd":null,"kp":[]},{"i":39655,"as":"论文报道了在中国早石炭世（约3.6亿年前）地层中发现的新型种子植物化石Ganiopteris。这是已知最早在叶片（叶面）上附着胚珠或种子的植物，为起源于二叠纪冈瓦纳大陆的舌羊齿类提供了关键的进化起源信息。","scd":null,"kp":[]},{"i":39656,"as":"","scd":null,"kp":[]},{"i":39657,"as":"降冰片二烯与炔烃的[2+2]环加成反应通常倾向于形成exo（外型）产物。现开发出一种镍催化高endo（内型）选择性的[2+2]环加成反应，用于生成难以合成的endo-三环壬二烯，并通过分子内[2+2]光化学环加成进一步衍生化合成高立方烷。","scd":null,"kp":[]},{"i":39658,"as":"通过在Ni/SiAlO催化剂上进行非热等离子体活化催化过程，成功在温和条件下将N2和CH4直接共转化为烷基胺和NH3。这种等离子体与催化的协同作用促进了反应物活化并实现了N-C和N-H偶联。该工艺一步完成，绕过了耗能的哈伯-博施法和胺化级联过程。","scd":null,"kp":[]},{"i":39659,"as":"本文综述了高效、稳定且可扩展的单片钙钛矿/硅串联光伏电池的材料与器件工程。该技术突破了传统晶硅约29.4%的效率极限。通过钙钛矿成分工程、添加剂引入、界面钝化、电荷选择性接触优化及硅底电池架构改进等策略，实验室器件效率已超越该阈值。","scd":null,"kp":[]},{"i":39660,"as":"金属有机框架（MOFs）的传统合成多依赖昂贵金属盐并产生腐蚀性废物。本研究利用廉价金属氢氧化物通过简单酸碱反应直接合成多种MOFs，水是唯一副产物。此法实现接近沸石水平的低成本规模化生产，合成的没食子酸盐基MOF能高效分离醇/苯共沸物。","scd":null,"kp":[]},{"i":39661,"as":"","scd":null,"kp":[]},{"i":39662,"as":"通过手性添加剂立体选择性掺杂，可以破坏中心对称晶体的对称性从而诱发压电效应。研究将四种手性N-乙酰-L-氨基酸掺入中心对称的N-乙酰-DL-缬氨酸晶体中，结合密度泛函理论和拉曼光谱，探究了极化的微观起源，明确了是由掺杂剂与主体的偶极失配还是晶格畸变主导。","scd":null,"kp":[]},{"i":39663,"as":"利用新型自由电子激光器进行时间分辨X射线光电子能谱分析，可实时监测核心电子结合能的亚eV级位移。在氟吡啶的研究中，通过监测光激发S1态松弛过程中的N和F原子位点发现，F位点主要响应振动弛豫，对电子激发态不敏感，揭示了电子激发与原子核运动之间的相互作用。","scd":null,"kp":[]},{"i":39664,"as":"结合原位高分辨率透射电镜与分子动力学模拟，研究揭示了铁酸锶(SrFeO3)拓扑相变的原子尺度动力学。450°C还原生成了缓冲相及未知的空位有序相，随后坍塌为无限层状SrFeO2。在200°C反向氧化时，途径发生分叉。这为理解过渡金属氧化物相变提供了新视角。","scd":null,"kp":[]},{"i":39665,"as":"[FeFe]-氢化酶具有极快的析氢速率，但极易被氧气不可逆抑制。通过分辨率为1.96埃的X射线晶体结构分析，证实CbA5H具有抗氧性的关键在于其高度氧化的Hinact状态，并且保护性配体为保守的半胱氨酸硫醇基团，该基团直接配位金属中心从而实现了对氧气的可逆抗性。","scd":null,"kp":[]},{"i":39666,"as":"为开发基于地球丰富元素的析氢反应（HER）分子电催化剂，研究合成了一系列NCN钳形支撑的Bi(III)有机金属催化剂（包含7种不同结构的配合物）。这些催化剂打破了传统的活性-过电位比例关系，展示了主族元素在稳定低价活性中间体及通过次级配位球调控电催化活性方面的潜力。","scd":null,"kp":[]},{"i":39667,"as":"报道了一种基于金属光氧化还原催化的脱氧C(sp3)-C(sp)偶联策略，利用炔基溴作为偶联伴侣，将醇直接转化为炔烃。该反应在氧化还原中性的温和条件下进行，通过NHC介导醇活化和镍催化生成烷基自由基。该方法适用于药物、肽类和天然产物等复杂醇的底物。","scd":null,"kp":[]},{"i":39668,"as":"通过ZrCl3-CH4体系的爆发性成核，在碳布上直接构建了富含缺陷的ZrC纳米岛，作为铂单原子的超强稳定锚定平台。该方法将ZrC颗粒表面数密度提升了两个数量级，并消除了游离碳污染。ZrC促进水分解，Pt单原子促进氢脱附，使该电极的质量活性达到商业Pt@C催化剂的116至132倍。","scd":null,"kp":[]},{"i":39669,"as":"为开发质子交换膜水电解制气的超低铱阳极催化剂，报道了一种Ti-Zr复合静电纺丝氧化物纳米棒载体。Zr的引入稳定了富含锐钛矿的TiO2，并加强了IrOx的界面锚定。在0.2 mgIr cm-2的低负载量下，多孔纳米棒网络有效改善了铱的利用率、离聚物渗透和传质，表现出高活性和耐久性。","scd":null,"kp":[]},{"i":39670,"as":"人类鸟氨酸转氨酶（hOAT）是依赖吡哆醛5'-磷酸（PLP）的酶，在多种癌症代谢中起关键作用。研究采用第二次去质子化策略，设计并合成了带有炔基或腈基的环戊烯基γ-氨基丁酸类似物，作为高效的hOAT灭活剂。这些化合物通过酶催化的γ-去质子化形成酮亚胺中间体，随后发生互变异构，从而实现对hOAT的不可逆抑制。","scd":null,"kp":[]},{"i":39671,"as":"近红外和短波红外发光材料在光学通信和传感器领域备受关注。研究人员通过在七次甲基苯并噻唑染料的聚次甲基链上增加空间位阻，合成了四种新染料，成功设计出发射短波红外的二维J-聚集体。研究表明，引入空间位阻会显著改变分子的自组装介晶相和光物理性质，为开发低成本且安全的NIR/SWIR发光材料提供了新途径。","scd":null,"kp":[]},{"i":39672,"as":"隐花色素4a（Cry4a）是介导鸟类磁感应的关键蛋白。通过经典分子动力学和量子力学/分子机械力学自由能模拟，研究了色氨酸自由基阳离子的去质子化及质子耦合电子转移（PCET）路径。研究发现，第三个色氨酸有限的溶剂可及性显著抑制了其有效去质子化，揭示了蛋白质-溶剂界面在调控光激发后自由基对重组动力学和自旋选择性过程中的关键作用。","scd":null,"kp":[]},{"i":39673,"as":"","scd":null,"kp":[]},{"i":39674,"as":"该研究合成了一种基于四氰基对醌二甲烷（TCNQ）和热稳定的S=1/2四唑啉基自由基的电荷转移复合物，并获得了在低温下具有巨大磁阻的非凡多晶型物。X射线晶体学显示其具有包含乙腈分子的D-A-A-D四聚体堆积基序，A-A二聚体表现出强π键合，面间距为3.1 Å。实验数据与理论计算结果高度一致。","scd":null,"kp":[]},{"i":39675,"as":"全碳主链聚合物的闭环化学回收通常需要高温或特定非商业聚合物。研究提出了一种通用的光催化解聚方法，利用多种商业有机和无机光催化剂，在非氯化介质中实现对自由基通量的精确控制，成功将催化活性与溶剂解耦。这种与溶剂无关的方法对聚甲基丙烯酸甲酯和聚苯甲基丙烯酸酯等难以降解的聚合物实现了大于95%的近乎定量的解聚产率。","scd":null,"kp":[]},{"i":39676,"as":"电池中金属锂（Li0）的形态、腐蚀和空间分布等动态行为影响电池寿命与安全。该研究提出了一种利用高Z元素进行氧化还原染色的方法，以增强Li0在电子束或X射线下的可见度。研究发现重金属离子可被Li0还原并成核为纳米颗粒，成功实现了对嵌入SEI中无活性Li0的多尺度空间可视化与识别。","scd":null,"kp":[]},{"i":39677,"as":"该研究考察了配体脱芳构化驱动的金属-配体协同作用（MLC）在锰催化羟磷化反应中的角色。通过全面的物种分析、动力学和光谱学研究，确定了催化剂在溶液中的结构，并分离出脱芳构化和非脱芳构化的催化活性中间体。研究表明，尽管该反应中存在多条可行的催化路径，但脱芳构化MLC路径在其中发挥了特定作用。","scd":null,"kp":[]},{"i":39678,"as":"该研究提出了一种在温和条件下从甲醇水溶液中高效制氢的无催化剂微液滴策略。在3.5升放大反应器中使用海水作为水源，实现了968.1 μmol h-1的析氢速率，主要液相产物为甲醛。结合电子顺磁共振、同位素标记和理论计算，研究阐明了微液滴界面驱动甲醇脱氢的物理化学机制。","scd":null,"kp":[]},{"i":39679,"as":"该研究利用球磨技术对香草醛与巴比妥酸的Knoevenagel缩合反应进行了动力学分析。与溶液中的一级反应动力学不同，机械化学动力学呈现S型曲线，即在缓慢的诱导期后反应迅速加速。通过在不同材质和不同频率的球磨罐中进行实验，研究确认了试剂在特定机械环境下的力学变化是导致自催化加速的原因。","scd":null,"kp":[]},{"i":39680,"as":"","scd":null,"kp":[]},{"i":39681,"as":"该研究将具有内腔的纯碳氢分子笼溶解于大体积空间排阻溶剂中，制备出II型多孔液体。分子动力学模拟和正电子湮灭寿命光谱证实溶剂被有效排除在分子笼腔体之外，保留了源自笼的永久孔隙率。该材料在埃尺度限制下表现出对二氧化碳的强物理吸附亲和力，适用于溶液体系中的选择性气体捕获与分离。","scd":null,"kp":[]},{"i":39682,"as":"","scd":null,"kp":[]},{"i":39683,"as":"糠醛的电催化加氢制取2-甲基呋喃（2MF）常受析氢副反应和糠醇生成的干扰。研究通过电解质工程优化，在pH=2下使用铜电催化剂发现，相比硫酸盐电解质，磷酸基电解质在-0.5 V（vs RHE）下将2MF的选择性从54.8%提升至72.1%。原位表面增强拉曼光谱表明，磷酸能与吸附的糠醛形成氢键，从而有效调控反应路径并提高目标产物的法拉第效率。","scd":null,"kp":[]},{"i":39684,"as":"手性哌啶类药物的直接不对称氢化合成受限于芳香环稳定性和多立体中心控制。研究报道了一种铱催化动态动力学拆分策略，无需预活化步骤即可直接实现外消旋C2-取代吡啶的不对称加氢。反应的关键在于原位生成碘化氢，瞬时激活吡啶环并实现高效的手性催化转化，为高立体化学多样性的手性哌啶合成提供了理想途径。","scd":null,"kp":[]},{"i":39685,"as":"多取代四氢呋喃是天然产物和药物中的关键结构，但现有合成方法通常步骤繁杂。本研究提出了一种新方法，能够从简单的分子砌块出发进行模块化组装，并实现精准的化学、区域、非对映和对映选择性控制。该策略突破了复杂sp³-杂环构建的技术瓶颈，为具有多个相邻立体中心的多取代四氢呋喃的高效合成提供了通用且稳健的平台。","scd":null,"kp":[]},{"i":39686,"as":"涉及碳正离子的骨架重排对复杂多环分子合成极具价值，但其选择性控制充满挑战。研究通过吲哚与邻氯醌的不对称亲电去芳香化及氮杂-普林斯环化，生成桥环苯鎓离子中间体。基于对该高活性中间体的选择性转化，成功发散性地组装出一系列结构复杂且含有拥挤立体中心的手性多环分子，实现了复杂多环骨架的高效、高立体选择性构建。","scd":null,"kp":[]},{"i":39687,"as":"为了探索星际冷气体介质中肽键的非生物形成机制，研究结合真空紫外-红外光解光谱与从头算量子化学计算，考察了丙烯腈、3-丁烯腈和4-戊烯腈与水在118 nm光电离下的离子-分子反应。实验证实产物高度依赖于腈类前体的烷基链长度。研究表明，气相腈-水团簇在真空紫外光电离驱动下，确实能够形成具备肽或类肽键的预生物分子。","scd":null,"kp":[]},{"i":39688,"as":"","scd":null,"kp":[]},{"i":39689,"as":"","scd":null,"kp":[]},{"i":39690,"as":"","scd":null,"kp":[]},{"i":39691,"as":"夏季北大西洋急流（NAJ）近期呈现出向赤道方向显著移动的特征，这与纬向平均急流向极地移动的趋势相反。利用先进的数值模型和再分析数据，研究证实NAJ的向赤道偏移主要由气候内部变率主导，而非外部强迫。其中，夏季北大西洋“暖洞”通过湍流热释放起到了关键驱动作用，这一独特机制深刻影响了区域极端天气系统的路径。","scd":null,"kp":[]},{"i":39692,"as":"研究利用钡离子（Ba2+）作为探针，探究了电压门控钾离子通道（KCNQ1）的孔道特性与电压传感器结构状态的关系。实验发现，外部Ba2+对KCNQ1通道的阻断具有电压依赖性，而电压依赖性通道开放主要源于Ba2+的电压依赖性解阻断过程。这表明电压传感器结构域和调节亚基能够在电压门控激活之外，直接改变通道开放孔道的构象和属性。","scd":null,"kp":[]},{"i":39693,"as":"研究开发了一种全二维的高温离子门控突触晶体管（A2D-HTIGST），专为125°C以上高温环境的神经形态计算设计。该器件采用二硫化钨（WS2）作为沟道，硫代磷酸铜铟（CuInP2S6）作为离子门控层，六方氮化硼（h-BN）作为电子势垒。该突触晶体管在高温下展现出优异的通道电导精准控制能力，并成功实现了极低能耗的类脑智能应用。","scd":null,"kp":[]},{"i":39694,"as":"针对非离子共价有机框架（COFs）难以手性诱导的问题，研究提出了一种界面溶剂热合成策略。通过在水相中分离超亲水性离子胺，在有机相中分离醛单体，实现了精确的动力学调控和高效的分子到介观尺度的手性放大。该方法成功合成出阴离子、阳离子和两性离子型的高有序螺旋COFs，具有优异的光学活性，椭圆度超过3600 mdeg，绝对不对称因子高达0.07。","scd":null,"kp":[]},{"i":39695,"as":"","scd":null,"kp":[]},{"i":39696,"as":"研究设计了一种名为UNITE的通用无创癌症检测框架，基于浅层全基因组测序（sWGS，0.1×测序深度）提取的“基因组区域-片段长度”矩阵进行癌症识别。通过对涵盖26种癌症类型的2063个血浆样本进行评估，证实该多特征人工智能（AI）算法能够整合碎片组学和表观遗传学特征。该技术有效突破了早期低肿瘤负荷下依赖突变信号的传统检测局限。","scd":null,"kp":[]},{"i":39697,"as":"研究利用超高分辨率3T和7T MRI以及超高梯度扩散MRI技术，调查了先天性失明对人类早期视觉皮层的影响。结果显示，先天失明个体的灰质和浅表白质中，代表铁和髓鞘的R2*和MTsat标记物减少，同时扩散率、取向分散度增加，且神经突密度降低。这证实了感觉经验的缺失会直接影响人类大脑皮层的髓鞘化进程及相关微观结构的成熟。","scd":null,"kp":[]},{"i":39698,"as":"研究者提出了一种由高输出纤维状介电弹性体驱动器（DEAs）驱动的无电机髋部外骨骼套装。这种新型致动器克服了传统电机或气动装置笨重坚硬的缺陷，通过双极性分子设计，实现了381.6 mN·mm⁻²的阻塞应力、260 J/kg的能量密度和1664 W/kg的功率密度。该技术为下肢轻量化辅助提供了一种全新的柔性解决方案。","scd":null,"kp":[]},{"i":39699,"as":"研究揭示了无重金属胶体量子点发光二极管（QD-LEDs）运行过程中的纳米级退化机制。红光和蓝光QD-LEDs在运行中会发生颗粒粗化和功能层变薄，并在器件内部产生氧和氢元素的扩散，其中氧气会积聚在铝电极与ZnMgO电子传输层界面。原位透射电镜观察表明，在原子氢物种存在的条件下，电子束照射会加剧这些纳米级的形态与化学变化。","scd":null,"kp":[]},{"i":39700,"as":"研究提出了一种利用DNA导向和鸟嘌呤特异性化学的逆向缺陷设计策略，成功在单壁碳纳米管中引入鸟嘌呤缺陷。这些被定义为sp²缺陷的修饰不同于传统的sp³缺陷，它们在实现可调谐的性能调制同时，最大程度地保留了碳纳米管晶格的π共轭结构。该技术应用于五种不同的单手性碳纳米管，实现了依赖于手性的高分辨率发射特性调控。","scd":null,"kp":[]},{"i":39701,"as":"结合高对比度tau-PET探针与正常连接组学，研究比较了37名进行性核上性麻痹（PSP）患者和48名健康对照组。结果发现，PSP患者的tau沉积部位与一个共同的皮质网络相连，该网络主要与支持目标导向行为的经典动作模式和额顶叶网络重叠。这一发现揭示了tau蛋白积累引发的认知症状背后的特定大脑网络机制，且该网络无法仅从脑萎缩中推导得出。","scd":null,"kp":[]},{"i":39702,"as":"研究利用冷冻电子显微镜解析了活性代谢型谷氨酸受体（mGlu）与G蛋白复合物的结构（包括mGlu1-Gq、mGlu1-Gi和mGlu5复合物）。C类G蛋白偶联受体中的第一组受体（mGlu1和mGlu5）优先偶联Gq/11蛋白。这些复合物结构直观揭示了第一组受体优先结合Gq/11蛋白的特定分子机制，填补了其在神经突触传递和神经系统疾病研究中关键环节的空白。","scd":null,"kp":[]},{"i":39703,"as":"基于隼鸟2号任务在碳质小行星“龙宫”上意外检测到的硫同素异形体（S8、S7和S6），研究通过星际冰类似物的实验提供了确凿证据。研究表明，这些硫同素异形体可追溯至冷分子云演化的早期阶段，在这些阶段中，星际冰幔通过高能处理促进了复杂含硫物质的形成。这为理解星际介质中非常规的硫化物化学反应过程提供了重要依据。","scd":null,"kp":[]},{"i":39704,"as":"研究团队基于最优传输理论，提出了一种模拟具有任意体积、动态形状和形变特性的多细胞粒子系统的新框架。该计算模型能够有效处理细胞聚集体、组织或细菌菌落等系统中强烈的体积排斥和形状相互作用限制。该框架支持广泛的相互作用和形变机制，并在最先进的数值层面上自动处理体积排斥约束，为探索发育生物学中的宏观自组织结构提供了技术方法。","scd":null,"kp":[]},{"i":39705,"as":"研究在外延BiFeO3（BFO）薄膜中发现了一种机械辅助的铁电极化翻转路径。仅使用面外电场时，极化翻转需约4伏电压并伴随多态共存；而在施加机械压力的情况下，正向矫顽电压可大幅降至0伏，实现自发极化反转。这种通过机械应力改变能量学并控制多铁性材料畴结构的策略，克服了传统电场翻转高切换场和极化变体竞争的限制。","scd":null,"kp":[]},{"i":39706,"as":"研究者利用刚性方平面单体（TCTP）和螺硼酸酯连接基团，成功合成了具有nbo拓扑结构的三维结晶共价有机框架（COF）。理论计算表明，TCTP核心的高刚性有效抑制了骨架形成过程中的结构波动。通过微晶体电子衍射技术，研究明确解析出该材料具有非互穿的立方框架结构。这一发现解决了带有螺硼酸酯连接的三维COF结构表征的难题。","scd":null,"kp":[]},{"i":39707,"as":"研究证实，在弛豫铁电钙钛矿基体中人为引入原子级化学异质性，能够有效提升无铅陶瓷的储能密度和效率。以(Bi0.5Na0.5)TiO3基弛豫铁电体为宿主，通过操纵A/B亚晶格占位的关联性设计，原子尺度化学异质性成功调和了介电陶瓷中大极化、低滞后损耗与高击穿强度之间的固有矛盾。该技术为先进介电电容器提供了重要设计路线。","scd":null,"kp":[]},{"i":39708,"as":"结合第一性原理计算与机器学习加速的路径积分分子动力学，研究量化了地核形成条件下硅酸盐和金属熔体之间的氢同位素分馏。结果表明，地核形成过程使得硅酸盐地球富集氘，而同位素较轻的氢则集中在地核中。这一物理机制要求原地球初始的氘氢比（D/H）必须低于现今地幔的数值，为解释地球整体水分历史和起源提供了新约束模型。","scd":null,"kp":[]},{"i":39709,"as":"研究通过结合电化学门控与局部热激活，在单一且可扩展的模拟组件中实现了多种复杂的神经形态计算功能。该电化学存储器除了基础的ON/OFF开关外，还能实现线性多态模拟电阻调节、非线性易失性开关、脉冲、振荡及随机等特性。这一技术突破解决了在单一器件中复现生物神经元极端多功能性以适应人工智能计算需求的重大挑战。","scd":null,"kp":[]},{"i":39710,"as":"研究人员开发了聚合物支持的质膜（PSPM）技术，结合DNA-PAINT超分辨率显微镜，直接观察到了细胞焦亡过程中质膜上的天然GSDMD（Gasdermin D）孔道。定量分析显示，GSDMD组装成异质性大分子结构，并揭示了人和小鼠在孔道大小上的物种差异。此外，棕榽酰化缺陷的C191A突变体虽保留微弱的膜结合能力，但无法形成完整的孔道结构。","scd":null,"kp":[]},{"i":39711,"as":"为克服自发荧光技术中低量子产率和光谱重叠的限制，研究开发了一种双光子光热（2PPT）显微镜。该技术利用光热方法测量细胞内源性发色团（如NADH和FAD）的光学吸收，而非自发荧光，通过双光子吸收产生的局部热瞬变实现亚微摩尔级分辨率的检测。这种特异性标记技术成功捕捉到了线粒体对化疗反应的代谢变化。","scd":null,"kp":[]},{"i":39712,"as":"研究开发了一类具有半不稳定性的ImQun氮杂环卡宾配体，用于实现无氧化剂的金(I)/金(III)催化反应。最佳的ImQunDippNMe2AuCl催化剂在螯合氮原子和金中心之间具有极短的距离，这为无氧化剂反应模式提供了结构基础。该配体平台展现出极高的催化活性，在多种化学转化中具有潜力替代传统的钯催化体系。","scd":null,"kp":[]},{"i":39713,"as":"研究揭示了微生物代谢产物短链脂肪酸（SCFAs，如丙酸和丁酸）调节免疫的具体机制。SCFAs通过直接结合p38α MAP激酶并促进其与TAB1的相互作用，触发p38α自磷酸化。激活的p38α随后磷酸化TRAF3的丝氨酸85位点，阻断K63连接的多泛素化及下游TBK1-IRF3激活，从而抑制巨噬细胞活化并减轻肠道炎症。在溃疡性结肠炎患者的粪便数据中也验证了该机制的强相关性。","scd":null,"kp":[]},{"i":39714,"as":"通过对人类抗原诱导的1型调节性T（Tr1）细胞进行多组学分析，并结合CRISPR功能基因组学，研究发现转录因子IRF4、BATF和MAF在Tr1细胞的分化、表型和功能中发挥着关键作用。基于这些发现提取的Tr1转录特征标签，成功在患者单细胞数据集中精准识别出具有Tr1表型的细胞。这为人类Tr1细胞在组织中的识别及其治疗应用提供了分子层面的靶点。","scd":null,"kp":[]},{"i":39715,"as":"基于全球森林样地数据集，研究将群落冠层叶片性状划分为三个维度：叶片经济型、叶片密度和氮磷比(N:P)。这三个性状维度的变化受不同因素驱动：叶片经济型由落叶树比例决定，叶片密度受土壤有效磷和温度影响，N:P比则由温度主导。这三个性状维度共同解释了森林生态系统最大光合作用变异的60.2%，其中叶片N:P比显示出最强的解释力。","scd":null,"kp":[]},{"i":39716,"as":"利用小鼠前交叉韧带重建模型，研究发现低强度机械刺激通过ACSL4介导的脂质代谢重编程，促进了巨噬细胞的M2极化和胞葬作用，从而加速腱骨愈合。敲除Acsl4会降低脂肪酸氧化并阻碍此愈合过程。此外，CCL9-CCR1信号轴引导了骨髓基质细胞的募集，且工程化表达CCL9的外泌体同样能够有效促进腱骨修复。","scd":null,"kp":[]},{"i":39717,"as":"组蛋白H2BE113K是乳腺癌中常见的错义突变。研究表明，该突变能促进乳腺癌细胞的集落形成。转录组学分析显示，H2BE113K细胞内多种癌症通路基因出现差异表达，且高表达基因位点的染色质可及性增加，并伴有H2BE113K的富集。此外，消耗G3BP2会影响这一过程，揭示了H2BE113K通过调节染色质动力学来驱动乳腺癌进展的核心机制。","scd":null,"kp":[]},{"i":39718,"as":"下丘脑内侧视前区（MPOA）在驱动母性行为中起关键作用。研究鉴定出一条从MPOA投射至腹侧被盖区（VTA）的催乳素受体神经回路，该回路在母鼠与幼崽互动时被特异性激活。激活该回路可促使未交配雌鼠增加与幼崽的互动，而消除此投射中的催乳素作用则会阻止产后母幼互动的增加。该催乳素受体MPOA-VTA神经元可调节多巴胺活动。","scd":null,"kp":[]},{"i":39719,"as":"针对胚胎黏附研究缺乏体外模型的局限，研究人员开发了一种双通道微流控平台，包含器官来源的子宫内膜上皮细胞和原代基质细胞。该模型重现了子宫内膜的关键生理特征，包括上皮极化、基质蜕膜化、细胞外囊泡释放和激素诱导的容受性。利用小鼠胚胎和人类囊胚验证发现，胚胎表现出初始黏附特征，如滋养外胚层接触建立、内细胞团重排等。","scd":null,"kp":[]},{"i":39720,"as":"研究对5个地点3年内收集的6151份狐蝠 pooled 尿液样本进行RT-qPCR分析，探讨了亨德拉病毒脱落动态。结果揭示了病毒载量的周期性变化与马群溢出风险的纵向关联。研究指出，仅凭病毒基因组检测阳性率不足以评估溢出风险，必须考虑感染性病毒的存在及达到传播所需的足够剂量，这对预测和管理人畜共患病溢出具有重要意义。","scd":null,"kp":[]},{"i":39721,"as":"曲美替尼是一种高选择性的MEK抑制剂，尽管耐受性良好，但会引起剂量限制性心肌病。小鼠模型及体外实验证实，曲美替尼会导致心肌细胞和部分癌细胞发生线粒体功能障碍，并在体内引发先天免疫反应。体内实验显示，给药3天内即出现心肌收缩功能障碍，2周内可发展为心力衰竭，高分辨率呼吸测定进一步证实了其心脏毒性机制。","scd":null,"kp":[]},{"i":39722,"as":"花粉萌发过程中，大量分泌囊泡的定向运输是关键。研究发现Myo11C1和Myo11C2蛋白具有功能冗余性，双突变体会导致囊系泊效率受损及F-actin组织异常。Myo11C1并不与肌动蛋白丝共定位，而是与AtFH5分泌囊泡共定位。分析表明，Myo11C结合从AtFH5-SVs成核的肌动蛋白丝并表现出正端定向运动，由formin-actin-myosin系统驱动非常规囊泡运输。","scd":null,"kp":[]},{"i":39723,"as":"细胞可塑性促进结直肠癌进展和耐药性。研究发现，在家族性腺瘤性息肉病患者的息肉和小鼠肠腺瘤中，早期已存在与PROX1+肿瘤干细胞相关的可塑细胞状态（PCS）。当经典Wnt效应子Tcf7或Lef1缺失时，肠道肿瘤细胞会表现出进行性的可塑性变化、Myc激活以及Lgr5+肿瘤干细胞谱系定向的丧失，揭示了肿瘤早期干细胞命运的演变。","scd":null,"kp":[]},{"i":39724,"as":"针对缺乏陪葬品的早期基督教儿童骨骼遗骸难以进行形态学性别鉴定的问题，研究对瑞典晚维京时代至中世纪的142个个体（含68名未成年和74名成人）进行了基因组学筛查。通过基因组性别鉴定和亲缘分析，结果推翻了集体墓葬反映密切血缘关系的假设，为古代集体墓葬中儿童对待方式及集体坟墓的作用提供了新的基因组学事实依据。","scd":null,"kp":[]},{"i":39725,"as":"全钙钛矿叠层太阳能电池的发展受限于窄带隙锡铅钙钛矿中亚晶胞结晶时Sn/Pb分布不均的问题，这会产生陷阱态并加速降解。研究采用S-烯丙基-L-半胱氨酸（SALC）作为配体引入分子稳定策略，利用其与碘化锡（SnI2）的强硫醚配位优先结合，有效调节结晶动力学，实现空间上均匀的锡铅分布，从而提升全钙钛矿叠层电池的效率和稳定性。","scd":null,"kp":[]},{"i":39726,"as":"针对单网络弹性体刚度与韧性难以兼顾且坚韧多网络弹性体抗疲劳性有限的痛点，研究开发出双网络颗粒弹性体（DNGE）。该材料由坚硬的弹性体微粒通过较软的第二网络连接而成，完美结合了韧性与抗疲劳性。其局部变化的组成和结构使DNGE能够有效分散应力，并在中等应变下重复耗散能量，在软体机器人和可穿戴电子设备领域极具应用潜力。","scd":null,"kp":[]},{"i":39727,"as":"研究团队报告了一项在1.036 GHz附近进行的轴子光环仪后续搜索，该工作完成了并扩展了先前的物理研究。研究恢复并分析了此前因实验信息未记录而无法使用的数据集。此次搜寻旨在探测暗物质候选信号，最终结果完成了对1.036 GHz附近候选信号的排除，相关结果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39728,"as":"介绍了一种名为ASPIRE（通过重用加速序列后验推断）的通用框架。该框架能够将现有的后验样本和贝叶斯证据估计值，在无需重新运行原始分析的情况下，直接转换为替代模型下的无偏结果。ASPIRE结合了归一化流等技术，大幅提升了引力波数据分析中贝叶斯推断的计算效率。","scd":null,"kp":[]},{"i":39729,"as":"尽管相关费米子系统响应的运动方程存在明确的理论公式，但在原子核的数值计算中必须进行可行近似。研究评估了其中一种广泛应用的近似方法——截断谐振子基。作者深入分析了在核响应的相对论方法中，由基截断、统计误差以及系统不确定性带来的影响，为原子核结构相对论计算提供了精度验证方法。","scd":null,"kp":[]},{"i":39730,"as":"基于欧洲核子研究中心（CERN）反质子减速器提供的低能反质子束，研究扩展了从头算无核壳模型/共振基组方法（NCSM/RGM），用于研究低能光反质子-原子核系统。该工作利用反物质作为探测核结构的探针，探讨了形成包含反质子的少数体奇异系统的机制，为理解反物质与物质的相互作用提供了详细计算结果。","scd":null,"kp":[]},{"i":39731,"as":"基于原始M3Y-Reid相互作用，研究重新参数化了一种依赖密度的核子-核子相互作用（CDM3YR），以在非相对论Hartree-Fock计算中精确重现对称核物质的饱和特性。研究利用这种折叠模型，深入对比分析了12C+12C与16O+16O系统的低能弹性散射和聚变过程，为重离子核反应机制研究提供了关键参数。","scd":null,"kp":[]},{"i":39732,"as":"研究引入了一种新型的深度卷积神经网络（NN）增强的贝叶斯全局分析方法，用于研究最高能重离子碰撞中的体观测量。该框架结合了相对论2+1D二阶粘性流体力学、动态冻结以及微扰量子色动力学（pQCD），通过机器学习方法有效优化了重离子碰撞复杂物理过程的模型参数提取和不确定性分析。","scd":null,"kp":[]},{"i":39733,"as":"中子皮厚度是探测核状态方程同位旋矢量部分及其密度依赖性的敏感工具，通常由对称能斜率参数L表征。研究利用多种实验和观测方法提取了中子皮厚度数据，并采用层次贝叶斯分析方法对其进行全局评估。研究结果量化了中子皮厚度测量值，并精确限定了对称能斜率参数L的取值范围及其理论 implications。","scd":null,"kp":[]},{"i":39734,"as":"这是针对此前发表于《物理评论快报》的一篇研究论文（《探测下一次银河系核心坍缩超新星中的引力波记忆》，Phys. Rev. Lett. 133, 231401 (2024)）的勘误（Erratum）。原文作者提交了相关勘误内容，勘误发表于《物理评论快报》137卷，对原论文中存在的疏漏或错误进行了修正。","scd":null,"kp":[]},{"i":39735,"as":"颗粒流中的尺寸偏析现象广为人知：实验室实验表明在装填料仓时大颗粒向壁面迁移，小颗粒集中在中心。然而，大规模工业料仓的现场观测却呈现出相反的模式。研究针对这一悖论展开探讨，分析了料仓装填过程中偏析模式的尺度依赖性，揭示了实验模型与实际工程物理过程产生差异的关键机制。","scd":null,"kp":[]},{"i":39736,"as":"边缘激发是手性拓扑有序系统的标志性特征，在连续分数量子霍尔态（FQH）中由手性Luttinger液体理论描述。研究探讨了这些场理论预测能否在离散的玻色子Hofstadter模型中精确识别。研究具体分析了ν=1/2分数量子霍尔绝缘体中的手性边缘激发，验证了其在离散晶格系统中的物理特征表现。","scd":null,"kp":[]},{"i":39737,"as":"金红石TiO2(111)极性表面因具有独特的电子和化学性质，在催化和电子学中具有重要作用。由于其内在的不稳定性通常需要通过表面重构来缓解，其原子结构难以被解析。本文研究了熵（特别是振动熵）在补偿和稳定这种极性表面中的作用，为理解极性表面的稳定机制提供了新的视角。","scd":null,"kp":[]},{"i":39738,"as":"化学短程有序（SRO）是多主元合金（MPEAs）原子结构的内在特征，有效控制SRO结构能够显著提升合金的强度和延展性。然而，SRO的实验表征一直面临巨大挑战。本研究利用正电子湮没技术，成功实现了对多主元合金中化学短程有序结构的鉴别，为多主元合金的微观结构表征与性能调控提供了有效的实验方法。","scd":null,"kp":[]},{"i":39739,"as":"三维螺旋注入方案实现了在具有纳秒级旋转周期的超紧凑环中存储粒子束。研究团队首次在一个周长为22厘米、旋转周期为4.7纳秒的弱聚焦环中，利用140纳秒的脉冲切割磁铁成功存储了动量为297 keV/c的电子束。该实验证明了三维螺旋注入技术在小型化加速器束流存储方面的可行性。","scd":null,"kp":[]},{"i":39740,"as":"角动量守恒是物理学的基本定律。在离散晶格中，由于存在非平庸的动量空间能带交叉，角动量守恒的实现形式与连续空间存在显著差异。本研究探讨了二次能带相切和非平庸卷绕现象，揭示了离散晶格系统中广义角动量守恒的规律，加深了对离散系统拓扑与对称性的理解。","scd":null,"kp":[]},{"i":39741,"as":"本研究利用数十年前的卡文迪许实验装置，为一种带有极小部分电子电荷的假想粒子（毫电荷粒子）设定了新的属性界限。研究通过分析现有实验数据，在无需建造全新对撞机或探测设备的情况下，成功缩小了这类潜在新粒子的参数空间，为超标准模型粒子的寻找提供了新的约束条件。","scd":null,"kp":[]},{"i":39742,"as":"本研究采用Gogny相互作用力，针对覆盖幻数中子壳层N=82及N=126的Xe、Ba、Ce和Nd同位素，进行了关于轴向四极和十六极集体形变的二维生成坐标法（GCM）计算。研究重点探讨了由入侵轨道驱动的四极与十六极形变效应在这些同位素中的稳定性及其演变规律。","scd":null,"kp":[]},{"i":39743,"as":"本研究在Chern-Simons-Landau-Ginzburg理论框架下，调查了分数量子霍尔效应中任意子准粒子（涡旋）的相互作用。研究表明，该系统明确实现了第一类和第二类超导特性的混合。通过高斯定律，每个涡旋同时带有磁通量和电荷，揭示了混合超导态的物理机制。","scd":null,"kp":[]},{"i":39744,"as":"","scd":null,"kp":[]},{"i":39745,"as":"气候变化和社会经济发展加剧了全球河流洪水风险。本研究结合高分辨率水动力模拟、人口预测及现有防洪水平，分析了美国本土洪水风险。结果显示，到2050年，小河流对气候变化引起的洪水强度增加表现出更高的敏感性。由于小河流沿岸防洪设施目前最薄弱，附近居民面临极高风险。要将小河流洪水风险恢复至历史水平，需要投入最高的防洪建设资金。","scd":null,"kp":[]},{"i":39746,"as":"","scd":null,"kp":[]},{"i":39747,"as":"UMAP和tSNE等随机近邻嵌入（SNE）算法在可视化高维噪声数据时，常无法保留几何结构，甚至错误分离连通的子流形。为此，本研究提出了一种结合离散图曲率的SNE算法——EmbedOR。该算法利用曲率增强的距离度量进行随机嵌入，以凸显底层的聚类结构。研究从数学上证明了EmbedOR能将一致性扩展至更广泛的数据集，并在真实与合成数据中展现了优异的聚类保持能力。","scd":null,"kp":[]},{"i":39748,"as":"本研究利用印度村庄的数据，分析了网络中的多重性（即人与人之间拥有多种不同类型的关系）。结果显示，社交、建议、帮助和借贷等实际关系相互关联但各不相同，而基于种族和地理的常用网络代理指标与实际关系几乎不相关。实验和理论表明，不同关系层间的重叠会阻碍疾病等简单传染物的传播，但高水平的多重性增强了复杂信息或行为的扩散。","scd":null,"kp":[]},{"i":39749,"as":"","scd":null,"kp":[]},{"i":39750,"as":"研究开发了一种结合样本量子对角化（SQD）与定域活性空间自洽场（LASSCF）的混合量子-经典工作流，命名为LASSQD，用于求解过渡金属配合物的基态。该方法将量子采样与基于片段的多参考理论结合，降低了强关联活性空间的计算成本。在多个铁基配合物上的测试表明，LASSQD的计算结果与LASSCF高度吻合（误差在1 kcal/mol以内），通过稀疏近似极大降低了计算量。","scd":null,"kp":[]},{"i":39751,"as":"","scd":null,"kp":[]},{"i":39752,"as":"","scd":null,"kp":[]},{"i":39753,"as":"光催化合成过氧化氢（H2O2）的效率常受限于电荷的快速复合。受自然光合作用类囊体膜分步电子转移机制的启发，本研究设计了仿生供体-受体1-受体2（D-A1-A2）有机笼。在该结构中，供体和受体沿能量梯度有序排列，实现了抑制复合的连续电荷转移（RS-SCT）过程，从而有效促进了光催化H2O2的生成。","scd":null,"kp":[]},{"i":39754,"as":"","scd":null,"kp":[]},{"i":39755,"as":"","scd":null,"kp":[]},{"i":39756,"as":"","scd":null,"kp":[]},{"i":39757,"as":"","scd":null,"kp":[]},{"i":39758,"as":"电化学由CO2和含氮小分子形成C-N键是生产胺和酰胺等高价值产物的可持续途径。相较于难以精确研究构效关系的异相催化剂，分子催化剂在基础研究中具有易于调节的优势。本研究展示了一种单分子催化剂在电化学CO2与硝酸根还原形成C-N键中的应用，为深入理解金属中心、配体及二级配位球对催化活性的影响提供了基础。","scd":null,"kp":[]},{"i":39759,"as":"一步构建多个连续立体中心以合成复杂手性分子一直是有机化学的挑战。本研究报道了一种光诱导铜催化的方法，通过分子内1,5-氢原子转移（HAT）策略，实现了环烷基胺的位点和对映选择性的β-C(sp3)-H炔基化。该催化去对称化自由基交叉偶联反应在无张力环系中成功构建了C(sp3)-C(sp)键。研究结合了联二萘酚与新型三齿配体，为合成复杂手性分子提供了高效的新途径。","scd":null,"kp":[]},{"i":39760,"as":"电化学固氮反应（NRR）在水溶液中常因吸附态氢（*H）的积累而受制于析氢反应（HER）。非水溶剂虽能缓解此竞争，但缺乏抑制HER的分子设计原则。本研究通过密度泛函理论计算与微动力学建模证明，质子供体的空间位阻可选择性地控制 Ru(0001) 表面的质子耦合电子转移（PCET）。增大供体体积可显著提高HER Volmer步的反应势垒，从而在不大幅减慢NRR的情况下有效抑制析氢副反应。","scd":null,"kp":[]},{"i":39761,"as":"由于氧化还原化学上的根本不匹配，高氧化态铈与还原性氢化物配体的络合产物此前未被发现。本研究首次报道了四价铈铝氢化物络合物的合成、表征及反应性。通过借鉴四价铈烷基配合物的合成策略，成功分离出目标产物。单晶X射线衍射、核磁共振、紫外可见近红外光谱以及DFT计算表征了该络合物的成键与结构，循环伏安法和小分子反应揭示了其基本的反应特性。","scd":null,"kp":[]},{"i":39762,"as":"本研究合成了锰掺杂的Co3O4，相较于纯Co3O4，其展现出更优异的催化性能、防水性及长期耐久性。研究表明，锰掺杂赋予了Co3O4更高的Co3+含量和氧空位，有利于CO的催化氧化。由于锰的d电子少于钴，掺杂导致更高的d带中心，这阻碍了锰与CO分子间的电子交换，抑制了CO的电子给出并削弱了CO吸附，最终实现了符合Sabatier原理的最佳反应活性。","scd":null,"kp":[]},{"i":39763,"as":"钛表面的TiO2钝化膜能隔绝环境氧化物，但微生物膜会加速其腐蚀。本研究发现，生长在钛表面的海洋微生物铜绿假单胞菌（Shewanella algae）通过还原TiO2破坏钝化膜。该生物膜消耗氧气，在整体有氧条件下的金属界面处形成厌氧环境。高分辨率表征显示钝化层变薄及低价钛氧化物积累，电化学分析表明腐蚀速率增加了六倍。微生物还原的核黄素是导致钝化膜失稳的关键因素。","scd":null,"kp":[]},{"i":39764,"as":"","scd":null,"kp":[]},{"i":39765,"as":"环己醇电催化氧化是合成己二酸（AA）的环保途径，但现有电催化剂在碱性介质中稳定性差。本研究通过自下而上的策略合成了基于[Ni36]纳米笼的金属有机框架（[Ni9]-MOF）。该材料在强碱（8 M NaOH）和强酸（1 M HCl）中均表现出极佳的稳定性。实验证明，[Ni9]-MOF能高效催化环己醇氧化生成己二酸，且催化剂具有高度可回收性，为工业可持续生产己二酸提供了新型高效材料。","scd":null,"kp":[]},{"i":39766,"as":"金属锡因高理论容量是极具潜力的钠离子电池负极材料，但嵌钠时的巨大体积膨胀会导致颗粒粉化和电极失效。本研究通过溶液过饱和法在块状锡颗粒上原位包覆了高杨氏模量的NaF层。NaF涂层的强机械限制效应有效抑制了锡的体积膨胀和机械应力，并促进了薄而均匀的固体电解质界面（SEI）膜的形成，显著提高了库仑效率。该设计为解决合金负极的体积膨胀问题提供了有效策略。","scd":null,"kp":[]},{"i":39767,"as":"该研究开发了一种直接合成p型PbS量子点墨水的方法，具备可调的量子点尺寸、光吸收和p型电子特性。这种墨水能够在6英寸硅基底上生成导电且高度均匀的p型薄膜，克服了传统固相配体交换法中配体替换不完全和氧化不均匀导致的薄膜不均匀问题，为晶圆级短波红外光电产品的制造提供了可行方案。","scd":null,"kp":[]},{"i":39768,"as":"该研究提出了一种基于内在动力学稀疏表示的功能子空间聚类无监督方法（FRID）。该方法能够从中尺度神经记录中识别具有共享微电路连通性和信息编码特性的神经元。在模拟复杂网络和经验性钙记录中，FRID的表现显著优于基于相关放电的聚类方法，为构建细粒度的大脑功能图谱提供了解决方案。","scd":null,"kp":[]},{"i":39769,"as":"","scd":null,"kp":[]},{"i":39770,"as":"","scd":null,"kp":[]},{"i":39771,"as":"","scd":null,"kp":[]},{"i":39772,"as":"该研究开发了一种滴状芯吸方法，将负载盐的吸附剂集成到三维多孔基底中。该方法解决了负载盐松散粉末形态在器件集成中的难题，制备出机械性能稳固且具备蒸汽可及性的吸附剂模块，为推进吸附式大气取水和热能储存技术的规模化应用提供了有效路径。","scd":null,"kp":[]},{"i":39773,"as":"","scd":null,"kp":[]},{"i":39774,"as":"研究开发了一类新型荧光点击染料，通过对（硅）罗丹明呫吨支架的氨基进行结构修饰，实现了极短的连接子和高度优化的淬灭状态。这种修饰合成了单功能和双功能衍生物，其中单功能染料与现有点击标记策略完全兼容，并展现出优异的荧光响应，实现了高效的荧光开启。","scd":null,"kp":[]},{"i":39775,"as":"","scd":null,"kp":[]},{"i":39776,"as":"金属锂的动态行为影响电池的寿命与安全，但难以对低Z元素进行跨尺度化学与空间识别。研究开发了一种通过氧化还原反应将高Z元素（重金属离子）染色到金属锂表面的方法。金属锂将重金属离子还原并在表面成核为纳米颗粒，有效增强了其在电子束或X射线下的可见度。该技术成功实现了对嵌入残余SEI中死锂的直接多尺度可视化观察。","scd":null,"kp":[]},{"i":39777,"as":"研究探讨了配体去芳香化驱动的金属-配体协同（MLC）在锰催化烯烃氢膦化反应中的作用。通过全面的动力学和光谱学研究，确定了溶液中Mn(I)催化剂的结构，并分离出去芳香化和非去芳香化的催化活性中间体。结果表明，尽管该反应中存在多种可及的催化机制路径，但去芳香化驱动的MLC在反应过程中发挥了实质性作用。","scd":null,"kp":[]},{"i":39778,"as":"Invas是一种感知基因倒位的转录组组装框架，可处理大量短读长测序数据。该工具结合全基因组测序断点和转录组证据，恢复未比对读长，并利用共轭流优化组装亚型。在4.2万个事件中，Invas表现出高精度和高召回率，并在7个疾病队列中成功识别出复发性胚系易感变异和体细胞驱动因子。","scd":null,"kp":[]},{"i":39779,"as":"研究发现细胞因子受体TACI对于骨髓长寿命浆细胞的存活至关重要。TACI缺失会降低多克隆浆细胞数量，削弱T细胞依赖性和非依赖性抗原诱导的长寿命浆细胞，严重损害SARS-CoV-2和流感疫苗诱导的免疫保护。机制上，TACI缺失会导致线粒体ROS积累，从而影响浆细胞存活。","scd":null,"kp":[]},{"i":39780,"as":"研究揭示了乙酰转移酶HBO1复合物中JADE和BRPF支架亚基与核小体结合的机制。结构分析表明，JADE1的PZP结构域具有强DNA结合能力，能结合组蛋白H3尾部；而BRPF1的PZP结构域因无法结合大部分H3尾部且DNA结合力弱，与核小体的结合能力低一千倍。JADE1的PZP结构域能够保护H3尾部。","scd":null,"kp":[]},{"i":39781,"as":"研究利用单细胞RNA测序和单细胞ATAC测序的多组学方法，绘制了皮肤鳞状细胞癌小鼠模型中不同EMT状态的转录组和染色质图谱。结合CRISPR/Cas9功能丧失实验，研究定义了控制上皮-间充质转化各状态间转变的转录因子，阐明了调控肿瘤起始、转移及治疗耐药性的动态过程机制。","scd":null,"kp":[]},{"i":39782,"as":"研究构建了生物工程化的患者来源肿瘤-免疫模型，通过将癌细胞与相关成鞘细胞在3D基质或脱细胞人类卵巢上共培养，模拟了高级别浆液性癌的缺氧和细胞外基质重塑特征。该模型能够重建生理相关的氧气水平，并研究肿瘤-基质-免疫的多细胞相互作用，克服了现有模型无法完全反映肿瘤微环境特征的局限。","scd":null,"kp":[]},{"i":39783,"as":"研究利用患者来源类器官的连续原位移植模型，发现结直肠癌细胞在转移过程中会短暂采用表皮角质形成细胞的伤口愈合程序。扩散肿瘤细胞在转移前会失去癌症干细胞特征并表达伤口诱导角蛋白（如KRT17）。这种状态是可逆的，当细胞在远处器官定植后，会重新获得类似原发肿瘤的特征。","scd":null,"kp":[]},{"i":39784,"as":"研究利用冷冻电镜解析了大肠杆菌全局转录阻遏蛋白Mlc及其与调节伙伴（包括IICBGlc、DNA操作子和抗阻遏蛋白MtfA）的复合物结构。这些结构揭示了Mlc的分子架构及其与大分子结合伙伴的相互作用机制，结合分子动力学模拟，阐明了Mlc介导碳水化合物代谢转录调控的结构基础。","scd":null,"kp":[]},{"i":39785,"as":"研究综合了机载激光雷达数据和地面森林清查数据，发现气候不仅直接影响森林初级生产力，还通过调节林冠结构多样性产生间接影响。这种间接机制具有显著作用。研究观察到结构多样性热点与高生产力热点之间存在明显的纬度一致性，揭示了林冠结构多样性在气候与森林生产力间的中介作用。","scd":null,"kp":[]},{"i":39786,"as":"研究利用英国生物银行的大规模多模态数据，将2923种血浆蛋白质与多器官的1051种成像特征进行整合分析，绘制了表型和遗传联系图谱。研究发现了5067种表型蛋白质-成像关联，确定了器官特异性和共享蛋白质组关系，并映射了器官结构和功能的关键蛋白质预测因子。","scd":null,"kp":[]},{"i":39787,"as":"研究结合3D单分子定位与角度相关性分析，构建了SARS-CoV-2感染的多色超分辨率图谱。研究发现nsp5蛋白酶定位于DMV孔附近，支持了依赖于蛋白酶的成熟模型，即nsp5的作用允许膜闭合并完成囊内多蛋白加工以激活复制复合物。研究还发现了桥接DMV的双链RNA连接体和胞内结构蛋白。","scd":null,"kp":[]},{"i":39788,"as":"研究发现胆汁酸代谢物甘胆酸通过下调TRIB3的表达，破坏了肠道干细胞的自我更新，从而加速炎症性肠病的进展。TRIB3在隐窝细胞中高表达，对维持肠道上皮干细胞稳态至关重要。这一发现揭示了胆汁酸代谢失衡导致黏膜愈合障碍的具体分子机制。","scd":null,"kp":[]},{"i":39789,"as":"研究提出了一种贝叶斯半机制废水模型EpiSewer，该模型同时考虑了感染动力学、病原体脱落和测量噪声，能够直接从原始浓度和流量数据推断出有效再生数(Rt)和流行病增长率(rt)。该模型无需预先平滑、插补或去除异常值，在三个季节的多病原体废水监测评估中表现有效。","scd":null,"kp":[]},{"i":39790,"as":"研究揭示了新型窄谱抗生素abaucin精准杀伤鲍曼不动杆菌的机制。Abaucin通过结合其必需的脂蛋白转运蛋白LolDF发挥作用。冷冻电镜结构显示，两个abaucin分子对称结合在LolDF腔内，将其锁定在非生产性的向外开放构象。该抗生素对临床分离的耐碳青霉烯鲍曼不动杆菌(CRAB)表现出强效的体内外抗菌活性。","scd":null,"kp":[]},{"i":39791,"as":"研究揭示了人类细胞中NatB复合物共翻译N端乙酰化的机制。NatB通过新生多肽相关复合物NAC的高亲和力相互作用被招募，NACα的UBA结构域与辅助亚基NAA25结合。同时，两个NatB亚基与核糖体表面形成接触，使NatB活性位点直接定位于新生链旁，实现高效的共翻译乙酰化。","scd":null,"kp":[]},{"i":39792,"as":"","scd":null,"kp":[]},{"i":39793,"as":"","scd":null,"kp":[]},{"i":39794,"as":"研究利用高分散的MnOx/ZSM-5催化剂，实现了温和条件下甲烷直接选择性氧化。研究发现，反应路径受催化剂形态控制：Mn单原子催化剂主要产生C1产物（甲酸和甲醇，选择性约78.8%）；而Mn纳米颗粒催化剂则专一产生以乙酸为主的C2液态含氧化合物，乙酸选择性高达81.8%。这归因于两者截然不同的甲烷活化机制。","scd":null,"kp":[]},{"i":39795,"as":"","scd":null,"kp":[]},{"i":39796,"as":"本文提出一种通过简单的氧化化学激活单层胶体MoS2中性激子发射的方法。环境条件下的紫外光照射使光致发光强度提高2个数量级以上，并伴随显著的蓝移和激子寿命延长约100倍（从0.07纳秒增至6.14纳秒）。这表明材料由以三离子为主的复合转变为中性激子复合，有效克服了硫空位引起的缺陷和非辐射复合限制。","scd":null,"kp":[]},{"i":39797,"as":"","scd":null,"kp":[]},{"i":39798,"as":"","scd":null,"kp":[]},{"i":39799,"as":"","scd":null,"kp":[]},{"i":39800,"as":"本文报道了一种金属氢键有机框架（MHOFs），可直接利用空气、水和自然光合成乙醛。其中，HNNU-Se表现出优异的性能，在无需牺牲剂的室外条件下，乙醛产率为557.1 μmol g⁻¹ h⁻¹，电子选择性达95%。其机制在于[Zn(tpy)]2+阳离子捕获和激活二氧化碳，[XCN]-阴离子作为质子穿梭形成富质子微环境，从而促进质子转移动力学。","scd":null,"kp":[]},{"i":39801,"as":"本文开发了一种用于大型螺旋装置（LHD）的中性束电流驱动模拟代码。该代码集成了求解电磁感应、新经典输运和快离子分布函数的模块。代码已通过与等离子体电流演化的解析解进行基准测试，并应用于实际的LHD放电。模拟的等离子体电流趋势和绝对值与测量结果相似，验证了代码在估算束驱动电流及其他分量方面的有效性。","scd":null,"kp":[]},{"i":39802,"as":"本文研究了通过选区激光熔化（SLM）成形的添加Y2O3的氧化物弥散强化（ODS）钢的高温蠕变和辐照损伤行为。微观结构分析表明，SLM成形的ODS-RAFM钢在相同应力和温度下具有更长的高温蠕变寿命，其细晶与再结晶及氧化物钉扎密切相关。同时，该钢表现出优异的辐照稳定性，硬化和板条宽度增加率均低于普通RAFM钢。","scd":null,"kp":[]},{"i":39803,"as":"本文使用磁通管方法研究了仿星器配置中气球模的非线性饱和现象。为解决仿星器数值平衡中缺乏精确力平衡的问题，提出了一种变分方法计算磁通管能量。研究证实，对于线性气球不稳定的剖面，存在跨越等离子体小半径10%-20%的饱和磁通管状态。该模型成功再现了Wendelstein 7X全非线性MHD模拟中位移磁通管结构的特征。","scd":null,"kp":[]},{"i":39804,"as":"本文使用SONIC偏滤器代码研究了JA DEMO托卡马克设计中的功率和粒子排出及杂质浓度问题。模拟评估了在不同氘气注入率下氦气的排出情况。通过增加氘气注入率，在维持较低分离极向电子密度的同时，将外偏滤器峰值热负荷降低至10 MW m⁻2以下。研究还评估了圆顶排气槽处的偏滤器中性和气体压力。","scd":null,"kp":[]},{"i":39805,"as":"在QUEST装置中，通过高场侧注入电子回旋波（ECW）实现了向电子伯恩斯坦波（EBW）的有效模式转换，用于等离子体启动。实验明确观察到由磁场反转方向的EBW驱动电流，这一特性对闭合磁通面的形成具有重要作用。研究基于改进的电流密度剖面模型，重建了开放磁通面阶段的电流分布，并验证了该阶段EBW电流驱动的效率。","scd":null,"kp":[]},{"i":39806,"as":"本文提出了一种专门用于评估由中性束注入（NBI）电离原子驱动的离子回旋辐射（ICE）增长率的计算方法。NBI电离原子的分布函数被建模为速度幂律和俯仰角高斯分布。通过在均匀等离子体中计算快磁声波的增长率，发现速度梯度和俯仰角各向异性对ICE激发有直接影响。增长率与NBI的注入方向密切相关。","scd":null,"kp":[]},{"i":39807,"as":"本文系统研究了TCV双零（DN）L模等离子体中三角性对功率分配和边界湍流的影响。实验表明，三角性显著影响偏滤器内外靶板之间的功率分配。在高三角性DN等离子体中，仅有少部分排气功率到达内靶；而在低三角性中该比例上升。分析模型显示，这源于极向气球径向传输减少以及高场侧横场传输增强。","scd":null,"kp":[]},{"i":39808,"as":"针对未来聚变反应堆的自加热机制，本文研究了JT-60SA装置中D-3He场景下的阿尔法粒子产生和约束。由于JT-60SA未计划进行DT运行，研究提出了依赖3He seeding和500 keV高能中性束注入的方案来产生阿尔法粒子。这为理解ITER中关键聚变阿尔法粒子的约束特性提供了替代的实验途径。","scd":null,"kp":[]},{"i":39809,"as":"针对EAST装置中大瞬态误差干扰下固定参数PID控制器易导致执行器饱和的问题，本文开发了一种基于深度强化学习的等离子体形状控制器。该控制器在现有的等磁通控制方案内运行，在旨在重现大瞬态误差条件的模拟环境中进行训练。通过采用针对大干扰鲁棒性定制的奖励设计，提高了托卡马克磁控边界在强干扰下的控制精度和稳定性。","scd":null,"kp":[]},{"i":39810,"as":"本文为EAST开发了一款快速放电模拟器，将快速集成建模工具METIS与自由边界平衡代码FBT耦合。METIS通过自洽求解热和粒子输运演化等离子体剖面，输出结果直接用于FBT计算给定等离子体形状所需的极向场线圈电流。这种耦合策略为探索托卡马克可行运行空间和生成执行器波形提供了可靠工具。","scd":null,"kp":[]},{"i":39811,"as":"本文开发了二维傅里叶空间全局回旋本征值代码ESR2D，用于求解托卡马克中离子温度梯度（ITG）模的二维回旋本征值问题。在绝热电子线性ITG基准测试中，ESR2D与GENE、NLT和ORB5等初始值代码吻合良好。研究证实，系统中存在两个不同环向分支的ITG模共存。","scd":null,"kp":[]},{"i":39812,"as":"为开发聚变系统的数字孪生并连接下一代装置，2021年启动了E-TASC倡议。该团队利用经过验证的模拟工具，结合百亿亿次级计算和多保真度模型（包括人工智能替代品），在开发聚变系统数字孪生方面取得实质性进展。该倡议包含15个TSVV项目并得到五个高级计算中心的支持。","scd":null,"kp":[]},{"i":39813,"as":"本文利用MARS-F代码结合REORBIT模块，模拟了DIII-D破裂后损失事件中撞击中心柱的逃逸电子（RE）的环向分布。通过追踪三维场中测试RE的导向中心漂移轨道，发现主导的磁流体动力学不稳定性为m/n=2/1, 3/2和1/1模式。外加n=1共振磁扰动会锁定MHD不稳定性，对电子的损失分布产生显著影响。","scd":null,"kp":[]},{"i":39814,"as":"ITER中子活化系统（NAS）是测量总中子产额和第一壁注量的关键诊断系统。其原理是利用气动传输线放置样品材料进行中子活化，随后测量其感应放射性。本文系统量化了NAS中子学模型中的主要不确定度来源，重点关注NAS辐照端和托卡马克的几何建模，这对于可靠的中子输运建模和精确测量至关重要。","scd":null,"kp":[]},{"i":39815,"as":"为研究动态等离子体表面相互作用，本文开发了新型线性等离子体发生器Upgraded Pilot-PSI (UPP)。该装置首次将高通量等离子体暴露与操作式离子束分析（IBA）耦合。UPP能产生稳态氢等离子体，同时利用质子或氦离子束分析材料表层，能够研究氢同位素输运、动态滞留和溅射等过程，还能在材料暴露于等离子体的同时诱导辐射损伤以研究缺陷稳定性。","scd":null,"kp":[]},{"i":39816,"as":"本文介绍了正在为HL-3托卡马克建设的6兆瓦离子回旋频率范围（ICRF）加热系统，预计2026年9月投入使用。该系统频率范围为25-50 MHz，脉冲时长最高5秒。针对氘等离子体，采用氢少数离子和氘二次谐波加热方案（33 MHz, 2.2T）；针对氚等离子体，考虑氦-3基波和氚二次谐波加热方案（25 MHz, 2.5T）。射频发生器由4台1.5 MW发射机组成。","scd":null,"kp":[]},{"i":39817,"as":"在TCV托卡马克中，观察到了环向模数n=0（即轴对称）的全球阿尔芬本征模（GAEs）。这些在多个频率下观察到的n=0 GAEs由阿尔芬连续谱的周期性结构引起。线性MHD计算预测了n=0 GAEs的径向分裂，这与最近观察到的回旋频率以下范围的GAEs径向分裂一致。建模证实这些n=0 GAEs主要位于阿尔芬连续谱的极小值下方。","scd":null,"kp":[]},{"i":39818,"as":"本文进一步研究了EAST托卡马克中共振磁扰动（RMP）对离子内部输运势垒的多种影响。除了触发和维持ion-ITB外，通过调整RMP线圈的相位、环向模数和电流，可实现对势垒的主动控制。在固定其他放电设置的情况下，仅调整RMP线圈配置即可形成ion-ITB，表现出强鲁棒性。结果表明，高n RMP比低n RMP更有利于ion-ITB的形成。","scd":null,"kp":[]},{"i":39819,"as":"本研究使用陀螺流体FAR3d代码进行非线性模拟，分析了JET氘-氚（D-T）放电中的快离子扰动现象。经验证的模拟表明，环向阿尔芬本征态和鱼骨模分别由ICRH加速的穿越型氘离子和捕获型氢离子去稳。多种 energetic particle（高能粒子）模拟揭示了不同高能粒子物种间存在显著的非线性耦合，即使在阿尔法粒子比例较低时，这种耦合也会对其约束产生强烈影响。","scd":null,"kp":[]},{"i":39820,"as":"本研究将COREDIV代码应用于带有钨偏滤器和铍壁的JET高电流、高功率基准脉冲的集成数值建模，等离子体成分为92%氚和8%氢。该模拟通过自洽求解芯部一维径向输运方程与刮削层二维多流体输运方程，采用“半解释性”方法调整输运系数以匹配辐射分布、镍浓度和Zeff等实验数据。模拟结果为该高功率运行场景下的杂质输运与杂质源提供了理论分析。","scd":null,"kp":[]},{"i":39821,"as":"在间接驱动惯性约束聚变（ICF）中，黑腔辐射驱动温度及靶丸上的对称性是关键参数。该研究提出一种通过测量两个正交方向上再发射的X射线辐射通量，来同时确定靶丸上辐射温度和P2不对称性的新方法。利用高Z替代靶丸可解耦黑腔与内爆靶丸间的相互作用，并基于自相似理论给出了不透明度和状态方程对P2不对称性测量的影响。该方法的演示实验已在神光100 kJ激光装置上完成。","scd":null,"kp":[]},{"i":39822,"as":"为响应2023年初制定的新ITER基准运行方案，中国氦冷陶瓷增殖剂测试包层模块（CN HCCB TBM）团队开展了初步工程分析。新基准旨在尽早启动核运行阶段并降低部分运行参数。针对这些工程与技术挑战，团队对HCCB TBM的设计进行了更新，以提升其工程性能和制造可行性，确保其与ITER新运行策略及中国磁约束聚变能发展战略保持一致。","scd":null,"kp":[]},{"i":39823,"as":"","scd":null,"kp":[]},{"i":39824,"as":"为解决水系锌离子电池中水引起的析氢反应和锌枝晶问题，研究人员开发了一种基于同源约束策略的机器学习辅助设计方法。通过线性核支持向量回归模型结合留一法交叉验证，成功筛选出DL-谷氨酸和DL-组氨酸两种具有出色调节水结构能力的氨基酸衍生添加剂。实验证实，这些添加剂能够重新调节电解液结构，有效提升锌负极的稳定性与电池的整体性能。","scd":null,"kp":[]},{"i":39825,"as":"该研究通过晶体工程显著增强了PtBi合金中的体态自旋霍尔效应，降低了自旋霍尔纳米振荡器（SHNOs）的阈值电流。通过引入Bi元素，Pt94.0Bi6.0合金的自旋霍尔效率从纯Pt的0.07大幅提升至0.24。这一体态主导的效率提升避免了传统方法中增加电阻率的权衡问题，为神经形态计算和高频技术提供了一条实现高效、纳米级微波器件的有前景路径。","scd":null,"kp":[]},{"i":39826,"as":"该研究设计了一种响应肿瘤微环境的细胞膜伪装纳米复合材料，用于实体瘤和白血病的联合治疗。该复合材料以过氧化锌为核心，外层包裹载药（阿霉素或柔红霉素）的介孔有机硅，并由掺锰氧化铈纳米颗粒作为介孔门控，最外层覆以同源细胞膜。该结构能够实现治疗成分在病灶部位的靶向释放，有效克服传统化疗药物的脱靶毒性，实现精准递送与多模态联合治疗。","scd":null,"kp":[]},{"i":39827,"as":"本研究通过仿生矿化策略合成了钆-白蛋白纳米结构，并共载入全氟五苯基-15-冠-5醚（PFCE）和光敏剂IR780，构建了诊断治疗一体化探针（IPGB）。该探针在1.5、3.0和9.4 T磁场下均展现出强19F MRI信号及T1-T2双模态对比增强效果，实现了1H/19F多模态成像。除成像功能外，IPGB还表现出优异的光动力治疗（PDT）功效。","scd":null,"kp":[]},{"i":39828,"as":"为解决介电弹性体（DEs）在低电场下易产生机电不稳定性的问题，该研究提出一种互穿聚合物网络（IPN）策略。该网络结合了含动态二硫键的聚氨酯脲的物理交联与聚乙二醇二甲基丙烯酸酯的共价交联。这种IPN交联弹性体具有较低的初始杨氏模量（1.05 MPa），在小应变下易于变形，并在中等应变时出现明显的应变硬化，从而有效抑制了机电不稳定性，实现了低电场下的高驱动应变。","scd":null,"kp":[]},{"i":39829,"as":"本研究开发了一种超灵敏的无线侧流免疫分析平台（WLFIAP），用于检测牙龈卟啉单胞菌。该平台深度集成了荧光纳米DNA步行器与微电子技术。研究合成了一种新型荧光金属有机框架纳米复合物，其荧光强度比商用PCNs高约16.95倍。结合具有优异运动动力学特性的四足DNA步行器，该平台有效放大了检测信号，突破了传统检测方法灵敏度低、耗时长且设备昂贵的瓶颈。","scd":null,"kp":[]},{"i":39830,"as":"该研究提出了一种可持续且适用于规模化制造的生物衍生石墨烯固态离子选择性电极制备方法。通过将硬木生物炭转化为类石墨烯纳米片并制成可打印墨水，采用高通量丝网印刷技术制成电极。与以往基于无定形碳的电极不同，该电极涂覆有聚氯乙烯（PVC）基离子选择性膜，成功实现了无水培营养液的高通量、低成本快速监测。","scd":null,"kp":[]},{"i":39831,"as":"该研究结合ZIF-8前驱体的全固态合成与直接限制热解技术，成功将PtFe合金纳米颗粒均匀锚定在氮掺杂碳上，制备出PtFe/NC催化剂。该催化剂仅含1.59 wt%的Pt，但其半波电位达0.897 V，质量活性高达2.34 A mgPt-1，是商用20 wt% Pt/C催化剂的17倍。该合成工艺具备低成本、无溶剂和尺寸可控的特点，在质子交换膜燃料电池的氧还原反应中展现出优异的活性与稳定性。","scd":null,"kp":[]},{"i":39832,"as":"为探究全固态锂硫电池复杂的固相反应机制，该研究设计了可在实际条件下进行原位硫K边X射线吸收光谱测试的电池。结合主成分分析与约束优化的混合方法，有效解决了严重峰重叠带来的光谱解卷积难题。结果清晰揭示了放电过程的两步反应路径：硫直接还原为Li2S2，随后进一步还原为Li2S。该发现为全固态锂硫电池的机理研究提供了确凿数据。","scd":null,"kp":[]},{"i":39833,"as":"该研究在碳纤维/环氧树脂复合材料中构建了由苝二酰亚胺/氧化石墨烯（PDI/GO）异质结定制的多功能界面。通过共价键和π-π相互作用，该异质结调节了界面属性并形成电子转移通道。PDI/GO异质结表现出机械响应的荧光“关-开”行为。这种双模态自感知策略实现了复合材料结构增强与双模式损伤监测的同步，满足了结构健康监测对高灵敏度和结构兼容性的要求。","scd":null,"kp":[]},{"i":39834,"as":"该研究提出了一种氟化驱动的多位点锚固策略，利用3-氟-4-(氨甲基)吡啶铵二碘化物（3-F-AMP）作为高效钝化剂，以提升钙钛矿太阳能电池的性能。3-F-AMP的氟化作用调节了分子偶极矩并形成近乎平面的几何结构，使氟原子、质子化氨基和吡啶氮位点能够与钙钛矿表面发生协同作用。这种多位点锚固不仅有效抑制了界面缺陷的形成，还促进了电荷提取，从而制备出高效且稳定的钙钛矿太阳能电池。","scd":null,"kp":[]},{"i":39835,"as":"该研究通过介孔普鲁士蓝与聚合物聚六亚甲基双胍（PHMB）共组装，构建了多功能纳米抗菌剂mPB@PHMB，用于治疗并发耐甲氧西林金黄色葡萄球菌（MRSA）感染的烧伤创面。该纳米复合材料结合了强效的抗菌活性与调节炎症微环境的能力。在mPB固有多酶模拟活性的作用下，mPB@PHMB能够高效清除炎症微环境中的自由基，在有效杀灭多重耐药菌的同时缓解过度炎症，促进伤口愈合。","scd":null,"kp":[]},{"i":39836,"as":"该研究提出了一种通过电化学环境工程在非质子溶剂中实现电化学CO2还原制甲酸盐的新策略。通过采用解耦的质子生成方案，利用阳极寄生析氧反应产生质子，并将其受控地由阳极室传输至阴极室。该阴极使用非质子溶剂，阳极使用水溶剂。此方法无需额外添加质子溶剂，即可控制活性质子的原位传输，成功实现了在非质子介质中高选择性地生成加氢还原产物。","scd":null,"kp":[]},{"i":39837,"as":"为解决单一共价有机框架光生电子-空穴对极易复合的问题，该研究构建了由两种具有互补带隙的光敏COFs集成的杂化纳米纤维气凝胶。这种设计有效促进了界面处的杂化，使电荷转移电阻最小化，并将载流子寿命延长至7.86 ns。在加铀天然海水中，该优化材料的铀吸附容量高达1023.88 mg/g，去除率达99.99%，显著提升了光催化提铀的性能。","scd":null,"kp":[]},{"i":39838,"as":"该研究开发了一种负载多奈哌齐的氧化应激响应型纳米复合材料（RDB），采用“鸡尾酒疗法”实现阿尔茨海默病的多靶点协同治疗。该系统利用牛血清白蛋白（BSA）通过gp60受体介导的内吞作用穿透血脑屏障。在H2O2浓度升高的微环境下，RDB响应性释放药物。同时，RuO2-TPP靶向线粒体并阻断氧化应激级联反应，通过激活线粒体自噬和重塑炎症微环境，有效修复受损神经元。","scd":null,"kp":[]},{"i":39839,"as":"该研究在不含缓冲层、界面工程或有毒元素的简单二元Ge-Te体系中实现了选通管存储器（SOM）的运行。通过成分工程系统调节化学计量比，找到了一个明确的成分窗口，该窗口下的SOM器件表现出显著的极性依赖性阈值电压偏移（高达~1.5 V）。基于脉冲的电学测量揭示了不同成分下存储窗口与开态电导之间的权衡关系，为高密度、高能效的无毒元素存储器件开发提供了新平台。","scd":null,"kp":[]},{"i":39840,"as":"本文评估了在NU-1000（一种锆基多孔金属有机框架）中引入含有碱性基团的有机聚合物（聚甲基丙烯酸甲酯和聚甲基丙烯酸二甲氨基乙酯）对持久性农药苯线磷光降解的影响。研究发现，NU-1000能有效将苯线磷光氧化为仍有毒性的苯线磷亚砜，但进一步转化为无毒水解产物的效率受限且需要碱性条件。相比之下，制备的杂化材料能够有效提升持久性有机磷农药的光降解效率。","scd":null,"kp":[]},{"i":39841,"as":"本研究展示了首个采用全溶液 processed、刮涂法制备的碳顶电极的有机太阳能电池，作为传统金属电极的低成本可回收替代方案。为防止有机层受损，研究引入了坚固的电子传输层结构：包含溶液 processed的掺铝氧化锌纳米颗粒薄膜，以及在80°C下通过原子层沉积生长的20纳米厚氧化锡层。该电子传输层架构能够有效保护底层有机层免受碳顶电极溶液处理的破坏。","scd":null,"kp":[]},{"i":39842,"as":"本研究设计了一种基于金属离子的纳米系统，用于高效装载RNA并靶向递送至巨噬细胞，以治疗肝纤维化。该系统通过金属离子介导的NF-κB通路有效抑制TNF-α的产生，并调节巨噬细胞极化。此外，系统中引入的全氟碳化合物赋予了纳米载体储氧能力，从而在缺氧环境中显著提升基因递送效率。小鼠模型实验显示，该系统使TNF-α水平降低至与健康状态相当的水平。","scd":null,"kp":[]},{"i":39843,"as":"针对质子交换膜燃料电池中Fe-N-C氧还原催化剂因微孔主导而引起的严重氧传输阻力和电极溢流问题，研究提出一种形态工程策略。通过构建由超薄纳米片堆叠而成、具有分级多孔结构的纳米花状Fe-N-C催化剂，解决了上述瓶颈。电子显微镜和压汞法证实，该独特结构具有互联的超薄纳米片和丰富的大孔，共同建立了高效的气体传输通道，有效缓解了氧传输阻力。","scd":null,"kp":[]},{"i":39844,"as":"研究系统调查了沉积在平坦和微结构掺杂硅表面的二氧化钛、特氟龙、金刚石、氮化硼和氧化铝等超薄介电纳米涂层。实验测量与理论模型表明，这些纳米涂层不仅能保留甚至能增强硅表面在250纳米至20微米宽频带上的发射率，同时对润湿性提供广泛控制。其中，金刚石涂层表面在中红外波段表现出最高的宽带发射率和角度各向同性。","scd":null,"kp":[]},{"i":39845,"as":"本研究利用原位扫描光电子显微镜和微聚焦X射线光电子能谱技术，揭示了二硫化钼（MoS2）检测二氧化氮（NO2）的关键微观机制。通过对比离子喷射沉积生长的MoS2薄膜和剥离的单层MoS2化学传感器，研究发现MoS2的形貌、缺陷和厚度会影响电荷重新分布。这种动态电荷重新分布是导致NO2检测过程中电阻变化的核心机制。","scd":null,"kp":[]},{"i":39846,"as":"研究提出了一种解释振动强耦合（VSC）效应的宏观凝聚理论。实验表明，在光学微腔中放置分子集合体可以在无光源条件下改变基态化学反应速率。由于VSC具有多体性质，现有聚焦于单激发图像的理论难以解释相关现象。新理论指出，当集体拉比分裂超过阈值并表现出类似相变的行为时，VSC效应可以通过形成宏观凝聚态来解释反应速率常数和平衡常数的改变。","scd":null,"kp":[]},{"i":39847,"as":"现有单次光谱系统在光谱带宽、分辨率和采集速度之间存在固有不兼容性。本研究引入了一种可重构的单次光谱方法，实现了对光谱带宽、分辨率和采集速度的完全可编程控制，达到了86飞米的超高分辨率。该技术能够单次捕获完整的瞬态事件，为生物医学诊断、环境监测、材料应力分析和电信网络波动检测等领域的快速及非重复过程提供了关键见解。","scd":null,"kp":[]},{"i":39848,"as":"研究提出了一个定量框架，用于建模靶向蛋白降解（TPD）的细胞作用机制，并利用实际可获取的参数预测其细胞功效。将该模型应用于41个靶标的已发表数据，揭示了TPD过程特征的降解速率范围（0.1至10 min−1）。该定量方法定义了靶标降解倾向的全景图，证明了蛋白降解率受靶标半衰期和E3连接酶水平等关键因素的共同影响，为降解剂优化提供了路线图。","scd":null,"kp":[]},{"i":39849,"as":"利用美国森林清查数据和基于卫星的稳定性评估，研究探索了森林如何抵抗和恢复复合极端气候，以及树木多样性如何调节这些反应。复合极端气候（如同时发生的高温和干旱或水分过量）会导致比单一极端气候更低的森林抵抗力和恢复力，表现出协同效应并造成更大的负面影响。其中，复合高温和干旱的破坏力略强于复合高温和水分过量。更高的树木多样性能够显著缓冲复合极端气候对森林生态系统的负面影响。","scd":null,"kp":[]},{"i":39850,"as":"人类疱疹病毒复制依赖于必须从无活性单体转变为活性二聚体的病毒蛋白酶。研究分离出一种构象选择性抗体Fab5，2.6埃的冷冻电镜结构显示，Fab5结合在远离活性位点和二聚界面的“锁扣环”上，固定二聚体中的C端尾部。针对HCMV和KSHV蛋白酶的结构导向突变证实，β-和γ-疱疹病毒蛋白酶锁扣环中存在的3残基基序具有关键功能作用，验证了破坏该锁扣环是有效的抗病毒策略。","scd":null,"kp":[]},{"i":39851,"as":"转录因子ERG是内皮特性的关键调节因子。研究发现，在高胆固醇血症小鼠中诱导性敲除内皮细胞中的Erg会增加斑块负荷。谱系追踪和单细胞转录组学显示，ERG缺失导致内皮细胞去分化、获得间充质命运，并促进内皮-间质转化细胞在斑块内迁移和扩张，与促动脉粥样硬化细胞发生相互作用。此外，ERG缺失还导致屏障功能早期破坏，促进脂质摄取和泡沫细胞积累，加速动脉粥样硬化进程。","scd":null,"kp":[]},{"i":39852,"as":"研究结合生物正交非经典氨基酸标记（BONCAT）、荧光激活细胞分选（FACS）和宏基因组学，评估了农药多样性对土壤中活跃微生物群抗生素抗性基因（活跃ARGs）的影响。结果表明，与未处理对照组相比，无论是低还是高农药多样性均显著增加了活跃ARG的丰度。农药多样性以不同的机制驱动了土壤中活跃抗生素抗性基因的富集，促进了抗性基因在土壤中的传播。","scd":null,"kp":[]},{"i":39853,"as":"研究绘制了利什曼原虫在不同宿主生命周期中的2'-O-甲基化图谱，发现两个在生命阶段差异修饰的位置由小核仁RNA（snoRNA）指导沉积。通过对负责指导修饰Am479的snoRNA进行胞嘧啶碱基编辑，未检测到缺乏该修饰的核糖体，表明此修饰是必需的。通过解析过表达该指导snoRNA的细胞的核糖体冷冻电镜结构，并与亲本细胞对比，揭示了snoRNA决定的翻译核糖体的结构与功能机制。","scd":null,"kp":[]},{"i":39854,"as":"研究发现玉米中所有七个阿糖酸脱水酶（ADTs）均特异性定位于叶绿体中的质体小球，且ADT2.2对阿糖酸和预苯酸具有高催化活性，确立了质体小球是苯丙氨酸合成场所。遗传分析证实仅ADT2.2对植物和种子发育不可或缺，其缺失会导致种子中苯丙氨酸严重缺乏。这种代谢阻断直接降低了tRNA的充电水平，从而抑制蛋白质翻译，并引起翻译稳态机制发生重组。","scd":null,"kp":[]},{"i":39855,"as":"利用组织透明束描成术、电生理学和双光子成像技术，研究在小鼠觅食任务中识别出一种具有单次测试精度的编码奖赏的小脑机制。浦肯野细胞的同步活动触发了小脑深核中短暂的群体静默（IPS）。IPS在奖赏后100毫秒出现，随奖赏预测误差进行缩放，并诱导腹侧被盖区多巴胺神经元的反弹相位放电。这种高时间精度的群体动态介导了多巴胺奖赏信号，确保了奖赏预测和行为的快速适应。","scd":null,"kp":[]},{"i":39856,"as":"研究报道了接近生物合成末端的天然人源细胞质RNA聚合酶II（Pol II）的综合结构分析。该复合物包含Gdown1以及三种生物发生因子RPAP2和小GTP酶GPN1、GPN3。冷冻电镜分析揭示了Gdown1和RPAP2如何与Pol II结合并阻止转录因子的过早结合。研究进一步阐明了RPAP2如何将GPN1-GPN3系于复合物上，以及组装因子如何协同完成这一核心多亚基酶在细胞质中的装配过程。","scd":null,"kp":[]},{"i":39857,"as":"研究证实了两种仅存在三个氨基酸差异的NADPH依赖型苯甲醛还原酶负责在矮牵牛花中形成苯甲醇及其下游衍生物（苯甲酸苄酯和水杨酸甲酯）。该发现解开了植物中苯甲醇合成酶未知之谜，阐明了苯甲醇生物合成及其亚细胞区室化在植物香味形成和苯丙氨酸依赖途径中合成植物激素水杨酸的关键作用。此外，下调苯甲醛还原酶的表达显著减少了这些化合物的生成。","scd":null,"kp":[]},{"i":39858,"as":"鳞状细胞癌中EZH2表达上调但PRC2催化的H3K27me3标记却显著减少。机制上，致癌Ras信号传导导致PRC2亚基EED降解，破坏了PRC2的稳定性并耗竭了H3K27me3。EED的丢失使角质形成细胞重编程为侵袭性的肿瘤特异性细胞状态，并诱导旁分泌因子重塑肿瘤微环境。这一发现揭示了致癌Ras通过诱导EED降解和PRC2功能障碍，从而促进侵袭性鳞状细胞癌发展的分子机制。","scd":null,"kp":[]},{"i":39859,"as":"NIMA相关激酶1（NEK1）无义突变是肌萎缩侧索硬化症（ALS）的风险变异。研究证明，源自ALS相关NEK1无义突变的三种截断型蛋白从细胞质转位至细胞核，定位于核仁并形成液态核质灶。与野生型NEK1的弥散分布不同，这些截断突变体在细胞内外均易发生液-液相分离。机制上，截断的NEK1s通过相分离相互作用，阻碍核糖体RNA的生物合成，最终驱动运动功能障碍。","scd":null,"kp":[]},{"i":39860,"as":"本研究通过单细胞RNA测序和T细胞受体测序，分析了输卵管中组织驻留记忆样T细胞（TRML）。研究发现，输卵管来源与肿瘤浸润的TRML之间存在显著的克隆重叠（18.4%），且这些共享克隆型主要富集于耗竭的CD8+ T细胞亚群中。功能分析证实，输卵管中的TRML能够识别自身肿瘤抗原，揭示了输卵管在预防高级别浆液性卵巢癌中的免疫监视作用。","scd":null,"kp":[]},{"i":39861,"as":"研究开发了基于BERT架构的血浆蛋白质组学预训练模型ProLM。该模型在15,499名健康参与者的数据上完成预训练，能够捕获基线蛋白质表达关系并预测16种常见慢性疾病。经过微调后，ProLM衍生的蛋白质组学风险评分在预测全部16种疾病时优于年龄+性别模型，在14种疾病中优于心血管疾病风险方程，在11种疾病中优于35变量临床面板评分。模型还成功识别出GDF15等表达变化早于临床诊断15年以上的关键蛋白质。","scd":null,"kp":[]},{"i":39862,"as":"研究发现肝细胞癌（HCC）微环境中的调节性T细胞会激活Nrf2信号通路。正常肝脏中的Treg代谢不活跃且易凋亡，而富含乳酸的肿瘤微环境会激活Nrf2，将氧化还原稳态与线粒体功能偶联，从而促进Treg的代谢活性、存活和免疫抑制功能。通过特定基因敲除导致Nrf2功能丧失，可以削弱Treg的抑制功能，表明靶向Nrf2通路是逆转肿瘤免疫抑制微环境的有效策略。","scd":null,"kp":[]},{"i":39863,"as":"本研究通过随机对照试验探究了全基因组多基因风险评分（PS）与饮食干预减重的交互作用。研究从38,621名基因型个体中筛选出BMI遗传易感性极高和极低的前5%人群，共223名参与者接受了为期6个月的结构化饮食指导或对照干预。研究旨在验证不同遗传倾向的个体在饮食干预下的BMI变化差异，为基于遗传背景的个性化体重管理提供确切的临床证据。","scd":null,"kp":[]},{"i":39864,"as":"研究发现跨膜蛋白141（TMEM141）是代谢相关脂肪性肝炎（MASH）及其相关纤维化的关键调节因子。在MASH患者和模型中，TMEM141表达因微小RNA-149增加而降低。实验表明，肝细胞中特异性敲除TMEM141可抵御高脂/胆固醇/果糖饮食诱导的MASH，而过表达人类TMEM141则会加剧病情。机制上，TMEM141定位于线粒体内并与线粒体复合物I相互作用，调控ROS-HNF4α信号通路。","scd":null,"kp":[]},{"i":39865,"as":"研究评估了统计与深度学习方法在心力衰竭目标试验模拟（TTE）中控制混杂偏倚的能力。针对射血分数降低的心衰患者，研究采用倾向评分匹配、逆概率加权、目标最大似然估计和Transformer深度学习四种方法，模拟了β受体阻滞剂和地高辛的疗效。结果表明，没有任何一种方法能够重现随机对照试验（RCT）的基准结果，所有方法均提示β受体阻滞剂呈中性或有害效应，证实观察性研究中的适应症混杂偏倚难以被高级算法完全消除。","scd":null,"kp":[]},{"i":39866,"as":"研究结合交联质谱、定量蛋白质组学、计算工具和冷冻电镜技术，解析了巨型病毒（Melbournevirus）完整颗粒的蛋白质架构。研究将88种病毒蛋白定位到不同的病毒颗粒亚区室，并提出了25种内膜蛋白的拓扑结构。同时，研究在冷冻电镜数据中分配了8个衣壳组件，包括将衣壳外壳与膜结合的蛋白。该工作揭示了巨型病毒复杂的内部组装机制和结构特征。","scd":null,"kp":[]},{"i":39867,"as":"受珊瑚群落的多级协作机制启发，研究开发了一种搭载工程菌的核壳结构仿生微胶囊反应器（MY-E@SS）用于治疗炎症性肠病（IBD）。该仿生多功能外壳能保护工程菌安全通过胃肠道，到达发炎的肠道部位后，工程菌感知病理微环境并响应性释放抗炎肽。在雄性小鼠IBD模型中，该系统展现出优异的生物安全性和治疗效果，有效克服了传统益生菌疗法在胃酸存活率、肠道定植效率和靶向性方面的局限。","scd":null,"kp":[]},{"i":39868,"as":"研究偶然发现了一类新型核酶连接酶，其只有在RNA底物的亲核2'-羟基旁存在相邻的3'-磷酸基团时，才能催化该底物的2'-羟基攻击自身的5'-三磷酸基团。这种对3'-磷酸基团的依赖性类似于基于蛋白质的RNA修复酶机制。研究表明，由核酶催化的3'-磷酸化RNA连接反应，为原始细胞中的RNA修复提供了一条可行的演化路径。","scd":null,"kp":[]},{"i":39869,"as":"研究基于美国加州中部的1691份调查数据，探讨了影响海洋接触及其对人类福祉贡献的因素。结果显示，海洋对人类主观和关系层面的福祉贡献大于物质层面的贡献。然而，缺乏兴趣或经济承受能力、基础设施不足或污染暴露，以及相关知识匮乏等个人、环境和知识壁垒，限制了弱势群体获取这些海洋红利。研究强调了公平获取海洋资源对于提升公众福祉的重要性。","scd":null,"kp":[]},{"i":39870,"as":"研究提出了一种基于三明治架构的全柔性热电发电机（f-TEG），可用于自供电手势识别。该器件采用n型Bi2Te2.7Se0.3和p型Bi0.5Sb1.5Te3作为热电单元，以液态金属为电极，免去了传统表面金属化和复杂焊接工艺。为提高热导率，封装层采用了掺入20wt%氮化铝陶瓷纳米颗粒的PDMS复合材料，实现了0.45 W m-1 K-1的热导率。该器件能够有效收集人体低品位废热，为可穿戴设备提供持续动力。","scd":null,"kp":[]},{"i":39871,"as":"研究结合环南极表面色素数据集与卫星海洋颜色观测，开发了南大洋诊断色素框架，解析了1998至2024年间春季和夏季的浮游植物群落组成。对比1998-2014年与2015-2024年两个时期（以9月海冰范围骤降约7%为界）发现，在受海冰影响的海域，春季硅藻对总叶绿素的贡献增加了约10%，而在南极地区则减少了最多约3%。研究揭示了南大洋表面浮游植物群落组成发生了显著的区域性分岔趋势。","scd":null,"kp":[]},{"i":39872,"as":"研究开发了一种不穿透神经组织、可贴合在脊髓表面的超薄环状电极阵列。在自由活动的大鼠短期植入实验中，该阵列利用深度学习解码器，通过提取与中枢模式发生器节律一致的低频脊髓振荡，实现了高达R²=0.97的运动意图解码准确率，并以94.4%的准确率分类了八种感觉模式。在急性麻醉猪的跨物种验证中，该接口同样表现出优异的信号记录与解码能力，证明其能同时实现运动、躯体感觉和内脏感觉的监测。","scd":null,"kp":[]},{"i":39873,"as":"针对观测数据存在噪声、高维和多尺度特性导致方程发现困难的问题，研究提出了一种结构化算子学习框架。该框架将方程发现重构为约束动态推断问题，集成了谱分解、物理引导的稀疏投影和跨视图一致性正则化。通过将动力学分解为尺度解析组件，并在统一架构内强制执行扰动物观测的不变性，该框架能够直接从混乱且充满噪声的观测数据中提取出具有物理可解释性的确定性动力学方程。","scd":null,"kp":[]},{"i":39874,"as":"研究发现了控制复杂网络动态渗透过程的强健时间自相似现象。通过追踪增量生长事件的完整统计数据，研究揭示了碎裂动力学由两个独立的Fisher型临界指数（τc和τs）控制。这两个指数独特地表征了系统的普适类，通过新建立的标度关系可以推导出所有其他标准临界指数。该框架在经验网络上得到了严格验证，为理解复杂系统中的灾难性碎裂和结构转变提供了理论基础。","scd":null,"kp":[]},{"i":39875,"as":"电催化C-N偶联合成尿素是一项绿色技术，其催化剂性能评估依赖于尿素的精准定量。常规方法通过脲酶将尿素分解为铵根离子（NH4+）并计算浓度增量来实现定量。然而研究发现，所有四种市售脲酶均存在NH4+杂质，会导致尿素浓度的假阳性误判。即使使用杂质含量最低的脲酶，其产生的假阳性尿素生成速率也过高。这一发现揭示了现有电催化尿素定量方法中存在的严重系统性误差风险。","scd":null,"kp":[]},{"i":39876,"as":"为研究非铱催化剂在酸性析氧反应中的双位点协同机制，研究将Cu、Mn、W等金属掺入RuO2中。结合原位表征和理论模拟发现，Mn掺杂增强了Ru-O轨道耦合并建立单向电子转移，导致高压下Ru过氧化并加速性能衰减。相反，W掺杂调节了Ru和O的带中心，降低了轨道重叠，减弱了Ru-O共价键，实现了双向电子转移。该研究阐明了掺杂剂介导相邻活性中心电荷转移的具体机制及其对催化活性和稳定性的影响。","scd":null,"kp":[]},{"i":39877,"as":"研究利用具有可调层间阳离子的蛭石基二维纳米通道，探讨了离子对纳米受限水传输的调节作用。结果表明，包含强水合离子的膜尽管层间距更大，但水传输速度明显减慢；而弱水合离子则能实现超快渗透。红外光谱证实，离子会引起氢键网络的重组。强水合离子会破坏水分子间的氢键网络，增加水传输的能垒。该研究揭示了离子与水相互作用重塑氢键网络从而调控纳米尺度水流的具体物理机制。","scd":null,"kp":[]},{"i":39878,"as":"研究通过施加外延剪切应变，在WO3外延薄膜中成功诱导出极性相。这种应变稳定了低对称性的三斜结构，该结构在较大的薄膜厚度和较高温度下依然稳定存在。在原子尺度上，氧八面体倾斜模式的改变促进了这种对称性降低，进而导致宏观极性相和抗畸变极化子的出现。该研究证实了利用外延应变在二元氧化物中实现新颖极性物态和电子功能的有效性。","scd":null,"kp":[]},{"i":39879,"as":"研究通过调节手性反铁磁体Mn3Sn的磁层厚度，观察到了其自旋轨道力矩（SOT）开关行为的跨模态转变。在较厚的器件中，显著的焦耳热会破坏磁序并干扰状态切换；而随着厚度减小，器件表现出清晰的本征自旋轨道力矩切换特征，避免了热效应的干扰。该研究成功区分了反铁磁序切换中的本征机制与温度辅助机制，为开发基于反铁磁材料的皮秒级超快、低功耗下一代存储器件提供了关键参数支撑。","scd":null,"kp":[]},{"i":39880,"as":"受Eshelby夹杂理论指导，研究团队通过增材制造与定制后处理，在超细晶NiCoCr基多主元合金中构建了新型分层纳米有序（HNO）结构。该结构包含约70nm的非共格σ弥散相、双峰共格L12析出相（约5nm和26nm）以及局部化学有序（约0.7nm），成功使该低温合金同时实现了2.0 GPa以上的超高屈服强度和优异的均匀延伸率，打破了强塑性的传统权衡限制。","scd":null,"kp":[]},{"i":39881,"as":"研究人员利用胶束插层技术，成功在金纳米棒和三角纳米棱镜等各向异性等离激元纳米颗粒表面实现了导电聚合物（聚吡咯，PPy）斑点的位点选择性定位。该位点选择性由纳米颗粒局部曲率和十二烷基硫酸钠(SDS)浓度共同控制。此外，通过HCl掺杂可以调控PPy与Au界面处的电荷转移，克服了传统合成策略依赖含硫醇配体的局限。","scd":null,"kp":[]},{"i":39882,"as":"基于中性原子阵列的可编程量子模拟器为研究量子自旋液体提供了平台。研究采用射影对称群框架，描述了在红宝石晶格里德堡阵列中合成的Z2量子自旋液体（QSL）的对称性分数化模式。通过系统比较所有可能平均场猜想的静态结构因子与密度矩阵重整化群计算结果，精准识别了微观层面实现的Z2 QSL候选态，并详细分析了其动态结构因子以供未来实验参考。","scd":null,"kp":[]},{"i":39883,"as":"研究团队开发了一种基于(Bi,Sb)2Se3半导体的高效超柔性光电刺激器（OES）。该半导体特殊的平行一维链晶体结构赋予了器件出色的柔性与光生载流子传输能力。该OES能在低至0.55 μW cm−2的近红外光强下实现稳定的光电转换，有效克服了组织衰减导致的弱光激发难题，为通过光电电子学进行心脏重塑提供了新的技术途径。","scd":null,"kp":[]},{"i":39884,"as":"结合聚焦离子束制备与原位球差校正透射电镜技术，研究团队对定向二维Bi2O2Se纳米器件进行了电学探测和实时结构演变成像。配合密度泛函理论（DFT）计算证实，O2-和Se2-离子的各向异性迁移势垒导致了面内和面外器件截然不同的电学行为与阻变特性，揭示了二维忆阻技术中晶体学各向异性主导离子迁移的原子级机制。","scd":null,"kp":[]},{"i":39885,"as":"为解决冶金学中原子扩散导致塑性变形的表征难题，研究提出了一种高分辨率、高通量的局部变形映射（LDM）技术。该技术通过将纳米模具压入微结构形成纳米柱阵列来表征局部扩散变形。该方法能够在宏观面积（约平方厘米）上实现约10 nm²的分辨率，并在单次实验中生成高达约10¹²个数据点，实现了空间塑性响应与微结构的分离与高灵敏化学成分分析。","scd":null,"kp":[]},{"i":39886,"as":"由α-磷酸三钙合成的缺钙羟基磷灰石（CDHA）纳米柱表现出针对革兰氏阳性枯草芽孢杆菌的接触杀菌活性。利用同步辐射 cryo-软X射线断层扫描和光谱显微镜技术，研究在亚细胞分辨率下观察了完全水合细菌的超微结构和细胞内离子变化。暴露于纳米形貌的细菌出现细胞膜破裂、细胞质泄漏和多泡体形成，证实CDHA除了造成机械损伤外，还能通过与环境进行离子交换产生化学相互作用。","scd":null,"kp":[]},{"i":39887,"as":"研究团队在氮化镓光声子混合集成平台上，基于布里渊散射的斯托克斯和反斯托克斯过程，成功实现了单向行波声子参量放大。该研究填补了声子集成电路（PnICs）中基于行波集成波导的声子参量放大器空白，为经典与量子域的纳米级声子控制和高级信号处理提供了关键的有源器件支撑。","scd":null,"kp":[]},{"i":39888,"as":"原位同步辐射X射线纳米衍射表明，在1.5×10³ A cm−2的电流密度下，六方η-Cu6Sn5相能够被稳定保留，而在同等温度的热处理下该相通常会转变为η′相。保留的η相通过各向异性弹性畸变来适应电流，其c轴膨胀约1.3%，基面收缩约0.8%，并伴随平面选择性的位错重排，撤去电流后出现部分晶格恢复，证实稳恒电流可作为稳定金属晶体结构的热力学场。","scd":null,"kp":[]},{"i":39889,"as":"由手性材料Co1/3TaS2和非磁性范德华铁磁体Fe3GeTe2组成的全范德华异质结构，表现出源自界面手性的两种不同且非传统的自旋轨道转矩。这些由结构手性引起的界面效应，使垂直磁化能够在无外加磁场条件下实现翻转，且所需电流密度极低（约10^6 A/cm²），显著提升了能量效率。","scd":null,"kp":[]},{"i":39890,"as":"研究提出了一种拓扑晶格收缩策略，成功合成了具有高孔隙率、高结晶度和相纯度的多孔单晶闪锌矿ZnO整体材料。原位透射电镜揭示了其原子级形成过程：{222}通道内S/O的优先迁移促发了外延成核，界面应变则导致空位聚集成互联纳米孔。ZnO极低的缺陷密度有效抑制了光生载流子的快速复合，从而大幅提升了甲烷光氧化反应的效率。","scd":null,"kp":[]},{"i":39891,"as":"为解决全波仿真计算成本高导致AI电磁模型训练数据严重稀缺的问题，研究引入了超电路嵌入表面（MCES）框架。该框架由固定结构拓扑和可通过集总元件实现的柔性超电路组成，将设计重心从全波仿真转移到电路级建模。利用笔记本电脑即可轻松生成超过600万个样本，结合开发出的正反向AI设计方法，实现了在频率和振幅上丰富的多功能电磁设计能力。","scd":null,"kp":[]},{"i":39892,"as":"为解决弹热制冷再生器中相变不均匀问题，研究受针叶树结构启发，设计出一种多层针叶状弹热制冷再生器。该设计通过改变三层管道的数量以匹配材料固有的相变应力分布，有效缓解了过应力与不完全相变。在使用同种商用NiTi材料的情况下，该再生器实现了45.5 K的无负载温度跨度，比均匀结构基准高出12.4%，并在往复式弹冷水机中验证了其可扩展性。","scd":null,"kp":[]},{"i":39893,"as":"利用大体积（约60 mm³）超高纯铈样品进行的中子衍射研究表明，高压下形成的晶体结构取决于压缩路径。在室温下慢速压缩（约0.25 GPa/小时）会形成正交相，揭示了动力学路径和微观结构继承性对固体高压相选择的强烈影响。这一发现纠正了以往认为固体在压力下仅反映热力学平衡态的假设，解释了数十年来关于铈高压晶体结构的矛盾报道。","scd":null,"kp":[]},{"i":39894,"as":"通过对海量沉积物数据集进行空间分析，研究发现在地球历史上六次最大规模的冰河期中，高纬度海洋沉积物的锰浓度存在普遍的相对富集模式，而热带沉积物中的锰浓度相对较低。这种明确的纬度锰梯度分布动力学表明，极端冰川作用与氧化事件协同引发了全球锰元素地球化学循环的重大扰动。","scd":null,"kp":[]},{"i":39895,"as":"为开发针对呼吸道合胞病毒（RSV）感染的体外治疗筛选模型，研究发现重症RSV感染儿童的重症监护病房外周血中性粒细胞中髓过氧化物酶（MPO）水平显著升高。为此，研究建立了一个整合了儿童气道上皮细胞、内皮细胞和成人中性粒细胞的气液界面（ALI）系统，成功再现了血气道屏障，为模拟RSV感染的中性粒细胞活化等临床反应和体外治疗筛选提供了功能生物标志物及可靠模型。","scd":null,"kp":[]},{"i":39896,"as":"针对高级别浆液性卵巢癌的异质性，研究探讨了在四周内整合多达11种技术（涵盖DNA、RNA、蛋白质和功能分析）对血液、单细胞及bulk肿瘤组织、恶性腹水进行全面分子图谱分析的可行性。多模态分子分析改变了76%患者的假定治疗建议，且多组学指导下的维持治疗延长了部分患者的总生存期。同时发现腹水来源单细胞与实体瘤具有截然不同的细胞和分子特征。","scd":null,"kp":[]},{"i":39897,"as":"研究揭示了界面流变学在控制界面聚合反应中的关键作用，这是制造聚酰胺（PA）海水淡化膜的黄金标准。通过利用光反应性两亲分子精确调节油水界面的界面流变性能，研究人员成功控制了聚合过程中的流体不稳定性及膜表面形貌。基于此物理结构化策略制造的PA膜在脱盐性能上展现出宏观尺度的显著提升。","scd":null,"kp":[]},{"i":39898,"as":"为解决水系锌空气电池中锌负极存在的枝晶生长、析氢和腐蚀等问题，研究在电解液中引入四氟硼酸铟作为功能性添加剂。原位构建的锌铟动态合金界面有效调控了锌的成核行为并促进了均匀沉积，显著抑制了枝晶形成。该动态合金界面同时参与了高度可逆的沉积溶解过程，大幅提升了电池的界面稳定性，实现了超高可逆的锌空气电池。","scd":null,"kp":[]},{"i":39899,"as":"为探究糖基磷脂酰肌醇（GPI）及其锚定蛋白在细胞膜界面的构象，研究使用带有叠氮和生物素标签的双功能GPI探针，结合自旋标记和功率饱和电子顺磁共振（EPR）深度分析技术，量化了探针在POPC和DPPC脂质体中对膜束缚及可溶性弛豫剂的可达性。结果显示，GPI及GPI锚定蛋白在脂质双分子层中表现出截然不同的、依赖于物相的特异性朝向。","scd":null,"kp":[]},{"i":39900,"as":"本研究提出了一种利用铁草酸盐光催化实现未活化酮与未活化烯烃直接分子间还原偶联的策略。传统酮烯烃偶联局限于分子内或活化底物，该催化平台通过内层还原将酮转化为羟自由基，有效克服了极性不匹配问题，成功实现了未活化底物间的Csp3-Csp3键构建。","scd":null,"kp":[]},{"i":39901,"as":"淀粉样低聚物是阿尔茨海默症等神经退行性疾病中最具毒性的物种。研究团队利用交联自旋标记电子自旋共振技术发现，在洗涤剂胶束中，淀粉样圆柱蛋白肽K11V从六聚体增加到八聚体。结合AlphaFold模拟证实，具有β桶结构的八聚体表现出类似洗涤剂的毒性机制，能够直接从生物膜中抽取脂质。","scd":null,"kp":[]},{"i":39902,"as":"为了非侵入性地实时探究肿瘤光动力治疗预后机制，研究人员提出了一种“时空异步”探针设计策略，并开发了HD-LN双模态探针。该探针能够进行无串扰的荧光和光声双模态成像。在具体机制上，HD-LN首先被肿瘤高表达的亮氨酸氨基肽酶（LAP）激活，从而开启荧光信号并恢复检测能力，实现对肿瘤光疗后中性粒细胞募集的实时精确监测。","scd":null,"kp":[]},{"i":39903,"as":"结构电池致力于将能量存储与机械承载功能融合于单一材料系统中，为轻量化电气化提供了全新范式。该文章阐述了推动结构电池从实验室概念可行性走向实际部署应用所需的科学与工程发展路线图。","scd":null,"kp":[]},{"i":39904,"as":"硅负极在充放电过程中的体积膨胀严重制约了高能量密度和快充锂离子电池的发展。本研究引入了一种具有机械互锁交联的聚丙烯酸粘合剂，通过拓扑驱动的分子运动均匀耗散电极应力。该设计有效维持了电极在压延和循环过程中的表面孔隙率和结构完整性，实现了高电极密度下的稳定运行并显著提升了快充性能。","scd":null,"kp":[]},{"i":39905,"as":"","scd":null,"kp":[]},{"i":39906,"as":"热带巨型树木龙脑香树的水分运输系统在进化过程中，已经演化出克服重力效应和抵御水分胁迫的能力。","scd":null,"kp":[]},{"i":39907,"as":"十位《自然》杂志的贡献者分享了他们当前的读书爱好和推荐的暑期阅读书目。","scd":null,"kp":[]},{"i":39908,"as":"参与慈善机构的志愿服务工作能够为科研工作者带来实际的职业益处，并帮助他们建立有价值的社交联系。","scd":null,"kp":[]},{"i":39909,"as":"宽带隙混合卤化物钙钛矿在光照射下易发生卤化物偏析，限制了钙钛矿-有机叠层太阳能电池的性能。研究通过在前驱体溶液中引入光可转化添加剂TDB建立两阶段稳定策略：结晶阶段，TDB抑制富溴相沉淀并加速卤化物混合；光照运行期间，TDB发生转化形成新物质以稳定结构，有效提升了电池性能。","scd":null,"kp":[]},{"i":39910,"as":"近期研究在La-Sc-H高压系统中发现了室温超导现象。研究团队利用机器学习加速晶体结构预测，在250 GPa下识别出一系列亚稳态三元氢化物，并发现Fm3¯m La2ScH36结构与实验中观察到的未知次相相符。第一性原理计算表明，化学计量的La2ScH36是潜在室温超导体，临界温度Tc高达369-412 K，而考虑结构稳定性的缺氢次相La2ScH36-x同样具有超导潜力。","scd":null,"kp":[]},{"i":39911,"as":"一篇经过详尽研究的记录阐述了临床试验如何彻底改变了健康和社会政策，并回顾了推动循证医学崛起的特立独行者们的历史贡献。","scd":null,"kp":[]},{"i":39912,"as":"微生物学家Linda Guamán致力于为国家服务，却卷入了一场政治争议。她因此遭到逮捕并面临数年监禁，在有关COVID-19检测的问题上经历了长达四年的法庭诉讼战。","scd":null,"kp":[]},{"i":39913,"as":"","scd":null,"kp":[]},{"i":39914,"as":"","scd":null,"kp":[]},{"i":39915,"as":"","scd":null,"kp":[]},{"i":39916,"as":"磁性斯格明子是拓扑保护的自旋结构，可作为信息载体。本研究设计了一种由CoB和CoFeB两种不同铁磁体构成的人工反铁磁体。由于外场和层间交换作用对子晶格的不对称影响，系统在不同磁场下产生了两种斯格明子：大磁场下的常规极性斯格明子和小磁场下的反向极性斯格明子。这一发现通过X射线磁强测定技术得到了证实。","scd":null,"kp":[]},{"i":39917,"as":"天文学家在太阳系外发现了包含四个碳原子的赤藓酮糖。这是目前在太空中探测到的结构最复杂的“真糖”分子，该发现为探索生命起源提供了重要线索。","scd":null,"kp":[]},{"i":39918,"as":"为揭示月球远端与近端不对称性的起源，研究分析了中国嫦娥六号（CE6）从月球背面采集的岩石样本。地球化学数据显示，CE6斜长岩更富镁，且其镁套样品的钾、稀土元素和磷（KREEP）含量低于近端同类样品。通过对比月壳不同区域的岩性差异，该研究为了明月球岩浆洋（LMO）凝固过程中的不对称形成机制提供了关键线索。","scd":null,"kp":[]},{"i":39919,"as":"电化学氧化脱氢（ODH）在化学制造中面临生产速率慢的挑战。本研究通过选择性浸出NiV层状双氢氧化物中的钒离子，制备出富含金属空位的Ni(OH)2。实验与计算表明，催化剂中的金属空位提高了Ni-O基团中氧的氧化还原活性，加速了有机分子的亲核ODH过程。该催化剂在生物质衍生物的电化学转化中表现出显著提升的效率。","scd":null,"kp":[]},{"i":39920,"as":"精确控制复杂拓扑结构的机械互锁分子组装是一项重大挑战。本研究通过调控配体配位角度，设计了具有不同咔唑-吡啶连接角度的配体，并将其与特定结构单元结合。研究成功定向合成了四种独特结构：分子镊子状化合物、雪花状折叠组装体、818节点分子结和闭环三链结构。单晶X射线衍射分析证实，配体角度决定了最终的复杂三维拓扑几何构型。","scd":null,"kp":[]},{"i":39921,"as":"锂硫电池具有高能量密度的潜力，但受限于多硫化物的穿梭效应和缓慢的硫氧化还原动力学。电催化是加速多硫化物转化的有效策略，其中金属-氮-碳催化剂表现出特殊的吸引力。尽管已知配位环境和氮种类（如吡啶氮或吡咯氮）对催化活性有重要影响，但不同配体结构与硫还原机制之间的具体关系仍有待阐明。该研究报告了相关碳材料中初级壳层氮的调控策略以增强电催化性能。","scd":null,"kp":[]},{"i":39922,"as":"杂原子身份对生物活性分子的理化性质影响深远。为避免繁杂的从头合成，本研究开发了一种直接骨架编辑策略，通过简单的一锅法两步反应，将易得的氧杂环丁烷转化为氮杂环丁烷。该反应在路易斯酸介导下进行分子间氨解，随后发生分子内脱水环化，具有底物范围广、官能团耐受性优异的特点，实现了高效的非氧化还原骨架编辑。","scd":null,"kp":[]},{"i":39923,"as":"有机硼酸酯是多组分成键的多功能平台，但通过亲电氨基化诱导的1,2-硼酸酯迁移一直未获突破。本研究开发了一种模块化且具有高非对映选择性的方案，实现了烯基硼酸酯络合物的直接氨基化1,2-迁移，成功合成无保护基的β-氨基硼酸酯。该反应利用商用胺化试剂DPPH，通过快速形成氮丙啶鎓离子并发生1,2-迁移完成，原位红外光谱和密度泛函理论为其提供了机理支持。","scd":null,"kp":[]},{"i":39924,"as":"研究人员正在通过重写DNA和染色质上的化学标签来调节基因表达，这项技术被称为表观遗传编辑。","scd":null,"kp":[]},{"i":39925,"as":"本研究开发了一种结合有机催化和生物催化的级联反应，能将易得的醛转化为具有对映选择性的手性β-氯胺。该反应在近中性条件下进行，产率高达88%，对映体比例超过99:1。当将体系pH值调节至9.5时，该系统可直接生成手性氮丙啶，实现了通过单一平台利用pH值控制获取两类高附加值产物。","scd":null,"kp":[]},{"i":39926,"as":"本研究提出了一个机理框架，用于解释在铜催化剂上进行电化学二氧化碳还原（CO2RR）时，C2+产物形成中CO覆盖度与反应级数之间的矛盾。研究发现，铜表面具有位点异质性，OC-CO耦合反应主要发生在对CO具有强亲和力的高活性“少数位点”上，而大部分铜表面位点相对惰性。分子抑制剂的相关性表明，这些CuCO位点很可能位于高曲率的纳米结构上。","scd":null,"kp":[]},{"i":39927,"as":"本研究通过高发射率的9-π延伸蒽的[4+2]光二聚反应，合成了一种新型光力探针（OFP）。该探针在200°C以上具有优异的热稳定性，并在商业热塑性聚合物（如PMMA、PS、TPU和PE）中以低于5%的负载量实现了力化学激活。实验证明，功能化的TPU在熔融加工后仍保持稳定的机械化学响应，解决了传统探针热反应性不良的问题，适用于热塑性塑料的损伤检测。","scd":null,"kp":[]},{"i":39928,"as":"针对全固态锂电池中石榴石电解质（LLZTO）的烧结和晶界限制问题，研究提出了一种纳米工程过度饱和掺杂策略。通过在LLZTO中掺入1.0 wt%的钇（形成LLYZTO），在退火过程中晶界处形成了La-Y-O（LYO）纳米级中间相。这种材料改性方法显著提高了材料的压痕断裂韧性、临界电流密度和体离子电导率，同时保持了低电子电导率，改善了机械和电化学性能。","scd":null,"kp":[]},{"i":39929,"as":"为解决传统锌电极在循环过程中容易降解的问题，研究人员开发了一种基于流动锌浆料的电池。该电池将锌纳米颗粒分散在导电网络中，并利用特定配体稳定浆料。这种结构实现了可逆的Zn/Zn2+转化，从而使电池具备持久的稳定运行能力，为长时储能提供了一种有效方案。","scd":null,"kp":[]},{"i":39930,"as":"为解决宽禁带黄铜矿Cu2ZnSnS4（CZTS）太阳能电池的开路电压（VOC）亏损问题，研究提出了一种早期局部化学调控的缺陷调节策略。该策略通过稳定局部化学环境，抑制元素扩散引起的次生相和有害缺陷，维持理想的结晶路径。这种方法促进了良性缺陷的形成，有效降低了VOC损失，在宽禁带CZTS太阳能电池中实现了847 mV的开路电压。","scd":null,"kp":[]},{"i":39931,"as":"","scd":null,"kp":[]},{"i":39932,"as":"","scd":null,"kp":[]},{"i":39933,"as":"","scd":null,"kp":[]},{"i":39934,"as":"","scd":null,"kp":[]},{"i":39935,"as":"","scd":null,"kp":[]},{"i":39936,"as":"研究人员开发了具有刺激可裂解聚碳酸酯双层结构的刚性聚合物囊泡，能够在化学或光照触发下发生可编程的形变，如单向伸长、内陷和解体。其机制在于跨膜化学反应的能量局部耗散建立了反应梯度，导致疏水嵌段裂解。这成功在合成组装体中实现了将生化或光能输入转化为可编程的机械形变响应。","scd":null,"kp":[]},{"i":39937,"as":"","scd":null,"kp":[]},{"i":39938,"as":"本研究将一种兼具光吸收和燃料生成能力的单组分光活性分子催化剂[Cp*Ir(4,4'-Y2-bpy)Cl][Cl]锚定在多孔锡掺杂氧化铟（ITO）电极上，在无需额外光敏剂或牺牲还原剂的情况下实现了光电化学析氢。光谱电化学分析表明，该反应遵循单点析氢机制，涉及电荷向ITO注入，这与溶液中的双金属机制不同。","scd":null,"kp":[]},{"i":39939,"as":"为解决有机羰基电极材料（OCEMs）在电解质中易溶解的难题，研究提出了一种动态溶剂化结构调节策略。传统策略侧重于静态调节，而该研究关注电化学动态过程中的溶剂化行为，防止OCEMs在动态电化学过程中取代阴离子参与溶剂化而加剧溶解。该策略有效抑制了OCEMs的降解，从而实现了长寿命的锂-有机电池。","scd":null,"kp":[]},{"i":39940,"as":"通过对核苷三磷酸盐（NTP）加工酶的大量晶体学结构进行定量分析，研究鉴定出一种普遍存在的“Mg-pinch（镁夹）”基序。大多数NTP加工酶都需要二价镁离子参与催化。该研究证实了这种特定的镁离子配位结构在断裂键的极化中起到关键作用，揭示了NTP处理酶普遍存在的保守催化机制。","scd":null,"kp":[]},{"i":39941,"as":"研究证明，水微滴能在室温下且无需催化剂的条件下，诱导二硫化碳（CS2）发生快速自由基聚合反应，生成聚碳硫化物固体。气-水界面的超高电场产生高活性自由基和水合电子，促成了常规体相溶液中无法实现的转化。生成的聚合物是由共轭C=C和C-S网络组成的交联结构，并掺入了氢元素。","scd":null,"kp":[]},{"i":39942,"as":"","scd":null,"kp":[]},{"i":39943,"as":"","scd":null,"kp":[]},{"i":39944,"as":"研究人员利用拉曼微光谱技术，在微米尺度上精确测量了不同种类的单个浮游植物细胞周围的“浮游植物圈”内化学物质的浓度分布。研究明确测量了浮游植物代谢物（如岩藻黄素）在单细胞周围的浓度梯度，打破了以往认为该梯度仅由理想扩散决定的经典假设。","scd":null,"kp":[]},{"i":39945,"as":"通过对印度尼西亚棕榈油行业“零毁林承诺”（ZDCs）的评估，研究发现这些自愿性可持续采购承诺实现了极高的供应商合规性，但并未产生额外的环保效益。尽管企业实施了ZDCs，但由于供应链复杂且数据受限，这些承诺未能带来超出无承诺基准的实际毁林减少效果。","scd":null,"kp":[]},{"i":39946,"as":"脊索样胶质瘤（ChG）中存在蛋白激酶Cα（PKCα）激酶结构域的D463H点突变。研究显示，该突变将PKCα转化为假激酶，消除了其催化活性，并赋予其新的支架功能。突变的PKCα作为显性负效因子抑制内源性PKC活性。分子动力学模拟表明，组氨酸取代会导致结构不稳定，通过通路重布线驱动肿瘤发生。","scd":null,"kp":[]},{"i":39947,"as":"研究利用全基因组和位点特异性的表观遗传漂变指标以及基于时钟的生物学衰老估计，调查了狗的表观遗传衰老特征。研究发现，狗的DNA甲基化不稳定在整个生命周期中具有基因组结构特征，并且受体型大小影响。跨国比较显示，韩国狗的表观遗传年龄加速（EAA）普遍高于美国狗，且存在与性别相关的差异。","scd":null,"kp":[]},{"i":39948,"as":"通过包含数万次评估的联合实验和行为实验，研究发现，在面对社会挑战时，科学共识和社会共识的结合能够最有效地动员公众采取行动。即便在政府和行业表示反对的情况下，这种结合的双重共识信号依然保持强大的影响力，能够有效促使公众采取应对行动。","scd":null,"kp":[]},{"i":39949,"as":"研究发现，组蛋白脱乙酰酶HDA19是调节植物对非生物胁迫（干旱、热和盐度）敏感性的关键。通过赖氨酸乙酰化组分析，鉴定出组蛋白H3.3上的非经典K27/K36双乙酰化标记是HDA19的特异性底物。在盐胁迫下，野生型植物中该标记减少，而缺乏HDA19的突变体中该标记增加，导致植物表现出抗逆性。","scd":null,"kp":[]},{"i":39950,"as":"通过分析全球19个大都市地区约3000条公交线路和每年40亿人次乘客的数据，研究揭示了公交频率与乘客需求及乘车时间之间存在的稳健标度定律。该定律表明，在资源分配过程中，公交车内的拥挤程度是控制公交发车频率与需求之间标度规律的核心因素。","scd":null,"kp":[]},{"i":39951,"as":"","scd":null,"kp":[]},{"i":39952,"as":"研究通过黄瓜卷须的实验和自向异性生长模型，揭示了攀缘植物卷须缠绕动力学是由内部应力控制的。在低轴向拉力下，曲率呈指数级饱和；在超过临界阈值的高拉力下，卷须无法盘绕，但会产生对应于固有残余曲率的内在卷绕应力。差异生长是曲率产生的根本原因，在没有外部载荷时，曲率的生成完全受内部应力限制。","scd":null,"kp":[]},{"i":39953,"as":"","scd":null,"kp":[]},{"i":39954,"as":"","scd":null,"kp":[]},{"i":39955,"as":"","scd":null,"kp":[]},{"i":39956,"as":"","scd":null,"kp":[]},{"i":39957,"as":"","scd":null,"kp":[]},{"i":39958,"as":"本工作提出一种可涂抹、直接在皮肤上绘制的干电极。该电极能在具有分级纹理的皮肤形貌上形成超共形界面，并具备厚度梯度以最小化界面应力。测试表明，其接触阻抗低至10.8 kΩ cm。该技术解决了传统表皮电极在皮肤变形或出汗时接触受限，以及软电极与刚性数据采集系统之间连接不稳定的问题，可应用于无线传感和人机交互界面。","scd":null,"kp":[]},{"i":39959,"as":"尖孢镰刀菌等根部维管束病原体通过侵染木质部破坏植物水分和养分运输。研究发现，在病原体侵染木质部之前，其初期接触会触发植物体内脱落酸（ABA）水平的快速系统性升高，诱导拟南芥发生发育重编程。这一反应具体表现为根生长受抑、根尖分生组织结构紊乱以及木质部构型改变，从而启动植物防御机制。","scd":null,"kp":[]},{"i":39960,"as":"","scd":null,"kp":[]},{"i":39961,"as":"","scd":null,"kp":[]},{"i":39962,"as":"多次跨膜蛋白的生物合成对内质网（ER）质量控制构成挑战。酵母β-(1,3)-葡聚糖合酶的催化亚基Fks1具有复杂的多跨膜结构。研究探究了预测产物与氧化还原酶相似的必需基因Pbr1（YNL181W）的细胞功能。通过结合定量形态分析和全局遗传相互作用等技术，揭示了Pbr1在酵母Fks1葡聚糖合酶的内质网质量控制与折叠过程中发挥关键作用。","scd":null,"kp":[]},{"i":39963,"as":"既往知识和选择性注意力在目标导向行为中至关重要。本研究利用多回波功能磁共振成像技术，记录了受试者在执行涉及名人与匿名者图片的选择性工作记忆任务时的大脑活动。研究重点比较了大脑对新奇刺激与熟悉刺激的选择机制，揭示了目标相关性如何依赖于先验知识，并阐明了默认网络支持注意力、工作记忆与先验知识之间交互的目标导向调节机制。","scd":null,"kp":[]},{"i":39964,"as":"社会性昆虫表现出明显的随年龄变化的行为谱。在蜜蜂中，仅年轻工蜂会受蜂王下颌腺信息素（QMP）触发而表现出侍卫行为。研究揭示，老年蜜蜂依然具备潜在的QMP侍卫反应能力，但这种能力受到表达doublesex基因的细胞电活动的抑制性调节。这一发现揭示了神经系统调节年龄依赖性劳动分工的潜在机制。","scd":null,"kp":[]},{"i":39965,"as":"传统的超分辨荧光显微镜要求相距极近的相同荧光分子依次发光才能被分辨，同时追踪距离仅几纳米的多个荧光团被认为是不可能的。本研究基于MINFLUX超分辨技术，利用带有强度零点的激发光束探测亚衍射区域，提供了一种概念框架。该框架能够不间断地分辨和追踪持续发射且位置发生纳米级随机变化的相同荧光团或点散射体。","scd":null,"kp":[]},{"i":39966,"as":"新基因的产生机制包括基因复制、基因融合和水平基因转移（HGT）。研究提出，动物基因组中通过HGT获得的外源基因与内源序列融合，可形成含有非后生动物和后生动物双重起源区域的“HGT嵌合体”。研究人员开发了分子系统发育学分析流程，对319个高质量节肢动物基因组进行分析，发现了274个高置信度HGT嵌合体，对应104个独立起源事件。","scd":null,"kp":[]},{"i":39967,"as":"传统认为CD8+ T细胞的细胞毒性依赖于T细胞受体（TCR）与MHC I类分子复合物的结合。本研究以急性髓系白血病（AML）为模型，发现了一种矛盾的杀灭机制：该机制不依赖MHC，但依然依赖于TCR，并需要CD64的参与。通过对AML配体和CTL受体进行基因敲除验证，证实了CD64介导了这种TCR依赖且MHC非依赖性的细胞毒性作用。","scd":null,"kp":[]},{"i":39968,"as":"本研究利用功能脑成像技术，考察了7至17岁自闭症儿童青少年与正常发育对照组在处理母亲声音和非亲属声音时的神经反应。研究重点关注青春期社会注意力的重新定向，识别人类声音处理过程中的神经生物学特征。结果发现，自闭症儿童青少年在声音-奖赏回路中表现出与正常发育对照组不同的年龄相关发育分化模式，揭示了其社会交流障碍的神经基础。","scd":null,"kp":[]},{"i":39969,"as":"肠内分泌细胞（EECs）在肠道-大脑迷走神经轴的连接中发挥关键作用。利用斑马鱼遗传模型追踪肠道迷走神经网络发育发现，迷走神经感觉纤维在受精后第2天开始支配肠道，并向上皮层内新形成的EECs延伸分支。这表明肠道迷走神经感觉网络的发育与EECs的形成紧密耦合，EECs直接介导了肠道与大脑之间迷走神经轴的物理连接。","scd":null,"kp":[]},{"i":39970,"as":"基于在高草草原生态系统进行的为期6年的实验性干旱研究，发现干旱重塑了土壤细菌、真菌和原生生物的群落组成，并伴随微生物多样性和生物量的持续下降。时间-衰减关系分析显示，干旱条件下土壤微生物群落的演替轨迹与正常环境相比表现出日益明显的分歧，表明严重干旱对地下生物多样性及生态系统韧性具有深刻影响。","scd":null,"kp":[]},{"i":39971,"as":"反向洒水器问题长期存在多种竞争性理论。本研究开展了一系列实验，通过定制吸入式设备的几何形状，直接测量其运动、扭矩和流体流动，以验证现有的核心假说。实验结果反驳了基于流体总角动量及射流等效应的旧有观点，明确证实了几何构型在控制动量通量和洒水器反向运动中起决定性作用。","scd":null,"kp":[]},{"i":39972,"as":"在动态环境中，大脑通过调整学习率来平衡决策的稳定性与灵活性。本研究探讨了蓝斑向眶额叶皮层的去甲肾上腺素输入如何在不确定性下支持适应性学习。实验让大鼠在不同随机性水平的概率反转学习任务中做出决策，结果表明大鼠的行为表现可通过学习率的灵活调整来最佳解释，证实了眶额叶去甲肾上腺素在自适应调整学习率中的核心作用。","scd":null,"kp":[]},{"i":39973,"as":"本研究探讨了铁酸铋（BiFeO3）薄膜中的交变磁性特征。研究发现在超薄反铁磁材料铁酸镧（LaFeO3）层限制下的BiFeO3层中存在磁子传输现象，并表现出新兴的各向异性特征。这项研究为基于磁子的超快信息传输以及自旋信息的无破坏读出提供了新途径。","scd":null,"kp":[]},{"i":39974,"as":"研究将Lipkin-Nogami（LN）方法与连续介质中的形变相对论Hartree-Bogoliubov理论相结合，探究了LN修正对形变晕核镁-42（42Mg）的影响。计算结果表明，在引入LN修正后，42Mg的晕核结构依然存在。该研究推进了对奇特原子核结构的理论描述。","scd":null,"kp":[]},{"i":39975,"as":"在训练数据有限时，数据驱动模型容易受到随机初始化波动和数据采样偏差的影响。为解决从α衰变到团簇衰变的预测难题，研究采用迁移学习（TL）技术。通过先在相关大数据集上对深度神经网络进行预训练，再迁移应用，有效克服了优化波动和样本不足带来的挑战，提高了核衰变预测的准确性。","scd":null,"kp":[]},{"i":39976,"as":"三核子力（3NF）在理解有限核结构和无限核物质饱和属性中具有重要作用。为了更准确地描述核系统，研究推导了适用于新局域位置空间两核子势的手征三核子力。该研究将这一新型三核子力应用于从头算多体计算中，以验证和提升核物理基础计算的精度。","scd":null,"kp":[]},{"i":39977,"as":"宇称破坏电子散射是测量原子核内中子密度的有效方法，对理解原子核和中子星结构至关重要。本研究详细计算了宇称破坏不对称性（A_pv）的辐射修正。通过应用电弱辐射修正，提高了通过电子散射测量核内中子分布的模型无关性预测精度。","scd":null,"kp":[]},{"i":39978,"as":"研究引入了一个简化版的Connes-Narnhofer-Thirring量子动力学熵，用于量化通过连续监测可观测值所获得的关于量子系统初始状态的信息量。研究发现，通过监测系统可观测值，可以得到非零的熵增长率。该研究确立了量子动力学熵的增长率受到普朗克极限（Planckian Bound）的限制。","scd":null,"kp":[]},{"i":39979,"as":"热操作是用于推导量子系统热力学限制的核心量子通道，但其传统定义依赖于实施过程而非基本原理。本研究提出了一种基于信息平衡概念的热操作替代模型。该研究从信息论的平衡状态出发，重新审视并定义了量子热力学过程，为量子热力学提供了更为基础的理论框架。","scd":null,"kp":[]},{"i":39980,"as":"量子纠缠虽能提升量子计量的精度，但常因粒子损耗而失效。研究证明，量子扰乱机制通过将编码参数的信息分散到多体关联中，从而保护了计量精度。在哈亚尔随机扰乱机制下，计量学优势能够免受粒子损失的影响。该研究发表在《物理评论快报》上。","scd":null,"kp":[]},{"i":39981,"as":"研究探讨了电子-正电子湮灭中的电荷-电荷关联（QQC），以此作为探测量子色动力学中电荷动力学的一种手段。尽管在领先阶之外通常存在发散，但研究证明QQC在背对背极限下具有红外和共线安全性。研究人员将这一特性称为“领先”安全性。该成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":39982,"as":"理论研究表明，螺线管湍流可显著提高聚变反应率，但目前缺乏直接测量高能量密度等离子体中螺线管流并区分其与压缩湍流的标准诊断方法。为此，研究人员提出了一种利用激光偏振旋转来探测和直接测量螺线管等离子体湍流的新方法，以填补相关诊断技术的空白。","scd":null,"kp":[]},{"i":39983,"as":"受近期扭曲二碲化钼（MoTe2）实验的启发，研究人员提出并发展了一种在ν_tot=4/3状态下的分数量子拓扑绝缘体的无序相互作用边缘理论。该理论模型详细描述了该材料边缘态的物理特性，为理解和分析扭曲MoTe2中的分数拓扑绝缘体态提供了理论基础。","scd":null,"kp":[]},{"i":39984,"as":"磁子频率梳由一系列离散频率线组成，在磁子自旋电子学以及先进信息处理和传感技术中具有广阔的应用前景。尽管三磁子散射过程被广泛认为是其产生机制，本研究聚焦于受激磁子频率梳的相关特性与机制，进一步推动了该领域的技术前沿。相关结果发表在《物理评论快报》。","scd":null,"kp":[]},{"i":39985,"as":"研究人员为手性活性固体构建了新的理论框架，该固体因活性扭矩的作用能够发生局部内部旋转。该框架展示了奇弹性如何在与生物和合成系统密切相关的结构无序材料中产生。这一发现为理解和利用手性活性材料的力学特性提供了全新的理论依据。","scd":null,"kp":[]},{"i":39986,"as":"研究人员提出了一种名为“推挤随机游走”的极简模型，用于描述可变形介质中的物质输运过程。在该模型中，移动的示踪粒子能够排开并移动障碍物。这一机制在1维和2维系统中引发了全新的扩散动力学行为，有助于深刻理解复杂柔性和可形变介质中的物质传输。","scd":null,"kp":[]},{"i":39987,"as":"研究人员利用中子自旋回波光谱学和脉冲场梯度核磁共振技术，详细研究了非缠结和弱缠结聚异戊二烯（PI）熔体的动力学特性。通过与高度缠结PI熔体的光谱进行对比，实验验证了合作动力学广义朗之万方程理论关于蛇行及聚合物动力学的核心预测，仅在长时间尺度下观察到布朗扩散。","scd":null,"kp":[]},{"i":39988,"as":"为了克服脂质纳米颗粒（LNPs）递送顺铂时载药量低、不稳定和疗效差的局限，研究人员开发了多羧基树枝状脂肽（DG3）以通过铂配位作用提高载药量和肿瘤靶向性。最优制剂hDDLN具有优异的稳定性和高载药量，其与STING激动剂联用在体内外均表现出协同增效作用，能促进树突细胞成熟和细胞毒性T细胞浸润并减少调节性T细胞。","scd":null,"kp":[]},{"i":39989,"as":"本期简报主要涵盖三个要点：一是严谨的科学研究如何彻底改变医疗健康与社会政策；二是实验室培育精子技术取得的重大突破；三是美国国家科学基金会（NSF）计划削减核心科学项目预算，以资助白宫的一项新倡议。","scd":null,"kp":[]},{"i":39990,"as":"TRIUMF超冷先进中子源（TUCAN）合作组报告了基于超流氦-4的全新散裂驱动超冷中子源的首批实验结果。该中子源旨在为精确测量中子电偶极矩（nEDM）做准备。实验共产生了(9.3±0.8)×10^5个超冷中子，标志着该项高精度物理测量装置的初步成功运行。","scd":null,"kp":[]},{"i":39991,"as":"在三聚体钌酸盐Ba4Ru3O10中，研究人员通过在晶体结构、热力学和输运性质上的同步测量，发现了一种强烈的钉扎密度波不稳定性特征。这一发现揭示了一种隐藏的密度波不稳定性，证明该氧化物不仅是传统认知中的纯磁性绝缘体，还包含复杂的电子电荷有序态。","scd":null,"kp":[]},{"i":39992,"as":"研究在原子尺度上直接观察了多组分单分子结中的动态能量传输过程。实验揭示了在金表面连接烷基硫醇自组装单分子层光激发后，能量在极早时期的清晰传递时序：能量首先从金表面层迅速传输到分子内部。这一发现深入阐明了单个固体-分子结界面的能量传输动力学及其高热导特性。","scd":null,"kp":[]},{"i":39993,"as":"研究表明，在确定性演化下，以简单态初始化的混沌量子系统会迅速演化出极高的复杂性，且无法进行有效的经典模拟。在稳定子形式体系中，这种经典模拟的难度（即“魔力”资源）可以通过谱形因子来量化。研究成功将热场双重态中的魔幻动力学与谱形因子紧密联系起来。","scd":null,"kp":[]},{"i":39994,"as":"预测托卡马克破裂期间的三维热负荷对ITER至关重要。研究提出将垂直位移事件的磁流体力学模拟、真实三维第一壁模型上的磁力线追踪与瞬态壁热响应耦合的物理工作流。该流程在JET的铍装甲实验中验证有效，并进一步应用于配备钨装甲的2024年ITER新基准条件中，评估了破裂热负荷及其三维局部化特征。","scd":null,"kp":[]},{"i":39995,"as":"研究人员首次在TCV托卡马克装置中观察到离子回旋辐射（ICE）。测得的ICE频率紧跟磁轴处的氘离子回旋频率，其时间变化与等离子体平衡演化及磁轴偏移一致。核心区域的ICE主要出现在同时进行电子回旋共振加热和中性束注入的阶段，通常以二次谐波为主，且常伴有精细的光谱分支分裂和频率啁啾现象。","scd":null,"kp":[]},{"i":39996,"as":"为应对托卡马克装置全生命周期中的等离子体破裂挑战，研究提出了一套涵盖从初始数据稀缺到后期高性能运行各阶段的破裂预测策略。该策略结合了三种预测方法：在缺乏破裂数据的早期阶段，采用仅需正常样本训练的异常检测预测器实现从首次放电开始的保护；在后期则使用先进模型维持高性能运行时的预测能力。","scd":null,"kp":[]},{"i":39997,"as":"本研究探讨了在电阻性扰动托卡马克平衡中，用于量化共振驱动最直接的两个指标（代表屏蔽电流和穿透场）之间的相对行为。使用GPEC内部电阻磁流体力学模型发现，一个指标随伦德奎斯特数按比例变化并在低值下饱和，另一个则受全局扭曲结构影响。两者在同一电阻模型下产生高度相似的主导耦合模式。","scd":null,"kp":[]},{"i":39998,"as":"聚对苯二甲酸乙二醇酯（PET）虽具高强度和低成本优势，但其耐热性差限制了其在高温环境（如包装、电池和汽车零部件）中的应用。本文系统综述了提升PET耐热性的多种策略，主要包括通过调节分子流动性、控制结晶行为以及复合材料增强。具体方法涉及分子结构修饰、添加成核剂、优化加工工艺及聚合物共混。","scd":null,"kp":[]},{"i":39999,"as":"癌症免疫疗法在临床上常面临响应率低、难以穿透深层肿瘤组织及疗效不足等局限。基于纳米医学的物理化学治疗策略（包括光热疗法、光动力疗法、声动力疗法、纳米酶疗法和癌症疫苗）展现出巨大潜力。将这些纳米疗法与免疫疗法或调节性细胞死亡途径结合，可有效调节肿瘤微环境，增强抗癌免疫反应，克服单一免疫疗法的不足。","scd":null,"kp":[]}]);